local P = LoreForeverPacks.Begin("LoreForever_Lang_frFR")
P.entries["quest:92466"] = {n="Call of Earth",s="Dans Call of Earth, les initiés réunissent ce que leur instructeur leur demande. Leur effort montre s'ils sont prêts à poursuivre leur formation.",h="Dans Call of Earth, les initiés réunissent ce que leur instructeur leur demande.",kw={"call of earth","détermination","terre","éléments","chaman","esprits","épreuve"},ang={["class:Shaman"]="En tant que chaman, vous prouvez votre volonté avant d'approfondir votre communion avec les esprits de la pierre et du sol.",["faction:Horde"]="Au sein de la Horde, vous rencontrez des épreuves chamaniques comme Call of Earth, rite fondamental pour les adeptes des pratiques spirituelles."},sec={{t="Une épreuve de volonté",b="L'instructeur met la volonté de l'initié à l'épreuve en lui demandant des matériaux précis. Les réunir exige patience et endurance. En répondant aux exigences de la terre, l'élève montre qu'il a la force nécessaire pour communier avec son pouvoir immuable."},{t="La prochaine étape",b="Quand l'initié revient avec les offrandes demandées, l'instructeur constate sa ténacité. L'élève a tenu bon pendant l'épreuve et est prêt à passer à l'étape suivante de sa formation spirituelle."}},faq={{q="Qu'est-ce que Call of Earth ?",a="Call of Earth demande aux initiés spirituels de réunir les objets requis et de faire preuve de persévérance avant de poursuivre leur formation.",al={"qu'est-ce que call of earth","quête call of earth"}},{q="Que démontre la réussite de cette épreuve ?",a="Réussir l'épreuve montre votre ténacité et votre détermination à votre mentor. Cela prouve que vous avez assez de concentration pour assumer de plus grandes responsabilités spirituelles.",al={"qu'ai-je prouvé","ténacité et détermination"}},{q="Que se passe-t-il après Call of Earth ?",a="Après Call of Earth, votre instructeur vous juge prêt à passer à l'étape suivante vers la communion avec les éléments.",al={"quelle est la suite","quête suivante"}},{q="Pourquoi un initié doit-il communier avec la terre ?",a="L'initié fait preuve d'endurance avant de communier avec les esprits de la terre, dont la nature évoque stabilité et force.",al={"pourquoi la terre","signification des esprits de la terre"}},{q="Qui supervise Call of Earth ?",a="Un maître spirituel ou un mentor chaman guide les initiés pendant l'épreuve et juge leur discipline et leur aptitude à se lier aux esprits.",al={"qui donne cette quête","instructeur de call of earth"}},{q="Qui peut entreprendre cette épreuve ?",a="Call of Earth met à l'épreuve ceux qui apprennent à s'accorder aux éléments.",al={"tout le monde peut-il faire call of earth","call of earth est-elle réservée aux chamans"}}},fp="13,139,17.238.0,13.185.0,26.123.0,43.147.0,48.110.0,40.111.0,31.139.0,40.72.0"}
P.entries["quest:92467"] = {n="Call of Earth",s="À la Cime des Esprits, vous buvez un Earth Sapta et rencontrez un guide élémentaire. La force de la terre pourrait vous aider à retrouver les vents.",h="À la Cime des Esprits, vous buvez un Earth Sapta et rencontrez un guide élémentaire.",kw={"call of earth","earth sapta","éléments","quatre vents","cime des esprits","chaman","esprits"},ang={["class:Shaman"]="En tant que chaman, vous utilisez des saptas pour accorder votre esprit à un élément et communier avec ses esprits.",["race:Skyborne"]="En tant que Skyborne, vous pouvez dériver très haut, dans une mer infinie de nuages, et être séparé des quatre vents. La terre vous offre un fondement stable pour comprendre."},sec={{t="La nature du sapta",b="Les chamans boivent des saptas pour ouvrir leur regard sur le monde élémentaire. Chaque breuvage accorde l’esprit d’un mortel à un royaume et révèle des esprits habituellement invisibles. Seuls ceux qui ont assez de résolution peuvent supporter leur pouvoir. Des praticiens choisis gardent le secret de ces breuvages."},{t="La Cime des Esprits",b="Vous voyagez vers le nord-est, à travers un col, jusqu’à la Cime des Esprits, où les novices communient avec la terre. Les saptas ne se boivent que dans des lieux sacrés. Sur une terre consacrée, le breuvage vous permet de percer le voile et de voir ce que les esprits choisissent de révéler."},{t="La force de la terre",b="Après que vous avez bu l’Earth Sapta, un guide élémentaire vous accueille comme un enfant des quatre vents. Vous cherchez à comprendre pourquoi ils sont partis. L’esprit de la terre ne peut expliquer les raisons des esprits du vent, mais il vous enseigne la force et la résolution inébranlable.\n\nMême très haut, au milieu d’une mer infinie de nuages, vous devez d’abord vous ancrer à la terre. Alors seulement, vous pourrez parler de nouveau aux vents."}},faq={{q="Qu’est-ce qu’un Earth Sapta ?",a="Un Earth Sapta est un breuvage magique qui accorde votre esprit à l’élément de la terre. Avec assez de résolution, vous pouvez voir les esprits élémentaires invisibles aux yeux des gens ordinaires.",al={"qu’est-ce qu’un earth sapta","explication du sapta","à quoi sert un sapta"}},{q="Où faut-il boire l’Earth Sapta ?",a="Buvez l’Earth Sapta à la Cime des Esprits, au nord-est, en traversant un col. Les saptas se boivent uniquement sur une terre sacrée.",al={"où boire l’earth sapta","emplacement de la cime des esprits","où se trouve la cime des esprits"}},{q="Pourquoi les saptas doivent-ils être bus dans des lieux sacrés ?",a="Les saptas sont des breuvages puissants qui unissent les esprits mortels aux éléments. La tradition chamanique exige qu’ils soient bus dans des lieux sacrés pour communier avec les esprits.",al={"pourquoi boire un sapta dans un lieu sacré","peut-on boire un sapta n’importe où"}},{q="Pourquoi l’esprit appelle-t-il le quêteur un « enfant des quatre vents » ?",a="L’esprit de la terre vous accueille comme un enfant des quatre vents parce que vous cherchez à comprendre pourquoi les vents sont partis.",al={"qui est l’enfant des quatre vents","pourquoi enfant des quatre vents"}},{q="Pourquoi les esprits du vent sont-ils partis ?",a="Même l’esprit de la terre, à la Cime des Esprits, ignore pourquoi les esprits du vent se sont éloignés et où ils sont partis.",al={"pourquoi les vents sont-ils partis","où sont partis les vents"}},{q="Comment communier avec la terre aide-t-il à renouer avec les vents ?",a="La terre vous enseigne la force et la résolution. Même au milieu d’une mer infinie de nuages, vous restez lié à la terre. Apprendre sa stabilité est le premier pas pour parler de nouveau aux quatre vents.",al={"pourquoi commencer par la terre","comment la terre aide-t-elle à retrouver les vents"}}},fp="13,133,23.267.0,19.241.0,21.381.1,23.161.0,39.114.0,47.154.0,70.111.0,39.123.0,72.194.0"}
P.entries["quest:92468"] = {n="Call of Earth",s="Un esprit de la terre vous envoie auprès de Windshaper Boros, au Bosquet de Thendal, avec un éclat de Quartz brut. Là, cet éclat devient le cœur de votre premier Totem de terre et marque le début de votre étude des forces élémentaires.",h="Un esprit de la terre vous envoie auprès de Windshaper Boros, au Bosquet de Thendal, avec un éclat de Quartz...",kw={"call of earth","totem de terre","éléments","quartz brut","chaman","bosquet de thendal","windshaper boro","windshaper boros"},ang={["class:Shaman"]="En tant que chaman, recevoir votre premier totem marque le début de votre communion avec les forces élémentaires. Il vous offre un point de concentration matériel pour les sorts et les rites liés à la terre.",["race:Skyborne"]="En tant que Skyborne, vous commencez votre retour aux vents en maîtrisant la terre et en vous ancrant dans ses fondations solides."},sec={{t="Le don de la Terre",b="Un esprit de la terre vous remet un éclat de Quartz brut, preuve de votre communion. Il vous envoie auprès de Windshaper Boros, au Bosquet de Thendal, avec l’éclat. Même le plus petit fragment peut résister. Les esprits accordent leur faveur et leur respect à ceux qui font preuve de patience, de résilience et de sagesse."},{t="Les quatre éléments et le totem",b="Windshaper Boros place le Quartz brut au cœur de votre Totem de terre. Il vous rappelle que la voie élémentaire comporte quatre parts. Vous aspirez peut-être à entendre et à chanter les chants du vent. Pourtant, la maîtrise commence par la compréhension des quatre forces, à commencer par le sol inébranlable sous vos pieds."}},faq={{q="Qui est Windshaper Boros ?",a="Windshaper Boros, aussi appelé Boro, vit au Bosquet de Thendal. Ancien praticien et artisan, il guide les novices dans leur compréhension des esprits élémentaires et façonne leurs totems focalisateurs à partir de dons élémentaires.",al={"qui est boro","lieu où se trouve windshaper boros","où se trouve le bosquet de thendal"}},{q="À quoi sert le Quartz brut ?",a="Un esprit de la terre vous remet le Quartz brut comme preuve de votre rencontre et de votre communion. Windshaper Boros s’en sert comme fondation et cœur de votre Totem de terre.",al={"qu’est-ce que le quartz brut","éclat de terre","utilité du quartz"}},{q="Pourquoi faut-il un Totem de terre ?",a="Un Totem de terre vous offre un point de concentration personnel pour communier avec les esprits de la terre et canaliser les sorts liés à la terre. Il marque votre statut de novice et vous ancre aux fondements élémentaires du monde.",al={"que fait le totem de terre","rôle du totem","pourquoi faut-il un totem"}},{q="Pourquoi faut-il communier avec la terre avant de parler aux vents ?",a="Les vents ne sont qu’une part de l’équilibre élémentaire du monde. Avant de rechercher leurs chants, vous étudiez les quatre éléments, en commençant par la stabilité, la patience et la force de la terre.",al={"pourquoi commencer par la terre","rechercher les vents","les quatre éléments"}},{q="Où se trouve le Bosquet de Thendal ?",a="Le Bosquet de Thendal est le sanctuaire où Windshaper Boros s’occupe des affaires élémentaires et enseigne aux novices qui commencent leur cheminement chamanique.",al={"où se trouve le bosquet de thendal","zone du bosquet de thendal"}},{q="Quelle sagesse l’esprit de la terre transmet-il ?",a="L’esprit de la terre enseigne que même la plus petite pierre peut résister lorsque des choses plus grandes s’effondrent. Il demande patience, force intérieure et quête de sagesse en échange du respect mutuel et de l’harmonie.",al={"ce que demandent les éléments","philosophie de la terre"}}},fp="13,200,16.270.0,31.290.0,24.205.0,40.156.0,32.191.0,63.180.0,31.136.0,41.202.0"}
P.entries["quest:92469"] = {n="Return to Rorian",s="Yala Windwatcher vous envoie au Bosquet de Thendal avec des nouvelles urgentes du terrain. Après que vous avez aidé à repousser les agitateurs sur l’Île de Zéphras, elle vous apprend que les Al’Aketh ont troublé les esprits du vent locaux.",h="Yala Windwatcher vous envoie au Bosquet de Thendal avec des nouvelles urgentes du terrain.",kw={"al’aketh","secte","rorian","pierres dressées","bosquet de thendal","esprits du vent","yala windwatcher","île de zéphras"},ang={["class:Druid"]="En tant que Druide, vous partagez la responsabilité de défendre le Bosquet de Thendal et de préserver la paix dans les terres sacrées de l’Île de Zéphras.",["class:Shaman"]="En tant que Chaman, vous savez que l’agitation délibérée des esprits du vent par les Al’Aketh menace l’équilibre élémentaire."},sec={{t="Un rapport alarmant",b="Yala Windwatcher reste sur l’Île de Zéphras pour affronter les hostiles qui s’y trouvent encore. Elle vous envoie au Bosquet de Thendal annoncer que les Al’Aketh n’agissent plus seulement dans l’ombre."},{t="L’escalade des pierres dressées",b="Rorian the Dayseeker affirme que les dirigeants du Bosquet de Thendal observent les Al’Aketh à distance depuis quelque temps. À présent, les sectateurs ont agité les esprits du vent natifs près des pierres dressées. C’est une escalade inquiétante, et les dirigeants ne peuvent plus se contenter de les observer de loin."}},faq={{q="Qui vous envoie parler à Rorian ?",a="Après que vous avez aidé à repousser les agitateurs hostiles qui menacent la région, Yala Windwatcher vous envoie faire votre rapport à Rorian.",al={"donneur de quête","qui lance retour auprès de rorian","yala windwatcher"}},{q="Où se trouve Rorian the Dayseeker ?",a="Rorian the Dayseeker se trouve au Bosquet de Thendal, où les dirigeants du bosquet supervisent les affaires de l’Île de Zéphras.",al={"où se trouve rorian","emplacement de rorian","rorian au bosquet de thendal"}},{q="Qui sont les Al’Aketh ?",a="Les Al’Aketh sont une secte de l’Île de Zéphras. Les dirigeants du bosquet les observaient discrètement de loin, mais leur récente agitation des esprits du vent près des pierres dressées en fait désormais une menace active.",al={"quelle est cette secte","qui sont les al’aketh","secte al’aketh"}},{q="Pourquoi la nouvelle n’a-t-elle pas surpris Rorian ?",a="Rorian et les dirigeants du bosquet connaissaient déjà les déplacements de la secte sur l’île. Jusqu’à présent, ils l’observaient discrètement au lieu de l’affronter directement.",al={"rorian était-il au courant","réaction de rorian","pourquoi cela ne l’a pas surpris"}},{q="Que se passe-t-il après votre rapport à Rorian ?",a="Après avoir entendu votre rapport et vous avoir remercié d’avoir aidé le Bosquet de Thendal, Rorian vous envoie auprès d’Aetheen of the Gales, membre du Conseil des Anciens, qui vous observe depuis quelque temps.",al={"quête suivante","que se passe-t-il après retour auprès de rorian","après retour auprès de rorian"}},{q="Pourquoi Yala est-elle restée sur place ?",a="Yala Windwatcher reste sur le lieu du conflit pour s’occuper des derniers hostiles, tandis qu’elle vous envoie transmettre les nouvelles urgentes.",al={"pourquoi yala reste-t-elle","où est partie yala","rôle de yala windwatcher"}}},fx={aa0b8ee2={q="Pourquoi Yala Windwatcher vous envoie-t-elle auprès de Rorian ?",a="Yala a besoin que les dirigeants du Bosquet de Thendal soient immédiatement alertés de la présence confirmée du culte d'Al’Aketh. Tandis qu'elle reste en arrière pour finir de s'occuper des retardataires sur le terrain, Rorian the Dayseeker doit être prévenu de l'escalade du culte et de son agitation des esprits locaux afin que le bosquet puisse coordonner une réponse.",al={"pourquoi faire rapport à rorian","motif de yala windwatcher","pourquoi yala veut-elle que rorian soit informé"}}},fp="16,202,13.176.0,33.264.1,35.115.0,38.100.0,21.192.0,41.160.0,44.171.1,25.117.0"}
P.entries["quest:92470"] = {n="Foul Matriarch",s="Dans les grottes au sud de Thendal, Aetheen of the Gales met les nouvelles recrues à l’épreuve face aux urseras. Elles doivent éclaircir les meutes et tuer leur mère de tanière, Urs'anah, pour prouver qu’elles peuvent affronter de plus grands périls sur l’Île de Zéphras.",h="Dans les grottes au sud de Thendal, Aetheen of the Gales met les nouvelles recrues à l’épreuve face aux...",kw={"aetheen of the gales","foul matriarch","grotte de thendal","bosquet de thendal","thendal","urs'anah","ursera","île de zéphras"},ang={["class:Hunter"]="En tant que Chasseur, traquer une féroce matriarche dans sa caverne met à l’épreuve votre connaissance des bêtes et votre détermination.",["race:Skyborne"]="En tant que recrue des Skyborne, maîtriser les prédateurs terrestres comme Urs'anah montre que vous pouvez vous défendre sur la terre ferme. Vous êtes prêt à vous aventurer au-delà de vos débuts isolés."},sec={{t="Une épreuve de détermination",b="Aux abords de Thendal, Aetheen of the Gales observe les nouveaux venus prendre leurs marques. Lorsqu’une recrue montre des aptitudes prometteuses, Aetheen l’envoie dans les grottes du sud pour un dangereux rite de passage. Là, elle éclaircit les meutes locales d’urseras et affronte la mère de couvée qui menace les abords du village."},{t="La menace d’Urs'anah",b="Les rôdeurs locaux savent que les urseras sont féroces, mais Urs'anah représente la plus grande menace pour le refuge. Au fond de la Grotte de Thendal, la redoutable matriarche dirige ses charognards et garde son repaire. Sa tête tranchée prouve qu’un aventurier peut affronter des bêtes féroces et qu’il est prêt à s’aventurer au-delà du bosquet de départ."}},faq={{q="Qui confie la tâche de tuer Urs'anah ?",a="Aetheen of the Gales confie l’épreuve depuis Thendal. Aetheen observe les nouvelles recrues prometteuses repérées par des figures locales comme Rorian, puis met leur courage à l’épreuve lors d’une chasse dangereuse.",al={"qui confie foul matriarch","donneur de quête foul matriarch","qui est aetheen of the gales"}},{q="Où trouver Urs'anah et les charognards urseras ?",a="Urs'anah et les charognards urseras vivent dans les grottes au sud et au sud-ouest de Thendal, dans les collines du Bosquet de Thendal. Le repaire de la matriarche se trouve au fond de la caverne.",al={"emplacement d’urs'anah","où se trouve ursanah","grotte des urseras zéphras","emplacement de la grotte de thendal"}},{q="Qu’est-ce qu’un ursera ?",a="Les urseras sont des prédateurs agressifs semblables à des ours, originaires des crags les plus sauvages de l’Île de Zéphras. Leurs meutes de charognards peuvent établir des tanières dangereusement près de lieux habités comme Thendal.",al={"qu’est-ce qu’un ursera","lore des urseras","les urseras sont-ils des ours"}},{q="Que signifie l’achèvement de cette chasse pour un aventurier ?",a="Tuer Urs'anah marque un rite de passage. En venant à bout des intrus cultistes et de la faune la plus dangereuse du bosquet, le chasseur prouve qu’il est prêt à quitter le sanctuaire de Thendal et à assumer de plus grandes responsabilités sur l’Île de Zéphras.",al={"pourquoi tuer ursanah","importance de foul matriarch"}}},fx={["03aee340"]={q="Pourquoi Aetheen of the Gales vous envoie-t-elle contre la matriarche ?",a="Aetheen of the Gales a surveillé vos progrès et exige une preuve de votre détermination. Elle doit savoir si vous possédez la force et la ténacité nécessaires pour survivre aux périls bien plus grands qui attendent l'île de Zéphras. Abattre la dangereuse matriarche prouve que vous êtes capable d'aller au-delà de la sécurité de Thendal et de servir l'île lors d'épreuves plus profondes et plus périlleuses.",al={"pourquoi aetheen veut-elle la mort d'urs'anah","motif d'aetheen","pourquoi tuer urs'anah"}},["30b9798a"]={q="À quoi sert la Tête d'Urs'anah ?",a="La tête sert de preuve physique indéniable de la mort de la matriarche. Urs'anah est une mère de tanière notoire connue des forestiers locaux, et Aetheen n'acceptera rien de moins que sa tête tranchée pour vérifier que la dangereuse bête a bel et bien été mise hors d'état de nuire.",al={"utilité de la tête d'urs'anah","pourquoi garder la tête d'urs'anah","but de la tête d'urs'anah"}},a1adff34={q="Qui est Urs'anah ?",a="Urs'anah est la féroce matriarche et mère de tanière des ursera locaux, habitant les grottes au sud de Thendal. Connue et crainte par les forestiers de l'île, elle commande la meute de charognards, ce qui fait d'elle la principale menace parmi les bêtes prédatrices du bosquet.",al={"qui est urs'anah","qu'est-ce qu'urs'anah","histoire d'urs'anah"}}},fp="14,220,17.293.0,22.297.0,38.181.0,54.169.0,18.178.0,57.242.0"}
P.entries["quest:92471"] = {n="Aetheen of the Gales",s="Sur l’Île de Zéphras, les jeunes aventuriers qui réussissent leurs premières épreuves vont rencontrer Aetheen of the Gales au Bosquet de Thendal. Là, la génération montante se soumet à son jugement.",h="Sur l’Île de Zéphras, les jeunes aventuriers qui réussissent leurs premières épreuves vont rencontrer Aetheen...",kw={"aetheen of the gales","conseil des anciens","rorian the dayseeker","shen'dorei","bosquet de thendal","île de zéphras"},sec={{t="Évaluer le potentiel",b="Sur l’Île de Zéphras, les jeunes novices accomplissent leurs premières tâches, qui mettent à l’épreuve leur ténacité et leur force d’âme. Les mentors de l’île cherchent ceux qui sont prêts à aider à défendre leur foyer. Rorian the Dayseeker remarque les jeunes capables d’assumer de plus grandes responsabilités."},{t="La liseuse de vents du Bosquet de Thendal",b="Au Bosquet de Thendal, Aetheen of the Gales lit les courants de l’air. Elle siège au Conseil des Anciens, qui gouverne l’Île de Zéphras, et évalue les jeunes shen'dorei à l’âge adulte. Vous présenter à elle vous mène au-delà des tâches mineures le long du périmètre de l’île, vers les menaces qui pèsent sur la communauté."}},faq={{q="Qui est Aetheen of the Gales ?",a="Aetheen of the Gales dirige l’Île de Zéphras et siège à son Conseil des Anciens. Au Bosquet de Thendal, elle lit les vents et évalue les jeunes shen'dorei qui arrivent à l’âge adulte, afin de déterminer s’ils sont prêts à défendre leur foyer.",al={"qui est aetheen","rôle d’aetheen of the gales","aetheen zéphras"}},{q="Pourquoi Rorian envoie-t-il les joueurs rencontrer Aetheen ?",a="Après leurs premières tâches, Rorian the Dayseeker envoie les novices capables et résilients auprès d’Aetheen. Elle évalue leurs compétences et les oriente vers les défis plus importants auxquels l’île fait face.",al={"pourquoi rencontrer aetheen","rorian envoie auprès d’aetheen","but de cette quête"}},{q="Où trouver Aetheen of the Gales ?",a="Aetheen of the Gales se trouve au Bosquet de Thendal, sur l’Île de Zéphras. Elle y lit les vents et supervise les épreuves de passage à l’âge adulte des jeunes de l’île.",al={"lieu où se trouve aetheen","où se trouve aetheen","aetheen bosquet de thendal"}},{q="Qu’est-ce que le Conseil des Anciens ?",a="Le Conseil des Anciens gouverne les shen'dorei de l’Île de Zéphras. Aetheen et les autres membres du conseil guident leur communauté pour assurer sa survie, son leadership et sa préparation.",al={"conseil des anciens zéphras","qui gouverne zéphras"}},{q="Que se passe-t-il après s’être présenté à Aetheen ?",a="Quand Aetheen juge un jeune aventurier prêt à servir l’Île de Zéphras, elle lui confie des missions sérieuses contre les dangers de la nature sauvage locale, notamment la faune agressive et les matriarches malfaisantes.",al={"quête suivante après aetheen","que veut aetheen"}},{q="Que signifie « arriver à l’âge adulte » pour les shen'dorei de l’Île de Zéphras ?",a="Pour les jeunes shen'dorei de l’Île de Zéphras, arriver à l’âge adulte signifie faire ses preuves au cours d’épreuves physiques et magiques. Avant d’assumer cette responsabilité, ils montrent à une ancienne de l’île comme Aetheen qu’ils sont capables de servir.",al={"shen'dorei et passage à l’âge adulte","passage à l’âge adulte zéphras"}}},fx={d6e78b3c={q="Pourquoi Rorian a-t-il besoin que vous alliez spécifiquement parler à Aetheen ?",a="Vos premières tâches à travers l'île ont été discrètement traitées comme des épreuves pour jauger votre courage. Zéphras fait face à de sérieux défis, et ses dirigeants ont besoin de jeunes shen'dorei compétents et fougueux arrivant à l'âge adulte pour se manifester et aider leur peuple. Ayant prouvé votre compétence, Rorian vous a désigné comme quelqu'un prêt pour une évaluation directe par l'Ancienne Aetheen.",al={"pourquoi moi aetheen of the gales","pourquoi rorian me choisit-il","pourquoi m'envoyer vers aetheen"}}},fp="20,159,22.226.0,32.303.0,28.215.0,45.180.0,40.145.0,30.160.0,40.184.0,62.200.0"}
P.entries["quest:92472"] = {n="The Next Step",s="L’aînée Aetheen of the Gales prend la route du sud après la victoire contre les bêtes près de Thendal. Les zélotes d’Al’Aketh menacent Shen’dar.",h="L’aînée Aetheen of the Gales prend la route du sud après la victoire contre les bêtes près de Thendal.",kw={"aetheen of the gales","culte d’al’aketh","al'akir","agent de police aonda","shen’dar","mur-céleste","thendal","île de zéphras"},ang={["class:Shaman"]="En tant que chaman, vous connaissez le danger que représentent les mortels qui vénèrent aveuglément des seigneurs élémentaires comme Al'Akir. Sa nature instable exige souvent la servitude plutôt que l’équilibre.",["race:Skyborne"]="Pour les Skyborne, combattre les Al’Aketh revient à lutter contre le fanatisme élémentaire qui menace les colonies de leur terre natale, sur l’Île de Zéphras."},sec={{t="Quitter Thendal",b="L’aînée Aetheen of the Gales voit le danger grandir sur l’Île de Zéphras. Les prédateurs et les matriarches des étendues sauvages du nord ont été éliminés, mais ce n’était que le moindre des périls. Les colonies isolées ont encore besoin de défenseurs."},{t="L’ombre grandissante du culte",b="Le culte d’Al’Aketh est le principal danger dans le sud de l’Île de Zéphras. Ses zélotes impitoyables vénèrent Al'Akir le seigneur du Vent, maître de Mur-Céleste dans le royaume élémentaire. Leur pouvoir grandissant menace Shen’dar. Aetheen envoie les voyageurs vers le sud, le long de la route, au-delà des embusqués dans les hautes-terres, pour aider la garde locale de l’agent de police Aonda."}},faq={{q="Où mène ce voyage ?",a="La route part vers le sud depuis Thendal, traverse les Hautes-terres de Shen’dar et rejoint Shen’dar. L’agent de police Aonda supervise la défense du village.",al={"où aller","prochain centre","destination"}},{q="Qui est l’agent de police Aonda ?",a="L’agent de police Aonda détient l’autorité civile et militaire à Shen’dar. Il veille à l’ordre et protège le village contre la menace grandissante des cultistes.",al={"agent de police aonda","qui est aonda"}},{q="Qu’est-ce que le culte d’Al’Aketh ?",a="Les Al’Aketh sont des zélotes impitoyables de l’Île de Zéphras qui vénèrent Al'Akir le seigneur du Vent, maître de Mur-Céleste. Leur pouvoir grandissant menace les colonies de l’île.",al={"qui sont les al’aketh","histoire du culte d’al’aketh","cultistes"}},{q="Qui est Al'Akir ?",a="Al'Akir le seigneur du Vent règne sur les cieux et commande Mur-Céleste. Les élémentaires de l’air le révèrent, et le culte d’Al’Aketh le vénère avec ferveur.",al={"qui est al'akir","seigneur du vent","maître de mur-céleste"}},{q="Pourquoi l’aînée Aetheen envoie-t-elle les voyageurs loin de Thendal ?",a="Les menaces immédiates autour de Thendal étant écartées, Aetheen envoie des défenseurs aguerris à Shen’dar. L’avancée du culte d’Al’Aketh met bien davantage l’île en péril que les troubles autour de Thendal.",al={"pourquoi quitter thendal","objectif d’aetheen"}},{q="Quels dangers se trouvent sur la route de Shen’dar ?",a="Le sentier vers le sud traverse les Hautes-terres de Shen’dar. Des embusqués d’Al’Aketh et des brutes renégates du culte s’en prennent aux voyageurs entre les colonies de l’île.",al={"dangers de la route","voyage vers le sud","danger dans les hautes-terres"}}},fp="13,134,23.226.0,30.315.0,29.140.0,23.152.0,26.157.0,15.133.0,56.194.0,52.145.0"}
P.entries["quest:92473"] = {n="Aggressive Encroachment",s="Au village, des ursera affamés menacent désormais la colonie. Valreaa Valewind appelle à une élimination après qu’une bête a failli attaquer un enfant près de l’arbre aîné.",h="Au village, des ursera affamés menacent désormais la colonie.",kw={"griffes","arbre aîné","intrusion","ursera efflanqués","bosquet de thendal","ursera","valreaa valewind"},ang={["class:Druid"]="En tant que druide, vous pouvez voir l’équilibre du bosquet vaciller. L’agressivité soudaine et la malnutrition des ursera indiquent un trouble invisible dans l’écosystème local.",["class:Hunter"]="En tant que chasseur, vous savez que la famine peut pousser les prédateurs affamés à abandonner leur méfiance naturelle envers les colonies."},sec={{t="Prédateurs désespérés",b="Des ursera venus de tanières au sud-ouest du village sont devenus dangereux pour ses habitants. Un jeune adulte affamé a atteint le pied de l’arbre aîné central et a failli lacérer un enfant qui jouait. Les forestiers de la colonie ont tué la bête avant que quiconque ne soit blessé."},{t="Élimination dans le bosquet",b="Les forestiers pensent que la faim pousse les ursera vers les terres habitées. Ils ont ordonné d’éliminer les bêtes les plus efflanquées qui rôdent hors de leurs tanières dans le Bosquet de Thendal. Les Rangers of the Grove espèrent ainsi empêcher de nouvelles incursions tout en cherchant la cause de la détresse de la faune."}},faq={{q="Qui propose Aggressive Encroachment ?",a="Valreaa Valewind, une dirigeante parmi les forestiers, propose cette tâche. Elle veille sur le bosquet et protège la colonie voisine des bêtes prédatrices.",al={"qui propose aggressive encroachment","donneur de quête","quête de valreaa valewind"}},{q="Pourquoi les ursera rôdent-ils si près du village ?",a="Les ursera sont affamés et désespérés. La faim les pousse bien au-delà de leurs terrains de chasse habituels, jusque dans la colonie.",al={"pourquoi les ursera attaquent","agressivité des ursera","pourquoi les ursera sont-ils furieux"}},{q="Où trouver les ursera efflanqués ?",a="Les ursera efflanqués rôdent dans le Bosquet de Thendal, au sud-ouest du village, à l’extérieur des entrées des tanières et non au fond de la grotte.",al={"où trouver les ursera efflanqués","emplacement des ursera","ours du bosquet de thendal"}},{q="Quelle tragédie évitée de justesse a provoqué cette élimination ?",a="Un jeune ursera a atteint l’arbre aîné au centre du village et a tenté d’attaquer un jeune garçon qui jouait. Les forestiers ont tué la bête juste à temps pour le sauver.",al={"ursera attaque garçon","que s’est-il passé au village","garçon près de l’arbre aîné"}},{q="Pourquoi les ursera se comportent-ils de façon si erratique ?",a="Les ursera sont devenus inhabituellement agressifs, mais les forestiers ignorent ce qui a causé leur manque de nourriture ou ce changement de comportement.",al={"ce qui a changé chez les ursera","pourquoi les ursera meurent de faim"}},{q="Quelle preuve Valreaa Valewind demande-t-elle ?",a="Valreaa Valewind demande six Scrawny Ursera Claws prélevées sur les bêtes mal nourries qui rôdent dans le bosquet, afin de prouver que ces dangereux prédateurs ont été éliminés.",al={"que dois-je récupérer","objectif d’aggressive encroachment"}}},fp="23,153,19.242.0,17.281.0,35.147.0,53.121.0,38.116.0,37.164.0,43.126.0,41.156.0"}
P.entries["quest:92474"] = {n="Falling With Style",s="À Thendal, Myriaal Mistwake envoie de jeunes Skyborne depuis une tour de guet pour tester leur aptitude à tomber. Ils planent jusqu’à Rorian the Dayseeker, en contrebas.",h="À Thendal, Myriaal Mistwake envoie de jeunes Skyborne depuis une tour de guet pour tester leur aptitude à...",kw={"falling with style","myriaal mistwake","rorian the dayseeker","chute lente","thendal","marcher sur l’air","tour de guet","île de zéphras"},ang={["race:Skyborne"]="En tant que Skyborne, vous apprenez à ralentir votre chute et entendez le débat sur l’usage prudent de votre magie innée, qui vous permet de marcher sur le vent."},sec={{t="Un saut depuis la tour",b="Bien au-dessus de Thendal, sur l’Île de Zéphras, Myriaal Mistwake invite de jeunes Skyborne à éprouver leur héritage par un saut audacieux. Elle encourage les nouveaux venus à s’élancer du rebord de la tour de guet et à se fier à leur don pour ralentir leur chute. L’exercice est ludique, mais il les prépare à marcher sur l’air quand le danger surviendra au-delà du bosquet."},{t="Des tempéraments différents",b="Myriaal se réjouit des descentes soudaines qui surprennent les spectateurs, tandis que Rorian the Dayseeker préfère la prudence. Alors que les novices planent pour atterrir devant lui, il les avertit qu’un usage inconsidéré de leur magie pourrait laisser les voyageurs sans défense face au danger. Il admet toutefois qu’un entraînement maîtrisé au village a sa place."}},faq={{q="À quoi sert cette quête ?",a="Ce saut permet aux novices Skyborne de s’entraîner à maîtriser une descente lente depuis une hauteur grâce à leur magie innée.",al={"à quoi sert cette quête","but de falling with style","pourquoi faire cette quête"}},{q="Qui donne cette quête et où ?",a="Myriaal Mistwake la donne depuis la tour de guet en bois, au-dessus de Thendal, sur l’Île de Zéphras.",al={"donneur de quête","où commencer falling with style","qui donne falling with style"}},{q="Devant qui atterrissez-vous ?",a="Vous atterrissez près de Rorian the Dayseeker, que Myriaal espère surprendre avec ce saut.",al={"près de qui atterrir","qui est rorian","rendre falling with style"}},{q="Pourquoi le saut contrarie-t-il Rorian ?",a="Rorian estime que les Skyborne doivent faire preuve de discipline dans l’usage de leur magie innée et ne pas la gaspiller en plaisanteries qui effraient les gens.",al={"pourquoi rorian est-il fâché","réaction de rorian","pourquoi rorian vous réprimande"}},{q="Quelle capacité exerce-t-on ?",a="Vous vous exercez à marcher sur l’air, le don des Skyborne qui ralentit la chute et évite les blessures à l’atterrissage.",al={"quelle capacité est utilisée","quête marcher sur l’air","capacité raciale des skyborne"}},{q="Où cela se passe-t-il ?",a="L’exercice a lieu à Thendal, sur l’Île de Zéphras, le berceau ancestral des Skyborne.",al={"lieu de la quête","où se trouve thendal","quelle est cette zone"}}},fx={fb92945d={q="Pourquoi Myriaal Mistwake vous fait-elle sauter de la tour de guet ?",a="Myriaal Mistwake traite le saut comme un défi ludique pour vous aider à pratiquer votre capacité innée à marcher sur l'air, mais elle a aussi un motif malicieux : elle veut surprendre Rorian the Dayseeker et bien rire en le voyant s'agiter.",al={"pourquoi myriaal veut-elle cela","motif de myriaal mistwake","pourquoi sauter de la tour"}}},fp="18,151,21.318.0,27.303.0,34.105.0,30.91.0,28.80.0,32.125.0,32.95.0,27.103.0"}
P.entries["quest:92479"] = {n="A Scribbled Letter",s="À l’Abbaye de Comté-du-Nord, après des affrontements avec les kobolds des environs, les aventuriers reçoivent une convocation de Tordrin Stemblade. Elle invite les recrues prometteuses à venir suivre son entraînement tandis que les dangers grandissent autour de Hurlevent.",h="À l’Abbaye de Comté-du-Nord, après des affrontements avec les kobolds des environs, les aventuriers reçoivent...",kw={"a scribbled letter","entraîneur de chasseurs","camps de kobolds","abbaye de comté-du-nord","vallée de comté-du-nord","lettre écrite à la hâte","tordrin stemblade"},ang={["class:Hunter"]="Tordrin Stemblade forme des chasseurs à l’Abbaye de Comté-du-Nord. Il remarque que les temps ont changé : de nouvelles races prennent l’arc pour défendre Hurlevent contre les bêtes et la vermine.",["faction:Alliance"]="Former des défenseurs compétents à l’Abbaye de Comté-du-Nord aide à protéger la Forêt d’Elwynn contre l’avancée des kobolds et les autres menaces grandissantes qui pèsent sur Hurlevent."},sec={{t="Une convocation à Comté-du-Nord",b="Après des affrontements contre les camps de kobolds de la vallée, les aventuriers de l’Abbaye de Comté-du-Nord reçoivent une lettre écrite à la hâte, scellée par Tordrin Stemblade. Elle leur demande de s’en occuper sans tarder avant de passer à d’autres affaires. Cette convocation offre aux champions en herbe un mentorat officiel dans l’enceinte protectrice de l’abbaye."},{t="Des conseils en temps périlleux",b="Tordrin Stemblade affirme que les temps ont changé. Des peuples inconnus prennent désormais les armes pour défendre le royaume. Alors que les terres sauvages autour de Comté-du-Nord deviennent chaque jour plus dangereuses, il propose ses conseils aux voyageurs, de jour comme de nuit. Il les guide tandis qu’ils perfectionnent leurs talents et viennent en aide au peuple éprouvé de Hurlevent."}},faq={{q="Qu’est-ce qu’une lettre écrite à la hâte ?",a="Après des affrontements contre les camps de kobolds, les aventuriers de l’Abbaye de Comté-du-Nord reçoivent une lettre scellée par Tordrin Stemblade. Elle les invite à suivre son mentorat et son entraînement dans la vallée.",al={"qu’est-ce que la lettre écrite à la hâte","quête de la lettre écrite à la hâte","lettre de tordrin"}},{q="Qui a envoyé la lettre ?",a="La lettre a été envoyée par Tordrin Stemblade. C’est un entraîneur local de l’Abbaye de Comté-du-Nord, où il forme les aventuriers novices qui apprennent leur métier.",al={"qui a envoyé la lettre","qui a écrit la lettre","auteur de la lettre écrite à la hâte"}},{q="Où trouver Tordrin Stemblade ?",a="Tordrin Stemblade se trouve à l’Abbaye de Comté-du-Nord, dans la Vallée de Comté-du-Nord. Il y reste jour et nuit, prêt à instruire et à conseiller les voyageurs.",al={"où se trouve tordrin stemblade","emplacement de tordrin","trouver tordrin stemblade"}},{q="Pourquoi Tordrin Stemblade a-t-il envoyé la lettre ?",a="Lorsqu’un aventurier fait ses preuves contre les kobolds des environs, Tordrin lui fait parvenir un message afin qu’il reçoive une formation adéquate. Il veut le préparer aux dangers grandissants qui menacent les habitants de Comté-du-Nord et le royaume de Hurlevent dans son ensemble.",al={"pourquoi tordrin a-t-il envoyé une lettre","but de tordrin stemblade","pourquoi cette convocation"}},{q="Quels dangers menacent actuellement Comté-du-Nord ?",a="La Vallée de Comté-du-Nord subit les incursions de camps de kobolds agressifs et de dangereuses bêtes mangeuses d’hommes qui rôdent dans les bois alentour. En réponse, les mentors locaux rassemblent et entraînent les combattants capables.",al={"quels dangers menacent comté-du-nord","dangers à l’abbaye de comté-du-nord","kobolds à comté-du-nord"}},{q="Que propose Tordrin Stemblade après la réception de la lettre ?",a="Tordrin propose un entraînement et des conseils continus. Il encourage les aventuriers à se familiariser avec la région et à aider les habitants face aux nombreux problèmes du royaume.",al={"que propose tordrin","entraînement de tordrin","que se passe-t-il après avoir rencontré tordrin"}}},fp="18,193,23.303.0,26.296.0,27.177.0,20.140.0,37.153.0,42.232.0,48.187.0,61.156.0"}
P.entries["quest:92481"] = {n="A Student of the Arcane",s="Sur l’Île de Zéphras, Rorian the Dayseeker appelle les lanceurs de sorts novices à suivre A Student of the Arcane. Après avoir fait leurs preuves, les nouveaux venus examinent un Cristal de rappel luminescent et se présentent à Dorii Brightwhisper, leur mentor local.",h="Sur l’Île de Zéphras, Rorian the Dayseeker appelle les lanceurs de sorts novices à suivre A Student of the...",kw={"dorii brightwhisper","cristal de rappel luminescent","quête de mage","rorian the dayseeker","a student of the arcane","bosquet de thendal","vuldren","île de zéphras"},ang={["class:Mage"]="En tant que mage, votre apprentissage auprès de Dorii Brightwhisper commence ici. Votre voie dans la magie contribue à restaurer les secrets des arcanes perdus depuis longtemps dans les nuages.",["race:Skyborne"]="En tant que Skyborne, vous savez que des millénaires d’isolement dans les nuages ont fait décliner les traditions arcaniques. Les jeunes apprentis jouent un rôle essentiel dans le renouveau de l’héritage de votre peuple."},sec={{t="Un message dans un cristal",b="Après avoir aidé à régler le problème des vuldrens près du Bosquet de Thendal, les mages en herbe reçoivent un curieux artefact : un Cristal de rappel luminescent. Dorii Brightwhisper, l’instructeur des arcanes de l’île, l’a laissé derrière lui. Le message qu’il contient met à l’épreuve les aptitudes des initiés et les accueille dans une étude plus approfondie de la magie."},{t="Redécouvrir les arcanes",b="Dorii Brightwhisper explique que la maîtrise des arcanes s’est lentement perdue parmi son peuple. Pendant des millénaires, celui-ci a vécu reclus dans les hauteurs, parmi les nuages. Dorii voit donc en chaque nouveau pratiquant un pionnier capable de retrouver les connaissances perdues et de restaurer l’ancien héritage magique de son peuple, jadis si puissant."}},faq={{q="Qu’est-ce que le Cristal de rappel luminescent ?",a="Le Cristal de rappel luminescent est un petit foyer magique que Dorii Brightwhisper a confié à Rorian the Dayseeker. Il contient un message inscrit qui présente les bases de la communication arcanique aux jeunes apprentis.",al={"cristal de rappel","message du cristal","à quoi sert le cristal"}},{q="Qui est Dorii Brightwhisper ?",a="Dorii Brightwhisper est le maître des mages qui réside dans le bâtiment derrière Rorian the Dayseeker, au Bosquet de Thendal, sur l’Île de Zéphras. Dorii guide les jeunes mages qui cherchent à renouer avec les anciennes traditions arcaniques de leur peuple.",al={"qui est dorii","maître des mages de zéphras","emplacement de dorii"}},{q="Pourquoi la magie des arcanes a-t-elle décliné chez le peuple de Zéphras ?",a="Comme l’explique Dorii, la magie des arcanes a décliné peu à peu pendant les milliers d’années où son peuple a vécu reclus dans les hauteurs, parmi les nuages. Dorii et les autres instructeurs forment de nouveaux novices pour qu’ils recherchent et retrouvent ce qui a été perdu.",al={"pourquoi la magie a-t-elle décliné","lore des arcanes des skyborne","magie des arcanes perdue"}},{q="Qui donne cette quête ?",a="Rorian the Dayseeker propose cette quête au Bosquet de Thendal, sur l’Île de Zéphras, après qu’un mage en herbe a terminé Harmony in Balance.",al={"donneur de quête","qui lance a student of the arcane","quête de rorian"}},{q="Où puis-je trouver Dorii Brightwhisper ?",a="Dorii Brightwhisper vit dans le bâtiment juste derrière Rorian the Dayseeker, au Bosquet de Thendal.",al={"emplacement de dorii brightwhisper","où est le maître des mages","trouver dorii"}},{q="Quel prérequis faut-il remplir avant de commencer cette quête ?",a="Vous devez d’abord terminer Harmony in Balance, qui consiste à régler le problème des vuldrens locaux pour Rorian the Dayseeker.",al={"prérequis","quelle quête faire avant"}}},fx={["1ed09f17"]={q="Pourquoi Rorian the Dayseeker vous envoie-t-il auprès de Dorii ?",a="Rorian transmet simplement une communication urgente destinée à vous. Pendant que vous vous occupiez de la menace vuldren voisine, Dorii Brightwhisper a laissé un cristal de rappel spécifiquement inscrit pour votre attention. Rorian s'assure que vous receviez le cristal et vous guide directement vers le maître des mages du bosquet afin que votre potentiel arcanique ne reste pas inexploité.",al={"pourquoi rorian vous envoie-t-il","motif de rorian the dayseeker","pourquoi parler à dorii brightwhisper"}},ab250928={q="Pourquoi Dorii Brightwhisper veut-elle vous entraîner spécifiquement ?",a="Les arts arcaniques ont décliné parmi vos semblables au fil des millénaires passés isolés dans les nuages. Ayant prouvé votre compétence face aux menaces locales, Dorii Brightwhisper voit en vous la capacité brute nécessaire pour aider à récupérer cet héritage perdu. Elle cherche des apprentis mages qui peuvent activement explorer et maîtriser les arcanes, plutôt que de laisser le savoir ancien s'effacer de la mémoire.",al={"pourquoi vous a student of the arcane","pourquoi m'entraîner","pourquoi dorii veut-elle de moi"}}},fp="23,217,20.301.0,24.270.0,35.210.0,27.215.0,55.213.0,21.118.0,37.101.0,63.111.0"}
P.entries["quest:92482"] = {n="The Way of the Hunter",s="Les jeunes chasseurs du Bosquet de Thendal commencent leur entraînement après avoir repoussé les vuldrens locaux. Rorian the Dayseeker les convoque pour rencontrer Tai'ree Farsight et commencer leur apprentissage officiel.",h="Les jeunes chasseurs du Bosquet de Thendal commencent leur entraînement après avoir repoussé les vuldrens...",kw={"maître-chasseur","rorian the dayseeker","note gribouillée","tai'ree farsight","the way of the hunter","bosquet de thendal","vuldrens","zéphras"},ang={["class:Hunter"]="Sur l'Île de Zéphras, vous commencez votre entraînement officiel de chasseur auprès de Tai'ree Farsight."},sec={{t="Une convocation à la chasse",b="Après avoir éclairci les rangs des vuldrens qui perturbaient les abords du Bosquet de Thendal, les jeunes chasseurs découvrent à leur retour que leurs compétences pratiques ont attiré l'attention. Rorian the Dayseeker leur remet une Note gribouillée de Tai'ree Farsight, la maître-chasseuse du bosquet. Pour les rôdeurs novices qui se préparent à explorer l'Île de Zéphras, cette rencontre fait passer leur travail de la défense de l'île à l'apprentissage des techniques martiales et de la survie."},{t="L'apprentissage de Tai'ree",b="Près du centre du village, Tai'ree Farsight accueille les élèves prometteurs avec un réalisme rigoureux. Pour prospérer dans une nature sauvage, il faut des sens affûtés et des réflexes éclairs. Ses conseils s'appuient sur ses longues années d'expérience et offrent aux pisteurs de l'île une base pour perfectionner leur tir de précision et leurs compétences de survie."}},faq={{q="Qui propose cette tâche ?",a="Après avoir aidé Rorian the Dayseeker à régler le problème des vuldrens locaux dans « Harmony in Balance », il vous propose cet entraînement au Bosquet de Thendal, sur l'Île de Zéphras.",al={"qui donne the way of the hunter","début de quête","quête de rorian"}},{q="Qui est Tai'ree Farsight ?",a="Tai'ree Farsight est la maître-chasseuse du Bosquet de Thendal, près du centre du village. Elle supervise l'entraînement et la discipline des tireurs en herbe et des pisteurs de l'île.",al={"où se trouve tai'ree","maître-chasseur bosquet de thendal","emplacement de tai'ree farsight"}},{q="À quoi sert la Note gribouillée ?",a="La Note gribouillée est un message laissé par Tai'ree Farsight pendant que vous vous occupiez des vuldrens. Elle vous indique de la retrouver sur la place du village pour commencer un entraînement avancé.",al={"note gribouillée","que dit la note","note de chasseur"}},{q="Où se déroule cette quête ?",a="La quête se déroule entièrement au Bosquet de Thendal, un avant-poste sur l'Île de Zéphras.",al={"zone de quête","lieu de la quête de chasseur","où se trouve le bosquet de thendal"}},{q="Quel prérequis faut-il remplir avant cette quête ?",a="Avant de rencontrer Tai'ree, vous devez accomplir « Harmony in Balance » pour Rorian the Dayseeker. Vous y faites vos preuves en vous occupant des vuldrens agressifs près du bosquet.",al={"prérequis pour the way of the hunter","comment débloquer","quête précédente"}},{q="Qu'enseigne Tai'ree Farsight aux nouveaux chasseurs ?",a="Tai'ree Farsight est votre maître de classe. Lui parler vous présente les principes fondamentaux du pistage sur l'île et vous donne accès aux techniques de combat et aux compétences de chasseur de base.",al={"que fait tai'ree","pourquoi parler à tai'ree"}}},fx={bb563a7d={q="Pourquoi Rorian the Dayseeker vous envoie-t-il auprès de Tai'ree Farsight ?",a="Pendant que vous étiez occupé à gérer la menace vuldren, le maître des chasseurs du village, Tai'ree Farsight, a spécifiquement laissé un mot demandant à vous parler. Rorian transmet simplement le message et vous indique où elle attend dans le Bosquet de Thendal afin que vous puissiez commencer à perfectionner vos compétences martiales.",al={"pourquoi rorian vous envoie-t-il","motif de rorian la voie du chasseur","pourquoi rendre visite à tairee farsight"}}},fp="21,173,21.403.0,23.307.0,21.153.0,24.164.0,42.181.0,33.86.0,54.184.0,45.185.0"}
P.entries["quest:92483"] = {n="At Home in the Shadows",s="Rorian vous envoie rencontrer Akeri Duskblade dans le Bosquet de Thendal, où commence l’entraînement des voleurs. Cette convocation marque le passage des corvées du village à la discrétion et au combat.",h="Rorian vous envoie rencontrer Akeri Duskblade dans le Bosquet de Thendal, où commence l’entraînement des...",kw={"akeri duskblade","at home in the shadows","quête de voleur","maître des voleurs","rorian the dayseeker","note simple","bosquet de thendal","île de zéphras"},ang={["class:Rogue"]="En tant que voleur, vous commencez votre entraînement officiel sur l’Île de Zéphras en rencontrant Akeri Duskblade dans la tour de guet du Bosquet de Thendal."},sec={{t="Une invitation suspecte",b="Akeri Duskblade a remarqué les jeunes voleurs qui s’occupent des menaces autour du Bosquet de Thendal. Le maître des voleurs du bosquet évite de rencontrer ouvertement les habitants, alors il fait parvenir un mot par Rorian the Dayseeker. Akeri garde ses raisons pour lui, mais Rorian voit qu’il connaît les compétences dont un voleur a besoin au-delà des limites protégées du bosquet."},{t="Leçons dans la tour de guet",b="Akeri Duskblade vous attend dans la tour de guet du village du Bosquet de Thendal. Il observe l’aplomb et la vigilance de chaque nouvelle recrue, puis avertit que des pas imprudents hors du bosquet peuvent mener à une mort prématurée. Réussir son examen marque le début de l’entraînement officiel à la discrétion, à la précision et à la survie sur l’Île de Zéphras."}},faq={{q="Qui donne la quête At Home in the Shadows ?",a="Après avoir terminé Harmony in Balance, Rorian the Dayseeker vous remet la convocation d’Akeri dans le Bosquet de Thendal, sur l’Île de Zéphras.",al={"qui lance at home in the shadows","donneur de quête at home in the shadows","quête de rorian"}},{q="Où trouver Akeri Duskblade ?",a="Akeri Duskblade vous attend dans la tour de guet du village, dans le Bosquet de Thendal, sur l’Île de Zéphras.",al={"emplacement d’akeri duskblade","où trouver akeri duskblade","trouver akeri"}},{q="Qu’est-ce que la note simple donnée pendant la quête ?",a="La note simple d’Akeri Duskblade invite les voleurs prometteurs à le rencontrer. Lisez-la avant de parler à Akeri.",al={"note simple zéphras","qu’est-ce que la note","lire la note simple"}},{q="Cette quête est-elle accessible à toutes les classes ?",a="Non. Cet entraînement s’adresse aux voleurs qui apprennent leur métier dans le Bosquet de Thendal.",al={"les non-voleurs peuvent-ils faire cette quête","at home in the shadows réservé aux voleurs","condition de classe"}},{q="Qu’enseigne Akeri Duskblade ?",a="Akeri Duskblade enseigne la discrétion, la ruse et le maniement de la lame aux voleurs du Bosquet de Thendal qui commencent leur périple à travers l’Île de Zéphras.",al={"rôle d’akeri duskblade","qui est akeri","maître des voleurs bosquet de thendal"}},{q="Quelle quête préalable faut-il terminer ?",a="Terminez d’abord Harmony in Balance pour Rorian the Dayseeker. Il vous remettra ensuite la note d’Akeri.",al={"prérequis at home in the shadows","quête précédente","débloquer at home in the shadows"}}},fx={["776f9cb3"]={q="Pourquoi Rorian the Dayseeker vous envoie-t-il auprès d'Akeri Duskblade ?",a="Après avoir prouvé vos capacités en gérant la menace vuldren locale, Rorian transmet simplement une convocation. Akeri Duskblade, le maître des voleurs résident du bosquet, a spécifiquement demandé à vous voir et a laissé un mot pour votre attention. Rorian reconnaît qu'un apprenti voleur a besoin d'un tutorat approprié par quelqu'un adapté au métier, notant avec espièglerie que vous et la louche Duskblade vous entendrez probablement bien.",al={"motifs de rorian","pourquoi envoyer vers akeri","pourquoi parler à akeri duskblade"}},["4629917d"]={q="Pourquoi Rorian a-t-il besoin que vous y alliez au lieu de traiter lui-même avec Akeri ?",a="Akeri Duskblade a demandé à vous voir personnellement, pas Rorian ou les gardiens du bosquet. Vous avez choisi la voie du voleur, et Akeri est le mentor local responsable de l'entraînement de ceux qui opèrent depuis les ombres. La convocation est destinée à tester votre conscience, aiguiser vos instincts et vous préparer à survivre au-delà de la sécurité du Bosquet de Thendal.",al={"pourquoi moi akeri duskblade","pourquoi akeri veut-elle me voir","pourquoi le maître des voleurs veut-il de moi"}}},fp="22,157,18.326.0,25.286.0,43.118.0,33.85.0,47.101.0,39.69.0,32.135.0,48.91.0"}
P.entries["quest:92484"] = {n="Embracing the Elements",s="Au Bosquet de Thendal, Rorian the Dayseeker appelle les jeunes chamans à commencer leur formation élémentaire. Le message de Windshaper Boro évoque le silence entre le peuple et les esprits des vents.",h="Au Bosquet de Thendal, Rorian the Dayseeker appelle les jeunes chamans à commencer leur formation élémentaire.",kw={"embracing the elements","cristal de rappel bourdonnant","rorian the dayseeker","chaman","esprits des quatre vents","bosquet de thendal","windshaper boro","île de zéphras"},ang={["class:Shaman"]="En tant que chaman, vous rencontrez Windshaper Boro pour recevoir un enseignement formel et apprenez que les vents élémentaires sont devenus silencieux. Les chamans se consacrent à rétablir la communion avec eux.",["faction:Horde"]="En tant que voyageur de la Horde sur l’Île de Zéphras, vous rencontrez les invocateurs élémentaires de l’île et découvrez leur lutte avec les esprits. Le silence des esprits façonne leur entraînement."},sec={{t="Un appel aux éléments",b="Rorian the Dayseeker vient vous voir après que vous avez aidé à régler le problème des vuldrens autour du village. Windshaper Boro a laissé un Cristal de rappel bourdonnant pendant votre absence. Son message vous appelle au centre du bosquet, où commence l’enseignement formel des éléments."},{t="Le silence des vents",b="Windshaper Boro vous apprend que les esprits des quatre vents ont cessé toute communication il y a des années. Ils ont rompu la communion qu’ils partageaient autrefois avec le peuple. Désormais, les chamans de l’Île de Zéphras étudient le monde naturel et s’entraînent avec acharnement, dans l’espoir de briser le silence et de parler à nouveau aux esprits."}},faq={{q="Qui donne la quête Embracing the Elements ?",a="Après que vous avez aidé à régler le problème des vuldrens locaux, Rorian the Dayseeker vous envoie depuis le Bosquet de Thendal, sur l’Île de Zéphras.",al={"donneur de quête embracing the elements","qui lance embracing the elements"}},{q="Où se trouve Windshaper Boro ?",a="Près du centre du Bosquet de Thendal, sur l’Île de Zéphras, Windshaper Boro forme les chamans du village.",al={"emplacement de windshaper boro","où se trouve boro","trouver windshaper boro"}},{q="Pourquoi les esprits élémentaires ont-ils cessé de parler aux habitants ?",a="Windshaper Boro dit que les esprits des quatre vents ont cessé de parler et ont quitté le peuple il y a des années. Les chamans locaux ignorent pourquoi, mais ils étudient dans l’espoir de rétablir ce lien.",al={"pourquoi les vents sont silencieux","silence des esprits des quatre vents","que sont devenus les esprits du vent"}},{q="Qu’est-ce que le Cristal de rappel bourdonnant ?",a="Windshaper Boro a laissé le Cristal de rappel bourdonnant pendant que vous aidiez le village. L’examiner indique que vous êtes prêt à commencer la formation élémentaire sous sa tutelle.",al={"cristal de rappel bourdonnant","cristal de rappel zéphras"}},{q="Quelle quête préalable mène à Embracing the Elements ?",a="Harmony in Balance vient d’abord. Vous vous occupez des vuldrens qui perturbent les environs.",al={"quête préalable embracing the elements","quelle quête précède embracing the elements"}},{q="Quel est le rôle de Windshaper Boro au Bosquet de Thendal ?",a="Windshaper Boro forme les chamans du Bosquet de Thendal. Il enseigne aux nouveaux initiés la communion élémentaire et le monde naturel.",al={"que fait boro","rôle de windshaper boro"}}},fx={["52185878"]={q="Pourquoi Rorian the Dayseeker vous envoie-t-il auprès du Sculpte-vents Boro ?",a="Pendant que vous étiez occupé à gérer les problèmes de vuldren du bosquet, le Sculpte-vents Boro a spécifiquement laissé un cristal de rappel aux soins de Rorian à votre intention. Rorian ne fait que vous transmettre le cristal et vous diriger vers Boro, près du centre du village, afin que vous puissiez commencer à apprendre à marcher sur la voie des éléments.",al={"pourquoi rorian veut-il cela","quête rorian boro pourquoi","pourquoi examiner le cristal de rappel bourdonnant"}}},fp="22,190,25.245.0,16.285.0,43.113.0,33.100.0,63.180.0,35.179.0,56.90.0,53.126.0"}
P.entries["quest:92485"] = {n="A Student of Nature",s="Sur l’Île de Zéphras, A Student of Nature commence par une convocation adressée aux druides novices. Après avoir contribué à rétablir l’harmonie locale, ils sont appelés par Xyton Silverwind sous les ramures du Bosquet de Thendal pour découvrir l’équilibre naturel de l’île.",h="Sur l’Île de Zéphras, A Student of Nature commence par une convocation adressée aux druides novices.",kw={"druide","parchemin plié","rorian the dayseeker","bosquet de thendal","vuldren","xyton silverwind","île de zéphras"},ang={["class:Druid"]="En tant que druide, vous commencez une formation à vie avec Xyton Silverwind dans les arts de la nature, du croc et de la branche."},sec={{t="Une convocation du bosquet",b="Après la résolution des troubles locaux causés par une faune trop zélée, Rorian the Dayseeker remet une convocation personnelle aux jeunes initiés. Le parchemin plié a été laissé par Xyton Silverwind. Il invite les aspirants druides à s’avancer et à étudier les mystères les plus profonds de la nature, car leurs talents naturels ont attiré l’attention des anciens du bosquet."},{t="Gardiens de l’équilibre",b="Rencontrer Xyton Silverwind au niveau inférieur du grand arbre dans le Bosquet de Thendal marque le premier pas d’un novice dans sa vocation. Pour Silverwind, les plantes et les animaux de l’Île de Zéphras forment un tout vivant complexe qui exige des soins constants et un équilibre vigilant. La voie du croc, de la griffe, de la plume et de la branche demande un mentorat durable, et cette rencontre inaugure une vie consacrée à veiller sur la nature."}},faq={{q="Qui envoie le joueur auprès de Xyton Silverwind ?",a="Après avoir contribué à maîtriser les vuldren indisciplinés autour du bosquet, Rorian the Dayseeker vous remet un parchemin plié qui vous dirige vers Xyton Silverwind.",al={"qui donne a student of nature","donneur de quête","rorian"}},{q="Où se trouve Xyton Silverwind ?",a="Xyton Silverwind se trouve au rez-de-chaussée du grand arbre dans le Bosquet de Thendal, juste derrière Rorian the Dayseeker, sur l’Île de Zéphras.",al={"emplacement de xyton silverwind","où se trouve xyton","emplacement du maître des druides"}},{q="Quel est le but de cette quête ?",a="A Student of Nature présente Xyton Silverwind aux druides novices comme leur principal enseignant et guide pour préserver l’équilibre naturel de l’Île de Zéphras.",al={"pourquoi faire cette quête","objectif de la quête","début de la formation des druides"}},{q="Qu’enseigne Xyton Silverwind aux druides novices sur l’Île de Zéphras ?",a="Silverwind enseigne que les plantes et les animaux de l’île sont liés et qu’ils ont besoin de soins actifs et d’équilibre, par les disciplines du croc, de la griffe, de la plume et de la branche.",al={"que dit xyton","équilibre naturel de zéphras","rôle des druides à zéphras"}},{q="Quel prérequis faut-il remplir avant de recevoir cette convocation ?",a="Les initiés doivent d’abord accomplir Harmony in Balance pour Rorian the Dayseeker et s’occuper de la population de vuldren indisciplinés avant de recevoir le message de Silverwind.",al={"quête prérequise","quête précédente","avant a student of nature"}},{q="Que contient le Parchemin plié ?",a="Le parchemin plié est un message laissé par Xyton Silverwind. Il invite le jeune druide prometteur à le retrouver sous la canopée du grand arbre pour poursuivre sa formation.",al={"message du parchemin plié","message de silverwind","que contient le parchemin"}}},fx={caa97f7a={q="Pourquoi Rorian the Dayseeker vous envoie-t-il auprès de Xyton Silverwind ?",a="Pendant que vous étiez occupé à gérer la menace vuldren locale, le maître des druides résident, Xyton Silverwind, a spécifiquement laissé un message pour vous. Rorian sert d'intermédiaire pour s'assurer que les initiés prometteurs reçoivent les instructions appropriées, vous exhortant à écouter les conseils de Silverwind afin que vous puissiez maîtriser les arts druidiques et préserver l'équilibre naturel.",al={"motif de rorian","pourquoi m'envoyer vers silverwind","pourquoi rorian vous donne-t-il un parchemin plié"}}},fp="19,216,24.341.0,22.376.0,41.144.0,34.125.0,34.140.0,66.167.0,66.146.0,46.164.0"}
P.entries["quest:92489"] = {n="Power Overwhelming",s="High Sorcerer Andromath envoie de l’aide de Hurlevent à Dalaran, où la magie arcanique est devenue dangereuse. Le Kirin Tor reconstruit la cité derrière des frontières closes, tandis qu’un Mana Elemental menace ses travaux.",h="High Sorcerer Andromath envoie de l’aide de Hurlevent à Dalaran, où la magie arcanique est devenue dangereuse.",kw={"énergie arcanique","archimonde","dalaran","high sorcerer andromath","kirin tor","mana elemental","power overwhelming","hurlevent"},ang={["class:Mage"]="En tant que mage, vous savez que le Kirin Tor partage votre vocation et que les manifestations arcaniques instables mettent Dalaran en danger.",["faction:Alliance"]="En tant qu’allié du Kirin Tor, vous savez que Hurlevent tient à renforcer ses liens avec lui en aidant Dalaran à se reconstruire."},sec={{t="Une cité recluse",b="Après qu’Archimonde a détruit Dalaran lors de la Troisième guerre, le Kirin Tor s’est replié sur lui-même. Autrefois, érudits et sorciers accouraient du monde entier à ses portes. À présent, les mages survivants tiennent les étrangers à l’écart tandis qu’ils reconstruisent leur cité en ruine derrière des frontières closes."},{t="Forces arcaniques incontrôlées",b="Tandis que le Kirin Tor restaure Dalaran, l’énergie arcanique est devenue dangereuse. Des fuites instables jaillissent hors de contrôle et prennent la forme d’êtres de pur mana. High Sorcerer Andromath craint que des troubles internes ne compromettent le rétablissement de la cité, ou que Dalaran ne renonce à ses anciens liens avec l’Alliance. Il envoie donc des champions de Hurlevent pour apaiser le Mana Elemental et rappeler au Kirin Tor que ses alliés sont toujours à ses côtés."}},faq={{q="Qu’est-ce que la quête Power Overwhelming ?",a="High Sorcerer Andromath envoie de l’aide de Hurlevent tandis que le Kirin Tor reconstruit Dalaran. Un Mana Elemental né d’une énergie arcanique incontrôlée menace leurs travaux.",al={"qu’est-ce que power overwhelming","quête power overwhelming","quête mana elemental dalaran"}},{q="Qui donne cette quête ?",a="High Sorcerer Andromath demande aux champions de Hurlevent de se rendre à Dalaran pour aider le Kirin Tor.",al={"qui donne power overwhelming","quête andromath","où commencer power overwhelming"}},{q="Pourquoi Dalaran est-elle recluse et méfiante ?",a="Archimonde a dévasté Dalaran lors de la Troisième guerre. Tandis que le Kirin Tor reconstruit sa cité, les mages survivants restent méfiants envers les étrangers.",al={"pourquoi dalaran est-elle recluse","que s’est-il passé à dalaran","pourquoi les mages de dalaran sont-ils méfiants"}},{q="Quelle est la cause du trouble à Dalaran ?",a="Pendant la reconstruction de Dalaran, une énergie arcanique instable est devenue incontrôlable et a donné naissance à des élémentaires de mana hostiles.",al={"déferlement arcanique à dalaran","pourquoi y a-t-il des élémentaires de mana à dalaran","que se passe-t-il à dalaran"}},{q="Qu’est-ce que le Mana Elemental ?",a="Un Mana Elemental est un être formé de pur mana. Son apparition montre que le trouble arcanique qui menace Dalaran est plus grave que ne le laissaient penser les premiers rapports.",al={"qu’est-ce que le mana elemental","lore des élémentaires de dalaran","créature de pur mana"}},{q="Pourquoi Hurlevent envoie-t-elle de l’aide à Dalaran ?",a="Le Kirin Tor est depuis longtemps un allié de l’Alliance. High Sorcerer Andromath envoie de l’aide, car il craint que Dalaran ne sombre dans le chaos ou ne quitte l’Alliance alors qu’elle est vulnérable.",al={"pourquoi hurlevent aide-t-elle dalaran","pourquoi l’alliance se soucie-t-elle de dalaran"}}},fp="18,189,19.248.0,21.415.0,37.155.0,21.101.0,41.133.0,43.118.0,27.156.0,41.171.0"}
P.entries["quest:92514"] = {n="Welcome to Shen'dar Village",s="À Shen’dar, les nouveaux venus sont envoyés rencontrer l’aînée et l’aubergiste du village. Les tensions locales côtoient la menace grandissante des bandits à la frontière.",h="À Shen’dar, les nouveaux venus sont envoyés rencontrer l’aînée et l’aubergiste du village.",kw={"bandits","coriella calmbreeze","ordre suprême","illaya amberwind","shen’dar","touché par les esprits","welcome to shen'dar village","sculpte-vents"},ang={["class:Shaman"]="En tant que chaman, vous pouvez sentir la faible charge d’électricité statique dans l’air autour des Sculpte-vents touchés par les esprits, comme Illaya Amberwind à Shen’dar."},sec={{t="Premiers pas à Shen’dar",b="À Shen’dar, les nouveaux venus rencontrent d’abord les personnes qui organisent la vie quotidienne. Ceux qui sont touchés par les esprits sont envoyés auprès de l’aînée Illaya Amberwind, près de la place du village. Coriella Calmbreeze accueille les visiteurs à l’auberge du village, où ils peuvent trouver un logement et des provisions. Ces présentations aident les voyageurs à découvrir les coutumes du village avant de prendre les armes."},{t="Factions et troubles à la frontière",b="Les différends à Shen’dar restent courtois, même si les Sculpte-vents et l’Ordre suprême ne sont pas d’accord. Leurs frictions idéologiques traversent la région, mais les deux groupes savent que la survie passe avant tout. Les bandits gagnent du terrain. Ce danger incite le village à mettre de côté les querelles mineures."}},faq={{q="Quel est l’objectif de la quête Welcome to Shen’dar ?",a="La quête Welcome to Shen’dar guide les nouveaux venus vers les personnes qui dirigent la communauté et la servent. Les voyageurs sont envoyés auprès de l’aînée des Sculpte-vents du village et de l’aubergiste avant d’aider à régler les problèmes locaux, comme la présence des bandits.",al={"quête de shen’dar","aperçu de la quête welcome to shen’dar","que faire à shen’dar"}},{q="Qui est Illaya Amberwind ?",a="Illaya Amberwind est l’aînée des Sculpte-vents de Shen’dar. Elle se trouve près du centre du village et guide ceux qui sont touchés par les esprits, dans un contexte de tensions politiques locales.",al={"qui est illaya amberwind","emplacement d’illaya amberwind","aînée des sculpte-vents de shen’dar"}},{q="Qui est Coriella Calmbreeze ?",a="Coriella Calmbreeze tient l’auberge de Shen’dar, où elle propose le gîte, le repos et des provisions aux voyageurs et aux habitants.",al={"qui est coriella calmbreeze","aubergiste de shen’dar","où se trouve l’auberge de shen’dar"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents sont des personnes touchées par les esprits, que signale une charge d’électricité statique dans l’air autour d’elles. Malgré leurs tensions et les menaces plus vastes, eux et l’Ordre suprême entretiennent des relations courtoises à Shen’dar.",al={"que sont les sculpte-vents","traditions des sculpte-vents touchés par les esprits","ordre suprême contre sculpte-vents"}},{q="Quelle est la tension entre l’Ordre suprême et les Sculpte-vents ?",a="L’Ordre suprême et les Sculpte-vents sont en conflit politique et idéologique. À Shen’dar, les deux camps préservent la paix et s’occupent de préoccupations communes plus urgentes.",al={"qu’est-ce que l’ordre suprême","conflit à shen’dar","tensions entre l’ordre suprême et les sculpte-vents"}},{q="À quels problèmes Shen’dar est-il actuellement confronté ?",a="Shen’dar fait face aux bandits qui sévissent dans les environs, ainsi qu’au différend philosophique entre les Sculpte-vents et l’Ordre suprême.",al={"problèmes à shen’dar","quelle menace pèse sur shen’dar","bandits à shen’dar"}}},fp="27,136,23.361.0,29.291.0,61.234.0,24.155.0,27.112.0,24.221.0,63.168.0,51.146.0"}
P.entries["quest:92515"] = {n="The Problem With Prideclaws",s="Le village des Hautes-terres de Shen’dar est menacé par les prideclaws, les bandits et les cultistes. Les bêtes s’approchent de la colonie, et les abattre protège ses habitants tout en fournissant des peaux utiles.",h="Le village des Hautes-terres de Shen’dar est menacé par les prideclaws, les bandits et les cultistes.",kw={"abattage","peaux de prideclaw","prideclaws","shen’dar","hautes-terres de shen’dar","the problem with prideclaws","frontières du village"},ang={["class:Hunter"]="Pour un chasseur, traquer et abattre les prédateurs près des colonies est un travail familier. Mais les prideclaws, avec un tel nombre, imposent le respect."},sec={{t="Une menace sauvage grandissante",b="Les prideclaws s’approchent du village des Hautes-terres de Shen’dar. Des bandits rôdent dans les collines, et des cultistes déments troublent la région. Les villageois sont menacés de plusieurs côtés. À mesure que les bêtes gagnent en audace et étendent leur territoire, la colonie se retrouve de plus en plus à leur portée."},{t="Protéger les frontières",b="Les villageois ont organisé une chasse aux prideclaws avant que les prédateurs errants ne s’en prennent aux animaux domestiques ou aux enfants. Repousser les prideclaws loin des frontières contribue à protéger la colonie. Leurs peaux robustes fournissent aussi aux artisans du village la matière nécessaire à la fabrication d’objets utiles."}},faq={{q="Que sont les prideclaws ?",a="Les prideclaws sont de féroces prédateurs des collines et des hautes-terres de Shen’dar. Leurs peaux ont de la valeur, et leur nombre grandissant les rapproche des colonies.",al={"que sont les prideclaws","histoire des prideclaws","prideclaws"}},{q="Où se trouvent les prideclaws ?",a="Les prideclaws rôdent dans les collines des Hautes-terres de Shen’dar. Leur nombre grandissant les rapproche du village et de ses habitants.",al={"où se trouve cette quête","où vivent les prideclaws","emplacement des prideclaws"}},{q="Pourquoi le village doit-il réduire le nombre de prideclaws ?",a="Des bandits et des cultistes fous menacent déjà la région. À mesure que leur nombre augmente, les prideclaws s’approchent du village et mettent en danger les enfants et les animaux domestiques.",al={"pourquoi tuer les prideclaws","pourquoi réduire le nombre de prideclaws","danger pour le village"}},{q="Que fera-t-on des peaux de prideclaw ?",a="Les artisans du village utilisent les peaux de prideclaw pour fabriquer des objets et des fournitures pratiques.",al={"que deviennent les peaux","utilisation des peaux de prideclaw","utilité des peaux"}},{q="Quels autres dangers menacent les collines environnantes ?",a="Des bandits errants et des cultistes instables troublent les collines autour de la colonie, aux côtés des prideclaws sauvages.",al={"autres menaces à shen’dar","qu’est-ce qui menace aussi le village","menaces locales"}},{q="Que pensent les habitants des prideclaws ?",a="Le villageois chargé de superviser la chasse trouve les prideclaws plutôt mignons, même derrière des gardes armés. Il faut toutefois protéger le village avant qu’un drame ne survienne.",al={"qui donne la quête the problem with prideclaws","avis du donneur de quête"}}},fp="27,188,21.276.0,20.237.0,20.157.0,33.131.0,48.159.0,43.74.0,48.109.0,38.162.0"}
P.entries["quest:92516"] = {n="Hippogryph Harassment",s="Près de Shen’dar, Hippogryph Harassment met les voyageurs en danger. Une volée sauvage niche au sud-est du village, dans les Hautes-terres de Shen’dar, et attaque ceux qui empruntent la route voisine. Vous devez éliminer ses jeunes, ses protecteurs et sa matriarche pour permettre aux voyageurs de passer sans danger.",h="Près de Shen’dar, Hippogryph Harassment met les voyageurs en danger.",kw={"hippogriffe","hippogryph harassment","matriarche hippogriffe","protecteur hippogriffe","jeune hippogriffe","kalimdor","matriarche","hautes-terres de shen’dar","shen’dar"},ang={["class:Druid"]="En tant que druide, vous recherchez l’harmonie avec la nature sauvage. Vous pouvez considérer cet abattage comme une nécessité regrettable pour rétablir l’équilibre après que les bêtes se sont mises à s’attaquer aux voyageurs.",["class:Hunter"]="En tant que chasseur, vous comprenez l’instinct prédateur des bêtes ailées et la hiérarchie d’un perchoir sauvage. Tuer la matriarche est le meilleur moyen de mettre fin à l’agressivité de la volée.",["race:NightElf"]="En tant qu’elfe de la nuit, vous vénérez les hippogriffes comme les compagnons sacrés d’Élune. Décimer une volée sauvage agressive est une tâche solennelle lorsque la nature sauvage menace la sécurité des voyageurs."},sec={{t="Péril sur la route",b="Les voyageurs près de Shen’dar sont menacés par le ciel. Une volée sauvage niche au sud-est du village, dans les Hautes-terres de Shen’dar. Partout dans Kalimdor, les hippogriffes sont connus comme de nobles bêtes, et certains sont liés à des cavaliers elfes. Les volées indomptées, toutefois, défendent férocement leur territoire.\n\nLes convois et les voyageurs isolés qui empruntent les chemins en contrebas sont devenus la cible d’embuscades aériennes. Ces attaques entravent le passage et pourraient isoler le village si les créatures ne sont pas maîtrisées."},{t="Décimer la volée",b="Il faut s’attaquer aux aires de nidification de la volée dans les Hautes-terres de Shen’dar pour mettre fin au danger. Pour sécuriser les routes en altitude, tuez les jeunes avant qu’ils n’atteignent leur maturité et venez à bout des protecteurs vigilants qui gardent le périmètre.\n\nLa matriarche dirige les attaques contre les passants. Les voyageurs ne pourront emprunter les routes sans danger que lorsque le nid aura été frappé et qu’elle aura été tuée."}},faq={{q="Pourquoi les hippogriffes attaquent-ils les voyageurs près de Shen’dar ?",a="Les hippogriffes ont établi leurs aires de nidification au sud-est de Shen’dar, dans les Hautes-terres de Shen’dar. Leur territoire borde la principale route de passage, et ils attaquent ceux qui s’en approchent pour défendre leur couvée et leurs terrains de chasse.",al={"pourquoi les hippogriffes attaquent","pourquoi les hippogriffes sont hostiles","cause des attaques d’hippogriffes"}},{q="Où se trouve la volée d’hippogriffes ?",a="La volée niche au sud-est de Shen’dar, dans les Hautes-terres de Shen’dar. Son perchoir surplombe la route, où les jeunes, les protecteurs et la matriarche se rassemblent parmi les falaises et les crêtes.",al={"où sont les hippogriffes","emplacement des hippogriffes","emplacement des hautes-terres de shen’dar"}},{q="Quels hippogriffes faut-il tuer pour accomplir la tâche ?",a="Pour rétablir la sécurité des voyageurs, tuez huit jeunes hippogriffes, six robustes protecteurs hippogriffes et la matriarche hippogriffe qui dirige le perchoir dans les Hautes-terres de Shen’dar.",al={"quels hippogriffes tuer","cibles de hippogryph harassment","objectifs hippogriffes"}},{q="Qui dirige la volée d’hippogriffes ?",a="Une puissante matriarche hippogriffe dirige la volée dans les Hautes-terres de Shen’dar. Elle commande le perchoir et sa défense des aires de nidification au sud-est de Shen’dar ; il faut donc la tuer pour libérer la route de l’emprise de la volée.",al={"qui dirige les hippogriffes","matriarche hippogriffe","chef hippogriffe"}},{q="Pourquoi faut-il éliminer les jeunes hippogriffes ?",a="Les jeunes assureront la croissance et l’expansion de la volée. Les éliminer avec les protecteurs adultes empêchera le perchoir de regagner rapidement ses forces ou d’imposer durablement sa terreur sur les routes locales.",al={"pourquoi tuer les jeunes hippogriffes","pourquoi cibler les jeunes hippogriffes","éliminer les jeunes hippogriffes"}},{q="Ces hippogriffes sont-ils apprivoisés ou alliés à quelqu’un ?",a="Non. Ces créatures sauvages et indomptées ont établi un perchoir de leur propre chef dans les Hautes-terres de Shen’dar. Contrairement aux montures disciplinées élevées par les elfes de la nuit, cette volée farouche considère tout humanoïde de passage comme un intrus ou une proie qui empiète sur son territoire.",al={"les hippogriffes sont-ils apprivoisés","ces hippogriffes sont-ils des elfes de la nuit","hippogriffes amicaux"}},{q="Quel danger ces hippogriffes représentent-ils pour le village voisin ?",a="La volée niche en surplomb de la route qui part vers le sud-est depuis Shen’dar. Les bêtes fondent sur les chariots de ravitaillement, les messagers et les voyageurs de passage, menaçant la sécurité des déplacements terrestres et risquant d’isoler le village des terres environnantes.",al={"quelle menace représentent les hippogriffes","danger pour shen’dar","pourquoi les hippogriffes posent problème"}}},fp="21,267,17.465.0,17.357.0,66.235.0,38.181.0,53.165.0,42.231.0,41.232.0,49.257.0,62.250.0"}
P.entries["quest:92517"] = {n="The Criminal Element",s="Les Highlands Bandits terrorisent les Hautes-terres de Shen’dar depuis une grotte derrière une cascade. Une nouvelle secte est arrivée, et les défenseurs locaux sont débordés. Il faut donc faire appel à une aide extérieure contre le chef de la bande, « Badwind » Bennic.",h="Les Highlands Bandits terrorisent les Hautes-terres de Shen’dar depuis une grotte derrière une cascade.",kw={"badwind bennic","bennic","secte","highlands bandits","hautes-terres de shen’dar","the criminal element","grotte derrière une cascade"},ang={["class:Rogue"]="En tant que voleur, vous savez que les grottes cachées derrière les cascades sont des repaires familiers pour les bandits. « Badwind » Bennic et sa bande manquent de prudence pour rester hors de vue des habitants et échapper à leur colère."},sec={{t="Hors-la-loi derrière les chutes",b="Les Highlands Bandits ont établi leur repaire dans une grotte cachée derrière une cascade au nord des Hautes-terres de Shen’dar. Leur chef, « Badwind » Bennic, commande des coupe-jarrets qui tourmentaient les habitants bien avant l'arrivée d'une secte énigmatique. Depuis, leurs actes criminels ont semé la terreur. Les défenseurs locaux sont débordés et ne peuvent détacher de troupes. Vous êtes donc envoyé pour démanteler la bande et abattre Bennic."},{t="Un changement dans l'ombre",b="Après l'élimination de « Badwind » Bennic, les Highlands Bandits perdent leur emprise et les habitants connaissent un bref répit. Pourtant, les hors-la-loi survivants pourraient chercher refuge auprès de la secte voisine. Si elle accueille ces bandits de grand chemin aguerris, ses rangs pourraient grossir et aggraver la menace dans toute la région."}},faq={{q="Qui est « Badwind » Bennic ?",a="« Badwind » Bennic dirige les Highlands Bandits depuis une grotte cachée derrière une cascade dans les Hautes-terres de Shen’dar. Sa bande sévit dans la région depuis longtemps, et les récents troubles en ont fait une menace encore plus grande.",al={"qui est badwind bennic","bennic","badwind"}},{q="Où se cachent les Highlands Bandits ?",a="Les Highlands Bandits se cachent dans une grotte derrière une cascade, au nord des Hautes-terres de Shen’dar.",al={"où se trouvent les bandits","emplacement de la grotte des bandits","grotte derrière une cascade"}},{q="Quelle est la secte mentionnée dans la région ?",a="La secte est une faction nouvelle et inquiétante dont les adeptes se rassemblent à Falaath Village, au sud, et dont les rangs grossissent. Les bandits étaient là avant son arrivée, mais sa présence a rendu la région plus dangereuse. Les forces locales craignent que les bandits survivants ne trouvent refuge auprès de la secte et ne renforcent ses rangs.",al={"quelle secte","lien avec la secte","qui est la secte"}},{q="Pourquoi les forces locales ne peuvent-elles pas s'occuper elles-mêmes des bandits ?",a="Les forces locales sont débordées par l'apparition de la secte et manquent de soldats pour chasser les bandits. Abattre Bennic et disperser sa bande élimine une menace active dans la région.",al={"pourquoi tuer les bandits","problème des bandits"}},{q="Qu'arrive-t-il aux bandits après la défaite de Bennic ?",a="Bennic vaincu, le repaire des bandits est dispersé, mais les hors-la-loi survivants pourraient chercher la protection de la secte voisine et grossir ses rangs déjà inquiétants.",al={"qu'arrive-t-il aux bandits survivants","tous les bandits sont-ils morts"}},{q="Où ce conflit se déroule-t-il ?",a="Les Highlands Bandits rôdent dans les Hautes-terres de Shen’dar, où ils ont établi une grotte cachée derrière une cascade.",al={"où se trouvent les hautes-terres de shen'dar","hautes-terres de shen’dar"}}},fp="20,221,24.398.0,22.278.1,24.206.0,39.95.0,39.323.0,53.187.0,53.159.0,36.100.0"}
P.entries["quest:92519"] = {n="Ward Restocking",s="À Trépas-d'Orgrim, le Docteur Gregory Victor manque de remèdes, d'antidotes et d'élixirs pour l'infirmerie. Les Toniques empaquetés se trouvent à la Ferme de Go'Shek.",h="À Trépas-d'Orgrim, le Docteur Gregory Victor manque de remèdes, d'antidotes et d'élixirs pour l'infirmerie.",kw={"apothicaire jorell","hautes-terres arathies","docteur gregory victor","ferme de go'shek","trépas-d'orgrim","toniques empaquetés","ward restocking"},ang={["faction:Horde"]="En tant que membre de la Horde, vous savez que Trépas-d'Orgrim a besoin d'un approvisionnement régulier en toniques et en médicaments. Ils aident ses soldats, ses défenseurs et les voyageurs à tenir bon face aux menaces des Hautes-terres Arathies.",["race:Undead"]="En tant que Mort-vivant, vous savez que l'apothicaire Jorell représente la Société royale des apothicaires en Arathie. Son comportement imprévisible et ses expériences toxiques à la Ferme de Go'Shek exaspèrent même ses alliés."},sec={{t="Une pénurie à l'infirmerie",b="Le Docteur Gregory Victor soigne les blessés et les malades de Trépas-d'Orgrim dans l'infirmerie. L'apothicaire réprouvé des environs fournit habituellement remèdes, antidotes et élixirs à la clinique. Quand les livraisons cessent, Victor fait appel à des voyageurs capables pour maintenir les réserves de la clinique."},{t="L'ermite de la Ferme de Go'Shek",b="L'apothicaire Jorell travaille dans une cabane exiguë à la Ferme de Go'Shek, au sud-ouest de Trépas-d'Orgrim. Le Docteur Victor affirme que Jorell est souvent absent. Ce chimiste réprouvé excentrique néglige peut-être ses devoirs ou succombe à ses propres concoctions nocives. Les messagers envoyés chercher les Toniques empaquetés devraient trouver les médicaments sur place, que Jorell soit là ou non."}},faq={{q="Qui propose la quête Ward Restocking ?",a="Le Docteur Gregory Victor dirige l'infirmerie de Trépas-d'Orgrim. Quand les livraisons habituelles cessent, il demande à des voyageurs fiables de récupérer des provisions.",al={"qui donne ward restocking","donneur de quête ward restocking","quête du docteur gregory victor"}},{q="Où se trouve l'apothicaire Jorell ?",a="L'apothicaire Jorell travaille dans une petite cabane à la Ferme de Go'Shek, au sud et légèrement à l'ouest de Trépas-d'Orgrim, le long de la route des Hautes-terres Arathies.",al={"où se trouve l'apothicaire jorell","emplacement du laboratoire de jorell","où trouver des toniques"}},{q="Pourquoi le Docteur Gregory Victor vous envoie-t-il à la Ferme de Go'Shek ?",a="Le Docteur Gregory Victor vous envoie à la Ferme de Go'Shek parce que l'apothicaire Jorell n'a pas livré à l'infirmerie de Trépas-d'Orgrim une caisse d'antidotes et d'élixirs dont elle avait un besoin urgent.",al={"pourquoi aller à la ferme de go'shek","que trouve-t-on à la ferme de go'shek"}},{q="De quelles provisions l'infirmerie a-t-elle besoin ?",a="L'infirmerie a besoin d'une caisse de Toniques empaquetés contenant les antidotes et les élixirs de l'apothicaire Jorell. Ils reconstitueront les réserves qui s'épuisent à l'infirmerie de Trépas-d'Orgrim.",al={"que sont les toniques empaquetés","quels objets récupérer"}},{q="Pourquoi l'apothicaire Jorell n'a-t-il pas livré les provisions lui-même ?",a="Le Docteur Gregory Victor soupçonne Jorell de s'être encore empoisonné en préparant ses concoctions dans sa cabane mal aérée, ou d'avoir négligé ses devoirs envers l'infirmerie.",al={"qu'est-il arrivé à jorell","jorell est-il mort","pourquoi jorell n'a-t-il pas livré"}},{q="Où faut-il livrer les provisions ?",a="Apportez la caisse de Toniques empaquetés depuis la Ferme de Go'Shek au Docteur Gregory Victor, à l'infirmerie de Trépas-d'Orgrim.",al={"où apporter les toniques","à qui remettre ward restocking"}}},fp="15,140,22.273.0,27.333.0,37.154.0,35.137.0,56.170.0,38.166.0,60.161.0,37.102.0"}
P.entries["quest:92528"] = {n="Among the Faithful",s="À Falaath Village, vous vous mêlez aux fidèles d’Al’Akir dans les Hautes-terres de Shen’dar. Leurs rangs grandissants et leur magie des tempêtes attirent l’attention, tandis que leurs chefs préparent des plans menaçant les colonies et avant-postes voisins.",h="À Falaath Village, vous vous mêlez aux fidèles d’Al’Akir dans les Hautes-terres de Shen’dar.",kw={"al’akir","among the faithful","falaath village","lorthuna","hautes-terres de shen’dar","prêtre du ciel aanders","tour de guet occidentale","seigneur du vent"},ang={["class:Priest"]="En tant que prêtre, vous connaissez les fois sacrées ou de l’ombre. À Falaath Village, les cultistes suivent des prêtres du ciel dévoués à Al’Akir, le Seigneur du Vent, et canalisent la force primordiale de la tempête.",["class:Shaman"]="En tant que chaman, vous connaissez les forces élémentaires qu’adore le culte d’Al’Akir et qu’il maîtrise grâce à son emprise sur les énergies des tempêtes."},sec={{t="Infiltrer Falaath Village",b="Vous arrivez à Falaath Village, dans les Hautes-terres de Shen’dar, en tant que nouvelle recrue enthousiaste parmi les fidèles d’Al’Akir. Les cultistes se vantent de voir leurs rangs grossir. Ils prétendent que leur dévotion donne forme à la tempête et à sa fureur. Les nouvelles recrues sont généralement envoyées auprès du prêtre du ciel Aanders pour être évaluées, mais une rencontre inattendue à l’auberge du village vient interrompre cette routine."},{t="L’invité secret",b="Le prêtre du ciel Aanders reçoit un invité de marque dans le quartier nord du village. Pendant qu’il est occupé, vous pouvez circuler dans la colonie sans être surveillé. En écoutant les chefs aux portes, vous découvrez leur plan immédiat : une offensive militaire coordonnée dans les Hautes-terres de Shen’dar."},{t="Le plan de Lorthuna",b="Lorthuna est l’invitée mystérieuse de l’auberge et la commandante suprême de tout le culte. Sa présence annonce une attaque agressive contre Shen’dar et la tour de guet occidentale. Shen’dar est un centre de population évident. Pourtant, les éclaireurs locaux ne comprennent pas pourquoi la tour de guet isolée est visée ni ce qui se cache derrière l’offensive du culte portée par la tempête."}},faq={{q="Qui sont les fidèles d’Al’Akir ?",a="Les fidèles d’Al’Akir forment un culte voué au Seigneur du Vent, Al’Akir. Ils sont établis autour de Falaath Village, dans les Hautes-terres de Shen’dar, manient la magie des tempêtes et obéissent à Lorthuna.",al={"qui sont les fidèles d’al’akir","quel est ce culte","culte d’al’akir"}},{q="Qui est le prêtre du ciel Aanders ?",a="Le prêtre du ciel Aanders est un officier haut placé du culte à Falaath Village. Il évalue et accueille les nouvelles recrues, mais il est occupé à recevoir un invité important à l’auberge du village pendant votre infiltration.",al={"qui est le prêtre du ciel aanders","aanders","évaluateur du culte"}},{q="Qui est Lorthuna ?",a="Lorthuna est la cheffe suprême du culte d’Al’Akir. Sa présence secrète à l’auberge de Falaath Village révèle que le culte prépare une offensive imminente de grande envergure dans les Hautes-terres.",al={"qui est lorthuna","lorthuna cheffe du culte","invité à l’auberge"}},{q="Pourquoi le culte vise-t-il la tour de guet occidentale ?",a="Le culte prévoit des attaques simultanées contre Shen’dar et la tour de guet occidentale. Le village est une cible compréhensible, mais les défenseurs des Hautes-terres ignorent toujours le rôle de la tour de guet dans cette attaque.",al={"pourquoi attaquer la tour de guet","culte et tour de guet occidentale","cibles du culte"}},{q="Où cela se passe-t-il ?",a="Falaath Village se trouve dans les Hautes-terres de Shen’dar. Le village est une base importante et un terrain de rassemblement pour les fidèles d’Al’Akir et leurs nouvelles recrues.",al={"où se trouve falaath village","emplacement de falaath village"}},{q="Quelles sont les intentions du culte dans les Hautes-terres de Shen’dar ?",a="Le culte cherche à étendre son influence et à déchaîner la magie des tempêtes dans les Hautes-terres de Shen’dar. Sous la direction de Lorthuna, son assaut immédiat vise Shen’dar et la tour de guet occidentale.",al={"quels sont les objectifs du culte dans les hautes-terres de shen’dar","plans du culte à shen’dar"}}},fp="18,227,28.348.0,16.267.1,17.364.2,32.176.0,25.204.0,16.188.0,49.208.0,27.137.0,57.197.0"}
P.entries["quest:92529"] = {n="Falaath Village",s="À Falaath Village, des recrues marquées se rassemblent pour s’attirer les faveurs du seigneur des Vents. Elles viennent de Shen’dar pour se présenter au missionnaire Jasaan et rejoindre les fidèles.",h="À Falaath Village, des recrues marquées se rassemblent pour s’attirer les faveurs du seigneur des Vents.",kw={"al'akir","falaath village","marque d'akir","missionnaire jasaan","sania silverstream","shen’dar","shen'dorei","seigneur des vents"},ang={["class:Shaman"]="En tant que chaman, vous recherchez l’harmonie avec les esprits élémentaires. Les fidèles s’adressent à Al'Akir par la pénitence et la dévotion religieuse, dans l’espoir de retrouver les vents qui les ont abandonnés.",["race:Skyborne"]="En tant que shen'dorei cherchant à renouer votre lien avec les vents, vous rejoignez les fidèles à Falaath Village dans une contrition partagée. Là, vous espérez regagner les faveurs d’Al'Akir."},sec={{t="La contrition pour le seigneur des Vents",b="À Shen’dar, Sania Silverstream affirme que son peuple est devenu orgueilleux et a tenu les bienfaits de l’air pour acquis. Les esprits du vent l’ont abandonné, et la stagnation a suivi. À présent, des recrues pénitentes reçoivent la marque d’Akir et se rendent à Falaath Village. Là, elles rejoignent d’autres personnes qui espèrent que leurs actes de contrition leur rendront les faveurs du vent."},{t="La mission de Falaath",b="À Falaath Village, le missionnaire Jasaan accueille les initiés portant la marque d’Akir. Jasaan voit en chaque nouvel acolyte une bénédiction des quatre vents. Ceux qui arrivent peuvent chercher la grâce élémentaire d’Al'Akir."}},faq={{q="Quelle est la quête Falaath Village ?",a="Des recrues marquées se rendent de Shen’dar à Falaath Village pour se présenter au missionnaire Jasaan. Là, elles cherchent à rejoindre les fidèles.",al={"quelle est la quête falaath village","présentation de falaath village","quête falaath village"}},{q="Qui est le missionnaire Jasaan ?",a="Le missionnaire Jasaan est un acolyte près de l’entrée de Falaath Village. Jasaan accueille les recrues envoyées par Sania Silverstream pour rechercher les bénédictions d’Al'Akir.",al={"qui est le missionnaire jasaan","histoire de jasaan","missionnaire de falaath"}},{q="Qui est Sania Silverstream ?",a="Sania Silverstream est l’une des fidèles de Shen’dar. Elle donne la marque d’Akir aux nouvelles recrues et les envoie à Falaath Village.",al={"qui est sania silverstream","histoire de sania","sœur sania"}},{q="Pourquoi les shen'dorei vénèrent-ils Al'Akir ?",a="Les fidèles croient que leur peuple est devenu orgueilleux et a tenu les bienfaits des vents pour acquis. Les esprits l’ont abandonné, et par des actes de contrition, ils cherchent à regagner les faveurs d’Al'Akir.",al={"pourquoi vénérer alakir","culte du seigneur des vents alakir","qui est le seigneur des vents"}},{q="Qu’est-ce que la marque d’Akir ?",a="La marque d’Akir est un signe que Sania Silverstream donne aux recrues de Shen’dar. Elle les identifie comme membres des fidèles avant leur entrée à Falaath Village.",al={"qu’est-ce que la marque d'akir","marque d'akir perdue","marque des recrues"}},{q="Qui sont les shen'dorei mentionnés dans la quête ?",a="Les shen'dorei dont parle Sania sont des elfes confrontés à la stagnation depuis que les esprits du vent ont retiré leurs faveurs. Certains cherchent la rédemption par leur dévotion aux éléments.",al={"qui sont les shendorei","histoire des shen dorei"}}},fp="15,158,27.338.0,22.204.0,34.143.0,25.150.0,26.139.0,43.190.0,25.162.0,46.157.0"}
P.entries["quest:92532"] = {n="The Warrior's Path",s="Rorian the Dayseeker vous envoie auprès de Blademaster Ren, à Thendal. Elle enseigne aux jeunes guerriers le combat et la discipline nécessaires pour défendre leur peuple.",h="Rorian the Dayseeker vous envoie auprès de Blademaster Ren, à Thendal.",kw={"blademaster ren","note chiffonnée","rorian the dayseeker","thendal","la voie du guerrier","tour de guet","île de zéphras"},ang={["class:Warrior"]="En tant que guerrier, vous commencez votre formation martiale à Thendal, sous la tutelle de Blademaster Ren."},sec={{t="Un appel à la tour de guet",b="Après avoir rétabli l’équilibre dans les environs, vous retournez auprès de Rorian the Dayseeker, à Thendal. La maîtresse-lame du village vous a remarqué, et Rorian vous remet une note chiffonnée rédigée par Ren elle-même. Elle vous demande de venir la voir directement.\n\nRen vous attend dans la tour de guet du village, tout en haut de la colonie. De là, elle surveille les frontières de l’île et les recrues qui les défendront peut-être un jour."},{t="Le devoir de protéger",b="Dans la tour de guet, Blademaster Ren vous apprend que le combat exige davantage que la force brute. Un guerrier doit diriger, endurer et protéger à mesure que le monde devient plus incertain. Ren s’engage à vous guider tandis que vous perfectionnez vos talents. Son entraînement rigoureux vous prépare aux périls croissants qui menacent votre foyer."}},faq={{q="Qui m’envoie trouver Blademaster Ren ?",a="Après avoir terminé votre travail à Thendal, Rorian the Dayseeker vous dirige vers Blademaster Ren. Ren a demandé à Rorian de vous envoyer à sa tour de guet à votre retour.",al={"qui donne cette quête","donneur de quête","rôle de rorian"}},{q="Où trouver Blademaster Ren ?",a="Blademaster Ren vous attend dans la tour de guet de Thendal, sur l’Île de Zéphras. Elle veille sur le village et entraîne les combattants novices.",al={"où se trouve blademaster ren","emplacement de ren","tour de guet de thendal"}},{q="Qu’est-ce que la Note chiffonnée ?",a="La Note chiffonnée est l’invitation personnelle de Blademaster Ren, transmise par Rorian. Elle vous demande de la lire et de vous rendre à la tour de guet de Thendal pour suivre un entraînement martial.",al={"note chiffonnée","que dit la note","note de ren"}},{q="Qu’enseigne Blademaster Ren aux jeunes guerriers ?",a="Blademaster Ren enseigne la vigilance, le leadership et la protection. Les guerriers doivent avoir la volonté de s’interposer entre le danger et leur peuple, alors que le monde change et que les périls se multiplient.",al={"enseignement de ren","que fait apprendre ren","but du guerrier"}},{q="Cette quête est-elle nécessaire à l’entraînement des guerriers sur l’Île de Zéphras ?",a="Cette quête vous présente Blademaster Ren, votre maître de classe à Thendal, et vous indique où revenir pour apprendre des techniques martiales.",al={"faut-il faire cette quête","présentation du maître guerrier","est-ce obligatoire"}},{q="Que veut dire Ren par « que les vents vous guident » ?",a="La bénédiction de Ren reflète la culture de l’Île de Zéphras. Elle souhaite aux voyageurs un passage sûr, de la concentration et de la chance sur des terres inconnues et dangereuses.",al={"signification de que les vents vous guident","citation sur le vent","adieux de ren"}}},fx={["2d8c1194"]={q="Pourquoi Rorian the Dayseeker m'envoie-t-il auprès du Maître lames Ren ?",a="Le Maître lames Ren a personnellement demandé à Rorian de vous diriger vers la tour de guet dès votre retour à Thendal. Avec le monde qui change et les épreuves périlleuses à venir, Ren reconnaît que les guerriers en herbe ont besoin d'instructions de combat dédiées et de conseils de leadership si votre peuple doit survivre aux dangers à venir. Rorian honore simplement la demande de Ren pour s'assurer que vous receviez la formation dont vous avez besoin.",al={"pourquoi rorian m'envoie-t-il","motif de rorian","pourquoi trouver le maître lames ren"}}},fp="18,146,27.382.0,24.302.0,37.160.0,33.138.0,26.167.0,47.165.0,60.128.0,48.140.0"}
P.entries["quest:92544"] = {n="Al'Aketh Thugs",s="Dans les ruines du temple près du Bosquet de Thendal, les sectateurs d’Al’Aketh menacent les voyageurs. Envoyés du Sanctuaire d’Akir sur ordre de la grande prêtresse Lorthuna, ils harcèlent les passants et enrôlent de force de nouvelles recrues. Hanaa Nightwind vous demande de briser leur emprise et d’abattre leur commandant.",h="Dans les ruines du temple près du Bosquet de Thendal, les sectateurs d’Al’Aketh menacent les voyageurs.",kw={"brute al’aketh","néophyte al’aketh","al'aketh thugs","hanaa nightwind","grande prêtresse lorthuna","malduko cloudcrush","sanctuaire d’akir","bosquet de thendal"},sec={{t="Des sectateurs brutaux dans les ruines",b="Juste au sud-ouest du Bosquet de Thendal, les ruines d’un ancien temple sont devenues dangereuses pour les voyageurs. Al’Aketh s’est emparé des lieux et s’en prend aux gens près du bosquet. Les Rangers postés à proximité soupçonnent la grande prêtresse Lorthuna d’avoir envoyé ces brutes du Sanctuaire d’Akir. Ils maltraitent les habitants et les forcent à se soumettre à la secte."},{t="Malduko Cloudcrush, chef brutal",b="Dans les ruines, Malduko Cloudcrush règne par la violence et la peur. Des brutes et des néophytes fraîchement endoctrinés lui obéissent, faisant du temple un avant-poste agressif aux portes du Bosquet de Thendal. Hanaa Nightwind espère qu’abattre Cloudcrush et disperser ses fidèles brisera l’assurance de la secte. Cela leur montrera que la coercition ne sera pas tolérée sur ces terres."}},faq={{q="Qui sont les Al’Aketh ?",a="Les Al’Aketh sont une secte fanatique qui sévit sur Zephras. La grande prêtresse Lorthuna les dirige depuis le Sanctuaire d’Akir. Ses fidèles intimident les voyageurs et les habitants et usent de violence pour les forcer à les rejoindre.",al={"que sont les al’aketh","secte al’aketh","qui sont les alaketh"}},{q="Pourquoi les sectateurs attaquent-ils le Bosquet de Thendal ?",a="Les sectateurs ont établi leur camp dans les ruines d’un temple au sud-ouest du Bosquet de Thendal. Ils y tendent des embuscades aux voyageurs qui quittent la région et terrorisent les gens sur la route. Ils espèrent pousser les habitants à se soumettre à la secte.",al={"pourquoi les sectateurs sont ici","pourquoi le bosquet de thendal","motivations des sectateurs"}},{q="Qui est Malduko Cloudcrush ?",a="Malduko Cloudcrush dirige le campement des Al’Aketh dans les ruines du temple. Hanaa Nightwind le qualifie de monstre. Il commande les brutes et les néophytes qui s’en prennent aux voyageurs des routes voisines.",al={"malduko","cloudcrush","qui est malduko cloudcrush"}},{q="Qui est Hanaa Nightwind ?",a="Hanaa Nightwind est une Ranger qui protège le Bosquet de Thendal. Elle reste à son poste le long de la route et avertit les voyageurs de l’embuscade toute proche. Elle compte sur des aventuriers capables pour écarter la menace.",al={"hanaa","hanaa nightwind","donneur de quête"}},{q="Qui a envoyé ces sectateurs dans les ruines ?",a="Hanaa soupçonne la grande prêtresse Lorthuna d’avoir envoyé les sectateurs du Sanctuaire d’Akir. Lorthuna y supervise les activités de la secte.",al={"qui les commande","chef de la secte","qui a envoyé malduko"}},{q="Que trouve-t-on d’autre près des ruines du temple ?",a="Une ligne tellurique active se trouve dans les ruines antiques, à l’extrémité sud-ouest de la région, près du campement des Al’Aketh.",al={"ligne tellurique des ruines","secret des ruines du temple","ruines au sud-ouest"}}},fx={b63e8692={q="Pourquoi Hanaa Nightwind veut-elle que les voyous Al'Aketh soient éliminés ?",a="Les adeptes du culte Al'Aketh ont campé dangereusement près de Bosquet de Thendal, harcelant les voyageurs le long des routes et tentant de contraindre les habitants locaux à rejoindre leur zélé troupeau. La forestière Hanaa Nightwind veut briser leur emprise sur les ruines du sud-ouest et envoyer un message sanglant et indubitable qui forcera les adeptes survivants à abandonner la zone.",al={"pourquoi tuer les voyous alaketh","motif de hanaa nightwind","pourquoi nettoyer les ruines du temple"}},b6ccde37={q="Pourquoi Hanaa Nightwind ne peut-elle pas s'occuper elle-même des adeptes ?",a="Hanaa doit rester à son poste pour surveiller et avertir les voyageurs sans méfiance quittant le Bosquet de Thendal avant qu'ils ne tombent dans l'embuscade du culte. Bien qu'il lui faille toute sa retenue pour ne pas marcher elle-même dans les ruines, elle ne peut abandonner son devoir à la lisière du bosquet.",al={"pourquoi hanaa a-t-elle besoin de moi","pourquoi hanaa ne les combat-elle pas","pourquoi moi pour les voyous alaketh"}}},fp="14,276,29.322.0,18.370.0,21.201.0,45.206.0,26.168.0,23.188.0,37.122.0,45.117.0"}
P.entries["quest:92550"] = {n="Havoc in the Highlands",s="Dans les hautes-terres, Shen’dar attaque les forces d’Al’Aketh à Falaath Village. Ses défenseurs veulent stopper l’assaut avant qu’il ne commence et protéger leur foyer.",h="Dans les hautes-terres, Shen’dar attaque les forces d’Al’Aketh à Falaath Village.",kw={"al’aketh","commandant cyclas","falaath village","havoc in the highlands","living lightning","sania silverstream","shen’dar","stormcallers"},ang={["class:Shaman"]="En tant que chaman, vous savez que les Stormcallers d’Al’Aketh et leur Living Lightning invoquée manient les éléments. Les sectateurs transforment le vent et la tempête en armes au service d’une agressivité fanatique."},sec={{t="Frappe préventive",b="Des sectateurs fanatiques se préparent à attaquer Shen’dar. Ses dirigeants vous envoient donc dans les ruines de Falaath Village pour frapper les premiers, avant que les forces d’Al’Aketh ne lancent leur assaut."},{t="Assaut sur Falaath Village",b="Les fanatiques d’Al’Aketh se rassemblent à Falaath Village et manient un pouvoir élémentaire chaotique. Vous brisez leurs rangs en vainquant les Stormcallers d’Al’Aketh et en détruisant Living Lightning. Puis vous retrouvez le commandant Cyclas et le décapitez."},{t="Sécuriser les hautes-terres",b="Le commandant Cyclas est mort, et son avant-garde est dévastée. Shen’dar gagne un répit vital. Tandis que les habitants prennent les armes, Sania Silverstream quitte la ville sans se faire remarquer. Elle fuit pendant que les défenses locales se renforcent."}},faq={{q="Qu’est-ce que Havoc in the Highlands ?",a="Shen’dar frappe les premiers les sectateurs d’Al’Aketh dans les ruines de Falaath Village. Ses défenseurs espèrent stopper l’assaut avant qu’il ne commence.",al={"quête havoc in the highlands","qu’est-ce que havoc in the highlands","quête des hautes-terres"}},{q="Qui menace Shen’dar ?",a="Les forces d’Al’Aketh menacent Shen’dar. Elles vénèrent les tempêtes élémentaires et disposent de Stormcallers, de Living Lightning asservie et de leur chef, le commandant Cyclas.",al={"qui sont les ennemis","quel est ce culte","qui attaque shen’dar"}},{q="Où les sectateurs se rassemblent-ils ?",a="Les sectateurs se rassemblent dans les ruines de Falaath Village. Le commandant Cyclas et ses fidèles d’Al’Aketh s’en servent comme base de départ.",al={"où se trouve le commandant cyclas","ruines de falaath village","où aller"}},{q="Qui est le commandant Cyclas ?",a="Le commandant Cyclas dirige les forces d’Al’Aketh rassemblées dans les ruines de Falaath Village. Elles se préparent à marcher sur Shen’dar.",al={"qui est le commandant cyclas","histoire de cyclas","culte de cyclas"}},{q="Pourquoi Sania Silverstream a-t-elle fui Shen’dar ?",a="Sania Silverstream quitte Shen’dar juste avant que ses défenseurs ne se mobilisent. Elle fuit sans doute après avoir vu les habitants prendre les armes et organiser leur défense.",al={"fuite de sania silverstream","pourquoi sania est-elle partie","qui est sania silverstream"}},{q="La frappe a-t-elle réussi à sécuriser Shen’dar ?",a="Shen’dar repousse la menace immédiate en brisant l’avant-garde des sectateurs et en décapitant le commandant Cyclas. Les fanatiques qui reviendront trouveront les hautes-terres prêtes à résister.",al={"shen’dar a-t-elle survécu","conséquences de l’attaque","shen’dar est-elle en sécurité"}}},fp="22,163,19.185.0,26.214.0,22.231.1,31.145.0,36.153.0,31.128.0,24.119.0,49.163.0,53.179.0"}
P.entries["quest:92551"] = {n="Fournitures volées",s="Les caravanes vers les Hautes-terres de Shen’dar sont attaquées, et leurs marchandises volées s’amassent à Falaath Village. Les vivres et les pierres de vent se font rares dans les colonies des hautes-terres, laissant certains enfants du ciel au bord de la famine.",h="Les caravanes vers les Hautes-terres de Shen’dar sont attaquées, et leurs marchandises volées s’amassent à...",kw={"al’aketh","caravanes","connétable","falaath village","hautes-terres de shen’dar","enfants du ciel","fournitures volées","pierres de vent"},ang={["race:Skyborne"]="Les raids brisent le lien vital entre les hautes-terres et les basses-terres. Sans livraisons régulières de vivres et de pierres de vent, les habitants des villes des enfants du ciel souffrent de la faim."},sec={{t="Les raids coupent la route des hautes-terres",b="Depuis des mois, des pillards attaquent les caravanes sur la route entre les basses-terres et les Hautes-terres de Shen’dar. Leurs chariots transportent des vivres et des pierres de vent dont dépendent les colonies des hautes-terres. Les livraisons se raréfiant, les habitants des villes peinent à survivre, et certains frôlent la famine."},{t="La cache de Falaath",b="Les Al’Aketh accusent de simples bandits d’être à l’origine des attaques. Pourtant, les fournitures disparues réapparaissent sans cesse à Falaath Village, où les Al’Aketh entreposent les sacs volés. Les marchandises récupérées sont confiées aux autorités locales et au connétable, qui les envoient directement aux enfants du ciel qui en ont le plus besoin."}},faq={{q="Quelles fournitures ont été volées aux caravanes ?",a="Les caravanes entre les basses-terres et les hautes-terres transportaient des vivres et des pierres de vent. Des livraisons régulières aident à nourrir les habitants et à leur fournir le nécessaire.",al={"ce qui a été volé","fournitures dérobées","marchandises volées"}},{q="Qui s’en prend aux caravanes ?",a="Les Al’Aketh attaquent les caravanes de ravitaillement depuis des mois. Ils accusent de simples bandits, mais les sacs volés réapparaissent sans cesse à Falaath Village.",al={"qui a volé les fournitures","qui a attaqué les caravanes","assaillants des caravanes"}},{q="Où les caches de ravitaillement volé sont-elles entreposées ?",a="Les Al’Aketh entreposent les sacs de ravitaillement volés à Falaath Village, dans les Hautes-terres de Shen’dar.",al={"où sont les fournitures","où trouver les fournitures","emplacement des caches volées"}},{q="Pourquoi ces caravanes de ravitaillement sont-elles prises pour cible ?",a="Les caravanes transportent des vivres et des pierres de vent entre les basses-terres et les hautes-terres. Les raids privent les enfants du ciel locaux de fournitures, tandis que les marchandises des hautes-terres s’amassent à Falaath Village.",al={"pourquoi voler des pierres de vent et des vivres","pourquoi attaquer les caravanes"}},{q="Que deviennent les fournitures une fois récupérées ?",a="Une fois récupérées, les fournitures sont confiées au connétable et aux autorités locales. Ils les redistribuent aux habitants qui ont le plus besoin de nourriture et d’aide.",al={"qui récupère les fournitures","redistribution des fournitures","que deviennent les fournitures récupérées"}},{q="Pourquoi les Al’Aketh accusent-ils des bandits d’être à l’origine des raids ?",a="Les Al’Aketh accusent des bandits itinérants pour détourner les soupçons. Pourtant, les cargaisons volées réapparaissent sans cesse dans leur village, à Falaath Village.",al={"pourquoi accuser les bandits","excuse des al’aketh sur les bandits"}}},fp="15,213,30.272.0,17.274.0,44.135.0,44.138.0,46.93.0,45.171.0,53.144.0,48.134.0"}
P.entries["quest:92553"] = {n="Restocking the Larders",s="Dans les Hautes-terres de Shen’dar, sur Zephras, le cuisinier du village a besoin d’aide pour remplir les réserves. Le danger empêche les villageois de chercher de quoi se nourrir. Le cuisinier fait donc appel à vous pour obtenir des œufs et de la Viande de trotteur.",h="Dans les Hautes-terres de Shen’dar, sur Zephras, le cuisinier du village a besoin d’aide pour remplir les...",kw={"cuisine","restocking the larders","hautes-terres de shen’dar","petits œufs","viande de trotteur","suif d’ursera","zephras"},ang={["profession:Cooking"]="En tant que cuisinier, ramasser de la Viande de trotteur et des petits œufs vous donne une expérience pratique et des recettes adaptées à la faune de Zephras."},sec={{t="Les dangers des hautes-terres",b="Les dangers grandissants compliquent la vie dans les Hautes-terres de Shen’dar. Les villageois ne peuvent plus s’aventurer sans risque dans la nature pour cueillir ou chasser, et les réserves communes sont presque vides. Les cuisiniers du coin comptent donc sur les voyageurs prêts à braver les sentiers sauvages pour aider à nourrir la colonie."},{t="Nourriture et réconfort",b="Le cuisinier vous demande de trouver de la Viande de trotteur et des petits œufs frais parmi la faune des hautes-terres. En échange, il partage ses connaissances du gibier local et de ses recettes. Les petits œufs frits dans du suif d’ursera apportent du réconfort, accompagnés de fleurs-de-paix séchées pour une pipe paisible."}},faq={{q="Quelles provisions faut-il pour Restocking the Larders ?",a="Le cuisinier du coin a besoin de trois Small Eggs et de huit morceaux de Viande de trotteur pour nourrir le village, car le danger retient les cueilleurs ordinaires chez eux.",al={"objectif de restocking the larders","quoi ramasser pour restocking the larders"}},{q="Où trouver les ingrédients ?",a="Les créatures sauvages des Hautes-terres de Shen’dar, sur Zephras, fournissent la Viande de trotteur et les petits œufs.",al={"où trouver de la viande de trotteur sur zephras","emplacement des œufs à shen’dar"}},{q="Pourquoi le village manque-t-il de nourriture ?",a="Les dangers grandissants rendent la chasse et la cueillette trop périlleuses pour les villageois ordinaires, et les réserves s’épuisent.",al={"pourquoi faut-il de la nourriture sur zephras","pourquoi le village a faim à shen’dar"}},{q="Quelle récompense le cuisinier offre-t-il en échange des provisions ?",a="En échange de provisions fraîches, le cuisinier propose des conseils culinaires, des techniques et un apprentissage des recettes locales.",al={"que propose le donneur de quête","quête d’apprentissage de la cuisine"}},{q="Que sont les Hautes-terres de Shen’dar et Zephras ?",a="Les Hautes-terres de Shen’dar se trouvent sur Zephras, où les habitants font face à des menaces croissantes tout en tentant de subvenir à leurs besoins quotidiens.",al={"qu’est-ce que zephras","où se trouvent les hautes-terres de shen’dar"}},{q="Comment le cuisinier prépare-t-il les œufs ?",a="Le cuisinier fait frire les petits œufs fraîchement ramassés dans du suif d’ursera, un réconfort sur Zephras.",al={"secret de cuisine au suif","comment cuire les œufs sur zephras"}}},fp="22,187,24.271.0,22.247.0,52.134.0,35.100.0,39.111.0,45.106.0,44.116.0,35.82.0"}
P.entries["quest:92579"] = {n="To Valanaar",s="Aonda envoie un rapport urgent à Valanaar, où les forces de maintien de la paix se préparent à une menace grandissante. Leur cheffe, Valennia Stormfist, doit préparer les siens à l'approche d'un conflit avec la secte.",h="Aonda envoie un rapport urgent à Valanaar, où les forces de maintien de la paix se préparent à une menace...",kw={"aonda","secte","forces de maintien de la paix","shen'dar","to valanaar","valanaar","valennia stormfist"},sec={{t="Une missive urgente",b="Après vous avoir aidé à défendre Shen'dar et son pylône, Aonda vous confie un message urgent pour Valennia Stormfist. Valanaar se trouve à l'extrémité sud-est de l'île, où les forces de maintien de la paix ont établi leur quartier général sous le commandement de Valennia. Aonda vous avertit que les jours paisibles touchent à leur fin. Valennia doit préparer les siens à un affrontement inévitable avec la secte agressive en pleine expansion."},{t="La tempête se lève",b="Les forces de maintien de la paix ont évité tout conflit direct avec la mystérieuse secte jusqu'à ce que ses incursions fassent atteindre aux tensions un point de rupture. Après avoir lu le rapport d'Aonda, Valennia sait qu'elles doivent rassembler leurs forces restantes et préparer leur défense. La secte pourrait s'en prendre à Valanaar même."}},faq={{q="Qui vous envoie à Valanaar ?",a="Aonda, une montagnarde de Shen'dar, vous envoie à Valanaar. Après que vous avez contribué à protéger le village et son pylône de la menace imminente des adeptes de la secte, elle vous confie un rapport écrit urgent à porter à l'autre bout de l'île.",al={"qui envoie à valanaar","donneur de quête to valanaar","qui m'envoie à valanaar"}},{q="Qui est Valennia Stormfist ?",a="Valennia Stormfist dirige les forces de maintien de la paix de l'île depuis leur quartier général à Valanaar. Elle est chargée de la défense locale et du maintien de l'ordre, notamment face à l'expansion agressive de la secte.",al={"qui est valennia stormfist","valennia dirigeante","valennia"}},{q="Qu'est-ce que Valanaar ?",a="Valanaar est une colonie située à l'extrémité sud-est de l'île. C'est la base des forces de maintien de la paix sous le commandement de Valennia Stormfist, ainsi qu'un refuge et un lieu de rassemblement pour les habitants.",al={"qu'est-ce que valanaar","où se trouve valanaar","emplacement de valanaar"}},{q="Quel est le but du rapport d'Aonda ?",a="Le rapport d'Aonda décrit la menace grandissante de la secte et les événements qui ont mis Shen'dar et son pylône en danger. Les forces de maintien de la paix ont évité tout conflit direct, mais l'expansion rapide de la secte rend l'affrontement inévitable. Valanaar doit préparer ses défenses.",al={"pourquoi livrer le rapport","quel est le rapport d'aonda","que contient la lettre"}},{q="Quelle menace la secte fait-elle peser sur l'île ?",a="Le rapport avertit qu'une secte inconnue s'étend rapidement sur l'île. Les forces de maintien de la paix ont gardé leurs distances pour éviter une guerre ouverte, mais les récentes actions agressives de la secte contre des lieux comme Shen'dar rendent désormais le conflit inévitable.",al={"quelle secte menace valanaar","qui est la secte","menace de la secte sur l'île"}},{q="Que se passe-t-il une fois arrivé à Valanaar ?",a="À la réception de cette sombre nouvelle, Valennia doit consulter les forces de maintien de la paix qui lui restent et préparer la défense contre de futures attaques de la secte. Tandis qu'elle coordonne leurs plans, elle invite les voyageurs à aider les habitants de Valanaar.",al={"que faire après avoir livré le rapport","que faire ensuite à valanaar"}}},fp="11,206,18.368.0,19.279.1,26.207.0,26.191.0,17.167.0,38.241.0,45.248.0,37.226.0"}
P.entries["quest:92595"] = {n="The Windshapers",s="Parmi les esprits du vent, les Sculpte-vents cherchent un moyen de sauver Zephras et les Shen'dorei. Illaya Amberwind accueille de nouvelles recrues tandis que les dangers se rassemblent à Mur-Céleste.",h="Parmi les esprits du vent, les Sculpte-vents cherchent un moyen de sauver Zephras et les Shen'dorei.",kw={"al’aketh","illaya amberwind","shen'dorei","vision céleste","mur-céleste","sculpte-vents","zephras"},ang={["class:Shaman"]="En tant que chaman, vous pouvez communier avec les éléments grâce à votre formation, mais d'autres personnes peuvent aussi posséder la vision céleste. Les Sculpte-vents partagent ce devoir spirituel avec les invocateurs élémentaires.",["race:Skyborne"]="En tant que membre des Skyborne, vous savez que les Sculpte-vents luttent pour la survie des Shen'dorei et la préservation de leur foyer, malgré les périls de Mur-Céleste et de Zephras."},sec={{t="Mandat des Sculpte-vents",b="Illaya Amberwind accueille de nouvelles recrues dans les rangs des Sculpte-vents, qui communient avec les esprits du vent et protègent les Shen'dorei. L'ordre recherche les personnes dotées d'une perception spirituelle innée. Il espère réparer la fracture grandissante entre son peuple et les forces élémentaires qui soutiennent son royaume aérien. Chaque Sculpte-vent porte ce fardeau."},{t="Épreuves sur Zephras",b="Les Al’Aketh sèment le trouble à Mur-Céleste, et le plan élémentaire recèle ses propres dangers. Les Sculpte-vents pensent que Zephras ne pourra résister et que les Shen'dorei ne pourront affronter la tempête que s'ils renouent avec les esprits des vents."}},faq={{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents communient avec les esprits du vent et protègent les Shen'dorei. Guidés par Illaya Amberwind, ils recherchent les personnes douées de vision céleste pour renouer avec les esprits et préserver leur patrie menacée.",al={"qui sont les sculpte-vents","faction des sculpte-vents","que font les sculpte-vents"}},{q="Qu'est-ce que la vision céleste ?",a="La vision céleste est une sensibilité spirituelle innée qui permet de se relier aux éléments aériens. Une formation chamanique officielle n'est pas nécessaire, mais maîtriser cette vision est essentiel pour atteindre les esprits des vents.",al={"qu'est-ce que la vision céleste","histoire de la vision céleste"}},{q="Qui est Illaya Amberwind ?",a="Illaya Amberwind guide les Sculpte-vents et reconnaît les dons spirituels chez les voyageurs. Elle accueille les personnes douées de vision céleste et leur explique la mission de l'ordre, le péril qui menace Zephras et les épreuves auxquelles les Shen'dorei font face.",al={"qui est illaya","illaya amberwind"}},{q="Qu'est-ce que Zephras ?",a="Zephras est une terre ou une colonie aérienne qui endure de grandes difficultés et des troubles internes. Les Sculpte-vents luttent pour la protéger et y préserver un avenir pour leur peuple.",al={"qu'est-ce que zephras","histoire de zephras"}},{q="Qui sont les Al’Aketh ?",a="Les Al’Aketh sont une faction hostile au sein de Mur-Céleste, qui trouble les Sculpte-vents et les Shen'dorei. Leur menace s'ajoute aux dangers qui pèsent sur ceux qui tentent de survivre à Mur-Céleste.",al={"qui sont les al’aketh","menace des al’aketh"}},{q="Qui sont les Shen'dorei ?",a="Les Shen'dorei sont le peuple que les Sculpte-vents cherchent à protéger. Les Al’Aketh et les conditions périlleuses à Mur-Céleste menacent leur survie. Les Sculpte-vents veulent donc assurer leur avenir en rétablissant l'équilibre avec les vents.",al={"qui sont les shen'dorei","histoire des shen'dorei"}}},fp="15,176,26.326.0,17.239.0,24.217.0,17.209.0,24.217.0,16.171.0,21.150.0,23.209.0"}
P.entries["quest:92596"] = {n="The High Order",s="Sur Zephras, Rathiril Sunlance explique aux nouveaux venus pourquoi les shen'dorei doivent désormais se débrouiller seuls. Leurs bienfaiteurs élémentaires ont disparu : ces descendants des Bien-nés d'Eldre'Thalas se tournent donc vers la magie des arcanes ancestrale pour protéger leur peuple.",h="Sur Zephras, Rathiril Sunlance explique aux nouveaux venus pourquoi les shen'dorei doivent désormais se...",kw={"al’aketh","arcanes","eldre'thalas","bien-nés","rathiril sunlance","shen'dorei","l'ordre suprême","zephras"},ang={["class:Mage"]="Rathiril affirme que même les aventuriers sans formation officielle de mage possèdent de puissantes auras arcaniques. Leur magie commune est un héritage inné, et non une discipline acquise.",["race:Skyborne"]="En tant que Skyborne, vous descendez des anciens Bien-nés d'Eldre'Thalas. Vous devez maîtriser vos dons arcaniques pour vous débrouiller seuls, maintenant que vos protecteurs élémentaires ont disparu."},sec={{t="Un peuple livré à lui-même",b="Les shen'dorei de Zephras s'efforcent de retrouver leur force et de choisir leur propre voie. Pendant longtemps, des bienfaiteurs élémentaires les ont protégés. Ces protecteurs ont désormais disparu, laissant le peuple exposé aux conflits internes et aux dangers qui l'entourent. Rathiril Sunlance recherche ceux qui sont doués pour la magie des arcanes afin de préserver leur peuple et de renforcer leurs propres forces."},{t="L'héritage d'Eldre'Thalas",b="Les shen'dorei portent l'héritage d'Eldre'Thalas et une source innée d'énergie arcanique. Même ceux qui n'ont jamais reçu de formation officielle en sorcellerie partagent ce pouvoir. L'Ordre suprême considère qu'il est du destin des descendants des Bien-nés de manier ces dons ancestraux. Grâce à eux, les shen'dorei espèrent résister à Al’Aketh, qui les menace de l'intérieur, et faire face aux nombreuses menaces qui pèsent sur leur foyer de Zephras."}},faq={{q="Qu'est-ce que l'Ordre suprême ?",a="Parmi les shen'dorei de Zephras, l'Ordre suprême œuvre à la survie de leur peuple. Fondé par des descendants des Bien-nés d'Eldre'Thalas, il cherche à manier leurs dons arcaniques ancestraux pour que leur société puisse se défendre et perdurer par ses propres moyens.",al={"qui sont les membres de l'ordre suprême","qu'est-ce que l'ordre suprême","but de l'ordre suprême"}},{q="Qui est Rathiril Sunlance ?",a="Rathiril Sunlance est un elfe lié à l'Ordre suprême, sur Zephras. Il enseigne aux nouveaux venus les énergies arcaniques locales, le sort des shen'dorei et leur détermination à survivre sans leurs anciens protecteurs élémentaires.",al={"qui est rathiril","histoire de rathiril sunlance","sunlance"}},{q="Qu'est-ce que Zephras ?",a="Zephras est une île flottante de Mur-Céleste où vivent désormais Rathiril Sunlance et les siens. L'île regorge d'énergies arcaniques, et les shen'dorei font face aux dangers qui menacent leur peuple ainsi qu'à l'incertitude quant à leur sécurité face aux menaces extérieures.",al={"où se trouve l'ordre suprême","qu'est-ce que zephras","histoire de zephras"}},{q="Qui sont les shen'dorei ?",a="Les shen'dorei sont des elfes descendants des Bien-nés d'Eldre'Thalas. Désormais installés sur Zephras, ils possèdent un lien inné avec la magie des arcanes et cherchent à se débrouiller seuls.",al={"qui sont les shen'dorei","shen'dorei","histoire des shen'dorei"}},{q="Qui étaient les bienfaiteurs élémentaires ?",a="Les bienfaiteurs élémentaires étaient de puissants êtres élémentaires qui aidaient et protégeaient autrefois les shen'dorei. Ils ont disparu : le peuple de Zephras doit donc compter sur sa propre magie et sa débrouillardise.",al={"qui sont les élémentaires","protecteurs élémentaires","bienfaiteurs élémentaires"}},{q="Que sont les Al’Aketh ?",a="Les Al’Aketh sont une faction interne ou une menace qui met en danger les shen'dorei de Zephras. L'Ordre suprême organise des défenses, en partie pour faire face à ces menaces internes.",al={"que sont les al’aketh","menace des al’aketh","menaces internes à zephras"}},{q="Quel est le lien entre l'Ordre suprême et Eldre'Thalas ?",a="Les ancêtres des shen'dorei venaient d'Eldre'Thalas, l'antique cité des Bien-nés située en Kalimdor, connue de beaucoup sous le nom de Hache-tripes dans les années qui suivirent la Troisième guerre. L'Ordre suprême honore cet héritage en préservant leurs dons arcaniques ancestraux et en les maniant.",al={"lien avec eldre'thalas","viennent-ils de hache-tripes","origines des bien-nés"}}},fp="14,225,21.364.0,22.360.0,23.242.0,25.214.0,16.225.0,23.168.0,35.191.0,22.164.0,63.241.0"}
P.entries["quest:92597"] = {n="Reading the Ley Lines",s="Sur l’Île de Zéphras, les jeunes Skyborne cherchent les courants arcaniques sous leurs pieds. Falorne Fallwind les envoie au Bosquet de Thendal pour sentir la puissance qui monte à travers le plan élémentaire.",h="Sur l’Île de Zéphras, les jeunes Skyborne cherchent les courants arcaniques sous leurs pieds.",kw={"al’aketh","falorne fallwind","bien-nés","lignes telluriques","reading the ley lines","skyborne","bosquet de thendal","pierres dressées de thendal","sculpte-vents","île de zéphras"},ang={["class:Mage"]="En tant que Mage, vous pouvez puiser dans les lignes telluriques exposées comme dans une réserve de puissance brute au milieu des tempêtes élémentaires.",["race:Skyborne"]="En tant que Skyborne, vous éveillez votre ascendance innée de Bien-né et apprenez à canaliser l’énergie tellurique souterraine dans vos sorts."},sec={{t="Courants arcaniques du plan élémentaire",b="Des lignes telluriques courent sous l’Île de Zéphras, jusque dans le plan élémentaire. D’étranges élémentaires et les hostiles Al’Aketh traversent l’île tandis que ces courants enfouis remontent vers la surface. Pour ceux qui ont le lignage et le savoir nécessaires pour les canaliser, ces lignes exposées ouvrent la voie à une puissance arcanique brute."},{t="Héritage des Bien-nés",b="Falorne Fallwind exhorte les initiés à revendiquer leur ascendance de Bien-né plutôt qu’à rechercher la faveur des esprits du vent. Les Sculpte-vents locaux et les Al’Aketh se tournent tous deux vers ces esprits. Selon Fallwind, survivre aux rudes puissances du plan élémentaire dépend de la maîtrise de la force arcanique sous leurs pieds, et non de supplications adressées à des créatures étrangères pour obtenir leur pitié."},{t="Pierres dressées de Thendal",b="Au nord-est de la colonie, les anciennes pierres dressées du Bosquet de Thendal marquent une puissante convergence de lignes telluriques. Des vents tourbillonnants et des convertis d’Al’Aketh encerclent ce lieu exposé. Là, les initiés peuvent accorder leurs sens au pouls de la ligne tellurique et libérer tout le potentiel de leurs capacités raciales naturelles."}},faq={{q="Qui donne la quête Reading the Ley Lines ?",a="Sur l’Île de Zéphras, Falorne Fallwind confie ce rite aux jeunes Skyborne qui apprennent à canaliser leur puissance arcanique ancestrale.",al={"donneur de quête","falorne fallwind","qui donne reading the ley lines"}},{q="Où se trouve la ligne tellurique ?",a="La ligne tellurique se trouve au nord-est de la colonie, aux Pierres dressées de Thendal, dans le Bosquet de Thendal, au milieu d’élémentaires hostiles et de convertis d’Al’Aketh.",al={"emplacement de la ligne tellurique","où se trouve le bosquet de thendal","emplacement des pierres dressées de thendal"}},{q="Pourquoi y a-t-il des lignes telluriques dans le plan élémentaire ?",a="Des conduits arcaniques courent sous terre, même dans le plan élémentaire. Les lignes telluriques ont commencé à percer la surface, donnant aux Skyborne un accès direct à de puissants courants.",al={"arcanes dans le plan élémentaire","lore des lignes telluriques du plan élémentaire"}},{q="Que pense Falorne Fallwind des Sculpte-vents ?",a="Falorne méprise la révérence des Sculpte-vents envers les esprits de l’air. Il y voit une supplication pitoyable adressée à des êtres élémentaires indifférents, qui ne vaut pas mieux que le culte des Al’Aketh.",al={"falorne et les sculpte-vents","lore des sculpte-vents","sculpte-vents et bien-nés"}},{q="Quelle capacité faut-il pour canaliser la ligne tellurique ?",a="Vous utilisez la capacité raciale des Skyborne Read Ley Line en vous tenant au point de convergence énergétique près des pierres dressées.",al={"capacité read ley line","comment lire une ligne tellurique","capacité raciale utilisée"}},{q="Quel avantage procure l’accès aux lignes telluriques ?",a="Accéder à une ligne tellurique exposée canalise une énergie arcanique brute dans son utilisateur et accroît ses talents magiques. Ses effets varient selon la nature du conduit.",al={"à quoi servent les lignes telluriques","avantages des lignes telluriques"}}},fx={e5a629f0={q="Pourquoi Falorne Fallwind veut-il que vous lisiez les lignes telluriques ?",a="Falorne croit que réclamer votre héritage Bien-né et puiser directement dans les lignes telluriques arcaniques est le seul chemin vers le salut de votre peuple dans le plan élémentaire. Il considère des groupes comme les Sculpte-vents et les Al'Aketh avec mépris pour s'être avilis devant des entités élémentaires indifférentes. À ses yeux, la survie exige de maîtriser la magie latente plutôt que de compter sur des esprits capricieux.",al={"motif de falorne fallwind","pourquoi lire les lignes telluriques","falorne fallwind lignes telluriques pourquoi"}}},fp="21,171,38.291.0,16.349.0,23.302.0,42.118.0,30.142.0,49.174.0,47.161.0,49.114.0,49.147.0"}
P.entries["quest:92598"] = {n="The Gift of Skysight",s="Sur l’Île de Zéphras, Ventaari Brightwish guide les jeunes Sculpte-vents vers la vue céleste. Lors d’une convergence élémentaire, ils éveillent leur perception et écoutent les esprits.",h="Sur l’Île de Zéphras, Ventaari Brightwish guide les jeunes Sculpte-vents vers la vue céleste.",kw={"convergence élémentaire","esprits élémentaires","vue céleste","pierres dressées","bosquet de thendal","ventaari brightwish","sculpte-vent","zéphras"},ang={["class:Shaman"]="En tant que chaman, vous savez qu’une convergence élémentaire est un lieu sacré, où la frontière entre la volonté des mortels et les plans élémentaires s’amincit.",["faction:Horde"]="En tant que membre de la Horde, vous comptez sur la clairvoyance des Sculpte-vents pour affronter les dangers inconnus de l’Île de Zéphras.",["race:Skyborne"]="En tant que Skyborne, vous héritez de la vue céleste de vos patrons élémentaires. Elle ancre votre identité culturelle et spirituelle."},sec={{t="Une perception sacrée",b="Les Sculpte-vents naissent liés aux forces élémentaires qui façonnent leur monde. Ils nomment vue céleste cette faculté sacrée. Ce don accorde les sens des mortels au royaume spirituel et franchit le fossé entre les vivants et l’invisible. Dans les terres sauvages, un Sculpte-vent peut faire appel à cette vision intérieure. Près d’une puissance concentrée, le lien se renforce et apporte des bienfaits ainsi que la sagesse murmurée par les esprits."},{t="La convergence du Bosquet de Thendal",b="Au nord-est de la colonie, d’anciennes pierres dressées marquent une convergence élémentaire dans le Bosquet de Thendal. Les énergies brutes s’amassent en ces lieux, où les esprits s’attardent. Ventaari Brightwish y envoie les novices pour éprouver leur force spirituelle. La vue céleste s’affine avec la pratique, comme une faculté du corps ou de l’esprit. Les Sculpte-vents doivent apprendre à lire les présages changeants des éléments, car la survie de leur peuple en dépend."}},faq={{q="Quel est le but de cette quête ?",a="Ventaari Brightwish envoie les novices Sculpte-vents auprès d’une convergence élémentaire, où sa puissance aiguise leur vue céleste.",al={"but du don de vue céleste","pourquoi faire cette quête","apprentissage de la vue céleste"}},{q="Qui est Ventaari Brightwish ?",a="Ventaari Brightwish guide et conseille les jeunes Sculpte-vents sur l’Île de Zéphras, et leur apprend à honorer et à cultiver leur héritage élémentaire.",al={"ventaari","qui est ventaari brightwish","brightwish"}},{q="Qu’est-ce qu’une convergence élémentaire ?",a="Une convergence élémentaire rassemble l’énergie spirituelle, souvent autour d’anciennes pierres dressées. Les esprits élémentaires s’y attardent et des pouvoirs comme la vue céleste s’y renforcent.",al={"qu’est-ce qu’une convergence élémentaire","histoire des convergences élémentaires","convergence du bosquet de thendal"}},{q="Où se trouve la convergence élémentaire ?",a="La convergence élémentaire se trouve parmi les pierres dressées du Bosquet de Thendal, au nord-est de la colonie sur l’Île de Zéphras.",al={"où se trouve la convergence","emplacement du bosquet de thendal","emplacement des pierres dressées"}},{q="Peut-on faire appel à la vue céleste partout ?",a="Un Sculpte-vent peut faire appel à la vue céleste partout. Dans une convergence élémentaire, son pouvoir s’approfondit et les esprits proches peuvent offrir d’autres éclairages.",al={"peut-on utiliser la vue céleste partout","vue céleste hors d’une convergence","où utiliser la vue céleste"}},{q="Pourquoi la vue céleste est-elle essentielle à la survie ?",a="La vue céleste permet aux mortels de percevoir les esprits élémentaires et de prêter attention aux avertissements des éléments. Selon Ventaari, cette vision est vitale pour affronter les dangers et préserver leur peuple.",al={"pourquoi la vue céleste est importante","survie grâce à la vue céleste","survie et éléments"}}},fx={d2ee972c={q="Pourquoi Ventaari Brightwish veut-elle que vous utilisiez la Skysight à la convergence ?",a="Ventaari Brightwish cherche à vous former dans votre héritage inné de Sculpte-vents. Comme un muscle, la Skysight doit être exercée dans des lieux de pouvoir tels que la Convergence élémentaire afin que vous puissiez apprendre à combler la distance entre les royaumes mortels et spirituels. Elle croit que communier avec les esprits et écouter ce que les éléments disent à votre peuple est crucial pour votre survie même.",al={"pourquoi ventaari veut-elle cela","motif de ventaari brightwish","pourquoi utiliser la skysight ici"}}},fp="20,163,19.399.0,32.398.0,34.114.0,27.131.0,33.163.0,43.119.0,30.136.0,50.163.0"}
P.entries["quest:926"] = {n="Pierre de puissance imparfaite",s="Dans les Tarides, des pierres imparfaites chargées d’énergie arcanique reposent sur des tables rituelles. Leurs créateurs les ont laissées instables, et elles consument leur puissance peu après avoir été déplacées.",h="Dans les Tarides, des pierres imparfaites chargées d’énergie arcanique reposent sur des tables rituelles.",kw={"arcanique","tarides","pierre de puissance imparfaite","pierres de puissance","table rituelle","magie instable"},ang={["faction:Horde"]="En tant que membre de la Horde, vous surveillez les curiosités arcaniques disséminées dans les Tarides. La sorcellerie des Voleurs pourrait menacer vos routes d’approvisionnement."},sec={{t="Une fabrication instable",b="Dans les Tarides, les pierres de puissance imparfaites renferment de l’essence arcanique dans des structures fragilisées. Leurs créateurs les ont laissées instables, si bien qu’elles se dégradent en matière inerte quelques instants après avoir été manipulées."},{t="Une énergie qui se consume",b="Une pierre commence à consumer sa puissance dès qu’elle quitte la table rituelle où elle repose. Son énergie se dissipe trop vite pour que quiconque puisse la transporter bien loin."}},faq={{q="Qu’est-ce qu’une Pierre de puissance imparfaite ?",a="La pierre renferme une puissance magique brute, mais ses défauts délibérés la poussent à se consumer rapidement dès qu’elle est déplacée.",al={"pierre de puissance imparfaite","qu’est-ce que cette pierre","histoire de la pierre de puissance"}},{q="Peut-on conserver les pierres indéfiniment ?",a="Non. Dès qu’elles sont séparées des tables qui les stabilisent, leurs matrices magiques s’effondrent et leur énergie s’épuise rapidement.",al={"garder la pierre imparfaite","peut-on la stocker","conserver la pierre"}},{q="Qui utilise ces pierres ?",a="L’orc Ak'Zeloth prépare les pierres, et les aventuriers de la Horde les transportent jusqu’à l’autel du feu, au pic de Brume-funeste. Là, ils perturbent le lien entre The Demon Seed et la Légion ardente.",al={"qui a créé les pierres de puissance","qui les a façonnées","créateurs des pierres"}},{q="Pourquoi la Horde s’y intéresse-t-elle ?",a="La Horde utilise ces pierres contre la Légion ardente. Ak'Zeloth les a préparées pour Neeru Fireblade ; en transporter une jusqu’à l’autel du feu, au pic de Brume-funeste, peut briser le lien entre The Demon Seed et la Légion.",al={"intérêt de la horde","pourquoi la horde la veut-elle"}}},fp="18,171,22.187.0,21.150.0,29.102.0,40.128.0,22.182.0,35.206.0"}
P.entries["quest:9260"] = {n="Enquêter au sujet du Fléau à Hurlevent",s="Le lieutenant Orrin appelle les défenseurs de Hurlevent à repousser les forces du Fléau qui menacent la ville. Des nécropoles se dressent au-delà des remparts. Il leur demande de réunir des pierres nécrotiques et d’étudier les runes autour des camps ennemis.",h="Le lieutenant Orrin appelle les défenseurs de Hurlevent à repousser les forces du Fléau qui menacent la ville.",kw={"aube d'argent","invasion","roi-liche","lieutenant orrin","nécropole","pierres nécrotiques","cercles runiques","fléau","hurlevent"},ang={["class:Paladin"]="En tant que paladin, vous affrontez le Fléau aux abords de Hurlevent. Vous pouvez déchaîner votre courroux sacré contre ses runes et protéger les habitants du royaume.",["class:Priest"]="En tant que prêtre, vous pouvez étudier les murmures tortueux des runes et découvrir la magie de l’Ombre qui lie les forces de première ligne du Fléau.",["faction:Alliance"]="Pour l’Alliance, défendre les portes de Hurlevent est une question de survie. Le Fléau a atteint jusqu’à ce bastion du sud."},sec={{t="Des morts-vivants aux portes de la capitale",b="Les forces du Fléau ont atteint les abords de Hurlevent. Des nécropoles flottent dans le ciel tandis que des morts-vivants et des sectateurs s’installent près du plus grand bastion du royaume. Le lieutenant Orrin rassemble des défenseurs à l’extérieur de la ville pour les repousser avant qu’ils ne menacent la capitale."},{t="Les runes murmurantes",b="Des runes lumineuses marquent la terre autour des camps du Fléau, mais leur fonction reste incertaine. Les cercles crépitent d’une magie semblable à celle des nécropoles et portent d’étranges murmures. Le lieutenant Orrin ne peut que supposer qui entend ces voix surnaturelles, si quelqu’un les entend."}},faq={{q="Qui est le lieutenant Orrin ?",a="Le lieutenant Orrin est un officier qui coordonne les défenses de Hurlevent. Il travaille avec l’Aube d’argent et organise les combattants locaux pour recueillir des renseignements et démanteler les positions du Fléau près de la ville.",al={"orrin","lieutenant orrin","qui donne cette quête"}},{q="Pourquoi le Fléau attaque-t-il Hurlevent ?",a="Le Roi-liche a envoyé des nécropoles et des forces d’invasion à travers Azeroth pour semer la terreur et grossir les rangs des morts-vivants. Hurlevent est un bastion majeur des vivants, le Fléau en a donc fait une cible.",al={"pourquoi le fléau est ici","invasion du fléau à hurlevent","pourquoi attaquer hurlevent"}},{q="Que sont les cercles runiques lumineux ?",a="Le Fléau a placé des cercles runiques lumineux près de ses camps. Ils palpitent d’une magie ténébreuse et portent des murmures surnaturels, mais leur fonction reste inconnue.",al={"cercles runiques","runes lumineuses","à quoi servent les cercles"}},{q="Que sont les pierres nécrotiques ternes ?",a="Les pierres nécrotiques ternes sont des objets magiques que transportent les soldats subalternes du Fléau. Elles renferment une énergie nécrotique persistante et intéressent l’Aube d’argent.",al={"pierre nécrotique pâle","pierres nécrotiques","que sont les pierres nécrotiques"}},{q="Quel est le rôle de l’Aube d’argent dans cette mission ?",a="L’Aube d’argent est un ordre indépendant qui combat le Fléau où qu’il apparaisse. Le lieutenant Orrin travaille avec l’ordre pour obtenir des renseignements et des pierres utiles à sa guerre contre les armées du Roi-liche.",al={"aube d'argent","lien avec l’aube d’argent"}},{q="Est-il dangereux de s’approcher des cercles runiques ?",a="Les cercles dégagent une énergie inquiétante et des murmures discordants. Des éclaireurs prudents peuvent s’en approcher et découvrir comment le Fléau communique sans perdre la raison.",al={"les runes sont-elles sans danger","murmures dans les runes"}}},fx={c2a78be7={q="Pourquoi le Lieutenant Orrin veut-il que cela fasse l'objet d'une enquête ?",a="Le roi Liche a déchaîné ses forces mort-vivantes juste devant les portes de Hurlevent sous une sinistre nécropole flottante. Le Lieutenant Orrin sait que la cité ne peut se permettre de rester les bras croisés pendant que les envahisseurs s'amassent devant sa porte. Il a besoin d'urgence de comprendre l'étrange magie derrière leurs cercles runiques luisants et d'éclaircir leurs rangs avant que les morts-vivants n'établissent un pied-à-terre permanent juste devant les murs du royaume.",al={"pourquoi orrin veut-il cela","motif du lieutenant orrin","pourquoi enquêter sur le fléau"}},["9cb0511c"]={q="Contre qui êtes-vous envoyé en dehors de Hurlevent ?",a="Vous combattez les forces d'invasion du Fléau rassemblées sous la nécropole juste à l'extérieur de la cité. Ces troupes de choc mort-vivantes et ces aberrations ont établi un campement aux portes de Hurlevent pour semer le chaos et menacer le royaume au nom du roi Liche.",al={"qui est-ce que je combats","qui sont les ennemis en dehors de hurlevent","quel fléau est à l'extérieur"}}},fp="36,219,33.265.0,20.249.0,24.195.0,39.206.0,35.155.0,29.139.0,52.202.0,44.164.0"}
P.entries["quest:9261"] = {n="Enquêter au sujet du Fléau à Forgefer",s="Le Fléau presse les portes de Forgefer, et le lieutenant Nevell appelle des renforts. Des troupes de morts-vivants se rassemblent sous une nécropole en lévitation, tandis que des cercles runiques lumineux marquent leurs campements.",h="Le Fléau presse les portes de Forgefer, et le lieutenant Nevell appelle des renforts.",kw={"aube d'argent","pierre nécrotique pâle","dun morogh","enquêter au sujet du fléau à forgefer","forgefer","roi-liche","lieutenant nevell","nécropole","cercle runique","fléau"},ang={["class:Paladin"]="En tant que paladin, vous vous opposez au Fléau, ennemi de la Lumière sacrée. Vous êtes appelé à enquêter sur la malveillance runique du roi-liche et à purger ses serviteurs écervelés.",["class:Priest"]="En tant que prêtre, vous savez que les murmures des cercles runiques pourraient menacer la raison des soldats ordinaires. Leur résister demande une grande force spirituelle.",["faction:Alliance"]="En tant que soldat de l’Alliance, vous savez que Forgefer est un pilier essentiel du commerce et de la guerre. Une tête de pont des morts-vivants à ses portes menace les voies d’approvisionnement dans les Royaumes de l’est.",["race:Dwarf"]="En tant que nain, vous savez que la souillure qui s’étend sur les neiges immaculées de Dun Morogh est intolérable. L’entrée de la montagne est le seuil de votre foyer."},sec={{t="La mort aux portes de la montagne",b="Le lieutenant Nevell et l’Aube d’argent observent les morts-vivants à l’entrée montagneuse de Forgefer. Des nécropoles flottent au-dessus des hauteurs glaciales de Dun Morogh, loin de Lordaeron et des Plagued Lands du nord. Ils comptent arrêter le Fléau avant qu’il n’atteigne la forteresse des Barbe-de-Bronze."},{t="Inscriptions impies",b="Des campements de morts-vivants s’étendent sous la nécropole. Des cercles runiques lumineux et des pierres nécrotiques palpitantes marquent le sol, et les éclaireurs proches des cercles entendent de sombres voix dans la magie environnante. Le lieutenant Nevell pense que les cercles transmettent des messages, mais il ignore à qui le Fléau s’adresse."}},faq={{q="Qui est le lieutenant Nevell ?",a="Le lieutenant Nevell est un officier de l’Aube d’argent posté à Forgefer pour coordonner sa défense contre le Fléau. Il demande aux défenseurs de récupérer des pierres nécrotiques et de découvrir le rôle des sigils impies autour des campements des envahisseurs.",al={"nevell","lieutenant nevell","donneur de quête"}},{q="Pourquoi le Fléau attaque-t-il Forgefer ?",a="Des forces du Fléau campent sous une nécropole, aux abords de Forgefer. Le lieutenant Nevell demande aux défenseurs d’en réduire les rangs et d’enquêter sur les étranges cercles runiques alentour.",al={"fléau aux abords de forgefer","pourquoi des morts-vivants à dun morogh","invasion de forgefer"}},{q="Que sont les pierres nécrotiques ternes ?",a="Les pierres nécrotiques ternes sont récupérées sur les envahisseurs du Fléau et rapportées à l’Aube d’argent pour prouver que des morts-vivants ont été tués.",al={"pierres nécrotiques","pierre nécrotique pâle","pierres du fléau"}},{q="À quoi servent les cercles runiques lumineux ?",a="Des cercles runiques lumineux apparaissent près des forces du Fléau. Le lieutenant Nevell vous demande d’en découvrir le rôle.",al={"cercles runiques","cercles lumineux","que sont les runes"}}},fx={["4916b51d"]={q="Pourquoi le Lieutenant Nevell veut-il que cela fasse l'objet d'une enquête ?",a="Avec le Fléau marchant sur le seuil de Forgefer et une nécropole se profilant au-dessus, le Lieutenant Nevell et l'Aube d'argent refusent de rester inactifs. D'étranges cercles runiques brillant d'une magie impie sont apparus près des campements mort-vivants à l'extérieur des portes. Nevell sait que ces rituels ont une sombre importance, et il a besoin que vous découvriez quelles forces sinistres les envahisseurs canalisent avant que la cité ne soit confrontée à une catastrophe encore plus grande.",al={"motif de nevell","pourquoi enquêter sur le fléau à forgefer","pourquoi nevell veut-il que cela soit fait"}},f222933f={q="Contre qui êtes-vous envoyé pour combattre à l'extérieur de Forgefer ?",a="Vous êtes envoyé contre l'avant-garde du Fléau campée juste devant les portes de Forgefer. Déployés sous le commandement du roi Liche et soutenus par une nécropole flottante, ces horreurs mort-vivantes cherchent à terroriser Dun Morogh et à assiéger le royaume nain.",al={"qui combattre","cibles du fléau forgefer","qui est-ce que je combats"}}},fp="36,188,27.275.0,19.288.1,25.231.0,39.162.0,29.120.0,49.110.0"}
P.entries["quest:9262"] = {n="Enquêter au sujet du Fléau à Darnassus",s="À Darnassus, le Lieutenant Beitha appelle à l’aide alors que les campements du Fléau se rapprochent. L’Aube d’argent a besoin de défenseurs pour frapper les morts-vivants et découvrir l’utilité des runes devant les portes.",h="À Darnassus, le Lieutenant Beitha appelle à l’aide alors que les campements du Fléau se rapprochent.",kw={"aube d'argent","beitha","darnassus","lich king","nécropole","pierre nécrotique","cercle runique","fléau","teldrassil","mort-vivant"},ang={["class:Druid"]="En tant que druide, vous voyez la nécromancie et la chair en décomposition sur Teldrassil comme un fléau que vous avez juré d’éradiquer.",["class:Priest"]="En tant que prêtre, vous faites face à des runes nécromantiques corrompues et aux murmures qui circulent dans le réseau ténébreux du Fléau.",["faction:Alliance"]="En tant que membre de l’Alliance, vous participez à la défense de Darnassus contre la force d’invasion du Lich King.",["race:NightElf"]="En tant que Kaldorei, vous voyez les nécropoles et les morts-vivants près du sol sacré de Teldrassil comme une profanation à purger."},sec={{t="Une peste sur l’Arbre-monde",b="Le Fléau a atteint Teldrassil. Des nécropoles flottantes surplombent les camps d’invasion près de Darnassus, d’où déferlent goules, squelettes et autres horreurs mortes-vivantes. Le Lieutenant Beitha de l’Aube d’argent coordonne la défense de la ville. Elle appelle les volontaires à ralentir l’attaque et à recueillir des renseignements avant que les morts-vivants ne submergent la terre natale des elfes de la nuit."},{t="Murmures dans les runes",b="Près des camps du Fléau, le Lieutenant Beitha demande aux défenseurs de récupérer des pierres nécrotiques pâles sur les membres du Fléau tombés au combat et d’examiner les cercles runiques lumineux au sol. Leurs murmures parviennent à quiconque s’en approche. Les cercles transmettent des messages, mais Beitha ignore avec qui le Fléau communique."}},faq={{q="Qui est le Lieutenant Beitha ?",a="Le Lieutenant Beitha est une officière de l’Aube d’argent en poste à Darnassus. Elle organise la résistance au Fléau et demande aux défenseurs d’en réduire les effectifs et d’étudier ses dispositifs nécromantiques.",al={"qui donne la quête enquêter au sujet du fléau à darnassus","donneur de quête beitha","histoire du lieutenant beitha"}},{q="Pourquoi le Fléau attaque-t-il Darnassus ?",a="Les forces du Fléau campent devant Darnassus, sous une nécropole. Le Lieutenant Beitha demande aux défenseurs d’en réduire les effectifs et d’enquêter sur les cercles runiques alentour.",al={"pourquoi des morts-vivants à darnassus","invasion de teldrassil","le lich king attaque les elfes de la nuit"}},{q="Que sont les cercles runiques lumineux devant la ville ?",a="Les cercles runiques lumineux se trouvent près des forces du Fléau. Le Lieutenant Beitha vous demande d’en découvrir l’utilité.",al={"runes du fléau à darnassus","cercles runiques devant darnassus","que sont les runes d’invasion"}},{q="Que sont les pierres nécrotiques pâles ?",a="Les pierres nécrotiques pâles proviennent des envahisseurs du Fléau. Les défenseurs les remettent à l’Aube d’argent comme preuve que des morts-vivants ont été tués.",al={"pierres nécrotiques","à quoi servent les pierres nécrotiques","histoire des pierres nécrotiques pâles"}},{q="Qui finance ou dirige la riposte à Darnassus ?",a="L’Aube d’argent coordonne l’enquête par l’intermédiaire du Lieutenant Beitha. Cet ordre se consacre à combattre le Fléau.",al={"qui dirige la défense de darnassus","aube d’argent à darnassus"}},{q="Écouter les cercles runiques peut-il vous faire du mal ?",a="Personne ne connaît leurs effets exacts. Beitha demande aux défenseurs d’enquêter sur l’étrange énergie qui entoure les cercles.",al={"murmures des cercles runiques","danger des voix des cercles runiques"}}},fx={["39b377fd"]={q="Pourquoi le Lieutenant Beitha veut-elle que cela soit fait ?",a="Le roi Liche a envoyé une invasion de morts-vivants directement sur le seuil de Teldrassil, ancrée par une nécropole se profilant au-dessus de Darnassus. Le Lieutenant Beitha et l'Aube d'argent refusent de rester inactifs pendant que des aberrations se rassemblent devant les portes de la cité. Elle a besoin que vous éclaircissiez leurs rangs pour soulager la pression sur la capitale, apportiez la preuve de leur destruction, et découvriez le sombre dessein derrière les cercles runiques luisants renforçant leur campement.",al={"motif de beitha","pourquoi enquêter sur le fléau","pourquoi beitha a-t-elle besoin que cela soit fait"}},a5f671f0={q="Contre qui êtes-vous envoyé pour combattre à l'extérieur de Darnassus ?",a="Vous êtes envoyé contre les forces d'invasion du Fléau qui ont établi un campement juste à l'extérieur de Darnassus. Ces serviteurs morts-vivants et ces aberrations ont été déployés directement par le roi Liche sous l'ombre d'une nécropole flottante, cherchant à établir un pied-à-terre et à menacer la capitale des elfes de la nuit.",al={"qui est-ce que je combats","quels sont les fléaux à l'extérieur de darnassus","qui sont les envahisseurs"}}},fp="36,187,26.352.0,21.290.1,25.185.0,39.160.0,52.111.0,29.113.0,52.118.0,44.109.0"}
P.entries["quest:9263"] = {n="Enquêter au sujet du Fléau à Orgrimmar",s="Aux abords d’Orgrimmar, le Fléau lance son assaut sous une nécropole flottante. Le Lieutenant Dagel appelle les défenseurs à repousser les morts-vivants, à récupérer des pierres nécrotiques et à examiner des cercles runiques chargés d’énergie nécromantique. L’assaut étend l’emprise du Roi-liche jusqu’à Durotar.",h="Aux abords d’Orgrimmar, le Fléau lance son assaut sous une nécropole flottante.",kw={"aube d'argent","dagel","durotar","invasion","roi-liche","pierre nécrotique","orgrimmar","cercle runique","fléau"},ang={["faction:Horde"]="Une force du Fléau campant à portée de vue des tours d’Orgrimmar constitue un affront que la Horde ne peut tolérer. Chaque champion assermenté a le devoir de défendre Durotar contre les serviteurs du Roi-liche.",["race:Orc"]="Les orcs ont gagné le sol rouge et aride de Durotar au prix de la souffrance et du sang. Ils ne laisseront pas des monstruosités sans esprit souiller le foyer qu’ils ont bâti de leurs propres mains.",["race:Undead"]="Pour les Réprouvés, le Fléau rappelle leur ancien asservissement. Écraser les envahisseurs est une vendetta personnelle contre l’emprise persistante du Roi-liche."},sec={{t="Des morts-vivants aux portes",b="Le Fléau menace désormais des terres éloignées de Lordaeron et des glaces du nord. Ses nécropoles flottantes projettent leur ombre sur Azeroth, jusqu’à Durotar. Des forces mortes-vivantes se sont rassemblées aux portes d’Orgrimmar et ont dressé des camps qui menacent la capitale de la Horde. Le Lieutenant Dagel et l’Aube d’argent coordonnent la défense et appellent les champions locaux à repousser les envahisseurs avant qu’ils n’établissent un siège."},{t="Reliques nécrotiques et sombres murmures",b="Des pierres nécrotiques ternes et des cercles runiques lumineux se trouvent dans le camp du Fléau. Les cercles entourent le camp et portent le même pouvoir sombre que la nécropole au-dessus. Ceux qui pénètrent dans les runes entendent des voix surnaturelles résonner à travers l’éther. Ces voix semblent communiquer, mais Dagel ignore à qui elles s’adressent."}},faq={{q="Pourquoi le Fléau attaque-t-il Orgrimmar ?",a="Des forces du Fléau ont établi un camp aux abords d’Orgrimmar, sous une nécropole. Le Lieutenant Dagel appelle les défenseurs à réduire leurs rangs et à examiner les cercles runiques voisins.",al={"pourquoi le fléau attaque orgrimmar","morts-vivants aux abords d’orgri","le roi-liche attaque orgrimmar"}},{q="Qui est le Lieutenant Dagel ?",a="Le Lieutenant Dagel est un officier qui coordonne ses efforts avec l’Aube d’argent pour rallier les défenseurs contre l’invasion. Depuis les abords de la menace, Dagel ordonne aux combattants d’abattre les morts-vivants et d’examiner leurs outils arcaniques.",al={"lieutenant dagel","dagel donneur de quête","qui est dagel"}},{q="Que sont les pierres nécrotiques ternes ?",a="Les pierres nécrotiques ternes sont récupérées sur les envahisseurs du Fléau et rapportées à l’Aube d’argent comme preuve que des morts-vivants ont été abattus.",al={"pierres nécrotiques","que sont les pierres nécrotiques ternes","pierres ternes"}},{q="Que sont les cercles runiques lumineux aux abords de la ville ?",a="Les cercles lumineux renferment la même énergie étrange que les morts-vivants voisins et la nécropole. Dagel demande aux défenseurs d’en découvrir l’utilité.",al={"cercles runiques","runes lumineuses orgri","cercles du fléau"}},{q="Pourquoi l’Aube d’argent est-elle à Durotar ?",a="L’Aube d’argent est un ordre indépendant qui se consacre à détruire le Fléau partout où il apparaît. L’ordre œuvre avec les défenseurs de la Horde pour protéger les frontières d’Orgrimmar contre l’invasion.",al={"aube d’argent à orgrimmar","pourquoi l’aube d’argent est ici","aube d’argent et horde"}},{q="La nécropole qui surplombe la ville représente-t-elle un danger ?",a="La nécropole domine le camp du Fléau et partage son énergie étrange. Sa présence fait des morts-vivants aux abords de la ville une menace préoccupante.",al={"citadelle flottante orgri","nécropole au-dessus de durotar"}}},fx={["4fe35d0b"]={q="Pourquoi le Lieutenant Dagel veut-il que le Fléau fasse l'objet d'une enquête ?",a="Avec les sbires du roi Liche s'amassant juste devant les portes d'Orgrimmar sous une nécropole sinistre, le Lieutenant Dagel sait que la cité ne peut rester inactive. Il craint quelle magie infecte les envahisseurs préparent dans leurs campements. En dévoilant le but de leurs étranges cercles runiques luisants et en éclaircissant la horde envahissante, Dagel espère recueillir des renseignements vitaux sur les sombres desseins du Fléau et prévenir un siège catastrophique de Durotar.",al={"pourquoi dagel veut-il cela","motif de dagel","pourquoi enquêter sur le fléau"}},["76cd191d"]={q="Contre qui êtes-vous envoyé pour combattre à l'extérieur d'Orgrimmar ?",a="Vous êtes envoyé contre les forces mort-vivantes envahissantes envoyées par le roi Liche, qui ont établi un campement directement à l'extérieur d'Orgrimmar sous une nécropole flottante. Ces aberrations sans esprit et ces infects rôdeurs font partie d'une invasion coordonnée menaçant Kalimdor, établissant de vils pied-à-terre arcaniques à travers le désert pour miner les défenses de la Horde et terroriser Durotar.",al={"qui combattons-nous","ennemis du fléau à l'extérieur d'orgrimmar","qui dois-je tuer pour dagel"}}},fp="36,274,19.396.0,33.327.1,39.164.0,24.201.0,33.120.0,52.136.0,43.181.0,49.135.0"}
P.entries["quest:92640"] = {n="Desperate Times",s="Valennia Stormfist attend à Valanaar, prête à frapper le culte dans son sanctuaire. Il faut arrêter Lorthuna sur place, mais les Sculpte-vents et l’Ordre suprême doivent d’abord apaiser leurs profondes tensions.",h="Valennia Stormfist attend à Valanaar, prête à frapper le culte dans son sanctuaire.",kw={"culte","desperate times","ordre suprême","lorthuna","sanctuaire","valanaar","valennia stormfist","sculpte-vents"},sec={{t="Une frappe directe",b="Le culte ne peut pas être affronté sans danger à découvert, alors les défenseurs ont besoin d’un plan plus audacieux. Ils frapperont le sanctuaire du culte au lieu de livrer une longue bataille sur un terrain défavorable. S’ils éliminent Lorthuna avant qu’elle ne mène à bien sa part du grand dessein du culte, ils pourront neutraliser la menace à la source."},{t="Unir les factions divisées",b="À Valanaar, Valennia Stormfist prépare depuis quelque temps un assaut contre le sanctuaire. L’attaque nécessite des renforts importants et l’union des forces des factions. Pourtant, les Sculpte-vents et l’Ordre suprême restent divisés par de graves tensions politiques, ce qui met leur alliance en péril."}},faq={{q="Qui est Valennia Stormfist ?",a="Valennia Stormfist se trouve à Valanaar, où elle prépare un assaut contre le sanctuaire du culte. L’attaque dépend de la coopération entre les factions rivales.",al={"qui est valennia","valennia stormfist","où se trouve valennia"}},{q="Qui est Lorthuna ?",a="Lorthuna est une figure importante du culte hostile. Elle dirige un complot crucial depuis le sanctuaire, ce qui fait d’elle la cible de l’attaque prévue.",al={"qui est lorthuna","histoire de lorthuna","lorthuna cheffe du culte"}},{q="Pourquoi attaquer directement le sanctuaire ?",a="Le culte ne peut pas être affronté sans danger à découvert. Le plan consiste à frapper le sanctuaire et à arrêter Lorthuna avant qu’elle ne mène son complot à bien.",al={"pourquoi attaquer le sanctuaire","raison de l’attaque du culte"}},{q="Quel est le problème entre les Sculpte-vents et l’Ordre suprême ?",a="Les tensions sont vives entre les Sculpte-vents et l’Ordre suprême. Aucune des deux factions ne peut attaquer le sanctuaire seule, elles doivent donc coopérer.",al={"tensions entre l’ordre suprême et les sculpte-vents","pourquoi les factions s’affrontent","conflit des sculpte-vents"}},{q="Où se trouve Valanaar ?",a="Valanaar est le lieu où Valennia Stormfist coordonne le plan et rallie des alliés pour frapper le sanctuaire du culte.",al={"où se trouve valanaar","emplacement de valanaar"}},{q="Quel est l’objectif général de cette mission ?",a="L’objectif est de retrouver Valennia Stormfist à Valanaar, de découvrir les détails de son attaque prévue et de contribuer à la coopération entre les factions divisées.",al={"objectif de desperate times","quel est le plan de desperate times"}}},fp="15,195,15.304.0,24.282.0,26.153.0,16.140.0,41.140.0,61.148.0,18.121.0,41.150.0"}
P.entries["quest:92642"] = {n="Disrupting Logistics",s="Dans les Plaines Aérelles, les cultistes d’Al’Aketh lancent un assaut massif. Leurs soigneurs maintiennent les bagarreurs au combat, et les défenseurs ont besoin d’aide avant que leurs lignes ne cèdent.",h="Dans les Plaines Aérelles, les cultistes d’Al’Aketh lancent un assaut massif.",kw={"al’aketh","bagarreurs","cultistes","disrupting logistics","plaines aérelles","soigneurs","valennia"},ang={["class:Priest"]="En tant que prêtre, vous savez comment le soutien des soigneurs peut maintenir une ligne offensive. Les soigneurs d’Al’Aketh sont la clé de voûte de l’assaut des cultistes.",["class:Rogue"]="En tant que voleur, vous savez combien il est précieux de vous glisser derrière les lignes ennemies pour éliminer les soigneurs et désorganiser les renforts."},sec={{t="Une défense désespérée",b="Un assaut féroce s’abat sur les défenseurs postés au-dessus des Plaines Aérelles. Les forces ennemies se rassemblent et les lignes locales sont sur le point de céder. Les commandants attendaient d’importants renforts de Valennia, mais doivent compter sur les bras capables qui se présentent. Frapper les soutiens ennemis pourrait être le seul moyen de préserver la défense."},{t="Briser les rangs des cultistes",b="Les bagarreurs d’Al’Aketh avancent en rangs, soutenus par des soigneurs qui pansent leurs blessures. Dans les Plaines Aérelles, éliminer ces soigneurs peut briser l’assaut des cultistes. Les défenseurs auront alors une chance de se rallier et de repousser l’invasion."}},faq={{q="Que raconte la quête Disrupting Logistics ?",a="Disrupting Logistics est une défense désespérée contre l’assaut d’Al’Aketh dans les Plaines Aérelles. Un défenseur isolé a besoin d’aide pour éliminer les soutiens ennemis de première ligne avant que la défense ne s’effondre.",al={"qu’est-ce que disrupting logistics","quête disrupting logistics","quête des plaines aérelles"}},{q="Qui sont les cultistes d’Al’Aketh qui attaquent les Plaines Aérelles ?",a="Les cultistes d’Al’Aketh attaquent les Plaines Aérelles avec des bagarreurs et des soigneurs. Leur front organisé dépend du soutien des soigneurs pour maintenir la pression sur les défenseurs locaux.",al={"qui sont les al’aketh","qui attaque les plaines aérelles","qui sont les cultistes"}},{q="Pourquoi les soigneurs d’Al’Aketh sont-ils précisément visés ?",a="Les soigneurs d’Al’Aketh permettent aux combattants de l’avant-garde de poursuivre leur avancée. Les éliminer pourrait briser l’élan de l’assaut et donner aux défenseurs une chance de se rallier et de repousser les cultistes.",al={"pourquoi tuer les soigneurs","pourquoi viser les soigneurs d’al’aketh"}},{q="Où cet assaut a-t-il lieu ?",a="L’assaut a lieu dans les Plaines Aérelles, juste en contrebas de l’avant-poste défensif. Les bagarreurs et les soigneurs d’Al’Aketh ont envahi les plaines et poursuivent leur attaque.",al={"où se trouvent les plaines aérelles","emplacement des plaines aérelles"}},{q="Qui est Valennia ?",a="Valennia semble organiser l’aide et les renforts. Le défenseur est exaspéré que Valennia n’ait envoyé qu’un seul aventurier face à un assaut massif.",al={"qui est valennia","renforts de valennia"}},{q="Qui commande la défense contre Al’Aketh ?",a="Un défenseur acculé appelle à l’aide tandis que les siens sont sur le point de succomber face à Al’Aketh. Le défenseur vénère « les vents » et a besoin de toute force combattante capable de renverser le cours de la bataille.",al={"qui donne disrupting logistics","qui sont les miens qui résistent"}}},fp="20,178,19.351.0,25.239.0,39.198.0,53.171.0,51.183.0,35.192.0,16.146.0,46.183.0"}
P.entries["quest:92643"] = {n="The Turncoat",s="Un sectateur d’Al’Aketh propose de faire défection et de révéler les plans de la secte pour l’île. Vous devez aller le chercher dans une retraite isolée des hautes-terres, au nord-ouest de Valanaar, où la rencontre pourrait être un piège.",h="Un sectateur d’Al’Aketh propose de faire défection et de révéler les plans de la secte pour l’île.",kw={"al’aketh","sectateur","déserteur","hautes-terres","the turncoat","renégat","valanaar"},ang={["class:Rogue"]="L’infiltration, la défection et les embuscades sont familières à un Voleur. Les sectateurs qui quittent les rangs risquent le silence ou la lame. Les assassins à l’extérieur montrent que le secret peut frapper dans les deux sens, dans les hautes-terres."},sec={{t="Un serment brisé",b="Un sectateur dans les rangs d’Al’Aketh affirme connaître les véritables intentions de la secte pour l’île. Il propose de faire défection, mais exige de fermes garanties de protection. La secte garde ses plans secrets, alors le contacter pourrait valoir le danger."},{t="La cachette des hautes-terres",b="Le déserteur attend seul dans une demeure isolée des hautes-terres, au nord-ouest de Valanaar. Vous devez le rejoindre avec prudence. La rencontre pourrait être une embuscade d’Al’Aketh destinée à débusquer ceux qui fouillent les affaires de la secte."},{t="Silence dans les hautes-terres",b="Le déserteur gît mort dans la maison isolée des hautes-terres. Des assassins l’ont retrouvé et frappé avant l’arrivée d’une escorte. Dehors, les assassins tombés témoignent de la suite des événements. Un éclat sur le corps du renégat mort laisse penser qu’il a laissé une réponse derrière lui."}},faq={{q="Qui est le renégat ?",a="Le renégat était un ancien membre de la secte Al’Aketh qui affirmait connaître ses véritables intentions pour l’île. Il proposait de faire défection et de révéler ce qu’il savait en échange d’une protection.",al={"qui est le renégat","qui était le déserteur","identité du renégat"}},{q="Qu’est-ce qu’Al’Aketh ?",a="Al’Aketh est une secte énigmatique qui opère dans la région. Ses projets pour l’île restent dissimulés par le secret et le fanatisme, si bien que les autorités locales prennent de grands risques pour contacter les déserteurs prêts à parler.",al={"qui sont les al’aketh","secte al’aketh","qu’est-ce qu’al’aketh"}},{q="Où le déserteur se cache-t-il ?",a="Le déserteur se cachait dans une demeure isolée des hautes-terres, au nord-ouest de Valanaar. Il y attendait une escorte, confiant dans les promesses de protection.",al={"où se cache le renégat","emplacement du renégat","où trouver le renégat"}},{q="Qu’est-il arrivé au déserteur ?",a="Quand quelqu’un a atteint la demeure isolée des hautes-terres, les assassins avaient déjà retrouvé et tué le déserteur. On l’a découvert mort dans la maison, trop tard pour l’interroger.",al={"qu’est-il arrivé au renégat","le déserteur est-il mort","qui a tué le renégat"}},{q="Qu’a laissé le renégat ?",a="Après avoir éliminé les assassins à l’extérieur, un éclat sur le corps du déserteur mort a attiré l’attention. L’objet brillant était toujours là et pourrait donner un indice sur les secrets qu’il détenait.",al={"quel objet brillant","objet brillant du renégat","reflet brillant sur le corps"}},{q="Pourquoi le sectateur a-t-il décidé de faire défection ?",a="Le sectateur affirme connaître les véritables intentions d’Al’Aketh pour l’île et ne fera défection qu’avec des garanties de protection. On ignore ce qui l’a poussé à quitter la secte.",al={"pourquoi le sectateur a-t-il fait défection","motif du renégat","pourquoi trahir al’aketh"}}},fp="12,206,13.233.0,20.213.0,24.246.1,20.188.0,21.197.0,29.147.0,30.166.0,35.168.0,37.171.0"}
P.entries["quest:92644"] = {n="Unfortunate News",s="Vous trouvez le cultiste renégat mort avant qu'il puisse parler. Un cristal bleu endommagé gît sous son corps, et vous le portez au grand aîné Talanaanis Shadowsong, à Valanaar.",h="Vous trouvez le cultiste renégat mort avant qu'il puisse parler.",kw={"cultiste","cristal luisant","shadowsong","talanaanis shadowsong","transfuge","unfortunate news","valanaar"},ang={["class:Mage"]="En tant que Mage, vous reconnaîtrez peut-être dans le cristal bleu luisant et endommagé un artefact. Le grand aîné Shadowsong enquête sur les cultistes et prend le cristal pour l'étudier."},sec={{t="Un rendez-vous manqué",b="Vous arrivez au lieu du rendez-vous et découvrez que le cultiste transfuge a déjà été tué. Son corps est encore chaud. Un petit cristal bleu luisant, endommagé mais vibrant encore, repose dessous. Vous le portez au grand aîné Talanaanis Shadowsong, à Valanaar."},{t="L'enquête de Shadowsong",b="Vous retournez seul à Valanaar et annoncez au grand aîné Talanaanis Shadowsong que le transfuge est mort avant d'avoir pu témoigner. La perte d'un contact vivant est un sérieux revers. Pourtant, le cristal bleu endommagé attire l'attention du grand aîné. Il le trouve intéressant et vous le prend."}},faq={{q="Qu'est-ce que la quête Unfortunate News ?",a="Vous trouvez le cultiste transfuge mort avant qu'il puisse parler. Un cristal bleu luisant et endommagé repose sous son corps. Vous le portez au grand aîné Talanaanis Shadowsong.",al={"qu'est-ce qu'unfortunate news","quête unfortunate news","unfortunate news wow forever"}},{q="Qui était le cultiste transfuge ?",a="Le transfuge était un cultiste renégat que vous deviez rencontrer. Il a été tué avant de pouvoir parler ou s'enfuir, laissant derrière lui un corps encore chaud et un cristal endommagé.",al={"qui est le transfuge mort","qui est mort dans unfortunate news","cultiste transfuge"}},{q="Qui est le grand aîné Shadowsong ?",a="Talanaanis Shadowsong est un elfe et le grand aîné de Valanaar. Il dirige les enquêtes sur les cultistes et reçoit le cristal endommagé trouvé sur le corps du transfuge.",al={"qui est shadowsong à valanaar","où se trouve talanaanis shadowsong","talanaanis shadowsong"}},{q="Qu'est-ce que le cristal bleu endommagé ?",a="Le cristal bleu endommagé est un petit cristal luisant trouvé sous le transfuge abattu. Le grand aîné Shadowsong le trouve intéressant et vous le prend.",al={"qu'est-ce que le cristal luisant","cristal bleu du cultiste","cristal endommagé unfortunate news"}},{q="Où se déroule cette quête ?",a="Le grand aîné Talanaanis Shadowsong réside à Valanaar. Vous y retournez avec votre rapport et le cristal récupéré.",al={"où se trouve valanaar","emplacement de valanaar","rendre la quête unfortunate news"}},{q="Quel est le lien entre cette quête et The Turncoat ?",a="Cette quête fait suite à The Turncoat, où vous partez à la recherche du cultiste transfuge. Vous arrivez trop tard pour le sauver.",al={"quelle quête précède unfortunate news","prélude à unfortunate news","quête the turncoat"}}},fp="16,164,19.232.0,26.275.1,35.166.0,29.160.0,29.166.0,33.153.0,33.120.0,44.112.0"}
P.entries["quest:92645"] = {n="Breaking the Breaker",s="Dans les Plaines Aérelles, les sectateurs acculent les défenseurs. La commandante Belguilos dirige l’assaut depuis sa villa à flanc de colline, et la frapper là pourrait être leur seule chance de survivre.",h="Dans les Plaines Aérelles, les sectateurs acculent les défenseurs.",kw={"belguilos","breaking the breaker","commandante belguilos","commandante des sectateurs","plaines aérelles","pacificatrice","la briseuse","villa"},ang={["class:Warrior"]="En tant que guerrier, vous affrontez la commandante Belguilos, une ancienne pacificatrice que l’on craint sous le nom de « la Briseuse ».",["race:Skyborne"]="Les défenseurs invoquent les quatre vents pour bénir le héros après l’arrêt des sectateurs."},sec={{t="Une défense désespérée",b="Les sectateurs assaillent les Plaines Aérelles et poussent les défenseurs locaux au bord du gouffre. Les repousser semble presque impossible tant que la commandante Belguilos dirige l’attaque. Tous la craignent sous le nom de « la Briseuse ». \n\nSa villa sert de base à l’opération. La tuer là-bas est périlleux, presque suicidaire, mais l’inaction condamne les défenseurs."},{t="La pacificatrice déchue",b="Avant de commander les sectateurs, Belguilos maintenait l’ordre comme pacificatrice. Même alors, son attitude mettait profondément mal à l’aise ceux qui l’entouraient. Quand l’influence de la secte s’est propagée hors de tout contrôle, elle a embrassé son extrémisme. À présent, elle commande les sectateurs et inspire la terreur."}},faq={{q="Qui est Belguilos la Briseuse ?",a="Belguilos, surnommée « la Briseuse », dirige l’attaque des sectateurs. Avant de rejoindre la secte, elle servait comme pacificatrice, bien que son entourage la trouvât déjà inquiétante.",al={"qui est belguilos","qui est la briseuse","commandante des sectateurs"}},{q="Où trouver la commandante Belguilos ?",a="La commandante Belguilos se trouve dans la villa au pied de la colline, dans les Plaines Aérelles. De là, elle coordonne l’assaut des sectateurs contre les défenseurs locaux.",al={"où se trouve belguilos","emplacement de belguilos","où trouver la briseuse"}},{q="Pourquoi éliminer Belguilos ?",a="Il est presque impossible de repousser l’assaut des sectateurs tant que Belguilos le dirige. L’éliminer brise le commandement de la secte et donne aux défenseurs une véritable chance de survivre.",al={"pourquoi tuer belguilos","raison de l’attaque des sectateurs","pourquoi la briseuse est-elle dangereuse"}},{q="Quel était le passé de Belguilos avant qu’elle rejoigne la secte ?",a="Avant que l’influence de la secte ne se propage hors de tout contrôle, Belguilos servait comme pacificatrice. Ceux qui la connaissaient la trouvaient déjà profondément inquiétante.",al={"qu’était belguilos avant","belguilos était-elle bonne","pacificatrice sectatrice"}},{q="Que signifie la bénédiction des quatre vents ?",a="La bénédiction des quatre vents exprime le profond soulagement et la gratitude des défenseurs après l’arrêt définitif de la terrifiante commandante des sectateurs.",al={"signification des quatre vents","qui dit que les quatre vents vous bénissent"}},{q="Que sont les Plaines Aérelles ?",a="Les Plaines Aérelles sont un territoire disputé où se déroule l’assaut des sectateurs. La commandante Belguilos se trouve dans une villa au pied de la colline.",al={"que sont les plaines aérelles","où trouver la quête de la briseuse"}}},fp="20,195,19.329.0,22.276.0,29.175.0,39.158.0,33.180.0,50.158.0,59.166.0,32.144.0"}
P.entries["quest:92646"] = {n="Confront Lorthuna",s="Elaadrin Evengale et Ayessa Dawnsinger poursuivent la grande prêtresse Lorthuna à travers un portail jusqu’aux Flèches Rohashi, au-dessus de Zephras. Ils appellent à votre aide avant qu’elle n’échappe à la justice ou ne renforce son pouvoir.",h="Elaadrin Evengale et Ayessa Dawnsinger poursuivent la grande prêtresse Lorthuna à travers un portail...",kw={"ayessa dawnsinger","confront lorthuna","elaadrin evengale","grande prêtresse lorthuna","lorthuna","muln","flèches rohashi","valennia","sculpte-vents","zephras"},ang={["class:Priest"]="En tant que prêtre, vous affrontez la grande prêtresse Lorthuna, une dirigeante spirituelle corrompue parmi les flèches. Le combat contre elle pèse lourd pour ceux qui s’opposent aux doctrines ténébreuses.",["class:Shaman"]="En tant que chaman, vous partagez les enjeux spirituels du travail des Sculpte-vents pour guider l’équilibre élémentaire sur Zephras. Vous pouvez aider à préserver cet équilibre face à la menace de Lorthuna."},sec={{t="La poursuite dans les flèches",b="La grande prêtresse Lorthuna fuit à travers un portail mystique jusqu’aux Flèches Rohashi, au-dessus de Zephras. Un allié blessé reste au seuil du portail. Elaadrin Evengale et Ayessa Dawnsinger la suivent dans les hauteurs et appellent à votre aide avant qu’elle n’échappe à la justice ou ne renforce son pouvoir."},{t="Le prix de la bataille",b="Après l’affrontement dans les flèches, Valennia et ses forces survivantes ont besoin des soins d’un guérisseur. Elles sont escortées jusqu’à la résidence du Grand Ancien pour y récupérer. Lorthuna les a affrontées, et la coalition est meurtrie, ses ressources étant fortement entamées."},{t="Une île vulnérable",b="Après la bataille, Muln s’entretient au sujet des Sculpte-vents et de leur mission, puis part pour le continent d’Azeroth. Zephras reste gravement vulnérable. Les dirigeants restés sur place doivent planifier d’urgence les défenses contre les dangers qui menacent encore l’île."}},faq={{q="Qui est la grande prêtresse Lorthuna ?",a="La grande prêtresse Lorthuna est une adversaire redoutable qui fuit par un portail jusqu’aux Flèches Rohashi, au-dessus de Zephras. Ayessa Dawnsinger et Elaadrin Evengale la poursuivent jusque-là.",al={"qui est lorthuna","qu’est-ce que lorthuna","histoire de la grande prêtresse lorthuna"}},{q="Que sont les Flèches Rohashi ?",a="Les Flèches Rohashi sont des hauteurs qui surplombent l’île de Zephras. La grande prêtresse Lorthuna s’y enfuit par un portail, et ses poursuivants la suivent.",al={"que sont les flèches rohashi","où mène le portail","emplacement des flèches rohashi"}},{q="Qui a poursuivi Lorthuna à travers le portail ?",a="Elaadrin Evengale et Ayessa Dawnsinger poursuivent la grande prêtresse Lorthuna à travers le portail alors qu’elle fuit vers les flèches. Ils appellent à votre aide.",al={"qui a poursuivi lorthuna","ayessa et elaadrin","qui entre dans le portail"}},{q="Qu’est-il arrivé à Valennia et à ses forces ?",a="Valennia et ses forces survivantes ont besoin de soins immédiats après les combats. Des guérisseurs les soignent, puis elles sont escortées jusqu’à la résidence du Grand Ancien pour y récupérer.",al={"qui est valennia","qu’est-il arrivé à valennia","forces de valennia"}},{q="Quel est le rôle de Muln dans ces événements ?",a="Muln est un allié associé aux Sculpte-vents. Après avoir discuté de leur avenir et de leur mission, il part pour le continent d’Azeroth.",al={"qui est muln","muln quitte zephras","où est parti muln"}},{q="L’île de Zephras est-elle en sécurité après l’affrontement avec Lorthuna ?",a="Zephras reste gravement vulnérable après l’affrontement. Ses dirigeants doivent planifier d’urgence les défenses contre les dangers qui menacent l’île.",al={"que va-t-il arriver à zephras","zephras est-elle en sécurité maintenant","état de l’île de zephras"}}},fp="17,204,23.295.0,22.248.1,25.257.1,31.169.0,28.138.0,37.141.0,41.156.0,36.134.0,59.146.0"}
P.entries["quest:92679"] = {n="Blood Tithe",s="À Valanaar, Alvarion Windfield cherche de l'aide pour le verger qui fait vivre sa famille. La douleur empêche ce fermier Skyborne de travailler. Il envoie donc des voyageurs vers l'ouest auprès de sa femme, Aamelia, qui s'occupe de leur ferme des basses-terres.",h="À Valanaar, Alvarion Windfield cherche de l'aide pour le verger qui fait vivre sa famille.",kw={"aamelia windfield","alvarion windfield","blood tithe","skyborne","valanaar","verger champ-des-vents"},ang={["race:Skyborne"]="Fermier Skyborne, Alvarion Windfield souffre et appelle désespérément à l'aide. Ses épreuves montrent ce que les Skyborne affrontent au-delà de Valanaar."},sec={{t="Un appel à l'aide à Valanaar",b="Alvarion Windfield a quitté sa ferme pour venir à Valanaar chercher des combattants capables. La douleur le fait visiblement souffrir, et il craint pour le gagne-pain que lui procure sa ferme. Il vous demande de partir vers l'ouest, dans les basses-terres, où sa femme Aamelia s'occupe de leur verger familial."},{t="Des ennuis dans les basses-terres",b="Le Verger Champ-des-Vents se trouve dans les basses-terres, à l'ouest de Valanaar. Alvarion est trop malade pour s'occuper de la ferme, et Aamelia Windfield en assume seule les charges. Rejoignez la vallée occidentale, découvrez ce qui menace le verger et prêtez main-forte à la famille."}},faq={{q="Qui est Alvarion Windfield ?",a="Alvarion Windfield est un fermier Skyborne de Valanaar qui cherche des combattants pour protéger son foyer. Malgré les vives douleurs qui le tourmentent, il envoie des voyageurs auprès de sa femme, Aamelia, à leur verger.",al={"qui est alvarion","histoire d'alvarion windfield","qui donne blood tithe"}},{q="Où se trouve le Verger Champ-des-Vents ?",a="Le Verger Champ-des-Vents se trouve dans les basses-terres, à l'ouest de Valanaar. Alvarion y envoie des voyageurs pour retrouver sa femme, Aamelia Windfield, qui veille à la défense de la ferme.",al={"où se trouve le verger champ-des-vents","emplacement d'aamelia windfield","comment trouver le verger"}},{q="Pourquoi Alvarion souffre-t-il ?",a="Quand les voyageurs le rencontrent, la cause du mal d'Alvarion est inconnue. Il souffre de vives douleurs incapacitantes tandis qu'il leur parle, ce qui rend son appel à l'aide urgent.",al={"pourquoi alvarion souffre","qu'est-ce qui arrive à alvarion","douleur d'alvarion"}},{q="Qui est Aamelia Windfield ?",a="Aamelia Windfield est la femme d'Alvarion et s'occupe de leur verger familial à l'ouest de Valanaar. Il envoie les voyageurs prêts à aider défendre leurs terres.",al={"qui est aamelia","histoire d'aamelia windfield","femme d'alvarion"}},{q="Quelle est la tâche de Blood Tithe ?",a="Alvarion Windfield cherche de l'aide à Valanaar pour sa ferme en difficulté. Il vous demande de retrouver sa femme, Aamelia, dans leur verger des basses-terres.",al={"résumé de la quête blood tithe","de quoi parle blood tithe","ferme attaquée à valanaar"}},{q="Quel est le rôle de Valanaar ici ?",a="Valanaar est un lieu de rassemblement pour les voyageurs et les Skyborne. Alvarion s'y rend pour trouver des combattants capables de sauver son verger du danger.",al={"histoire de valanaar","où se déroule blood tithe","qu'est-ce que valanaar"}}},fp="11,208,18.270.0,23.239.0,26.183.0,39.163.0,24.149.0,25.143.0,32.131.0,37.139.0"}
P.entries["quest:92682"] = {n="Make Yourself Useful",s="Au Verger Champ-des-Vents, les bandits de Ferauu prennent des stormapples avant l’heure prévue. Certains hors-la-loi affamés ont rompu les rangs pour cueillir les fruits en avance. Chassez-les, et le gardien du verger vous respectera.",h="Au Verger Champ-des-Vents, les bandits de Ferauu prennent des stormapples avant l’heure prévue.",kw={"bandits","ferauu","bandits affamés","make yourself useful","verger","stormapples mûres","stormapples","verger champ-des-vents"},ang={["class:Rogue"]="En tant que voleur, vous remarquez le manque de discipline des voleurs amateurs lorsque des bandits trahissent leur bande pour voler des stormapples avant l’heure."},sec={{t="Des problèmes au Verger Champ-des-Vents",b="Le Verger Champ-des-Vents réserve une part régulière de sa récolte de fruits aux bandits de Ferauu. Ferauu dirige la bande, mais certains hors-la-loi ne peuvent attendre sa visite prévue. Ils s’introduisent tôt dans le verger pour cueillir des stormapples à leur compte."},{t="Des voleurs parmi les voleurs",b="Le gardien du verger met au travail les nouveaux arrivants ambitieux avant l’arrivée de Ferauu. Il vous demande de protéger les stormapples mûres et de chasser les bandits affamés qui rôdent illégalement parmi les arbres. Ils ont agi dans le dos de Ferauu pour prendre sa part. Le gardien dit que Ferauu les exécuterait probablement pour cela."}},faq={{q="Qui est Ferauu ?",a="Ferauu dirige les bandits qui exigent une part régulière de la récolte du Verger Champ-des-Vents. Il impose une discipline impitoyable à sa bande, mais certains bandits affamés se sont introduits tôt dans le verger dans son dos.",al={"qui est ferauu","histoire de ferauu","chef des bandits ferauu"}},{q="Qu’est-ce que le Verger Champ-des-Vents ?",a="Le Verger Champ-des-Vents est une ferme locale où poussent des stormapples. Les bandits de Ferauu exigent une part de sa récolte de fruits en échange de laisser le verger en paix.",al={"qu’est-ce que le verger champ-des-vents","histoire du verger champ-des-vents","verger de stormapples"}},{q="Pourquoi des bandits affamés rôdent-ils parmi les arbres à stormapples ?",a="Des bandits affamés de la bande de Ferauu sont entrés dans le verger avant la date prévue pour venir chercher la récolte, afin de voler des stormapples pour eux-mêmes. Ils ont rompu les rangs et abîmé les cultures. Le gardien du verger vous demande donc de les chasser.",al={"pourquoi tuer les bandits affamés","pourquoi des bandits sont-ils au verger","histoire des bandits affamés"}},{q="Que sont les stormapples ?",a="Les stormapples sont des fruits cultivés au Verger Champ-des-Vents. Elles nourrissent les gens et composent le tribut de la récolte exigé par les bandits de Ferauu.",al={"que sont les stormapples","stormapples mûres"}},{q="Ferauu sait-il que ses bandits s’introduisent dans le verger ?",a="Ferauu ignore que ces bandits sont venus en avance. Le gardien du verger dit qu’ils ont agi de leur propre chef, et Ferauu les exécuterait probablement s’il les surprenait à prendre des fruits avant son arrivée.",al={"ferauu sait-il pour les bandits","trahison de ferauu"}},{q="Qui vous confie la mission Make Yourself Useful ?",a="Le gardien du verger vous propose du travail au Verger Champ-des-Vents et surveille les bosquets depuis une fenêtre voisine. Face à des nouveaux arrivants audacieux en quête de travail ou de nourriture, il met votre courage à l’épreuve en vous envoyant contre les bandits qui s’introduisent dans le verger.",al={"qui donne make yourself useful","donneur de quête make yourself useful"}}},fp="20,208,28.224.0,21.298.0,14.193.0,26.153.0,53.219.0,21.125.0,59.175.0,40.230.0"}
P.entries["quest:92683"] = {n="Poussière de voltemouche",s="Dans les Plaines Aérelles, la poudre de voltemouche intéresse un fermier. Des voyageurs la récoltent sur des voltemouches géantes, tandis que des bandits menacent quiconque s'aventure seul dans les champs.",h="Dans les Plaines Aérelles, la poudre de voltemouche intéresse un fermier.",kw={"bandits","voltemouche","poussière de voltemouche","tapette à voltemouches","plaines aérelles","verger","poussière d'aile"},sec={{t="Les géantes des Plaines Aérelles",b="Des voltemouches géantes parcourent les champs extérieurs et les vergers des Plaines Aérelles. Leurs ailes libèrent une fine poussière, que vous pouvez récolter en quantité. Les fermiers des environs veulent cette poudre pour des besoins pratiques du foyer. Pourtant, ces insectes restent sauvages."},{t="Des tapettes et des secousses",b="Une Tapette à voltemouches fait tomber la poussière d'un coup brutal. La plupart des voltemouches paniquent, s'envolent et libèrent des tas de poudre en se secouant. Certaines se retournent et ripostent si on les provoque. D'ordinaire, elles sont dociles."},{t="Des usages mystérieux",b="La poussière est salissante à récolter et s'accroche aux vêtements et à l'équipement pendant des semaines. Le fermier attend sa livraison avec impatience, car les bandits rendent trop dangereuses les expéditions solitaires dans les champs. Demandez à quoi sert la poudre, et le résident se contente de vagues paroles sur des trucs et des machins."}},faq={{q="À quoi sert la poussière de voltemouche ?",a="Le résident affirme que la poussière a des usages pratiques dans le foyer, mais reste vague sur sa fonction, parlant de trucs et de machins.",al={"poussière de voltemouche","usage de la poussière de voltemouche","à quoi sert la poussière"}},{q="Où trouve-t-on des voltemouches ?",a="Les voltemouches géantes parcourent les champs extérieurs près du verger local, surtout dans les Plaines Aérelles. Les bandits des environs rendent la récolte dangereuse pour quiconque est seul.",al={"où trouver des voltemouches","emplacement des voltemouches","insectes des plaines aérelles"}},{q="Les voltemouches sont-elles agressives ?",a="Les voltemouches sont généralement dociles et s'enfuient quand on les dérange. Certaines se défendent si on les frappe ou les provoque, puis libèrent la poussière de leurs ailes.",al={"les voltemouches sont-elles dangereuses","les voltemouches attaquent-elles","comportement des voltemouches"}},{q="Comment récolter la poussière de voltemouche ?",a="Une Tapette à voltemouches assène un coup puissant aux insectes géants. En réaction, certaines agitent leur derrière et dispersent des tas de poussière de leurs ailes que vous pouvez ramasser.",al={"comment obtenir de la poussière","tapette à voltemouches","récolter la poussière de voltemouche"}},{q="Pourquoi le résident a-t-il besoin d'aide pour récolter la poussière ?",a="Le résident vit seul et ne peut pas facilement quitter sa ferme pour récolter la poussière. Les bandits qui parcourent les basses terres alentour rendent trop dangereux un voyage jusqu'aux champs éloignés.",al={"pourquoi demander de l'aide","menace des bandits des plaines aérelles","pourquoi le donneur de quête demande de l'aide"}},{q="Pourquoi le résident reste-t-il évasif sur le véritable usage de la poussière ?",a="Le résident refuse d'expliquer l'usage domestique de la poussière et élude les questions en parlant de trucs et de machins. Son usage reste inexpliqué.",al={"pourquoi tant de secret","recette secrète de poussière"}}},fp="15,184,23.244.0,19.200.0,21.277.0,33.122.0,29.170.0,28.135.0,33.151.0,59.169.0,58.144.0"}
P.entries["quest:92684"] = {n="Ornery Ornery Galestriders",s="Dans les Plaines Aérelles, la maigre récolte d’un pomiculteur est menacée par les galestriders qui pillent les stormapples. Chassez les oiseaux les plus hardis pour sauver les fruits restants et rapporter des filets pour le dîner.",h="Dans les Plaines Aérelles, la maigre récolte d’un pomiculteur est menacée par les galestriders qui pillent...",kw={"galestrider","plaines aérelles","galestrider des basses terres","verger","galestriders irascibles","stormapples","filet"},ang={["class:Hunter"]="En tant que chasseur, prenez garde aux puissants coups de patte et au tempérament agressif des galestriders des basses terres. Ils diffèrent de leurs congénères des hautes terres.",["profession:Cooking"]="Les galestriders des basses terres fournissent des filets nourrissants, parfaits pour un copieux repas chaud, bienvenu après de maigres récoltes et tant de fruits."},sec={{t="Défendre le verger",b="La maigre récolte laisse peu de réserves aux fermiers des Plaines Aérelles. À présent, des galestriders sauvages arrachent les stormapples mûres aux branches et menacent les fruits restants. Le fermier a besoin qu’on chasse ou abatte les oiseaux les plus hardis avant que la récolte ne disparaisse."},{t="Terreurs des basses terres",b="Les galestriders des basses terres sont plus grands et plus irascibles que leurs congénères des hautes terres. Prenez garde près de ces oiseaux imposants, voyageur : un puissant coup de patte peut blesser gravement ou tuer un combattant. Leurs filets offrent aux habitants affamés un repas copieux, chose rare."}},faq={{q="Pourquoi les galestriders posent-ils problème au fermier ?",a="Les galestriders pillent le verger pour y trouver des stormapples. La récolte étant déjà maigre, leur appétit menace les réserves de nourriture locales.",al={"que volent les galestriders","pourquoi tuer les galestriders","verger de stormapples"}},{q="À quel point les galestriders des basses terres sont-ils dangereux ?",a="Les galestriders des basses terres sont plus grands et plus agressifs que leurs congénères des hautes terres. Leurs puissants coups de patte peuvent tuer un voyageur pris au dépourvu.",al={"dangerosité des galestriders","attaques de galestriders","les galestriders sont-ils forts"}},{q="Que veut le fermier aux galestriders ?",a="Le fermier veut que les voyageurs abattent les galestriders agressifs des basses terres et récupèrent leurs filets pour le dîner.",al={"viande de galestrider","butin des galestriders","quête des filets"}},{q="Où trouve-t-on ces galestriders ?",a="Les galestriders irascibles des basses terres parcourent les Plaines Aérelles, surtout près des fermes et des vergers où ils cherchent des stormapples.",al={"où trouver les galestriders","emplacement des galestriders","plaines aérelles"}},{q="En quoi les galestriders des basses terres diffèrent-ils de ceux des hautes terres ?",a="Les galestriders des basses terres sont plus grands et plus irascibles que leurs congénères des hautes terres. Leurs coups de patte peuvent blesser gravement un voyageur.",al={"galestriders des hautes terres ou des basses terres","variétés de galestriders"}},{q="Que sont les stormapples ?",a="Les stormapples sont des fruits cultivés dans les vergers de la région. La récolte étant maigre, il faut protéger les arbres restants des galestriders en quête de nourriture.",al={"que sont les stormapples","récolte du verger"}}},fp="26,213,21.253.0,15.241.0,57.126.0,40.136.0,48.109.0,35.132.0,63.120.0,21.141.0"}
P.entries["quest:92685"] = {n="The Hills Have Eyes",s="Aamelia fait face à une attaque de bandits dans les Plaines Aérelles, et le raid de Ferauu approche. Elle envoie des voyageurs attaquer un camp dans les collines du nord avant que les bandits ne se rassemblent.",h="Aamelia fait face à une attaque de bandits dans les Plaines Aérelles, et le raid de Ferauu approche.",kw={"aamelia","masques de bandits","masques de bandits tachés de sang","ferauu","plaines aérelles","bandits de grand chemin","the hills have eyes"},ang={["profession:Tailoring"]="Aamelia plaisante d'un ton sombre sur l'idée de coudre les masques tachés de sang des bandits pour en faire une couverture destinée à Ferauu."},sec={{t="Une frappe préventive",b="Aamelia fait face à une attaque imminente dans les Plaines Aérelles. Ferauu mène les hors-la-loi qui menacent sa ferme. Elle vous demande d'attaquer leur camp dans les collines au nord. Réduisez les rangs des bandits de grand chemin avant qu'ils ne se rassemblent. Aamelia espère ainsi affaiblir leur attaque et gagner du temps avant leur arrivée."},{t="Un nouvel espoir et des représailles",b="Aamelia vous demande de rapporter les masques tachés de sang des bandits de grand chemin tombés au combat, comme preuve de l'embuscade. D'un ton sombre, elle plaisante sur l'idée de les coudre pour en faire une couverture destinée à Ferauu. Elle se réjouit que ses bourreaux aient rencontré une vive résistance.\n\nL'attaque du campement du nord met fin à des semaines d'attente désespérée. Aamelia a retrouvé le courage d'affronter Ferauu et sa troupe principale à leur arrivée."}},faq={{q="Qu'est-ce que The Hills Have Eyes ?",a="Aamelia demande aux voyageurs d'attaquer un camp de bandits dans les collines du nord avant que les bandits de grand chemin de Ferauu ne s'en prennent à sa ferme. Elle demande aussi les masques tachés de sang des bandits tombés au combat.",al={"quête the hills have eyes","qu'est-ce que cette quête","qu'est-ce que the hills have eyes"}},{q="Qui donne la quête The Hills Have Eyes ?",a="Aamelia vous confie cette mission depuis sa ferme, dans les Plaines Aérelles. Des semaines à attendre les bandits lui ont fait redouter leur attaque.",al={"qui donne the hills have eyes","qui est aamelia","donneuse de quête aamelia"}},{q="Qui est Ferauu ?",a="Ferauu dirige la bande de bandits de grand chemin qui sévit dans les Plaines Aérelles. Sa bande menace la ferme d'Aamelia et se prépare à l'attaquer.",al={"qui est ferauu","boss ferauu","chef des bandits ferauu"}},{q="Où se trouvent les bandits de grand chemin ?",a="Les bandits de grand chemin ont des campements dans les Plaines Aérelles, notamment un petit camp dans les collines, juste au nord de la ferme d'Aamelia.",al={"bandits des plaines aérelles","où sont les bandits","camp de bandits dans les collines"}},{q="Pourquoi Aamelia veut-elle les masques tachés de sang des bandits ?",a="Aamelia demande des masques tachés de sang comme preuve de l'embuscade. L'attaque du camp des bandits permet de rééquilibrer les forces avant l'assaut de Ferauu.",al={"pourquoi récupérer les masques","pourquoi des masques tachés de sang","à quoi servent les masques"}},{q="Que se passe-t-il après avoir terminé la quête ?",a="Après l'attaque du camp dans les collines, Aamelia retrouve espoir pour sa ferme. Ferauu et les bandits qui lui restent doivent arriver d'un instant à l'autre, et elle doit affronter leur attaque.",al={"que se passe-t-il après the hills have eyes","quête suivante aamelia","attaque de ferauu"}}},fp="19,175,19.295.0,28.357.1,28.177.0,40.136.0,14.130.0,41.136.0,49.140.0,40.161.0"}
P.entries["quest:92693"] = {n="Standing Our Ground",s="Aamelia Windfield vous donne une dernière chance de vous replier sur Valanaar avant que les bandits ne se rapprochent. Vous avez aidé les défenseurs locaux à se préparer, mais la bataille à venir semble toujours perdue d’avance.",h="Aamelia Windfield vous donne une dernière chance de vous replier sur Valanaar avant que les bandits ne se...",kw={"aamelia windfield","chef des bandits","bandits","cause perdue","standing our ground","valanaar"},sec={{t="Une dernière résistance désespérée",b="Aamelia Windfield vous donne une dernière chance de regagner Valanaar sans danger. Vous avez aidé les défenseurs locaux à se préparer contre les bandits, mais la bataille qui s’annonce semble mal engagée. Allez-vous rester à leurs côtés ou partir avant l’affrontement ?"},{t="Face au chef des bandits",b="Lorsque vous signalez que vous êtes prêt, vous partez avec Aamelia Windfield affronter le chef des bandits. Vaincre le brigand met fin à la menace immédiate. Aamelia peine à reprendre son souffle, sous le choc et soulagée que leur pari ait réussi."}},faq={{q="Qui donne la quête Standing Our Ground ?",a="Aamelia Windfield vous donne une dernière chance de vous replier avant d’affronter le chef des bandits.",al={"qui donne standing our ground","donneur de quête standing our ground","pnj standing our ground"}},{q="Qui affrontez-vous dans Standing Our Ground ?",a="Vous affrontez le chef des bandits qui menace les défenseurs locaux. Aamelia rassemble son courage et affronte le chef avec vous.",al={"qui est le chef des bandits standing our ground","boss standing our ground","chef des bandits standing our ground"}},{q="Quel est le rôle de Valanaar dans cette quête ?",a="Valanaar est le village voisin où Aamelia vous propose de vous replier si vous ne voulez pas risquer votre vie dans la bataille.",al={"où se trouve valanaar standing our ground","ville de repli standing our ground","quête valanaar"}},{q="Pourquoi Aamelia décrit-elle la bataille comme une cause perdue ?",a="Aamelia et ses compagnons pensent que les chances sont contre eux. Ils voient l’affrontement comme une dernière résistance désespérée, et la survie semble presque impossible sans aide extérieure.",al={"pourquoi standing our ground est une cause perdue","histoire standing our ground","difficultés d’aamelia windfield"}},{q="Que se passe-t-il une fois l’affrontement terminé ?",a="Le chef des bandits est vaincu. Aamelia Windfield est sous le choc et soulagée que cette épreuve soit terminée, et peine à calmer les battements précipités de son cœur.",al={"que se passe-t-il après avoir vaincu le chef des bandits standing our ground","rendre la quête standing our ground","aamelia survit-elle"}},{q="Qu’est-ce qui mène à cette dernière résistance ?",a="Vous avez aidé les défenseurs à se préparer à la menace des bandits, leur donnant une chance de se battre avant l’affrontement final.",al={"prérequis standing our ground","quêtes avant standing our ground"}}},fp="19,181,22.219.0,29.228.1,40.89.0,40.122.0,43.129.0,53.169.0,44.139.0,34.117.0"}
P.entries["quest:92698"] = {n="What Is My Purpose?",s="Dans les champs du verger, un Malfunctioning Cyclone Construct erre sans but. Depuis le départ des élémentaires d’air, ses paroles brisées se répètent depuis des décennies. Aamelia Windfield connaît les souvenirs des habitants sur son passé.",h="Dans les champs du verger, un Malfunctioning Cyclone Construct erre sans but.",kw={"aamelia windfield","alvarion","construct","cyclone construct","malfunctioning cyclone construct","verger","quelle est ma raison d’être","élémentaires d’air","sculpte-vents"},ang={["class:Shaman"]="En tant que chaman, le déclin du construct pourrait vous intéresser. Les récits locaux associent son abandon et sa défaillance au départ des élémentaires d’air.",["profession:Engineering"]="En tant qu’ingénieur, les anciens mécanismes du construct pourraient vous intriguer. Leur logique tourne toujours en boucle après des siècles d’usure et sans entretien."},sec={{t="Le construct errant",b="Un Malfunctioning Cyclone Construct arpente les champs, prisonnier d’une boucle défectueuse. Des fragments étouffés s’échappent de sous son armure, répétant des erreurs et des questions sur sa raison d’être. Après des décennies de solitude, ses anciennes directives sont corrompues ou oubliées. Il en impose, mais ne menace pas les passants. Sa voix brisée résonne au-dessus du sol tandis qu’il erre sans but."},{t="Travail oublié et Sculpte-vents",b="Aamelia Windfield affirme que le construct erre dans les champs depuis des décennies, apparemment depuis le départ des élémentaires d’air. Alvarion a supposé qu’il transportait autrefois les récoltes vers des marchés lointains ou s’occupait du bétail, il y a des siècles, avant que ces terres ne deviennent un verger. Les Sculpte-vents construisaient et entretenaient des Cyclone Constructs dans les temps anciens. Les travailleurs du verger ont parlé de leur demander de réparer la machine, mais la situation n’a jamais semblé urgente. Elle continue donc d’errer, largement ignorée."}},faq={{q="Qu’est-ce que le Malfunctioning Cyclone Construct ?",a="Le Malfunctioning Cyclone Construct est une ancienne machine cuirassée qui erre dans les champs des environs. Les Sculpte-vents l’entretenaient autrefois, mais des décennies sans soins l’ont laissée en mauvais état. Sous son armure, elle répète des mots brisés et des erreurs, tout en s’interrogeant sur sa raison d’être.",al={"qu’est-ce que le construct","cyclone construct","géant construct dans les champs"}},{q="Qui est Aamelia Windfield ?",a="Aamelia Windfield vit près du verger. Elle affirme que le construct arpente les champs depuis des décennies, apparemment depuis le départ des élémentaires d’air. Les Sculpte-vents prenaient autrefois soin de ce genre de machines.",al={"aamelia windfield","qui est aamelia","pnj du verger"}},{q="Quelle était la fonction d’origine du construct ?",a="La fonction d’origine du construct est inconnue. Aamelia Windfield dit qu’Alvarion pensait qu’il transportait peut-être les récoltes au marché ou s’occupait du bétail, il y a des siècles, avant l’existence du verger.",al={"fonction du construct","que faisait le construct","travail du construct"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents sont un ancien groupe qui construisait et entretenait des Cyclone Constructs. Les ouvriers agricoles du coin ont parlé de leur demander de l’aide, mais le construct n’a suscité aucune inquiétude urgente.",al={"sculpte-vents","qui a créé le construct","qui entretient les cyclone constructs"}},{q="Pourquoi le construct répète-t-il des paroles fragmentées ?",a="Le construct répète des paroles fragmentées parce que son fonctionnement est défectueux. Il est resté sans soins pendant des décennies, depuis le départ des élémentaires d’air. Ses paroles comprennent des questions sur sa raison d’être et des rapports d’erreurs.",al={"pourquoi le construct parle","erreur de fonctionnement du construct","que dit-il"}},{q="Pourquoi les habitants n’ont-ils pas réparé ou démantelé le construct ?",a="Les habitants n’ont pas réparé ni démantelé le construct, car il ne représente aucune menace et erre paisiblement parmi les arbres et les cultures du verger. Aamelia Windfield et d’autres habitants ont parlé de demander aux Sculpte-vents de l’entretenir, mais aucun besoin urgent ne s’est présenté.",al={"pourquoi ignorer le construct","pourquoi ne pas réparer le construct","le construct est-il dangereux"}},{q="Qui est Alvarion ?",a="Alvarion est un habitant du coin qu’Aamelia Windfield mentionne lorsqu’elle parle du passé du construct. Il pensait que celui-ci avait peut-être transporté les récoltes au marché ou gardé le bétail, avant que ces terres ne deviennent un verger.",al={"alvarion","qui est alvarion","théorie d’alvarion"}}},fp="19,220,23.373.0,35.470.0,45.276.0,25.191.0,42.187.0,24.182.0,48.216.0,60.264.0,16.201.0"}
P.entries["quest:92699"] = {n="The Supreme Magister",s="À Valanaar, Elaadrin Evengale attire les nouveaux venus vers l’Ordre suprême. Depuis un pavillon au sud-est de la colonie, l’ordre cherche des alliés face aux Sculpte-vents hostiles et à une secte proche.",h="À Valanaar, Elaadrin Evengale attire les nouveaux venus vers l’Ordre suprême.",kw={"arcanique","secte","elaadrin evengale","ordre suprême","rathiril","the supreme magister","valanaar","sculpte-vents"},ang={["class:Mage"]="En tant que mage, vous dégagez une aura arcanique qu’Elaadrin reconnaît. Il estime l’aptitude rare et la détermination nécessaires pour maîtriser les arcanes et préserver votre patrie."},sec={{t="L’Ordre suprême de Valanaar",b="Les nouveaux venus prometteurs de Valanaar sont dirigés vers l’Ordre suprême. Supreme Magister Elaadrin Evengale le dirige depuis un pavillon situé à l’extrême sud-est de la colonie. Il observe attentivement les nouveaux arrivants, à la recherche de la force, de la détermination et de l’aura arcanique nécessaires pour affronter les dangers qui menacent leur foyer."},{t="Factions rivales et sectes menaçantes",b="La paix à Valanaar est fragile. L’Ordre suprême et les Sculpte-vents sont de farouches ennemis ; les nouveaux venus sont donc avertis de se tenir à distance des Sculpte-vents, de peur que la violence n’éclate dans les rues. Une secte dangereuse rôde à proximité. Face aux menaces qui pèsent sur la ville, ses dirigeants ne peuvent se permettre des effusions de sang à l’intérieur."}},faq={{q="Qui est Elaadrin Evengale ?",a="Elaadrin Evengale dirige l’Ordre suprême en tant que Supreme Magister. Depuis un pavillon au sud-est de Valanaar, il recherche des personnes ayant l’aptitude arcanique et la détermination nécessaires pour défendre leur foyer.",al={"qui est elaadrin evengale","elaadrin evengale","qui est le supreme magister"}},{q="Où trouver Elaadrin Evengale ?",a="Elaadrin Evengale et ses fidèles opèrent depuis un pavillon situé à l’extrême sud-est de Valanaar.",al={"où se trouve le supreme magister","où trouver elaadrin evengale","emplacement du pavillon de valanaar"}},{q="Qu’est-ce que l’Ordre suprême ?",a="L’Ordre suprême est une organisation arcanique de Valanaar, dirigée par Supreme Magister Elaadrin Evengale. Ses membres manient la puissance des arcanes pour défendre leur foyer, mais leurs rangs s’éclaircissent et les tensions montent dans la colonie.",al={"qu’est-ce que l’ordre suprême","histoire de l’ordre suprême"}},{q="Pourquoi l’Ordre suprême et les Sculpte-vents sont-ils en conflit ?",a="L’Ordre suprême et les Sculpte-vents sont de farouches rivaux à Valanaar. Les dirigeants locaux les exhortent à rester à l’écart les uns des autres pour éviter toute violence dans les rues, surtout alors que les activités d’une secte menacent la colonie.",al={"pourquoi l’ordre suprême et les sculpte-vents se battent-ils","conflit avec les sculpte-vents","tensions à valanaar"}},{q="Qui est Rathiril ?",a="Rathiril oriente les nouveaux venus prometteurs vers l’Ordre suprême de Valanaar au moyen de missives magiques. Ces messages signalent à Elaadrin Evengale les personnes dotées d’un potentiel remarquable.",al={"qui est rathiril","missive de rathiril"}},{q="Quelle secte menace Valanaar ?",a="Une secte mystérieuse active aux abords de Valanaar menace la colonie. Les autorités locales s’efforcent d’apaiser les conflits entre des groupes tels que l’Ordre suprême et les Sculpte-vents afin de protéger Valanaar.",al={"quelle secte à valanaar","menace de la secte à valanaar"}}},fp="20,192,26.282.0,32.298.0,25.178.0,37.84.0,23.227.0,65.198.0,16.163.0,29.190.0"}
P.entries["quest:927"] = {n="Le cœur moussu",s="Près du lac Al'Ameth, Denalan étudie un cœur prélevé sur Blackmoss the Fetid. Une mousse sombre et huileuse recouvre le noyau, qui continue pourtant de battre après avoir été séparé du scion de bois.",h="Près du lac Al'Ameth, Denalan étudie un cœur prélevé sur Blackmoss the Fetid.",kw={"blackmoss the fetid","fléau","corruption","denalan","lac al'ameth","coeur moussu","teldrassil","scion de bois"},ang={["class:Druid"]="En tant que druide, vous vous intéressez vivement à un cœur palpitant et flétri comme celui-ci. Vous cherchez à savoir si sa corruption peut être purifiée ou si elle annonce un mal plus profond.",["profession:Herbalism"]="En tant qu'étudiant des plantes, vous voyez que la croissance huileuse sur ce noyau est contre nature. Elle défie les propriétés botaniques ordinaires en maintenant en vie un cœur séparé de son corps.",["race:NightElf"]="En tant que kaldorei, vous voyez le jeune Arbre-monde Teldrassil engendrer des scions de bois corrompus et agressifs comme Blackmoss. Leur fléau est un signe inquiétant : votre nouveau foyer est rongé par une maladie insidieuse."},sec={{t="Un noyau palpitant",b="Le cœur de Blackmoss the Fetid bat encore après avoir été séparé du scion de bois. Une mousse sombre et huileuse dissimule presque tout le noyau, mais un rythme lent persiste en son sein. Cette pulsation révèle une corruption qui dépasse le pourrissement ordinaire des plantes sauvages de Teldrassil."},{t="L'examen de Denalan",b="Denalan étudie la flore locale près du lac Al'Ameth, et ce cœur retient vivement son attention. Il reconnaît la corruption inquiétante qui l'affecte. Les scions de bois devraient être des êtres paisibles, liés aux branches de l'Arbre-monde, mais ce noyau est atteint d'un fléau virulent.\n\nTroublé par ce qu'il observe et désireux de comprendre, Denalan prévoit de planter l'organe pour l'étudier. Il espère découvrir comment cette mousse infecte prend racine dans le sol de l'île."}},faq={{q="D'où vient le cœur moussu ?",a="Ce cœur vient de Blackmoss the Fetid, un grand scion de bois très corrompu qui erre dans les étendues sauvages de Teldrassil.",al={"où trouver le cœur","butin du cœur moussu","cœur de blackmoss the fetid"}},{q="Pourquoi le cœur bat-il encore ?",a="La mousse sombre et huileuse semble maintenir le cœur en vie par une vigueur contre nature. Bien qu'il ait été séparé du scion de bois, il continue de battre lentement et régulièrement.",al={"pourquoi le cœur palpite","cœur qui bat encore","battement du cœur d'un scion de bois"}},{q="Qui est Denalan ?",a="Denalan est un naturaliste elfe de la nuit qui s'occupe d'une pépinière près du lac Al'Ameth. Il étudie la flore de Teldrassil, ses jeunes pousses et la corruption qui gagne les scions de bois de l'île.",al={"qui est denalan","où se trouve denalan","emplacement de denalan"}},{q="Que fera Denalan du cœur ?",a="Denalan prévoit de planter le cœur dans un pot enchanté pour le faire germer. En isolant la mousse infecte, il espère découvrir la cause de cette croissance flétrie.",al={"que devient le cœur","quête planting the heart","recherches de denalan sur le cœur"}},{q="Que sont censés être les scions de bois ?",a="Les scions de bois sont des élémentaires végétaux naturellement paisibles, nés de la forêt. Des forces obscures et une souillure contre nature en ont rendu beaucoup fous et agressifs à travers Teldrassil.",al={"que sont les scions de bois","histoire des scions de bois","les scions de bois sont-ils maléfiques"}},{q="La corruption du cœur est-elle magique ou naturelle ?",a="Cette mousse huileuse et infecte évoque un fléau contre nature qui frappe les plantes indigènes de Teldrassil, plutôt qu'une décomposition ordinaire à l'état sauvage.",al={"la mousse est-elle magique","origine de la mousse infecte","fléau de mousse à teldrassil"}}},fp="21,166,14.241.0,21.405.0,43.120.0,31.138.0,15.184.0,36.156.0,36.158.0,50.119.0"}
P.entries["quest:92700"] = {n="The Grand Skyseer",s="À Valanaar, les Sculpte-vents recherchent des voyageurs doués de vision spirituelle. Ils vous envoient auprès d’Ayessa Dawnsinger à leur pavillon, tandis que rivalités et culte menaçant mettent la colonie à rude épreuve.",h="À Valanaar, les Sculpte-vents recherchent des voyageurs doués de vision spirituelle.",kw={"ayessa dawnsinger","elder amberwind","ordre suprême","shen’dar","skysight","the grand skyseer","valanaar","sculpte-vents","zephras"},ang={["class:Druid"]="En tant que druide, vous pourriez trouver des esprits semblables aux vôtres parmi les Sculpte-vents. Ils perçoivent les auras spirituelles et observent les changements subtils dans les cieux.",["class:Shaman"]="En tant que chaman, vous pourriez trouver en Ayessa Dawnsinger un contact important. Elle reconnaît les voyageurs en harmonie avec les esprits et doués pour les affaires spirituelles."},sec={{t="Arrivée à Valanaar",b="Vous arrivez à Valanaar et êtes dirigé vers le pavillon central. Les Sculpte-vents s’y réunissent autour de The Grand Skyseer Ayessa Dawnsinger. Elder Amberwind a entendu parler de vos exploits à Shen’dar et vous accueille parmi ceux qui sont en harmonie avec les esprits. Des dangers vous guettent au-delà de la ville comme en son sein. Avancez donc prudemment dans ses jeux politiques fragiles."},{t="Rivalités et culte menaçant",b="La paix à Valanaar ne tient qu’à un fil. Les Sculpte-vents et l’Ordre suprême s’opposent ouvertement, et des escarmouches dans les rues menacent la colonie. Un culte obscur menace aussi la région. Les dirigeants locaux ont ordonné aux deux factions de garder leurs distances et d’affronter ce danger commun au lieu de se disputer le territoire."},{t="Le skysight se raréfie",b="The Grand Skyseer Ayessa Dawnsinger affirme que le skysight se raréfie parmi les habitants de Zephras. Les voyageurs qui arrivent dotés d’une aura puissante et en harmonie avec les esprits sont des alliés indispensables. Les Sculpte-vents en ont besoin pour guider leur terre à travers ces temps difficiles."}},faq={{q="Qui est The Grand Skyseer ?",a="Ayessa Dawnsinger dirige les Sculpte-vents à Valanaar et les guide sur le plan spirituel. Elle accueille les voyageurs au pavillon près du centre de la colonie, en particulier ceux qui résonnent avec les esprits et possèdent le rare don du skysight.",al={"qui est the grand skyseer","ayessa dawnsinger qui est-elle","qui est ayessa"}},{q="Où trouver Ayessa Dawnsinger ?",a="Ayessa Dawnsinger se trouve au pavillon des Sculpte-vents, près du centre de Valanaar. Elle attend les voyageurs venus de Shen’dar qui lui apportent des nouvelles de leurs exploits récents, rapportées par Elder Amberwind.",al={"où trouver ayessa dawnsinger","où se trouve le pavillon de the grand skyseer","emplacement d’ayessa à valanaar"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents forment une communauté spirituelle à Valanaar, où ils sont dirigés par The Grand Skyseer Ayessa Dawnsinger. Ils étudient les cieux et communient avec les esprits, malgré les vives tensions avec l’Ordre suprême.",al={"que sont les sculpte-vents","faction des sculpte-vents à valanaar"}},{q="Pourquoi les Sculpte-vents s’opposent-ils à l’Ordre suprême ?",a="Les Sculpte-vents et l’Ordre suprême s’affrontent au sujet des esprits du vent. L’Ordre suprême se méfie de leurs intentions et cherche à comprendre les pouvoirs du Mur-Céleste. Les Sculpte-vents font confiance aux élémentaires et prennent ces doutes pour une insulte. Toute violence dans les rues est interdite, surtout alors qu’un culte menace la région.",al={"conflit entre les sculpte-vents et l’ordre suprême","pourquoi l’ordre suprême en veut aux sculpte-vents","ordre suprême à valanaar"}},{q="Qu’est-ce que le don du skysight ?",a="Le skysight est une rare perception spirituelle que possèdent peu d’habitants de Zephras. Il leur permet de sentir les auras spirituelles et de communier avec des forces invisibles. Selon Ayessa, ce don se raréfie, ce qui rend ses détenteurs indispensables en ces temps difficiles.",al={"qu’est-ce que le skysight","don du skysight à zephras"}},{q="Qui est Elder Amberwind ?",a="Elder Amberwind est une personnalité respectée de Shen’dar. Elder Amberwind évalue les voyageurs et transmet à Valanaar des nouvelles de leurs exploits et de leur résonance spirituelle. Elder Amberwind dirige les plus dignes vers The Grand Skyseer Ayessa Dawnsinger.",al={"qui est elder amberwind","amberwind à shen’dar"}}},fp="17,185,19.340.0,27.313.0,19.244.0,25.226.0,37.185.0,24.199.0,49.292.0,29.232.0,23.222.0"}
P.entries["quest:92701"] = {n="To Valanaar",s="À Valanaar, Valennia Stormfist doit faire face à la menace grandissante du culte. Aonda envoie des nouvelles urgentes de Shen'dar, où le village et son pylône ont été défendus.",h="À Valanaar, Valennia Stormfist doit faire face à la menace grandissante du culte.",kw={"aonda","culte","pacificateurs","pylône","shen'dar","to valanaar","valanaar","valennia stormfist"},sec={{t="Message de Shen'dar",b="Après la défense de Shen'dar et de son pylône, Aonda envoie un messager de confiance à travers l'île. Le message est destiné à Valanaar, à l'extrémité sud-est de l'île. Là-bas, la commandante des pacificateurs doit apprendre à quelle vitesse le culte progresse."},{t="La tempête se lève",b="Valennia Stormfist et ses pacificateurs tentent depuis longtemps d'éviter un conflit ouvert avec le culte qui se répand sur l'île. Pourtant, les événements de Shen'dar marquent un tournant. L'influence du culte grandit, et Valennia ne peut plus empêcher l'affrontement. Ses troupes, de moins en moins nombreuses, doivent préparer Valanaar à un assaut."}},faq={{q="Qui est Valennia Stormfist ?",a="Valennia Stormfist commande les pacificateurs stationnés à Valanaar. Elle est chargée de protéger les habitants de l'île, tandis que sa petite garnison fait face à une activité grandissante du culte.",al={"qui est valennia stormfist","valennia","chef des pacificateurs"}},{q="Qui est Aonda ?",a="Aonda est une montagnarde stationnée à Shen'dar. Après avoir sécurisé un pylône et défendu le village contre les cultistes, elle confie à un voyageur son rapport écrit à l'intention de Valennia.",al={"qui a envoyé le rapport","montagnarde rusée","aonda"}},{q="Qu'est-ce que Valanaar ?",a="Valanaar se trouve à l'extrémité sud-est de l'île. C'est la base de Valennia Stormfist et des pacificateurs qui défendent les habitants de l'île.",al={"qu'est-ce que valanaar","où se trouve valanaar","emplacement de valanaar"}},{q="Quelle menace le culte fait-il peser sur l'île ?",a="Un culte en pleine expansion se répand sur l'île et s'en prend aux villages et aux pylônes sacrés. Les pacificateurs évitaient autrefois les affrontements directs, mais les défenseurs de Valanaar doivent maintenant se préparer au combat.",al={"quel culte","qui attaque","expansion du culte"}},{q="Qu'est-ce que Shen'dar ?",a="Shen'dar est un village situé près d'un pylône vital de l'île. Ses habitants ont récemment repoussé les cultistes pour protéger le village et le pylône, et ses dirigeants entretiennent des liens étroits avec les pacificateurs de Valanaar.",al={"qu'est-ce que shen'dar","shen'dar","village et pylône"}},{q="Que contient le rapport d'Aonda ?",a="Le rapport écrit d'Aonda raconte la défense de Shen'dar et de son pylône. Il avertit Valennia que le culte se répand trop rapidement pour qu'un affrontement direct puisse être évité.",al={"que contient le rapport d'aonda","contenu du rapport écrit","que dit la lettre"}}},fp="11,154,22.249.0,19.303.0,26.173.0,13.170.0,17.143.0,40.200.0,17.194.0,36.162.0"}
P.entries["quest:92703"] = {n="Deliver the News",s="Au Verger Champ-des-Vents, Aamelia annonce que sa famille est saine et sauve. Alvarion attend à Valanaar, où il est parti chercher de l’aide.",h="Au Verger Champ-des-Vents, Aamelia annonce que sa famille est saine et sauve.",kw={"aamelia","alvarion windfield","assemblage","deliver the news","verger","mur-céleste","valanaar","windfield","façonneur de vent"},ang={["race:Skyborne"]="En tant que Skyborne, vous entendez Alvarion évoquer les héros que son peuple connaissait par les récits avant son arrivée au Mur-Céleste. Leur souvenir rappelle les origines et l’héritage de votre peuple avant la migration."},sec={{t="Le verger est soulagé",b="Aamelia vous remercie d’avoir sauvé le verger de la famille Windfield. Son foyer est en sécurité, mais Alvarion Windfield est parti à Valanaar pour implorer de l’aide. Il doit savoir que sa famille et son foyer ne courent plus aucun danger."},{t="Un secret pour l’avenir",b="Aamelia demande à Alvarion de trouver un façonneur de vent qualifié une fois rétabli. Un assemblage se trouve encore au verger, et un expert doit l’examiner pour s’assurer qu’il ne représente aucune menace.\n\nAamelia attend un enfant. Elle vous demande de ne rien dire à Alvarion avant qu’il soit rentré sain et sauf chez lui, en personne."},{t="Un héros à Valanaar",b="Alvarion Windfield est submergé par l’émotion lorsque vous lui annoncez que sa famille et son foyer sont en sécurité. Il est parti pour Valanaar, convaincu que sa recherche d’aide était un espoir désespéré, presque vain. Votre réussite lui rappelle les héros légendaires dont son peuple se souvenait avant son arrivée au Mur-Céleste. La famille Windfield vous accueille chez elle pour toujours."}},faq={{q="Qu’est-ce que la quête Deliver the News ?",a="Aamelia vous demande de vous rendre à Valanaar et d’annoncer à son compagnon, Alvarion Windfield, qu’elle est saine et sauve et que le danger au verger est écarté.",al={"quête deliver the news","que signifie deliver the news","qui donne la quête deliver the news"}},{q="Qui est Alvarion Windfield ?",a="Alvarion Windfield vit au Mur-Céleste et se rétablit à Valanaar. Il est parti pour la ville chercher de l’aide pour le verger de sa famille, craignant que tout espoir ne soit perdu avant votre arrivée.",al={"qui est alvarion windfield","où se trouve alvarion","lieu où se trouve alvarion"}},{q="Qui est Aamelia ?",a="Aamelia vit au domaine Windfield et cultive le verger avec Alvarion. Reconnaissante de votre aide, elle vous demande de lui annoncer à Valanaar qu’ils sont sains et saufs.",al={"qui est aamelia","donneuse de quête aamelia"}},{q="Que cache Aamelia à Alvarion ?",a="Aamelia vous confie qu’elle attend un enfant. Elle vous demande de ne rien dire à Alvarion avant qu’il soit rétabli et rentré chez lui.",al={"quel est le secret d’aamelia","aamelia pose la main sur son ventre","aamelia est-elle enceinte"}},{q="Pourquoi Aamelia veut-elle qu’un façonneur de vent vienne au verger ?",a="Aamelia veut qu’Alvarion amène un façonneur de vent au verger après son rétablissement. Ce spécialiste pourra examiner un assemblage qui s’y trouve et vérifier qu’il ne présente aucun danger pour leur famille qui va s’agrandir.",al={"pourquoi un assemblage et un façonneur de vent","quel assemblage aamelia mentionne-t-elle","assemblage windfield"}},{q="Où se déroule cette quête ?",a="L’histoire vous mène du Verger Champ-des-Vents à Valanaar, une colonie du Mur-Céleste où ces colons ont établi leur foyer.",al={"où se déroule deliver the news","quête valanaar mur-céleste"}}},fp="16,125,21.196.0,23.287.1,18.337.0,35.135.0,26.168.0,15.161.0,44.134.0,58.181.0,33.126.0"}
P.entries["quest:92706"] = {n="WANTED: Bruuz",s="Bruuz menace les navires qui font vivre Cabestan. Gazlowe a affiché une prime pour le gigantesque requin qui rôde près des quais et perturbe le commerce côtier.",h="Bruuz menace les navires qui font vivre Cabestan.",kw={"les tarides","prime","bruuz","aileron dorsal","gazlowe","cabestan","requin","gentepression"},ang={["class:Hunter"]="En tant que chasseur, vous pouvez mettre votre patience et votre adresse à l'épreuve contre Bruuz, un gigantesque prédateur aquatique.",["profession:Cooking"]="En tant que cuisinier, vous pourriez utiliser la viande fraîche d'un requin aussi imposant que Bruuz. Gazlowe ne veut que l'aileron dorsal comme preuve de sa mise à mort."},sec={{t="Une terreur dans la baie",b="Cabestan est la principale porte d'entrée neutre de Kalimdor vers les Royaumes de l'est. Son commerce dépend des navires marchands. Depuis peu, un gigantesque requin nommé Bruuz rôde dans la baie. Les dockers lui ont donné ce nom après qu'il s'est mis à attaquer les petites barques, les marins et les cargaisons déchargées près des quais. Le requin perturbe le port et menace les navires qui approvisionnent Cabestan."},{t="La prime de Gazlowe",b="Gazlowe a affiché une prime publique pour que les navires ne désertent pas son port par peur du requin. L'avis appelle les pêcheurs et promet une belle récompense. Pour la réclamer, vous devez tuer Bruuz et rapporter son aileron dorsal en guise de preuve."}},faq={{q="Qui est Bruuz ?",a="Bruuz est un gigantesque requin agressif qui chasse près des quais marchands de Cabestan. Les dockers lui ont donné son nom après ses attaques contre les marins et les petites embarcations.",al={"qui est bruuz","requin bruuz","qui est bruuz le requin"}},{q="Pourquoi Gazlowe a-t-il mis une prime sur Bruuz ?",a="Bruuz perturbe le transport maritime et le commerce qui alimentent l'économie de Cabestan. Gazlowe offre de l'argent pour la carcasse du requin afin de protéger les affaires sur les quais.",al={"pourquoi tuer bruuz","quête du requin de gazlowe","pourquoi veut-il l'aileron de bruuz"}},{q="Où trouve-t-on généralement Bruuz ?",a="Bruuz rôde dans les eaux au large de Cabestan, dans Les Tarides, souvent près des principaux quais marchands et de l'entrée du port.",al={"emplacement de bruuz","où se trouve bruuz","trouver bruuz"}},{q="Quelle preuve Gazlowe exige-t-il pour confirmer la mise à mort ?",a="Gazlowe exige l'aileron dorsal de Bruuz comme preuve que le requin a été tué avant de verser la prime.",al={"rendre la quête de bruuz","que rapporter à gazlowe","aileron dorsal de bruuz"}},{q="Les aventuriers de l'Alliance et de la Horde peuvent-ils tous deux accepter cette prime ?",a="Oui. Cabestan est dirigée par le Cartel Gentepression, qui reste neutre, et Gazlowe accueille les aventuriers capables des deux factions pour s'occuper du requin.",al={"la prime sur bruuz est-elle neutre","la horde peut-elle faire la prime sur bruuz","l'alliance peut-elle faire la quête de bruuz"}},{q="Pourquoi la prime s'adresse-t-elle précisément aux pêcheurs ?",a="L'avis n'explique pas pourquoi il s'adresse aux pêcheurs. Il commence par « Avis aux pêcheurs ! » et promet une belle récompense pour l'aileron de Bruuz.",al={"avis aux pêcheurs bruuz","est-ce une quête de pêche"}}},fp="13,145,19.347.0,16.231.0,13.141.0,39.144.0,29.107.0,45.101.0,57.140.0,50.139.0"}
P.entries["quest:92708"] = {n="A Grand Adventure",s="Sur l’Île de Zéphras, Ayessa Dawnsinger et les Sculpte-vents cherchent à sauver leur foyer. L’île se trouve dans Mur-Céleste, où les esprits du vent ont disparu sans explication.",h="Sur l’Île de Zéphras, Ayessa Dawnsinger et les Sculpte-vents cherchent à sauver leur foyer.",kw={"a grand adventure","ayessa dawnsinger","azeroth","mur-céleste","esprits du vent","sculpte-vents","île de zéphras"},ang={["race:Skyborne"]="En tant que Skyborne de Mur-Céleste, vous faites face à un grand changement. Vous quittez votre foyer élémentaire pour chercher le salut de l’Île de Zéphras en Azeroth."},sec={{t="La crise de l’Île de Zéphras",b="Les esprits du vent ont disparu de l’Île de Zéphras, et la situation ne cesse de s’aggraver. Les Sculpte-vents ont enquêté sur les perturbations et découvert des vérités sur leurs congénères disparus et le destin de leur foyer élémentaire. Ayessa Dawnsinger vous demande de tenir compte de leurs découvertes et de vous préparer à une entreprise sans précédent."},{t="Une expédition au-delà de Mur-Céleste",b="Ayessa Dawnsinger pense que Mur-Céleste ne dispose ni de la puissance ni du savoir nécessaires pour sauver l’Île de Zéphras. Elle a conclu que le salut se trouve en contrebas, dans le monde mortel d’Azeroth. Quitter leur terre natale rompt avec la tradition. L’avenir de l’île dépend de ceux qui sont prêts à s’aventurer dans l’inconnu."}},faq={{q="Que raconte la quête A Grand Adventure ?",a="Ayessa Dawnsinger demande de l’aide alors que les esprits du vent disparaissent de l’Île de Zéphras. Les Sculpte-vents pensent que sauver leur foyer exige de quitter Mur-Céleste pour rejoindre Azeroth.",al={"que raconte cette quête","quête a grand adventure","que raconte a grand adventure"}},{q="Qui est Ayessa Dawnsinger ?",a="Ayessa Dawnsinger est une Sculpte-vent de l’Île de Zéphras. Elle enquête sur la crise et demande aux aventuriers capables de tenir compte des découvertes des Sculpte-vents.",al={"qui est ayessa","dawnsinger","qui est ayessa dawnsinger"}},{q="Quelle crise frappe l’Île de Zéphras ?",a="Les esprits du vent ont disparu de l’Île de Zéphras sans explication. Les Sculpte-vents enquêtent sur les perturbations et cherchent un moyen de sauver leur foyer.",al={"quelle est la crise de l’île de zéphras","que s’est-il passé sur l’île de zéphras","problème de l’île de zéphras"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents enquêtent sur les perturbations et la disparition des esprits du vent qui menacent l’Île de Zéphras.",al={"qui sont les sculpte-vents","sculpte-vents île de zéphras"}},{q="Pourquoi les Sculpte-vents doivent-ils se rendre en Azeroth ?",a="Ayessa Dawnsinger pense que Mur-Céleste ne dispose ni de la puissance ni du savoir nécessaires pour sauver l’Île de Zéphras. Elle pense qu’ils doivent chercher le salut en Azeroth, en contrebas.",al={"pourquoi aller en azeroth","pourquoi quitter mur-céleste","voie du salut"}},{q="Qu’est-ce que Mur-Céleste ?",a="Mur-Céleste est le royaume élémentaire des Sculpte-vents et de l’Île de Zéphras, au-dessus du monde mortel d’Azeroth.",al={"qu’est-ce que mur-céleste","où se trouve mur-céleste"}}},fp="17,165,26.318.0,24.283.1,36.158.0,25.150.0,44.145.0,24.95.0,49.142.0,16.107.0"}
P.entries["quest:92709"] = {n="A Grand Adventure",s="À Valanaar, Elaadrin Evengale vous demande d’écouter les projets de l’Ordre suprême. Sa quête d’une magie ancienne pourrait façonner l’avenir de l’Île de Zéphras.",h="À Valanaar, Elaadrin Evengale vous demande d’écouter les projets de l’Ordre suprême.",kw={"a grand adventure","magie ancienne","elaadrin evengale","ordre suprême","bien-nés","kirin tor","valanaar","île de zéphras"},sec={{t="Un héritage perdu",b="Elaadrin évoque votre lignée des Bien-nés et les jeunes gens qui pourraient aider à sauver leur foyer. L’Ordre suprême cherche la magie ancienne de ses ancêtres et ce qui a été perdu au fil de nombreux millénaires."},{t="La voie à suivre",b="Elaadrin affirme qu’Azeroth est essentielle à cette quête. Le Kirin Tor indiquera la voie à l’Ordre suprême. Pendant que ses membres se préparent à partir, vous pouvez parler aux autres à Valanaar. Beaucoup ont besoin d’aide pour leurs tâches."}},faq={{q="Qui me demande d’écouter ?",a="Elaadrin Evengale, à Valanaar, vous demande d’écouter les projets de l’Ordre suprême.",al={"qui est elaadrin","elaadrin evengale","qui veut parler"}},{q="Que cherche l’Ordre suprême à redécouvrir ?",a="L’Ordre suprême cherche la magie ancienne de ses ancêtres et ce qui a été perdu au fil de nombreux millénaires.",al={"que cherchent-ils","magie ancienne","projets de l’ordre suprême"}},{q="Pourquoi l’Ordre suprême cherche-t-il une magie ancienne ?",a="Elaadrin affirme que redécouvrir cette magie est essentiel pour percer les secrets de l’Île de Zéphras et assurer son avenir.",al={"pourquoi la magie ancienne","sauver zéphras","avenir de l’île"}},{q="Qui leur indiquera la voie ?",a="Elaadrin affirme que le Kirin Tor indiquera la voie à l’Ordre suprême.",al={"kirin tor","qui les guide","projet pour azeroth"}},{q="Que puis-je faire pendant qu’ils se préparent à partir ?",a="Pendant qu’ils se préparent à partir, vous pouvez parler aux autres membres de l’Ordre suprême à Valanaar. La plupart ont besoin d’aide pour leurs tâches.",al={"aide à valanaar","autres membres de l’ordre suprême","que faire ensuite"}}},fp="17,139,15.193.0,13.195.1,27.72.0,44.90.0,43.111.0,27.61.0,42.124.0"}
P.entries["quest:92727"] = {n="The Missing Scholar",s="Fillion Flamebreeze a disparu après être parti étudier la magie atmosphérique sur Zephras. L’Ordre suprême l’a envoyé vers les Hautes-terres de Shen’dar, et l’inquiétude grandit : la route depuis Valanaar n’a donné aucune nouvelle de son retour.",h="Fillion Flamebreeze a disparu après être parti étudier la magie atmosphérique sur Zephras.",kw={"sacoche ensanglantée","fillion flamebreeze","ordre suprême","hautes-terres de shen’dar","the missing scholar","valanaar","magie portée par le vent","zephras"},ang={["class:Mage"]="En tant que Mage, vous partagez la curiosité de Flamebreeze pour les courants arcaniques portés par le vent qui se rassemblent dans les hautes-terres de Zephras.",["race:Skyborne"]="En tant que Skyborne, vous savez que les vents et la magie atmosphérique de Zephras suscitent un vif intérêt. Les dangers cachés rendent le terrain périlleux, même pour les érudits."},sec={{t="La mission de l’Ordre suprême",b="L’Ordre suprême rassemble et préserve le savoir sur Zephras. Pourtant, les recherches de terrain sur l’île sont devenues périlleuses. Fillion Flamebreeze est parti vers les Hautes-terres de Shen’dar pour étudier les phénomènes arcaniques atmosphériques, mais n’a jamais fait son rapport. Ses pairs craignent désormais que les dangers des routes frontalières ne l’aient emporté."},{t="Des traces sur la route de l’ouest",b="Fillion Flamebreeze a quitté Valanaar et pris la direction de l’ouest, vers les Hautes-terres de Shen’dar. Il comptait y étudier la magie portée par le vent qui s’accumule parmi les sommets. Il a disparu avant d’achever son voyage. Le long de la route, les recherches ne permettent de retrouver que sa sacoche personnelle dans la poussière. Du sang séché la macule, et ses chances d’avoir survécu semblent bien minces."}},faq={{q="Qui est Fillion Flamebreeze ?",a="Fillion Flamebreeze est un érudit de l’Ordre suprême sur Zephras. Il est parti étudier la magie portée par le vent dans les Hautes-terres de Shen’dar, puis a disparu en chemin.",al={"qui est fillion flamebreeze","histoire de fillion flamebreeze","qui est l’érudit disparu"}},{q="Qu’est-il arrivé à Fillion Flamebreeze ?",a="Fillion Flamebreeze n’a jamais atteint sa destination. Sa sacoche abandonnée se trouve le long de la route de l’ouest vers les Hautes-terres de Shen’dar. Son nom brodé et les traces de sang séché suggèrent qu’il a été attaqué.",al={"qu’est-il arrivé à fillion","fillion est-il mort","sort de fillion flamebreeze"}},{q="Qu’est-ce que l’Ordre suprême ?",a="L’Ordre suprême rassemble et préserve le savoir sur Zephras. Ses activités sont devenues plus périlleuses face aux phénomènes magiques sauvages et aux menaces qui rôdent sur les routes.",al={"mission de l’ordre suprême","que fait l’ordre suprême","ordre suprême zephras"}},{q="Pourquoi Fillion se rendait-il dans les Hautes-terres de Shen’dar ?",a="Fillion Flamebreeze s’est rendu dans les Hautes-terres de Shen’dar pour consigner d’étranges courants de magie portée par le vent qui s’accumulent et circulent dans certaines parties des hautes-terres.",al={"où allait fillion","magie du vent shen’dar","pourquoi est-il allé dans les hautes-terres"}},{q="Où Fillion Flamebreeze a-t-il été vu pour la dernière fois ?",a="La sacoche ensanglantée de Fillion Flamebreeze se trouve le long de la route qui part vers l’ouest depuis Valanaar et grimpe vers les Hautes-terres de Shen’dar.",al={"où se trouve la sacoche","emplacement de la sacoche de fillion","route depuis valanaar"}},{q="Qu’est-ce que la magie portée par le vent des Hautes-terres de Shen’dar ?",a="La magie portée par le vent se compose de courants arcaniques atmosphériques qui se rassemblent naturellement en certains lieux élevés de Zephras. Les Hautes-terres de Shen’dar sont un sujet majeur de recherche arcanique.",al={"qu’est-ce que la magie portée par le vent de zephras","magie du vent des hautes-terres"}}},fp="19,224,24.308.0,26.321.1,27.158.0,37.214.0,23.152.0,53.139.0,40.129.0,54.177.0"}
P.entries["quest:92741"] = {n="Unwelcome Visitors",s="Dans la Forêt de Trombenoire, les criailleuses gagnent du terrain vers la lisière. À Valanaar, Iaadaria Bitterwind demande aux voyageurs de récolter leurs serres pour l’Ordre suprême.",h="Dans la Forêt de Trombenoire, les criailleuses gagnent du terrain vers la lisière.",kw={"propriétés alchimiques","iaadaria bitterwind","forêt de trombenoire","criailleuse","serres de criailleuse","l’ordre suprême","unwelcome visitors","valanaar"},ang={["class:Druid"]="En tant que druide, vous pouvez percevoir la croissance soudaine des criailleuses et leur expansion comme un déséquilibre dans la Forêt de Trombenoire. Il faut agir vite pour rétablir l’équilibre naturel de la forêt.",["class:Hunter"]="En tant que chasseur, vous pouvez suivre les criailleuses trop nombreuses de la Forêt de Trombenoire et en réduire la population. Vous assumez le travail des gardiens et des trappeurs, une tâche que l’Ordre suprême dédaigne."},sec={{t="La vague des criailleuses",b="La Forêt de Trombenoire est un bois dangereux où les aventuriers ordinaires n’ont pas le droit d’entrer. Les criailleuses y sont désormais plus nombreuses que jamais. Elles gagnent du terrain vers la lisière et étendent leurs territoires de chasse au-delà de la canopée. Si elles continuent de se répandre, les terres habitées et les routes seront de plus en plus menacées."},{t="Une élimination savante",b="À Valanaar, Iaadaria Bitterwind, de l’Ordre suprême, voit dans la prolifération des criailleuses à la fois un danger et une occasion. L’Ordre laisse généralement à d’autres le soin de lutter contre les nuisibles et de poser des pièges. Pourtant, les serres de criailleuse possèdent de rares propriétés alchimiques qui justifient une exception. Les voyageurs sont invités à entrer dans la Forêt de Trombenoire et à rapporter huit serres. L’Ordre suprême pourra ainsi contribuer à protéger la région et à étudier ces réactifs."}},faq={{q="Qui donne la quête Unwelcome Visitors ?",a="Iaadaria Bitterwind confie cette demande à Valanaar. Chercheuse de l’Ordre suprême, elle demande aux voyageurs de chasser les criailleuses des environs et de récolter des matériaux pour ses études alchimiques.",al={"qui donne unwelcome visitors","personnage qui donne la quête unwelcome visitors","où prendre unwelcome visitors"}},{q="Pourquoi l’Ordre suprême s’intéresse-t-il aux criailleuses ?",a="L’Ordre suprême s’intéresse aux serres des criailleuses, qui possèdent des propriétés alchimiques particulières. Bien que l’Ordre laisse généralement à d’autres le soin de poser des pièges et de lutter contre les nuisibles, Iaadaria Bitterwind voit là une occasion d’étudier de précieux réactifs tout en contribuant à protéger la région.",al={"pourquoi l’ordre suprême veut des serres","ordre suprême et criailleuses","motivation d’iaadaria bitterwind"}},{q="Pourquoi faut-il réduire la population de criailleuses ?",a="Ces derniers mois, les criailleuses de la Forêt de Trombenoire se sont considérablement multipliées. Elles quittent leur territoire forestier habituel et menaceront les environs si elles continuent de se répandre.",al={"pourquoi tuer les criailleuses","menace des criailleuses","pourquoi les criailleuses posent problème"}},{q="Où se trouve la Forêt de Trombenoire ?",a="La Forêt de Trombenoire se trouve près de Valanaar. Ses bois dangereux sont généralement interdits aux voyageurs ordinaires et aux aventuriers inexpérimentés, en raison de la faune violente qui les peuple.",al={"où se trouve la forêt de trombenoire","emplacement de la forêt de trombenoire","comment aller dans la forêt de trombenoire"}},{q="Que sont les criailleuses ?",a="Les criailleuses sont des bêtes prédatrices féroces originaires de la Forêt de Trombenoire. Leurs serres possèdent des propriétés alchimiques et, ces derniers mois, leur population a tellement augmenté qu’elles gagnent du terrain au-delà de la lisière.",al={"qu’est-ce qu’une criailleuse","histoire des criailleuses","quelle sorte de bêtes sont les criailleuses"}},{q="Quels objets faut-il pour terminer Unwelcome Visitors ?",a="Les voyageurs doivent rapporter huit serres de criailleuse de la Forêt de Trombenoire à Iaadaria Bitterwind, à Valanaar. Elles serviront à ses recherches savantes et alchimiques.",al={"objectifs d’unwelcome visitors","que faut-il pour unwelcome visitors","serres de criailleuse nécessaires"}},{q="Pourquoi la Forêt de Trombenoire est-elle interdite aux aventuriers ordinaires ?",a="La Forêt de Trombenoire est interdite aux aventuriers ordinaires, car sa faune est mortelle et ses bois sont traîtres. Quiconque s’y aventure, y compris les voyageurs chargés d’éliminer les criailleuses, doit se préparer à affronter de graves dangers.",al={"pourquoi la forêt de trombenoire est interdite","danger de la forêt de trombenoire","qui peut entrer dans la forêt de trombenoire"}}},fp="18,160,20.339.0,17.417.0,39.185.0,53.263.0,45.190.0,35.171.0,21.215.0,55.162.0,58.217.0"}
P.entries["quest:92742"] = {n="Testing the Wells",s="Dans toute la Marche de l’Ouest, Alba Fairmoon vous envoie tester les puits des fermes. Leurs échantillons pourraient révéler ce qui empoisonne le sol et les eaux souterraines.",h="Dans toute la Marche de l’Ouest, Alba Fairmoon vous envoie tester les puits des fermes.",kw={"alba fairmoon","eaux souterraines","la ferme des jansen","la ferme des molsen","poison","testing the wells","échantillon d’eau","marche de l’ouest"},ang={["class:Druid"]="En tant que druide, vous savez que les toxines surnaturelles dans le sol et les eaux souterraines blessent l’équilibre de la terre et appellent des soins.",["faction:Alliance"]="En tant que membre de l’Alliance, vous savez que les fermes de la Marche de l’Ouest doivent nourrir le royaume de Hurlevent. La santé de leurs puits concerne tout le royaume."},sec={{t="Un fléau dans la nappe phréatique",b="Alba Fairmoon vous demande de tester l’eau sous la Marche de l’Ouest. L’abandon et le banditisme ont déjà ravagé les plaines ouvertes. À présent, un poison sous terre menace les terres agricoles qui subsistent. Vous prélevez des échantillons dans les puits des fermes pour qu’Alba découvre ce qui contamine le sol et l’eau."},{t="Fermes des confins",b="Vous prélevez des échantillons dans les puits de La ferme des Jansen et de La ferme des Molsen. Ces exploitations se trouvent parmi des fermes éparses, exposées aux hors-la-loi défias et à la faune sauvage. Leur eau pourrait révéler si le fléau vient du sol, de la magie ou d’un acte délibéré."}},faq={{q="Quel est le but de Testing the Wells ?",a="Alba Fairmoon veut découvrir l’origine et la nature du poison qui affecte la Marche de l’Ouest. Des échantillons frais prélevés dans les puits des fermes lui permettront d’examiner la contamination.",al={"pourquoi tester les puits","objectif de tester les puits","à quoi sert cette quête"}},{q="Qui vous confie cette tâche ?",a="Alba Fairmoon vous demande votre aide dans son enquête sur la corruption qui se propage et les poisons surnaturels de la Marche de l’Ouest.",al={"qui donne tester les puits","quête d’alba fairmoon","donneur de quête"}},{q="Quels lieux faut-il échantillonner ?",a="Vous prélevez des échantillons dans les puits de La ferme des Jansen et de La ferme des Molsen, dans la Marche de l’Ouest.",al={"où aller","quels puits","emplacement des puits"}},{q="Qu’est-ce qui menace l’eau et le sol de la Marche de l’Ouest ?",a="Un fléau ou un poison inconnu corrompt les terres de la Marche de l’Ouest. Tester l’eau des puits est la première étape pour découvrir si l’eau sous les fermes est contaminée.",al={"pourquoi la marche de l’ouest est empoisonnée","qu’est-ce qui empoisonne les terres","origine du poison"}},{q="La contamination est-elle naturelle ou artificielle ?",a="La cause est encore inconnue. Les échantillons de La ferme des Jansen et de La ferme des Molsen pourraient révéler si la corruption vient d’une contamination naturelle des eaux souterraines ou d’un sabotage délibéré.",al={"l’eau est-elle empoisonnée volontairement","qui a empoisonné les puits"}},{q="Pourquoi se concentrer sur La ferme des Jansen et La ferme des Molsen ?",a="La ferme des Jansen et La ferme des Molsen sont des exploitations établies, dont les puits puisent dans la nappe phréatique sous les plaines. Les tester peut révéler jusqu’où s’étend la corruption.",al={"pourquoi jansen et molsen","pourquoi ces fermes"}}},fx={["40e3ab69"]={q="Pourquoi Alba Fairmoon veut-elle que cela soit fait ?",a="Alba Fairmoon tente de découvrir la source et la nature exacte du poison contaminant actuellement le sol et les eaux souterraines de la Marche de l’Ouest. En analysant l'eau provenant directement des puits des fermes en activité, elle espère diagnostiquer ce qui ravage la terre avant que la contamination ne se propage irrémédiablement.",al={"pourquoi alba veut-elle des échantillons d'eau","motif d'alba fairmoon","pourquoi tester les puits"}},d6dffc38={q="À quoi sert l'échantillon d'eau de La ferme des Jansen ?",a="Cet échantillon fournit à Alba Fairmoon de l'eau souterraine puisée directement à La ferme des Jansen. En l'examinant avec d'autres échantillons de fermes, elle peut retracer si le fléau imprègne profondément les aquifères souterrains à travers la Marche de l’Ouest ou s'il s'échappe d'un contaminant localisé spécifique.",al={"utilisation de l'échantillon d'eau de la ferme des jansen","pourquoi obtenir de l'eau de la ferme des jansen","but de l'échantillon de la ferme des jansen"}},fcb7e3cb={q="À quoi sert l'échantillon d'eau de La ferme des Molsen ?",a="Puisée au puits de La ferme des Molsen, cette eau permet à Alba Fairmoon de tester l'étendue de la corruption à travers différentes poches des terres agricoles de la Marche de l’Ouest. Comparer sa pureté avec d'autres puits locaux l'aide à évaluer le chemin et l'intensité du poison qui se propage.",al={"utilisation de l'échantillon d'eau de la ferme des molsen","pourquoi collecter l'échantillon de la ferme des molsen","but de l'eau de la ferme des molsen"}}},fp="17,131,21.270.0,21.268.0,41.155.0,22.110.0,35.65.0,46.164.0,43.167.0,42.182.0"}
P.entries["quest:92744"] = {n="Murloc Gills",s="À Longrivage, dans la Marche de l’Ouest, Alba Fairmoon cherche des branchies de murloc pour analyser la mer. Elle craint que le fléau des cultures n’atteigne la Grande mer, et que les branchies révèlent si les eaux côtières sont contaminées.",h="À Longrivage, dans la Marche de l’Ouest, Alba Fairmoon cherche des branchies de murloc pour analyser la mer.",kw={"alba fairmoon","fléau","famine","longrivage","murloc gills","eau de mer","hurlevent","toxines","marche de l’ouest"},ang={["class:Druid"]="La propagation du fléau intérieur aux eaux côtières menace la faune locale. La surveillance d’espèces indicatrices comme les murlocs aide à prévenir ce danger.",["faction:Alliance"]="Le roi Varian a disparu et les pénuries alimentaires attisent le mécontentement. Protéger les réserves alimentaires restantes de la Marche de l’Ouest est essentiel à la stabilité de Hurlevent.",["race:Human"]="Pour les habitants de Hurlevent, le déclin de la Marche de l’Ouest menace leurs foyers, leurs terres agricoles et leurs tables."},sec={{t="Une menace pour le littoral",b="La Marche de l’Ouest est au bord de la ruine. Les récoltes échouent, les fermiers quittent leurs foyers et des bandits sillonnent les routes. Alba Fairmoon craint que le fléau ne s’écoule des champs de l’intérieur vers la Grande mer. S’il contamine le littoral, les poissons qui nourrissent les pauvres de la Marche de l’Ouest et garnissent les tables de Hurlevent pourraient disparaître. Un royaume déjà éprouvé risquerait alors la famine."},{t="Sentinelles de la qualité de l’eau",b="Les murlocs sont obstinés et violents, mais leur corps amphibie peut révéler l’état de l’eau. En respirant, leurs branchies filtrent l’eau de mer et absorbent facilement les poisons, les fléaux et les polluants contre nature. Alba Fairmoon espère que des branchies fraîches prélevées sur les murlocs qui rôdent à Longrivage montreront jusqu’où la contamination s’est propagée."}},faq={{q="Pourquoi Alba Fairmoon veut-elle des branchies de murloc ?",a="Alba Fairmoon veut des branchies de murloc pour savoir si le fléau des cultures de la Marche de l’Ouest a atteint l’océan. Leurs branchies filtrent l’eau de mer et peuvent révéler des traces de toxines ou de pollution.",al={"pourquoi des branchies de murloc","alba fairmoon et les murlocs","but de la quête"}},{q="Où se trouvent les murlocs pour cette tâche ?",a="Les murlocs rôdent à Longrivage, la plage qui longe la côte ouest de la Marche de l’Ouest. Ils hantent les eaux peu profondes et les vasières au-delà des falaises.",al={"où sont les murlocs","emplacement des murlocs à longrivage","où trouver des branchies de murloc"}},{q="Quel est le danger plus général si l’océan est contaminé ?",a="La Marche de l’Ouest est le principal grenier à blé de Hurlevent, et ses cultures intérieures échouent déjà. La pêche côtière fournit une nourriture essentielle. Si des toxines empoisonnent la vie marine du littoral, le royaume pourrait connaître la famine sans échappatoire.",al={"pourquoi est-ce important","risque de famine dans la marche de l’ouest","menace pour hurlevent"}},{q="Les murlocs sont-ils particulièrement sujets aux maladies ?",a="Les murlocs survivent dans des conditions difficiles, mais leur système respiratoire amphibie réagit rapidement aux impuretés chimiques ou magiques de l’eau. Ils sont donc utiles pour étudier la pollution aquatique.",al={"physiologie des murlocs","les murlocs tombent-ils malades"}},{q="Cette quête est-elle liée à la Confrérie défias ?",a="La Confrérie défias a semé le chaos dans la Marche de l’Ouest et laissé les terres agricoles à l’abandon. L’enquête d’Alba Fairmoon porte plutôt sur le fléau écologique et la protection des réserves alimentaires du royaume.",al={"lien avec les défias","est-ce lié aux défias"}},{q="Qui est Alba Fairmoon ?",a="Alba Fairmoon est une chercheuse de l’Alliance dans la Marche de l’Ouest. Elle surveille le fléau et le déclin environnemental qui menacent les terres agricoles de la région.",al={"qui est fairmoon","histoire d’alba fairmoon"}}},fx={["853673a8"]={q="À quoi sert la branchie de murloc de Longrivage ?",a="Les Murloc Gills respirent par leurs branchies tout en rôdant dans les eaux côtières, ce qui rend leur tissu respiratoire sensible à tout ce qui pollue la mer. Alba Fairmoon utilise les branchies comme sujet de test biologique. En examinant le tissu à la recherche de toxines, elle peut déterminer si l'étrange corruption qui flétrit le sol et les récoltes de la Marche de l’Ouest a également commencé à empoisonner l'océan.",al={"utilisation des branchies de murloc","pourquoi collecter des branchies de murloc","branchies de murloc de longrivage"}},["4abd0ea3"]={q="Pourquoi chassez-vous les murlocs de Longrivage ?",a="Les murlocs vivent le long de la côte ouest de la Marche de l’Ouest, constamment exposés aux marées et aux embruns marins. Parce que leurs corps aquatiques filtrent l'eau côtière directement par leurs branchies, récolter des échantillons sur eux offre une preuve biologique immédiate de la présence ou non de contaminants ayant filtré depuis les terres agricoles troublées jusque dans la mer.",al={"pourquoi les murlocs","qui sont les murlocs de longrivage","pourquoi cibler les murlocs"}}},fp="12,190,25.325.0,26.319.0,41.169.0,44.133.0,53.215.0,42.192.0,50.195.0,21.137.0"}
P.entries["quest:92745"] = {n="The State of the Mines",s="Des métaux toxiques apparaissent dans les puits de la Marche de l’Ouest, et Alba Fairmoon craint pour les terres agricoles. Elle soupçonne les mines des Defias et prévient que les sols pourraient rester stériles pendant des décennies. Vous vous rendez à la Mine Veine-de-Jango et à la Carrière de la côte de l'Or pour perturber les activités minières.",h="Des métaux toxiques apparaissent dans les puits de la Marche de l’Ouest, et Alba Fairmoon craint pour les...",kw={"alba fairmoon","defias","carrière de la côte de l'or","mine veine-de-jango","terrassier kobold","exploitation minière","riverpaw","rejets toxiques","marche de l’ouest"},ang={["class:Druid"]="En tant que druide, vous faites face à une menace urgente : des poisons métalliques s’infiltrent dans les plaines et les écosystèmes côtiers de la Marche de l’Ouest.",["faction:Alliance"]="En tant que membre de l’Alliance, vous savez que la Marche de l’Ouest contribue à nourrir Hurlevent. Si les Defias ravagent ses terres agricoles, le royaume pourrait connaître la famine pendant des années.",["profession:Mining"]="À la Mine Veine-de-Jango et à la Carrière de la côte de l'Or, les Defias extraient des minerais sans se soucier de la sécurité ni de la stabilité des mines."},sec={{t="Empoisonner les terres",b="Alba Fairmoon découvre des taux dangereux de métaux toxiques dans les puits de la Marche de l’Ouest. Autrefois principal grenier à blé de Hurlevent, la région voit désormais ses cultures menacées. Alba soupçonne la Confrérie défias d’empoisonner l’eau par l’intermédiaire des mines dont elle s’est emparée. Si la contamination se poursuit, les terres alentour pourraient rester stériles pendant des décennies."},{t="Main-d’œuvre forcée et enrôlée",b="Les Defias font travailler les créatures locales aux côtés de leurs bandits de grand chemin, dépouillant ainsi la Marche de l’Ouest de ses ressources. Les gnolls Riverpaw extraient la pierre et les minerais à la Carrière de la côte de l'Or, tandis que des terrassiers kobolds creusent des galeries dans la Mine Veine-de-Jango. Perturber leur travail affaiblit la capacité des Defias à traiter et à distribuer les minerais contaminés."}},faq={{q="Pourquoi les mines de la Marche de l’Ouest rejettent-elles des métaux toxiques ?",a="Alba Fairmoon soupçonne les mines dont la Confrérie défias s’est emparée de contaminer les eaux souterraines de la Marche de l’Ouest avec des métaux toxiques. Elle veut perturber le travail des mineurs pour mettre fin à la pollution.",al={"pourquoi l’eau de la marche de l’ouest est toxique","pollution des mines de la marche de l’ouest","rejets toxiques dans la marche de l’ouest"}},{q="Qui dirige les activités minières dans la Marche de l’Ouest ?",a="La Confrérie défias contrôle les activités minières de la Marche de l’Ouest. Elle s’est emparée des infrastructures de l’ancien royaume et a chargé les gnolls Riverpaw et les kobolds d’extraire des minerais.",al={"qui dirige les mines","qui contrôle les mines de la marche de l’ouest","exploitation minière des defias"}},{q="Où travaillent les gnolls Riverpaw et les kobolds ?",a="Les gnolls Riverpaw travaillent à la Carrière de la côte de l'Or, sur le littoral occidental de la Marche de l’Ouest, tandis que les terrassiers kobolds travaillent dans la Mine Veine-de-Jango, au nord.",al={"où se trouvent les mineurs","emplacement de la carrière de la côte de l'or","emplacement de la mine veine-de-jango"}},{q="Qui est Alba Fairmoon ?",a="Alba Fairmoon enquête sur l’eau de la Marche de l’Ouest et cherche à protéger les terres agricoles de la région contre des dégâts durables.",al={"qui donne la quête état des mines","histoire d’alba fairmoon","donneur de quête"}},{q="Pourquoi les gnolls et les kobolds travaillent-ils pour les Defias ?",a="Les Defias emploient des gnolls et des kobolds comme main-d’œuvre dans les mines dont ils se sont emparés. Alba ne précise pas comment ces travailleurs ont été recrutés.",al={"pourquoi les defias recrutent des gnolls","kobolds au service des defias"}},{q="Les terres de la Marche de l’Ouest peuvent-elles se remettre de cette contamination ?",a="Selon Alba Fairmoon, les sols peuvent se remettre si la source de la toxicité est éliminée rapidement. Si les activités minières se poursuivent, les terres pourraient rester infertiles et dévastées pendant des décennies.",al={"les sols de la marche de l’ouest vont-ils guérir","les cultures peuvent-elles repousser"}}},fx={f9d72c87={q="Pourquoi Alba Fairmoon veut-elle que les mineurs soient tués ?",a="Des analyses d'eau des puits locaux ont révélé la présence de métaux toxiques dangereux s'infiltrant dans le sol de la Marche de l’Ouest. Alba Fairmoon sait que si l'exploitation minière intensive n'est pas stoppée immédiatement, le poison environnemental subsistera, rendant la région stérile et incapable de produire des récoltes pendant des décennies.",al={"pourquoi tuer les mineurs","mobile d'alba fairmoon","pourquoi stopper l'exploitation minière"}},["23ba5f2a"]={q="Qui sont les mineurs de la Mine Veine-de-Jango et de la Carrière de la côte de l'Or ?",a="Vous êtes envoyé affronter les Kobolds fouilleurs dans la Mine Veine-de-Jango et les Mineurs patte-de-rivière dans la Carrière de la côte de l'Or. Plutôt que de travailler pour leur propre compte, ces créatures sont utilisées comme main-d'œuvre par la The Defias Brotherhood, qui a saisi les mines pour piller impitoyablement les richesses minérales de la Marche de l’Ouest.",al={"qui sont les mineurs","qui êtes-vous envoyé tuer","kobolds fouilleurs et mineurs patte-de-rivière"}}},fp="22,240,18.325.0,25.320.0,51.182.0,48.160.0,50.136.0,21.107.0,50.113.0,57.169.0"}
P.entries["quest:92747"] = {n="Moonbrook Espionage",s="À Ruisselune, Alba Fairmoon suit les indices d’une activité industrielle suspecte dans la Marche de l’Ouest. Le poison répandu dans la région ne semble pas provenir des petites mines, alors les Mortemines, sous la ville, attirent son attention.",h="À Ruisselune, Alba Fairmoon suit les indices d’une activité industrielle suspecte dans la Marche de l’Ouest.",kw={"alba fairmoon","les mortemines","espionnage","fournitures industrielles","mines","ruisselune","poison","marche de l’ouest"},ang={["class:Rogue"]="En tant que voleur, vous pouvez vous faufiler dans Ruisselune pour recueillir des renseignements sur les opérations défias sans donner l’alerte.",["faction:Alliance"]="En tant que membre de l’Alliance, vous savez qu’une activité industrielle à Ruisselune menace le grenier de la Marche de l’Ouest et la sécurité de Hurlevent.",["profession:Mining"]="En tant que mineur, vous connaissez les richesses et l’ampleur logistique des profondes galeries sous Ruisselune."},sec={{t="Une piste toxique",b="Les mines déjà fouillées dans la Marche de l’Ouest n’ont rien révélé sur l’origine du poison qui se répand dans la région. Aucune excavation de surface connue ne semble en être la source. Un grand site reste inexploré : les Mortemines, dont les vastes galeries s’étendent sous les rues en ruine de Ruisselune."},{t="Les secrets des Mortemines",b="La Horde envahit la région durant la Première guerre, et les récits racontent que les Mortemines furent abandonnées par la suite. Pourtant, du matériel et des fournitures industrielles modernes sont éparpillés dans Ruisselune. Ils témoignent d’importantes activités minières et manufacturières, dissimulées derrière l’apparence en ruine et désertée de la ville."}},faq={{q="Qui confie Espionnage de Ruisselune ?",a="Alba Fairmoon vous envoie enquêter à Ruisselune. Elle étudie des toxines suspectes et une activité industrielle dans la Marche de l’Ouest disputée.",al={"donneur de quête","qui confie espionnage de ruisselune","alba fairmoon"}},{q="Pourquoi Alba enquête-t-elle à Ruisselune ?",a="Les autres mines de la région ne présentent aucun signe de production du poison qu’étudie Alba. Ruisselune se trouve juste au-dessus des Mortemines, et elle soupçonne donc une opération clandestine sous la ville.",al={"pourquoi ruisselune","que trouve-t-on à ruisselune","enquêter à ruisselune"}},{q="Que sont les Mortemines ?",a="Les Mortemines sont les mines d’or les plus profondes et les plus vastes de la région. Elles sont considérées comme des ruines désertées depuis la chute de Hurlevent durant la Première guerre, bien que des vermines et des bandits soient réputés les hanter.",al={"histoire des mortemines","que sont les mortemines"}},{q="Quels objets récupère-t-on durant cette mission de reconnaissance ?",a="Des éclaireurs sont envoyés récupérer des Fournitures d’ingénierie suspectes éparpillées dans Ruisselune. Ces fournitures témoignent d’activités industrielles et de raffinage à proximité des puits de mine.",al={"fournitures d’ingénierie suspectes","objets de quête espionnage de ruisselune"}},{q="Quelles menaces occupent Ruisselune actuellement ?",a="La Confrérie défias a envahi Ruisselune et utilise ses bâtiments délabrés comme base avancée. Ses membres gardent l’entrée en surface du réseau souterrain.",al={"ennemis de ruisselune","qui contrôle ruisselune"}},{q="Que prouve la découverte de ces fournitures ?",a="La présence d’équipement industriel moderne et lourd dans une ville que l’on croyait abandonnée indique qu’une faction organisée mène des activités de fabrication à grande échelle, à l’insu des autorités de Hurlevent.",al={"que signifient ces fournitures","industrie défias"}}},fp="19,209,13.271.0,24.282.1,32.144.0,36.181.0,23.198.0,53.167.0,40.161.0,39.175.0"}
P.entries["quest:92748"] = {n="Explosive Consultation",s="Alba Fairmoon vous envoie chercher un moyen d’arrêter le poison qui se répand des Mortemines dans les champs de la Marche de l’Ouest. Dans le Quartier des Nains de Hurlevent, vous cherchez un ingénieur capable de fabriquer les explosifs lourds nécessaires.",h="Alba Fairmoon vous envoie chercher un moyen d’arrêter le poison qui se répand des Mortemines dans les champs...",kw={"alba fairmoon","les mortemines","quartier des nains","ingénierie","explosive consultation","fée dérailleur","hurlevent","toxines","marche de l’ouest"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous constatez que les communautés frontalières de la Marche de l’Ouest, en difficulté, dépendent des ateliers du Quartier des Nains de Hurlevent.",["profession:Engineering"]="En tant qu’ingénieur, vous savez que la force brute ne peut pas résoudre les problèmes des terres empoisonnées de la Marche de l’Ouest. Neutraliser de grandes machines souterraines exige des munitions spécialisées et un savoir-faire technique précis.",["race:Gnome"]="En tant que gnome, vous apportez une ingéniosité technologique qui peut aider à contrer les menaces industrielles souterraines hors de portée des forces régulières de l’Alliance."},sec={{t="Une source toxique",b="Les champs empoisonnés de la Marche de l’Ouest mènent aux toxines caustiques et aux déchets industriels des Mortemines. Des machines renforcées protègent les installations souterraines, et les armes ordinaires ne peuvent pas les neutraliser. Des explosifs lourds pourraient briser ces machines et mettre fin à l’empoisonnement."},{t="L’expertise de Hurlevent",b="Dans le Quartier des Nains de Hurlevent, vous cherchez Fée Dérailleur, une ingénieure capable de concevoir les explosifs nécessaires. Les forges rugissantes, les bricoleurs et les marchands de poudre à canon abondent dans le quartier. Ses artisans savent peut-être comment arrêter les activités des Mortemines."}},faq={{q="Pourquoi avons-nous besoin d’explosifs dans les Mortemines ?",a="Les indices recueillis dans la Marche de l’Ouest révèlent une vaste activité industrielle dans les Mortemines, où des toxines contaminent les terres agricoles voisines. Des explosifs lourds peuvent neutraliser ses machines renforcées.",al={"pourquoi des explosifs aux mortemines","pourquoi faut-il des bombes","raison des toxines des mortemines"}},{q="Qui donne cette quête ?",a="Alba Fairmoon envoie des héros enquêter sur les contaminants anormaux et les troubles qui menacent la Marche de l’Ouest.",al={"qui donne consultation explosive","début de consultation explosive"}},{q="Qui est Fée Dérailleur ?",a="Fée Dérailleur est une ingénieure gnome du Quartier des Nains de Hurlevent. Elle travaille sur des dispositifs mécaniques complexes et des composés volatils, et peut fabriquer de puissants explosifs.",al={"emplacement de fée dérailleur","qui est dérailleur"}},{q="Pourquoi se rendre dans le Quartier des Nains ?",a="Le Quartier des Nains de Hurlevent est le cœur industriel de la ville. Des forgerons et des bricoleurs qualifiés y travaillent, aux côtés de marchands de poudre à canon et de composants d’ingénierie.",al={"pourquoi le quartier des nains","lien avec le quartier des nains de hurlevent"}},{q="Le gouvernement de Hurlevent aide-t-il dans cette entreprise ?",a="Le roi Varian Wrynn ayant disparu, la Maison des nobles hésite à envoyer des garnisons militaires officielles dans la Marche de l’Ouest. Les défenseurs locaux comptent sur des volontaires indépendants et des artisans privés de la capitale plutôt que sur les régiments de l’armée régulière.",al={"l’armée apporte-t-elle son aide","pourquoi un ingénieur de hurlevent"}}},fx={fe11cddb={q="Pourquoi Alba Fairmoon veut-elle que vous trouviez des explosifs ?",a="Alba Fairmoon a découvert la preuve d'une opération industrielle massive cachée au plus profond des Mortemines. Elle a lié ces machines souterraines directement aux toxines infectes qui empoisonnent le sol et ravagent les terres agricoles au-dessus. Sachant qu'une opération de cette envergure ne peut être démantelée à la main, elle souhaite obtenir des explosifs lourds pour détruire toute machine malfaisante polluant la campagne avant que les dommages ne deviennent irréversibles.",al={"pourquoi alba fairmoon veut-elle des explosifs","mobile d'alba fairmoon","pourquoi alba a-t-elle besoin d'explosifs"}}},fp="22,216,14.261.0,29.256.0,43.169.0,22.101.0,27.174.0,44.171.0,52.231.0"}
P.entries["quest:92749"] = {n="A Dynamite Plan",s="Dans le Quartier des Nains de Hurlevent, Fée Dérailleur veut lancer un plan inspiré par des discussions sur le sabotage industriel. Elle demande dix bâtons de dynamite grossière.",h="Dans le Quartier des Nains de Hurlevent, Fée Dérailleur veut lancer un plan inspiré par des discussions sur...",kw={"dynamite grossière","quartier des nains","ingénierie","explosifs","sabotage","fée dérailleur","hurlevent"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous découvrez le projet explosif de Fée à l’intérieur des murs de votre capitale, Hurlevent.",["profession:Engineering"]="En tant qu’ingénieur, vous pouvez fabriquer de la dynamite grossière avec de la poudre de dynamite grossière et de l’étoffe de lin. C’est une première épreuve simple de bricolage.",["race:Gnome"]="En tant que gnome, vous voyez Fée Dérailleur faire face aux problèmes industriels complexes avec des inventions ingénieuses et explosives."},sec={{t="Des étincelles dans le Quartier des Nains",b="Fée Dérailleur est une ingénieure gnome du Quartier des Nains de Hurlevent. Elle accueille favorablement les discussions sur le sabotage industriel et demande aux mercenaires de passage de lui apporter un lot de dynamite grossière."},{t="Ambitions gnomes",b="Vous pouvez fabriquer de la dynamite grossière à un établi d’ingénieur ou en faire commerce avec les artisans de la ville. Fée demande dix bâtons, de quoi perturber les manœuvres industrielles en cours dans les territoires environnants. Son plan illustre les méthodes pragmatiques et périlleuses que les gnomes privilégient face aux bouleversements mécaniques et politiques."}},faq={{q="Qui est Fée Dérailleur ?",a="Fée Dérailleur est une ingénieure du Quartier des Nains de Hurlevent, au milieu des forges et des ateliers. Elle se consacre à des projets d’ingénierie audacieux et explosifs.",al={"fée dérailleur","qui est fée dérailleur","donneur de quête"}},{q="De quoi Fée a-t-elle besoin pour cette tâche ?",a="Fée a besoin de dix bâtons de dynamite grossière. Vous pouvez les fabriquer grâce à l’ingénierie ou vous les procurer par le commerce ou à l’hôtel des ventes.",al={"objets du plan de dynamite","de quoi ai-je besoin","objets nécessaires"}},{q="Pourquoi Fée veut-elle de la dynamite grossière ?",a="Les discussions sur le sabotage industriel ont attiré l’attention de Fée. Pour commencer, elle veut se constituer une réserve de charges explosives rudimentaires.",al={"pourquoi de la dynamite","utilité de la dynamite","motif du sabotage"}},{q="Où dois-je rendre la quête ?",a="Fée Dérailleur se trouve dans le Quartier des Nains de Hurlevent.",al={"où rendre la quête","lieu de remise","emplacement de fée dérailleur"}},{q="L’ingénierie est-elle nécessaire pour terminer cette quête ?",a="Non, l’ingénierie n’est pas nécessaire. Les ingénieurs peuvent fabriquer de la dynamite grossière, mais vous pouvez aussi en faire commerce ou en acheter à l’hôtel des ventes.",al={"l’ingénierie est-elle nécessaire","prérequis d’ingénierie","les non-ingénieurs peuvent-ils faire cette quête"}},{q="Quel est le lien avec les problèmes qui touchent Hurlevent ?",a="Fée ne précise pas quelles sont les cibles de son sabotage. Elle montre seulement son empressement à commencer avec de la dynamite quand le sujet du sabotage industriel est abordé.",al={"problèmes à hurlevent","sabotage à marche de l’ouest","histoire du sabotage industriel"}}},fx={dd094caa={q="À quoi sert la Dynamite grossière ?",a="Fée Dérailleur est impatiente de se livrer à un peu de sabotage industriel, et la puissance explosive est au cœur de son plan. La Dynamite grossière fournit la force de concussion brute dont elle a besoin pour perturber les opérations mécaniques ou dégager les obstacles structurels pour son entreprise à venir.",al={"utilisation de la dynamite grossière","pourquoi fée dérailleur a-t-elle besoin de dynamite","pourquoi de la dynamite grossière"}}},fp="15,158,30.184.0,17.309.0,27.155.0,36.130.0,37.112.0,29.60.0,47.130.0,58.129.0"}
P.entries["quest:92750"] = {n="Detonation at a Distance",s="Fée Dérailleur cherche un moyen plus sûr de déclencher des explosifs et vous envoie au renseignement de Hurlevent.",h="Fée Dérailleur cherche un moyen plus sûr de déclencher des explosifs et vous envoie au renseignement de...",kw={"detonation at a distance","jasper lagangrène","détonateur à distance","si:7","fée dérailleur","renseignement de hurlevent","marche de l’ouest"},ang={["class:Rogue"]="En tant que voleur, vous pénétrez au cœur des opérations du SI:7, dans la Vieille ville, où s'exercent les méthodes clandestines humaines.",["profession:Engineering"]="En tant qu'ingénieur, vous pouvez fabriquer des mèches et de la dynamite. Les déclencheurs à distance de qualité militaire proviennent souvent de contacts spécialisés dans le sabotage discret.",["race:Gnome"]="En tant que gnome, vous partagez l'intérêt de Fée Dérailleur pour les problèmes d'ingénierie. Elle se tourne vers les services de renseignement humains pour obtenir des munitions d'espionnage."},sec={{t="Une explosion contrôlée",b="Les gobelins et les gnomes manipulent les produits chimiques volatils avec imprudence, mais certaines explosions exigent de la prudence. Une mèche ordinaire peut vous mettre en danger. Les bricoleurs ordinaires n'ont pas le déclencheur spécial dont Fée Dérailleur a besoin pour provoquer une explosion contrôlée."},{t="Faire appel au SI:7",b="Fée Dérailleur vous envoie auprès du renseignement de Hurlevent, dans la Vieille ville, plutôt que vers les artificiers nains locaux ou les fournisseurs d'ingénierie ordinaires. Ses agents, connus sous le nom de SI:7, se spécialisent dans le sabotage, la furtivité et les démolitions ciblées. Jasper Lagangrène en fait partie dans la capitale et peut fournir du matériel dangereux en toute discrétion."}},faq={{q="Qui vous envoie en mission ?",a="Fée Dérailleur, une gnome bricoleuse du Quartier des Nains de Hurlevent, vous envoie chercher un détonateur à distance.",al={"donneur de quête","qui lance détonation à distance","quête de fée dérailleur"}},{q="À qui devez-vous parler à Hurlevent ?",a="Fée Dérailleur vous envoie auprès de Jasper Lagangrène, un agent du renseignement de Hurlevent.",al={"où rendre la quête","contact du renseignement de hurlevent","emplacement de jasper lagangrène"}},{q="Pourquoi Fée Dérailleur a-t-elle besoin d'un détonateur à distance ?",a="Fée Dérailleur veut déclencher des explosifs à distance. Un déclencheur à distance est plus pratique que de risquer vos membres dans une explosion incontrôlée.",al={"pourquoi un détonateur à distance","objectif de la détonation"}},{q="Pourquoi contacter le renseignement de Hurlevent plutôt qu'un ingénieur ?",a="Le renseignement de Hurlevent dispose d'équipement spécialisé de sabotage que les marchands ordinaires et les bricoleurs de terrain ne vendent pas ou ne distribuent pas ouvertement.",al={"pourquoi le si:7","pourquoi le renseignement de hurlevent"}},{q="Où se trouve Jasper Lagangrène à Hurlevent ?",a="Jasper Lagangrène se trouve au quartier général du SI:7, dans la Vieille ville, où travaillent les espions et les agents clandestins de Hurlevent.",al={"jasper lagangrène à hurlevent","salle de jasper lagangrène"}},{q="Quelle faction peut accomplir cette tâche ?",a="Seuls les membres de l'Alliance peuvent accomplir cette mission. Elle repose sur la coopération avec le service de renseignement royal de Hurlevent.",al={"réservé à l'alliance","la horde peut-elle faire cette quête"}}},fx={be1ed035={q="Pourquoi Fée Dérailleur vous envoie-t-elle au SI:7 au lieu d'y aller elle-même ?",a="Fée Dérailleur ne possède pas de détonateur à distance elle-même. Comme vous souhaitez une explosion contrôlée qui garde vos membres intacts, elle vous oriente vers les gens sournois du SI:7, dont elle pense qu'ils peuvent en trouver un. La quête n'explique pas pourquoi elle n'y va pas elle-même.",al={"pourquoi moi fée dérailleur","pourquoi envoyer le joueur au si:7","pourquoi fée dérailleur ne peut-elle pas aller à hurlevent"}}},fp="24,124,18.229.0,21.299.0,30.108.0,40.84.0,53.136.0,59.133.0,41.95.0,37.125.0"}
P.entries["quest:92751"] = {n="Detonation at a Distance",s="À Ruisselune, des explosions sous la Marche de l’Ouest attirent l’attention du SI:7. Jasper Lagangrène, agent de Hurlevent, vous envoie un kit de détonateur à distance pour agir en sécurité.",h="À Ruisselune, des explosions sous la Marche de l’Ouest attirent l’attention du SI:7.",kw={"les mortemines","quartier des nains","jasper lagangrène","ruisselune","détonateur à distance","si:7","fée dérailleur","marche de l’ouest"},ang={["class:Rogue"]="En tant que voleur, votre rencontre avec Jasper Lagangrène vous donne un aperçu du réseau secret du SI:7. Il surveille les agents sur le terrain et leur fournit discrètement des outils.",["faction:Alliance"]="En tant que membre de l’Alliance, vous voyez Hurlevent tenter de reprendre la Marche de l’Ouest par le renseignement et l’ingénierie clandestine plutôt que par la force militaire ouverte.",["profession:Engineering"]="En tant qu’ingénieur, vous pouvez apprécier un détonateur prototype qui déclenche les charges à distance et évite les mèches à allumage manuel risquées lors des démolitions dans les grottes.",["race:Gnome"]="En tant que gnome, le travail de Fée Dérailleur montre comment l’ingénierie gnome fournit des prototypes aux espions de Hurlevent."},sec={{t="Des yeux dans l’ombre",b="Jasper Lagangrène et le SI:7 suivent les événements sur les terres de Hurlevent, notamment à la frontière agitée de la Marche de l’Ouest. Quand on l’informe des travaux explosifs à Ruisselune, Lagangrène sait déjà ce qui se passe dans les tunnels miniers abandonnés sous la campagne."},{t="Une solution prototype",b="Les explosions dans des grottes étroites mettent en danger tous ceux qui se trouvent à proximité. Jasper Lagangrène vous confie un prototype de Kit de détonateur à distance fabriqué par des ingénieurs alliés à l’Alliance. Il permet de faire détoner des charges sous la Marche de l’Ouest depuis l’extérieur. Il vous envoie avec le kit auprès de Fée Dérailleur, dans le Quartier des Nains de Hurlevent, et vous recommande de ne pas mentionner le SI:7 à vos alliés elfes."}},faq={{q="Qui est Jasper Lagangrène ?",a="Jasper Lagangrène est un agent du service de renseignement de Hurlevent, le SI:7. Il surveille les menaces secrètes à travers le royaume et fournit des outils pour les contrer.",al={"jasper lagangrène","qui donne detonation at a distance","donneur de quête"}},{q="Pourquoi le SI:7 s’intéresse-t-il à Ruisselune ?",a="Des bandits et des hors-la-loi tiennent Ruisselune, dont la surface mène aux Mortemines. Les démolitions profondément enfouies sous la Marche de l’Ouest ont attiré l’attention du réseau de renseignement de Hurlevent.",al={"pourquoi ruisselune","lien avec les défias","grottes de la marche de l’ouest"}},{q="Qui est Fée Dérailleur ?",a="Fée Dérailleur est une ingénieure gnome du Quartier des Nains de Hurlevent. Elle prépare des explosifs pour la démolition.",al={"fée dérailleur","qui reçoit le détonateur","personnage pour rendre la quête"}},{q="Qui est l’« amie elfe » mentionnée par Jasper Lagangrène ?",a="Jasper Lagangrène parle d’Alba Fairmoon, l’elfe qui enquête sur le poison de la Marche de l’Ouest et vous a envoyé chercher des explosifs. Le SI:7 cache son soutien direct aux alliés extérieurs.",al={"amie elfe","ne pas le dire à l’elfe","jasper lagangrène et l’elfe"}},{q="À quoi sert le Kit de détonateur à distance ?",a="Le Kit de détonateur à distance déclenche des charges de démolition depuis une distance sûre. Il permet aux agents de dégager ou d’effondrer des passages souterrains sans rester piégés à l’intérieur.",al={"détonateur à distance","kit de détonateur","à quoi sert le kit"}},{q="Où cette quête vous mène-t-elle ?",a="Vous apportez le kit de détonateur à Fée Dérailleur, dans le Quartier des Nains de Hurlevent.",al={"où aller","itinéraire de quête","lieu où rendre la quête"}}},fx={dd5ef9f7={q="Pourquoi Jasper Lagangrène aide-t-il avec le détonateur à distance ?",a="Jasper Lagangrène propose un kit de prototype de détonateur avancé pour Fée Dérailleur. Il vous demande de ne pas mentionner son implication à votre amie elfe tout en aidant à la démolition prévue.",al={"mobile de jasper lagangrène","pourquoi aider avec le détonateur","pourquoi jasper lagangrène donne-t-il le kit"}},["2c859344"]={q="Pourquoi Jasper Lagangrène vous le demande-t-il au lieu de s'en occuper lui-même ?",a="Jasper Lagangrène vous confie le kit de prototype de détonateur pour Fée Dérailleur, tout en vous demandant de ne pas mentionner son implication à votre amie elfe. Il n'explique pas pourquoi il ne peut pas le livrer personnellement.",al={"pourquoi m'envoyer","pourquoi jasper lagangrène ne le livre-t-il pas","pourquoi pas des agents du si:7"}}},fp="24,179,19.243.0,20.334.1,18.154.0,35.165.0,27.120.0,44.162.0,42.162.0,31.88.0"}
P.entries["quest:92752"] = {n="Explosive Consultation",s="À Marche de l’Ouest, Fée Dérailleur envoie une charge instable à Alba Fairmoon. Les explosifs amorcés doivent lui parvenir sans encombre, sans que le détonateur soit touché.",h="À Marche de l’Ouest, Fée Dérailleur envoie une charge instable à Alba Fairmoon.",kw={"alba fairmoon","détonateur","explosive consultation","explosifs","ingénierie gnome","fée dérailleur","marche de l’ouest"},ang={["faction:Alliance"]="En tant qu’aventurier de l’Alliance, vous voyez des agents utiliser des armes peu conventionnelles contre les camps de bandits fortifiés et les machines rebelles de Marche de l’Ouest.",["profession:Engineering"]="En tant qu’ingénieur, vous savez que les munitions gnomes ont un fort pouvoir destructeur et un détonateur à la détente facile.",["race:Gnome"]="En tant que gnome, vous voyez Fée Dérailleur apporter à Marche de l’Ouest, en proie aux troubles, les solutions explosives de Gnomeregan."},sec={{t="Une livraison instable",b="Fée Dérailleur a préparé un lot d’Explosifs de destruction ultime pour Alba Fairmoon. En temps de guerre, les bandits Defias et les bêtes sauvages menacent déjà les routes de Marche de l’Ouest. Transporter une charge active rend le voyage plus dangereux."},{t="À manipuler avec précaution",b="Fée Dérailleur vous avertit de protéger le détonateur. Les explosifs doivent détruire l’opération industrielle cachée dans Mortemines, qui empoisonne les terres agricoles de Marche de l’Ouest. Alba Fairmoon a besoin des explosifs intacts avant de pouvoir s’en servir."}},faq={{q="Qui donne la quête Explosive Consultation ?",a="Fée Dérailleur, une gnome bricoleuse du Quartier des Nains de Hurlevent, vous confie les explosifs à transporter.",al={"qui donne explosive consultation","donneur de quête explosive consultation","quête fée dérailleur"}},{q="Qui reçoit les explosifs à la fin de la quête ?",a="Alba Fairmoon, à Marche de l’Ouest, reçoit les Explosifs de destruction ultime.",al={"où apporter les explosifs","qui termine explosive consultation","alba fairmoon explosifs"}},{q="Quel objet devez-vous transporter ?",a="Vous transportez un paquet d’Explosifs de destruction ultime avec un détonateur amorcé et délicat.",al={"que remet fée dérailleur","objet explosive consultation","quelle est cette bombe"}},{q="Pourquoi faut-il des explosifs à Marche de l’Ouest ?",a="Alba Fairmoon a découvert que les toxines qui empoisonnent les terres agricoles de Marche de l’Ouest provenaient d’une vaste opération industrielle cachée dans Mortemines. Elle a cherché un ingénieur capable de fournir des explosifs pour la détruire.",al={"pourquoi ont-ils besoin de bombes","utilité des explosifs à marche de l’ouest","pourquoi faire exploser des choses à marche de l’ouest"}},{q="Cette quête est-elle accessible aux aventuriers de la Horde ?",a="Non. Fée Dérailleur et Alba Fairmoon soutiennent les opérations de l’Alliance. Seuls les aventuriers de l’Alliance peuvent s’en charger.",al={"la horde peut-elle faire explosive consultation","horde explosive consultation"}},{q="Fée Dérailleur vous avertit-elle d’un danger particulier ?",a="Fée Dérailleur vous avertit que la bombe est amorcée et vous demande de manipuler le détonateur avec une extrême précaution pendant le voyage.",al={"avertissement de fée dérailleur","avertissement sur la bombe à marche de l’ouest"}}},fx={bb434565={q="Pourquoi Fée Dérailleur veut-elle que les explosifs soient livrés à Alba ?",a="Fée Dérailleur a fini d'assembler les Explosifs de destruction ultime commandés pour les efforts d'Alba Fairmoon dans la Marche de l’Ouest. Ayant fabriqué cette cargaison périlleuse, Fée Dérailleur a besoin d'un aventurier pour gérer le transport délicat et dangereux vers Alba afin que la bombe puisse être utilisée comme prévu.",al={"pourquoi livrer les explosifs à alba","mobile de fée dérailleur","pourquoi fée dérailleur a-t-elle fabriqué la bombe"}}},fp="22,151,19.237.0,18.246.0,44.105.0,52.68.0,43.86.0,38.190.0,45.117.0,60.121.0"}
P.entries["quest:92753"] = {n="Destruction in Deadmines",s="Dans les Mortemines, sous Ruisselune, l’industrie défias ravage les terres. Alba Fairmoon soupçonne leur forge métallurgique d’en être la source et vous envoie la détruire avec des explosifs.",h="Dans les Mortemines, sous Ruisselune, l’industrie défias ravage les terres.",kw={"alba fairmoon","les mortemines","confrérie défias","explosifs de destruction ultime","forge métallurgique","ruisselune","sabotage","marche de l’ouest"},ang={["faction:Alliance"]="Détruire la forge défias s’attaque aux machines et aux armes qui menacent la souveraineté de Hurlevent depuis la Marche de l’Ouest.",["profession:Engineering"]="Alba Fairmoon propose d’utiliser des Explosifs de destruction ultime spécialisés contre les installations industrielles lourdes pour éliminer la source présumée de contamination.",["profession:Mining"]="Les Mortemines étaient autrefois les mines d’or et de fer les plus riches de Hurlevent. Les défias en ont fait un complexe fortifié de fonderies qui souille la terre."},sec={{t="Saboter la fonderie",b="Sous Ruisselune, les Mortemines abritent un complexe fortifié qui alimente la Confrérie défias. Sa lourde forge fond le métal et fabrique des machines. Alba Fairmoon pense que cette forge est probablement à l’origine de la contamination qui ravage la région. Elle veut la détruire."},{t="Une explosion décisive",b="Au-delà des barricades, des coupe-gorge et des ingénieurs gobelins, la forge vous attend. Vous transportez des Explosifs de destruction ultime et les placez près des installations de la forge. Puis vous fuyez vers les collines au-dessus de Ruisselune. Alba Fairmoon vous y attend pour faire détoner la charge, dans l’espoir que les terres puissent commencer à guérir."}},faq={{q="Quel est l’objectif de cette mission ?",a="Vous devez pénétrer dans les Mortemines, sous Ruisselune, trouver la forge métallurgique de la Confrérie défias et placer des Explosifs de destruction ultime à proximité. Alba Fairmoon vous attend à la sortie.",al={"objectif de quête","que faire","qu’est-ce que destruction dans les mortemines"}},{q="Qui est Alba Fairmoon ?",a="Alba Fairmoon est une agente de l’Alliance dans la Marche de l’Ouest. Elle pense que la souillure et le poison de la région proviennent de la fonte intensive et des activités industrielles dans les Mortemines.",al={"qui est alba","histoire d’alba fairmoon","donneur de quête"}},{q="Pourquoi la forge défias est-elle si dangereuse ?",a="Alba soupçonne que la grande forge métallurgique des Mortemines est à l’origine du poison. Elle espère que sa destruction permettra aux terres de commencer à guérir.",al={"pourquoi détruire la forge","à quoi sert la forge","poison de la forge"}},{q="Où le joueur retrouve-t-il Alba après avoir placé les explosifs ?",a="Alba Fairmoon vous attend dans les collines derrière Ruisselune, à l’extérieur des Mortemines, près de la sortie supérieure de la mine. Elle est prête à déclencher les explosifs dès que vous serez sorti sain et sauf.",al={"où alba attend-elle","emplacement de la sortie des mortemines","lieu de remise de la quête"}},{q="Où se trouve la forge dans les Mortemines ?",a="La forge se trouve au plus profond des Mortemines, au-delà des tunnels miniers, dans la fonderie industrielle où travaillent les ouvriers défias et les surveillants gobelins.",al={"où se trouve la forge","emplacement de la forge des mortemines","trouver la forge"}},{q="La destruction de la forge guérira-t-elle immédiatement les terres ?",a="Alba espère que l’arrêt de la fonte intensive permettra aux terres autour de Ruisselune de se rétablir. Il faudra du temps pour effacer les années d’activité industrielle et de négligence défias.",al={"les terres vont-elles guérir","le poison va-t-il cesser","conséquences de la destruction de la forge"}}},fx={cfdfebff={q="Pourquoi Alba Fairmoon veut-elle que la forge soit détruite ?",a="Alba croit que la forge des Defias au plus profond des Mortemines est la véritable source de la pollution infecte s'infiltrant dans la terre environnante. En posant des explosifs et en brisant l'opération de fonte massive, elle espère couper le mal à la racine afin que le sol blessé de la Marche de l’Ouest puisse enfin commencer à guérir.",al={"mobile d'alba fairmoon","pourquoi détruire la forge des mortemines","pourquoi alba veut-elle que cela soit fait"}}},fp="24,177,22.263.0,16.278.1,33.180.0,21.167.0,48.146.0,62.163.0,48.141.0,52.146.0"}
P.entries["quest:928"] = {n="La couronne de la Terre",s="À Sombrevallon, vous portez vers le sud l’eau du puits de lune à Corithras Ragelune, à Dolanaar. Ce voyage vous mène de l’entraînement protégé à la tâche plus vaste de protéger Teldrassil.",h="À Sombrevallon, vous portez vers le sud l’eau du puits de lune à Corithras Ragelune, à Dolanaar.",kw={"aldrassil","corithras ragelune","crown of the earth","dolanaar","puits de lune","récipient à moitié rempli","sombrevallon","teldrassil","tenaron poignorage"},ang={["class:Druid"]="En tant que druide, le transport des eaux consacrées vous associe aux efforts visant à nourrir et à équilibrer l’écosystème en pleine croissance de Teldrassil.",["class:Priest"]="En tant que prêtre, porter l’eau du puits de lune consacrée par Elune's Grace reflète votre devoir de veiller à la santé spirituelle de votre communauté.",["race:NightElf"]="En tant que jeune Kaldorei, quitter Sombrevallon est un rite de passage tandis que vous partez servir votre peuple."},sec={{t="Quitter le bosquet",b="Vous avez goûté à l’eau enchantée du puits de lune de Sombrevallon. À la cime d’Aldrassil, Tenaron Poignorage scelle l’eau recueillie dans un récipient plus grand, puis vous envoie au-delà du bosquet protégé. La route mène au sud, vers Dolanaar, à travers des bois où le danger est devenu plus imprévisible."},{t="La route de Dolanaar",b="Dolanaar est le premier grand village au-delà de Sombrevallon, le long des chemins pavés qui traversent le centre de Teldrassil. Son puits de lune se trouve au cœur du village. Corithras Ragelune, un ancien chargé de veiller à la préservation des branches, vous y attend. Le récipient que vous portez vous associe aux efforts plus vastes pour protéger L’Arbre-monde."}},faq={{q="Que transportez-vous à Dolanaar ?",a="Vous portez le Récipient à moitié rempli, qui contient de l’eau consacrée du puits de lune de Sombrevallon. Tenaron Poignorage a recueilli votre offrande pour que Corithras Ragelune l’utilise dans des rites à travers Teldrassil.",al={"qu’est-ce que le récipient","histoire du récipient à moitié rempli","quelle est cette eau"}},{q="Qui est Corithras Ragelune ?",a="Corithras Ragelune est un ancien elfe de la nuit qui se tient près du puits de lune de Dolanaar. Il dirige les personnes qui viennent participer à des rites et à des enquêtes destinés à préserver L’Arbre-monde.",al={"qui est corithras","rôle de corithras ragelune","où se trouve corithras"}},{q="Pourquoi Tenaron vous envoie-t-il loin de Sombrevallon ?",a="Sombrevallon vous offre un entraînement de base, tandis que les problèmes de Teldrassil s’étendent à travers ses branches. Après que vous avez fait vos preuves contre les menaces locales et honoré les puits de lune, Tenaron vous envoie à Dolanaar, où une tâche plus vaste vous attend.",al={"pourquoi quitter sombrevallon","pourquoi aller à dolanaar","tenaron m’envoie ailleurs"}},{q="Où se trouve la route de Dolanaar ?",a="Suivez le chemin pavé vers le sud depuis Aldrassil et franchissez les portes de Sombrevallon. Restez sur la route tandis qu’elle tourne vers le sud puis l’ouest, et elle vous mènera à Dolanaar.",al={"comment aller à dolanaar","chemin vers dolanaar","route hors de sombrevallon"}},{q="Pourquoi Tenaron vous met-il en garde contre les bêtes dangereuses ?",a="Tenaron dit que des bêtes dangereuses rôdent dans les forêts depuis quelque temps. La faune est devenue agressive, même au sein des branches sacrées de Teldrassil, alors vous risquez gros si vous quittez le sentier pavé.",al={"pourquoi les bêtes sont-elles dangereuses","bêtes corrompues de teldrassil","avertissement de rester sur la route"}},{q="Que se passe-t-il après votre arrivée à Dolanaar ?",a="Corithras Ragelune prend le récipient et vous envoie remplir des fioles à d’autres puits de lune de Teldrassil. La tâche se poursuit à travers l’arbre.",al={"que faire après crown of the earth","quête suivante à dolanaar","que fait corithras"}}},fx={a4343de4={q="Pourquoi Tenaron Poignorage envoie-t-il un aventurier au lieu de livrer le récipient lui-même ?",a="Tenaron Poignorage supervise les branches d'Aldrassil et s'occupe des affaires sacrées de Sombrevallon, où les jeunes elfes de la nuit aiguisent leurs arts pour la première fois. Il ne peut abandonner ses devoirs au sommet du grand arbre simplement pour transporter des eaux par coursier à travers Teldrassil. Envoyer des initiés prometteurs lui permet de tester votre discipline et votre préparation pour le monde extérieur, tout en s'assurant que le récipient sacré atteigne Corithras Ragelune sans laisser Sombrevallon sans surveillance.",al={"pourquoi m'envoyer","pourquoi tenaron a-t-il besoin de moi","pourquoi ne pas apporter le récipient lui-même"}}},fp="18,172,17.281.0,20.317.0,31.196.0,26.161.0,46.219.0,30.160.0,45.177.0,37.142.0"}
P.entries["quest:92812"] = {n="Economic Warfare",s="Un centaure Gelkis vous demande de récupérer des totems sculptés appartenant à d'autres clans. Ces totems racontent des histoires et donnent aux Gelkis plus de poids dans leurs négociations avec les Magram.",h="Un centaure Gelkis vous demande de récupérer des totems sculptés appartenant à d'autres clans.",kw={"troc","centaure","désolace","guerre économique","gelkis","magram","totem","échange"},sec={{t="Des histoires à échanger",b="Les Gelkis respectent une ancienne coutume des centaures : les clans échangent des totems sculptés qui racontent les grands exploits d'une personne ou d'un clan. Même s'ils restent en conflit, les clans honorent toujours cette tradition. Vous pouvez apporter aux Gelkis des totems pris aux centaures tombés d'autres clans, afin qu'ils aient davantage à offrir en échange."},{t="Les réserves des Gelkis",b="Les Gelkis ajoutent vos contributions à leur collection, et leur pouvoir grandit. Il leur reste encore beaucoup à faire avant de pouvoir vaincre le Magram Clan."}},faq={{q="Qu'échangent les centaures ?",a="Les clans centaures échangent des totems sculptés qui représentent les grands exploits d'une personne ou d'un clan.",al={"marchandises échangées par les centaures","objets échangés"}},{q="Pourquoi les totems sont-ils importants pour les Gelkis ?",a="Les Gelkis utilisent les totems comme monnaie d'échange, et chaque ajout à leur collection les renforce.",al={"totems gelkis","valeur des totems"}},{q="Les centaures échangent-ils encore pendant les combats ?",a="Oui. Les clans respectent la tradition malgré leur conflit sans fin, même si les occasions d'échanger se font rares.",al={"échanges entre clans centaures","échanges pendant les conflits"}},{q="Quel clan les Gelkis espèrent-ils vaincre ?",a="Les Gelkis espèrent vaincre le Magram Clan.",al={"ennemi des gelkis","clan magram"}}},fp="16,152,16.298.0,13.152.1,26.99.0,43.99.0,42.113.0,42.44.0"}
P.entries["quest:92819"] = {n="Destruction in Deadmines",s="Alba Fairmoon vous envoie contre la forge de la Confrérie défias, sous la Marche de l’Ouest. Les explosifs sont en place, et elle attend dans les collines derrière Ruisselune avec le détonateur.",h="Alba Fairmoon vous envoie contre la forge de la Confrérie défias, sous la Marche de l’Ouest.",kw={"alba fairmoon","les mortemines","défias","destruction in deadmines","détonateur","explosifs","sabotage","marche de l’ouest"},ang={["class:Rogue"]="Vous infiltrez le territoire ennemi, placez des charges, puis vous vous éclipsez avant l’explosion dans le cadre d’une opération de sabotage clandestine.",["faction:Alliance"]="En tant que membre de l’Alliance, chaque coup porté à la place forte des défias contribue à protéger les fermes en difficulté de la Marche de l’Ouest et la frontière sud de Hurlevent.",["profession:Engineering"]="La démolition et les détonateurs à distance sont au cœur de cette mission, un savoir-faire qui pourrait plaire aux ingénieurs."},sec={{t="Sabotage sous la Marche de l’Ouest",b="Sous la Marche de l’Ouest, les Mortemines abritent les forces de la Confrérie défias. Alba Fairmoon vous envoie saboter la forge cachée dans les mines. Les explosifs sont placés à côté. Vous retrouvez Alba dans les collines derrière Ruisselune, où vous pouvez les faire exploser à bonne distance. Elle espère que la déflagration permettra à la terre empoisonnée de la Marche de l’Ouest de commencer à guérir."},{t="Le détonateur",b="Au fond des Mortemines, la charge attend près de la forge. Après avoir retrouvé Alba Fairmoon dans les collines derrière Ruisselune, vous pouvez la faire exploser depuis l’extérieur des cavernes grâce à un détonateur à distance. Elle espère que la destruction de la forge permettra à la terre empoisonnée de la Marche de l’Ouest de commencer à guérir."}},faq={{q="Qui propose la quête Destruction in Deadmines, dans les Mortemines ?",a="Alba Fairmoon, une agente en Marche de l’Ouest, vous envoie contre la place forte de la Confrérie défias.",al={"qui donne destruction in deadmines","donneur de quête détonation mortemines","quête alba fairmoon"}},{q="Quel est l’objectif principal de cette mission ?",a="Vous faites exploser les charges placées près de la forge de la Confrérie défias dans les Mortemines. Retrouvez Alba Fairmoon, puis utilisez le détonateur depuis l’extérieur des mines.",al={"que faire dans destruction in deadmines","objectif de destruction in deadmines","comment terminer destruction in deadmines"}},{q="Pourquoi viser les Mortemines avec des explosifs ?",a="Alba Fairmoon a découvert que le poison des terres agricoles de la Marche de l’Ouest provenait d’une grande forge métallurgique cachée dans les Mortemines. Elle espère que sa destruction permettra à la terre de commencer à guérir.",al={"pourquoi faire exploser les mortemines","histoire du sabotage des mortemines","pourquoi utiliser un détonateur dans les mortemines"}},{q="Où cette quête se déroule-t-elle ?",a="Après avoir placé les explosifs, vous retrouvez Alba Fairmoon dans les collines derrière Ruisselune, à l’extérieur des Mortemines.",al={"lieu de destruction in deadmines","où se trouve destruction in deadmines","emplacement du détonateur des mortemines"}},{q="Cette mission est-elle accessible aux joueurs de la Horde ?",a="Non. Alba Fairmoon travaille avec les agents de l’Alliance qui défendent la Marche de l’Ouest contre la Confrérie défias.",al={"destruction in deadmines est-elle réservée à l’alliance","la horde peut-elle faire destruction in deadmines"}},{q="Quelle menace la Confrérie défias représente-t-elle en Marche de l’Ouest ?",a="La Confrérie défias a chassé les fermiers, pillé des villages et pris le contrôle des mines abandonnées de la Marche de l’Ouest. Depuis les profondeurs des Mortemines, elle prépare une insurrection armée qui menace le royaume de Hurlevent.",al={"histoire des défias en marche de l’ouest","pourquoi combattre les défias","que font les défias dans les mortemines"}}},fp="24,158,25.344.0,13.261.0,46.95.0,46.145.0,41.169.0,33.115.0,43.99.0,57.209.0"}
P.entries["quest:92834"] = {n="Avenged Tenfold",s="Elaadrin passe de la diplomatie aux représailles après que le culte d’Al’Aketh a répondu à son appel par la violence. L’érudit de l’Ordre suprême avait envoyé son cher ami Belathaan Brightwish chercher la paix au Sanctuaire d’Akir, au nord de Valanaar.",h="Elaadrin passe de la diplomatie aux représailles après que le culte d’Al’Aketh a répondu à son appel par la...",kw={"al’aketh","avenged tenfold","belathaan brightwish","elaadrin","gustberry fields","ordre suprême","sanctuaire d’akir","sculpte-vents","amulettes de pierre de vent"},ang={["class:Mage"]="En tant que mage, vous pouvez voir Elaadrin canaliser une puissance arcanique crépitante lorsqu’on le provoque. Le dévouement de l’Ordre suprême à la logique va de pair avec une formidable puissance magique."},sec={{t="L’ouverture diplomatique",b="La violence du culte d’Al’Aketh a poussé des factions comme les Peacekeepers et les Sculpte-vents à faire étalage de leur force armée. Elaadrin parlait au nom de l’Ordre suprême et jugeait ces démonstrations dangereusement insensées. Son ordre privilégie le pragmatisme et évite les conflits, aussi croyait-il encore qu’un dialogue raisonné pouvait fonctionner. Il a envoyé son ami proche, Belathaan Brightwish, au Sanctuaire d’Akir pour négocier la paix."},{t="Un refus macabre",b="Le culte d’Al’Aketh a répondu en envoyant un paquet contenant la langue tranchée de Belathaan, enduite de pigment argenté. Elaadrin était horrifié et rongé par la culpabilité. Il a compris que sa volonté d’agir avec noblesse avait coûté la vie à son cher ami, et reconnu que les Sculpte-vents avaient raison de rejeter les négociations. Il a abandonné la diplomatie et appelé les voyageurs à traquer les cultistes dans Gustberry Fields et au Sanctuaire d’Akir, et à récupérer leurs Al'Aketh Windstone Charms."},{t="Prudence et colère arcanique",b="L’Ordre suprême fait passer la logique avant les sentiments et estime qu’éviter l’effusion de sang est généralement la voie prudente. Pourtant, Elaadrin montre combien la logique froide peut se retourner contre vous quand des ennemis prennent la retenue pour de l’impuissance. Une énergie arcanique crépitante se rassemble autour de lui. L’Ordre suprême privilégie la paix, mais ceux qui massacrent ses émissaires s’exposent à des représailles écrasantes."}},faq={{q="Qui est Elaadrin ?",a="Elaadrin représente l’Ordre suprême et a d’abord cherché à faire la paix avec le culte d’Al’Aketh. Après le meurtre de son émissaire et ami proche Belathaan Brightwish, il a abandonné la diplomatie et ordonné l’élimination des cultistes.",al={"qui est elaadrin","donneur de quête avenged tenfold","qui donne cette quête"}},{q="Qu’est-il arrivé à Belathaan Brightwish ?",a="Belathaan Brightwish était l’ami proche d’Elaadrin et son émissaire au Sanctuaire d’Akir, envoyé pour engager un dialogue pacifique avec le culte d’Al’Aketh. Le culte l’a assassiné et a renvoyé à Elaadrin une boîte contenant sa langue tranchée, peinte avec un pigment argenté.",al={"qu’est-il arrivé à belathaan","qui est belathaan brightwish","pourquoi belathaan est-il mort"}},{q="Qui sont les cultistes d’Al’Aketh ?",a="Les Al’Aketh forment un culte violent actif au nord de Valanaar, autour de Gustberry Fields et du Sanctuaire d’Akir. Ils portent des amulettes de prière appelées Al'Aketh Windstone Charms et répondent avec violence aux ouvertures pacifiques des étrangers.",al={"qui sont les alaketh","qui sont les cultistes","culte d’al’aketh"}},{q="Qu’est-ce que l’Ordre suprême ?",a="L’Ordre suprême privilégie le pragmatisme, l’intellect et la logique. Ses membres cherchent généralement à éviter les conflits et à préserver la vie, mais peuvent répondre à une offense grave par de féroces représailles magiques.",al={"qu’est-ce que l’ordre suprême","croyances de l’ordre suprême"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents et les Peacekeepers sont des factions qui ont d’abord répondu par des démonstrations de force à la violence du culte d’Al’Aketh. Elaadrin a qualifié leur réaction d’inconsciente, mais a ensuite admis qu’ils avaient raison de rejeter les appels diplomatiques.",al={"qui sont les sculpte-vents","sculpte-vents et peacekeepers"}},{q="Où trouve-t-on les cultistes d’Al’Aketh ?",a="Les cultistes d’Al’Aketh se rassemblent au nord de Valanaar, dans Gustberry Fields et autour du Sanctuaire d’Akir. Belathaan Brightwish a été envoyé au Sanctuaire avant sa mort.",al={"où se trouve le sanctuaire d’akir","où se trouve gustberry fields","où se trouvent les cultistes"}}},fp="15,227,23.376.0,20.443.1,25.341.0,16.209.0,38.249.0,30.223.0,23.186.0,24.239.0,38.164.0"}
P.entries["quest:92840"] = {n="Catching Wind",s="Aux Pierres dressées surplombantes, l’Ordre suprême cherche des relevés qui pourraient aider à sauver Zephras. Son expédition se heurte à la vive opposition des Sculpte-vents dans les Hautes-terres de Shen’dar.",h="Aux Pierres dressées surplombantes, l’Ordre suprême cherche des relevés qui pourraient aider à sauver Zephras.",kw={"al’aketh","catching wind","fillion","ordre suprême","index esoteria","pierres dressées surplombantes","hautes-terres de shen’dar","valanaar","sculpte-vents","formations de pierre des vents","zephras"},ang={["class:Mage"]="En tant que mage, vous pourriez apprécier les mesures précises de l’Index Esoteria et considérer les forces élémentaires comme un domaine d’étude.",["class:Shaman"]="En tant que chaman, vous pourriez être tiraillé entre le respect des courants élémentaires des Sculpte-vents et le prélèvement mesuré de puissance élémentaire par l’Ordre suprême."},sec={{t="Mesurer les bourrasques",b="L’Ordre suprême étudie les flux élémentaires sauvages des Hautes-terres de Shen’dar dans l’espoir de sauver Zephras. Aux Pierres dressées surplombantes, ses chercheurs utilisent un Index Esoteria, un outil conçu pour recueillir des données sur les grandes formations de pierre des vents. Les Sculpte-vents voient ces sondes comme une intrusion profane qui outrage le vent."},{t="Dogme et recherche",b="L’expédition de l’Ordre suprême et les Sculpte-vents s’affrontent bientôt près des pierres. Les Sculpte-vents jugent que l’étude et le prélèvement d’énergie élémentaire profanent leurs traditions sacrées. L’Ordre suprême les considère comme prisonniers de croyances étroites, à l’image des violents Al’Aketh. Il ne laissera pas leur résistance interrompre ses efforts pour sauver le royaume."},{t="Le massacre des pierres dressées",b="Aux Pierres dressées surplombantes, l’Ordre suprême rencontre une résistance hostile et l’affrontement fait couler le sang parmi les pierres des vents. L’Ordre suprême obtient ses relevés grâce à l’Index Esoteria. Les Sculpte-vents qualifient les combats de massacre, et cette querelle jette une ombre sur Valanaar."}},faq={{q="De quoi parle la quête Catching Wind ?",a="L’Ordre suprême envoie un agent étudier l’énergie élémentaire aux Pierres dressées surplombantes, dans les Hautes-terres de Shen’dar. L’agent emporte un Index Esoteria pour recueillir des données sur les pierres des vents, malgré l’opposition des Sculpte-vents.",al={"qu’est-ce que catching wind","quête catching wind"}},{q="Qu’est-ce que l’Index Esoteria ?",a="L’Index Esoteria est un instrument de l’Ordre suprême conçu pour extraire, mesurer et consigner l’énergie élémentaire des grandes formations de pierre des vents aux Pierres dressées surplombantes.",al={"qu’est-ce que l’index esoteria","appareil index esoteria"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents défendent leurs sites sacrés et leurs croyances traditionnelles sur la magie élémentaire. Ils considèrent les recherches et les appareils de l’Ordre suprême comme une profanation et luttent pour empêcher les étrangers d’approcher des pierres des vents.",al={"qui sont les sculpte-vents","histoire des sculpte-vents"}},{q="Qui sont les Al’Aketh ?",a="Les Al’Aketh sont un groupe violent que l’Ordre suprême compare aux Sculpte-vents. L’Ordre suprême juge ces deux groupes dangereux et fanatiques, liés par des croyances inflexibles, mais considère les Al’Aketh comme plus violents.",al={"qui sont les al’aketh","al’aketh"}},{q="Où se trouvent les Pierres dressées surplombantes ?",a="Les Pierres dressées surplombantes se trouvent dans les Hautes-terres de Shen’dar. Leurs grandes formations de pierre des vents canalisent de puissants courants élémentaires, ce qui rend le site important pour les recherches de l’Ordre suprême.",al={"où se trouvent les pierres dressées surplombantes","emplacement des pierres dressées surplombantes"}},{q="Qui est Fillion ?",a="Fillion est un agent ou chercheur de l’Ordre suprême envoyé étudier l’énergie élémentaire aux Pierres dressées surplombantes. Après l’affrontement avec les Sculpte-vents, l’Ordre suprême a envoyé un aventurier muni de l’Index Esoteria pour récupérer les données.",al={"qu’est-il arrivé à fillion","qui est fillion"}},{q="Pourquoi l’Ordre suprême a-t-il besoin des données sur les pierres des vents ?",a="L’Ordre suprême estime que connaître les forces élémentaires du royaume est essentiel pour sauver Zephras. Il juge ces recherches nécessaires pour surmonter des menaces auxquelles les croyances traditionnelles ne peuvent répondre.",al={"pourquoi l’ordre suprême veut-il les données","sauver zephras"}}},fp="13,177,19.306.0,26.322.0,27.272.1,38.234.0,26.168.0,24.199.0,21.205.0,47.183.0,15.231.0,48.184.0"}
P.entries["quest:92849"] = {n="The Missing Scholar",s="Vous suivez la piste de Fillion Flamebreeze, disparu après une mission aux Pierres dressées surplombantes. Elle mène au nord, vers une grotte où une bête ailée l’a traîné.",h="Vous suivez la piste de Fillion Flamebreeze, disparu après une mission aux Pierres dressées surplombantes.",kw={"fillion","fillion flamebreeze","pierres dressées surplombantes","the missing scholar","sculpte-vents","bête ailée"},sec={{t="Le chercheur disparu",b="Vous trouvez des signes de lutte sur la piste qu’a suivie Fillion Flamebreeze. Ils indiquent qu’il a été victime d’un acte malveillant. En les suivant vers le nord, vous arrivez à une grotte sombre. Le chercheur disparu y est peut-être encore en vie, dans l’attente d’aide."},{t="L’embuscade des Sculpte-vents",b="Fillion Flamebreeze revenait d’une mission aux Pierres dressées surplombantes lorsque les Sculpte-vents lui ont tendu une embuscade. Ils l’ont roué de coups, traîné jusqu’à l’entrée de la grotte et laissé là, en sang. Sans défense, il a dû affronter ce qui l’attendait à l’intérieur."},{t="Le repaire de la bête ailée",b="Alors que Fillion agonisait sur le seuil de la caverne, une imposante bête ailée a surgi des ténèbres et l’a traîné à l’intérieur. Elle l’a emporté au fond de son repaire pour nourrir ses petits. Un sauvetage opportun lui a épargné ce sort."}},faq={{q="Qui est Fillion Flamebreeze ?",a="Fillion Flamebreeze est un érudit qui revenait d’une mission aux Pierres dressées surplombantes lorsque les Sculpte-vents lui ont tendu une embuscade. Laissé en sang et inconscient devant une grotte voisine, il a été traîné à l’intérieur par un imposant prédateur ailé.",al={"qui est fillion","fillion flamebreeze","pnj chercheur disparu"}},{q="Que faisait Fillion aux Pierres dressées surplombantes ?",a="Les Pierres dressées surplombantes étaient le lieu de la mission d’étude de Fillion Flamebreeze. Sur le chemin du retour, il est tombé dans une embuscade tendue par les Sculpte-vents. La nature exacte de ses recherches reste inconnue.",al={"que sont les pierres dressées surplombantes","mission aux pierres surplombantes","mission de fillion"}},{q="Qui a attaqué Fillion Flamebreeze ?",a="Les Sculpte-vents ont tendu une embuscade à Fillion Flamebreeze et l’ont roué de coups. Ils l’ont traîné jusqu’à l’entrée d’une grotte voisine et l’ont laissé en sang, à peine conscient.",al={"qui a attaqué fillion","que sont les sculpte-vents","embuscade des sculpte-vents"}},{q="Quelle créature a emmené Fillion dans la grotte ?",a="Une imposante bête ailée, dans une grotte au nord du lieu de l’embuscade, a emporté Fillion depuis l’entrée. Elle l’a traîné dans son repaire pour nourrir ses petits affamés.",al={"bête de la grotte","monstre ailé fillion","qui a emmené fillion"}},{q="Où trouver Fillion Flamebreeze ?",a="Des indices sur les lieux du malheur de Fillion Flamebreeze pointent vers une grotte située juste au nord. Il est prisonnier du nid de la bête et attend d’être secouru avant d’être dévoré.",al={"comment trouver fillion","où est le chercheur disparu","emplacement de la grotte de fillion"}},{q="Qu’est-il arrivé au chercheur disparu ?",a="Fillion survit à son épreuve parce que quelqu’un intervient à temps dans la grotte. Sans un aventurier pour le trouver et lui porter secours, il aurait fini dans l’assiette de la bête ailée et de ses petits.",al={"fillion a-t-il survécu","qu’arrive-t-il à fillion flamebreeze","sauver le chercheur disparu"}}},fp="19,179,23.215.0,25.234.1,24.217.1,27.237.0,55.204.0,33.144.0,41.165.0,39.186.0,41.190.0"}
P.entries["quest:92850"] = {n="The Missing Scholar",s="Fillion Flamebreeze est bloqué près d’une tanière dangereuse, et Valanaar doit être débarrassée de cette menace. Dès qu’il peut voyager, il vous demande de tuer la matriarche criailleuse des environs.",h="Fillion Flamebreeze est bloqué près d’une tanière dangereuse, et Valanaar doit être débarrassée de cette...",kw={"fillion flamebreeze","criailleuse","tanière des criailleuses","matriarche criailleuse","supreme magister","the missing scholar","valanaar"},ang={["class:Mage"]="En tant que mage, vous avez reçu la même formation aux arts des arcanes que Fillion Flamebreeze. Il s’appuie sur cette formation pour se rétablir et voyager en sécurité."},sec={{t="Un nid dangereux",b="Après cette épreuve, Fillion Flamebreeze peut reprendre la route vers Valanaar et sa sécurité. Pourtant, une couvée de criailleuses a établi son nid près de la colonie. Fillion vous demande d’entrer dans la Tanière des criailleuses et de tuer la matriarche criailleuse avant que les bêtes ne menacent la ville."},{t="Rendre compte au magister",b="Quand vous rapportez la tête de la matriarche à Fillion, à Valanaar, il vous remercie. Pourtant, les criailleuses sont le cadet de leurs soucis. Fillion s’apprête à rendre compte de sa mission et de la région environnante au Supreme Magister."}},faq={{q="Qui est Fillion Flamebreeze ?",a="Fillion Flamebreeze est un érudit versé dans les arts des arcanes. Il était en mission près de Valanaar avant de se retrouver bloqué près d’un nid de bêtes dangereuses.",al={"qui est fillion flamebreeze","qui est l’érudit","qui donne the missing scholar"}},{q="Que sont les criailleuses ?",a="Les criailleuses sont des bêtes hostiles qui nichent dans une tanière proche de Valanaar. Leur présence menace tous ceux qui voyagent dans la région.",al={"que sont les criailleuses","où nichent les criailleuses","menace des criailleuses"}},{q="Qui est le Supreme Magister ?",a="Le Supreme Magister est Elaadrin Evengale, qui dirige l’Ordre suprême à Valanaar. Fillion lui rend compte des événements survenus dans la tanière et de l’état de sa mission.",al={"qui est le supreme magister","rapport de fillion","à qui fillion rend-il compte"}},{q="Qu’est-ce que Valanaar ?",a="Valanaar est la colonie proche où Fillion est en poste. Il y retourne dès qu’il est assez rétabli pour voyager.",al={"qu’est-ce que valanaar","où se trouve valanaar"}},{q="Qu’est-ce que la matriarche criailleuse ?",a="La matriarche criailleuse dirige les criailleuses qui nichent dans la Tanière des criailleuses. Fillion vous demande de la tuer et de rapporter sa tête afin d’écarter le danger immédiat qui menace Valanaar.",al={"cible : matriarche criailleuse","qui tuer dans la tanière des criailleuses"}},{q="Pourquoi Fillion considère-t-il les criailleuses comme le cadet de leurs soucis ?",a="Les criailleuses menacent Valanaar parce qu’elles nichent tout près de la colonie. À votre retour, Fillion dit qu’elles ne sont que le cadet de leurs soucis.",al={"pourquoi le cadet de leurs soucis","plus grand danger pour valanaar"}}},fp="19,163,25.263.0,25.226.1,27.156.0,21.128.0,28.157.0,17.118.0,33.171.0,70.152.0"}
P.entries["quest:92860"] = {n="In Service of Zephras",s="L’Ordre suprême offre désormais à Valanaar tout son soutien militaire et diplomatique contre la secte des Al’Aketh. Les mouvements hostiles sur l’île ont mis fin à sa politique d’évitement de la confrontation directe.",h="L’Ordre suprême offre désormais à Valanaar tout son soutien militaire et diplomatique contre la secte des...",kw={"al’aketh","belathaan","secte des al’aketh","ordre suprême","in service of zephras","stormfist","valanaar","valennia stormfist","zephras"},sec={{t="La menace grandissante",b="L’Ordre suprême a longtemps tenté d’éviter un conflit ouvert avec la secte secrète des Al’Aketh. Des rapports faisant état de mouvements de troupes importants et d’une hostilité manifeste ont mis fin à cette politique. Les sectateurs se mobilisent, et chaque colonie de l’île voit sa paix et sa sécurité menacées. L’Ordre suprême a donc décidé d’agir. Il envoie un émissaire rejoindre les défenseurs locaux avant que les Al’Aketh ne frappent."},{t="Alliance avec Valanaar",b="Valennia Stormfist accepte l’offre de soutien sans réserve de l’Ordre suprême pour la résistance de Valanaar contre les Al’Aketh. Ensemble, les deux camps peuvent former une défense unie et préparer des opérations militaires conjointes dans la région. L’émissaire lui annonce aussi la mort de Belathaan. Le cousin de Valennia était un serviteur dévoué de Zephras. Elle le pleure et jure de le venger, puis se tourne vers les préparatifs de la campagne à venir."}},faq={{q="De quoi parle la quête In Service of Zephras ?",a="L’Ordre suprême envoie un émissaire auprès de Valennia Stormfist pour promettre son soutien à Valanaar. Il avait tenté d’éviter la violence directe avec les Al’Aketh, mais leur hostilité et les rapports de mouvements de troupes importants sur l’île l’ont contraint à changer de politique. Cette offre entraîne l’Ordre suprême dans la défense de Valanaar et annonce la mort de Belathaan.",al={"aperçu d’in service of zephras","que se passe-t-il dans in service of zephras","quête in service of zephras"}},{q="Qui est Valennia Stormfist ?",a="Valennia Stormfist dirige les efforts de défense contre les Al’Aketh à Valanaar. Elle reçoit l’offre d’aide mutuelle de l’Ordre suprême. Belathaan, son cousin et serviteur de Zephras, est mort. Valennia jure de venger ceux qui menacent son peuple.",al={"histoire de valennia stormfist","qui est valennia","valennia stormfist"}},{q="Qui était Belathaan ?",a="Belathaan était le cousin de Valennia Stormfist et un serviteur dévoué de Zephras. L’émissaire apprend sa mort à Valennia. Cette nouvelle rend le conflit plus personnel et renforce sa promesse de le venger.",al={"qui est belathaan","histoire de belathaan","qu’est-il arrivé à belathaan"}},{q="Que sont les Al’Aketh ?",a="Les Al’Aketh sont une secte hostile active sur l’île. Leurs actes hostiles et leurs mouvements de troupes menacent le peuple de Zephras. L’Ordre suprême a renoncé à éviter un conflit direct et s’est allié à d’autres contre la secte.",al={"qui sont les al’aketh","secte des al’aketh","que sont les alaketh"}},{q="Quel rôle joue l’Ordre suprême dans ce conflit ?",a="L’Ordre suprême a d’abord cherché à éviter une guerre directe contre les Al’Aketh. Leurs actes hostiles et les rapports de mouvements de troupes importants ont convaincu ses dirigeants d’agir. L’Ordre suprême envoie désormais un messager auprès de Valennia Stormfist et promet toute sa puissance à la résistance de Valanaar.",al={"rôle de l’ordre suprême","pourquoi l’ordre suprême se bat-il","ordre suprême et zephras"}},{q="Qu’est-ce que Zephras ?",a="Zephras est l’île aussi appelée Île de Zéphras, que l’Ordre suprême, Valanaar et ses défenseurs cherchent à protéger. Les mouvements grandissants des Al’Aketh menacent son peuple, et Belathaan reste dans les mémoires comme un fidèle serviteur de Zephras. C’est pour assurer la sécurité de ce peuple que l’Ordre suprême rejoint la défense.",al={"où se trouve zephras","qui est zephras","histoire de zephras"}}},fp="21,194,20.378.0,22.413.1,46.324.0,26.251.0,18.227.0,21.223.0,47.266.0,16.284.0"}
P.entries["quest:92867"] = {n="Ground to Keep",s="Le gardien des terres Lomar vous demande de chasser les intrus du Donjon de Stromgarde. Les sculptures et les lieux de sépulture sacrés qui subsistent du royaume doivent être protégés.",h="Le gardien des terres Lomar vous demande de chasser les intrus du Donjon de Stromgarde.",kw={"boulderfist","lieux de sépulture","terres à préserver","gardien des terres lomar","sculptures","stromgarde","donjon de stromgarde","syndicat","witherbark"},sec={{t="Les vestiges d’un royaume",b="Au Donjon de Stromgarde, le gardien des terres Lomar vous demande de repousser les intrus Boulderfist, du Syndicat et Witherbark. Il dit que Stromgarde a d’autres ressources en réserve, qui doivent rester cachées pour les protéger. Le soutien grandit en faveur de la préservation des sculptures et des lieux de sépulture sacrés qui subsistent du royaume."}},faq={{q="Qui demande de l’aide ?",a="Le gardien des terres Lomar vous demande de chasser les intrus Boulderfist, du Syndicat et Witherbark du Donjon de Stromgarde.",al={"qui demande de l’aide","gardien des terres lomar","qui a donné cela"}},{q="Pourquoi protéger les vestiges de Stromgarde ?",a="Le soutien grandit en faveur de la préservation des sculptures et des lieux de sépulture sacrés qui subsistent à Stromgarde.",al={"pourquoi protéger stromgarde","que faut-il protéger","protéger les sculptures"}},{q="Quels intrus se trouvent au Donjon de Stromgarde ?",a="Les Boulderfist, le Syndicat et les Witherbark se sont installés au Donjon de Stromgarde.",al={"qui se trouve dans le donjon","ennemis à stromgarde","boulderfist syndicat witherbark"}},{q="Que faut-il garder caché ?",a="Lomar dit que Stromgarde a d’autres ressources en réserve, qui doivent rester cachées pour les protéger.",al={"qu’est-ce qui est caché","réserves de stromgarde","que faut-il garder secret"}}},fp="14,149,19.307.0,23.112.0,47.96.0,39.86.0,24.92.0"}
P.entries["quest:92871"] = {n="In Service of Zephras",s="Partout sur Zephras, le culte d’Al’Aketh se rassemble en vue d’un conflit plus vaste. Les Sculpte-vents envoient un émissaire pour assurer à Valennia Stormfist qu’ils aideront ses pacificateurs.",h="Partout sur Zephras, le culte d’Al’Aketh se rassemble en vue d’un conflit plus vaste.",kw={"al’aketh","in service of zephras","valanaar","valennia stormfist","sculpte-vents","zephras"},sec={{t="Rumeurs sur l’île",b="Les rapports sur les activités d’Al’Aketh se répandent sur Zephras. Les pacificateurs de Valennia Stormfist veillent sur l’île depuis longtemps, mais le culte semble maintenant préparer un conflit de plus grande ampleur. Les Sculpte-vents promettent donc de soutenir les forces de Valanaar si les combats éclatent au grand jour."},{t="Promesse de soutien",b="Vous êtes envoyé auprès de Valennia Stormfist pour lui assurer que les Sculpte-vents sont prêts à aider ses pacificateurs. Valennia accueille favorablement leur promesse rapide. Elle est prête à discuter avec vous de la menace croissante du culte."}},faq={{q="Qui est Valennia Stormfist ?",a="Valennia Stormfist dirige les pacificateurs qui protègent Zephras. Elle supervise la défense de l’île, notamment la campagne de Valanaar contre Al’Aketh.",al={"qui est valennia stormfist","valennia stormfist"}},{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents sont des alliés sur Zephras qui aident Valennia Stormfist et ses pacificateurs. Ils offrent tout leur soutien aux forces de Valanaar face à la menace croissante d’Al’Aketh.",al={"qui sont les sculpte-vents","histoire des sculpte-vents"}},{q="Que sont les Al’Aketh ?",a="Les Al’Aketh sont un culte actif sur toute l’étendue de Zephras. Selon les rapports, ses membres préparent des opérations de plus grande envergure et se préparent au conflit.",al={"qui sont les al’aketh","que sont les al’aketh","culte d’al’aketh"}},{q="Qu’est-ce que Zephras ?",a="Zephras est une île défendue par Valennia Stormfist et ses pacificateurs. Les Sculpte-vents les aident à lutter contre le culte d’Al’Aketh.",al={"qu’est-ce que zephras","île de zephras"}},{q="Qu’est-ce que Valanaar ?",a="Valanaar est un village de Zephras et le foyer des pacificateurs de Valennia Stormfist. Les Sculpte-vents soutiennent pleinement sa lutte contre Al’Aketh.",al={"qu’est-ce que valanaar","qui est valanaar"}}},fp="21,167,20.279.0,16.208.0,26.148.0,24.175.0,22.115.0,16.125.0,17.144.0"}
P.entries["quest:92872"] = {n="Dutiful Steps",s="Le gardien Alaric vous demande de porter de la poussière funéraire du Donjon de Stromgarde jusqu’à la mer. Ce rite renouvelle le souvenir des morts.",h="Le gardien Alaric vous demande de porter de la poussière funéraire du Donjon de Stromgarde jusqu’à la mer.",kw={"gardien alaric","rites cérémoniels","crypte","pas dévoués","morts","grande mer","sacoche de poussière funéraire","donjon de stromgarde","poussière funéraire"},sec={{t="Vers la mer",b="Votre retour vers le monde ensoleillé commence par une petite sacoche. Le gardien Alaric vous demande de la porter jusqu’aux falaises derrière le Donjon de Stromgarde et d’en jeter le contenu dans la Grande mer. Cette poussière vient du tombeau sous le donjon, où ses gardiens préservent les rites cérémoniels en l’honneur des morts. À chaque saison, une partie est répandue dans les océans d’Azeroth, pour symboliser le renouvellement d’un cycle."}},faq={{q="Qui me demande de porter la poussière ?",a="Le gardien Alaric vous demande de porter la poussière funéraire de la crypte du Donjon de Stromgarde jusqu’à la mer.",al={"qui m’a confié cette tâche","requête d’alaric"}},{q="Que contient la sacoche ?",a="La sacoche contient de la poussière provenant du tombeau sous le Donjon de Stromgarde.",al={"contenu de la sacoche","poussière funéraire"}},{q="Pourquoi répandre la poussière funéraire dans la mer ?",a="À chaque saison, une partie de la poussière funéraire est répandue dans les océans d’Azeroth pour symboliser le renouvellement des cycles.",al={"pourquoi jeter de la poussière dans l’océan","à quoi sert la poussière"}},{q="Où dois-je jeter la sacoche ?",a="Le gardien Alaric vous demande de jeter la poussière funéraire dans la Grande mer depuis les falaises derrière le Donjon de Stromgarde.",al={"où la jeter","falaises derrière stromgarde"}},{q="Que préservent les gardiens du tombeau ?",a="Les gardiens du tombeau préservent les connaissances des rites cérémoniels servant à honorer les morts.",al={"contenu du tombeau","rites cérémoniels"}}},fp="13,142,14.371.0,35.91.0,23.61.0,43.101.0,37.106.0,40.87.0"}
P.entries["quest:92880"] = {n="Return to Valanaar",s="Yorna annonce à Valanaar que la tour de guet orientale a tenu. Son périmètre est sécurisé et les derniers assaillants sont éliminés.",h="Yorna annonce à Valanaar que la tour de guet orientale a tenu.",kw={"tour de guet orientale","quatre vents","return to valanaar","valanaar","valennia stormfist","yorna","yorna's report"},ang={["race:Skyborne"]="En tant que Skyborne, vous partagez les liens des défenseurs et des dirigeants avec les quatre vents, exprimés dans leur bénédiction."},sec={{t="Nouvelles de l'avant-poste",b="Après l'attaque contre l'avant-poste, Yorna envoie des nouvelles à Valanaar. Les assaillants ont été mis en déroute et les défenseurs éliminent ceux qui restent. Vous portez Yorna's Report pour rassurer les dirigeants qui attendent des nouvelles en ville."},{t="Soulagement à Valanaar",b="Vous apportez le rapport de la tour de guet orientale à Valennia Stormfist, à Valanaar. La tour a tenu et son périmètre est sécurisé. Soulagée de savoir que la frontière reste sûre, Valennia remercie les vents."}},faq={{q="Qui vous envoie à Valanaar ?",a="Yorna vous envoie à Valanaar après la défense acharnée de l'avant-poste. Elle vous demande de porter un rapport aux dirigeants de la colonie.",al={"qui donne la quête return to valanaar","qui vous renvoie à valanaar","yorna donneuse de quête"}},{q="À qui remettre votre rapport à Valanaar ?",a="Vous remettez votre rapport à Valennia Stormfist, à Valanaar. Elle attend des nouvelles des défenseurs de la périphérie et de leur sécurité.",al={"qui est valennia stormfist","où se trouve valennia stormfist","où remettre return to valanaar"}},{q="Qu'est-ce que Yorna's Report ?",a="Yorna's Report indique que les défenseurs ont consolidé leur position et éliminent les assaillants qui restent.",al={"qu'est-ce que yorna's report","que dit le rapport de yorna"}},{q="Quelle tour de guet a été attaquée ?",a="Yorna et ses forces ont défendu la tour de guet orientale, une position clé pour surveiller les accès à Valanaar.",al={"quelle tour a été attaquée","à quelle tour de guet se trouve yorna"}},{q="Quel est l'état de la tour de guet orientale ?",a="Les défenseurs ont sécurisé la tour de guet orientale et stabilisé la situation. Ils éliminent encore les assaillants qui restent.",al={"la tour de guet est-elle sûre","les défenseurs ont-ils gagné"}},{q="Pourquoi les défenseurs parlent-ils des quatre vents ?",a="Les défenseurs de Valanaar honorent les quatre vents et les éléments. Leur bénédiction et les remerciements de Valennia aux vents témoignent de cette révérence.",al={"signification des quatre vents","que les quatre vents vous bénissent"}}},fp="18,153,21.219.0,18.204.0,26.128.0,33.105.0,23.112.0,34.105.0,45.130.0,45.135.0"}
P.entries["quest:92881"] = {n="The High Elder's Request",s="À Valanaar, le grand aîné Talaanis Shadowsong appelle à l'aide après des assauts coordonnés contre les tours de guet de la région. Des rapports de la tour de guet occidentale signalent qu'une secte hostile prend pour cible les pylônes d'ancrage locaux.",h="À Valanaar, le grand aîné Talaanis Shadowsong appelle à l'aide après des assauts coordonnés contre les tours...",kw={"pylônes d'ancrage","tour de guet orientale","shadowsong","prêtre du ciel","talaanis shadowsong","the high elder's request","valanaar","tour de guet occidentale"},ang={["class:Priest"]="Pour les prêtres qui étudient la manipulation divine ou rituelle, l'intérêt de la secte pour les pylônes d'ancrage et le rôle du prêtre du ciel à la tour de guet occidentale sont des signes inquiétants."},sec={{t="Problèmes aux tours de guet",b="Des assauts coordonnés contre les tours de guet occidentale et orientale révèlent une tendance inquiétante. Ce qui semblait être des escarmouches dispersées indique désormais une attaque planifiée contre les pylônes d'ancrage locaux. Un rapport de la tour de guet occidentale explique comment un prêtre du ciel a révélé l'intérêt de la secte pour ces structures. La défense des tours est désormais une priorité urgente."},{t="Audience à Valanaar",b="La menace qui pèse sur les pylônes d'ancrage grandit, alors les dirigeants vous envoient parler au grand aîné Talaanis Shadowsong à Valanaar. Il dispose d'une piste prometteuse sur les déplacements de la secte et cherche des alliés expérimentés pour traquer l'ennemi. La secte pourrait préparer un rituel ou un sabotage."}},faq={{q="Qui est le grand aîné Shadowsong ?",a="Le grand aîné Talaanis Shadowsong est un dirigeant de Valanaar. Une activité coordonnée de la secte a frappé les tours de guet de la région, et il cherche des alliés capables d'enquêter sur ses intentions.",al={"qui est talaanis shadowsong","grand aîné shadowsong","où se trouve shadowsong"}},{q="Où se trouve Valanaar ?",a="Valanaar est le lieu où le grand aîné Talaanis Shadowsong est en poste. Il coordonne les défenses et enquête sur les incursions de la secte visant les pylônes d'ancrage et les tours locales.",al={"qu'est-ce que valanaar","emplacement de valanaar"}},{q="Pourquoi les tours de guet ont-elles été attaquées ?",a="Des attaques coordonnées ont frappé les tours de guet occidentale et orientale. Les défenseurs soupçonnent des manœuvres délibérées visant les pylônes d'ancrage voisins, et non des raids au hasard.",al={"pourquoi les tours de guet ont-elles été attaquées","tours de guet occidentale et orientale","attaques contre les tours de guet"}},{q="Que sont les pylônes d'ancrage ?",a="Les pylônes d'ancrage sont des structures importantes pour la défense ou la région. Des rapports de la tour de guet occidentale laissent penser qu'une secte hostile cherche à s'en prendre à eux ou à les détourner de leur fonction.",al={"que sont les pylônes d'ancrage","secte et pylônes d'ancrage","pourquoi les pylônes d'ancrage"}},{q="Qui était le prêtre du ciel à la tour de guet occidentale ?",a="Un prêtre du ciel a été impliqué dans l'incident de la tour de guet occidentale. Les rapports issus de cette rencontre ont amené les dirigeants à soupçonner que la secte poursuit un plan plus vaste impliquant les pylônes d'ancrage.",al={"qui était le prêtre du ciel","prêtre du ciel à la tour de guet occidentale","rôle du prêtre du ciel"}},{q="Quelle secte prend les tours de guet pour cible ?",a="Une secte hostile a mené des attaques simultanées contre les tours de guet de la région. Sa nature et ses motivations font toujours l'objet d'une enquête, tandis que le grand aîné Shadowsong cherche à découvrir ses plans.",al={"de quelle secte s'agit-il","qui a attaqué les tours"}}},fp="24,213,26.339.0,20.266.0,29.188.0,18.159.0,34.160.0,27.166.0,48.177.0,39.179.0"}
P.entries["quest:929"] = {n="La couronne de la Terre",s="Près de Brise-stellaire, vous puisez de l’eau sacrée pour Darnassus. À Dolanaar, Corithras Ragelune envoie les jeunes elfes de la nuit remplir le puits de lune de la cité. Il leur apprend pourquoi leur peuple prend soin des grandes ramures de Teldrassil.",h="Près de Brise-stellaire, vous puisez de l’eau sacrée pour Darnassus.",kw={"corithras ragelune","crown of the earth","dolanaar","flasque de jade","puits de lune","nordrassil","brise-stellaire","teldrassil"},ang={["class:Druid"]="En tant que druide, vous connaissez les puits de lune, réservoirs vivants de magie naturelle et astrale. Leurs eaux relient les devoirs de votre ordre à Darnassus aux racines de Teldrassil.",["race:NightElf"]="En tant qu’elfe de la nuit, vous êtes confronté à la perte de l’immortalité et à la disparition de Malfurion Hurlorage. En puisant l’eau des puits de lune, vous découvrez le récent chagrin de votre peuple."},sec={{t="Entretenir les puits de lune",b="Les druides vous ont préparé une flasque de jade pour votre voyage à Brise-stellaire. Là-bas, un puits de lune secondaire contient de l’eau sanctifiée. Le travail raffiné de la flasque vous permet de puiser cette eau lumineuse et de la transporter sans altérer sa pureté.\n\nLe puits de lune central de Darnassus dépend de sources disséminées comme celle-ci. Les anciens envoient les initiés à pied remplir les fontaines de la cité de la grâce d’Elune. Ce voyage apprend aux jeunes ce qu’il faut pour nourrir Teldrassil."},{t="Échos de la troisième guerre",b="Corithras Ragelune vous parle du chagrin qui a suivi la bataille du mont Hyjal. Les elfes de la nuit ont sacrifié Nordrassil, leur Arbre-Monde ancestral, et perdu leur immortalité. Illidan Hurlorage a été libéré au milieu des ruines, tandis que Shan'do Malfurion Hurlorage disparaissait.\n\nLes jours qui suivirent furent marqués par le deuil et l’isolement. Les kaldorei se tournèrent vers Teldrassil."}},faq={{q="À quoi sert l’eau des puits de lune ?",a="Les druides de Darnassus remplissent le puits de lune principal de la cité avec l’eau des sanctuaires forestiers. Cela entretient le réseau sacré qui s’étend sur Teldrassil.",al={"pourquoi puiser l’eau des puits de lune","utilité de l’eau des puits de lune","utilité de la flasque de jade"}},{q="Où se trouve le puits de lune pour cette tâche ?",a="Le puits de lune se trouve juste à l’extérieur de Brise-stellaire, à l’est de Dolanaar, le long du sentier forestier.",al={"où se trouve le puits de lune","emplacement du puits de lune de brise-stellaire","puits de brise-stellaire"}},{q="Qui est Corithras Ragelune ?",a="Corithras Ragelune est un elfe de la nuit de Dolanaar qui guide les jeunes aventuriers dans leurs devoirs rituels. Il leur enseigne l’histoire liée à la santé de Teldrassil.",al={"qui donne la quête","histoire de corithras ragelune"}},{q="Quelle histoire Corithras raconte-t-il à votre retour ?",a="Corithras raconte les conséquences de la bataille du mont Hyjal. Nordrassil a été sacrifié, les kaldorei ont perdu leur immortalité, Illidan a été libéré et Shan'do Malfurion Hurlorage a disparu.",al={"que raconte corithras","texte de l’histoire crown of the earth"}},{q="Pourquoi les elfes de la nuit se sentent-ils perdus après le mont Hyjal ?",a="Nordrassil offrait aux elfes de la nuit une vie éternelle et une protection. Ils ont sacrifié son pouvoir pour détruire Archimonde, perdant ainsi leur existence intemporelle et devenant mortels, sans repères et profondément vulnérables.",al={"pourquoi les elfes ont perdu leur immortalité","que s’est-il passé après hyjal"}},{q="Que signifie Shan'do ?",a="Shan'do signifie « maître honoré » en darnassien. C’est un titre honorifique donné à Malfurion Hurlorage, le chef suprême des druides.",al={"que signifie shan'do","signification de shan'do"}}},fx={["5a4296ad"]={q="Pourquoi Corithras Ragelune veut-il que cela soit fait ?",a="Corithras accomplit des devoirs vitaux pour le Cercle cénarien tout en éduquant les jeunes elfes de la nuit sur l'état fragile de leur peuple. Les eaux sacrées de Teldrassil exigent des soins constants et de l'équilibre, et les druides de Darnassus dépendent de l'eau fraîche recueillie dans les puits de lune extérieurs à travers les branches. En échangeant ce service contre de l'histoire et des conseils, Corithras s'assure à la fois que le puits de lune de Darnassus reste approvisionné et que vous compreniez les lourds fardeaux que votre peuple porte à la suite de la Troisième Guerre.",al={"mobile de corithras ragelune","pourquoi corithras a-t-il besoin d'eau","tâche du puits de lune de corithras"}},["0abe9d82"]={q="À quoi sert la Flasque de jade remplie ?",a="La Flasque de jade remplie contient de l'eau sacrée recueillie au puits de lune près de Brise-stellaire. Spécialement conçue pour contenir et préserver les eaux des puits de lune sans diminuer leur puissance magique latente, elle apporte un réapprovisionnement aux druides de Darnassus, qui puisent dans la force combinée des sources de Teldrassil pour leurs rituels et leurs soins.",al={"but de la flasque de jade remplie","à quoi sert la flasque de jade","flasque de jade remplie"}}},fp="18,215,24.445.0,23.359.0,46.138.0,44.90.0,26.151.0,46.194.0,47.202.0,18.122.0"}
P.entries["quest:92909"] = {n="Harvesting the Harvesters",s="À la Ferme des Saldean, dans la Marche de l’Ouest, Ozwin Ironsprocket est piégé par des golems des moissons détraqués. Ce bricoleur gnome de passage a besoin de pièces récupérées pour construire un moyen de s’échapper.",h="À la Ferme des Saldean, dans la Marche de l’Ouest, Ozwin Ironsprocket est piégé par des golems des moissons...",kw={"isoresorts de golem","golems des moissons","gyrostabilisateurs de moissonneur","harvesting the harvesters","forgefer","ozwin ironsprocket","ferme des saldean","marche de l’ouest"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance à la Ferme des Saldean, vous pouvez aider un érudit gnome de passage, échoué après sa tentative ratée de réparer les moissonneurs détraqués de la Marche de l’Ouest.",["profession:Engineering"]="En tant qu’ingénieur, vous pouvez récupérer des isoresorts et des gyrostabilisateurs sur les golems des moissons détraqués et les utiliser comme pièces pour un dispositif d’évasion.",["race:Gnome"]="En tant que gnome, vous connaissez bien l’ambition d’Ozwin de bricoler des machines complexes. Il a sous-estimé l’agressivité des machines et s’est retrouvé acculé dans une étable de ferme."},sec={{t="Une entreprise mal calculée",b="Ozwin Ironsprocket est venu de Forgefer vers le sud, après que ses ateliers ont appris que des moissonneurs mécaniques détraqués sévissaient dans la Marche de l’Ouest. L’ingénieur gnome pensait pouvoir diagnostiquer et recalibrer les machines agricoles. Il espérait ramener la paix dans les terres agricoles de la région, déjà troublées par les hors-la-loi et désormais envahies par des moissonneurs déchaînés."},{t="Coincé dans l’étable",b="Près de la Ferme des Saldean, Ozwin a découvert que les golems des moissons étaient bien plus violents que ne le suggéraient ses schémas. Leurs lames acérées et leurs mouvements erratiques l’ont poussé à se réfugier dans une étable voisine. Piégé à l’intérieur, il ne peut pas retourner aux champs sans danger. Il a besoin de voyageurs audacieux pour récupérer des isoresorts et des gyrostabilisateurs sur les machines afin de construire un appareil qui lui permettra de s’échapper."}},faq={{q="Qui est Ozwin Ironsprocket ?",a="Ozwin Ironsprocket est un bricoleur gnome de Forgefer venu dans la Marche de l’Ouest pour recalibrer les golems des moissons déchaînés. Leur hostilité l’a poussé à se réfugier dans une étable de la Ferme des Saldean.",al={"qui est ozwin ironsprocket","ozwin","donneur de quête"}},{q="Pourquoi les golems des moissons sont-ils si agressifs ?",a="Les golems des moissons des champs abandonnés de la Marche de l’Ouest se montrent extrêmement agressifs envers les passants. Leur férocité dépasse de loin ce à quoi Ozwin s’attendait lorsqu’il pensait qu’un simple recalibrage suffirait à les réparer.",al={"pourquoi les moissonneurs attaquent","pourquoi les golems sont agressifs","qu’est-ce qui ne va pas avec les moissonneurs"}},{q="Où trouver Ozwin Ironsprocket ?",a="Ozwin Ironsprocket se cache dans une étable de la Ferme des Saldean, dans la Marche de l’Ouest, à l’abri des golems des moissons qui rôdent dans les champs voisins.",al={"où se trouve ozwin ironsprocket","où rendre la quête harvesting the harvesters","emplacement d’ozwin"}},{q="Que compte construire Ozwin avec les pièces récupérées ?",a="Ozwin a besoin d’isoresorts de golem et de gyrostabilisateurs de moissonneur pour construire un engin mécanique qui lui permettra de fuir l’étable sans danger.",al={"à quoi servent les pièces dont ozwin a besoin","pourquoi récupérer des isoresorts","pièces pour un dispositif d’évasion"}},{q="Pourquoi Ozwin a-t-il voyagé de Forgefer à la Marche de l’Ouest ?",a="Ozwin a voyagé de Forgefer à la Marche de l’Ouest après avoir appris que des machines détraquées terrorisaient la campagne. Il pensait pouvoir recalibrer les moissonneurs.",al={"pourquoi ozwin est venu dans la marche de l’ouest","pourquoi quitter forgefer"}},{q="D’où viennent les pièces de golem requises ?",a="Les isoresorts et les gyrostabilisateurs proviennent des golems des moissons et des moissonneurs hostiles dans les champs autour de la Ferme des Saldean, dans la Marche de l’Ouest.",al={"où trouver les pièces","comment obtenir des isoresorts et des gyrostabilisateurs"}}},fp="25,156,24.307.0,20.345.0,26.178.0,41.190.0,38.124.0,57.134.0,48.158.0,44.135.0"}
P.entries["quest:92910"] = {n="Harvesting the Harvesters",s="Une pièce récupérée sur un moissonneur pourrait intéresser quelqu’un qui étudie les golems des moissons. On vous demande de l’apporter à Ozwin Ironsprocket, à la Ferme des Saldean.",h="Une pièce récupérée sur un moissonneur pourrait intéresser quelqu’un qui étudie les golems des moissons.",kw={"golem des moissons","moissonneur","harvesting the harvesters","ozwin ironsprocket","assemblage autocognitif de précision","ferme des saldean","pièce récupérée"},sec={{t="Une pièce récupérée",b="Quelqu’un à la Ferme des Saldean pourrait vouloir examiner la pièce que vous avez récupérée sur un moissonneur. Elle semble presque intacte, et Ozwin Ironsprocket attend de la voir."}},faq={{q="Que dois-je apporter à Ozwin ?",a="Vous apportez à Ozwin Ironsprocket l’Assemblage autocognitif de précision, une pièce récupérée sur un moissonneur.",al={"pièce de moissonneur","quel objet","autocognition assembly"}},{q="Où dois-je apporter la pièce récupérée ?",a="Apportez l’Assemblage autocognitif de précision à Ozwin Ironsprocket, à la Ferme des Saldean.",al={"où est ozwin","ferme des saldean","où l’apporter"}},{q="Pourquoi cette pièce pourrait-elle intéresser quelqu’un ?",a="La pièce récupérée semble presque intacte, et quelqu’un qui s’intéresse aux golems des moissons pourrait vouloir la voir.",al={"pourquoi les moissonneurs","qui veut ceci","intérêt pour les moissonneurs"}}},fp="25,141,15.156.0,24.101.0,35.84.0,32.101.0"}
P.entries["quest:92911"] = {n="Harvesting the Harvesters",s="À la Ferme des Saldean, Ozwin Ironsprocket a besoin de pièces pour un appareil destiné à prendre brièvement le contrôle des systèmes des moissonneurs. Il poursuit l’assemblage pendant que vous rassemblez ce qu’il lui faut.",h="À la Ferme des Saldean, Ozwin Ironsprocket a besoin de pièces pour un appareil destiné à prendre brièvement...",kw={"copper modulators","lunette basique","appareil","golem isosprings","moissonneurs","harvesting the harvesters","ozwin ironsprocket"},sec={{t="Des pièces pour Ozwin",b="Ozwin Ironsprocket, à la Ferme des Saldean, étudie le fonctionnement des moissonneurs. Il pense pouvoir prendre brièvement le contrôle de leurs systèmes. Vous rassemblez les pièces de son appareil pendant qu’il continue de bricoler l’assemblage."},{t="L’appareil achevé",b="Ozwin termine l’appareil et vous demande de l’essayer. Il reste à la ferme, où il commence à se sentir chez lui."}},faq={{q="Qui demande des pièces ?",a="Ozwin Ironsprocket, à la Ferme des Saldean, a besoin de pièces pour un appareil.",al={"qui a besoin de pièces","pièces ozwin"}},{q="Que construit Ozwin ?",a="Ozwin construit un appareil destiné à prendre brièvement le contrôle des systèmes des moissonneurs.",al={"quel appareil","appareil des moissonneurs"}},{q="De quelles pièces Ozwin a-t-il besoin ?",a="Ozwin a besoin de Golem Isosprings, de Copper Modulators et d’une Lunette basique.",al={"liste des pièces","de quoi ozwin a besoin"}},{q="Où travaille Ozwin ?",a="Ozwin Ironsprocket travaille à la Ferme des Saldean.",al={"où est ozwin","emplacement ozwin"}}},fp="25,182,15.218.0,19.117.1,24.62.0,23.80.0,27.67.0,23.48.0"}
P.entries["quest:92914"] = {n="Strange Pylons",s="À Shen’dralas, un pylône de cristal épuisé laisse sa fonction inconnue. Vous êtes chargé d’en chercher d’autres à proximité.",h="À Shen’dralas, un pylône de cristal épuisé laisse sa fonction inconnue.",kw={"cristal","ruines elfiques","gemme","élémentaires de mana","pylône","shen’dralas","pylônes étranges"},sec={{t="Parmi les ruines",b="Un cristal étrange repose sur un piédestal ancien, au milieu des ruines elfiques de Shen’dralas. Il y a quelques instants à peine, des élémentaires de mana émaciés le gardaient. La gemme est fracturée et sa magie presque épuisée, sa fonction reste donc mystérieuse. Vous fouillez les environs à la recherche d’autres pylônes semblables."}},faq={{q="Qu’est-ce que cet étrange pylône ?",a="C’est une gemme fracturée, posée sur un piédestal ancien à Shen’dralas. Sa magie épuisée laisse sa fonction inconnue.",al={"pylône étrange","pylône de cristal","qu’est-ce que ce cristal"}},{q="Pourquoi le cristal bourdonne-t-il ?",a="Un faible bourdonnement de puissance émane de la gemme fracturée, bien que sa magie soit presque épuisée.",al={"bourdonnement du cristal","pourquoi bourdonne-t-il","faible bourdonnement"}},{q="Que gardait le cristal ?",a="Des élémentaires de mana émaciés gardaient le cristal il y a quelques instants à peine.",al={"élémentaires de mana","qu’est-ce qui le gardait","élémentaires près du pylône"}},{q="Où sont les autres pylônes ?",a="Vous êtes chargé de chercher à Shen’dralas d’autres pylônes semblables à celui que vous avez trouvé.",al={"autres pylônes","trouver d’autres pylônes","emplacement des pylônes"}}},fp="14,109,15.269.0,26.116.0,27.92.0,30.63.0,27.76.0"}
P.entries["quest:92947"] = {n="Making Our Move",s="Au Sanctuaire d’Akir, une force de frappe attaque les Al’Aketh et leur grand-prêtresse. Une charge frontale attirera les défenseurs tandis que le gros des troupes approchera par le flanc.",h="Au Sanctuaire d’Akir, une force de frappe attaque les Al’Aketh et leur grand-prêtresse.",kw={"al’aketh","maître-lame al’aketh","gardien al’aketh","implorateur d’esprits al’aketh","grand-prêtresse","hyusaa quickbreeze","making our move","sanctuaire d’akir"},ang={["class:Priest"]="L’assaut vise les dirigeants al’Aketh du Sanctuaire d’Akir, dont la grand-prêtresse hostile et ses implorateurs d’esprits."},sec={{t="Une tenaille coordonnée",b="Au Sanctuaire d’Akir, l’assaut repose sur le timing et la division des forces. Un petit groupe de combattants d’élite charge les portes principales pour donner l’alerte et attirer les défenseurs au-dehors. Pendant ce temps, le commandant mène l’équipe d’assaut principale par le flanc. Cette poussée divise l’attention des défenseurs et ouvre la voie vers les dirigeants du sanctuaire."},{t="Briser les lignes des Al’Aketh",b="Les Al’Aketh défendent le Sanctuaire d’Akir avec des gardiens cuirassés, des implorateurs d’esprits mystiques et des maîtres-lames aguerris. La force de frappe doit percer leurs lignes de front pour atteindre le saint des saints, où la grand-prêtresse dirige ses fidèles. Une fois les défenseurs extérieurs vaincus, vous retrouverez Hyusaa Quickbreeze, le commandant en second de la force, sur les marches du sanctuaire."}},faq={{q="Quel est l’objectif de l’assaut dans Making Our Move ?",a="La force de frappe cherche à pénétrer dans le Sanctuaire d’Akir et à atteindre la grand-prêtresse. Des combattants chargent de front pour attirer les défenseurs tandis que l’équipe principale les prend à revers.",al={"making our move","quête making our move","quête du sanctuaire d’akir"}},{q="Qui est Hyusaa Quickbreeze ?",a="Hyusaa Quickbreeze est le commandant en second de la force de frappe. Après avoir réduit les défenseurs al’Aketh du sanctuaire, vous devez retrouver Quickbreeze près des marches.",al={"qui est hyusaa","hyusaa quickbreeze","où se trouve hyusaa"}},{q="Quelle grand-prêtresse est visée par l’attaque ?",a="La grand-prêtresse commande les Al’Aketh au sein du Sanctuaire d’Akir. La force de frappe prend les lignes ennemies à revers pour l’atteindre et la vaincre.",al={"qui est la grand-prêtresse d’akir","grand-prêtresse al’aketh","grand-prêtresse visée"}},{q="Qu’est-ce que le Sanctuaire d’Akir ?",a="Le Sanctuaire d’Akir est un lieu de culte fortifié occupé par les Al’Aketh. Des gardiens, des implorateurs d’esprits et des maîtres-lames défendent son sanctuaire central, où résident leurs dirigeants.",al={"qu’est-ce que le sanctuaire d’akir","histoire du sanctuaire d’akir","où se trouve le sanctuaire d’akir"}},{q="Quelles forces al’Aketh occupent le sanctuaire ?",a="Les Al’Aketh sont les défenseurs hostiles du Sanctuaire d’Akir. Leurs rangs comptent des gardiens en première ligne, des implorateurs d’esprits qui maîtrisent les sorts et des maîtres-lames agiles qui protègent l’accès à leur grand-prêtresse.",al={"qui sont les al’aketh","défenseurs al’aketh","ennemis al’aketh"}},{q="Pourquoi lancer une diversion frontale pendant l’assaut ?",a="Une poignée de combattants aguerris entre par l’entrée principale du sanctuaire pour attirer les défenseurs et semer le chaos. Cela donne au gros des troupes l’occasion de prendre le complexe à revers et d’avancer vers le sanctuaire intérieur.",al={"pourquoi faire diversion","plan d’attaque du sanctuaire","stratégie d’attaque making our move"}}},fp="15,179,20.338.0,27.359.0,56.171.0,26.156.0,49.132.0,27.174.0,47.195.0,49.203.0"}
P.entries["quest:93"] = {n="Gâteaux au crabe brun",s="À Sombre-Comté, les Gâteaux au crabe brun sont un en-cas apprécié qui ne contient pas de crabe. Le Chef Grual vous envoie chercher des pattes d’araignée pour La Tremblote, affamé et nerveux.",h="À Sombre-Comté, les Gâteaux au crabe brun sont un en-cas apprécié qui ne contient pas de crabe.",kw={"chef grual","sombre-comté","bois de la pénombre","gâteaux au crabe brun","la tremblote","scarlet raven tavern","pattes d’araignée","tisseuse venimeuse"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous voyez comment des infrastructures négligées et des voies d’approvisionnement coupées poussent des villes comme Sombre-Comté à se nourrir de vermine géante.",["profession:Cooking"]="En tant que cuisinier aux confins de la civilisation, vous découvrez que même des prédateurs terrifiants, comme les araignées géantes venimeuses, peuvent devenir une spécialité régionale."},sec={{t="Un mets douteux",b="Le Chef Grual cuisine à la Scarlet Raven Tavern, à Sombre-Comté. L’isolement, la magie noire et les voies d’approvisionnement coupées ont privé le Bois de la Pénombre de nourriture, poussant les habitants à changer leurs habitudes alimentaires. Selon Grual, les gâteaux tirent leur saveur acidulée des pattes gluantes des araignées géantes locales, et non des fruits de mer venus de rivages lointains."},{t="À la chasse aux toiles venimeuses",b="Le Chef Grual vous envoie vers le nord, dans les contreforts et le long des rives où les tisseuses venimeuses tissent leurs pièges. Les morts-vivants et les bêtes sauvages rendent la forêt lugubre dangereuse, mais la viande d’araignée fraîche est l’une des rares sources de protéines disponibles dans ces bois ravagés. Grual fait frire les pattes assaisonnées dans une poêle brûlante jusqu’à ce qu’elles soient croustillantes."},{t="Un réconfort pour une âme maudite",b="La Tremblote a trouvé refuge dans le village abandonné de la Colline-aux-Corbeaux, dans l’ouest du Bois de la Pénombre. La culpabilité et une terreur tremblante le hantent depuis qu’il a déchaîné par inadvertance des horreurs sur la région. Ce vagabond agité ne pense presque qu’à son estomac affamé. Une fournée chaude des savoureux gâteaux d’araignée du Chef Grual lui offre un rare réconfort dans son exil."}},faq={{q="Les Gâteaux au crabe brun contiennent-ils vraiment du crabe ?",a="Non. Le Chef Grual reconnaît sans détour que les Gâteaux au crabe brun sont entièrement faits de pattes d’araignée gluantes. Sombre-Comté n’a accès ni à la mer ni à du crabe frais, alors il utilise des araignées géantes locales pour leur texture et leur saveur piquante et acidulée.",al={"vrai crabe","secret des gâteaux au crabe","composition des gâteaux au crabe"}},{q="Où le Chef Grual trouve-t-il les pattes d’araignée ?",a="Grual compte sur les aventuriers pour récolter des pattes gluantes sur les tisseuses venimeuses agressives. Elles nichent surtout dans le nord du Bois de la Pénombre, entre les contreforts forestiers et la rivière.",al={"où trouver des pattes d’araignée","emplacement des araignées au bois de la pénombre","emplacement des tisseuses venimeuses"}},{q="Pour qui prépare-t-on ces gâteaux au crabe ?",a="Le Chef Grual prépare cette fournée pour La Tremblote, mais il sert aussi ces gâteaux aux clients de Sombre-Comté. La Tremblote est un ermite terrifié qui vit dans la ville fantôme de la Colline-aux-Corbeaux, dans l’ouest du Bois de la Pénombre, et qui cherche désespérément à manger.",al={"pour qui sont les gâteaux au crabe","qui mange les gâteaux au crabe","pourquoi faire des gâteaux au crabe"}},{q="Le Chef Grual m’apprendra-t-il à faire des Gâteaux au crabe brun ?",a="Le Chef Grual garde secrète sa recette précise des Gâteaux au crabe brun et refuse de révéler son mélange d’épices signature. Il offre tout de même aux aventuriers serviables une autre recette de son répertoire.",al={"apprendre la recette des gâteaux au crabe","recette des gâteaux au crabe en cuisine"}},{q="Pourquoi Sombre-Comté compte-t-elle sur les araignées pour se nourrir ?",a="Les morts-vivants, les worgens Nightbane et des créatures hostiles assiègent les routes du Bois de la Pénombre, perturbant gravement le commerce et l’agriculture. Le bétail frais et les marchandises importées se faisant rares, les habitants de Sombre-Comté utilisent la faune qu’ils peuvent capturer.",al={"pourquoi manger des araignées à sombre-comté","pénuries alimentaires au bois de la pénombre"}},{q="La Tremblote sait-il que les gâteaux sont faits d’araignées ?",a="La Tremblote raffole des célèbres gâteaux au crabe du Chef Grual et se soucie peu de leurs ingrédients. Paralysé par la peur et affamé dans les bois, il est ravi de retrouver un plat familier de Sombre-Comté, quelle que soit son origine répugnante.",al={"la tremblote sait-il pour les araignées","réaction de la tremblote à la viande d’araignée"}}},fx={e54432be={q="À quoi sert la Patte d'araignée gluante ?",a="Malgré le nom agréable sur le menu de la taverne, les Pattes d'araignée gluantes sont la chair principale à l'intérieur des célèbres Gâteaux au crabe brun du Chef Grual. Grual assaisonne les membres grouillants avec son mélange secret d'épices et les fait saisir dans une poêle, comptant sur leurs jus naturels pour donner aux gâteaux savoureux leur saveur distinctive et piquante.",al={"utilisation de la patte d'araignée gluante","pourquoi des pattes d'araignée gluantes","pattes d'araignée et gâteaux au crabe"}}},fp="16,156,23.300.0,22.309.0,25.320.1,43.216.0,42.166.0,40.196.0,54.184.0,44.236.0,48.213.0"}
P.entries["quest:930"] = {n="Le fruit luminescent",s="Un fruit étrange luit parmi les arbres de Teldrassil, et sa croissance inquiète ceux qui le trouvent. Vous le portez à Denalan, au Lac Al'Ameth, pour que l'herboriste étudie cette plante inconnue.",h="Un fruit étrange luit parmi les arbres de Teldrassil, et sa croissance inquiète ceux qui le trouvent.",kw={"bourbiers","denalan","fruit luminescent","herboristerie","lac al'ameth","strange fruited plant","teldrassil","timberlings"},ang={["class:Druid"]="En tant que druide chargé de préserver l'équilibre de la nature, vous savez que des plantes étrangères et instables qui poussent dans les branches sacrées de Teldrassil sont préoccupantes.",["profession:Herbalism"]="En tant qu'herboriste, vous pouvez voir comment des graines étrangères traversent les continents et changent au contact d'un sol enchanté.",["race:NightElf"]="En tant qu'elfe de la nuit, vous apprenez de Denalan que le jeune sol de votre nouveau foyer, Teldrassil, peut subir les effets imprévisibles de fléaux étrangers."},sec={{t="Une récolte contre nature",b="Dans les branches brumeuses de Teldrassil, vous pouvez trouver des plantes portant de gros fruits ronds qui brillent de leur propre lumière. L'équilibre de l'Arbre-monde est délicat, et la faune se comporte étrangement ces derniers temps. Ces plantes inhabituelles appellent donc à la prudence. Vous cueillez les fruits luminescents pour les apporter à quelqu'un qui connaît la flore sauvage."},{t="L'enquête de Denalan",b="Au Lac Al'Ameth, Denalan accueille le fruit luminescent avec fascination et inquiétude. Le jardinier et herboriste pense que ses graines viennent peut-être de contrées lointaines, par-delà la mer, voire des Royaumes de l'est. Il s'inquiète toutefois davantage de la réaction de cette graine étrangère au contact du sol de Teldrassil. Quand Denalan plante les graines dans une terre préparée, des bourbiers hostiles en surgissent."}},faq={{q="Où trouver la plante aux fruits étranges ?",a="La Strange Fruited Plant pousse à l'état sauvage dans la forêt de Teldrassil, dans les sous-bois, loin des grandes habitations. La cueillir permet d'obtenir le Fruit luminescent.",al={"où trouver la plante","emplacement de la plante aux fruits étranges","comment commencer le fruit luminescent"}},{q="Qui est Denalan ?",a="Denalan est un herboriste et botaniste elfe de la nuit qui vit sur les rives du Lac Al'Ameth. Il prend soin du sol, étudie les plantes locales et observe les étranges perturbations qui affectent Teldrassil.",al={"où se trouve denalan","pnj denalan","à qui remettre le fruit luminescent"}},{q="Pourquoi le fruit luit-il ?",a="Personne ne sait pourquoi le fruit luit. Denalan le trouve inhabituel et prévoit de l'étudier.",al={"pourquoi le fruit luit","qu'est-ce qui ne va pas avec le fruit"}},{q="Que se passe-t-il quand vous remettez le fruit à Denalan ?",a="Vous apportez le fruit luminescent à Denalan, au Lac Al'Ameth, pour qu'il l'examine. Vous découvrirez ses conclusions et le résultat de votre livraison à votre retour.",al={"qu'est-ce qui apparaît après la quête","embuscade de bourbiers"}},{q="D'où Denalan pense-t-il que cette plante vient ?",a="Denalan soupçonne que les graines de cette plante viennent de très loin, par-delà la Grande mer, et ont été transportées jusqu'en Kalimdor depuis le lointain continent oriental d'Azeroth.",al={"origine des graines","origine du fruit"}},{q="Cette quête est-elle liée à d'autres problèmes écologiques sur Teldrassil ?",a="Oui. Cette plante fait partie de l'étude plus vaste que mène Denalan pour comprendre pourquoi les branches de Teldrassil et les créatures des bois, comme les Timberlings, sont devenues plus agitées et anormales.",al={"corruption de teldrassil","problèmes au lac al'ameth"}}},fx={a8a1e1a2={q="Pourquoi apporter le fruit luminescent à Denalan ?",a="La Plante aux fruits étranges est une flore sans conscience, mais sa luminescence étrange et son apparence bizarre se distinguent immédiatement de la flore naturelle de Teldrassil. Reconnaissant qu'une telle anomalie contre-nature justifie une enquête, vous prenez l'initiative de livrer un spécimen à Denalan au Lac Al'Ameth, sachant que le botaniste étudie activement les étranges perturbations écologiques de l'île.",al={"pourquoi le fruit de denalan","mobile de la plante aux fruits étranges","pourquoi ramasser le fruit luminescent"}}},fp="17,185,20.306.0,23.373.1,41.158.0,15.190.0,24.85.0,48.147.1,46.137.0,67.161.0"}
P.entries["quest:93016"] = {n="A Brief History Lesson",s="On vous envoie à Shen’dralas pour parler des cristaux que vous avez réparés. Leur lueur inquiète, mais une explication vous attend.",h="On vous envoie à Shen’dralas pour parler des cristaux que vous avez réparés.",kw={"un bref cours d’histoire","lueur des cristaux","cristaux","ciel saisissant","mordent evenshade","shen'dralar","shen’dralas","temple"},sec={{t="Questions à Shen’dralas",b="Les cristaux que vous avez réparés suscitent des questions, et l’on vous envoie auprès de Mordent Evenshade, à Shen’dralas, pour obtenir des réponses. Le ciel a pris un aspect saisissant, ce qui ajoute au malaise suscité par les demandes précédentes."},{t="Une visite en projet",b="Mordent dit que son silence venait de son enthousiasme à voir les cristaux briller de nouveau. Il espère visiter le temple de Shen’dralas, même s’il n’a pas le courage de parler aux Shen'dralar qui s’y trouvent."}},faq={{q="Qui doit expliquer les cristaux ?",a="Mordent Evenshade, à Shen’dralas, doit expliquer les cristaux que vous avez réparés.",al={"qui explique les cristaux","infos sur mordent","explication des cristaux"}},{q="Pourquoi les demandes précédentes semblaient-elles suspectes ?",a="Les demandes manquaient de contexte, et le ciel avait pris un aspect saisissant.",al={"pourquoi suspect","qu’est-ce qui était étrange","pourquoi sans contexte"}},{q="Pourquoi Mordent a-t-il omis l’explication ?",a="Mordent dit qu’il était impatient de voir à nouveau briller les cristaux et qu’il a omis d’expliquer la situation dès le départ.",al={"pourquoi pas d’explication","raison de mordent","pourquoi a-t-il attendu"}},{q="Mordent prévoit-il de visiter le temple ?",a="Mordent se réjouit à l’idée de visiter à nouveau le temple de Shen’dralas, même s’il dit qu’il lui faudra peut-être du temps avant de pouvoir parler aux Shen'dralar qui s’y trouvent.",al={"visite du temple","mordent s’y rend-il","temple de shen’dralas"}}},fp="22,132,24.211.0,15.191.1,40.79.0,45.84.0,42.117.0,38.140.0"}
P.entries["quest:93036"] = {n="Infiltrating the Cult",s="À Shen’dar, Sania Silverstream rallie des fidèles tandis que la paix précaire s’effrite. Le village demande à une nouvelle venue de l’approcher et de découvrir ce que l’Ordre des Al’Aketh réserve à la communauté.",h="À Shen’dar, Sania Silverstream rallie des fidèles tandis que la paix précaire s’effrite.",kw={"al’aketh","al'akir","alaketh","alakir","infiltrating the cult","sania silverstream","shen’dar","seigneur du vent"},ang={["class:Priest"]="En tant que prêtre, vous reconnaîtrez peut-être que Sania Silverstream a voué sa foi à un Seigneur élémentaire, et non à la Lumière sacrée ou à Elune. Ses manières religieuses avenantes dissimulent le culte des élémentaires.",["class:Rogue"]="En tant que voleur, vous pouvez mettre vos talents d’espionnage, de tromperie et de reconnaissance au service de votre approche de la secte par l’intermédiaire de sa recruteuse sans méfiance."},sec={{t="Une paix précaire",b="À Shen’dar, une trêve précaire avec l’Ordre des Al’Aketh commence à se défaire. Depuis longtemps, les autorités locales tolèrent Sania Silverstream, une missionnaire autoproclamée qui vit parmi elles. L’Ordre se présente comme un mouvement religieux pacifique et envoie de doux recruteurs attirer des fidèles sans méfiance. Les dirigeants du village laissent Sania recruter pour éviter que la secte ne provoque un conflit ouvert. À présent, cette paix fragile s’effrite."},{t="Sous le voile de la missionnaire",b="Sania Silverstream est une prêtresse novice de l’Ordre des Al’Aketh, dévouée à Al'Akir le seigneur du Vent, souverain des élémentaires d’air. Elle invite les nouveaux venus à découvrir son souverain et leur promet une place à sa table. Les habitants de Shen’dar la connaissent trop bien pour l’approcher sans risque. Les dirigeants du village font donc appel à une nouvelle venue pour gagner sa confiance et découvrir ce que la secte prépare pour leur foyer."}},faq={{q="Qui est Sania Silverstream ?",a="Sania Silverstream est une prêtresse novice de l’Ordre des Al’Aketh qui vit à Shen’dar et se présente comme une missionnaire. Elle recrute en douceur des habitants pour adorer Al'Akir le seigneur du Vent.",al={"qui est sania","histoire de sania silverstream","prêtresse sania"}},{q="Qu’est-ce que l’Ordre des Al’Aketh ?",a="L’Ordre des Al’Aketh est une secte qui se présente comme un mouvement religieux classique. Ses membres vénèrent Al'Akir le seigneur du Vent, souverain des élémentaires d’air, et recrutent discrètement des convertis dans les communautés voisines pour étendre leur influence.",al={"qui sont les alaketh","qu’est-ce qu’alaketh","ordre des alaketh"}},{q="Pourquoi Shen’dar tolère-t-il Sania Silverstream ?",a="Les dirigeants de Shen’dar tolèrent le travail missionnaire de Sania Silverstream afin de préserver une paix fragile et d’éviter un conflit ouvert avec la secte. Cette trêve s’effrite, alors ils ont décidé d’enquêter discrètement sur elle.",al={"pourquoi laisser sania rester","pourquoi ne pas tuer sania","pourquoi sania est-elle au village"}},{q="Qui est Al'Akir le seigneur du Vent ?",a="Al'Akir le seigneur du Vent est le Seigneur élémentaire des cieux, des tempêtes et de l’air. L’Ordre des Al’Aketh le vénère comme son souverain et promet une place à sa table à ceux qui se repentent et le rejoignent.",al={"qui est le seigneur du vent","histoire d’alakir","qui est alakir"}},{q="Pourquoi vous demande-t-on d’infiltrer la secte plutôt que d’envoyer un habitant ?",a="Comme vous venez d’arriver à Shen’dar, Sania et les Al’Aketh ne vous connaissent pas. Ils risquent moins de soupçonner que vous travaillez pour les dirigeants du village, ce qui vous permet de l’approcher comme une recrue intéressée sans éveiller les soupçons.",al={"pourquoi moi","pourquoi envoyer un aventurier","raison de la quête d’infiltration"}},{q="Que préparent les Al’Aketh pour Shen’dar ?",a="Les dirigeants de Shen’dar soupçonnent que le recrutement des Al’Aketh dissimule des projets plus vastes et agressifs pour la communauté. Ils veulent les découvrir avant que la paix fragile ne s’effondre.",al={"projet de la secte pour le village","que veulent les alaketh","intentions des alaketh"}}},fp="21,204,18.424.0,29.388.1,26.197.0,34.244.0,54.210.0,28.192.0,60.218.0,52.181.0"}
P.entries["quest:93065"] = {n="Prepare for Battle",s="Les Peacekeepers se rassemblent en ville pour marcher vers les terres alentour. Vous êtes appelé à effectuer vos derniers préparatifs et à retrouver Valennia Stormfist dans les Plaines Aérelles avant le départ de la compagnie.",h="Les Peacekeepers se rassemblent en ville pour marcher vers les terres alentour.",kw={"route orientale","plaines aérelles","mobilisation","peacekeepers","prepare for battle","valennia stormfist"},ang={["class:Warrior"]="En tant que combattant de première ligne, vous savez que ce rassemblement précède le combat. Vérifiez votre équipement et prenez place dans les rangs auprès de vos alliés tandis que la compagnie se prépare à partir."},sec={{t="Un appel au rassemblement",b="Les Peacekeepers, les forces de défense locales, ont appelé leurs troupes et les volontaires aux armes tandis que les tensions montent. Sécurisez votre équipement, préparez vos armes et rejoignez la compagnie qui se rassemble pour marcher en formation vers les terres alentour."},{t="Le rassemblement dans les Plaines Aérelles",b="La compagnie se rassemble le long de la route orientale qui part vers le nord en quittant la ville, en direction des Plaines Aérelles. Là, l'organisatrice Valennia Stormfist inspecte les combattants et fait l'appel. Puis la compagnie marche au-devant du danger."}},faq={{q="Qui est Valennia Stormfist ?",a="Valennia Stormfist organise le rassemblement des Peacekeepers dans les Plaines Aérelles. Elle supervise les derniers préparatifs le long de la route orientale qui part vers le nord en quittant la ville, avant le départ des forces.",al={"qui est valennia stormfist","valennia stormfist","stormfist"}},{q="Qui sont les Peacekeepers ?",a="Les Peacekeepers sont une force de défense locale organisée. Ils se rassemblent pour faire face à une menace imminente aux abords de la ville.",al={"qui sont les peacekeepers","peacekeepers","force des peacekeepers"}},{q="Où se trouvent les Plaines Aérelles ?",a="Les Plaines Aérelles sont le lieu de rassemblement des forces de défense locales. Leur zone de regroupement se trouve le long de la route qui part vers le nord en quittant la ville.",al={"où se trouvent les plaines aérelles","emplacement des plaines aérelles","plaines aérelles"}},{q="À quoi se préparent les Peacekeepers ?",a="Les Peacekeepers se préparent à marcher en force hors de la ville. Ils appellent les alliés capables à vérifier leur équipement et à se rassembler aux abords de la ville avant le départ de la compagnie.",al={"à quoi se préparent-ils","pourquoi se préparer au combat","quel est le combat"}},{q="Où se trouve le point de rendez-vous pour la marche ?",a="La compagnie se retrouve le long de la route orientale qui part vers le nord en quittant la ville. Ses membres peuvent s'y mettre en formation avant de marcher vers le champ de bataille.",al={"où se trouve le point de rassemblement","où retrouver valennia","point de rendez-vous"}},{q="Que se passe-t-il une fois que tout le monde est rassemblé ?",a="Valennia Stormfist inspecte les rangs rassemblés et fait l'appel. Puis les forces marchent au-devant du danger.",al={"comment se termine le rassemblement","que dit valennia","nous sommes aussi prêts que possible"}}},fp="18,208,16.240.0,35.213.0,26.187.0,25.115.0,33.128.0,40.160.0,44.142.0,40.102.0"}
P.entries["quest:93089"] = {n="What Comes Next",s="Sur l’Île de Zéphras, l’Ordre suprême sollicite votre bénédiction avant de partir avec ses alliés du Kirin Tor. Son expédition dépend de la découverte d’une réponse arcanique à l’instabilité de l’île.",h="Sur l’Île de Zéphras, l’Ordre suprême sollicite votre bénédiction avant de partir avec ses alliés du Kirin...",kw={"ansirem","dalaran","elaadrin evengale","ordre suprême","kirin tor","coupe-ciel","what comes next","île de zéphras"},sec={{t="Le départ",b="High Elder Shadowsong a béni l’expédition, et les préparatifs sont terminés. Ansirem s’est employé à mettre en place le transport par coupe-ciel entre Dalaran et l’Île de Zéphras. L’avant-garde s’apprête à partir. Parlez à Elaadrin Evengale quand vous serez prêt à quitter l’île."}},faq={{q="À qui parler avant de quitter l’Île de Zéphras ?",a="Parlez à Elaadrin Evengale quand vous serez prêt à quitter l’Île de Zéphras.",al={"à qui parler","quitter l’île de zéphras","départ d’elaadrin"}},{q="Où va l’Ordre suprême ?",a="L’Ordre suprême prépare une expédition, avec une liaison par coupe-ciel entre Dalaran et l’Île de Zéphras.",al={"où vont-ils","destination de l’ordre suprême","prochaine étape"}},{q="Qui aide l’Ordre suprême ?",a="Le Kirin Tor aide l’Ordre suprême. Ansirem a travaillé à mettre en place le transport par coupe-ciel entre Dalaran et l’Île de Zéphras.",al={"qui sont les alliés","aide du kirin tor","alliés de l’ordre suprême"}},{q="Que cherche l’expédition ?",a="L’expédition espère trouver une solution arcanique pour stabiliser l’Île de Zéphras.",al={"que cherchent-ils","solution arcanique","pourquoi quitter l’île"}},{q="Qu’est-il arrivé au culte ?",a="Elaadrin affirme que le culte a été vaincu et que les préparatifs de l’expédition sont terminés.",al={"situation du culte","le culte est-il vaincu","qu’en est-il du culte"}}},fp="15,179,13.274.0,48.70.0,30.101.0,30.117.0,31.83.0,26.91.0"}
P.entries["quest:93090"] = {n="What Comes Next",s="Sur l’Île de Zéphras, l’expédition se prépare à traverser les cieux jusqu’à Kalimdor. Le culte local est vaincu et le grand aîné Shadowsong lui a accordé sa bénédiction. Des fendeurs célestes transportent désormais les voyageurs entre l’île et Mulgore.",h="Sur l’Île de Zéphras, l’expédition se prépare à traverser les cieux jusqu’à Kalimdor.",kw={"ayessa dawnsinger","cercle terrestre","grand aîné shadowsong","mulgore","muln","fendeur céleste","what comes next","île de zéphras"},ang={["class:Shaman"]="En tant que chaman, vous vous rendez à Mulgore pour rencontrer le Cercle terrestre, une organisation chamanique vénérée qui s’efforce d’apaiser les esprits élémentaires d’Azeroth.",["race:Tauren"]="En tant que tauren, vous vous rendez à Mulgore, la terre ancestrale de votre peuple. Le Cercle terrestre y a établi ses quartiers."},sec={{t="Départ de l’Île de Zéphras",b="Le grand aîné Shadowsong a béni la suite du voyage de l’expédition depuis l’Île de Zéphras, où le culte local a été vaincu et la sécurité rétablie. L’expédition regarde désormais au-delà de l’île et se prépare à traverser les cieux ouverts vers Kalimdor. Ayessa Dawnsinger coordonne le départ final pour ceux qui sont prêts à partir."},{t="Fendeurs célestes vers Mulgore",b="Muln a œuvré pour assurer des trajets réguliers en fendeur céleste entre l’Île de Zéphras et Mulgore. Les voyages d’essai ont réussi, et un groupe d’avant-garde a déjà traversé. Ses membres attendent de l’autre côté pour entrer en contact avec les chamans du Cercle terrestre."}},faq={{q="Qu’est-ce que la quête What Comes Next ?",a="L’expédition se prépare à quitter l’Île de Zéphras après avoir obtenu la bénédiction du grand aîné Shadowsong et vaincu le culte local. Les voyageurs sont prêts à traverser les cieux en fendeur céleste jusqu’à Kalimdor.",al={"que signifie what comes next","quête what comes next","qu’est-ce que cette quête"}},{q="Où l’expédition se rend-elle ?",a="Des fendeurs célestes relient l’Île de Zéphras à Mulgore, une région de mesas herbeuses au centre de Kalimdor. Le Cercle terrestre y a établi ses quartiers, et des membres de l’avant-garde de l’expédition les y attendent déjà.",al={"où allons-nous","destination du fendeur céleste","où va le fendeur céleste"}},{q="Qui est Ayessa Dawnsinger ?",a="Ayessa Dawnsinger coordonne le départ de l’Île de Zéphras. Les préparatifs sont en place, les vols d’essai ont réussi et le grand aîné Shadowsong a béni le départ de l’expédition.",al={"qui est ayessa dawnsinger","ayessa dawnsinger","ayessa"}},{q="Qui est Muln ?",a="Muln a œuvré à la mise en place de trajets réguliers en fendeur céleste entre l’Île de Zéphras et Mulgore. Il a effectué des voyages d’essai pour assurer une traversée sûre des cieux.",al={"qui est muln","muln et le fendeur céleste","muln et zéphras"}},{q="Qu’est-ce que le Cercle terrestre ?",a="Le Cercle terrestre est une organisation de chamans voués à maintenir l’harmonie entre les esprits élémentaires. Ses membres sont les contacts et les hôtes de l’expédition à Mulgore.",al={"qu’est-ce que le cercle terrestre","cercle terrestre mulgore","qui sont les membres du cercle terrestre"}},{q="Pourquoi l’expédition quitte-t-elle l’Île de Zéphras ?",a="Le culte local est vaincu et le grand aîné Shadowsong a béni l’expédition. Ces tâches accomplies, l’expédition peut quitter l’Île de Zéphras et poursuivre son voyage vers le continent.",al={"pourquoi quitter l’île de zéphras","l’île de zéphras est-elle terminée","pourquoi aller à mulgore"}}},fp="15,214,27.332.0,21.231.0,34.191.0,33.185.0,25.184.0,12.149.0,25.166.0,43.176.0"}
P.entries["quest:931"] = {n="Les racines chatoyantes",s="Une plante curieuse scintille parmi les racines et la canopée de Teldrassil. Des voyageurs en apportent une bouture à Denalan, au Lac Al'Ameth, dans l'espoir que le botaniste puisse expliquer son origine.",h="Une plante curieuse scintille parmi les racines et la canopée de Teldrassil.",kw={"botanique","denalan","lac al'ameth","racines chatoyantes","frondes écloses","plante étrange à frondes","marais des chagrins","teldrassil"},ang={["class:Druid"]="En tant que druide, vous pouvez observer les effets de la flore étrangère sur la jeune canopée de Teldrassil.",["profession:Herbalism"]="Les herboristes et les passionnés de plantes peuvent se demander comment une plante du Marais des Chagrins prospère si loin de ses marécages d'origine.",["race:NightElf"]="En tant qu'elfe de la nuit qui prend soin de votre nouveau foyer, vous pouvez voir comment les expériences de Denalan révèlent la résilience du sol de Teldrassil."},sec={{t="Une étrange lueur",b="Une étrange plante capte la lumière dans les branches de Teldrassil. Ses frondes se tordent en scintillant par pulsations, d'une façon inhabituelle pour la végétation de l'île. Cette lueur attire le regard parmi les plantes de la jeune forêt."},{t="La découverte de Denalan",b="Au Lac Al'Ameth, Denalan reconnaît la bouture comme une plante venue d'au-delà du nord de Kalimdor. Il en a vu une pour la dernière fois il y a des décennies, alors qu'il voyageait dans le Marais des Chagrins, dans les Royaumes de l'est. Il se demande comment sa graine a traversé l'océan et poussé si grand sur L'Arbre-monde. Denalan commence à cultiver l'échantillon et à l'étudier."}},faq={{q="D'où vient cette étrange plante ?",a="Denalan affirme que la plante vient du Marais des Chagrins, dans les Royaumes de l'est. Il a vu un spécimen vivant dans ces marais pour la dernière fois il y a des décennies.",al={"origine de la fronde","d'où vient la fronde","plante des marais"}},{q="Qui est Denalan ?",a="Denalan est un botaniste et herboriste elfe de la nuit, près du Lac Al'Ameth, sur Teldrassil. Il étudie et entretient la flore de l'île, et expérimente avec des graines étrangères et des jardinières.",al={"histoire de denalan","qui est denalan"}},{q="Pourquoi cette plante pousse-t-elle sur Teldrassil ?",a="Personne ne sait comment la plante est arrivée sur Teldrassil. Denalan se demande comment une graine a traversé La Grande mer depuis les Royaumes de l'est, puis a pris racine et grandi dans le sol de Teldrassil.",al={"comment est-elle arrivée à teldrassil","pourquoi la fronde est ici"}},{q="Que se passe-t-il après avoir donné la fronde à Denalan ?",a="Denalan place le spécimen dans sa jardinière, au Lac Al'Ameth, et commence à l'étudier. Plusieurs frondes poussent et fleurissent rapidement, lui offrant davantage de matière à étudier.",al={"quête suivante","expérience de denalan","frondes écloses"}},{q="Cette plante provoque-t-elle la corruption de Teldrassil ?",a="Non. La plante semble être une variété exotique inhabituelle qui s'est retrouvée au mauvais endroit, plutôt qu'une source de corruption.",al={"la fronde est-elle corrompue","plante corrompue"}}},fx={add2b0dd={q="Pourquoi apporter une fronde de la Plante à la fronde étrange à Denalan ?",a="La plante elle-même n'a aucun motif conscient ; c'est simplement un spécimen inhabituel et pulsant qui pousse à l'état sauvage dans les branches de Teldrassil. Vous reconnaissez son aura étrange et scintillante comme quelque chose d'exotique et potentiellement contre-nature pour le grand arbre, ce qui vous pousse à récolter une bouture pour Denalan, le botaniste résident étudiant la flore rare au Lac Al'Ameth.",al={"mobile de la plante à la fronde étrange","pourquoi apporter la fronde à denalan","pourquoi prendre la fronde"}}},fp="20,168,14.188.0,19.318.1,50.139.0,15.180.0,40.174.0,47.151.1,47.107.0"}
P.entries["quest:93159"] = {n="The Strange Hermit",s="The Strange Hermit est une quête d'introduction dans la Forêt de Trombenoire centrée sur un reclus timide et encapuchonné vivant à l'écart de la civilisation. En quête de conversation après un long isolement, l'Hermit partage des aperçus de sa vie simple et artisanale ainsi que son lien avec les esprits chanteurs de la forêt locale.",h="The Strange Hermit est une quête d'introduction dans la Forêt de Trombenoire centrée sur un reclus timide et...",kw={"esprits de la forêt","artisanal","hermit","silhouette encapuchonnée","solitaire","forêt de trombenoire","étrange hermit"},ang={["class:Druid"]="Les druides en harmonie avec la nature peuvent apprécier l'interaction de l'Hermit avec les esprits de la forêt locaux, bien que son incapacité à converser véritablement avec eux contraste avec la communion plus profonde d'un druide.",["profession:Engineering"]="Les bricoleurs et les artisans peuvent comprendre le réconfort que trouve l'Hermit à fabriquer des objets de ses mains pour aménager sa demeure solitaire."},sec={{t="Un reclus dans les bois",b="Sous la canopée de la Forêt de Trombenoire, vous découvrez un reclus encapuchonné, loin des villes et des routes commerciales. On le connaît simplement sous le nom de Strange Hermit. Des années sans compagnie ordinaire l’ont rendu nerveux et gauche en conversation. Même une salutation lui semble étrange."},{t="Esprits et choses simples",b="Bien que solitaire, l'Hermit insiste sur le fait qu'il a toute la compagnie et toutes les provisions dont il a besoin. Il confie avoir vécu ailleurs avant de s'installer ici, choisissant de mener une vie entourée de bibelots artisanaux et des esprits de la forêt locaux. Si les esprits sauvages lui chantent fréquemment des refrains, il admet que des chœurs mélodieux ne peuvent pas remplacer entièrement une conversation avec quelqu'un capable de lui répondre."}},faq={{q="Qui est Strange Hermit ?",a="Strange Hermit est un reclus excentrique et encapuchonné de la Forêt de Trombenoire. Peu habitué à la compagnie, il entretient ses objets fabriqués à la main et passe du temps avec les esprits des bois locaux plutôt qu’avec d’autres personnes.",al={"étrange hermit","identité de l'hermit","qui est l'hermit"}},{q="Où vit l'Hermit ?",a="L'Hermit a établi son foyer au plus profond des arbres de la Forêt de Trombenoire, vivant bien à l'écart des sentiers battus où bien peu de voyageurs s'aventurent.",al={"où est l'hermit","emplacement de la forêt de trombenoire","zone de l'hermit"}},{q="Pourquoi l'Hermit vit-il seul ?",a="Il admet avoir vécu complètement ailleurs avant de se retirer dans la forêt. Bien qu'il reste très vague au sujet de son passé, il a choisi une vie tranquille entouré uniquement d'objets qu'il a construits et des esprits sauvages des bois.",al={"pourquoi l'hermit est seul","isolement de l'hermit","histoire de l'hermit"}},{q="L'Hermit peut-il parler avec les esprits de la forêt ?",a="Il considère les esprits de la forêt locaux comme ses compagnons, bien qu'ils ne tiennent pas de conversation normale. À la place, ils chantent pour lui, ce qu'il trouve agréable même si cela n'offre pas la profondeur d'échange d'un semblable mortel.",al={"l'hermit parlant aux esprits","esprits de la forêt de trombenoire","amis de l'hermit"}},{q="Qu'a construit l'Hermit dans la forêt ?",a="L'Hermit mentionne posséder plusieurs objets et structures artisanaux qui l'occupent, trouvant réconfort et satisfaction dans de simples biens faits main.",al={"artisanat de l'hermit","qu'a construit l'hermit"}},{q="Que se passe-t-il pendant la quête « The Strange Hermit » ?",a="La quête consiste à s'approcher de l'Hermit nerveux dans la Forêt de Trombenoire pour engager une conversation amicale et écouter le peu qu'il est disposé à partager sur son existence de reclus.",al={"quête the strange hermit","parler à l'hermit"}}},fp="18,192,22.261.0,25.245.0,26.194.0,27.117.0,36.180.0,41.148.0,40.140.0,51.115.0"}
P.entries["quest:93160"] = {n="The Forest's Bounty",s="Dans la Forêt de Trombenoire, une cueilleuse a besoin d'aide pour ramasser des glands tombés au sol. Des prédateurs semblables à des raptors rôdent dans les bois les plus profonds, et les glands peuvent être grillés pour préparer un repas forestier.",h="Dans la Forêt de Trombenoire, une cueilleuse a besoin d'aide pour ramasser des glands tombés au sol.",kw={"glands","cuisine","cueillette","oiseau-raptor","glands de trombenoire","forêt de trombenoire","the forest's bounty"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez faire griller des glands de Trombenoire pour préparer un simple repas forestier."},sec={{t="Une cueillette périlleuse",b="Une cueilleuse prudente a ramassé les glands près des zones sûres de la Forêt de Trombenoire. Des créatures féroces, semblables à des raptors, rôdent parmi les arbres et l'empêchent de rejoindre les bosquets plus sauvages. Il faut donc des voyageurs de passage pour ramasser les glands plus loin dans les bois et veiller à ce que personne ne souffre de la faim."},{t="Faire griller la récolte",b="Les glands de Trombenoire sont nourrissants lorsqu'ils sont préparés avec soin. Crus, ils peuvent être amers ou durs, mais les faire griller au feu transforme cette récolte sauvage en un mets riche. Pour les ramasser, vous devrez braver les bois où rôdent des oiseaux prédateurs."}},faq={{q="Qui vous demande de ramasser les glands ?",a="Une cueilleuse nerveuse près de la Forêt de Trombenoire vous demande de ramasser des glands. Elle a récolté ceux qui se trouvaient à proximité, mais a besoin d'aide pour atteindre les bois où rôde une faune dangereuse.",al={"qui donne la quête des glands","qui veut des glands","donneur de quête les glands de la forêt"}},{q="Où trouve-t-on les glands ?",a="Des glands de Trombenoire sont éparpillés sous la canopée de la Forêt de Trombenoire. Cherchez sur le sol forestier et prenez garde aux prédateurs parmi les arbres.",al={"où trouver les glands de trombenoire","emplacement des glands","glands de la forêt de trombenoire"}},{q="Pourquoi est-il dangereux de ramasser des glands ici ?",a="Des oiseaux prédateurs semblables à des raptors rôdent sur le sol forestier. Sans entraînement au combat, les gens ordinaires risquent leur vie s'ils s'éloignent du camp.",al={"pourquoi la forêt de trombenoire est dangereuse","que sont les oiseaux-raptors","pourquoi le ramassage des glands est dangereux"}},{q="À quoi servent les glands ?",a="Ces glands constituent une nourriture sauvage et nourrissante. Faites-les griller au feu pour obtenir un en-cas chaud à partager avec ceux qui osent affronter les bêtes de la forêt.",al={"à quoi servent les glands de trombenoire","glands grillés","pourquoi ramasser des glands"}},{q="Que sont les créatures semblables à des oiseaux-raptors mentionnées dans la forêt ?",a="La cueilleuse parle de dangereuses « choses ressemblant à des oiseaux-raptors » qui chassent dans la Forêt de Trombenoire. Ces prédateurs aviaires ou reptiliens sont assez grands et féroces pour s'en prendre à un voyageur imprudent.",al={"que sont les choses ressemblant à des oiseaux-raptors","oiseaux-raptors à trombenoire","raptors de la forêt"}},{q="Comment préparer les glands pour les manger ?",a="Crus, les glands de Trombenoire peuvent être durs ou amers. Faites-les griller à la chaleur pour en faire un mets délicieux.",al={"les glands de trombenoire sont-ils comestibles crus","comment cuire les glands de trombenoire","manger des glands forestiers"}}},fp="19,164,23.292.0,20.236.0,34.162.0,27.132.0,40.133.0,29.128.0,59.181.0,39.99.0"}
P.entries["quest:93165"] = {n="Mercy Falls on Deaf Ears",s="Dans les étendues sauvages autour de la Forêt de Trombenoire, les survivants Nightclaw cherchent à se venger des Al’Aketh. Après une terrible tragédie causée par les sectateurs, ils offrent des pièces et la promesse d’un accès à leurs traditions secrètes contre des trophées prélevés sur leurs ennemis tués. Leur querelle s’étend désormais à toute la Forêt de Trombenoire et aux territoires environnants.",h="Dans les étendues sauvages autour de la Forêt de Trombenoire, les survivants Nightclaw cherchent à se venger...",kw={"al’aketh","vendetta sanglante","sectateurs","oreilles","plaines aérelles","mercy falls on deaf ears","nightclaw","forêt de trombenoire","sanctuaire d’akir"},sec={{t="Œil pour œil, dent pour dent",b="L’enclave des Nightclaw et les sectateurs Al’Aketh sont engagés dans une querelle acharnée. Une terrible tragédie a privé les survivants de tout espoir de paix. Ils veulent venger leurs proches tombés et font appel aux aventuriers et aux mercenaires de passage. L’enclave offre des pièces et promet une confiance accrue à ceux qui tuent des sectateurs et rapportent leurs oreilles comme preuve."},{t="La menace des Al’Aketh",b="Les Al’Aketh étendent leur influence dans les Plaines Aérelles, la Forêt de Trombenoire et l’antique Sanctuaire d’Akir. Leurs pratiques sombres et leur fanatisme leur ont valu la haine des habitants locaux. Frapper les camps de la secte dans ces contrées peut affaiblir son emprise et gagner les faveurs des discrets Nightclaw. L’enclave garde ses mystères jusqu’à ce qu’un étranger prouve sa loyauté."}},faq={{q="Qu’est-ce que Mercy Falls on Deaf Ears ?",a="L’enclave des Nightclaw offre des pièces et une confiance accrue à ceux qui tuent des sectateurs Al’Aketh et rapportent leurs oreilles. Les survivants cherchent à se venger après une terrible tragédie.",al={"quête mercy falls on deaf ears","qu’est-ce que cette quête","aperçu de la quête"}},{q="Qui sont les Al’Aketh ?",a="Les Al’Aketh sont une secte de sectateurs maudits dont les actes ont causé ruine et tragédie dans les communautés voisines. Ils opèrent dans les Plaines Aérelles, la Forêt de Trombenoire et le Sanctuaire d’Akir, déclenchant des vendettas avec les habitants de ces terres.",al={"qui sont les al’aketh","traditions des sectateurs al’aketh"}},{q="Où trouver les sectateurs Al’Aketh ?",a="On trouve des sectateurs Al’Aketh dans la Forêt de Trombenoire, autour du Sanctuaire d’Akir et dans toute la région des Plaines Aérelles. Les Nightclaw demandent une preuve à ceux qui les tuent.",al={"où trouver les sectateurs al’aketh","lieux des al’aketh","où trouver les sectateurs"}},{q="Pourquoi le donneur de quête collecte-t-il les oreilles des sectateurs ?",a="Les Nightclaw exigent les oreilles des sectateurs pour prouver que leurs ennemis sont morts. Après une terrible tragédie causée par les Al’Aketh, l’enclave cherche à se venger et exige une preuve pour chaque prime versée.",al={"pourquoi les oreilles","pourquoi veulent-ils les oreilles des sectateurs","oreilles comme preuve"}},{q="Qui sont les Nightclaw ?",a="Les Nightclaw sont une enclave secrète qui a subi de lourdes pertes face aux Al’Aketh. Ils gardent leurs traditions secrètes, mais promettent aux étrangers de leur révéler leurs mystères s’ils prouvent leur loyauté en combattant les sectateurs.",al={"faction des nightclaw","qui sont les nightclaw","traditions secrètes des nightclaw"}},{q="Quelle tragédie les Al’Aketh ont-ils causée ?",a="Les Al’Aketh ont causé une grande tragédie à l’enclave des Nightclaw, déclenchant une vendetta sans merci. La prime ne donne aucun détail sur l’incident ni sur ses victimes, mais les survivants réclament une vengeance totale.",al={"qu’ont fait les al’aketh","qu’est-il arrivé à l’enclave","tragédie des al’aketh"}},{q="Quels sont les secrets des Nightclaw ?",a="Les Nightclaw gardent leurs secrets au sein de l’enclave et ne les révèlent pas immédiatement aux étrangers. Ils promettent de donner accès à ces connaissances cachées à ceux qui continuent de les aider à combattre les Al’Aketh et prouvent qu’ils sont de véritables alliés.",al={"secrets des nightclaw","quels secrets les nightclaw possèdent-ils","que révèlent les nightclaw"}}},fp="24,329,15.361.0,19.392.0,33.168.0,21.257.0,37.169.0,46.180.0,22.231.0,36.206.0,33.234.0"}
P.entries["quest:93172"] = {n="Free the Hollows",s="Dans la Forêt de Trombenoire, le chant triste des wind hollows résonne parmi les ruines anciennes. Une tragédie d’autrefois lie ces esprits fantomatiques, et des voyageurs cherchent à leur rendre la paix.",h="Dans la Forêt de Trombenoire, le chant triste des wind hollows résonne parmi les ruines anciennes.",kw={"free the hollows","fantômes","hollows","ruines","trombenoire","forêt de trombenoire","wind hollows"},ang={["class:Druid"]="En tant que druide, vous savez que les esprits agités de la Forêt de Trombenoire troublent la nature et réclament équilibre et délivrance.",["class:Priest"]="En tant que prêtre, vous voyez les wind hollows comme des esprits tristes, prisonniers d’une tragédie. Les détruire est considéré comme un acte de compassion qui libère les âmes liées par l’angoisse.",["race:NightElf"]="En tant qu’elfe de l’île, vous savez que la Forêt de Trombenoire est depuis longtemps réputée hantée, ses esprits étant liés à d’anciennes ruines."},sec={{t="Les hantises de Trombenoire",b="Les elfes de toute l’île craignent depuis longtemps la Forêt de Trombenoire, qu’ils considèrent comme un bosquet hanté. Dans ses bois du nord-est, de vieilles ruines de pierre gisent sous la végétation envahissante. Des wind hollows fantomatiques y dérivent sans repos, mais ne montrent aucune malveillance. Leur tristesse évoque un désastre qui frappa les ruines il y a bien longtemps."},{t="Le chant des lamentations",b="Par les nuits calmes, les voyageurs près des ruines entendent un chant étrange porté par la brise. Aucun chant mortel ne lui ressemble, et sa profonde mélancolie trouble ceux qui l’entendent. Les voyageurs compatissants pensent que les ombres souffrent dans leur lamentation éternelle. Ils cherchent les wind hollows pour briser leurs liens spectraux et leur accorder la paix."}},faq={{q="Que sont les wind hollows ?",a="Les wind hollows sont des esprits tristes et fantomatiques qui hantent de vieilles ruines elfes dans le nord-est de la Forêt de Trombenoire. Liés par une tragédie ancienne, ils chantent leur tristesse dans les arbres, la nuit.",al={"que sont les wind hollows","histoire des hollows","que sont les hollows"}},{q="Pourquoi faut-il libérer les wind hollows ?",a="On pense que les esprits restent liés par une terrible catastrophe et prisonniers de leur chagrin. Les détruire est considéré comme un acte de compassion qui libère leurs formes persistantes des ruines.",al={"pourquoi libérer les hollows","pourquoi tuer les hollows","but de libérer les hollows"}},{q="Où trouve-t-on les esprits ?",a="Les esprits se rassemblent parmi les ruines anciennes des bois du nord-est de la Forêt de Trombenoire, une île boisée habitée par des elfes.",al={"où se trouve la forêt de trombenoire","ruines de trombenoire","emplacement des ruines"}},{q="Quel est ce chant étrange que l’on entend dans les bois ?",a="Les wind hollows chantent une mélodie triste qui ne ressemble à aucun air ordinaire. On pense que leur chant vient de leur fin tragique et de leur captivité éternelle parmi les ruines de l’île.",al={"chant des hollows","chant fantomatique","pourquoi les fantômes chantent-ils"}},{q="Qui vous demande de libérer les wind hollows ?",a="Un observateur de l’île qui a pitié des esprits prisonniers vous demande de les libérer, sachant que les elfes du coin craignent les bois hantés.",al={"qui donne free the hollows","donneur de quête free the hollows"}},{q="Que s’est-il passé dans les ruines pour créer les wind hollows ?",a="Les détails exacts se sont perdus avec le temps, mais les habitants savent qu’un terrible événement s’est produit dans les ruines du nord-est et y a lié les esprits à un chagrin éternel.",al={"que s’est-il passé dans les ruines de trombenoire","pourquoi les ruines sont-elles hantées"}}},fp="16,173,23.290.0,17.315.0,26.184.0,41.184.0,28.125.0,47.176.0,33.121.0,49.152.0"}
P.entries["quest:93176"] = {n="My Little Friends",s="Un gardien vous propose un paquet pour commencer à étudier trois petites créatures. L’Entomology Starter Kit contient les notes et le matériel nécessaires.",h="Un gardien vous propose un paquet pour commencer à étudier trois petites créatures.",kw={"arbor tarantula","entomologie","flesh picker","hay weevil specimen","ménagerie","my little friends","nécessaire de départ"},sec={{t="L’offre d’un gardien",b="Un gardien qui a passé de nombreuses heures à étudier une petite ménagerie vous propose de partager son passe-temps. Le paquet contient des notes et du matériel pour commencer. Avec l’Entomology Starter Kit, vous pouvez partir à la recherche d’un Arbor Tarantula, d’un Hay Weevil Specimen et d’un Flesh Picker."}},faq={{q="Que veut me faire faire le gardien ?",a="Utilisez l’Entomology Starter Kit pour trouver et capturer un Arbor Tarantula, un Hay Weevil Specimen et un Flesh Picker.",al={"tâche my little friends","que faut-il collecter"}},{q="Que contient le paquet ?",a="Le paquet contient des notes et du matériel pour vous initier au passe-temps du gardien.",al={"contenu du nécessaire de départ","contenu du paquet"}},{q="Qu’étudie le gardien ?",a="Le gardien étudie l’anatomie, le régime alimentaire et les rituels sociaux des créatures d’une petite ménagerie.",al={"petite ménagerie","qu’étudie-t-il"}},{q="Que se passe-t-il si je perds le nécessaire ?",a="Le gardien dit que vous devrez acheter un autre paquet pour une somme modique.",al={"nécessaire de départ perdu","remplacement du nécessaire"}}},fp="17,141,18.256.0,35.111.0,23.86.0,28.96.0,31.74.0"}
P.entries["quest:932"] = {n="Haine folle",s="Près des colonies de Teldrassil, Lord Melenas a rallié les grells de Gangreroche. Tallonkai Viveracine envoie des champions de confiance arrêter le satyre avant qu’il ne menace les elfes de la nuit.",h="Près des colonies de Teldrassil, Lord Melenas a rallié les grells de Gangreroche.",kw={"gangreroche","grells","lord melenas","satyre","tallonkai viveracine","teldrassil","haine folle"},ang={["class:Druid"]="En tant que druide, vous voyez Melenas et ses grells corrompus empoisonner l’équilibre fragile de la jeune nature de Teldrassil.",["race:NightElf"]="En tant qu’elfe de la nuit, vous faites face à un ancien rappel de la chute de vos ancêtres, victimes de l’ambition démoniaque. Vaincre Lord Melenas est un devoir envers l’Arbre-monde et un acte de pénitence ancestrale."},sec={{t="Une honte amère",b="Les satyres portent le souvenir d’une ancienne trahison dans l’histoire des kaldorei. Pendant la War of the Ancients, ils étaient des Highborne qui se sont donnés à la Légion ardente. À présent, l’un d’eux s’est installé sur Teldrassil, le jeune Arbre-monde destiné à servir de sanctuaire. Pour Tallonkai Viveracine et les défenseurs à ses côtés, cette présence est une honte amère."},{t="La menace de Gangreroche",b="Au nord des sentiers voisins, les cavernes corrompues de Gangreroche grouillent de grells sauvages. Lord Melenas a rassemblé ces créatures chaotiques en une force hostile soumise à sa volonté. Tallonkai craint ce que le satyre pourrait déchaîner sur les branches de l’Arbre-monde et exige qu’on en finisse rapidement et discrètement. Il veut que Melenas soit tué et que sa tête tranchée lui soit rapportée."}},faq={{q="Qui est Lord Melenas ?",a="Lord Melenas est un satyre qui s’est emparé de Gangreroche, au nord de Teldrassil. Il commande des guerriers grells agressifs et complote pour répandre la corruption dans l’Arbre-monde.",al={"lord melenas","qui est melenas","boss de gangreroche"}},{q="Où trouver Lord Melenas ?",a="Lord Melenas se cache au fond de Gangreroche, au nord de Dolanaar, sur Teldrassil. Des grells et d’autres créatures corrompues l’entourent.",al={"emplacement de melenas","où se trouve melenas","comment trouver gangreroche"}},{q="Pourquoi Tallonkai Viveracine veut-il garder cela secret ?",a="Les satyres rappellent l’ancienne trahison des elfes de la nuit pendant la War of the Ancients. La présence audacieuse d’un satyre dans le jeune Arbre-monde est une honte, et Tallonkai veut régler le problème sans provoquer une panique générale.",al={"pourquoi garder le secret","pourquoi garder cela entre nous","secret de tallonkai"}},{q="Quel est le lien entre les satyres et les grells ?",a="Les grells sont de petites créatures sauvages et malicieuses, naturellement corrompues et présentes partout sur Teldrassil. Les satyres peuvent intimider ces créatures inférieures ou les soumettre à leurs ambitions.",al={"grells et satyres","pourquoi les grells suivent melenas","lien entre satyres et grells"}},{q="Pourquoi y a-t-il des satyres sur Teldrassil ?",a="Teldrassil a été planté il y a seulement quelques années, mais la corruption et les êtres maléfiques ont vite atteint l’île, malgré les espoirs des druides d’en faire un sanctuaire pur. Les satyres s’y sont glissés et ont établi des repaires dans des lieux ombrageux comme Gangreroche.",al={"satyres sur teldrassil","comment les satyres sont-ils arrivés ici","corruption de teldrassil"}},{q="Qui est Tallonkai Viveracine ?",a="Tallonkai Viveracine est un gardien elfe de la nuit posté près de Dolanaar. Il veille aux menaces contre Teldrassil et envoie des aventuriers combattre les foyers de corruption voisins.",al={"tallonkai","qui donne haine folle"}}},fx={["84ee0888"]={q="Pourquoi Tallonkai Viveracine a-t-il besoin de la Tête de Melenas ?",a="Tallonkai Viveracine demande la tête coupée du seigneur Melenas comme preuve irréfutable que le satyre a vraiment été tué. Avec le seigneur Melenas mort et sa tête en main, Tallonkai peut être assuré que la menace infecte tapi juste à côté de Sombrevallon a été éliminée en secret, lui permettant de laisser cette affaire humiliante derrière lui sans alerter les anciens.",al={"but de la tête de melenas","pourquoi rapporter la tête de melenas","à quoi sert la tête de melenas"}}},fp="14,179,17.327.0,22.331.0,20.167.0,30.123.0,51.210.0,50.167.0,54.221.0,27.165.0"}
P.entries["quest:93224"] = {n="Carved Centaur Totems",s="Le capitaine Pentigast, à la Combe de Nijel, cherche des totems centaures sculptés pour en imiter les motifs. Il espère que ces copies lui donneront un avantage auprès des clans centaures.",h="Le capitaine Pentigast, à la Combe de Nijel, cherche des totems centaures sculptés pour en imiter les motifs.",kw={"capitaine pentigast","totems centaures sculptés","bois sculpté","centaure","clans centaures","désolace","combe de nijel","totems"},sec={{t="Un marché de bois",b="À la Combe de Nijel, le capitaine Pentigast cherche à tirer avantage des sculptures sur bois des clans centaures. Les deux clans hésitent à accepter l’aide d’étrangers, surtout des non-centaures. Il vous demande de lui rapporter des échantillons de leurs motifs afin qu’il puisse faire réaliser des sculptures similaires."}},faq={{q="Pourquoi le capitaine Pentigast veut-il ces totems ?",a="Il espère faire réaliser des sculptures similaires et obtenir un avantage auprès des clans centaures.",al={"pourquoi des totems","plan de pentigast"}},{q="Pourquoi les clans centaures hésitent-ils à accepter de l’aide ?",a="Les deux clans hésitent à accepter de l’aide venant de l’extérieur de leur clan, surtout de la part de non-centaures.",al={"pourquoi les centaures refusent-ils l’aide","méfiance des centaures envers les étrangers"}},{q="En quoi les totems centaures sont-ils faits ?",a="Les centaures de la région font du troc avec des objets en bois sculpté.",al={"matériau des totems","bois sculpté"}},{q="Où le capitaine Pentigast attend-il ?",a="Le capitaine Pentigast se trouve à la Combe de Nijel.",al={"où se trouve pentigast","capitaine à la combe de nijel"}}},fp="21,158,17.267.0,43.81.0,50.88.0,36.42.0,34.38.0"}
P.entries["quest:93225"] = {n="Carved Centaur Totems",s="Gurda Wildmane pense que des totems sculptés pourraient l’aider à gagner les faveurs des Gelkis ou des Magram. Elle a besoin d’exemplaires authentiques recueillis auprès des clans centaures de Désolace.",h="Gurda Wildmane pense que des totems sculptés pourraient l’aider à gagner les faveurs des Gelkis ou des Magram.",kw={"totems centaures sculptés","monnaie centaure","désolace","gelkis","poste de rôdeur-fantôme","gurda wildmane","magram"},sec={{t="Une monnaie centaure",b="Gurda Wildmane, au Poste de Rôdeur-fantôme, a vu des clans centaures se retrouver loin de leurs campements pour faire du commerce. Elle les a vus utiliser des totems sculptés comme monnaie. Elle pense maintenant qu’un grand lot pourrait convaincre les Gelkis ou les Magram, mais les totems qu’elle a sculptés pourraient ne pas passer pour des objets authentiques. Elle vous demande donc de lui apporter des exemplaires authentiques."}},faq={{q="Que veut Gurda ?",a="Gurda Wildmane vous demande de lui apporter d’authentiques totems centaures sculptés.",al={"requête de gurda","besoin de wildmane"}},{q="Pourquoi lui faut-il des totems sculptés ?",a="Gurda pense qu’un grand lot pourrait l’aider à gagner les faveurs des Gelkis ou des Magram.",al={"totems pourquoi","pourquoi des totems"}},{q="Où les centaures utilisent-ils les totems ?",a="Gurda a vu des centaures de différents clans se retrouver loin de leurs campements et faire du commerce en utilisant des totems sculptés comme monnaie.",al={"commerce des centaures","où trouver des totems"}},{q="Où trouver Gurda Wildmane ?",a="Gurda Wildmane se trouve au Poste de Rôdeur-fantôme.",al={"emplacement de gurda","wildmane au poste de rôdeur-fantôme"}},{q="Quels clans centaures sont concernés ?",a="Gurda espère qu’un lot de totems pourrait lui gagner les faveurs des Gelkis ou des Magram.",al={"gelkis magram","quels clans"}}},fp="21,157,18.320.0,21.69.0,32.79.0,32.118.0,32.39.0,33.84.0"}
P.entries["quest:933"] = {n="La couronne de la Terre",s="Aux Bassins d'Arlithrien, Corithras Ragelune vous demande de puiser de l'eau tandis que les furbolgs Gangrebois deviennent violents. Son récit de Teldrassil commence par la disparition de Malfurion Hurlorage après la Troisième guerre.",h="Aux Bassins d'Arlithrien, Corithras Ragelune vous demande de puiser de l'eau tandis que les furbolgs...",kw={"corithras ragelune","dolanaar","fandral forteramure","gangrebois","malfurion hurlorage","bassins d'arlithrien","flasque de tourmaline"},ang={["class:Druid"]="En tant que druide, vous découvrez comment le leadership de Fandral Forteramure a divisé le Cercle cénarien, tandis qu'il cherchait à rendre aux Elfes de la nuit leur ancienne immortalité.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous découvrez comment Teldrassil a vu le jour après la soudaine disparition de Malfurion et apprenez quel choix politique a conduit à sa plantation."},sec={{t="Un puits de lune périlleux",b="Corithras Ragelune vous remet une Flasque de tourmaline et vous envoie à un puits de lune au sud-est de l'entrée de Darnassus, le long des Bassins d'Arlithrien. Les furbolgs Gangrebois étaient autrefois paisibles, mais ils attaquent désormais sans prévenir. Ils tendent des embuscades aux voyageurs et harcèlent les patrouilles des Sentinelles dans toute la région. Ces escarmouches menacent désormais le nouveau foyer des Elfes de la nuit."},{t="L'ambition de Fandral Forteramure",b="À votre retour avec la flasque remplie, Corithras vous raconte les débuts de Teldrassil. Après la Troisième guerre, Shan'do Malfurion Hurlorage a disparu, laissant les druides du Cercle cénarien sans chef et divisés. L'Archidruide Fandral Forteramure a pris la tête des druides en son absence. Il a exhorté le Cercle des Anciens, à Sombrivage, à cesser leur deuil. Selon lui, les Elfes de la nuit devaient retrouver leur immortalité perdue et guérir leur civilisation en plantant un nouvel Arbre-Monde immense."}},faq={{q="Où se trouve le puits de lune de cette quête ?",a="Le puits de lune se trouve au sud-est de l'entrée principale de Darnassus, le long des rives méridionales des Bassins d'Arlithrien.",al={"puits de lune d'arlithrien","emplacement du puits de lune","où remplir la flasque"}},{q="Pourquoi les furbolgs Gangrebois attaquent-ils ?",a="Les furbolgs Gangrebois, autrefois un peuple paisible d'hommes-ours, sont désormais en proie à une rage sombre et aveugle à travers Teldrassil. Les Sentinelles ont d'abord pris ces attaques pour des incidents isolés, mais elles sont devenues un danger constant pour les patrouilles et les établissements voisins.",al={"furbolgs enragés","furbolgs gangrebois agressifs","pourquoi les furbolgs attaquent"}},{q="Qu'est-il arrivé à Malfurion Hurlorage ?",a="Shan'do Malfurion Hurlorage a disparu sans explication après la Troisième guerre. Les druides du Cercle cénarien et les chefs des Elfes de la nuit ignorent ce qu'il est devenu.",al={"où est malfurion","qu'est-il arrivé à hurlorage","malfurion disparu"}},{q="Qui a décidé de planter Teldrassil ?",a="Malfurion ayant disparu, l'Archidruide Fandral Forteramure a pris la tête des druides. Il a convaincu le Cercle des Anciens, à Sombrivage, d'élever un nouvel Arbre-Monde, affirmant que les kaldorei en avaient besoin pour se reconstruire et retrouver l'immortalité perdue lors de la destruction de Nordrassil.",al={"qui a créé teldrassil","forteramure et l'arbre-monde","pourquoi teldrassil a été planté"}}},fx={f2628340={q="Pourquoi Corithras Ragelune veut-il que cela soit fait ?",a="Corithras Ragelune enquête sur les puits de lune sacrés à travers Teldrassil pour évaluer et s'occuper de la santé de l'Arbre-monde. Tout en vous guidant à travers ces rituels, il partage également l'histoire tourmentée de la plantation de Teldrassil, espérant que vous compreniez à la fois les devoirs sacrés de votre peuple et les signes troublants qui se propagent dans leur nouveau foyer.",al={"pourquoi corithras veut-il l'eau du puits de lune","mobile de corithras","pourquoi couronne de la terre"}},["21308da4"]={q="À quoi sert la Flasque de tourmaline remplie ?",a="La flasque contient de l'eau pure tirée du puits de lune près des Bassins d'Arlithrien. Corithras a besoin d'échantillons provenant des divers puits de lune de Teldrassil pour surveiller les eaux qui nourrissent l'Arbre-monde et pour mener les rites nécessaires afin de maintenir l'équilibre spirituel de la terre intact au milieu de la corruption croissante.",al={"but de la flasque de tourmaline remplie","pourquoi remplir la flasque de tourmaline","flasque de tourmaline et puits de lune"}}},fp="18,201,19.359.0,27.473.0,37.111.0,41.247.0,37.151.0,32.269.0"}
P.entries["quest:93317"] = {n="Crab Season",s="Sur Zephras, les cueilleurs s’empressent de récolter les traqueurs de Chantevent avant la fin de la brève saison. Des fanatiques rendent les rives périlleuses, alors les habitants demandent de l’aide.",h="Sur Zephras, les cueilleurs s’empressent de récolter les traqueurs de Chantevent avant la fin de la brève...",kw={"crab season","crabes","activité des fanatiques","chair des traqueurs de chantevent","traqueurs de chantevent","lac chantevent","zephras"},ang={["profession:Cooking"]="Comme cuisinier, vous pouvez préparer la chair saisonnière des traqueurs de Chantevent, récoltés dans le lac de Zephras."},sec={{t="Une récolte éphémère",b="Pendant quelques semaines chaque année, les traqueurs de Chantevent apparaissent sur les rives d’eau douce du lac Chantevent et le long des rivières qui l’alimentent. Leur chair est une denrée rare, mais la saison passe vite."},{t="Périls au bord de l’eau",b="Des fanatiques patrouillent dans les terres sauvages autour de Zephras, mettant en danger les cueilleurs locaux. Le voyage jusqu’au lac Chantevent est trop périlleux pour qu’ils s’y rendent seuls. Si vous n’affrontez pas les rives et ces crabes au mauvais caractère, cette brève récolte risque d’être perdue."}},faq={{q="Que sont les traqueurs de Chantevent ?",a="Les traqueurs de Chantevent sont des crabes agressifs que l’on ne trouve qu’aux abords du lac Chantevent, sur Zephras. On ne peut les récolter que pendant quelques semaines chaque année.",al={"que sont les traqueurs de chantevent","crabes de chantevent","crabes du lac de zephras"}},{q="Pourquoi faut-il récolter les crabes maintenant ?",a="Les traqueurs de Chantevent ne sont disponibles que pendant quelques semaines chaque année. Une fois la saison terminée, leur chair ne peut plus être récoltée avant l’année suivante.",al={"pourquoi récolter les traqueurs maintenant","période de récolte des traqueurs","pourquoi les crabes sont disponibles si peu de temps"}},{q="Pourquoi les cueilleurs locaux ne peuvent-ils pas récolter les crabes eux-mêmes ?",a="L’activité des fanatiques a rendu le voyage jusqu’au lac Chantevent trop dangereux pour les cueilleurs locaux, qui risquent de ne pas arriver avant la fin de la courte saison.",al={"pourquoi les habitants ne peuvent pas récolter les crabes","fanatiques de zephras","activité des fanatiques à chantevent"}},{q="Où trouve-t-on les traqueurs de Chantevent ?",a="Les traqueurs de Chantevent vivent sur les rives du lac Chantevent, sur Zephras, ainsi que le long des berges des rivières voisines qui le relient aux alentours.",al={"lieux où trouver les traqueurs de chantevent","où trouver les crabes sur zephras","rives du lac chantevent"}},{q="Les traqueurs de Chantevent sont-ils dangereux à chasser ?",a="Les traqueurs de Chantevent sont agressifs et pincent quiconque tente de les récolter.",al={"les traqueurs de chantevent sont-ils dangereux","caractère des crabes","crabes agressifs"}},{q="À quoi sert la chair des traqueurs de Chantevent ?",a="Les habitants récoltent la chair des traqueurs de Chantevent pour en faire une nourriture saisonnière, disponible quelques semaines seulement. Les fanatiques qui barrent les chemins les ont poussés à demander l’aide des aventuriers.",al={"utilité de la chair des traqueurs de chantevent","pourquoi récolter la chair des crabes","à quoi sert la chair des traqueurs"}}},fp="11,149,18.180.0,19.235.0,27.135.0,48.144.0,58.125.0,34.105.0,40.74.0,39.163.0"}
P.entries["quest:93318"] = {n="WANTED: Vulgara the Insatiable",s="Dans les Hautes-terres de Shen’dar, Vulgara the Insatiable terrorise les voyageurs et les colonies voisines. Le Constable Aonda a lancé une prime des Pacificateurs, et demande que la tête de Vulgara soit remise à Danarii Bellowveil.",h="Dans les Hautes-terres de Shen’dar, Vulgara the Insatiable terrorise les voyageurs et les colonies voisines.",kw={"prime","constable aonda","danarii bellowveil","pacificateurs","hautes-terres de shen’dar","shen’dar","vuldren","vulgara","vulgara the insatiable"},sec={{t="Le fléau des hautes-terres",b="Le Constable Aonda a désigné Vulgara the Insatiable comme un danger immédiat pour les hautes-terres. Cette immense vuldren ailée niche au sud-ouest de Shen’dar, où elle terrorise les voyageurs et les colonies locales. Les Pacificateurs font appel aux chasseurs de primes pour mettre fin à la menace."},{t="Des protecteurs sous pression",b="Des bandits et une secte obscure mettent les Pacificateurs à rude épreuve dans toute la région. Tuer Vulgara réduirait le danger pour la population locale et préserverait la sécurité des cieux de Shen’dar. Les défenseurs pourraient alors se consacrer à la défense civile."}},faq={{q="Qui est Vulgara the Insatiable ?",a="Vulgara the Insatiable est une vuldren ailée immense qui terrorise les Hautes-terres de Shen’dar. Les autorités locales la qualifient de fléau. Son appétit insatiable et sa violence menacent les voyageurs et les colonies voisines.",al={"qui est vulgara","histoire de vulgara","quel genre de monstre est vulgara"}},{q="Qui a lancé la prime sur Vulgara ?",a="Le Constable Aonda, des Pacificateurs locaux, a lancé la prime pour protéger les citoyens de la région. Les chasseurs doivent remettre à Danarii Bellowveil une preuve de la mort de Vulgara.",al={"qui a lancé la prime sur vulgara","qui veut la mort de vulgara","constable aonda"}},{q="Où trouver Vulgara the Insatiable ?",a="Vulgara rôde au sommet d’une colline au sud-ouest de Shen’dar, dans les Hautes-terres de Shen’dar.",al={"emplacement de vulgara","où apparaît vulgara","trouver vulgara"}},{q="Qui est Danarii Bellowveil ?",a="Danarii Bellowveil s’occupe de l’exécution de la prime. Alors que les bandits et les cultistes pressent les Pacificateurs, Danarii examine la tête tranchée de Vulgara et remet la récompense promise.",al={"qui est danarii bellowveil","remettre la prime à danarii"}},{q="Qu’est-ce qu’une vuldren ?",a="Une vuldren est une bête ailée prédatrice et dangereuse qui vit dans les hautes-terres. Vulgara est particulièrement immense et féroce, et ses attaques menacent les colonies locales.",al={"qu’est-ce qu’une vuldren","bête vuldren"}},{q="Quelles autres menaces pèsent sur les Hautes-terres de Shen’dar ?",a="Dans les Hautes-terres de Shen’dar, les Pacificateurs sont débordés par une secte bien implantée et des bandits qui s’en prennent aux citoyens locaux. Des bêtes prédatrices comme Vulgara leur donnent aussi du fil à retordre.",al={"quelles menaces dans les hautes-terres de shen’dar","secte et bandits de shen’dar"}}},fp="30,204,20.264.0,20.212.0,30.207.0,33.155.0,42.81.0,26.180.0,35.164.0,49.174.0"}
P.entries["quest:93319"] = {n="Pilfered Windstones",s="Sur Zephras, les pierres de vent dérobées ont épuisé les réserves d’urgence. Les Highlands Bandits les ont volées tandis qu’Aonda et ses rares gardiens de la paix défendent Falaath Village contre les sectateurs toujours plus nombreux.",h="Sur Zephras, les pierres de vent dérobées ont épuisé les réserves d’urgence.",kw={"aonda","grotte des bandits","falaath village","highlands bandits","pilfered windstones","hautes-terres de shen’dar","pierres de vent","zephras"},ang={["class:Rogue"]="En tant que Voleur, vous voyez comment les Highlands Bandits profitent d’une colonie affaiblie par la menace des sectateurs.",["race:Skyborne"]="En tant que Skyborne, vous savez que la vie quotidienne sur Zephras dépend des pierres de vent. Récupérer et défendre ces réserves compte pour les colonies locales."},sec={{t="Les réserves dérobées de Zephras",b="Les pierres de vent rythment la vie quotidienne sur Zephras. Chaque colonie garde des réserves d’urgence pour les périodes de crise, mais les stocks du village ont commencé à s’épuiser. Puis on a découvert des bandits capturés dans le nord des Hautes-terres de Shen’dar en possession des pierres. Pendant des mois, les Highlands Bandits s’étaient introduits dans les réserves locales, prenant tout ce qu’ils pouvaient tandis que la sécurité était réduite."},{t="Défenses affaiblies, menaces imminentes",b="Aonda est responsable de la défense du village et a refusé d’approuver un raid contre la grotte du nord. La colonie manque de gardiens de la paix à envoyer ailleurs. Au sud, les sectateurs se multiplient à Falaath Village, alors les gardes doivent tenir leurs postes face à cette menace. Les gardiens de la paix étant immobilisés, des aventuriers indépendants doivent affronter les bandits et récupérer les pierres de vent volées."}},faq={{q="À quoi servent les pierres de vent sur Zephras ?",a="Les habitants de Zephras dépendent des pierres de vent pour leur quotidien et leur survie. Les colonies conservent des réserves pour les urgences.",al={"à quoi servent les pierres de vent","pourquoi faut-il des pierres de vent","utilité des pierres de vent"}},{q="Qui a volé les pierres de vent ?",a="Les Highlands Bandits ont volé les pierres de vent. On a découvert des bandits capturés dans une grotte des Hautes-terres de Shen’dar en possession des pierres, et les habitants pensent que les voleurs s’introduisaient dans les entrepôts du village depuis des mois.",al={"qui a volé les pierres de vent","qui a pris les pierres de vent","voleurs de pierres de vent"}},{q="Où se trouvent les Highlands Bandits ?",a="Les Highlands Bandits campent dans une grotte au nord de la colonie, dans les Hautes-terres de Shen’dar. Ils y entreposent les biens dérobés dans les réserves du village.",al={"où se trouve la grotte des bandits","emplacement des highlands bandits","bandits des hautes-terres de shen’dar"}},{q="Pourquoi le village n’a-t-il pas délogé les bandits de leur grotte ?",a="Aonda supervise la défense de la colonie et a refusé d’organiser un raid contre la grotte du nord, car le village compte peu de gardiens de la paix. Les envoyer au loin laisserait la colonie vulnérable aux sectateurs toujours plus nombreux à Falaath Village, au sud.",al={"pourquoi ne pas attaquer la grotte des bandits","pourquoi aonda n’attaque-t-elle pas","défense du village contre les bandits"}},{q="Quelle menace pèse sur Falaath Village ?",a="Les sectateurs sont de plus en plus nombreux à Falaath Village, au sud de la colonie. Leur présence oblige les gardiens de la paix à protéger leur foyer au lieu de poursuivre les bandits.",al={"quelle menace pèse sur falaath village","sectateurs de falaath"}},{q="La récupération des pierres de vent résout-elle la pénurie de la colonie ?",a="La récupération des pierres volées soulage temporairement les réserves d’urgence, mais les perturbations des routes d’approvisionnement restent urgentes. Sans voies d’approvisionnement sûres, les pénuries continueront de menacer la colonie.",al={"les pierres de vent sont-elles en sécurité","routes d’approvisionnement de zephras","pénurie de pierres de vent résolue"}}},fp="19,184,28.354.0,38.379.0,40.117.0,25.210.0,40.137.0,51.254.0,38.159.0,63.194.0"}
P.entries["quest:93320"] = {n="Tower Defense",s="À la position fortifiée, Tower Defense résiste à un ennemi en nombre écrasant. Les défenseurs tiennent encore, mais l’épuisement menace de les faire céder.",h="À la position fortifiée, Tower Defense résiste à un ennemi en nombre écrasant.",kw={"défenseurs","épuisement","fortification","avant-poste","siège","impasse","tower defense"},ang={["class:Warrior"]="En tant que guerrier, vous savez qu’une position tenue face à un ennemi supérieur en nombre met l’endurance à l’épreuve autant que le talent. La discipline en première ligne peut empêcher la défense de s’effondrer."},sec={{t="Une défense éprouvée",b="La garnison repousse le premier assaut sur une position fortifiée. Pourtant, les assaillants sont plus nombreux et continuent d’avancer. Les combattants survivants s’épuisent, et la frontière entre survie et défaite s’amenuise."},{t="La menace de l’usure",b="La garnison tient son périmètre, mais le temps joue en faveur des assaillants. Les escarmouches prolongées contre des forces supérieures en nombre épuisent les défenseurs. Il leur faut une action décisive pour briser l’impasse avant que leurs lignes ne cèdent."}},faq={{q="De quoi parle Tower Defense ?",a="Tower Defense raconte une défense désespérée face à un ennemi en nombre écrasant. La ligne tient encore, mais l’épuisement menace de la faire céder si l’impasse perdure.",al={"qu’est-ce que tower defense","quête tower defense","de quoi parle cette quête"}},{q="Contre qui les défenseurs se battent-ils ?",a="Les assaillants sont plus nombreux que les défenseurs et pressent assez fort pour épuiser la garnison. Le culte attaque la tour de guet du pylône à l’extérieur de la ville.",al={"qui attaque dans tower defense","contre qui nous battons-nous","ennemi de tower defense"}},{q="Quelle est la situation des défenseurs ?",a="Les défenseurs s’épuisent après un combat prolongé sous un assaut incessant. Sans renfort, la garnison risque de perdre du terrain si l’impasse ne prend pas fin rapidement.",al={"pourquoi les défenseurs sont-ils épuisés","impasse à la tour","situation du combat"}},{q="Tenir la ligne suffit-il à gagner la bataille ?",a="Repousser l’assaut ne fait que gagner un peu de temps. La fatigue aura raison des défenseurs s’ils ne trouvent pas le moyen de sortir de l’impasse.",al={"avons-nous gagné tower defense","comment se termine tower defense","que se passe-t-il après les avoir repoussés"}},{q="Où se déroule cette défense ?",a="La défense se déroule dans un avant-poste fortifié assiégé. La pression constante d’assaillants nombreux a dispersé les forces des défenseurs.",al={"où se trouve tower defense","zone de tower defense","de quelle tour s’agit-il"}},{q="Que faut-il pour renverser la situation ?",a="Les défenseurs doivent trouver rapidement un plan pour briser le siège avant que leur ligne de front épuisée ne cède.",al={"que faut-il faire ensuite","comment gagner le siège","briser l’impasse"}}},fp="13,156,21.221.0,23.219.0,28.152.0,31.143.0,44.155.0,41.131.0,35.135.0,32.94.0"}
P.entries["quest:93394"] = {n="Meeting the Magister",s="Un contact Shen'dralar vous demande de trouver le Magister Kirandis dans le temple des Shen’dralas. La rencontre porte sur les pylônes restaurés et votre place parmi ses habitants méfiants.",h="Un contact Shen'dralar vous demande de trouver le Magister Kirandis dans le temple des Shen’dralas.",kw={"kirandis","magister kirandis","rencontre avec le magistère","pylônes","shen'dralar","shen’dralas","temple"},sec={{t="Au temple",b="La grande structure attire votre attention, et un contact Shen'dralar vous indique où trouver le Magister Kirandis. Le magistère est un vieil ami de la personne qui vous a envoyé et pourrait se réjouir de votre présence. Les Shen'dralar pourraient se montrer méfiants, aussi vous demande-t-on de les aborder avec respect."},{t="Les pylônes",b="Après que vous avez trouvé Kirandis, le magistère constate que les pylônes brillent de nouveau. Leur retour lie pleinement les Shen'dralar aux Shen’dralas. Kirandis vous encourage à rencontrer les habitants du temple, dont la méfiance pourrait s'atténuer avec le temps."}},faq={{q="Qui suis-je censé trouver ?",a="On vous demande de trouver le Magister Kirandis dans le temple des Shen’dralas.",al={"trouver kirandis","rencontre avec le magistère","temple de kirandis"}},{q="Où se trouve le Magister Kirandis ?",a="Le Magister Kirandis se trouve dans le temple des Shen’dralas.",al={"emplacement de kirandis","où est le magistère","kirandis au temple"}},{q="Qui est Kirandis pour la personne qui m'a envoyé ?",a="Kirandis est un vieil ami du contact Shen'dralar qui vous a envoyé.",al={"ami de kirandis","vieil ami du magistère"}},{q="Les Shen'dralar vont-ils m'accueillir ?",a="Les Shen'dralar pourraient se méfier de votre présence, mais on vous demande d'agir avec respect.",al={"shen'dralar méfiants","vont-ils m'apprécier","accueil des shen'dralar"}},{q="Qu'est-il arrivé aux pylônes ?",a="Leur pouvoir brille de nouveau, et Kirandis affirme que cela lie pleinement les Shen'dralar aux Shen’dralas.",al={"pouvoir des pylônes","pylônes du temple","pylônes restaurés"}},{q="Que dois-je faire après avoir rencontré Kirandis ?",a="Kirandis vous encourage à rencontrer certains habitants du temple, qui pourraient se montrer méfiants au début.",al={"rencontrer les habitants","que faire après kirandis","habitants des shen’dralas"}}},fp="20,180,13.266.0,10.221.0,26.75.0,27.54.0,42.66.0,32.86.0,32.92.0,40.88.0"}
P.entries["quest:934"] = {n="La couronne de la Terre",s="À la Clairière de l'Oracle, Corithras Ragelune vous envoie recueillir de l'eau dans le puits de lune sacré de Teldrassil. Votre voyage commence à révéler pourquoi la création de l'Arbre-monde a mal tourné.",h="À la Clairière de l'Oracle, Corithras Ragelune vous envoie recueillir de l'eau dans le puits de lune sacré de...",kw={"alexstrasza","flasque d'améthyste","corithras ragelune","fandral forteramure","immortalité","puits de lune","nozdormu","la clairière de l'oracle","oracle tree","teldrassil"},ang={["class:Druid"]="En tant que druide, vous voyez le fossé entre les ambitions autoritaires de Fandral Forteramure et l'équilibre naturel que Malfurion Hurlorage a toujours préservé.",["faction:Alliance"]="En tant que membre de l'Alliance, vous découvrez pourquoi le chancre et la folie des créatures troublent le territoire de la toute nouvelle capitale de l'Alliance, Teldrassil.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous découvrez les espoirs de votre peuple pour Teldrassil après le sacrifice de Nordrassil pendant la troisième guerre."},sec={{t="La Clairière de l'Oracle",b="Corithras Ragelune vous envoie au nord-ouest de Teldrassil, jusqu'à la Clairière de l'Oracle. Sous les grandes branches de l'Oracle Tree se trouve le premier et le plus puissant puits de lune de l'île. Vous puisez de l'eau dans son bassin sacré et la versez dans une Flasque d'améthyste. Les druides et l'arbre lui-même veillent sur la santé de leur nouvelle patrie depuis ce sanctuaire."},{t="La bénédiction refusée",b="À votre retour à Dolanaar avec la flasque, Corithras vous raconte comment le projet de l'archidruide Fandral Forteramure a mal tourné. Après le sacrifice de Nordrassil au Mont Hyjal, Forteramure a planté Teldrassil pour rendre leur immortalité aux Elfes de la nuit. Il a demandé aux Aspects draconiques de le bénir.\n\nNozdormu l'Intemporel a refusé et a reproché son arrogance à Forteramure. La reine Alexstrasza a elle aussi refusé sa bénédiction, le don de l'Aspect de la Vie. Privé de ce don, Teldrassil a poussé de façon instable et imparfaite, ce qui a rendu l'arbre vulnérable à une profonde corruption."}},faq={{q="Où se trouve le puits de lune de la Clairière de l'Oracle ?",a="Le puits de lune de la Clairière de l'Oracle se trouve au nord-ouest de Teldrassil, sous les grandes branches de l'Oracle Tree et juste au nord de la route principale menant à Darnassus.",al={"où se trouve la clairière de l'oracle","emplacement du puits de lune de la clairière de l'oracle","puits de l'oracle"}},{q="Qui est Corithras Ragelune ?",a="Corithras Ragelune est un gardien elfe de la nuit posté à Dolanaar. Il guide les jeunes défenseurs à travers Teldrassil pour leur faire prélever des échantillons dans ses puits de lune et leur enseigne l'histoire des débuts imparfaits de l'arbre.",al={"corithras","qui est corithras ragelune"}},{q="Teldrassil a-t-il rendu leur immortalité aux Elfes de la nuit ?",a="Non. Teldrassil a offert un nouveau foyer aux Elfes de la nuit, mais leur immortalité n'a pas été restaurée après le sacrifice de Nordrassil pendant la troisième guerre.",al={"les elfes de la nuit sont-ils immortels","immortalité de teldrassil","les elfes vivent-ils de nouveau éternellement"}},{q="À quoi sert l'eau recueillie dans la Clairière de l'Oracle ?",a="Le puits de lune sous l'Oracle Tree est le premier et le plus puissant de l'île. Son eau permet à Corithras d'évaluer la santé spirituelle et naturelle de Teldrassil.",al={"pourquoi recueillir l'eau de l'oracle","utilité de la flasque d'améthyste"}}},fx={["28d6c4e0"]={q="Pourquoi Corithras Ragelune veut-il que cela soit fait ?",a="Corithras Ragelune vous guide à travers les puits de lune sacrés de Teldrassil pour transmettre la véritable histoire du nouvel Arbre-monde. En vous envoyant sous les branches de l'Arbre de l'Oracle pour tirer de l'eau du premier et plus puissant puits de Teldrassil, il s'assure que vous communiiez avec sa sagesse profonde avant de révéler pourquoi les branches restent troublées et privées d'immortalité.",al={"pourquoi corithras veut-il l'eau","mobile de corithras","pourquoi envoyer à la clairière de l'oracle"}}},fp="18,174,16.321.0,19.520.1,43.152.0,26.190.0,45.139.0,62.156.0"}
P.entries["quest:93461"] = {n="Welcome to Shen'dar Village",s="À Shen’dar, les nouveaux venus de sang Bien-né sont accueillis sous une trêve fragile. L’Ordre suprême et les Sculpte-vents préservent la paix dans le village, tandis que d’anciennes rivalités couvent au-delà de ses frontières.",h="À Shen’dar, les nouveaux venus de sang Bien-né sont accueillis sous une trêve fragile.",kw={"coriella calmbreeze","ordre suprême","bien-né","pavillon principal","rathiril sunlance","shen’dar","sculpte-vents"},ang={["class:Mage"]="En tant que mage lié aux traditions des Bien-nés, vous pourriez reconnaître vos origines dans l’Ordre suprême. Ses anciens, dont Rathiril Sunlance, sont respectés à Shen’dar.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous découvrez à Shen’dar des liens avec les anciennes lignées des Bien-nés et leur héritage, rappel de la fierté et du patrimoine arcanique qui ont divisé la société elfique."},sec={{t="Un foyer fragile",b="Les nouveaux venus portant des traces de sang Bien-né se rendent au pavillon principal pour rendre hommage à Rathiril Sunlance, ancien de l’Ordre suprême. Ils cherchent aussi une chambre auprès de Coriella Calmbreeze, l’aubergiste locale. Différentes factions elfiques partagent ce refuge, mais leur trêve reste tendue."},{t="Rivalités des terres sauvages",b="La vie quotidienne apporte chambres et petits travaux, mais les frictions persistent entre l’Ordre suprême et les Sculpte-vents. Sur la place du village, les deux groupes restent courtois. Au-delà du village, loin des regards indiscrets, les vieilles rivalités n’ont plus de limites."}},faq={{q="Quel est le but de la quête Welcome to Shen’dar ?",a="Vous êtes accueilli à Shen’dar et découvrez ses figures importantes ainsi que la paix fragile qui y règne. Vous rencontrez Rathiril Sunlance, l’ancien de l’Ordre suprême, et Coriella Calmbreeze à l’auberge du village avant d’accepter des tâches locales.",al={"quel est le but de cette quête","informations sur l’accueil à shen’dar","présentation de shen’dar"}},{q="Qui est Rathiril Sunlance ?",a="Rathiril Sunlance est un ancien de l’Ordre suprême qui vit à Shen’dar. Il se trouve dans le pavillon principal du village, au détour d’un couloir depuis la personne qui vous accueille d’abord. Il est un interlocuteur pour ceux qui ont une ascendance Bien-née ou des affaires avec l’Ordre suprême.",al={"qui est rathiril sunlance","ancien de l’ordre suprême","où se trouve rathiril"}},{q="Qui est Coriella Calmbreeze ?",a="Coriella Calmbreeze tient l’auberge locale de Shen’dar. Elle propose aux voyageurs de la nourriture, un hébergement et des provisions avant qu’ils ne s’aventurent dans les terres sauvages alentour.",al={"qui est coriella calmbreeze","aubergiste de shen’dar","où loger à shen’dar"}},{q="Quelles tensions opposent l’Ordre suprême et les Sculpte-vents ?",a="L’Ordre suprême et les Sculpte-vents suivent des traditions et des ambitions différentes, et les tensions sont vives entre eux. Ils préservent une paix courtoise à Shen’dar, mais au-delà du village, le conflit peut dégénérer en violence dans les terres sauvages.",al={"ordre suprême et sculpte-vents","pourquoi ces tensions","conflit dans le village"}},{q="Que signifie le regard de l’Ordre suprême mentionné par le donneur de quête ?",a="Les descendants des Bien-nés ont une lueur singulière dans les yeux. Cet héritage arcanique permet aux habitants attentifs de reconnaître le regard de l’Ordre suprême.",al={"regard de l’ordre suprême","yeux des bien-nés","lueur des bien-nés"}},{q="Shen’dar est-il à l’abri des conflits ?",a="À Shen’dar, l’Ordre suprême et les Sculpte-vents restent courtois. Hors du village, la paix prend fin et l’hostilité éclate loin des regards vigilants.",al={"shen’dar est-il sûr","violence hors de shen’dar","danger dans les terres sauvages"}}},fp="27,199,16.267.0,22.230.0,61.211.0,25.249.0,27.156.0,63.230.0,56.157.0,39.171.0"}
P.entries["quest:93464"] = {n="The Visiting Mage",s="Un draeneï du Havre boueux vous demande de retrouver Azore, un mage humain en Désolace. Ses connaissances du draenethyst pourraient aider ceux qui ne comprennent pas pleinement son pouvoir.",h="Un draeneï du Havre boueux vous demande de retrouver Azore, un mage humain en Désolace.",kw={"azore","désolace","draeneï","draenethyst","le havre boueux","mage humain"},sec={{t="Un mage dont on se souvient",b="Au Havre boueux, un draeneï se rappelle avoir chassé Azore, venu de Désolace. Le mage humain craignait le pouvoir du draenethyst et avait averti qu'il ne devait pas tomber entre de mauvaises mains. Aujourd'hui, ses connaissances semblent valoir la peine d'être recherchées, même si le draeneï reconnaît que ceux qui sont ici ne comprennent pas pleinement le cristal. On vous demande de trouver Azore en Désolace."}},faq={{q="Qui est Azore ?",a="Azore est un mage humain de Désolace qui est venu autrefois au Havre boueux. Il craignait le pouvoir du draenethyst.",al={"qui est azore","mage de passage","mage et draenethyst"}},{q="Qu'est-ce que le draenethyst ?",a="Le draenethyst est sacré pour les draeneïs du Havre boueux et les aide à garder la raison, même s'ils ne le comprennent pas pleinement.",al={"draenethyst","cristal des draeneïs","qu'est-ce que le draenethyst"}},{q="Pourquoi dois-je chercher Azore ?",a="Les draeneïs du Havre boueux pensent que les connaissances d'Azore sur le draenethyst pourraient être précieuses.",al={"trouver azore","pourquoi chercher le mage","mage en désolace"}},{q="Où Azore est-il allé ?",a="Azore se trouve en Désolace.",al={"emplacement d'azore","où est le mage","trouver le mage de passage"}},{q="Pourquoi les draeneïs ont-ils chassé Azore ?",a="Ils ont chassé Azore pour protéger ce qui leur appartenait.",al={"pourquoi chasser azore","azore chassé","mage du havre boueux"}}},fp="17,159,17.336.0,13.98.0,20.119.0,27.88.0,19.21.0,37.49.0"}
P.entries["quest:93465"] = {n="Notes on Draenethyst",s="Azore Aldamort vous envoie chercher les notes de Gimashi sur le draenethyst. Les démonistes de la Lame ardente étudient cette substance venue d’au-delà de la Porte des ténèbres.",h="Azore Aldamort vous envoie chercher les notes de Gimashi sur le draenethyst.",kw={"azore aldamort","lame ardente","la porte des ténèbres","draenethyst","gimashi","notes","démoniste"},sec={{t="Notes sur le draenethyst",b="Selon Azore Aldamort, les notes de Gimashi pourraient expliquer ce que la Lame ardente a appris sur le draenethyst. Gimashi est une démoniste dont la tour se dresse dans un ravin au sud-est. Vous devez rapporter ses notes à Azore avant que la Lame ardente puisse utiliser ses connaissances sur cette substance à des fins plus sombres."}},faq={{q="Qu’est-ce que le draenethyst ?",a="Le draenethyst est une substance venue d’au-delà de la Porte des ténèbres.",al={"signification du draenethyst","qu’est-ce que le draenethyst","pierre de draenethyst"}},{q="Qui est Gimashi ?",a="Gimashi est une démoniste de la Lame ardente qui étudie le draenethyst.",al={"qui est gimashi","démoniste gimashi","notes de gimashi"}},{q="Pourquoi Azore veut-il les notes de Gimashi ?",a="Azore veut les notes de Gimashi pour découvrir ce que la Lame ardente sait sur le draenethyst.",al={"pourquoi ces notes","azore et le draenethyst","ce qu’azore veut"}},{q="Où se trouve Gimashi ?",a="Gimashi se trouve au sommet de sa tour, dans un ravin au sud-est.",al={"emplacement de gimashi","où se trouve la tour","ravin au sud-est"}},{q="D’où vient le draenethyst ?",a="Le draenethyst vient d’au-delà de la Porte des ténèbres.",al={"origine du draenethyst","substance de la porte des ténèbres","d’où vient le draenethyst"}}},fp="20,157,15.300.0,20.55.0,15.56.0,36.84.0,17.65.0,32.45.0"}
P.entries["quest:935"] = {n="La couronne de la Terre",s="À Teldrassil, on recueille l’eau des puits de lune pour soulager le mal de l’Arbre-monde. Les rites portent les échantillons à l’Archidruide Fandral Forteramure, à Darnassus, où grandit l’inquiétude face à cet arbre privé de bénédictions.",h="À Teldrassil, on recueille l’eau des puits de lune pour soulager le mal de l’Arbre-monde.",kw={"alexstrasza","enclave cénarienne","corithras ragelune","crown of the earth","darnassus","fandral forteramure","puits de lune","nozdormu","teldrassil"},ang={["class:Druid"]="En tant que druide, vous apportez l’eau des puits de lune à Fandral Forteramure, Archidruide du Cercle cénarien. Sa présence révèle les profondes divisions politiques et spirituelles entre druides, tandis que Malfurion est absent.",["faction:Alliance"]="En tant que membre de l’Alliance, vous découvrez Darnassus, capitale empreinte de mystère ancien. Les terres sauvages corrompues qui l’entourent montrent que le danger menace les Elfes de la nuit jusque sur leur sol sacré.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous percevez l’inquiétude qui se cache sous votre nouveau foyer. Teldrassil fut planté par orgueil, sans les bénédictions des Aspects dragons, et son mal menace le nouveau départ de votre peuple."},sec={{t="Une genèse imparfaite",b="Teldrassil s’éleva après la Troisième guerre pour offrir un nouveau foyer aux Elfes de la nuit et leur rendre l’immortalité perdue. Pourtant, les Grands Aspects Alexstrasza et Nozdormu lui refusèrent leurs bénédictions et ne voulurent pas approuver sa création. Sans leur protection, le mal se répand dans l’arbre. D’étranges créatures apparaissent dans ses branches, et des tribus de furbolgs autrefois pacifiques sombrent dans la folie."},{t="Remise à l’Archidruide",b="Corithras Ragelune envoie de jeunes aventuriers recueillir l’eau des puits de lune à travers Teldrassil. Il espère étudier les échantillons et apaiser les maux de l’arbre. Après les avoir versés dans un seul récipient, il vous envoie au cœur de Darnassus, à l’Enclave cénarienne. L’Archidruide Fandral Forteramure a façonné Teldrassil et considère que lui seul peut résoudre le problème de la corruption qui s’étend."}},faq={{q="Pourquoi Fandral Forteramure veut-il cette eau des puits de lune ?",a="Fandral Forteramure veut étudier les échantillons des puits de lune et combattre la corruption qui se répand dans l’Arbre-monde. Il a défendu la plantation de Teldrassil et se sent responsable de trouver un remède aux bêtes étranges et aux furbolgs devenus fous dans sa ramure.",al={"but de l’eau pour fandral","pourquoi fandral a-t-il besoin du récipient","à quoi sert l’eau"}},{q="Pourquoi Teldrassil est-il ravagé par la corruption et des bêtes enragées ?",a="La corruption et les bêtes étranges ravagent Teldrassil parce qu’il a été planté sans les bénédictions d’Alexstrasza the Life-Binder ni de Nozdormu the Timeless. Contrairement à l’antique Arbre-monde Nordrassil, il ne bénéficie pas de la protection de ces aspects primordiaux des dragons. Sa croissance imparfaite déforme la faune et les furbolgs des environs sous l’effet de fléaux malfaisants.",al={"pourquoi teldrassil est-il malade","corruption de teldrassil","pourquoi les furbolgs sont-ils fous"}},{q="Où se trouve l’Archidruide Fandral Forteramure ?",a="L’Archidruide Fandral Forteramure se trouve dans l’Enclave cénarienne, à Darnassus. Vous le trouverez au sommet du pavillon central des druides, qui surplombe les bosquets sacrés de l’Enclave.",al={"où se trouve fandral","emplacement de fandral forteramure","comment trouver fandral"}},{q="Qui est Corithras Ragelune ?",a="Corithras Ragelune est un Elfe de la nuit posté à Dolanaar. Il envoie de jeunes aventuriers remplir des fioles aux puits de lune de Teldrassil, puis verse leur eau dans un seul récipient et charge des courriers de le remettre à l’Archidruide Fandral Forteramure, à Darnassus.",al={"qui donne crown of the earth","rôle de corithras","corithras ragelune"}},{q="Que se passe-t-il après avoir terminé cette quête ?",a="Vous remettez le récipient rempli à Fandral Forteramure, ce qui conclut la chaîne principale de Crown of the Earth à Teldrassil. Il accepte l’eau avec brusquerie, puis se tourne de nouveau vers les menaces plus vastes qui pèsent sur le foyer des Elfes de la nuit.",al={"suite de crown of the earth","que faire après crown of the earth 6","quête suivante après crown of the earth"}},{q="Pourquoi Fandral Forteramure se montre-t-il si froid en recevant le récipient ?",a="Fandral Forteramure est fier et impatient. En l’absence de Malfurion Hurlorage, il porte le fardeau de diriger le Cercle cénarien. Il méprise les contretemps administratifs et les messagers lents, car il croit que la survie de Teldrassil repose sur ses épaules.",al={"pourquoi fandral est-il grossier","personnalité de fandral","fandral est-il toujours grognon"}}},fx={d62362b9={q="Pourquoi Corithras Ragelune veut-il que le récipient soit apporté à Fandral ?",a="Corithras est profondément inquiet de la maladie croissante qui infecte Teldrassil. Parce que l'Arbre-monde a poussé sans les bénédictions vitales des Aspects Alexstrasza et Nozdormu, des bêtes étranges ont surgi du sol et des furbolgs autrefois pacifiques sont devenus violemment fous. Corithras pense que l'Archidruide Fandral Forteramure recherche activement un remède pour purger cette corruption galopante, alors il combine d'urgence les échantillons d'eau que vous avez recueillis à travers les branches et vous envoie les livrer directement à Darnassus.",al={"mobile de corithras","pourquoi envoyer l'eau du puits de lune","pourquoi corithras veut-il que cela soit fait"}},["01febe86"]={q="Pourquoi Corithras Ragelune vous envoie-t-il plutôt que d'y aller lui-même ?",a="Corithras reste stationné à Dolanaar pour superviser les affaires locales et surveiller les anomalies inquiétantes qui perturbent les branches inférieures de Teldrassil. Vous avez personnellement voyagé jusqu'aux divers puits de lune pour rassembler les flasques d'eau, prouvant ainsi votre endurance et votre dévouement. En vous confiant le récipient combiné, Corithras peut continuer à surveiller Dolanaar tout en s'assurant que Fandral Forteramure reçoive les échantillons à Darnassus sans délai supplémentaire.",al={"pourquoi envoyer le joueur chez fandral","pourquoi moi corithras","pourquoi corithras ne livre-t-il pas le récipient"}}},fp="18,209,16.368.0,26.368.1,51.257.0,58.324.0,45.161.0,26.239.0,41.201.1,64.240.0"}
P.entries["quest:93552"] = {n="Harvesting Windstones",s="Au Bosquet de Thendal, Dalia the Collector vous demande de ramasser des pierres de vent brutes avant que leur pouvoir ne s’éteigne. Les anciennes énergies élémentaires de l’Île de Zéphras déclinent peu à peu.",h="Au Bosquet de Thendal, Dalia the Collector vous demande de ramasser des pierres de vent brutes avant que leur...",kw={"pylônes d’ancrage","dalia","dalia the collector","bosquet de thendal","élémentaires de vent","amas de pierres de vent","pierres de vent","île de zéphras"},ang={["class:Mage"]="En tant que Mage, vous pouvez percevoir la puissance élémentaire contenue dans les pierres de vent et la fragilité des écosystèmes magiques lorsque leurs sources élémentaires disparaissent.",["profession:Mining"]="En tant que mineur, vous récoltez dans les étendues sauvages de l’Île de Zéphras des minerais et des cristaux précieux, dont des pierres de vent brutes."},sec={{t="Une île qui s’éteint",b="L’Île de Zéphras dépend encore de la magie du vent, mais ses défenses naturelles faiblissent. Il y a des siècles, les élémentaires de vent qui partageaient l’île avec ses elfes ont disparu. Depuis, la magie qui soutient la terre et ses grands pylônes d’ancrage s’est affaiblie. Les habitants du Bosquet de Thendal ont donc besoin de toutes les réserves d’énergie brute qu’ils peuvent trouver."},{t="La valeur des pierres de vent",b="Des pierres de vent cristallines bleues sont éparpillées dans le Bosquet de Thendal. Leurs enveloppes fragiles renferment une magie du vent dense, héritée des âges passés. Elles ne peuvent pas soutenir l’île éternellement, mais offrent à ses elfes une source fiable de pouvoir arcanique. La collecte d’amas bruts reste essentielle à la vie quotidienne."}},faq={{q="Que sont les pierres de vent ?",a="Les pierres de vent sont des dépôts cristallins bleus éparpillés dans le Bosquet de Thendal. Elles renferment une énergie brute du vent concentrée, que les elfes de l’Île de Zéphras récoltent comme combustible magique.",al={"pierre de vent brute","amas de pierres de vent","cristaux bleus"}},{q="Qui est Dalia the Collector ?",a="Dalia the Collector est une collectionneuse elfe en poste au Bosquet de Thendal, sur l’Île de Zéphras. Elle organise la collecte de ressources brutes indispensables, surtout des pierres de vent, pour soutenir les réserves magiques déclinantes de l’île.",al={"dalia","dalia zéphras","dalia la collectionneuse"}},{q="Pourquoi la magie de l’Île de Zéphras s’affaiblit-elle ?",a="Il y a des siècles, les élémentaires de vent qui vivaient aux côtés des elfes locaux ont disparu. Depuis, la magie des grands pylônes d’ancrage, qui soutient l’île, s’est lentement dissipée.",al={"zéphras perd sa magie","magie déclinante de zéphras","pylônes d’ancrage"}},{q="Où sont partis les élémentaires de vent ?",a="Personne ne sait où sont partis les élémentaires de vent. Ils ont disparu il y a plusieurs siècles, laissant l’île épuiser peu à peu ses réserves élémentaires restantes.",al={"élémentaires disparus","où sont les élémentaires de vent"}},{q="Que sont les pylônes d’ancrage ?",a="Les grands pylônes d’ancrage sont d’anciennes structures de l’Île de Zéphras, imprégnées d’une puissante magie qui soutient la terre. Depuis la disparition des élémentaires, cette force s’est progressivement affaiblie.",al={"grands pylônes d’ancrage","histoire des pylônes d’ancrage"}},{q="Où trouver des pierres de vent brutes ?",a="Les pierres de vent brutes sont éparpillées dans le Bosquet de Thendal, sur l’Île de Zéphras, où elles prennent la forme d’affleurements cristallins bleus luminescents.",al={"emplacement des pierres de vent","cristaux du bosquet de thendal"}}},fx={["0a83a06c"]={q="Pourquoi Dalia The Collector veut-elle des Amas de pierre des vents ?",a="Dalia cherche des Amas de pierre des vents car l'Île de Zéphras dépend de leur pouvoir magique pour survivre. Depuis la disparition des élémentaires de vent il y a des siècles, la magie nourricière qui irriguait autrefois l'île décline lentement. Pour les elfes locaux, dont les vies et la culture restent profondément liées à l'énergie arcanique, la collecte de ces vents cristallisés fournit une source d'énergie vitale et fiable pour remplacer ce que les pylônes d'ancrage défaillants ne peuvent plus fournir.",al={"pourquoi dalia veut des pierres des vents","motif de dalia the collector","pourquoi récolter des pierres des vents"}},["33ac4299"]={q="À quoi servent les Amas de pierre des vents ?",a="Les Amas de pierre des vents contiennent l'énergie brute et concentrée des vents eux-mêmes. Comme les anciens pylônes d'ancrage magiques de l'Île de Zéphras perdent de leur puissance avec le temps, les habitants de l'île utilisent ces amas cristallisés comme une source d'énergie alternative fiable pour soutenir leur communauté et maintenir leur lien essentiel à l'énergie magique.",al={"utilité des amas de pierre des vents","à quoi sert un amas de pierre des vents","pourquoi des amas de pierre des vents"}}},fp="21,166,15.327.0,23.276.0,20.168.0,27.214.0,40.178.0,33.152.0,27.191.0,33.122.0"}
P.entries["quest:93644"] = {n="Tattered Journal",s="Un journal abîmé trouvé près de Shen’dralas vous mène à son auteur, Evenshade. Les mots manquants pourraient encore compter pour lui.",h="Un journal abîmé trouvé près de Shen’dralas vous mène à son auteur, Evenshade.",kw={"journal abîmé","evenshade","journal perdu","mordent","restaurer le journal","shen’dralas","journal en lambeaux"},sec={{t="Un nom subsiste",b="Près de Shen’dralas, les pages usées d’un journal ne vous laissent que peu de choses à lire. Parmi les lettres brouillées, un nom de famille reste lisible : Evenshade. Son auteur se trouve peut-être dans les environs, et les mots qui subsistent dans le journal sont le seul indice."},{t="Le sort du journal",b="Mordent reconnaît son journal, bien que des siècles se soient écoulés depuis qu’il l’a perdu. Le texte a disparu, mais il se souvient de son contenu et garde ce savoir pour lui. Il vous autorise à tenter de restaurer le journal si ses pages ont survécu."}},faq={{q="Où le journal a-t-il été trouvé ?",a="Le journal a été trouvé près de Shen’dralas.",al={"emplacement du journal","lieu du journal en lambeaux"}},{q="Qui a écrit le journal ?",a="Le nom qui subsiste dans le journal désigne Evenshade comme son auteur.",al={"auteur du journal","journal d’evenshade"}},{q="Pourquoi chercher Evenshade ?",a="Le journal porte le nom de famille Evenshade, et son auteur se trouve peut-être quelque part dans Shen’dralas.",al={"trouver evenshade","nom de famille du journal"}},{q="Peut-on lire le journal ?",a="La plupart des connaissances contenues dans le journal sont perdues, et les lettres restantes sont difficiles à distinguer.",al={"journal illisible","contenu du journal"}},{q="Que dit Mordent au sujet du journal ?",a="Mordent le reconnaît comme son journal perdu, mais affirme que le texte a disparu.",al={"journal de mordent","propriétaire du journal"}},{q="Mordent révélera-t-il ce qui était écrit ?",a="Mordent se souvient du contenu du journal, mais ne souhaite pas en parler à voix haute.",al={"contenu du journal","secret de mordent"}}},fp="16,124,14.231.0,18.250.1,28.39.0,22.71.0,23.88.0,25.96.0,40.72.0,36.85.0"}
P.entries["quest:93663"] = {n="Lost in Transit",s="Dar vous demande de retrouver un courrier gobelin disparu et sa cargaison destinée au Havre boueux. Cette perte menace sa réputation commerciale.",h="Dar vous demande de retrouver un courrier gobelin disparu et sa cargaison destinée au Havre boueux.",kw={"crocilisque","dar","draeneï","courrier gobelin","le havre boueux","perdu en chemin","cargaison","commerce"},sec={{t="Une cargaison manquante",b="Dar échange des fournitures supplémentaires avec les draeneï du Havre boueux contre une partie de leurs prises. Or, son courrier gobelin n'est pas revenu avec une cargaison. Dar craint qu'un crocilisque ne l'ait tué, mais récupérer les marchandises est essentiel à ses affaires. Il vous demande de fouiller près des points d'eau le long de la route et d'apporter la cargaison au Havre boueux."}},faq={{q="Qui est Dar ?",a="Dar échange des fournitures supplémentaires avec les draeneï du Havre boueux contre une partie de leurs prises.",al={"dar","qui a envoyé la cargaison","marchand gobelin"}},{q="Qui est le courrier disparu ?",a="Dar a envoyé un courrier gobelin avec sa dernière cargaison, mais celui-ci n'est jamais revenu.",al={"gobelin disparu","où est le courrier","courrier gobelin"}},{q="Où la cargaison devait-elle être livrée ?",a="La cargaison était destinée aux draeneï du Havre boueux.",al={"destination de la cargaison","où la livrer","livraison au havre boueux"}},{q="Pourquoi Dar veut-il retrouver la cargaison ?",a="Dar dit que sa réputation commerciale est en jeu si la cargaison n'est pas retrouvée et livrée.",al={"pourquoi retrouver la cargaison","réputation de dar","pourquoi est-ce important"}},{q="Où dois-je chercher le courrier ?",a="Dar vous demande de fouiller près des points d'eau le long de la route.",al={"où chercher","emplacement du courrier","où a disparu la cargaison"}}},fp="15,130,18.328.0,11.84.0,27.83.0,29.56.0,37.88.0,36.53.0"}
P.entries["quest:93680"] = {n="Clé de la ville",s="Wordeen cherche un moyen d’entrer à Dalaran, désormais reconstruite aux portes de la Dark Lady.",h="Wordeen cherche un moyen d’entrer à Dalaran, désormais reconstruite aux portes de la Dark Lady.",kw={"archimonde","légion ardente","dalaran","clé crasseuse","kirin tor","clé des égouts","moulin-de-tarren","wordeen voidglare"},sec={{t="La ville reconstruite",b="À Moulin-de-Tarren, Magus Wordeen Voidglare veut en apprendre davantage sur le Kirin Tor. Leur cité, Dalaran, est tombée aux mains de la démoniaque Légion ardente, d’un seul coup porté par l’archidémon Archimonde. Les mages survivants sont devenus des vagabonds dépossédés de tout. Ils ont maintenant reconstruit Dalaran aux portes mêmes de la Dark Lady.\n\nWordeen vous envoie fouiller leurs camps. Il espère que vous trouverez un grimoire ancien, une relique secrète ou autre chose qui permettra à la Horde d’entrer discrètement dans la cité. Vous rapportez une clé crasseuse des égouts de Dalaran."},{t="La réponse de Wordeen",b="Wordeen voit la clé des égouts et se réjouit que quelqu’un d’autre l’utilise. Il reste du travail avant de pouvoir s’en servir sans danger."}},faq={{q="Qui propose la quête Key to the City ?",a="Magus Wordeen Voidglare, à Moulin-de-Tarren, vous demande de l’aide.",al={"qui donne key to the city","donneur de quête key to the city","où commencer key to the city"}},{q="Pourquoi la Horde s'intéresse-t-elle à Dalaran ?",a="Le Kirin Tor a reconstruit Dalaran aux portes de la Dark Lady après qu’Archimonde a détruit sa cité. Wordeen veut en apprendre davantage sur ses membres et trouver un moyen pour la Horde d’y entrer discrètement.",al={"pourquoi dalaran","pourquoi surveiller dalaran","que font les mages"}},{q="Quel objet vous demande-t-on de trouver ?",a="Vous devez fouiller les camps du Kirin Tor pour trouver une clé crasseuse des égouts de Dalaran.",al={"que récupérer pour wordeen","quelle est la clé","objet key to the city"}}},fp="15,76,16.518.0,16.120.1,42.56.0,39.191.0,31.73.0"}
P.entries["quest:937"] = {n="La clairière enchantée",s="Au nord-ouest de Teldrassil, les harpies plumesang menacent la Clairière de l'Oracle et son ancien Oracle Tree. Après qu'elles ont tué un messager en route pour Darnassus, la Sentinelle Arynia Eclairciel ordonne d'éclaircir leurs nids et de rapporter leurs ceintures en preuve.",h="Au nord-ouest de Teldrassil, les harpies plumesang menacent la Clairière de l'Oracle et son ancien Oracle...",kw={"arynia eclairciel","plumesang","darnassus","harpies","la clairière de l'oracle","oracle tree","sentinelle","teldrassil","la clairière enchantée"},ang={["class:Druid"]="En tant que druide, vous éprouvez une grande révérence envers les anciens doués de conscience. Éliminer les harpies qui menacent l'Oracle Tree contribue à protéger l'équilibre naturel de la clairière.",["faction:Alliance"]="En tant que membre de l'Alliance, vous resserrez les liens avec les dirigeants des elfes de la nuit à Darnassus, toute proche, en aidant les Sentinelles à sécuriser les bosquets sacrés de Teldrassil.",["race:NightElf"]="En tant qu'elfe de la nuit, vous avez le devoir solennel de défendre les esprits anciens de l'Arbre-monde et de protéger les Sentinelles contre les attaques des harpies."},sec={{t="Une clairière assiégée",b="La Sentinelle Arynia Eclairciel protège la Clairière de l'Oracle avec une escorte de guerriers. En son cœur se dresse l'Oracle Tree, un ancien colossal enraciné parmi les ramures de Teldrassil. Les harpies plumesang se sont répandues dans la canopée alentour. Elles nichent dans ses creux et menacent quiconque s'approche."},{t="Les communications avec Darnassus coupées",b="Un messager porteur d'un rapport urgent de l'Oracle Tree n'atteint jamais Darnassus. Les harpies plumesang lui tendent une embuscade et le tuent avant qu'il puisse quitter la clairière. Arynia vous demande d'éclaircir leurs rangs et de rapporter des ceintures plumesang pour prouver que leurs nids ont été affaiblis."},{t="Un appel de l'arbre",b="À mesure que les nids voisins sont éclaircis, l'Oracle Tree envoie un fragment de son écorce enchantée. L'ancien cherche un émissaire pour porter son message aux hauts dirigeants des kaldorei."}},faq={{q="Pourquoi les harpies attaquent-elles la Clairière de l'Oracle ?",a="Les harpies plumesang nichent dans tout le nord de Teldrassil et ont encerclé l'Oracle Tree. Elles défendent farouchement leurs perchoirs et attaquent quiconque se rend dans la clairière sacrée ou en repart.",al={"harpies dans la clairière de l'oracle","pourquoi les plumesang attaquent","harpies de l'oracle tree"}},{q="Qui est la Sentinelle Arynia Eclairciel ?",a="La Sentinelle Arynia Eclairciel est une officier postée dans la Clairière de l'Oracle avec une modeste avant-garde. Elle protège l'Oracle Tree des harpies voisines et s'efforce de rétablir le contact avec Darnassus.",al={"arynia eclairciel","qui donne la clairière enchantée","histoire d'arynia eclairciel"}},{q="Qu'est-il arrivé au messager envoyé à Darnassus ?",a="Les harpies plumesang ont tendu une embuscade au messager qui portait un rapport de l'Oracle Tree à Darnassus et l'ont tué. Elles l'ont attaqué sur les sentiers de la clairière avant qu'il n'atteigne un lieu sûr.",al={"messager de l'oracle tree","messager mort darnassus"}},{q="Qu'est-ce que l'Oracle Tree ?",a="L'Oracle Tree est un ancien immense et doué de conscience, enraciné dans la Clairière de l'Oracle. Il veille sur les ramures de l'Arbre-monde et transmet sagesse et avertissements aux dirigeants des elfes de la nuit.",al={"oracle tree teldrassil","qui est l'oracle tree"}},{q="Quelle preuve la Sentinelle Eclairciel exige-t-elle ?",a="La Sentinelle Eclairciel vous demande de rapporter six ceintures plumesang prises sur des harpies tuées. Elles prouvent que les nids autour de la clairière ont été éclaircis.",al={"quête ceinture plumesang","combien de ceintures","preuve de quête"}},{q="Que se passe-t-il après l'élimination des harpies ?",a="Une fois les harpies voisines éclaircies, l'Oracle Tree laisse tomber un fragment de son écorce. Vous pouvez porter le message longtemps retardé de l'ancien jusqu'à Darnassus.",al={"quête suivante après la clairière enchantée","que fait ensuite l'oracle tree"}}},fx={["2b035f45"]={q="Pourquoi la Sentinelle Arynia Eclairciel veut-elle que cela soit fait ?",a="La Sentinelle Arynia Eclairciel a été envoyée avec un petit détachement de Sentinelles pour défendre l'Arbre de l'Oracle sacré. Des harpies ont niché dans toute la clairière, encerclant les défenseurs et massacrant même un messager envoyé à Darnassus avec des rapports cruciaux. Arynia ne peut laisser son poste défensif sans surveillance, elle a donc besoin d'un aventurier pour frapper directement les nids et repousser la volée avant que la clairière ne soit submergée.",al={"pourquoi tuer les harpies","motif d'arynia eclairciel","pourquoi protéger l'arbre de l'oracle"}},["164cdda3"]={q="Qui sont les harpies Plume-de-sang qui menacent la clairière ?",a="Les harpies Plume-de-sang sont de vicieux prédateurs aviaires qui se sont perchés sur les étendues nord-ouest de Teldrassil. Agressives et territoriales, elles ont construit des nids encerclant La Clairière de l'Oracle, coupant toute communication avec Darnassus et cherchant à chasser ou massacrer les protecteurs elfes de la nuit qui gardent l'arbre ancien.",al={"qui sont les harpies","harpies plume-de-sang teldrassil","pourquoi les harpies sont-elles ici"}},["3f052dc4"]={q="Pourquoi la Sentinelle Eclairciel ne peut-elle pas s'occuper elle-même des harpies ?",a="La Sentinelle Arynia Eclairciel ne dirige qu'un petit contingent de Sentinelles stationnées à l'Arbre de l'Oracle. Avec leur messager déjà mort et les harpies encerclant la position, ses troupes restantes doivent rester sur place pour protéger l'arbre sacré contre toute embuscade. Passer à l'offensive dans les repaires des harpies nécessite des voyageurs capables et libres, prêts à s'aventurer dans des nids hostiles.",al={"pourquoi arynia a-t-elle besoin de mon aide","pourquoi les sentinelles ne peuvent-elles pas tuer les harpies","pourquoi moi clairière enchantée"}}},fp="19,252,19.296.0,26.290.0,23.172.1,43.181.0,35.187.0,46.175.0,24.178.0,45.149.0,39.146.1"}
P.entries["quest:93735"] = {n="The Broken Construct",s="À Valanaar, un automate endommagé menace l’une des dernières reliques encore actives de l’île. Riaani Nightwind s’est rendu à l’ouest de la ville pour l’examiner. Ces anciennes machines portent l’histoire des esprits du vent.",h="À Valanaar, un automate endommagé menace l’une des dernières reliques encore actives de l’île.",kw={"artisan","the broken construct","assemblage","riaani nightwind","valanaar","esprits du vent","sculpte-vents"},ang={["class:Mage"]="En tant que mage, vous pourriez trouver particulièrement intéressants les appareils magiques délicats entretenus par les Sculpte-vents.",["class:Shaman"]="En tant que chaman, vous pouvez voir dans les assemblages offerts par les esprits du vent avant leur départ le lien ancien qui unissait ces esprits aux habitants de l’île.",["profession:Engineering"]="En tant qu’ingénieur, vous pouvez apprécier les défis mécaniques et magiques que doivent relever les artisans pour maintenir en état des assemblages enchantés anciens, privés de leurs esprits protecteurs."},sec={{t="Les dons des esprits du vent",b="Il y a bien longtemps, les esprits du vent ont offert aux habitants de l’île des instruments magiques, des appareils et des assemblages animés. Au fil des générations, les Sculpte-vents ont pris soin de ces dons. Puis les esprits sont partis et leur patronage a pris fin. La plupart des créations sont tombées en ruine. Seule une poignée fonctionne encore."},{t="Une crise à Valanaar",b="L’un des derniers assemblages encore fonctionnels de Valanaar a été endommagé. Sa perte amoindrirait encore le patrimoine déclinant de l’île. L’artisan Riaani Nightwind a été envoyé à l’ouest de la ville pour examiner la machine et tenter de la réparer. Ces appareils anciens sont fragiles, et il a besoin d’aide."}},faq={{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents sont des gardiens locaux chargés d’entretenir les instruments magiques, les appareils et les assemblages offerts par les esprits du vent. Depuis le départ des esprits, ils s’efforcent de préserver les quelques reliques encore fonctionnelles.",al={"qui sont les sculpte-vents","histoire des sculpte-vents","que font les sculpte-vents"}},{q="D’où viennent les assemblages magiques ?",a="Les esprits du vent ont offert aux habitants de l’île des assemblages, des instruments et des appareils magiques. Depuis leur départ, très peu de ces créations fonctionnent encore.",al={"qui a construit les assemblages","origine des assemblages","d’où viennent les assemblages"}},{q="Qui est Riaani Nightwind ?",a="Riaani Nightwind est un artisan envoyé à l’ouest de Valanaar pour examiner et réparer l’un des rares assemblages encore fonctionnels de la ville, après qu’il a été endommagé.",al={"qui est riaani nightwind","emplacement de riaani","artisan à valanaar"}},{q="Pourquoi la plupart des assemblages de l’île sont-ils brisés ?",a="La plupart des assemblages de l’île sont tombés en ruine après le départ des esprits du vent et la fin de leur ancien patronage. Seule une poignée est encore en état de marche.",al={"pourquoi les assemblages sont-ils brisés","pourquoi les assemblages sont-ils tombés en panne","départ des esprits du vent"}},{q="Quel est le lien entre Valanaar et les assemblages ?",a="Valanaar abrite quelques-uns des derniers assemblages encore fonctionnels de l’île, offerts par les esprits du vent. L’un d’eux a récemment été endommagé à l’ouest de la ville, et Riaani Nightwind a été envoyé pour l’examiner et le réparer.",al={"qu’est-ce que valanaar","ville de valanaar","où se trouve l’assemblage"}},{q="Que faut-il faire pour The Broken Construct ?",a="Vous devez vous rendre à l’ouest de Valanaar, trouver l’artisan Riaani Nightwind et l’aider à réparer l’assemblage endommagé.",al={"objectif de la quête the broken construct","que faire pour the broken construct","où aller pour the broken construct"}}},fp="20,230,25.291.0,20.290.0,24.236.0,43.173.0,24.151.0,47.167.0,48.204.0,47.127.0"}
P.entries["quest:93736"] = {n="Unwelcome Spirits",s="Les Sculpte-vents cherchent les esprits du vent, qui leur échappent. Des hollows apparaissent dans la Forêt de Trombenoire, et l’ordre recueille leurs essences pour découvrir ce qui a chassé les véritables esprits.",h="Les Sculpte-vents cherchent les esprits du vent, qui leur échappent.",kw={"hollows","forêt de trombenoire","lutins","unwelcome spirits","essence de hollow du vent","hollows du vent","esprits du vent","sculpte-vents"},ang={["class:Shaman"]="Pour ceux qui communient avec les éléments, le départ des esprits naturels du vent et l’arrivée des hollows signalent un profond déséquilibre de l’air dans la région."},sec={{t="Les esprits disparus",b="Les Sculpte-vents ont perdu le contact avec les esprits du vent. Ils cherchent à comprendre pourquoi ils sont partis et ce qui pourrait les faire revenir. Leur départ a laissé un vide dans l’atmosphère élémentaire locale."},{t="Ombres à Shadowgale",b="Après le départ des esprits du vent, d’étranges lutins appelés hollows sont apparus au nord, dans la Forêt de Trombenoire. Les Sculpte-vents ignoraient leur existence avant la disparition des esprits. Les hollows semblent liés à l’absence des esprits, et leurs essences pourraient aider à découvrir ce qu’ils sont."}},faq={{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents sont un ordre qui cherche à comprendre pourquoi les esprits du vent l’ont abandonné et comment les faire revenir. Leurs recherches portent désormais sur d’étranges phénomènes apparus après la disparition des esprits.",al={"qui sont les sculpte-vents","faction des sculpte-vents","que veulent les sculpte-vents"}},{q="Que sont les hollows ?",a="Les hollows sont d’étranges lutins du vent apparus dans la Forêt de Trombenoire après le départ des esprits originels du vent. Leur origine et leur nature restent inconnues, aussi les érudits recueillent-ils leurs essences pour les étudier.",al={"que sont les hollows","histoire des hollows du vent","lutins hollows"}},{q="Où se trouve la Forêt de Trombenoire ?",a="La Forêt de Trombenoire se trouve au nord. De mystérieux hollows du vent y sont apparus depuis le départ des esprits élémentaires de la région.",al={"où se trouve la forêt de trombenoire","emplacement de shadowgale"}},{q="Pourquoi les esprits du vent sont-ils partis ?",a="Nul ne sait pourquoi les esprits du vent ont disparu. Les Sculpte-vents en cherchent la cause et espèrent renouer le contact avec eux.",al={"pourquoi les esprits du vent sont-ils partis","où sont partis les esprits"}},{q="Pourquoi recueillir les essences de hollow du vent ?",a="Les Sculpte-vents recueillent les essences des hollows dispersés pour les étudier. Ils espèrent que ces vestiges révéleront ce qui a donné naissance à ces êtres après le départ des esprits.",al={"pourquoi recueillir les essences de hollow","utilité des essences de hollow du vent"}},{q="Les hollows sont-ils hostiles ?",a="Les hollows sont des intrus indésirables apparus après la disparition des esprits naturels. Leur propagation dans la Forêt de Trombenoire appelle à les disperser pour protéger la région et recueillir des spécimens.",al={"les hollows sont-ils dangereux","menace des lutins hollows"}}},fp="17,189,20.204.0,21.273.0,24.207.0,21.195.0,27.122.0,31.122.0,44.168.0,35.202.0"}
P.entries["quest:93737"] = {n="The Broken Construct",s="Ayessa vous envoie aider Riaani Nightwind, qui s’occupe d’un assemblage hors service. Écoutez ses plans pour savoir ce qu’il faut faire afin de réparer la machine.",h="Ayessa vous envoie aider Riaani Nightwind, qui s’occupe d’un assemblage hors service.",kw={"ayessa","assemblage cassé","assemblage","ingénierie","riaani nightwind","the broken construct"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous connaissez la frustration que peut provoquer le dépannage d’un assemblage aux pièces mécaniques complexes."},sec={{t="Au service de l’artisan",b="Ayessa vous envoie aider Riaani Nightwind à réparer un assemblage endommagé. Il est plongé dans ses entrailles, à la recherche de la cause du problème. Surpris par votre arrivée, Riaani doute qu’un voyageur sans formation puisse effectuer un travail mécanique délicat. Une fois sorti de la machine, il accepte de vous expliquer ce qu’il faut faire."},{t="Dépannage mécanique",b="Un assemblage dépend d’un montage précis et d’un calibrage minutieux. Lorsqu’il tombe en panne, son ingénieur doit s’atteler à un travail considérable. Riaani Nightwind est plongé jusqu’aux épaules dans des pièces mécaniques. Il a besoin d’une paire de mains pour rassembler des matériaux ou tester la machine sur le terrain. Écoutez ses instructions pour savoir comment aider à remettre l’assemblage inerte en état de marche."}},faq={{q="Qui est Riaani Nightwind ?",a="Riaani Nightwind est un bricoleur qui travaille sur un assemblage mécanique hors service. Il se méfie des nouveaux venus venus lui prêter main-forte, mais a besoin d’aide pour remettre la machine en marche.",al={"qui est riaani nightwind","riaani","mécanicien d’assemblages"}},{q="Qui est Ayessa ?",a="Ayessa est une associée qui envoie des voyageurs aider Riaani Nightwind à résoudre ses problèmes mécaniques. Sa recommandation le convainc d’envisager de confier une tâche à un nouveau venu.",al={"qui m’a envoyé auprès de riaani","ayessa","qui est ayessa"}},{q="Qu’est-ce que l’assemblage cassé ?",a="L’assemblage cassé est une création mécanique qui ne fonctionne plus correctement. Riaani Nightwind se trouve à l’intérieur, à la recherche des pièces et des tâches nécessaires aux réparations.",al={"qu’est-ce que l’assemblage","quelle machine riaani répare-t-il","machine cassée"}},{q="De quelle aide Riaani a-t-il besoin ?",a="Ayessa vous a envoyé aider Riaani. Il doit d’abord sortir des entrailles de l’assemblage pour vous expliquer de quelle aide il a besoin.",al={"que veut riaani que je fasse","quête de l’assemblage cassé","comment aider riaani"}},{q="Pourquoi Riaani doute-t-il de votre aide ?",a="Riaani est absorbé par son travail technique et s’impatiente lorsqu’on l’interrompt. Il considère la plupart des aventuriers comme des novices sans formation, jusqu’à ce qu’ils montrent qu’ils savent suivre des instructions mécaniques.",al={"pourquoi riaani me prend-il pour un novice","riaani est-il désagréable","dialogue de riaani"}}},fp="20,141,21.300.0,25.356.0,24.163.0,14.164.0,29.165.0,32.128.0,37.171.0"}
P.entries["quest:93738"] = {n="The Broken Construct",s="Un Sculpte-vents vous demande de raconter à Ayessa Dawnsinger ce que vous avez appris sur The Broken Construct. Les expériences de l’Ordre suprême sur la magie des esprits du vent suscitent des inquiétudes.",h="Un Sculpte-vents vous demande de raconter à Ayessa Dawnsinger ce que vous avez appris sur The Broken...",kw={"ayessa dawnsinger","belathaan","construct brisé","ordre suprême","valanaar","valennia stormfist","esprits du vent","sculpte-vents"},sec={{t="Retourner auprès d’Ayessa",b="Apportez à Ayessa Dawnsinger, à Valanaar, ce que vous avez appris. L’Ordre suprême a mis la patience des Sculpte-vents à l’épreuve avec ses expériences sur la magie des esprits du vent. Il a aussi touché à des connaissances relevant du domaine des Sculpte-vents. Ayessa peut décider de la suite."},{t="Un nom inquiétant",b="Ayessa pense que l’Ordre suprême est responsable de la défaillance de The Broken Construct. Elle connaît Belathaan comme le cousin de Valennia Stormfist et dit que sa mère était une Sculpte-vents. Son implication la déçoit. Elle a besoin de temps pour réfléchir."}},faq={{q="À qui dois-je faire mon rapport ?",a="Faites votre rapport à Ayessa Dawnsinger, à Valanaar.",al={"faire un rapport à ayessa","où faire son rapport","ayessa dawnsinger"}},{q="Pourquoi les Sculpte-vents s’inquiètent-ils au sujet de l’Ordre suprême ?",a="L’Ordre suprême a expérimenté avec la magie des esprits du vent et s’est mêlé de connaissances relevant du domaine des Sculpte-vents, bien que cela soit interdit.",al={"problèmes avec l’ordre suprême","pourquoi les sculpte-vents sont mécontents","magie du vent de l’ordre suprême"}},{q="Qu’est-il arrivé au construct ?",a="Ayessa pense que l’Ordre suprême est responsable de la défaillance de The Broken Construct.",al={"construct brisé","pourquoi le construct est brisé"}},{q="Qui est Belathaan ?",a="Belathaan est le cousin de Valennia Stormfist, et sa mère était une Sculpte-vents.",al={"belathaan","famille de belathaan","cousin de belathaan"}}},fp="20,158,16.251.0,16.239.1,23.57.0,55.140.0,31.79.0,17.76.0"}
P.entries["quest:93739"] = {n="Exploring the Horde",s="Depuis Grommash Hold, vous partez à la rencontre des chefs qui guident la Horde. Votre voyage vous mène d'Orgrimmar aux Trolls sombrelances, aux taurens et aux Réprouvés.",h="Depuis Grommash Hold, vous partez à la rencontre des chefs qui guident la Horde.",kw={"cairne sabot-de-sang","sombrelance","exploring the horde","réprouvés","grommash hold","nazgrel","orgrimmar","sylvanas coursevent","tauren","pitons-du-tonnerre","fossoyeuse","vol'jin"},ang={["faction:Horde"]="Vous rencontrez les chefs qui guident la Horde à travers Kalimdor et les Royaumes de l'est.",["race:Orc"]="Nazgrel conseille le chef de guerre Thrall à Orgrimmar et guide les jeunes guerriers orcs qui cherchent à faire leurs preuves.",["race:Tauren"]="Rencontrer le grand chef Cairne Sabot-de-Sang aux Pitons-du-Tonnerre vous mène au cœur spirituel et à la source de force des taurens.",["race:Troll"]="Parler avec le chasseur des ombres Vol'jin renforce les liens entre la tribu sombrelance et ses alliés orcs dans la Vallée des Esprits.",["race:Undead"]="Voyager jusqu'à Fossoyeuse pour rencontrer la Dame noire Sylvanas Coursevent révèle l'alliance stratégique, quoique tendue, entre les Réprouvés et la Horde de Kalimdor."},sec={{t="Ordres de Grommash Hold",b="Nazgrel vous envoie depuis Grommash Hold explorer les vastes territoires de la Horde. La forteresse se dresse au cœur d'Orgrimmar, où Nazgrel et le conseil du chef de guerre supervisent les affaires militaires. Vous quittez les canyons rouges de Durotar pour découvrir jusqu'où les peuples sous la bannière rouge sont unis."},{t="Une alliance pour survivre",b="Vous rencontrez les chefs des peuples alliés de la Horde : le chasseur des ombres Vol'jin des Trolls sombrelances, le grand chef Cairne Sabot-de-Sang des taurens et Dame Sylvanas Coursevent, reine des Réprouvés. Parler en personne à chacun vous permet de voir les liens entre Kalimdor et Lordaeron, de l'autre côté de la Grande mer, où la peste a ravagé les terres."}},faq={{q="Qu'est-ce que la quête Exploring the Horde ?",a="Vous faites votre rapport à Nazgrel dans Grommash Hold, puis voyagez à travers les territoires de la Horde pour rencontrer Vol'jin, Cairne Sabot-de-Sang et Dame Sylvanas Coursevent.",al={"qu'est-ce qu'exploring the horde","quête exploring the horde","que faire dans cette quête"}},{q="Qui est Nazgrel et où se trouve-t-il ?",a="Nazgrel est un guerrier orc et un lieutenant de confiance à Grommash Hold, dans Orgrimmar. Il conseille la Horde et guide les champions en devenir vers les commandants et les alliés répartis sur ses territoires.",al={"qui est nazgrel","où se trouve nazgrel","rôle de nazgrel"}},{q="Quels chefs devez-vous rencontrer ?",a="Vous rencontrez le chasseur des ombres Vol'jin des Trolls sombrelances, le grand chef Cairne Sabot-de-Sang des taurens à Mulgore, et Dame Sylvanas Coursevent, la reine banshee des Réprouvés à Fossoyeuse.",al={"quels chefs rencontrer","chefs à visiter","à qui parler"}},{q="Pourquoi les aventuriers doivent-ils rendre visite à chaque chef ?",a="Les peuples de la Horde sont unis par leur lutte commune pour survivre et par des pactes de fraternité. Rencontrer Vol'jin, Cairne et Sylvanas vous montre l'étendue de l'alliance, de Durotar et Mulgore jusqu'à Lordaeron.",al={"pourquoi rendre visite à tous les chefs","but des visites aux chefs de la horde","raison diplomatique"}},{q="Où se trouve chacun des chefs ?",a="Vol'jin se trouve parmi les Trolls sombrelances, dans la Vallée des Esprits d'Orgrimmar. Cairne Sabot-de-Sang tient sa cour au sommet des mesas des Pitons-du-Tonnerre, à Mulgore. Dame Sylvanas Coursevent réside dans le quartier Royal de Fossoyeuse, sous les ruines de Lordaeron.",al={"où se trouvent les chefs","emplacement des chefs","où trouver vol'jin cairne sylvanas"}},{q="Qu'est-ce que Grommash Hold ?",a="Grommash Hold est la forteresse centrale de la Vallée de la Force, à Orgrimmar. Nommée en l'honneur de Grom Hellscream, elle accueille le chef de guerre Thrall et ses conseillers, dont Nazgrel, qui supervisent les affaires de la Horde.",al={"qu'est-ce que grommash hold","où se trouve grommash hold","forteresse d'orgrimmar"}}},fp="19,164,25.281.0,23.338.0,38.134.0,39.179.0,35.195.0,52.182.0,39.242.0,22.187.0"}
P.entries["quest:93740"] = {n="Blood for Blood",s="Plusieurs novices Sculpte-vents gisent morts dans les Hautes-terres, et les Sculpte-vents soupçonnent Al’Aketh. Ayessa vous envoie au nord, dans les Plaines Aérelles, pour répondre à ces meurtres et rapporter les amulettes de prière en pierre des vents des cultistes tombés.",h="Plusieurs novices Sculpte-vents gisent morts dans les Hautes-terres, et les Sculpte-vents soupçonnent...",kw={"al’aketh","ayessa","blood for blood","cultistes","plaines aérelles","hautes-terres","sculpte-vents","amulettes de prière en pierre des vents"},sec={{t="Une sinistre découverte",b="Plusieurs novices Sculpte-vents ont été retrouvés assassinés dans les Hautes-terres. Les preuves sont rares, mais les Sculpte-vents soupçonnent les cultistes d’Al’Aketh. Leur fanatisme en fait les principaux suspects. Le credo des Sculpte-vents exige œil pour œil : ils ne laisseront donc pas ces meurtres sans réponse."},{t="L’appel aux représailles",b="Ayessa vous demande de frapper tout membre d’Al’Aketh que vous trouverez au nord, dans les Plaines Aérelles. Elle vous demande de rapporter les amulettes de prière en pierre des vents portées par les cultistes tombés, en preuve de leur mort. Les Sculpte-vents voient cette attaque comme une réponse au long fanatisme des cultistes."}},faq={{q="Qui sont les membres d’Al’Aketh ?",a="Les membres d’Al’Aketh sont des cultistes que les Sculpte-vents considèrent comme de sanglants fanatiques. Les Sculpte-vents les soupçonnent d’avoir tué des novices dans les Hautes-terres.",al={"qui sont les membres d’al’aketh","cultistes d’al’aketh","qui combat-on"}},{q="Pourquoi les Sculpte-vents veulent-ils se venger ?",a="Plusieurs novices Sculpte-vents ont été retrouvés morts dans les Hautes-terres, et les Sculpte-vents soupçonnent Al’Aketh. Leur credo exige de rendre coup pour coup.",al={"pourquoi tuer les membres d’al’aketh","novices sculpte-vents morts","pourquoi se venger"}},{q="Qui est Ayessa ?",a="Ayessa représente les Sculpte-vents. Elle dirige leurs représailles contre Al’Aketh et récupère les amulettes de prière prises aux cultistes tombés.",al={"qui est ayessa","donneur de quête","ayessa sculpte-vents"}},{q="Que sont les amulettes de prière en pierre des vents ?",a="Les cultistes d’Al’Aketh portent des amulettes de prière en pierre des vents. Ayessa vous les demande en preuve que les cultistes responsables des meurtres ont été tués.",al={"que sont les amulettes en pierre des vents","amulettes de prière","preuve de l’acte"}},{q="Où trouver les membres d’Al’Aketh ?",a="Les membres d’Al’Aketh se trouvent au nord, dans les Plaines Aérelles, où ils pratiquent leurs rites.",al={"où se trouvent les membres d’al’aketh","où se trouvent les cultistes","emplacement des plaines aérelles"}}},fp="15,228,16.279.0,22.280.0,21.138.0,44.145.0,14.144.0,37.142.0,32.94.0"}
P.entries["quest:93746"] = {n="A Firm Response",s="Ayessa Dawnsinger répond par la force à l’intrusion de l’Ordre suprême sur l’Île de Zéphras. Elle vous envoie intercepter Belathaan Brightwish sur la route au nord du Sanctuaire d’Akir, afin de clarifier les limites des Sculpte-vents.",h="Ayessa Dawnsinger répond par la force à l’intrusion de l’Ordre suprême sur l’Île de Zéphras.",kw={"a firm response","ayessa dawnsinger","belathaan brightwish","ordre suprême","living storms","sanctuaire d’akir","sculpte-vents","île de zéphras"},ang={["class:Shaman"]="En tant que chaman, vous affrontez des Living Storms au milieu de la magie élémentaire de l’air, turbulente et sauvage, qui règne sur l’Île de Zéphras.",["faction:Horde"]="En tant que membre de la Horde sur l’Île de Zéphras, vous contribuez à sécuriser ses positions et à empêcher des rivaux comme l’Ordre suprême d’empiéter sur les intérêts de vos alliés."},sec={{t="Tracer la limite",b="Les Sculpte-vents de l’Île de Zéphras n’acceptent pas la surveillance secrète de l’Ordre suprême. Leurs avertissements étant restés sans effet, Ayessa Dawnsinger fait monter la tension. Elle vous envoie intercepter Belathaan Brightwish sur la route isolée au nord du Sanctuaire d’Akir, loin des regards indiscrets de la ville."},{t="Orages sur la route",b="Belathaan Brightwish se dirige vers le nord, vers l’ancien Sanctuaire d’Akir, mais ses intentions sont obscures. Lorsque vous l’affrontez sur la route isolée, il devient hostile et des Living Storms se joignent au combat. Vaincre les élémentaires et humilier Belathaan envoie un message clair à l’Ordre suprême : les Sculpte-vents répondent aux ingérences par la force."}},faq={{q="Qui est Ayessa Dawnsinger ?",a="Ayessa Dawnsinger appartient aux Sculpte-vents, alliés de la Horde sur l’Île de Zéphras. Elle protège leur territoire et agit sans pitié contre les intrus qui se mêlent de leurs affaires.",al={"ayessa dawnsinger","qui donne une réponse ferme","ayessa"}},{q="Qui est Belathaan Brightwish ?",a="Belathaan Brightwish est lié à l’Ordre suprême. Ayessa Dawnsinger le prend pour cible afin d’intimider l’organisation après qu’on l’a aperçu se diriger seul vers le Sanctuaire d’Akir.",al={"belathaan brightwish","belthaan","qui est belathaan"}},{q="Qu’est-ce que l’Ordre suprême ?",a="L’Ordre suprême est une faction de l’Île de Zéphras dont les activités entrent en conflit avec celles des Sculpte-vents locaux. Malgré des avertissements explicites, il continue de sonder leurs affaires.",al={"ordre suprême","histoire de l’ordre suprême","qu’est-ce que l’ordre suprême"}},{q="Où se trouve le Sanctuaire d’Akir ?",a="Le Sanctuaire d’Akir se trouve au nord de la ville, sur l’Île de Zéphras. Belathaan est intercepté sur la route isolée qui y mène.",al={"sanctuaire d’akir","où se trouve le sanctuaire d’akir","sanctuaire d’akir zéphras"}},{q="Pourquoi Ayessa veut-elle que Belathaan soit vaincu plutôt que tué ?",a="Ayessa veut que Belathaan soit vaincu pour faire passer un message sans déclencher une guerre totale. Elle espère qu’il retournera auprès de ses supérieurs avec de la crainte et du respect pour les limites des Sculpte-vents.",al={"tuer belathaan","pourquoi épargner belathaan","pourquoi seulement le rosser"}},{q="Que sont les Living Storms rencontrés au cours de cette tâche ?",a="Les Living Storms sont des entités élémentaires qui apparaissent pendant l’affrontement avec Belathaan sur la route. Elles reflètent les énergies élémentaires instables de l’Île de Zéphras.",al={"living storms","que sont les living storms"}}},fx={["3180a0eb"]={q="Pourquoi Ayessa Dawnsinger veut-elle que Belathaan soit confronté ?",a="L'Ordre suprême s'est mêlé à maintes reprises des affaires des Sculpte-vents, ignorant les avertissements précédents de respecter leur territoire et leurs pratiques. Ayessa estime que les mots diplomatiques ne suffisent plus. En interceptant Belathaan sur la route et en lui donnant une sévère correction, elle espère envoyer un message sans équivoque à ses supérieurs indiquant que les Sculpte-vents feront respecter leurs frontières par la force si nécessaire.",al={"pourquoi confronter belathaan","motif d'ayessa","pourquoi envoyer un message à l'ordre suprême"}}},fp="15,209,16.292.0,18.327.1,25.168.0,28.169.0,23.169.0,36.118.0,57.176.0,56.160.0"}
P.entries["quest:93786"] = {n="A Message in Blood",s="Krom’rosh vous envoie contre la ferme humaine de Meadowsbrook. Il veut que les ouvriers agricoles soient tués pour répondre aux revendications des déserteurs sur ces terres.",h="Krom’rosh vous envoie contre la ferme humaine de Meadowsbrook.",kw={"un message dans le sang","farholde","ferme","déserteurs humains","krom’rosh","ferme de meadowsbrook","ouvriers agricoles de meadowsbrook","escarmouches"},ang={["faction:Horde"]="En tant que membre de la Horde, vous exécutez l’ordre de Krom’rosh contre les déserteurs humains qui ont revendiqué la ferme."},sec={{t="Les ouvriers agricoles",b="Krom’rosh vous indique la ferme de Meadowsbrook, au sud-ouest, de l’autre côté de la rivière. Des déserteurs humains ont revendiqué la ferme il y a quelques années, puis se sont avancés vers Farholde, le donjon de la rive orientale. Selon Krom’rosh, les escarmouches précédentes manquaient de combattants pour l’emporter. Il veut maintenant que vous perturbiez les activités de la ferme et ne laissiez aucun prisonnier."}},faq={{q="Qui me demande d’aller à Meadowsbrook ?",a="Krom’rosh vous demande d’attaquer la ferme de Meadowsbrook et d’en perturber les activités agricoles.",al={"qui m’a envoyé","tâche de krom’rosh","qui me le demande"}},{q="Pourquoi Krom’rosh veut-il que la ferme soit attaquée ?",a="Des déserteurs humains ont revendiqué la ferme et se sont étendus vers Farholde. Krom’rosh veut leur rappeler que son peuple est présent.",al={"pourquoi attaquer la ferme","pourquoi meadowsbrook","pourquoi combattre les humains"}},{q="Où se trouve la ferme de Meadowsbrook ?",a="La ferme de Meadowsbrook se trouve au sud-ouest, de l’autre côté de la rivière.",al={"où se trouve la ferme","emplacement de meadowsbrook","ferme au sud-ouest"}},{q="Qui sont les ouvriers agricoles ?",a="Les Meadowsbrook Farmhands sont les gens que Krom’rosh vous envoie tuer.",al={"qui sont les ouvriers agricoles","habitants de meadowsbrook","humains à la ferme"}},{q="Que s’est-il passé lors des escarmouches précédentes ?",a="Selon Krom’rosh, les escarmouches précédentes auraient tourné à l’avantage de son camp s’il avait eu davantage de combattants.",al={"combats précédents","pourquoi les escarmouches ont échoué","escarmouches de krom’rosh"}}},fp="18,136,13.314.0,34.73.0,44.119.0,27.50.0,22.72.0,40.98.0"}
P.entries["quest:93788"] = {n="Borrowed Blades",s="Kreza Darkthorn vous demande de prendre les haches des bûcherons au camp de bûcherons de Turner. Leurs lames fourniront les matériaux nécessaires aux armes de Rog’mar.",h="Kreza Darkthorn vous demande de prendre les haches des bûcherons au camp de bûcherons de Turner.",kw={"lames empruntées","forge","gur'dok","kreza darkthorn","bûcherons","rog’mar","camp de bûcherons de turner","armes","hache de bûcheron"},sec={{t="Au camp de bûcherons",b="Kreza Darkthorn fait tourner la forge de Rog’mar pendant que Gur'dok démonte les lames. La présence humaine au sud et le Crépuscule à l’ouest rendent la collecte de ressources difficile. On vous demande de rapporter les haches des bûcherons du camp de bûcherons de Turner, afin que leurs matériaux soient façonnés en armes."}},faq={{q="Qui veut les haches ?",a="Kreza Darkthorn, à Rog’mar, vous demande de récupérer les haches au camp de bûcherons de Turner.",al={"qui m’a envoyé","les haches de kreza","qui a besoin de lames"}},{q="Pourquoi Kreza veut-elle les haches des bûcherons ?",a="Gur'dok démontera les lames et Kreza utilisera leurs matériaux pour fabriquer des armes.",al={"pourquoi des haches","à quoi servent les haches","matériaux pour armes"}},{q="Où se trouve le camp de bûcherons de Turner ?",a="Le camp de bûcherons de Turner se trouve au sud, le long de la rivière, près du moulin.",al={"emplacement du camp de bûcherons","où sont les bûcherons","camp de turner"}},{q="Qu’est-ce qui rend la collecte de ressources difficile ?",a="La présence humaine au sud et le Crépuscule à l’ouest rendent la lutte pour les ressources difficile.",al={"pourquoi les ressources sont difficiles à obtenir","présence humaine","crépuscule à proximité"}}},fp="15,143,19.304.0,19.84.0,42.87.0,31.60.0,41.96.0"}
P.entries["quest:93791"] = {n="Speak with Belann",s="À Valanaar, les aspirants lanceurs de sorts sont envoyés rencontrer Belann Windwood. L’Ordre suprême honore la fabrication d’un focalisateur de sorts personnel, une tradition ancestrale.",h="À Valanaar, les aspirants lanceurs de sorts sont envoyés rencontrer Belann Windwood.",kw={"belann","belann windwood","ordre suprême","focalisateur de sorts","bâtons","valanaar","baguettes"},ang={["class:Mage"]="Pour un Mage, fabriquer un focalisateur de sorts personnel est un rite de passage essentiel qui rend hommage aux anciennes traditions de l’Ordre suprême."},sec={{t="Un rite de pouvoir grandissant",b="À mesure que les élèves maîtrisent mieux la magie, l’Ordre suprême recourt à une coutume ancestrale pour éprouver et renforcer leurs talents. Fabriquer leur propre focalisateur de sorts, baguette ou bâton, est l’une des traditions les plus anciennes de l’ordre. Ce rite s’adresse aux élèves qui souhaitent lier leur pouvoir grandissant à un instrument qu’ils ont façonné eux-mêmes."},{t="L’artisan de Valanaar",b="À Valanaar, les initiés sollicitent l’aide de Belann Windwood pour cet artisanat. Depuis plus d’un siècle, il forge des bâtons et des baguettes pour l’Ordre suprême. Mentor de confiance, Belann accueille les élèves dévoués et les guide dans l’artisanat et l’histoire de leurs outils magiques."}},faq={{q="Qui est Belann Windwood ?",a="Belann Windwood est un maître artisan qui vit à Valanaar. Depuis plus d’un siècle, il fabrique des bâtons et des baguettes pour les membres de l’Ordre suprême.",al={"qui est belann","belann windwood","belann"}},{q="Qu’est-ce que l’Ordre suprême ?",a="L’Ordre suprême est une ancienne organisation de praticiens. Ses traditions consistent notamment à guider les jeunes lanceurs de sorts dans la fabrication et la maîtrise de leurs propres focalisateurs de sorts.",al={"qu’est-ce que l’ordre suprême","histoire de l’ordre suprême"}},{q="Qu’est-ce qu’un focalisateur de sorts ?",a="Un focalisateur de sorts, comme une baguette ou un bâton, canalise les énergies magiques. Pour les lanceurs de sorts en formation de l’Ordre suprême, en fabriquer un est l’un des plus anciens rites de passage.",al={"qu’est-ce qu’un focalisateur de sorts","utilité d’un focalisateur de sorts"}},{q="Où se trouve Valanaar ?",a="Valanaar est le lieu où Belann Windwood a son atelier et aide les élèves de l’Ordre suprême à fabriquer des focalisateurs de sorts.",al={"où se trouve valanaar","emplacement de valanaar"}},{q="Pourquoi vous envoie-t-on parler à Belann ?",a="En tant qu’aspirant à la maîtrise de la magie, vous êtes envoyé étudier auprès de Belann, dont l’expertise s’étend sur plus d’un siècle, et commencer à façonner votre propre instrument magique.",al={"pourquoi voir belann","pourquoi fabriquer un focalisateur"}},{q="Que se passe-t-il après votre rencontre avec Belann ?",a="Lorsque vous vous présentez à Belann, à Valanaar, il vous accueille et se prépare à vous expliquer les prochaines étapes de l’assemblage de votre focalisateur de sorts.",al={"que se passe-t-il ensuite","après avoir parlé à belann"}}},fp="17,153,23.326.0,25.270.0,23.145.0,23.158.0,22.162.0,28.112.0,38.157.0,35.138.0"}
P.entries["quest:93797"] = {n="Boughs in the Wind",s="À Valanaar, Belann Windwood guide les apprentis dans l’ancien rite qui consiste à façonner un focalisateur de sorts. Ils cherchent une branche touchée par le vent près de Falaath Village, car de moins en moins d’habitants de Zephras naissent avec un don pour la magie.",h="À Valanaar, Belann Windwood guide les apprentis dans l’ancien rite qui consiste à façonner un focalisateur de...",kw={"belann windwood","boughs in the wind","falaath village","focalisateur de sorts","valanaar","sanctuaire du vent","rameau imprégné de vent","zephras"},ang={["class:Mage"]="Façonner un focalisateur de sorts à partir d’un rameau touché par le vent marque un rite précoce pour les lanceurs de sorts qui apprennent à canaliser la résonance élémentaire.",["race:Skyborne"]="Comme de moins en moins de jeunes manifestent un don pour la magie au fil des ans, façonner un focalisateur traditionnel contribue à préserver la culture ancestrale de votre peuple à Zephras."},sec={{t="Un rite de passage",b="Les jeunes lanceurs de sorts de Zephras commencent cet ancien rite lorsqu’ils manifestent un don pour la magie. À Valanaar, Belann Windwood guide les apprentis qui ramassent une branche tombée des arbres les plus anciens de la région. Les rameaux conservent des traces du vent et peuvent ainsi canaliser les sorts."},{t="Murmures au sanctuaire du vent",b="Les rameaux les plus puissants se trouvent près du sanctuaire du vent, juste au sud de Falaath Village, où les courants élémentaires se rassemblent. Selon la tradition, une branche peut choisir son lanceur de sorts, et certains disent qu’elle chante doucement à ceux qui savent manier son pouvoir. Pour les anciens comme Belann, chaque apprenti qui accomplit le rite contribue à perpétuer leur culture. De moins en moins d’habitants de Zephras naissent avec un don pour la magie au fil des ans."}},faq={{q="En quoi consiste la quête Boughs in the Wind ?",a="Les apprentis ramassent une branche tombée, touchée par le vent, pour façonner un focalisateur de sorts. Cet ancien rite contribue à préserver l’héritage magique de Zephras.",al={"qu’est-ce que boughs in the wind","quête boughs in the wind","quête du focalisateur de sorts"}},{q="Qui est Belann Windwood ?",a="Belann Windwood est un mentor de Valanaar qui guide les jeunes lanceurs de sorts lorsqu’ils façonnent leur focalisateur. Il s’inquiète de voir de moins en moins de personnes manifester un don pour la magie au fil des ans.",al={"qui est belann windwood","belann donneur de quête","belann à valanaar"}},{q="Où trouver le Rameau imprégné de vent ?",a="Les rameaux tombent des arbres les plus anciens, près du sanctuaire du vent juste au sud de Falaath Village. Belann y envoie les apprentis, car le bois ancien conserve des traces des courants élémentaires.",al={"où trouver un rameau du vent","où trouver le rameau imprégné de vent","emplacement du rameau"}},{q="Pourquoi les jeunes lanceurs de sorts créent-ils un focalisateur ?",a="Après avoir manifesté un don pour la magie, les apprentis façonnent leur propre focalisateur. Celui-ci canalise les énergies élémentaires et marque leur entrée dans un ancien rite culturel.",al={"pourquoi créer un focalisateur de sorts","rôle du focalisateur de sorts","histoire du focalisateur de sorts"}},{q="Pourquoi Belann demande-t-il si la branche vous a chanté ?",a="Selon Belann Windwood, la tradition veut qu’une branche choisisse souvent son lanceur de sorts. Un rameau adapté peut sembler chanter à quelqu’un qui perçoit les vents élémentaires.",al={"la branche choisit le lanceur","branche chantante","la branche vous choisit-elle"}},{q="Que devient la magie à Zephras ?",a="De moins en moins d’habitants de Zephras naissent avec un don naturel pour la magie au fil des ans. Belann estime qu’il est d’autant plus important de préserver les anciens rites.",al={"où se trouve zephras","la magie décline à zephras","histoire de la magie à zephras"}}},fp="18,207,17.262.0,27.396.0,37.130.0,23.174.0,41.181.0,47.153.0,46.155.0,38.147.0"}
P.entries["quest:938"] = {n="Brume",s="Sous les frondaisons ombragées de Teldrassil, Mist gît blessée, séparée de sa compagne. Elle a besoin d'un chemin sûr jusqu'à la Sentinelle Arynia Eclairciel, près d'un puits de lune.",h="Sous les frondaisons ombragées de Teldrassil, Mist gît blessée, séparée de sa compagne.",kw={"arynia eclairciel","mist","puits de lune","oracle tree","félin sabre-de-la-nuit","sentinelle","teldrassil"},ang={["class:Hunter"]="En tant que chasseur, vous reconnaissez la dévotion farouche dans le regard vif de Mist. La ramener saine et sauve auprès de sa compagne est une question de fierté.",["faction:Alliance"]="En tant que membre de l'Alliance, vous pouvez aider les sentinelles à Teldrassil et gagner la confiance des kaldorei qui défendent l'Arbre-monde.",["race:NightElf"]="En tant qu'elfe de la nuit, vous savez que le lien entre les sentinelles et les félins sabre-de-la-nuit est au cœur de votre art de la guerre et de votre savoir forestier. Ramener Mist chez elle honore cette ancienne complicité."},sec={{t="Une compagne blessée",b="Mist gît blessée dans les sous-bois de Teldrassil. Son pelage gris est marqué de profondes entailles sur le dos et le ventre. Ses yeux bleus restent vifs, et elle garde son calme au lieu de se comporter comme une bête féroce. Elle cherche conseil et protection auprès des voyageurs bienveillants."},{t="Le prix d'une embuscade",b="La Sentinelle Arynia Eclairciel et Mist patrouillaient près de l'Oracle Tree lorsque des sorcières leur tendirent une embuscade et les séparèrent. Arynia crut que sa compagne bien-aimée était morte. En deuil, elle se retira près d'un puits de lune, espérant que Mist avait survécu."}},faq={{q="Qui est Mist ?",a="Mist est la fidèle compagne féline sabre-de-la-nuit grise de la Sentinelle Arynia Eclairciel. Blessée dans les forêts de Teldrassil, elle a été séparée d'Arynia lors d'une embuscade.",al={"chat mist","qui est mist","qui est le félin sabre-de-la-nuit"}},{q="Qui a blessé Mist ?",a="Des sorcières ont tendu une embuscade à Mist et à la Sentinelle Arynia Eclairciel dans les bois de Teldrassil. Elles ont séparé les deux compagnes et tailladé le dos et le ventre de Mist.",al={"qui a blessé mist","pourquoi mist saigne","embuscade des sorcières contre mist"}},{q="Où faut-il escorter Mist ?",a="Escortez Mist en lieu sûr jusqu'à la Sentinelle Arynia Eclairciel, qui attend près d'un puits de lune, non loin de l'Oracle Tree.",al={"où emmener mist","rendre la quête mist","destination de mist"}},{q="Qui est la Sentinelle Arynia Eclairciel ?",a="La Sentinelle Arynia Eclairciel est une sentinelle elfe de la nuit et la compagne de Mist. Elle attend près d'un puits de lune, non loin de l'Oracle Tree.",al={"arynia eclairciel","eclairciel","maîtresse de mist"}},{q="Pourquoi les sentinelles elfes de la nuit sont-elles liées aux félins sabre-de-la-nuit ?",a="Depuis des millénaires, les sentinelles elfes de la nuit combattent aux côtés des grands félins de Kalimdor. Les félins sabre-de-la-nuit sont de farouches partenaires lors des escarmouches, des éclaireurs sous les frondaisons ombragées et des compagnons de confiance pour la vie.",al={"compagnons félins des elfes de la nuit","félins sabre-de-la-nuit des sentinelles","pourquoi des félins sabre-de-la-nuit"}},{q="Où se trouve l'Oracle Tree par rapport à ce sauvetage ?",a="L'Oracle Tree se dresse au nord-ouest de Teldrassil. Un puits de lune voisin fournit des eaux sacrées, et la Sentinelle Arynia Eclairciel y veille à ses devoirs.",al={"emplacement de l'oracle tree","puits de lune mist"}}},fx={["1795c253"]={q="Pourquoi Mist a-t-elle besoin de votre aide ?",a="Mist est gravement blessée, avec des lacérations profondes sur le dos et le ventre, séparée de sa compagne la Sentinelle Arynia Eclairciel. Affaiblie et bloquée seule dans la forêt, elle ne peut pas naviguer en toute sécurité à travers les périls de Teldrassil pour atteindre la sécurité du puits de lune sans votre protection.",al={"pourquoi aider mist","motif de mist","pourquoi mist a-t-elle besoin d'une escorte"}},["94db0917"]={q="Pourquoi Mist compte-t-elle sur vous plutôt que de se sauver elle-même ?",a="Mist est trop gravement blessée pour se frayer un chemin à travers les bois hostiles ou faire le long voyage de retour sans aide. Étant une bête séparée de sa Sentinelle, elle n'a aucun allié ou garde à proximité vers qui se tourner ; lorsque vous la rencontrez par hasard, elle vous reconnaît comme une présence amicale et accorde sa confiance en votre capacité à la guider et à la protéger.",al={"pourquoi moi mist","pourquoi mist ne peut-elle pas s'échapper seule","pourquoi mist vous suit-elle"}}},fp="4,154,19.257.0,19.238.1,12.145.0,17.135.0,30.101.0,35.120.0,50.191.0,52.150.0"}
P.entries["quest:93835"] = {n="Confront Lorthuna",s="Un mage blessé vous demande de suivre Ayessa Dawnsinger et Elaadrin Evengale à travers un portail jusqu’aux Flèches Rohashi. Là-bas, ils affrontent la grande prêtresse Lorthuna et ont besoin de votre aide.",h="Un mage blessé vous demande de suivre Ayessa Dawnsinger et Elaadrin Evengale à travers un portail jusqu’aux...",kw={"ayessa dawnsinger","elaadrin evengale","ordre suprême","lorthuna","portail","flèches rohashi","valennia","zephras"},sec={{t="À travers le portail",b="Lorthuna s’est enfuie par un portail vers les Flèches Rohashi, au-dessus de vous. Ayessa Dawnsinger et Elaadrin Evengale l’ont suivie il y a quelques instants, mais leur compagnon est trop grièvement blessé pour les accompagner. Rejoignez les deux mages à travers le portail tandis qu’ils affrontent la grande prêtresse."},{t="Après l’affrontement",b="Les mages restants ont été envoyés pour aider Valennia et ses forces à s’échapper. Valennia se repose à la résidence du haut ancien Shadowsong. Ansirem est retourné en Azeroth après avoir discuté des prochaines étapes de l’Ordre suprême. Zephras a survécu à cette journée, mais il reste dangereusement vulnérable, et il faut préparer la suite."}},faq={{q="Qui me demande de poursuivre Lorthuna ?",a="Un mage blessé vous demande de suivre Ayessa Dawnsinger et Elaadrin Evengale à travers le portail pour les aider à affronter la grande prêtresse Lorthuna.",al={"qui m’a envoyé","mage blessé","qui a besoin d’aide"}},{q="Où est allée Lorthuna ?",a="Lorthuna s’est enfuie par un portail vers les Flèches Rohashi, au-dessus de vous.",al={"où est lorthuna","portail de lorthuna","où s’est-elle enfuie"}},{q="Qui est parti à la poursuite de Lorthuna ?",a="Ayessa Dawnsinger et Elaadrin Evengale ont traversé le portail à la poursuite de Lorthuna.",al={"ayessa et elaadrin","qui l’a suivie","qui est là-haut"}},{q="Pourquoi le mage blessé ne peut-il pas les accompagner ?",a="Le mage a encaissé trop de coups et doit rester en arrière.",al={"pourquoi suis-je seul","mage trop blessé","pourquoi rester en arrière"}},{q="Où se trouve Valennia ?",a="Valennia se repose à la résidence du haut ancien Shadowsong après que les mages restants l’ont aidée, elle et ses forces, à s’échapper.",al={"emplacement de valennia","où est-elle allée","valennia est en sécurité"}},{q="Qu’est-ce qui est en jeu à présent ?",a="Zephras est dangereusement vulnérable, et l’Ordre suprême doit préparer la suite.",al={"zephras vulnérable","qu’est-il arrivé à zephras","suite de l’ordre suprême"}}},fp="17,176,18.239.0,15.311.1,38.137.0,22.62.0,24.79.0,40.49.0,18.116.0,20.84.0"}
P.entries["quest:93836"] = {n="The Fate of Zephras",s="Après la chute de Lorthuna, la nouvelle du danger parvient à Valanaar. Les protections de l’Île de Zéphras ont cédé, et Ayessa propose de partir pour Azeroth. Le grand aîné Talaanis Shadowsong doit apprendre ce qui s’est passé.",h="Après la chute de Lorthuna, la nouvelle du danger parvient à Valanaar.",kw={"al'akir","ayessa","the fate of zephras","lorthuna","muln","sanctuaire d’akir","talaanis shadowsong","valanaar","île de zéphras"},ang={["class:Shaman"]="En tant que chaman, vous savez que le domaine élémentaire du Seigneur du Vent Al'Akir entoure Zéphras. Les anciennes protections ont disparu, et l’île est désormais exposée.",["race:Skyborne"]="En tant que Skyborne de l’Île de Zéphras, vous faites face à la perte des protections et à la menace d’Al'Akir. Votre peuple cherche désormais au-delà de son foyer flottant un moyen de le protéger."},sec={{t="Une victoire précaire",b="Lorthuna est tombée après la bataille au-dessus du Sanctuaire d’Akir. Mais l’Île de Zéphras a payé cher cette victoire. Ses anciennes protections, qui la dissimulaient à Al'Akir, se sont effondrées. Le sanctuaire flottant est désormais exposé dans le domaine du Seigneur du Vent. Un messager traverse l’île pour porter la nouvelle à Valanaar."},{t="La nouvelle parvient à Valanaar",b="Le grand aîné Talaanis Shadowsong apprend la mort de Lorthuna et la chute des protections. Il découvre aussi qu’Ayessa compte mener une expédition en Azeroth. Leur voile magique ayant disparu, les insulaires cherchent hors de leur foyer un moyen de le protéger. Shadowsong met en balance la peur et l’espoir. Al'Akir est une terrible menace, mais les dieux élémentaires agissent sur de vastes échelles de temps. Les insulaires pourraient ainsi disposer d’un temps précieux pour agir."}},faq={{q="De quoi parle la quête The Fate of Zephras ?",a="Lorthuna est tombée au Sanctuaire d’Akir, et la nouvelle du danger est portée à Valanaar. Les protections de l’île ont cédé, et Ayessa propose une expédition en Azeroth. Le grand aîné Talaanis Shadowsong reçoit la nouvelle.",al={"quête the fate of zephras","que devient zephras","que se passe-t-il dans the fate of zephras"}},{q="Pourquoi l’Île de Zéphras est-elle menacée par Al'Akir ?",a="L’Île de Zéphras se trouve dans le domaine élémentaire d’Al'Akir, le Seigneur du Vent. D’anciennes protections dissimulaient autrefois le sanctuaire à son regard. Elles ont disparu, laissant l’île exposée si Al'Akir venait à déchaîner sa colère contre elle.",al={"pourquoi zephras est-elle menacée","pourquoi attaquer zephras","menace élémentaire contre zephras"}},{q="Qui est Talaanis Shadowsong ?",a="Talaanis Shadowsong est le grand aîné des Skyborne à Valanaar, sur l’Île de Zéphras. Il veille au gouvernement et à la survie de son peuple, et reçoit les rapports sur les menaces et les choix auxquels leur foyer est confronté.",al={"qui est talaanis shadowsong","grand aîné shadowsong","où se trouve talaanis shadowsong"}},{q="Quel est le plan d’Ayessa ?",a="Ayessa prévoit de mener une expédition de l’Île de Zéphras vers Azeroth. Elle cherche des réponses et des alliés au-delà de leur domaine pour aider à protéger son peuple contre Al'Akir.",al={"qui est ayessa","plan d’ayessa","que fait ayessa"}},{q="Qui était Lorthuna et que lui est-il arrivé ?",a="Lorthuna dirigeait le culte sur l’Île de Zéphras. Elle a été tuée au-dessus du Sanctuaire d’Akir, mettant fin à la direction du culte au moment où les protections de l’île s’effondraient.",al={"qui est lorthuna","cheffe de culte lorthuna","qu’est-il arrivé à lorthuna"}},{q="Qui est Muln ?",a="Muln est un conseiller ou un érudit qui connaît les seigneurs élémentaires. Il a averti les défenseurs de Zéphras du grand pouvoir d’Al'Akir et du danger qu’il représente, et a confirmé leur vulnérabilité sans dissimulation magique.",al={"qui est muln","histoire de muln"}}},fp="19,190,20.293.0,20.417.1,44.222.0,43.209.0,27.189.0,22.154.0,42.148.0,12.196.0"}
P.entries["quest:93926"] = {n="The Western Watch",s="À l’avant-poste au sud-ouest du village, les sectateurs pressent les défenseurs, et les dirigeants locaux les rappellent. Ils jugent que la tour coûte trop cher à défendre et se tournent vers la protection du village.",h="À l’avant-poste au sud-ouest du village, les sectateurs pressent les défenseurs, et les dirigeants locaux les...",kw={"secte","pacificateur vaaniel","pacificateurs","lanceurs de sorts des tempêtes","the western watch","tour de guet","tour de guet occidentale"},sec={{t="Un avant-poste coûteux",b="La tour de guet occidentale garde la frontière au sud-ouest du village. Les sectateurs ont repris leur assaut, et les dirigeants locaux décident que ce poste isolé coûte trop de vies à défendre. Ils préparent donc des ordres pour rappeler les pacificateurs. Ils espèrent épargner des vies et rassembler tous les défenseurs afin de protéger le village et ses habitants."},{t="Trop tard pour battre en retraite",b="Le Pacificateur Vaaniel commandait la garnison de The Western Watch. L’ordre de repli est arrivé trop tard. Les lanceurs de sorts sectateurs, maîtres des tempêtes, avaient envahi la tour avant que les messagers ne l’atteignent. Vaaniel et sa garnison gisaient morts parmi les pierres calcinées et les brûlures de foudre."}},faq={{q="Qui est le Pacificateur Vaaniel ?",a="Le Pacificateur Vaaniel commande les pacificateurs de la tour de guet occidentale. Les sectateurs attaquent, et on vous envoie le retrouver et lui dire de ramener rapidement sa garnison au village.",al={"qui est vaaniel","histoire de vaaniel","pacificateur vaaniel"}},{q="Pourquoi les pacificateurs ont-ils reçu l’ordre d’abandonner la tour de guet ?",a="Les dirigeants locaux ont ordonné aux pacificateurs de partir, car les assauts des sectateurs coûtaient trop de vies. Ils veulent rassembler les défenseurs au village pour protéger ses habitants.",al={"pourquoi abandonner la tour","pourquoi quitter la tour de guet","ordre de the western watch"}},{q="Qu’est-ce qui a tué le Pacificateur Vaaniel ?",a="Des lanceurs de sorts sectateurs, maîtres des tempêtes, ont tué le Pacificateur Vaaniel. La foudre et la magie élémentaire ont laissé des brûlures et des traces de feu sur lui et les défenseurs de la tour.",al={"comment vaaniel est-il mort","qui a tué vaaniel","qu’est-ce qui a tué le pacificateur"}},{q="Qui a attaqué la tour de guet occidentale ?",a="Une secte hostile a attaqué la tour de guet occidentale avec une magie des tempêtes dévastatrice. Les commandants locaux ignorent pourquoi la secte veut la tour, mais l’attaque menace les villages voisins.",al={"qui attaque la tour","attaque sectatrice de la tour occidentale","quelle est cette secte"}},{q="Où se trouve la tour de guet occidentale ?",a="La tour de guet occidentale se dresse au sud-ouest du village local et garde les accès occidentaux. Son isolement l’a rendue vulnérable aux assauts des sectateurs.",al={"où se trouve la tour de guet","emplacement de la tour de guet occidentale"}},{q="Qu’est-il arrivé à la garnison de la tour ?",a="La tour de guet était déjà tombée lorsque les messagers sont arrivés avec l’ordre d’évacuation. Les lanceurs de sorts sectateurs ont tué le Pacificateur Vaaniel et les autres défenseurs peu avant que des renforts ne puissent les atteindre.",al={"que se passe-t-il à la tour","sort de la tour de guet","des pacificateurs ont-ils survécu"}}},fp="17,183,16.329.0,19.264.1,27.189.0,60.173.0,32.152.0,36.180.0,40.148.0,43.184.0"}
P.entries["quest:93927"] = {n="A Last Request",s="Sur Zephras, un gardien de la paix tombé au combat porte un message qui pourrait révéler ses derniers instants. Sa note ensanglantée indique le devoir qu'il n'a pas pu accomplir.",h="Sur Zephras, un gardien de la paix tombé au combat porte un message qui pourrait révéler ses derniers...",kw={"a last request","note ensanglantée","gardien de la paix mort","gardien de la paix","note du gardien de la paix"},sec={{t="Une sinistre découverte",b="Vous trouvez un gardien de la paix mort dans les champs, une note ensanglantée entre les mains. En l'examinant, la note lui échappe. Sur Zephras, les gardiens de la paix risquent leur vie pour maintenir l'ordre. Ses derniers mots pourraient révéler ce qui lui est arrivé."},{t="Le dernier message",b="Le parchemin ensanglanté contient les dernières supplications ou instructions du gardien de la paix. Celui qui l'a tué a laissé son devoir inachevé. Lisez les indices et achevez sa dernière mission. La note indique la voie à suivre pour répondre à son dernier appel."}},faq={{q="Qui est le gardien de la paix mort ?",a="Lorsque vous le trouvez, l'identité du gardien de la paix tombé au combat est inconnue. Il maintenait l'ordre, et son devoir s'est achevé dans la violence. Il ne reste entre ses mains qu'un message urgent.",al={"qui est le gardien de la paix mort","gardien de la paix mort","identité du gardien de la paix"}},{q="Que dit la note ensanglantée ?",a="La note relate le dernier récit du gardien de la paix. Le culte a pris son poste par surprise. Raani ne l'a pas vu venir, Arvensus a reçu un coup d'épée dans le ventre, et un éclair a foudroyé le rédacteur. Laissé pour mort, il pensait que ses blessures achèveraient ce que le culte avait commencé.",al={"qu'est-ce que la note ensanglantée","que dit la note","note du gardien de la paix"}},{q="Comment découvre-t-on cette demande ?",a="Vous trouvez le corps du gardien de la paix dans les champs et l'examinez. La note ensanglantée qu'il tient contient ses dernières supplications.",al={"comment commencer a last request","où trouver a last request"}},{q="Qu'est-il arrivé au gardien de la paix ?",a="Le culte a tendu une embuscade au poste du gardien de la paix sans prévenir. Ses compagnons sont tombés, et un éclair l'a frappé, le laissant pour mort. Il a vécu assez longtemps pour relater les événements sur la note retrouvée entre ses mains.",al={"pourquoi le gardien de la paix a-t-il été tué","qui a tué le gardien de la paix"}},{q="Quelle est la dernière demande du gardien de la paix ?",a="Le gardien de la paix est mort avant d'avoir pu achever sa mission ou transmettre son message. Vous pouvez récupérer et lire sa note ensanglantée, déchiffrer ses dernières instructions et exaucer son dernier souhait.",al={"quelle est la demande du gardien de la paix","objectif de la dernière demande"}},{q="Quel est le rôle des gardiens de la paix ?",a="Les gardiens de la paix protègent les campements et les routes, y maintiennent l'ordre et les défendent contre les dangers. Quand l'un d'eux tombe au combat, ses tâches restent inachevées et ses alliés sans avertissement, à moins que quelqu'un ne récupère son rapport final.",al={"qui sont les gardiens de la paix","histoire des gardiens de la paix"}}},fp="14,146,16.225.0,17.216.0,28.153.0,35.249.0,31.111.0,33.207.0,39.189.0,32.219.0"}
P.entries["quest:93948"] = {n="Deliver the Signet",s="Un voyageur rapporte la Chevalière de la famille Chantelombre à Talaanis Chantelombre, grand aîné de Valanaar. Son retour confirme la mort de son neveu sur l’Île de Zéphras, et Talaanis oriente le voyageur vers les pacificateurs locaux.",h="Un voyageur rapporte la Chevalière de la famille Chantelombre à Talaanis Chantelombre, grand aîné de Valanaar.",kw={"deliver the signet","chevalière de la famille chantelombre","shen'dorei","talaanis chantelombre","valanaar","valennia stormfist","île de zéphras"},ang={["race:NightElf"]="En tant qu’Elfe de la nuit, le nom Chantelombre porte une longue histoire parmi les lignées elfiques. Sur l’Île de Zéphras, le grand aîné Talaanis et les shen'dorei locaux font face à leurs propres difficultés."},sec={{t="Une sombre mission",b="Un voyageur rapporte à Valanaar la Chevalière de la famille Chantelombre, retrouvée dans une tour isolée. Ce sinistre gage est destiné à Talaanis Chantelombre, le grand aîné de l’Île de Zéphras. Son peuple l’aime, bien que les épreuves pèsent sur la colonie. L’anneau confirme la mort de son neveu, et Talaanis reçoit l’héritage familial avec des condoléances."},{t="Deuil et devoir à Valanaar",b="À Valanaar, le grand aîné Talaanis Chantelombre remercie le voyageur d’avoir rapporté la chevalière, bien que le chagrin l’accable. Il reconnaît le talent du voyageur et l’oriente vers la capitaine Valennia Stormfist, qui dirige les pacificateurs de Valanaar. La colonie fait face à des circonstances difficiles et à des pressions croissantes. Ses protecteurs accueillent les bras vaillants."}},faq={{q="Qui est Talaanis Chantelombre ?",a="Talaanis Chantelombre est le grand aîné de l’Île de Zéphras. Sa communauté le respecte et l’aime, et la chevalière rapportée confirme la mort de son neveu.",al={"qui est talaanis","grand aîné talaanis","histoire de talaanis chantelombre"}},{q="Qu’est-ce que la Chevalière de la famille Chantelombre ?",a="La Chevalière de la famille Chantelombre est un anneau familial retrouvé dans une tour. Son retour à Talaanis Chantelombre confirme la mort de son neveu.",al={"qu’est-ce qu’une chevalière","anneau du neveu","chevalière chantelombre"}},{q="Où se trouve Valanaar ?",a="Valanaar est une colonie de l’Île de Zéphras. Le grand aîné Talaanis Chantelombre y réside, et la capitaine Valennia Stormfist dirige ses pacificateurs.",al={"où se trouve valanaar","colonie de valanaar","lieu de résidence de talaanis"}},{q="Qui est Valennia Stormfist ?",a="Valennia Stormfist dirige les pacificateurs de Valanaar. Le grand aîné Talaanis envoie les voyageurs capables lui parler, car la colonie a besoin d’aide.",al={"qui est valennia stormfist","capitaine valennia","capitaine des pacificateurs de valanaar"}},{q="Qui sont les shen'dorei dont parle Talaanis ?",a="Talaanis appelle shen'dorei les jeunes voyageurs capables qui descendent des hautes terres, un nom qui reflète la présence et l’héritage des elfes sur l’Île de Zéphras.",al={"qui sont les shen'dorei","shen'dorei des hautes terres"}},{q="Qu’est-il arrivé au neveu de Talaanis Chantelombre ?",a="Le neveu de Talaanis est mort dans une tour, où la chevalière familiale a été perdue. Rapporter l’anneau à Valanaar apprend au grand aîné la mort de son neveu.",al={"qu’est-il arrivé au neveu de talaanis","comment le neveu est-il mort"}}},fp="18,224,15.334.0,26.329.0,27.145.0,37.142.0,26.140.0,26.153.0,45.151.0,46.143.0"}
P.entries["quest:93949"] = {n="Bugged",s="Bugged est une quête à Valanaar où l'afflux saisonnier d'insectes des basses-terres s'avère être un complot d'espionnage. Les mages de l'Ordre suprême ont découvert que des sectateurs locaux tissent des charmes d'écoute sur des skyhoppers pour espionner la colonie, ce qui nécessite une campagne d'extermination pour éliminer ces nuisibles enchantés.",h="Bugged est une quête à Valanaar où l'afflux saisonnier d'insectes des basses-terres s'avère être un complot...",kw={"bugged","secte","skyhoppers enchantés","ordre suprême","sort d'écoute","skyhoppers","valanaar"},ang={["class:Mage"]="Les mages de l’Ordre suprême trouvent des charmes d’écoute sur des skyhoppers ordinaires. L’essaim saisonnier devient une menace pour Valanaar."},sec={{t="Des espions dans l'essaim",b="Pendant la saison des skyhoppers dans les basses-terres, des essaims d'insectes indigènes déferlent autour de la cité de Valanaar. Bien que généralement considérés comme un simple désagrément saisonnier, une inspection menée par les mages de l'Ordre suprême a révélé que plusieurs spécimens abattus portaient des enchantements d'écoute sophistiqués. Une secte locale a militarisé l'essaim d'insectes, transformant des nuisibles ordinaires des basses-terres en outils de surveillance discrets afin d'écouter aux portes de la cité."},{t="Purifier l'atmosphère",b="Comme les skyhoppers enchantés semblent impossibles à distinguer de leurs congénères ordinaires, les protecteurs de Valanaar sont contraints d'abattre les essaims sans distinction. Éradiquer ces insectes prive la secte hostile de tout accès à des renseignements cruciaux, interrompant la surveillance magique et renforçant les défenses de la cité contre la subversion interne."}},faq={{q="Que sont les skyhoppers ?",a="Les skyhoppers sont des nuisibles ailés originaires des basses-terres entourant Valanaar qui pullulent en grand nombre durant leur poussée saisonnière.",al={"que sont les skyhoppers","insecte skyhopper"}},{q="Qui a enchanté les insectes ?",a="Des sectateurs locaux sont soupçonnés d'avoir capturé des skyhoppers et de leur avoir apposé des sorts magiques d'écoute pour espionner la colonie.",al={"qui a enchanté les insectes","insectes espions de la secte","qui espionne à valanaar"}},{q="Comment savoir quels skyhoppers sont enchantés ?",a="Les skyhoppers enchantés semblent identiques aux insectes ordinaires à l'œil nu. Ce n'est qu'en exterminant les essaims que les espions imprégnés de magie peuvent être démasqués et éliminés.",al={"comment reconnaître les skyhoppers enchantés","quels insectes sont enchantés"}},{q="Où cela se déroule-t-il ?",a="L'infestation et l'espionnage ont lieu autour de Valanaar, une cité aérienne où des essaims saisonniers s'élèvent depuis les basses-terres adjacentes.",al={"où se trouve la quête bugged","insectes de valanaar"}},{q="Quel genre d'enchantement a été placé sur les skyhoppers ?",a="Les mages de l'Ordre suprême ont inspecté des insectes abattus et ont détecté un sort d'écoute spécialisé lié à eux, convertissant de fait ces créatures en outils de surveillance itinérants.",al={"quel sort est placé sur les insectes","enchantement de skyhopper"}},{q="Pourquoi tous les skyhoppers doivent-ils être exterminés ?",a="Comme les skyhoppers enchantés ne peuvent être distingués visuellement des nuisibles ordinaires, nettoyer l'essaim est nécessaire pour purger le réseau de postes d'écoute magiques de la secte et protéger Valanaar.",al={"pourquoi tuer les skyhoppers","objectif de la quête bugged"}}},fp="6,188,26.244.0,16.206.0,20.124.0,26.96.0,47.121.0,27.115.0,54.115.0,50.165.0"}
P.entries["quest:93951"] = {n="A Little Beauty",s="Dans les Hautes-terres de Shen’dar, les Skyborne ramassent du duvet d’hippogriffe près de Zéphras. Ses plumes éclatantes apportent beauté et petites joies au village dans les moments difficiles.",h="Dans les Hautes-terres de Shen’dar, les Skyborne ramassent du duvet d’hippogriffe près de Zéphras.",kw={"a little beauty","duvet","plumes","hippogriffe","plumage","hautes-terres de shen’dar","skyborne","zéphras"},ang={["race:Skyborne"]="En tant que Skyborne, vous pouvez ramasser du duvet d’hippogriffe éclatant pour orner vos cheveux de plumes douces. Cette coutume apporte de petites joies à Zéphras malgré les épreuves."},sec={{t="Plumes des Hautes-terres",b="Les hippogriffes sauvages nichent sur l’Île de Zéphras, au sud-ouest du village des Hautes-terres de Shen’dar. Ils défendent leur territoire et peuvent importuner les voyageurs des environs. Pourtant, ils perdent un duvet éclatant et doux comme la soie, que les Skyborne ramassent pour en faire des ornements de cheveux."},{t="La joie des petites choses",b="Pour l’artisan de Zéphras, ramasser des plumes pour les cheveux relève de bien plus que de la vanité. Même dans les moments difficiles, partager de petites joies avec les autres aide à garder le moral de la communauté. La beauté donne aux villageois chaque jour une raison de célébrer."}},faq={{q="Pourquoi ramasse-t-on des plumes d’hippogriffe ?",a="Les Skyborne ramassent le duvet des hippogriffes sauvages pour en faire des ornements de cheveux. Les plumes éclatantes et douces comme la soie sont tombées des oiseaux, qui peuvent importuner les voyageurs près du village.",al={"pourquoi ramasser des plumes","à quoi servent les plumes","utilité des plumes"}},{q="Qu’est-ce que Zéphras ?",a="Zéphras est l’île où vivent les Skyborne. Son artisan confectionne des ornements de cheveux avec les plumes ramassées pour apporter bonheur et légèreté aux habitants.",al={"qui est zéphras","quelle est cette ville","où cela se passe-t-il"}},{q="Où nichent les hippogriffes ?",a="Les hippogriffes sauvages nichent au sud-ouest du village des Hautes-terres de Shen’dar. Ils défendent leur territoire contre les visiteurs indésirables.",al={"où sont les nids","où sont les hippogriffes","emplacement des hautes-terres de shen’dar"}},{q="Pourquoi les petits luxes comme les ornements de cheveux sont-ils importants en ces temps difficiles ?",a="L’artisan estime que les petites joies et la beauté comptent, surtout dans les moments difficiles. Apporter du bonheur aux autres en vaut la peine.",al={"les plumes sont-elles importantes","pourquoi des ornements de cheveux","vanité futile"}},{q="Les hippogriffes sont-ils hostiles aux visiteurs ?",a="Les hippogriffes sauvages au sud-ouest du village défendent leurs nids contre les intrus. Ramasser leurs plumes tombées peut être dangereux pour les voyageurs imprudents.",al={"pourquoi les hippogriffes sont-ils dangereux","les hippogriffes sont-ils sauvages"}},{q="Les Skyborne ont-ils l’habitude de se décorer les cheveux avec des plumes ?",a="Oui, de nombreux Skyborne tressent des plumes éclatantes dans leurs cheveux. Le duvet d’hippogriffe est particulièrement doux et convient parfaitement à ces ornements.",al={"plumes des skyborne","les skyborne portent-ils des plumes"}}},fp="15,157,23.241.0,27.222.0,44.173.0,16.159.0,30.152.0,74.139.0,40.161.0,59.131.0"}
P.entries["quest:93958"] = {n="The Inner Sanctum",s="Au Sanctuaire d’Akir, l’assaut de Valennia Stormfist est tombé dans le silence. Ses troupes ont atteint la salle la plus profonde au terme de violents combats, et leurs alliés à l’extérieur craignent pour ceux qui s’y trouvent.",h="Au Sanctuaire d’Akir, l’assaut de Valennia Stormfist est tombé dans le silence.",kw={"sanctuaire intérieur","sanctuaire d’akir","stormfist","the inner sanctum","valennia","valennia stormfist"},sec={{t="Un silence soudain",b="Après un assaut acharné, Valennia Stormfist a mené son détachement dans le sanctuaire intérieur du Sanctuaire d’Akir. Des combats féroces et désespérés résonnaient au fond des salles. Puis le bruit s’est arrêté sans prévenir. À l’extérieur, les alliés qui attendent ne peuvent que craindre le pire."},{t="Le prix de la brèche",b="Valennia Stormfist est retrouvée grièvement blessée dans le sanctuaire silencieux. Après la bataille, le sort de son avant-garde reste incertain."}},faq={{q="Qui est Valennia Stormfist ?",a="Valennia Stormfist commande l’assaut dans les profondeurs du Sanctuaire d’Akir. Elle a mené ses forces par la brèche jusqu’au sanctuaire intérieur, où les combats ont bientôt cessé.",al={"qui est valennia","qui est valennia stormfist","valennia"}},{q="Qu’est-ce que le Sanctuaire d’Akir ?",a="Le Sanctuaire d’Akir abrite un sanctuaire intérieur désormais assiégé. Les troupes de Valennia ont percé ses défenses au prix de violents combats, faisant du sanctuaire le cœur d’un affrontement meurtrier.",al={"qu’est-ce que le sanctuaire d’akir","histoire du sanctuaire d’akir","sanctuaire d’akir"}},{q="Qu’est-il arrivé aux forces de Valennia à l’intérieur ?",a="De violents combats ont résonné à l’intérieur après la brèche, puis se sont arrêtés d’un seul coup. Ce silence fait craindre aux alliés à l’extérieur que l’avant-garde de Valennia ait été submergée ou tuée.",al={"pourquoi est-ce silencieux","qu’est-il arrivé aux forces de valennia","soldats de valennia"}},{q="Valennia Stormfist est-elle toujours en vie ?",a="Valennia Stormfist survit à l’assaut, grièvement blessée dans le sanctuaire intérieur du Sanctuaire d’Akir après la fin des combats.",al={"valennia est-elle en vie","valennia est-elle morte","sort de valennia"}},{q="Quel est l’objectif dans le sanctuaire intérieur ?",a="Le sanctuaire intérieur est la salle la plus profonde du Sanctuaire d’Akir. Vous êtes envoyé seul pour évaluer la situation après la bataille et retrouver Valennia ainsi que les éventuels combattants survivants.",al={"qu’est-ce que le sanctuaire intérieur","objectif de la quête du sanctuaire intérieur"}},{q="Qui vous envoie dans le sanctuaire intérieur ?",a="Un allié posté à l’arrière, à l’extérieur du sanctuaire intérieur, vous y envoie. Il tient le périmètre et veille sur vous pendant que vous rejoignez l’avant-garde de Valennia.",al={"qui vous envoie auprès de valennia","donneur de quête du sanctuaire intérieur"}}},fp="17,175,16.262.0,22.139.1,26.177.0,27.173.0,42.173.0,34.123.0,47.158.0,37.156.0"}
P.entries["quest:93963"] = {n="Exploring the Alliance",s="Au Donjon de Hurlevent, vous partez à la rencontre des dirigeants de Forgefer et de Darnassus. Leurs terres vous révèlent l’étendue de l’Alliance avant que vous ne preniez la route de la Marche de l’Ouest.",h="Au Donjon de Hurlevent, vous partez à la rencontre des dirigeants de Forgefer et de Darnassus.",kw={"dalaran","darnassus","exploring the alliance","grand bricoleur mekkatorque","forgefer","magni barbe-de-bronze","randal emerson","donjon de hurlevent","tyrande murmevent","marche de l’ouest"},ang={["faction:Alliance"]="Nouvel arrivant dans l’Alliance, vous visitez ses principaux bastions et rencontrez les dirigeants qui préservent le pacte.",["race:Skyborne"]="Invité Skyborne sur Azeroth, vous êtes encouragé à découvrir les nations alliées qui vous offrent refuge tandis que votre ordre se prépare à s’établir à Dalaran."},sec={{t="Une visite des terres alliées",b="Randal Emerson, un intendant de l’antichambre sud du Donjon de Hurlevent, vous envoie au-delà de la capitale humaine. Tout juste arrivé sur Azeroth, vous êtes invité à découvrir par vous-même les peuples alliés de l’Alliance. Vous quittez le donjon pour en apprendre davantage sur les cultures, les traditions et la puissance de ceux qui soutiennent Hurlevent."},{t="Audiences auprès des hauts dirigeants",b="Votre périple vous mène par terre et par mer à la rencontre des dirigeants de l’Alliance. À Forgefer, vous rencontrez le Roi Magni Barbe-de-Bronze dans les salles de la montagne, ainsi que le Grand bricoleur Gelbin Mekkanivelle, chef des gnomes déplacés. À Darnassus, au sommet de Teldrassil, vous rencontrez la Grande prêtresse Tyrande Murmevent. Leurs cités et leurs peuples révèlent les liens entre humains, nains, gnomes et elfes de la nuit."},{t="Un monde qui a besoin d’aide",b="Après ce long périple, vous retournez à Hurlevent. Mieux connaître Azeroth vous aide à soutenir votre propre peuple, tandis que votre ordre se prépare à s’établir à Dalaran. Pour l’heure, les territoires en difficulté près de la capitale ont besoin d’aide, à commencer par les terres agricoles malmenées de la Marche de l’Ouest."}},faq={{q="Qu’est-ce que la quête Exploring the Alliance ?",a="Vous parcourez Azeroth pour rencontrer les dirigeants des principaux sièges du pouvoir de l’Alliance. Votre périple vous mène devant les dirigeants de Forgefer et de Darnassus, ainsi que devant le Grand bricoleur Gelbin Mekkanivelle, chef des gnomes en exil.",al={"quête exploring the alliance","qu’est-ce que cette quête"}},{q="Qui est Randal Emerson ?",a="Randal Emerson est un intendant de l’antichambre sud du Donjon de Hurlevent. Il indique aux voyageurs comment rejoindre les autres capitales.",al={"randal emerson","qui indique le chemin"}},{q="Quels dirigeants faut-il rencontrer au cours de ce périple ?",a="Vous rendez visite au Roi Magni Barbe-de-Bronze à Forgefer, au Grand bricoleur Gelbin Mekkanivelle et à la Grande prêtresse Tyrande Murmevent à Darnassus. Chacun dirige un peuple majeur et détient une autorité au sein de l’Alliance.",al={"dirigeants à rencontrer","à qui parler"}},{q="Pourquoi Dalaran est-elle mentionnée à la fin de la quête ?",a="Votre ordre se prépare à s’établir à Dalaran. Pendant que ces préparatifs avancent, vous êtes encouragé à découvrir Azeroth et à aider les territoires voisins.",al={"pourquoi dalaran est mentionnée","ordre à dalaran"}},{q="Où mène le chemin après ce périple ?",a="Après votre retour au Donjon de Hurlevent, vous prenez la direction des campagnes proches de la capitale, plus précisément de la Marche de l’Ouest. Ses communautés en difficulté ont un besoin urgent de défenseurs compétents.",al={"où aller ensuite","après exploring the alliance"}},{q="Pourquoi l’aventurier est-il accueilli comme un invité de l’Alliance ?",a="Vous êtes considéré comme un étranger tout juste arrivé sur Azeroth, et l’on attend de vous que vous compreniez mieux le monde qui vous entoure afin de protéger et d’aider votre peuple. Ce périple vous fait découvrir la diversité des cultures de l’Alliance.",al={"invité de l’alliance","pourquoi invité"}}},fp="22,167,22.330.0,29.363.0,22.273.0,41.223.0,22.133.0,50.195.0,51.170.0,55.165.0,57.211.0"}
P.entries["quest:94"] = {n="L'œil attentif",s="À la Tour d’Azora, Theocritus observe Morganth de loin. Il envoie des voyageurs vers l’est, aux Carmines, pour placer un glyphe enchanté sur une ancienne statue de lion près de la Tour d'Ilgalar.",h="À la Tour d’Azora, Theocritus observe Morganth de loin.",kw={"elwynn","glyphe d'azora","morganth","ancienne statue de lion","les carmines","theocritus","tour d’azora","tour d'ilgalar"},ang={["class:Mage"]="En tant que mage, vous voyez comment la divination arcanique peut s’exercer à grande distance. Theocritus emploie les méthodes d’Elwynn, tandis que Morganth pratique la sorcellerie renégate.",["faction:Alliance"]="En tant que membre de l’Alliance, vous contribuez à protéger la frontière entre la Forêt d’Elwynn et les colonies assiégées des Carmines contre les lanceurs de sorts humains renégats comme Morganth."},sec={{t="Une rivalité au-delà de la frontière",b="Depuis sa tour, dans l’est de la Forêt d’Elwynn, Theocritus surveille les collines. Son rival, Morganth, est un puissant sorcier qui s’est emparé de la Tour d'Ilgalar, aux Carmines. Craignant que la magie noire de Morganth ne franchisse la frontière, Theocritus a créé l’Eye of Azora pour surveiller le mage renégat de loin."},{t="La veille du lion",b="Une vue lointaine ne permet pas à Theocritus de savoir ce que prépare Morganth. Il confie donc aux voyageurs le Glyphe d'Azora et les envoie près de la Tour d'Ilgalar, auprès de l’Old Lion Statue. La statue monte la garde à cet endroit depuis des décennies.\n\nPlacez le glyphe dans la cavité usée à sa base. Un lien arcanique remonte alors jusqu’à Azora et permet à Theocritus de sonder l’esprit de son rival."}},faq={{q="Qui est Theocritus ?",a="Theocritus est un mage de l’Alliance qui vit dans la Tour d’Azora, dans l’est de la Forêt d’Elwynn. Il étudie la magie pour protéger la région des lanceurs de sorts renégats, en particulier de Morganth.",al={"theocritus","mage de la tour d’azora","qui confie l'œil attentif"}},{q="Qui est Morganth ?",a="Morganth est un mage humain renégat qui a fait de la Tour d'Ilgalar, aux Carmines, son bastion. C’est le grand rival de Theocritus, qui craint les complots qu’il fomente contre les terres voisines.",al={"morganth","qui est morganth","mage rival"}},{q="Où se trouve l’Old Lion Statue ?",a="L’Old Lion Statue se dresse sur les crêtes qui surplombent la Tour d'Ilgalar, dans les collines orientales des Carmines. Une cavité peu profonde à sa base peut accueillir le Glyphe d'Azora.",al={"emplacement de la statue de lion","où se trouve la statue","où placer le glyphe d’azora"}},{q="À quoi sert le Glyphe d'Azora ?",a="Le Glyphe d'Azora est une pierre enchantée créée par Theocritus. Placé dans la statue de lion près de la Tour d'Ilgalar, il transmet son sort d’écoute arcanique et lui permet d’étudier les pensées de Morganth.",al={"glyphe d'azora","qu’est-ce que le glyphe"}},{q="Qu’est-ce que la Tour d'Ilgalar ?",a="La Tour d'Ilgalar est une tour de pierre isolée, perchée dans les rochers de l’est des Carmines. Morganth et ses serviteurs l’occupent et la défendent.",al={"tour d'ilgalar","ilgalar"}},{q="Que se passe-t-il après avoir placé le glyphe ?",a="Après que vous avez placé le Glyphe d'Azora dans la statue, Theocritus s’adresse à vous à travers la pierre et vous propose Looking Further. Il commence à découvrir les plans de Morganth.",al={"quête suivante","que faire après l'œil attentif"}}},fx={["0c307b8a"]={q="Pourquoi Theocritus veut-il que cela soit fait ?",a="Morganth est un mage impitoyable au pouvoir formidable terré dans la Tour d'Ilgalar. Bien que Theocritus puisse observer son rival en utilisant la magie de divination de l'Œil d'Azora, le voir ne suffit plus. En apposant le Glyphe d'Azora sur la statue de lion voisine, Theocritus espère pénétrer l'esprit de Morganth et découvrir ce que le magicien noir complote avant qu'il ne le déchaîne sur la région.",al={"motif de theocritus","pourquoi placer le glyphe d'azora","pourquoi espionner morganth"}}},fp="14,186,27.296.0,16.348.0,18.173.0,16.201.0,37.175.0,32.188.0,29.144.0,35.150.0"}
P.entries["quest:940"] = {n="Teldrassil",s="Après avoir repoussé les harpies, Arynia Eclairciel vous envoie à Darnassus porter des nouvelles aux dirigeants kaldorei. L’Écorce gravée informe l’Archidruide Fandral Forteramure des troubles qui agitent les ramures de Teldrassil.",h="Après avoir repoussé les harpies, Arynia Eclairciel vous envoie à Darnassus porter des nouvelles aux...",kw={"arynia eclairciel","enclave cénarienne","darnassus","fandral forteramure","immortalité","ecorce gravée","kaldorei","oracle tree","teldrassil"},ang={["class:Druid"]="En tant que druide, vous portez un message de l’Oracle Tree au chef du Cercle cénarien. Là, la lutte pour rétablir l’équilibre naturel de Teldrassil est manifeste.",["faction:Alliance"]="En tant que champion de l’Alliance, vous découvrez officiellement la capitale des elfes de la nuit et ses dirigeants sévères.",["race:NightElf"]="En tant qu’elfe de la nuit, vous remettez le rapport à l’Archidruide Forteramure et découvrez sa détermination à restaurer l’immortalité kaldorei malgré les troubles qui agitent les ramures de Teldrassil."},sec={{t="Un messager pour la cité de pierre",b="La Sentinelle Arynia Eclairciel vous remet un morceau d’Écorce gravée après que vous avez chassé les harpies de leurs nids dans la Clairière de l’Oracle. L’Oracle Tree veille sur la forêt, et Arynia peut maintenant prévenir les dirigeants kaldorei. Vous traversez les terres sauvages jusqu’à Darnassus, la grande forêt de pierre, pour remettre son rapport à l’Archidruide Fandral Forteramure."},{t="Ambition et frustration de Forteramure",b="Fandral Forteramure accueille le rapport avec gratitude et frustration. Les harpies ont été repoussées, mais une menace en remplace une autre sur Teldrassil. Forteramure a défendu la plantation du nouvel Arbre-monde pour rendre aux elfes de la nuit l’immortalité qu’ils ont perdue. Les afflictions qui touchent ses ramures lui rappellent que son œuvre est loin d’être achevée."}},faq={{q="Quel est le but de la quête « Teldrassil » ?",a="Vous portez le rapport de la Sentinelle Arynia Eclairciel depuis l’Oracle Tree jusqu’à l’Archidruide Fandral Forteramure, à Darnassus. L’Écorce gravée transmet des nouvelles de l’arbre après que vous avez repoussé les harpies.",al={"objectif de la quête teldrassil","but de cette quête","remise du rapport à teldrassil"}},{q="Qui est la Sentinelle Arynia Eclairciel ?",a="La Sentinelle Arynia Eclairciel est une sentinelle elfe de la nuit postée près de l’Oracle Tree, dans les terres sauvages de Teldrassil. Elle surveille les menaces de la région, notamment les harpies Bloodfeather, et coordonne la défense de la forêt avec Darnassus.",al={"histoire d’arynia eclairciel","qui donne la quête teldrassil"}},{q="Pourquoi Arynia appelle-t-elle Darnassus une « forêt de pierre » ?",a="On appelle Darnassus une forêt de pierre parce que ses temples, ses ponts et ses pavillons sont construits en marbre et en pierre. Les elfes de la nuit vivent sous la canopée de l’Arbre-monde, tandis que la cité s’élève parmi ces constructions.",al={"sens de forêt de pierre","pourquoi forêt de pierre"}},{q="Pourquoi le rapport sur l’Oracle Tree inquiète-t-il tant Fandral Forteramure ?",a="Fandral Forteramure s’inquiète, car le rapport décrit la corruption et le tumulte qui règnent parmi la faune de Teldrassil. Il a défendu la plantation de l’arbre dans l’espoir de restaurer l’immortalité kaldorei après les dégâts subis par Nordrassil lors de la Troisième guerre. Ces afflictions menacent cette ambition.",al={"réaction de fandral forteramure","pourquoi forteramure est inquiet"}},{q="Quelle quête précède celle-ci, et laquelle la suit ?",a="Vous arrivez après avoir combattu les harpies qui menacent l’Oracle Tree, à Enchanted Glade. Après que vous avez remis le rapport à l’Archidruide Forteramure, il vous envoie à Sombrivage avec le Bosquet des Anciens.",al={"suite de quêtes de teldrassil","quelle quête ensuite"}},{q="Où se trouve l’Archidruide Fandral Forteramure ?",a="L’Archidruide Fandral Forteramure réside à Darnassus, au sommet de l’Enclave cénarienne. Il y supervise les druides du Cercle cénarien et guide la gouvernance kaldorei.",al={"où se trouve fandral","emplacement de fandral forteramure"}}},fx={d4229979={q="Pourquoi la Sentinelle Arynia Eclairciel veut-elle que ce rapport soit remis ?",a="Arynia a besoin que l'Archidruide Fandral Forteramure reçoive le rapport de l'Arbre de l'Oracle afin que Darnassus reste informé de l'état de la branche. Les bois ont souffert des infestations de harpies et d'une corruption contre nature, et les messagers précédents n'ont pas réussi à faire le voyage en toute sécurité. Le calme étant revenu dans La Clairière de l'Oracle, la nouvelle doit atteindre l'Archidruide afin que les dirigeants puissent évaluer l'état de l'arbre-monde.",al={"pourquoi envoyer un rapport à fandral","motif d'arynia eclairciel","pourquoi arynia veut-elle que le rapport soit remis"}},["174bd7d2"]={q="Pourquoi Arynia Eclairciel vous envoie-t-elle plutôt qu'un autre messager ?",a="Les messagers précédents envoyés le long des sentiers forestiers n'ont pas réussi à atteindre Darnassus ou se sont perdus en chemin, ce qui rend Arynia hésitante à risquer un autre coureur ordinaire. Ayant prouvé votre courage et vos prouesses au combat en nettoyant les harpies de La Clairière de l'Oracle, vous avez gagné la faveur de la forêt et démontré que vous pouvez vous défendre vous-même et protéger le message le long des routes périlleuses menant à la ville.",al={"pourquoi m'envoyer à darnassus","pourquoi ne pas envoyer un autre messager","pourquoi arynia a besoin de vous"}}},fp="10,203,29.359.0,35.336.0,46.188.0,35.219.0,51.210.0,68.276.0,48.200.0,47.172.0"}
P.entries["quest:94003"] = {n="The Skybreaker Bulwark",s="Au Sanctuaire d’Akir, Zaal Stormshield détient le Rempart de Briseciel. Le dernier des Briseciel veut le reprendre au sectateur qui l’a volé.",h="Au Sanctuaire d’Akir, Zaal Stormshield détient le Rempart de Briseciel.",kw={"al’aketh","sanctuaire d’akir","briseciel","rempart de briseciel","défense des briseciel","le rempart de briseciel","zaal stormshield","île de zéphras"},ang={["class:Paladin"]="En tant que paladin, vous pourriez apprécier la tâche qui consiste à reprendre un héritage béni à un sectateur corrompu.",["class:Warrior"]="En tant que guerrier, vous pouvez apprendre la technique de défense des Briseciel en récupérant le bouclier ancestral."},sec={{t="Un lignage déchu",b="Sur l’Île de Zéphras, les Al’Aketh ont tué les Briseciel, ne laissant qu’un survivant. Le dernier membre de la famille porte un profond chagrin et une honte amère pour la perte de son plus précieux héritage. Le sectateur Zaal Stormshield a pris le Rempart de Briseciel et rôde désormais au Sanctuaire d’Akir."},{t="Le bouclier sacré",b="Selon la tradition familiale, le Rempart de Briseciel protège toute personne véritablement digne de le manier. Le dernier des Briseciel estime que Zaal ne mérite pas sa faveur divine. Le survivant cherche donc un aventurier pour abattre le voleur au Sanctuaire d’Akir et récupérer le bouclier ancestral. En échange, les Briseciel proposent d’enseigner la technique de défense des Briseciel."}},faq={{q="Qui sont les Briseciel ?",a="Les Briseciel sont un ancien lignage de l’Île de Zéphras, presque entièrement décimé par les Al’Aketh. La personne qui réclame le bouclier est la seule survivante.",al={"qui sont les briseciel","famille briseciel"}},{q="Qu’est-ce que le Rempart de Briseciel ?",a="Le Rempart de Briseciel est un bouclier ancestral du lignage Briseciel, sur l’Île de Zéphras. Selon la tradition familiale, aucun mal ne peut atteindre quiconque est digne de le manier.",al={"qu’est-ce que le rempart de briseciel","le bouclier","histoire du bouclier briseciel"}},{q="Qui sont les Al’Aketh ?",a="Les Al’Aketh ont tué la famille Briseciel sur l’Île de Zéphras, ne laissant qu’un survivant pour pleurer sa perte.",al={"qui a tué les briseciel","qui sont les al’aketh","al’aketh"}},{q="Qui est Zaal Stormshield ?",a="Zaal Stormshield est un sectateur qui a pris le Rempart de Briseciel après le massacre de la famille Briseciel. Il rôde avec le précieux héritage au Sanctuaire d’Akir, sur l’Île de Zéphras.",al={"qui détient le bouclier","zaal","stormshield"}},{q="Où se trouve le Sanctuaire d’Akir ?",a="Le Sanctuaire d’Akir se trouve sur l’Île de Zéphras. Zaal Stormshield y rôde avec le Rempart de Briseciel volé.",al={"où se trouve zaal","emplacement du sanctuaire d’akir","où trouver le bouclier"}},{q="Pourquoi récupérer la Barricade ?",a="Le dernier des Briseciel veut récupérer la Barricade pour réparer le déshonneur de sa famille et soustraire la relique sacrée à des mains indignes. En échange, le survivant enseigne la technique de défense des Briseciel.",al={"pourquoi récupérer le bouclier","qu’est-ce que la défense des briseciel","récompense du bouclier"}}},fp="22,144,16.273.0,17.345.0,24.143.0,31.153.0,21.98.0,24.166.0,28.103.0,34.187.0"}
P.entries["quest:94006"] = {n="The Great Ursera Spirit",s="Un druide vous envoie rencontrer Urs'endris, un esprit de Zephras qui enseigne aux druides à prendre la forme d’ursera depuis des générations. Son domaine dépérit, et Urs'endris peut vous guider dans la suite de vos études.",h="Un druide vous envoie rencontrer Urs'endris, un esprit de Zephras qui enseigne aux druides à prendre la forme...",kw={"druide","chutes","sanctuaire d’akir","esprit","urs'endris","ursera","valanaar","zephras"},ang={["class:Druid"]="En tant que druide, vos études vous ont conduit auprès d’Urs'endris, qui enseigne aux druides la forme d’ursera depuis des générations."},sec={{t="Le grand esprit",b="Un druide vous envoie auprès d’Urs'endris, près des chutes au nord-est de Valanaar. Vos études druidiques vous ont conduit à rencontrer l’un des grands esprits de Zephras. Urs'endris enseigne aux druides à prendre la forme d’ursera depuis des générations, et son domaine dépérit en sombrant dans le ciel."}},faq={{q="Qui est Urs'endris ?",a="Urs'endris est un sage esprit de Zephras qui enseigne aux druides à prendre la forme d’ursera depuis des générations.",al={"qui est urs'endris","grand esprit urs","esprit ursera"}},{q="Où puis-je trouver Urs'endris ?",a="Urs'endris se trouve près des chutes au nord-est de Valanaar, à proximité du Sanctuaire d’Akir.",al={"emplacement d’urs'endris","où est urs'endris","rencontrer l’esprit"}},{q="Pourquoi m’envoie-t-on auprès d’Urs'endris ?",a="Vos études druidiques sont assez avancées pour vous permettre de rencontrer l’un des grands esprits de Zephras, et Urs'endris peut poursuivre votre instruction.",al={"pourquoi rencontrer urs'endris","quête d’esprit druide","études ursera"}},{q="Qu’arrive-t-il au domaine d’Urs'endris ?",a="Le domaine d’Urs'endris a commencé à dépérir et à tomber dans le ciel.",al={"domaine qui dépérit","zephras chute","quel est le problème là-bas"}},{q="Qu’est-ce que la forme d’ursera ?",a="La forme d’ursera est une forme qu’Urs'endris enseigne aux druides à prendre depuis des générations.",al={"forme d’ursera","voie de la griffe","ursera"}}},fp="23,185,16.270.0,18.102.0,28.76.0,34.132.0,41.62.0,25.80.0"}
P.entries["quest:94007"] = {n="Taming the Beast",s="À Valanaar, Quel'ana Quickgale peut vous apprendre à apprivoiser une bête. Votre séjour dans les hautes terres vous a préparé à chercher un compagnon animal.",h="À Valanaar, Quel'ana Quickgale peut vous apprendre à apprivoiser une bête.",kw={"compagnon animal","apprivoisement des bêtes","hautes terres","quel'ana quickgale","taming the beast","valanaar"},sec={{t="Un nouveau compagnon",b="Votre hôte estime que votre séjour dans les hautes terres vous a préparé à chercher un compagnon animal. Rendez-vous à Valanaar et parlez à Quel'ana Quickgale. Il vous enseignera l'art d'apprivoiser les bêtes."}},faq={{q="Qui enseigne l'apprivoisement des bêtes ?",a="Quel'ana Quickgale vous apprend à apprivoiser les bêtes à Valanaar.",al={"qui est quel'ana quickgale","maître de l'apprivoisement des bêtes"}},{q="Où trouver Quel'ana Quickgale ?",a="Quel'ana Quickgale se trouve à Valanaar, le port au sud-est.",al={"où se trouve quel'ana","apprivoisement à valanaar"}},{q="Pourquoi dois-je aller à Valanaar ?",a="Vous êtes envoyé à Valanaar pour parler à Quel'ana Quickgale et commencer à apprendre à apprivoiser les bêtes.",al={"pourquoi valanaar","quête d'apprivoisement des bêtes"}},{q="Qu'est-ce que j'apprends ?",a="Quel'ana Quickgale vous apprendra à apprivoiser une bête afin que vous puissiez chercher un compagnon animal.",al={"qu'est-ce que l'apprivoisement des bêtes","compagnon animal"}}},fp="16,135,15.187.0,25.58.0,35.61.0,27.92.0,19.86.0"}
P.entries["quest:94013"] = {n="Taming the Beast",s="Quel'ana Quickgale vous soumet à une dernière épreuve : dompter un Vuldren Alpha. Le maîtriser vous prépare aux enseignements avancés de votre classe.",h="Quel'ana Quickgale vous soumet à une dernière épreuve : dompter un Vuldren Alpha.",kw={"compagnon animal","plaines aérelles","quel'ana quickgale","bâtonnet de domptage","taming the beast","valanaar","vuldren alpha","île de zéphras"},sec={{t="L'épreuve finale",b="Quel'ana vous donne un Bâtonnet de domptage et vous envoie dans les Plaines Aérelles. Là, vous devez dompter un Vuldren Alpha. Puis rapportez-lui le bâtonnet à Valanaar. Cette épreuve prouve votre maîtrise et vous prépare aux enseignements avancés de votre classe."},{t="Une nouvelle leçon",b="À votre retour, Quel'ana affirme que vous avez appris les bases. Il vous propose de vous apprendre à nouer un lien durable avec un compagnon animal. Il vous exhorte à transmettre ce savoir pour le bien de la classe dont l'Île de Zéphras a besoin."}},faq={{q="Que me demande de dompter Quel'ana ?",a="Quel'ana vous demande de dompter un Vuldren Alpha avec le Bâtonnet de domptage dans les Plaines Aérelles.",al={"dompter un vuldren alpha","quelle bête","dompter l'alpha"}},{q="Où trouver le Vuldren Alpha ?",a="Le Vuldren Alpha se trouve dans les Plaines Aérelles.",al={"emplacement de l'alpha","plaines aérelles","où dompter la bête"}},{q="À quoi sert le Bâtonnet de domptage ?",a="Quel'ana vous donne le Bâtonnet de domptage pour dompter un Vuldren Alpha.",al={"utilité du bâtonnet","quête du bâtonnet de domptage","comment utiliser le bâtonnet"}},{q="Où dois-je rapporter le Bâtonnet de domptage ?",a="Rapportez le Bâtonnet de domptage à Quel'ana Quickgale, à Valanaar.",al={"rapporter le bâtonnet","emplacement de quel'ana","où rapporter le bâtonnet de domptage"}},{q="Qu'apprendrai-je ensuite ?",a="Quel'ana dit qu'il peut vous apprendre à nouer un lien durable avec un compagnon animal.",al={"leçon suivante","lien avec un compagnon animal","que faire ensuite"}}},fp="16,136,15.228.0,12.223.1,34.88.0,34.47.0,27.58.0,33.56.0,29.79.0"}
P.entries["quest:94050"] = {n="Training the Beast",s="À Valanaar, vous rencontrez Quel'dora Quickgale, qui vous apprend à dresser votre familier.",h="À Valanaar, vous rencontrez Quel'dora Quickgale, qui vous apprend à dresser votre familier.",kw={"nourrir un familier","chasseur","dressage de familier","quel'dora quickgale","ranimer un familier","apprivoiser un familier","training the beast","valanaar"},ang={["class:Hunter"]="En tant que chasseur, vous apprenez à dresser et à guider un familier que vous savez déjà apprivoiser."},sec={{t="L'enseignement de Quel'dora",b="Votre confrère chasseur vous envoie auprès de sa sœur, Quel'dora Quickgale, à Valanaar. Vous savez déjà apprivoiser un familier. À présent, Quel'dora peut vous apprendre à dresser votre compagnon."},{t="La mission d'un chasseur",b="Quel'dora vous apprend à guider votre familier, à lui enseigner de nouvelles techniques, à le nourrir et à le ranimer s'il tombe au combat. Elle vous exhorte à respecter l'équilibre et à rester émerveillé par la nature qui vous entoure."}},faq={{q="Qui est Quel'dora Quickgale ?",a="Quel'dora Quickgale est la sœur du chasseur qui vous envoie apprendre à dresser un familier.",al={"qui est queldora","quel'dora","quickgale"}},{q="Où trouver Quel'dora ?",a="Quel'dora Quickgale se trouve à Valanaar.",al={"où trouver queldora","lieu où se trouve quel'dora","dresseur à valanaar"}},{q="Qu'enseigne Quel'dora ?",a="Quel'dora vous apprend à dresser et à guider votre familier, à lui enseigner des techniques, à le nourrir et à le ranimer s'il tombe au combat.",al={"dressage de familier","dresser mon familier","que peut enseigner un dresseur de familiers"}},{q="Puis-je déjà apprivoiser un familier ?",a="Le chasseur qui vous envoie auprès de Quel'dora dit que vous avez déjà le pouvoir d'apprivoiser un familier.",al={"apprivoiser un familier","apprivoisement de familier","un chasseur peut-il apprivoiser"}},{q="Que me demande le chasseur ?",a="Le chasseur vous demande de parler à Quel'dora Quickgale, à Valanaar.",al={"training the beast","quête du dresseur de familiers","parler à quel'dora"}},{q="Que dit Quel'dora au sujet de la nature ?",a="Quel'dora vous exhorte à respecter l'équilibre et à vous émerveiller devant la nature qui vous entoure.",al={"respecter la nature","équilibre","conseil de quel'dora"}}},fp="18,119,20.166.0,17.191.0,27.84.0,27.35.0,26.116.0,25.84.0,34.66.0,37.84.0"}
P.entries["quest:941"] = {n="Une belle plante",s="Au lac Al'Ameth, vous aidez Denalan à prendre soin d'un cœur de bois prélevé sur un scion corrompu. Il le débarrasse de sa mousse, puis vous demande de le placer dans sa jardinière pour voir s'il peut être guéri.",h="Au lac Al'Ameth, vous aidez Denalan à prendre soin d'un cœur de bois prélevé sur un scion corrompu.",kw={"blackmoss the fetid","cœur purifié","denalan","lac al'ameth","jardinière","coeur corrompu","teldrassil","scion"},ang={["class:Druid"]="En tant que druide, vous voyez une terre riche purifier le cœur d'un scion corrompu. C'est un signe rassurant que les soins naturels peuvent repousser la souillure contre nature qui affecte les ramures de L'Arbre-monde.",["profession:Herbalism"]="La maîtrise des terres riches en nutriments et du renouveau botanique de Denalan montre comment l'étude de la terre peut aider à réparer les plantes endommagées.",["race:NightElf"]="En tant qu'elfe de la nuit, vous voyez l'engagement kaldorei à veiller sur la nature dans la restauration du bois vivant et l'éveil de la vie chez les esprits forestiers déchus, alors même que Teldrassil souffre de troubles inquiétants."},sec={{t="Une seconde chance",b="Denalan a gratté la mousse fétide du cœur de bois prélevé sur Blackmoss the Fetid, un scion corrompu. Pourtant, une souillure contre nature palpite encore dans le bois. L'herboriste se fie donc à ses longues années passées à prendre soin des plantes et de la terre. Il vous demande d'enterrer le cœur dans sa jardinière personnelle, espérant que sa terre enrichie ramènera à la santé la vitalité naturelle qui lui reste."},{t="Le miracle de la terre enrichie",b="Dès qu'il touche la terre, le cœur s'enfonce dans le sol, comme mû par un instinct primordial. Quelques instants plus tard, il remonte, purifié de sa corruption et réchauffé d'une lueur douce et amicale. Le cœur d'une créature déchue et corrompue a été purifié. Cette transformation montre que des soins attentifs et une terre sacrée peuvent rétablir l'harmonie lorsque des fléaux contre nature frappent les habitants sauvages de Teldrassil."}},faq={{q="D'où vient ce cœur corrompu ?",a="Le cœur provient de Blackmoss the Fetid, un scion corrompu qui vivait sur les rives du lac Al'Ameth. Lorsqu'il a été récupéré, il était étouffé par une mousse fétide que Denalan a grattée.",al={"origine du cœur","d'où vient le cœur","cœur de blackmoss"}},{q="Qui est Denalan ?",a="Denalan est un botaniste et herboriste elfe de la nuit, installé dans un camp isolé à l'extrémité est du lac Al'Ameth. Il étudie la flore de Teldrassil, enquête sur l'étrange corruption qui se répand dans ses ramures et prépare des terres enrichies.",al={"qui est denalan","histoire de denalan"}},{q="Pourquoi placer le cœur dans une jardinière au lieu de le détruire ?",a="Denalan pense qu'il faut comprendre et guérir la nature plutôt que simplement la détruire. Il espère que sa terre nutritive pourra purger la souillure et rendre au cœur sa vitalité d'origine.",al={"pourquoi planter le cœur","pourquoi guérir le cœur"}},{q="Que se passe-t-il quand vous enterrez le cœur ?",a="Quand le cœur touche la terre, il s'y enfonce. Quelques secondes plus tard, il frétille et remonte à la surface, purifié de sa souillure et palpitant doucement comme un compagnon animé.",al={"que se passe-t-il dans la jardinière","le cœur s'enfonce"}},{q="Cela guérit-il la corruption des scions ?",a="Seul ce cœur récupéré a été guéri. Sa transformation montre que des esprits végétaux peuvent être purifiés individuellement grâce à des soins et à une terre riche, tandis que la corruption continue de se répandre dans Teldrassil.",al={"les scions sont-ils guéris","guérir les scions"}},{q="Pourquoi la terre de la jardinière de Denalan est-elle spéciale ?",a="Denalan a consacré beaucoup de temps à expérimenter différents composts et mélanges de terre nutritive autour du lac Al'Ameth. Il a conçu cette terre pour revitaliser la flore malade et purger le dépérissement qui la gagne.",al={"terre de denalan","terre de la jardinière"}}},fp="18,188,23.366.0,29.383.1,40.167.0,15.228.0,56.176.0,37.167.1,49.183.0,45.184.0"}
P.entries["quest:942"] = {n="Les absences du prospecteur",s="À Sombrivage, un étrange fossile vous mène par-delà la Grande mer, jusqu'aux Paluns. Le Chef archéologue Grisemoustache vous envoie auprès de l'Archéologue Outrepanse, à Port de Menethil, dans l'espoir qu'il en perce les secrets.",h="À Sombrivage, un étrange fossile vous mène par-delà la Grande mer, jusqu'aux Paluns.",kw={"absences du prospecteur","archéologue outrepanse","chef archéologue grisemoustache","sombrivage","taverne de l'eau-profonde","ligue des explorateurs","port de menethil","mystérieux fossile"},ang={["faction:Alliance"]="En tant qu'aventurier de l'Alliance, vous empruntez les routes maritimes de l'Alliance pour traverser la mer depuis Kalimdor jusqu'à Port de Menethil. Ces routes permettent aux branches de la Ligue de rester en contact.",["race:Dwarf"]="En tant que nain, vous découvrez l'étendue du réseau de la Ligue des explorateurs. Ses recherches dans le lointain Kalimdor sont liées à celles de confrères installés en Khaz Modan."},sec={{t="Une découverte curieuse",b="Le Chef archéologue Grisemoustache voit une ressemblance entre l'étrange fossile de Sombrivage et une relique présentée lors d'une conférence de la Ligue des explorateurs à Forgefer. L'Archéologue Outrepanse avait présenté cette relique et croyait que de tels fossiles recelaient des pouvoirs à libérer. Grisemoustache pense qu'Outrepanse est le seul nain capable de discerner ce qui rend cette trouvaille de Kalimdor si extraordinaire."},{t="Une traversée de la mer",b="Vous transportez le mystérieux fossile de Kalimdor jusqu'aux Royaumes de l'est. Outrepanse a été aperçu pour la dernière fois à la Taverne de l'Eau-profonde, à Port de Menethil, où il attendait une escorte armée pour se rendre au site des fouilles de Whelgar. En lui apportant le fossile, vous étendez l'enquête sur Sombrivage à une recherche archéologique plus vaste, qui traverse les continents."}},faq={{q="Pourquoi Grisemoustache m'envoie-t-il jusqu'à Port de Menethil ?",a="Le Chef archéologue Grisemoustache se souvient que l'Archéologue Outrepanse avait présenté une relique identique lors d'une conférence annuelle de la Ligue des explorateurs à Forgefer. Il pense qu'Outrepanse sait comment libérer son pouvoir caché et vous envoie donc au dernier endroit où on l'a vu, à Port de Menethil.",al={"pourquoi aller à port de menethil","mission du fossile de grisemoustache","pourquoi les paluns"}},{q="Qui est l'Archéologue Outrepanse ?",a="L'Archéologue Outrepanse est un chercheur de la Ligue des explorateurs affecté aux Paluns. Il séjourne à la Taverne de l'Eau-profonde, à Port de Menethil, en préparant une expédition vers le périlleux site des fouilles de Whelgar.",al={"qui est outrepanse","histoire de l'archéologue outrepanse"}},{q="Qu'est-ce que le mystérieux fossile ?",a="Le mystérieux fossile est un spécimen ancien découvert à Sombrivage. Outrepanse affirmait autrefois qu'un spécimen identique qu'il avait étudié recelait un pouvoir magique ou historique latent, qui attendait d'être libéré.",al={"qu'est-ce que le fossile","origine du mystérieux fossile","fossile de songerrance"}},{q="Que dit Outrepanse quand vous lui apportez le fossile ?",a="Outrepanse est stupéfait qu'une relique identique à son propre échantillon de recherche provienne du lointain Kalimdor. Cette découverte confirme que les terres sont liées par une histoire ancienne.",al={"réaction d'outrepanse","remettre le fossile"}},{q="Où Outrepanse veut-il aller ensuite ?",a="Outrepanse attend à Port de Menethil une escorte pour rejoindre l'intérieur des terres et le site des fouilles de Whelgar, un chantier majeur des Paluns.",al={"où va outrepanse","fouilles d'outrepanse"}},{q="Quelle est la place de cette quête dans l'histoire des absences du prospecteur ?",a="Après avoir escorté et sauvé le Prospecteur Songerrance à Sombrivage, vous examinez la relique qu'il a extraite avec Grisemoustache. L'enquête se déplace ensuite du nord de Kalimdor vers les experts de la Ligue des explorateurs, dans les Royaumes de l'est.",al={"absences du prospecteur partie quatre","contexte de la suite de quêtes"}}},fx={["5b36a0d8"]={q="Pourquoi le Chef archéologue Grisemoustache veut-il que cela soit fait ?",a="Le Chef archéologue Grisemoustache reconnaît que le mystérieux fossile découvert par Songerrance présente une ressemblance frappante avec une relique particulière présentée lors d'une conférence de la Ligue des explorateurs à Forgefer. Son découvreur, l'Archéologue Outrepanse, pensait que la relique possédait un pouvoir latent qui ne demandait qu'à être libéré. Grisemoustache espère qu'Outrepanse pourra étudier ce nouveau spécimen et révéler les secrets anciens du passé.",al={"pourquoi envoyer le fossile","motif de grisemoustache","pourquoi grisemoustache veut-il que le fossile soit examiné"}}},fp="28,201,19.374.0,23.327.0,60.282.0,31.217.0,30.195.0,52.171.0,37.121.0,68.212.0"}
P.entries["quest:94212"] = {n="Craftsman's Writ: Elixir of Wisdom",s="Un bon de commande transférable demande un Elixir of Wisdom et précise les modalités de livraison et de paiement. Le bon est nécessaire pour conclure l’échange.",h="Un bon de commande transférable demande un Elixir of Wisdom et précise les modalités de livraison et de...",kw={"bon de commande d’artisan","livraison","elixir of wisdom","paiement","transférable","bon"},sec={{t="Une demande écrite",b="Une note décolorée intitulée Craftsman's Writ: Elixir of Wisdom vous demande d’apporter un Elixir of Wisdom. Elle précise le lieu de livraison et les modalités de paiement, et le bon peut passer de main en main. Vous devez avoir le bon en votre possession pour conclure l’échange."}},faq={{q="Que demande le bon ?",a="Il demande un Elixir of Wisdom.",al={"bon d’élixir","objet demandé"}},{q="Puis-je transmettre le bon à quelqu’un d’autre ?",a="Oui. La note indique que le bon est transférable.",al={"bon transférable","quelqu’un d’autre peut-il le porter"}},{q="De quoi ai-je besoin pour conclure l’échange ?",a="Vous devez avoir l’objet demandé et le bon en votre possession. La note précise le lieu de livraison et les modalités de paiement.",al={"éléments nécessaires à la livraison","comment utiliser le bon"}}},fp="34,149,17.246.0,27.33.0,36.44.0,40.118.0"}
P.entries["quest:94214"] = {n="Craftsman's Writ: Shadow Protection Potion",s="Un bon cessible demande une Shadow Protection Potion et précise les modalités de livraison et de paiement. La transaction exige que vous ayez le bon sur vous.",h="Un bon cessible demande une Shadow Protection Potion et précise les modalités de livraison et de paiement.",kw={"craftsman's writ","livraison","paiement","potion","shadow protection potion","cessible","bon"},sec={{t="Une demande écrite",b="Une note délavée vous demande de fournir une Shadow Protection Potion. Elle précise aussi le lieu de livraison et les modalités de paiement, et indique que le bon peut passer de main en main. Vous devez avoir le bon sur vous pour conclure l’échange."}},faq={{q="Que demande le bon ?",a="Le bon demande une Shadow Protection Potion.",al={"que veulent-ils","demande de potion","objet demandé par le bon"}},{q="Où dois-je la livrer ?",a="Le lieu de livraison est indiqué sur votre carte.",al={"lieu de livraison","où apporter la potion","lieu indiqué"}},{q="Le bon précise-t-il comment je serai payé ?",a="Le bon contient des informations sur le paiement.",al={"modalités de paiement","combien paient-ils","paiement du bon"}},{q="Puis-je donner le bon à quelqu’un d’autre ?",a="Oui. La note indique que le bon est cessible.",al={"est-il cessible","transmettre le bon","céder le bon"}},{q="Dois-je garder le bon sur moi ?",a="Oui. Vous devez avoir le bon sur vous pour conclure la transaction.",al={"bon nécessaire pour livrer","faut-il l’avoir sur soi","bon requis"}}},fp="42,156,17.215.0,27.47.0,22.44.0,37.44.0,36.44.0,35.65.0"}
P.entries["quest:94216"] = {n="Craftsman's Writ: Elixir of Lesser Agility",s="Un ordre transmissible vous demande d'obtenir un Elixir of Lesser Agility pour un client. Il indique le lieu de livraison et les modalités de paiement.",h="Un ordre transmissible vous demande d'obtenir un Elixir of Lesser Agility pour un client.",kw={"agilité","ordre d'artisan","livraison","élixir","elixir of lesser agility","paiement","transmissible"},sec={{t="La demande d'un client",b="Un client cherche à obtenir un Elixir of Lesser Agility au moyen de cet ordre à l'encre délavée. Vous devez vous procurer l'objet demandé et l'apporter à l'endroit indiqué ; vous devez avoir l'ordre sur vous pour conclure la transaction."}},faq={{q="Que demande l'ordre ?",a="Le client demande un Elixir of Lesser Agility.",al={"objet demandé","demande d'élixir","que veulent-ils"}},{q="Où dois-je le livrer ?",a="L'ordre indique un lieu de livraison marqué sur votre carte.",al={"lieu de livraison","où l'apporter","lieu indiqué"}},{q="L'ordre précise-t-il comment fonctionne le paiement ?",a="L'ordre contient des informations sur le paiement.",al={"détails du paiement","quel montant payer","quel est le paiement"}},{q="Quelqu'un d'autre peut-il transporter l'ordre ?",a="Oui. Le texte au bas de l'ordre précise qu'il est transmissible.",al={"est-il transmissible","le transmettre","ordre à échanger"}},{q="Ai-je besoin de l'ordre pour effectuer la livraison ?",a="Oui. Vous devez avoir l'ordre sur vous pour conclure la transaction.",al={"besoin de l'ordre","garder le papier","ordre requis"}}},fp="42,132,20.209.0,27.51.0,22.58.0,36.44.0,32.54.0,44.68.0"}
P.entries["quest:94219"] = {n="Craftsman's Writ: Draught of Water Breathing",s="Un mandat transférable demande un Draught of Water Breathing et précise les modalités de livraison et de paiement. Vous avez besoin du mandat pour conclure l’échange.",h="Un mandat transférable demande un Draught of Water Breathing et précise les modalités de livraison et de...",kw={"craftsman's writ","livraison","draught of water breathing","paiement","respiration aquatique","mandat"},sec={{t="Une demande écrite",b="La note délavée vous demande un Draught of Water Breathing. Elle précise aussi le lieu de livraison et le paiement, et peut passer d’un détenteur à un autre."}},faq={{q="Que demande le mandat ?",a="Il demande un Draught of Water Breathing.",al={"que veulent-ils","demande de breuvage","objet du mandat"}},{q="Où dois-je le livrer ?",a="Le mandat indique un lieu de livraison, marqué sur votre carte.",al={"lieu de livraison","où le rapporter","lieu du mandat"}},{q="Quel paiement est proposé ?",a="Le mandat contient des informations sur le paiement.",al={"montant du paiement","paiement du mandat","que reçoit-on"}},{q="Le mandat peut-il être transféré ?",a="Oui. La note indique que le mandat peut être transféré.",al={"mandat transférable","quelqu’un d’autre peut-il le porter","transmettre le mandat"}},{q="Ai-je besoin du mandat pour conclure l’échange ?",a="Oui. Vous devez avoir le mandat sur vous pour conclure la transaction.",al={"besoin de la note","mandat requis","livraison possible sans mandat"}}},fp="44,143,17.146.0,27.43.0,22.55.0,24.44.0,28.47.0,44.65.0"}
P.entries["quest:94220"] = {n="Craftsman's Writ: Pearl-Handled Dagger",s="Un bon de commande cessible demande une Pearl-Handled Dagger et précise les modalités de livraison et de paiement. Vous avez besoin du bon pour conclure l’échange.",h="Un bon de commande cessible demande une Pearl-Handled Dagger et précise les modalités de livraison et de...",kw={"craftsman's writ","dague","livraison","paiement","pearl-handled dagger","bon de commande"},sec={{t="Le bon de commande",b="La note est rédigée à l’encre passée et mentionne une Pearl-Handled Dagger parmi les objets recherchés. Les dernières lignes précisent un lieu de livraison et les modalités de paiement. Le bon peut passer de main en main, mais vous devez l’avoir en votre possession pour conclure l’échange."}},faq={{q="Quel objet le bon demande-t-il ?",a="Le bon demande une Pearl-Handled Dagger.",al={"bon dague perle","quel objet est recherché"}},{q="Où dois-je livrer l’objet ?",a="Le lieu de livraison est indiqué sur votre carte.",al={"lieu de livraison","où l’apporter"}},{q="Que propose le client ?",a="Le bon contient des informations sur le paiement.",al={"modalités de paiement","montant du paiement"}},{q="Puis-je céder ce bon ?",a="Oui. Le bon indique qu’il peut être cédé.",al={"céder le bon","la note est-elle cessible"}},{q="Dois-je conserver le bon ?",a="Oui. Vous devez avoir le bon en votre possession pour conclure la transaction.",al={"bon nécessaire pour conclure","note à conserver"}}},fp="38,141,8.243.0,27.41.0,28.44.0,29.44.0,25.41.0,27.70.0"}
P.entries["quest:94222"] = {n="Commission d’artisan : marteau iridescent",s="Un client attend un Marteau iridescent. L’ordre de mission précise les modalités de livraison et de paiement. Sa marque cessible permet à son détenteur de conclure l’échange.",h="Un client attend un Marteau iridescent.",kw={"ordre de mission d’artisan","livraison","marteau","marteau iridescent","paiement","cessible","ordre de mission"},sec={{t="L’ordre de mission",b="Le client demande un Marteau iridescent. Apportez l’ordre de mission à l’endroit indiqué pour conclure l’échange."}},faq={{q="Que demande le client ?",a="Le client demande un Marteau iridescent.",al={"ordre de mission pour marteau iridescent","objet demandé"}},{q="Où dois-je le livrer ?",a="L’ordre de mission précise les modalités de livraison, et l’emplacement est indiqué sur votre carte.",al={"lieu de livraison indiqué sur l’ordre","où apporter le marteau"}},{q="Dois-je garder l’ordre de mission sur moi ?",a="Oui. Gardez l’ordre de mission sur vous pour conclure l’échange.",al={"ordre de mission nécessaire pour livrer","ordre de mission requis"}},{q="Quelqu’un d’autre peut-il utiliser l’ordre de mission ?",a="Oui. L’ordre de mission est cessible.",al={"ordre de mission cessible","transmettre l’ordre de mission"}},{q="L’ordre de mission précise-t-il les modalités de paiement ?",a="Oui. L’ordre de mission contient les informations de paiement.",al={"paiement du marteau","montant du paiement"}}},fp="35,155,8.108.0,28.49.0,22.76.0,33.53.0,30.40.0,36.43.0"}
P.entries["quest:94223"] = {n="Craftsman's Writ: Silver Skeleton Key",s="Un écrit transmissible demande une Clé squelette en argent et indique un lieu de livraison. Dans la crypte, une note du gardien et un coffre attendent celui qui possède la clé.",h="Un écrit transmissible demande une Clé squelette en argent et indique un lieu de livraison.",kw={"gardien","craftsman's writ","crypte","cimetière de colline-aux-corbeaux","clé squelette en argent","coffre","mort-vivant"},sec={{t="L’écrit",b="L’encre pâlie mentionne une Clé squelette en argent, un lieu de livraison et une récompense. L’écrit peut passer de main en main, mais vous devez le porter pour conclure l’échange."},{t="Dans la crypte",b="Une note posée sur un coffre annonce que le gardien du Cimetière de Colline-aux-Corbeaux est mort. Il dit que les employeurs de Sombre-Comté l’ont presque oublié et qu’il a laissé ses richesses dans la boîte à quiconque pourra l’ouvrir. Les morts-vivants se rassemblent tout près et personne d’autre n’est en vue. Vous utilisez la clé. Le coffre contient peu de choses, mais elles couvrent une partie du coût."}},faq={{q="Que demande l’écrit ?",a="L’écrit demande une Clé squelette en argent et indique un lieu de livraison ainsi qu’une récompense.",al={"écrit pour une clé en argent","quelle clé est demandée"}},{q="Quelqu’un d’autre peut-il porter l’écrit ?",a="Oui. L’écrit indique qu’il peut être transmis, mais vous devez le posséder pour conclure l’échange.",al={"écrit transmissible","puis-je le transmettre"}},{q="Où l’écrit m’envoie-t-il ?",a="L’écrit vous dirige vers l’endroit indiqué sur votre carte.",al={"lieu de livraison","où apporter la clé"}},{q="Qui a laissé la note dans la crypte ?",a="La note a été laissée par un gardien du Cimetière de Colline-aux-Corbeaux qui dit être mort.",al={"note du gardien","qui est mort"}},{q="Que contenait le coffre ?",a="Le coffre est presque vide, mais son contenu suffit à couvrir une partie du coût.",al={"coffre vide","trésor du gardien"}}},fp="37,165,8.165.0,12.334.1,27.81.0,32.97.0,28.56.0,31.77.0,22.72.0"}
P.entries["quest:94224"] = {n="Craftsman's Writ: Heavy Bronze Mace",s="Une requête passée à l’encre pâlie demande une Heavy Bronze Mace et précise les conditions de livraison et de paiement. Vous devez garder la requête pour conclure l’échange.",h="Une requête passée à l’encre pâlie demande une Heavy Bronze Mace et précise les conditions de livraison et de...",kw={"requête d’artisan","livraison","heavy bronze mace","masse","paiement","requête cessible"},sec={{t="Une requête écrite",b="La note est écrite à l’encre pâlie, et le client demande une Heavy Bronze Mace. Vous devez apporter l’objet demandé à l’endroit indiqué sur votre carte. Gardez la requête avec vous, car elle est nécessaire pour conclure l’échange."}},faq={{q="Que demande la requête ?",a="Le client demande une Heavy Bronze Mace.",al={"requête pour une heavy bronze mace","objet demandé"}},{q="Où dois-je livrer la masse ?",a="Le lieu de livraison est indiqué sur votre carte.",al={"lieu de livraison de la masse","où l’apporter"}},{q="Dois-je garder la requête ?",a="Oui. Vous devez avoir la requête en votre possession pour conclure la transaction.",al={"requête nécessaire","requête requise"}},{q="Que dit la note au sujet du paiement ?",a="La note contient des informations sur le paiement, mais le texte fourni n’en indique pas le montant.",al={"paiement de la masse","montant du paiement"}},{q="Quelqu’un d’autre peut-il utiliser la requête ?",a="L’inscription au bas de la note précise que la requête est cessible.",al={"requête cessible","céder la requête"}}},fp="35,133,17.218.0,27.44.0,28.44.0,27.69.0,37.92.0,30.56.0"}
P.entries["quest:94226"] = {n="Craftsman's Writ: Green Iron Gauntlets",s="La réquisition de MacKinley vous demande de lui apporter des Green Iron Gauntlets. Le billet transférable précise les modalités de livraison et de paiement.",h="La réquisition de MacKinley vous demande de lui apporter des Green Iron Gauntlets.",kw={"réquisition d’artisan","livraison","green iron gauntlets","coups de poing américains en fer vert","mackinley","paiement","transférable"},sec={{t="Une commande écrite",b="La réquisition délavée mentionne des Green Iron Gauntlets et précise un lieu de livraison ainsi qu’un paiement. Vous devez avoir la réquisition sur vous pour conclure l’échange. MacKinley attend la marchandise, mais son accueil laisse entendre que quelque chose cloche."},{t="Lors de l’échange",b="MacKinley dit qu’il voulait des coups de poing américains en fer vert, pas des gantelets. Il accepte les gantelets en attendant de recevoir ce qu’il voulait, puis vous paie moins que prévu."}},faq={{q="Que demande MacKinley ?",a="La réquisition demande une paire de Green Iron Gauntlets, mais MacKinley dit qu’il comptait demander des coups de poing américains en fer vert.",al={"que veut mckinley","réquisition de fer vert"}},{q="Où dois-je livrer les gantelets ?",a="La réquisition indique un lieu de livraison, marqué sur votre carte.",al={"où livrer","lieu de la réquisition"}},{q="Dois-je avoir la réquisition sur moi ?",a="Oui. Vous devez avoir la réquisition en votre possession pour conclure l’échange.",al={"réquisition nécessaire","réquisition oubliée"}},{q="Que dit la réquisition au sujet du paiement ?",a="Le billet contient des informations sur le paiement, mais son texte ne précise aucun montant.",al={"montant du paiement","modalités de paiement"}},{q="Quelqu’un d’autre peut-il transporter la réquisition ?",a="Oui. Le billet indique que la réquisition est transférable.",al={"réquisition transférable","peut-on donner la réquisition"}}},fp="38,123,15.216.0,15.157.1,28.114.0,33.55.0,27.66.0,37.77.0,32.44.0"}
P.entries["quest:94229"] = {n="Craftsman's Writ: Ornate Spyglass",s="Un document transmissible demande une Ornate Spyglass et précise les modalités de livraison et de paiement. Le client en attente indique qu’un ingénieur n’a pas encore livré la commande.",h="Un document transmissible demande une Ornate Spyglass et précise les modalités de livraison et de paiement.",kw={"document d’artisan","livraison","ingénieur","ornate spyglass","paiement","longue-vue","document"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous êtes lié à la commande : le client en attente indique qu’un ingénieur n’a pas encore livré la longue-vue."},sec={{t="Un client en attente",b="Un client attend qu’un ingénieur lui livre une Ornate Spyglass. Le document défraîchi nomme l’objet demandé et précise le lieu de livraison ainsi que les modalités de paiement. Vous devez avoir le document sur vous pour effectuer l’échange."}},faq={{q="Que demande le document ?",a="Le document demande une Ornate Spyglass.",al={"document ornate spyglass","objet demandé"}},{q="Où dois-je livrer la longue-vue ?",a="Le document indique un lieu de livraison, marqué sur votre carte.",al={"lieu de livraison de la longue-vue","où la livrer"}},{q="Le document précise-t-il les modalités de paiement ?",a="Le document contient des informations sur le paiement, mais le texte présenté ici n’indique aucun montant.",al={"paiement de la longue-vue","combien vont-ils payer"}},{q="Pourquoi dois-je garder le document ?",a="Vous devez avoir le document sur vous pour effectuer la transaction.",al={"faut-il le document ?","document oublié"}},{q="Qui attend la commande ?",a="Un client attend qu’un ingénieur lui livre l’Ornate Spyglass.",al={"qui veut la longue-vue","client en attente"}}},fp="33,163,18.217.0,27.38.0,32.55.0,36.79.0,31.60.0,29.69.0"}
P.entries["quest:94231"] = {n="Craftsman's Writ: Moonsight Rifle",s="Un ordre transmissible demande un Moonsight Rifle et indique un lieu de livraison ainsi qu’un paiement. L’acheteur veut que l’échange reste discret.",h="Un ordre transmissible demande un Moonsight Rifle et indique un lieu de livraison ainsi qu’un paiement.",kw={"couverture","ordre d’artisan","tirs croisés","livraison","moonsight rifle","paiement","fusil","satyre"},sec={{t="Un échange discret",b="Une note décolorée vous demande d’apporter un Moonsight Rifle à l’endroit indiqué, où le paiement vous attend. L’ordre peut passer de main en main, mais vous devez le porter pour conclure l’échange. L’acheteur vous avertit que votre approche attire l’attention et risque de compromettre sa couverture."},{t="Le fusil",b="Une fois le Moonsight Rifle présenté, l’acheteur vante sa puissance contre les satyres. Il vous dit de vous écarter avant que les tirs croisés ne commencent."}},faq={{q="Que demande l’ordre ?",a="L’ordre demande un Moonsight Rifle, à livrer à l’endroit indiqué sur votre carte.",al={"ordre de moonsight rifle","quel fusil veulent-ils"}},{q="Puis-je donner l’ordre à quelqu’un d’autre ?",a="Oui. La note indique que l’ordre est transmissible, mais vous devez le porter pour conclure l’échange.",al={"l’ordre est-il transmissible","transmettre l’ordre"}},{q="Pourquoi l’acheteur veut-il de la discrétion ?",a="L’acheteur dit que votre approche attire l’attention et risque de compromettre sa couverture.",al={"pourquoi tant de discrétion","compromettre la couverture"}},{q="Contre qui le fusil doit-il être utilisé ?",a="L’acheteur dit que le fusil pourrait faire sauter la tête d’un satyre.",al={"fusil contre les satyres","cible du moonsight rifle"}}},fp="33,127,16.270.0,9.139.1,27.87.0,36.107.0,33.86.0,42.62.0"}
P.entries["quest:94233"] = {n="Craftsman's Writ: Practice Lock",s="Un ordre transmissible vous demande de fournir une Practice Lock. Le lieu de livraison et les modalités de paiement sont indiqués sur la note.",h="Un ordre transmissible vous demande de fournir une Practice Lock.",kw={"craftsman's writ","livraison","serrure","paiement","practice lock","transmissible","ordre"},sec={{t="Une demande écrite",b="Un client demande une Practice Lock par l’intermédiaire d’un ordre transmissible et défraîchi. Vous devez livrer l’objet demandé à l’endroit indiqué sur votre carte et garder l’ordre sur vous pour conclure la transaction."}},faq={{q="Que demande l’ordre ?",a="L’ordre demande une Practice Lock.",al={"demande de practice lock","quel objet","ordre pour une serrure"}},{q="Où dois-je livrer la Practice Lock ?",a="Le lieu de livraison est indiqué sur votre carte.",al={"lieu de livraison","où l’apporter","où livrer"}},{q="Dois-je garder l’ordre ?",a="Oui. Vous devez avoir l’ordre sur vous pour conclure la transaction.",al={"faut-il l’ordre","apporter la note","ordre requis"}},{q="L’ordre est-il transmissible ?",a="Oui. L’ordre indique qu’il est transmissible.",al={"peut-on le transmettre","note transmissible","transmettre l’ordre"}},{q="La note mentionne-t-elle un paiement ?",a="L’ordre mentionne un paiement, mais le texte fourni n’en précise pas le montant.",al={"modalités de paiement","montant du paiement","paiement"}}},fp="31,122,17.215.0,27.36.0,37.44.0,27.69.0,25.38.0,30.68.0"}
P.entries["quest:94236"] = {n="Craftsman's Writ: Big Bronze Bomb",s="Un bon transférable demande une bombe en bronze massif et précise les modalités de livraison et de paiement. Vous devez avoir le bon sur vous pour conclure l’échange.",h="Un bon transférable demande une bombe en bronze massif et précise les modalités de livraison et de paiement.",kw={"bombe en bronze massif","bombe","bon d’artisan","livraison","paiement","bon transférable"},sec={{t="Une demande écrite",b="La note défraîchie vous demande d’apporter une bombe en bronze massif. Elle indique aussi un lieu de livraison et le paiement, et précise que le bon peut passer de main en main. Gardez-le sur vous pour la transaction."}},faq={{q="Quel objet le bon demande-t-il ?",a="Le bon demande une bombe en bronze massif.",al={"objet demandé","bon pour bombe en bronze massif"}},{q="Où dois-je livrer la bombe ?",a="Le bon indique le lieu de livraison marqué sur votre carte.",al={"lieu de livraison","où l’apporter"}},{q="Que propose le client ?",a="Le bon contient des informations sur le paiement.",al={"montant du paiement","modalités de paiement"}},{q="Puis-je donner le bon à quelqu’un d’autre ?",a="Oui. La note indique que le bon est transférable.",al={"bon transférable","transmettre la note"}},{q="Ai-je besoin du bon pour l’échange ?",a="Oui. Vous devez avoir le bon en votre possession pour conclure la transaction.",al={"bon requis pour conclure","dois-je garder la note sur moi"}}},fp="33,141,17.181.0,27.38.0,28.60.0,29.44.0,36.44.0,36.70.0"}
P.entries["quest:94238"] = {n="Craftsman's Writ: Heavy Leather Ball",s="Un Craftsman's Writ transférable demande une balle en cuir lourd et nomme un client. Sos'mol désire tant cette balle que sa livraison compte beaucoup pour lui.",h="Un Craftsman's Writ transférable demande une balle en cuir lourd et nomme un client.",kw={"craftsman's writ","livraison","balle en cuir lourd","ogre","paiement","sos'mol","transférable"},sec={{t="La demande d’un client",b="Le document défraîchi demande une balle en cuir lourd et précise les modalités de livraison et de paiement. Vous l’apportez pour conclure l’échange. À votre arrivée, Sos'mol fredonne une mélodie discordante sur l’ennui. Il continue de fredonner, mais plus doucement, et semble un peu gêné."},{t="La joie de Sos'mol",b="Sos'mol vous demande si vous lui avez apporté la balle. Lorsqu’il la reçoit, les larmes lui montent aux yeux et il dit que c’est le plus beau jour de la vie d’un ogre. Cette balle compte plus pour lui que tout ce qu’il avait pu désirer d’autre, même s’il ne se souvient plus de quoi il s’agissait."}},faq={{q="Que demande le document ?",a="Le document demande une balle en cuir lourd et précise les modalités de livraison et de paiement.",al={"document pour balle en cuir lourd","quel objet est demandé"}},{q="Qui est le client ?",a="Sos'mol est le client nommé pour la livraison.",al={"qui veut la balle","document de sos'mol"}},{q="Pourquoi Sos'mol veut-il une balle ?",a="Sos'mol dit qu’il rêvait de cette balle.",al={"pourquoi une balle","sos'mol veut une balle"}},{q="Que fait Sos'mol à mon arrivée ?",a="Sos'mol fredonnait une chanson discordante sur l’ennui et continue plus doucement à votre approche.",al={"que fait sos'mol","sos'mol chante"}},{q="Quelqu’un d’autre peut-il utiliser le document ?",a="Oui. La note précise que le document est transférable.",al={"document transférable","puis-je céder le document"}}},fp="36,151,20.284.0,17.252.1,27.88.0,20.46.0,29.60.0,36.99.0,30.44.0"}
P.entries["quest:94242"] = {n="Craftsman's Writ: Pilferer's Gloves",s="Un bon de commande cessible demande des Pilferer's Gloves et précise les modalités de livraison et de paiement. Vous avez besoin du bon pour conclure la transaction.",h="Un bon de commande cessible demande des Pilferer's Gloves et précise les modalités de livraison et de...",kw={"craftsman's writ","livraison","gants","paiement","pilferer's gloves","cessible","bon de commande"},sec={{t="Une commande écrite",b="Une note passée demande une paire de Pilferer's Gloves. Elle indique où les livrer et les modalités de paiement, et le bon de commande peut passer de main en main."},{t="La transaction",b="Vous devez avoir le bon de commande sur vous lorsque vous apportez les gants demandés à l’endroit indiqué. La note rattache les modalités de livraison et de paiement à cette commande écrite."}},faq={{q="Que demande le bon de commande ?",a="Le bon de commande demande une paire de Pilferer's Gloves.",al={"bon de commande pilferer's gloves","commande de gants","quel objet"}},{q="Où dois-je livrer les gants ?",a="Le lieu de livraison est indiqué sur votre carte.",al={"lieu de livraison","où apporter les gants","endroit indiqué"}},{q="De quoi ai-je besoin pour conclure la transaction ?",a="Vous devez avoir le bon de commande en votre possession pour conclure la transaction.",al={"besoin du bon de commande","bon de commande requis","conclure la transaction"}},{q="Le bon de commande précise-t-il les modalités de paiement ?",a="Le bon de commande contient des informations sur le paiement.",al={"modalités de paiement","montant du paiement","paiement des gants"}},{q="Quelqu’un d’autre peut-il porter le bon de commande ?",a="Oui. Le bon de commande est cessible.",al={"bon de commande cessible","transmettre la note","possibilité de le donner"}}},fp="35,141,15.156.0,15.156.0,27.48.0,30.44.0,43.65.0,36.44.0,32.30.0"}
P.entries["quest:94243"] = {n="Commission d’artisan : carquois lourd",s="Un avis Craftsman's Writ : Carquois lourd défraîchi vous demande d’apporter un Carquois lourd à l’endroit indiqué et précise les modalités de paiement.",h="Un avis Craftsman's Writ : Carquois lourd défraîchi vous demande d’apporter un Carquois lourd à l’endroit...",kw={"avis d’artisan","livraison","carquois lourd","paiement","carquois","cessible"},sec={{t="L’avis",b="La note vous demande de vous procurer un Carquois lourd et de l’apporter à l’endroit indiqué sur votre carte. Gardez l’avis sur vous pour conclure l’échange."}},faq={{q="Que demande l’avis ?",a="Le client demande un Carquois lourd.",al={"demande de carquois lourd","objet demandé"}},{q="Où dois-je le livrer ?",a="Le lieu de livraison est indiqué sur votre carte.",al={"lieu de livraison","où apporter le carquois"}},{q="Dois-je garder l’avis sur moi ?",a="Oui. Gardez l’avis sur vous pour conclure l’échange.",al={"avis nécessaire","avis requis"}},{q="Puis-je céder cet avis à quelqu’un d’autre ?",a="Oui. L’avis peut être cédé à quelqu’un d’autre.",al={"céder l’avis","quelqu’un d’autre peut-il l’utiliser"}},{q="L’avis mentionne-t-il un paiement ?",a="L’avis précise les modalités de paiement, mais aucun montant n’est indiqué.",al={"montant du paiement","paiement du carquois"}}},fp="30,121,8.140.0,27.39.0,22.41.0,28.54.0,37.49.0,30.56.0"}
P.entries["quest:94245"] = {n="Craftsman's Writ: Barbaric Gloves",s="Un document transmissible demande une paire de Barbaric Gloves et indique un lieu de livraison ainsi que les modalités de paiement. Vous devez l'avoir sur vous pour conclure la transaction.",h="Un document transmissible demande une paire de Barbaric Gloves et indique un lieu de livraison ainsi que les...",kw={"barbaric gloves","craftsman's writ","livraison","gants","paiement","transmissible","document"},sec={{t="La demande d'un client",b="Un client demande une paire de Barbaric Gloves par le biais de ce document défraîchi. La note indique un lieu de livraison et les modalités de paiement, et peut passer de main en main. Vous devez avoir le document en votre possession lorsque vous livrez l'objet demandé."}},faq={{q="Que demande le document ?",a="Le client demande une paire de Barbaric Gloves.",al={"document barbaric gloves","quels gants","craftsman's writ"}},{q="Où dois-je livrer les gants ?",a="Le lieu de livraison est indiqué sur votre carte.",al={"lieu de livraison","où livrer les gants"}},{q="Dois-je garder le document sur moi ?",a="Oui. Vous devez avoir le document en votre possession pour conclure la transaction.",al={"document à garder sur soi","document requis"}},{q="Le document peut-il être transmis ?",a="Oui. La note indique que le document est transmissible.",al={"transmettre le document","faire passer le document"}},{q="Que dit le document au sujet du paiement ?",a="Le document contient des informations sur le paiement.",al={"modalités de paiement","montant du paiement"}}},fp="33,151,20.237.0,27.50.0,30.44.0,28.70.0,28.44.0,37.44.0"}
P.entries["quest:94246"] = {n="Craftsman's Writ: Red Whelp Gloves",s="Un mandat transférable demande une paire de Red Whelp Gloves. Il indique un lieu de livraison et un paiement pour l’échange.",h="Un mandat transférable demande une paire de Red Whelp Gloves.",kw={"craftsman's writ","livraison","paiement","red whelp gloves","transférable","mandat"},sec={{t="Une demande écrite",b="Une note effacée demande une paire de Red Whelp Gloves et indique un lieu de livraison ainsi qu’un paiement. Vous devez détenir le mandat pour conclure l’échange."}},faq={{q="Que demande le mandat ?",a="Le mandat demande une paire de Red Whelp Gloves.",al={"mandat red whelp gloves","quel objet est demandé"}},{q="Où dois-je livrer les gants ?",a="Le mandat indique un lieu de livraison marqué sur votre carte.",al={"lieu de livraison","où apporter les gants"}},{q="De quoi ai-je besoin pour conclure l’échange ?",a="Vous devez avoir le mandat en votre possession pour conclure l’échange.",al={"éléments nécessaires","condition du mandat"}},{q="Le mandat peut-il être transféré ?",a="Oui. La note précise que le mandat est transférable.",al={"mandat transférable","quelqu’un d’autre peut-il le prendre"}},{q="Le mandat mentionne-t-il un paiement ?",a="Oui. Le mandat contient des informations sur le paiement.",al={"montant du paiement","paiement pour les gants"}}},fp="34,114,17.145.0,27.47.0,30.57.0,40.62.0,28.44.0,30.49.0"}
P.entries["quest:94249"] = {n="Craftsman's Writ: Azure Silk Hood",s="Un Craftsman’s Writ à l’encre passée réclame une Azure Silk Hood et précise les conditions de livraison et de paiement. Vous avez besoin du bon pour conclure l’échange.",h="Un Craftsman’s Writ à l’encre passée réclame une Azure Silk Hood et précise les conditions de livraison et de...",kw={"azure silk hood","craftsman's writ","livraison","paiement","capuche en soie","transférable","bon"},sec={{t="Les conditions écrites",b="La note est rédigée à l’encre passée et désigne un seul objet : une Azure Silk Hood. Elle indique aussi le lieu de livraison et le paiement. Le bon peut passer d’un porteur à un autre, mais vous devez l’avoir sur vous pour conclure la transaction."}},faq={{q="Que demande le bon ?",a="Le client demande une Azure Silk Hood.",al={"bon pour capuche azur","quel objet est demandé","craftsman writ"}},{q="Où livrer la capuche ?",a="Le lieu de livraison est indiqué sur votre carte.",al={"lieu de livraison","où l’apporter","lieu indiqué"}},{q="De quoi ai-je besoin pour la transaction ?",a="Vous devez avoir l’objet demandé et le bon en votre possession.",al={"quoi apporter","bon nécessaire ?","conclure l’échange"}},{q="Le bon précise-t-il les modalités de paiement ?",a="La note contient des informations sur le paiement, mais le texte présenté ici n’en précise pas le montant.",al={"montant du paiement","conditions de paiement","que reçoit-on"}},{q="Quelqu’un d’autre peut-il porter le bon ?",a="Oui. Le bon porte la mention « transférable ».",al={"bon transférable","peut-on le transmettre","qui peut le détenir"}}},fp="33,144,17.225.0,27.42.0,28.44.0,35.60.0,36.91.0,32.40.0"}
P.entries["quest:94250"] = {n="Craftsman's Writ: Small Silk Pack",s="Un ordre transmissible demande un Small Silk Pack et précise les modalités de livraison et de paiement. Il est nécessaire pour conclure l’échange.",h="Un ordre transmissible demande un Small Silk Pack et précise les modalités de livraison et de paiement.",kw={"craftsman's writ","livraison","paiement","soie","small silk pack","transmissible","ordre"},sec={{t="L’ordre",b="Une note défraîchie d’un client vous demande un Small Silk Pack. Elle précise où livrer le paquet et comment le paiement sera effectué. L’ordre peut passer de main en main, mais vous devez l’avoir en votre possession pour conclure l’échange."}},faq={{q="Que demande l’ordre ?",a="Le client demande un Small Silk Pack.",al={"ordre pour small silk pack","objet demandé","commande de paquet de soie"}},{q="Où dois-je livrer le paquet ?",a="L’ordre indique les informations de livraison, et l’emplacement est marqué sur votre carte.",al={"lieu de livraison","où le livrer","où se trouve le point de dépôt"}},{q="Comment le paiement s’effectue-t-il ?",a="L’ordre contient des informations sur le paiement.",al={"combien vais-je recevoir","détails du paiement","quel est le paiement"}},{q="Puis-je transmettre l’ordre à quelqu’un d’autre ?",a="Oui. La note indique que l’ordre est transmissible.",al={"l’ordre est-il transmissible","céder l’ordre","le transmettre"}},{q="Ai-je besoin de l’ordre pour conclure l’échange ?",a="Oui. Vous devez avoir l’ordre en votre possession pour conclure la transaction.",al={"ordre nécessaire pour la remise","dois-je garder la note","ordre requis"}}},fp="33,141,8.220.0,27.42.0,28.79.0,23.44.0,40.44.0,44.70.0"}
P.entries["quest:94252"] = {n="Craftsman's Writ: Red Woolen Boots",s="Un ordre transmissible demande une paire de Red Woolen Boots et précise la livraison et le paiement. Vous devez l’avoir pour conclure l’échange.",h="Un ordre transmissible demande une paire de Red Woolen Boots et précise la livraison et le paiement.",kw={"bottes","craftsman's writ","livraison","paiement","red woolen boots","transmissible","ordre"},sec={{t="La demande écrite",b="Une note défraîchie vous demande de fournir une paire de Red Woolen Boots. Elle indique où les livrer et comment le paiement sera effectué. L’ordre est transmissible, mais vous devez l’avoir en votre possession pour conclure l’échange."}},faq={{q="Que demande l’ordre ?",a="L’ordre demande une paire de Red Woolen Boots.",al={"ordre pour les bottes rouges","quelles bottes sont demandées"}},{q="Où dois-je livrer les bottes ?",a="L’ordre indique le lieu de livraison, et l’emplacement marqué apparaît sur votre carte.",al={"lieu de livraison","où apporter les bottes rouges"}},{q="Comment le paiement est-il prévu ?",a="L’ordre contient des informations sur le paiement.",al={"paiement pour les bottes","combien seront-ils payés"}},{q="Puis-je transmettre cet ordre ?",a="Oui. La note indique que l’ordre est transmissible.",al={"ordre transmissible","quelqu’un d’autre peut-il le porter"}},{q="Dois-je avoir l’ordre pour conclure l’échange ?",a="Oui. Vous devez avoir l’ordre en votre possession pour conclure la transaction.",al={"avoir l’ordre sur soi","conclure la transaction"}}},fp="34,143,19.213.0,27.47.0,29.81.0,24.44.0,25.44.0,44.75.0"}
P.entries["quest:94253"] = {n="Commission d’artisan : kilt coloré",s="Un client cherche un déguisement pour s’infiltrer dans Zul'Gurub, et le bon de travail de l’artisan : Kilt coloré indique le vêtement souhaité.",h="Un client cherche un déguisement pour s’infiltrer dans Zul'Gurub, et le bon de travail de l’artisan : Kilt...",kw={"kilt coloré","bon de travail de l’artisan","livraison","déguisement","ritualiste","zul'gurub"},sec={{t="Un déguisement",b="Le bon transmissible vous demande d’apporter un Kilt coloré à l’endroit indiqué. Le client compte franchir les portes de Zul'Gurub déguisé en ritualiste, et affirme que le kilt convient à ce déguisement."}},faq={{q="Que demande le bon ?",a="Le bon demande un Kilt coloré, à livrer à l’endroit indiqué sur votre carte.",al={"bon pour kilt coloré","objet requis"}},{q="Pourquoi le client veut-il un kilt coloré ?",a="Le client compte s’infiltrer dans Zul'Gurub déguisé en ritualiste et affirme que le kilt l’aidera.",al={"pourquoi un kilt","déguisement en kilt"}},{q="Puis-je transférer ce bon ?",a="Oui. Le bon précise qu’il est transmissible.",al={"transférer un bon","céder un bon"}},{q="Où dois-je livrer le kilt ?",a="Le bon vous indique l’endroit marqué sur votre carte.",al={"lieu de livraison","où l’apporter"}}},fp="31,121,10.206.0,27.88.0,43.104.0,25.38.0,32.56.0"}
P.entries["quest:943"] = {n="Les absences du prospecteur",s="À Sombrivage, les fouilles de Songerrance lancent ses recherches par-delà la Grande mer. Au Port de Menethil, l’Archéologue Outrepanse espère réunir les découvertes de Songerrance, son propre fossile et la Pierre de Relu perdue pour révéler les pouvoirs cachés de ces reliques.",h="À Sombrivage, les fouilles de Songerrance lancent ses recherches par-delà la Grande mer.",kw={"sombrivage","explorers' league","outrepanse","fossile","menethil","songerrance","pierre de relu","les paluns","whelgar"},ang={["faction:Alliance"]="En tant qu’aventurier de l’Alliance, vous pouvez contribuer à relier les terres des elfes de la nuit de Sombrivage aux colonies naines autour du Port de Menethil, par-delà la mer, aux côtés des messagers de l’Alliance.",["race:Dwarf"]="En tant que nain, vous voyez l’Explorers' League à l’œuvre : elle relie des sites de fouilles éloignés à travers les continents pour reconstituer l’héritage nain et percer les mystères des titans."},sec={{t="Archéologie intercontinentale",b="Vous avez déjà aidé le Prospecteur Songerrance, distrait, lors d’une escorte dans le nord de Sombrivage. À présent, les recherches traversent la Grande mer jusqu’aux marécages des Paluns. Le Prospecteur Whelgar conserve le fossile d’origine d’Outrepanse sur son site de fouilles. Après avoir examiné les découvertes, l’Archéologue Outrepanse croit que la Pierre de Relu peut libérer les mystérieux pouvoirs des fossiles."},{t="Perdu dans les marais",b="Avant qu’Outrepanse puisse rencontrer Whelgar, des raptors tachetés ont pris sa caravane en embuscade sur la route et avalé la Pierre de Relu. Pour percer le mystère, Outrepanse a besoin que vous chassiez les bêtes, récupériez la pierre et rapportiez son fossile d’origine du camp de Whelgar. Une fois les deux fossiles et la clé réunis, les chercheurs nains espèrent découvrir la véritable origine et les pouvoirs des reliques."}},faq={{q="Pourquoi une quête de Sombrivage se termine-t-elle dans les Paluns ?",a="L’Explorers' League travaille à travers Kalimdor et les Royaumes de l'est. Le Chef archéologue Grisemoustache a envoyé le fossile de Songerrance depuis Sombrivage par-delà la mer à l’Archéologue Outrepanse, dans les Paluns. Leurs recherches communes relient les deux sites de fouilles.",al={"pourquoi une quête des paluns à sombrivage","lien avec le port de menethil","pourquoi envoyer dans les paluns"}},{q="Qu’est-ce que la Pierre de Relu ?",a="La Pierre de Relu est une relique ancienne récupérée par l’Archéologue Outrepanse. Il croit qu’elle peut servir de chiffre ou de catalyseur pour libérer les secrets magiques dormants conservés dans les fossiles mis au jour à Sombrivage et dans les Paluns.",al={"pierre de relu","qu’est-ce que la pierre de relu","artefact de relu"}},{q="Qui est l’Archéologue Outrepanse ?",a="L’Archéologue Outrepanse est un agent de l’Explorers' League naine, établi au Port de Menethil. Il étudie les reliques anciennes provenant des fouilles voisines et espère libérer le pouvoir caché des fossiles découverts par les Prospecteurs Songerrance et Whelgar.",al={"outrepanse","qui est outrepanse"}},{q="Qui détient le fossile d’origine ?",a="Le Prospecteur Whelgar conserve le fossile d’origine d’Outrepanse sur son site de fouilles dans les Paluns. Vous avez déjà apporté à Outrepanse le fossile de Songerrance, découvert à Sombrivage.",al={"où se trouve le fossile","qui détient le fossile de songerrance","fossile de whelgar"}},{q="Pourquoi les raptors ont-ils la Pierre de Relu ?",a="Alors qu’il voyageait sur la route des Paluns pour consulter le Prospecteur Whelgar, Outrepanse a été pris en embuscade par des raptors tachetés. Dans la confusion, l’une des bêtes a avalé la pierre tout entière.",al={"raptor ayant avalé une relique","pourquoi les raptors ont la pierre"}},{q="Que pensent les nains que les fossiles vont révéler ?",a="Outrepanse croit que les fossiles recèlent un pouvoir caché et des secrets du passé. Il pense que la Pierre de Relu est la clé qui permettra de les libérer.",al={"pouvoir du fossile","que révèle le fossile"}}},fx={["1568e7b3"]={q="À quoi sert le Fossile d'Outrepanse ?",a="Le Fossile d'Outrepanse est l'un des anciens spécimens récupérés par les fouilleurs nains, aux côtés de la pièce découverte par le Prospecteur Songerrance à Sombrivage. L'Archéologue Outrepanse pense que ces anciennes reliques contiennent un pouvoir magique dormant et des secrets oubliés, qu'il espère enfin libérer et déchiffrer en utilisant le pouvoir résonnant de la Pierre de Relu.",al={"fossile d'outrepanse","utilité du fossile d'outrepanse","qu'est-ce que le fossile d'outrepanse"}}},fp="28,229,29.366.0,19.376.1,48.246.0,26.221.0,31.241.0,28.162.0,38.172.0,45.133.0"}
P.entries["quest:94369"] = {n="The Fate of Zephras",s="À Valanaar, vous avertissez Talaanis Shadowsong du danger qui menace l’Île de Zéphras. Les protections tombées exposent l’île à Al'Akir, et ses habitants doivent décider comment protéger leur foyer.",h="À Valanaar, vous avertissez Talaanis Shadowsong du danger qui menace l’Île de Zéphras.",kw={"al'akir","elaadrin","lorthuna","sanctuaire d’akir","talaanis shadowsong","valanaar","protections","seigneur du vent","zéphras"},sec={{t="Un avertissement pour Talaanis",b="Vous racontez à Talaanis ce qui s’est passé au-dessus du Sanctuaire d’Akir. Vous lui faites part du plan d’Elaadrin de quitter l’Île de Zéphras. Le grand ancien Shadowsong doit comprendre le danger et pourquoi vous avez été envoyé en Azeroth. Les habitants de Zéphras doivent trouver un moyen de sauver leur foyer."},{t="Ce qu’il en reste",b="Talaanis réfléchit à ces nouvelles. Lorthuna a disparu, et le culte a perdu son chef. Zéphras n’a pas été envahie. Pourtant, Al'Akir pourrait s’intéresser à l’île dans quelques années ou quelques décennies, et la peur côtoie désormais les motifs de célébration."}},faq={{q="À qui dois-je parler ?",a="Vous parlez à Talaanis Shadowsong, à Valanaar.",al={"à qui parler","talaanis","où faire mon rapport"}},{q="Que dois-je dire à Talaanis ?",a="Vous racontez à Talaanis ce qui s’est passé au-dessus du Sanctuaire d’Akir et lui faites part du plan d’Elaadrin de quitter l’Île de Zéphras.",al={"ce qui s’est passé au sanctuaire","que dois-je rapporter","nouvelles du sanctuaire d’akir"}},{q="Pourquoi les habitants de Zéphras craignent-ils Al'Akir ?",a="Les protections qui dissimulaient Zéphras sont tombées. Al'Akir pourrait décider d’attaquer alors que ses habitants se trouvent dans son domaine.",al={"pourquoi craindre al'akir","danger du seigneur du vent","menace d’al'akir"}},{q="Que doit savoir le grand ancien Shadowsong ?",a="Le grand ancien Shadowsong doit connaître le danger et savoir ce que les habitants de Zéphras comptent faire lors de leur mission en Azeroth.",al={"ce que talaanis doit savoir","nouvelles pour le grand ancien","intentions pour azeroth"}}},fp="19,183,22.251.0,12.225.1,20.47.0,24.102.0,48.104.0,45.122.0"}
P.entries["quest:94373"] = {n="Call of Earth",s="À Courbenclume, Teo Hammerstorm met à l’épreuve les initiés qui cherchent la faveur de la terre. Ils affrontent les trolls Crine-de-givre au sud et rapportent des pendentifs d’ours avant de recevoir un Earth Sapta.",h="À Courbenclume, Teo Hammerstorm met à l’épreuve les initiés qui cherchent la faveur de la terre.",kw={"courbenclume","call of earth","vallée des frigères","totem de terre","crine-de-givre","pendentif d’ours crine-de-givre","ours griffe-de-glace","sapta","chaman","teo hammerstorm"},ang={["class:Shaman"]="En tant que chaman, vous commencez à communier avec les esprits de la pierre et du sol lors de cette initiation. Teo prépare un Earth Sapta pour vous.",["faction:Alliance"]="En tant que membre de l’Alliance, vous affrontez les trolls Crine-de-givre dans des grottes au sud de Courbenclume.",["race:Dwarf"]="En tant que nain, vous trouvez cette épreuve près de Courbenclume, dans la Vallée des Frigères. Elle unit votre héritage montagnard et votre endurance à la patience de la terre."},sec={{t="La sagesse de la pierre",b="Dans la Vallée des Frigères, Teo Hammerstorm guide les initiés de Courbenclume sur le rude chemin de la terre. Il apprend aux jeunes arpenteurs à écouter les montagnes et à voir la terre comme un sol ferme. La pierre peut protéger ceux qui la respectent. La terre ne partage sa sagesse qu’avec ceux qui font preuve de cran et de patience."},{t="Épreuve dans l’Antre Crine-de-givre",b="Pour prouver qu’ils sont prêts, les initiés affrontent les trolls Crine-de-givre dans une grotte au sud de Courbenclume. Les trolls confectionnent de grossiers pendentifs avec les ours Griffe-de-glace qui parcourent les hauteurs gelées. Rapporter deux pendentifs d’ours depuis l’antre prouve la détermination et la force que les esprits élémentaires attendent."},{t="L’Earth Sapta",b="Après que l’initié lui a présenté les pendentifs, Teo Hammerstorm loue la patience, la plus grande vertu de la terre. Elle résiste à l’écroulement des pics et aux rivières qui creusent les vallées. Teo prépare ensuite un Earth Sapta, qui permet à l’initié de percevoir et de suivre la véritable voie des éléments."}},faq={{q="Qui donne la quête Call of Earth ?",a="Teo Hammerstorm, un guide ancien de Courbenclume dans la Vallée des Frigères, propose l’épreuve. Il enseigne les voies de la pierre aux initiés et leur demande de prouver leur détermination aux esprits de la terre.",al={"qui donne call of earth","donneur de quête call of earth","quête teo hammerstorm"}},{q="Que vous demande Teo Hammerstorm ?",a="Vous partez au sud de Courbenclume, dans une grotte habitée par les trolls Crine-de-givre, et rapportez deux pendentifs d’ours Crine-de-givre. Les trolls les fabriquent avec des ours Griffe-de-glace, puis vous les rapportez à Teo Hammerstorm.",al={"objectifs de call of earth","que faut-il pour call of earth","quête des pendentifs crine-de-givre"}},{q="Où trouver les pendentifs d’ours Crine-de-givre ?",a="Les trolls Crine-de-givre portent les pendentifs dans une grotte au sud de Courbenclume. Ils fabriquent ces talismans avec des ours Griffe-de-glace et les portent dans leur antre.",al={"où trouver les pendentifs d’ours crine-de-givre","comment obtenir les pendentifs d’ours crine-de-givre","grotte crine-de-givre courbenclume"}},{q="Quelle récompense Teo Hammerstorm prépare-t-il une fois l’épreuve terminée ?",a="Teo prépare un Earth Sapta, une potion rituelle qui vous accorde aux esprits élémentaires. Elle vous permet de suivre la véritable voie de la terre.",al={"qu’est-ce qu’un sapta","earth sapta nain","que fabrique teo hammerstorm"}},{q="Pourquoi les initiés doivent-ils affronter les trolls Crine-de-givre ?",a="Affronter les trolls Crine-de-givre montre le cran et la résistance nécessaires pour communier avec la terre. Prendre les pendentifs d’ours dans leur antre prouve la détermination de l’initié.",al={"pourquoi tuer les trolls crine-de-givre","pourquoi les pendentifs crine-de-givre"}},{q="Qu’enseigne Teo Hammerstorm sur la nature de la terre ?",a="Teo enseigne que la patience est la plus grande vertu de la terre. Elle endure l’écroulement des montagnes et les rivières qui creusent les vallées. Il dit que la pierre protège ceux qui la respectent, même si le socle rocheux peut se déplacer lorsqu’on lui manque de respect.",al={"vertus de la terre teo hammerstorm","sagesse de la montagne"}}},fp="13,171,19.289.0,26.279.0,17.273.1,35.180.0,40.189.0,46.135.0,57.139.0,60.162.0,58.204.0"}
P.entries["quest:94374"] = {n="Call of Earth",s="Auprès d’une Spirit Stone de montagne, un initié boit l’Earth Sapta et lie son esprit aux fondations durables du monde. Le breuvage ouvre la voie à la conscience élémentaire et enseigne l’humilité et la patience au milieu de la neige et de la roche.",h="Auprès d’une Spirit Stone de montagne, un initié boit l’Earth Sapta et lie son esprit aux fondations durables...",kw={"call of earth","dun morogh","earth sapta","rite élémentaire","chemin secret","sapta","chaman","spirit stone"},ang={["class:Shaman"]="En tant que chaman, vous prenez part à une communion essentielle qui lie l’esprit à la pierre et vous accorde, grâce au breuvage rituel du sapta, une vision qui dépasse la perception des mortels.",["faction:Alliance"]="En tant que membre de l’Alliance, vous découvrez un rite élémentaire pratiqué au milieu de crêtes montagneuses enneigées, où les traditions chamaniques prennent racine sur les terres de l’Alliance.",["race:Dwarf"]="En tant que nain, vous entendez cette communion sacrée dans la cadence rude de votre peuple, au milieu de sommets montagneux gelés. Elle lie la communion avec la terre aux hauteurs enneigées de Dun Morogh."},sec={{t="Le breuvage de la vision",b="Dans un sanctuaire de montagne isolé, vous buvez l’Earth Sapta, un breuvage enchanté. Une ancienne magie élémentaire lui confère le pouvoir de révéler aux yeux des mortels les esprits élémentaires et les courants subtils qui échappent à la vue ordinaire. Sa puissance fait du sanctuaire le seul endroit où le boire en toute sécurité, afin que l’esprit et la pierre puissent s’unir."},{t="La Spirit Stone dans la neige",b="Haut sur une montagne balayée par la neige, la Spirit Stone attend au bout d’un Chemin secret isolé. Vous traversez un froid mordant pour vous tenir humblement devant l’antique roche. La terre vivante accueille ceux qui viennent sans orgueil. Les montagnes donnent une force physique durable, tandis que les vastes plaines immuables enseignent la patience."},{t="Force et quiétude",b="Communier avec la pierre est un rite fondamental pour les éclaireurs spirituels. Le vent, le feu et les eaux fracassantes portent une fureur agitée, tandis que la terre enseigne la discipline et une résilience tranquille. Vous absorbez l’essence immobile de la terre, préparant votre esprit et votre corps aux dualités conflictuelles et chaotiques des éléments plus instables qui grondent à travers le monde."}},faq={{q="Qu’est-ce que l’Earth Sapta ?",a="L’Earth Sapta est un puissant breuvage mystique, façonné par la magie pour lier directement l’esprit du pratiquant aux éléments. Il n’est pas destiné aux faibles de volonté. Le boire perce la vision ordinaire des mortels et révèle les esprits et les vérités élémentaires que les autres ne peuvent percevoir.",al={"qu’est-ce que le sapta","histoire de l’earth sapta","que fait le sapta"}},{q="Où faut-il boire le sapta ?",a="Vous devez boire le breuvage uniquement dans un site sacré dédié. Pour ce rite, vous remontez la montagne vers le nord en empruntant un Chemin secret afin de trouver l’antique Spirit Stone parmi les crêtes rocheuses.",al={"où boire le sapta","emplacement de la spirit stone","où se trouve la spirit stone"}},{q="Quel est le but du rite Call of Earth ?",a="Ce rite est une épreuve fondamentale de communion et d’humilité. À la Spirit Stone, boire le sapta vous apprend à puiser la force des montagnes et la patience des plaines. Il accorde votre esprit mortel au monde vivant avant que vous n’affrontiez des éléments plus tumultueux.",al={"pourquoi faire cette quête","signification de call of earth","histoire de call of earth"}},{q="Qui sait préparer l’Earth Sapta ?",a="Seuls quelques chamans initiés savent préparer le sapta. Sa préparation exige du savoir et une préparation spirituelle. Sa recette est gardée avec une grande révérence, car le breuvage relie directement la conscience des mortels aux forces primordiales.",al={"qui connaît la recette du sapta","qui peut préparer le sapta"}},{q="En quoi l’élément terre diffère-t-il des autres éléments ?",a="Les autres forces élémentaires s’entrechoquent, brûlent et grondent dans un tumulte violent, tandis que la terre apporte une quiétude inébranlable, de la patience et des fondations solides. Vous apprenez d’abord l’humilité devant la pierre, puis vous affrontez la double nature instable des autres éléments.",al={"la terre face aux autres éléments","la terre comparée au feu, à l’eau et à l’air"}},{q="Dans quel environnement ce rite a-t-il lieu ?",a="Le rite se déroule en haut d’une chaîne de montagnes froide et ensevelie sous la neige. Vous suivez un Chemin secret à travers la neige et la pierre pour communier avec les esprits de la terre malgré le gel mordant.",al={"où se déroule call of earth","quête de la terre en pays gelé"}}},fp="13,213,21.300.0,28.300.0,22.330.0,20.259.0,33.174.0,46.264.0,34.232.0,61.242.0,39.178.0"}
P.entries["quest:94375"] = {n="Call of Earth",s="Les jeunes chamans de Dun Morogh cherchent la faveur des esprits de la terre avec Call of Earth. Ils apportent du quartz brut à Teo Hammerstorm, à Courbenclume, où il le façonne en cœur de Totem de terre.",h="Les jeunes chamans de Dun Morogh cherchent la faveur des esprits de la terre avec Call of Earth.",kw={"courbenclume","call of earth","vallée des frigères","dun morogh","totem de terre","quartz brut","chaman","teo hammerstorm","totem"},ang={["class:Shaman"]="En tant que chaman, vous entamez votre chemin en communiant avec les esprits de la terre et en obtenant un Totem de terre.",["faction:Alliance"]="En tant que chaman de l’Alliance, vous trouverez des spiritualistes élémentaires prêts à vous guider aux alentours de Courbenclume, sur les terres de Forgefer.",["race:Dwarf"]="En tant que nain, vous pouvez unir les liens de votre peuple avec la pierre et la montagne à la voie du chaman en communiant avec les esprits de la terre à Dun Morogh."},sec={{t="La pierre murmurante",b="À Dun Morogh, les jeunes chamans entament leur chemin spirituel en cherchant l’esprit de la terre et en écoutant ses enseignements. L’esprit leur donne du quartz brut, une pierre modeste destinée à devenir le cœur d’un Totem de terre. Le rite exige humilité, patience, force et détermination. Un novice apprend de la terre et ne mesure pas la valeur à la taille."},{t="La faveur de la montagne",b="Teo Hammerstorm attend le novice à Courbenclume, qui doit lui rapporter le quartz brut. Il juge si les esprits de la montagne l’ont reconnu et renvoie quiconque se présente sans la pierre. Apportez-lui le quartz, et il le façonnera en Totem de terre. Le totem lie le jeune chaman à la force des racines du monde."}},faq={{q="À quoi sert le quartz brut ?",a="Un esprit de la terre vous donne du quartz brut comme preuve de communion. Teo Hammerstorm s’en sert pour fabriquer votre Totem de terre.",al={"utilité du quartz brut","qu’est-ce que le quartz brut","pourquoi ai-je besoin de quartz brut"}},{q="Qui est Teo Hammerstorm ?",a="Teo Hammerstorm est un mentor à Courbenclume, à Dun Morogh. Il met les aspirants chamans à l’épreuve en leur demandant une preuve de communion avec les éléments avant de fabriquer leurs totems.",al={"qui est teo hammerstorm","emplacement de teo hammerstorm","où se trouve teo"}},{q="Qu’est-ce que Call of Earth ?",a="Avec Call of Earth, les jeunes chamans cherchent à communier avec les esprits de la terre et obtiennent leur premier Totem de terre.",al={"quête call of earth","qu’est-ce que call of earth","quête du totem de terre"}},{q="Que demande l’esprit de la terre au novice ?",a="L’esprit de la terre vous demande de rester fort et patient dans votre quête de sagesse. Il enseigne que les petites choses peuvent durer plus longtemps que les autres et que le véritable pouvoir naît du respect mutuel avec la terre.",al={"leçon de l’esprit de la terre","que demande la terre","philosophie chamanique de la terre"}},{q="Où se trouve Courbenclume ?",a="Courbenclume se trouve dans la Vallée des Frigères, à Dun Morogh. Les jeunes novices nains s’y entraînent et communient avec les montagnes environnantes.",al={"qu’est-ce que courbenclume","histoire de courbenclume","où se déroule call of earth"}},{q="Pourquoi le Totem de terre est-il important ?",a="Un totem relie un chaman aux esprits élémentaires. Le Totem de terre lie votre volonté à la force inébranlable et à la résilience des montagnes.",al={"importance du totem","histoire des totems chamaniques","à quoi sert un totem de terre"}}},fp="13,190,20.342.0,20.329.0,29.111.0,23.159.0,26.107.0,47.186.0,26.129.0,33.140.0"}
P.entries["quest:944"] = {n="Le Glaive du Maître",s="Au Glaive du Maître, dans le sud de Sombrivage, Onu craint que le Marteau du crépuscule ait atteint l’antique horreur déchue. Il envoie des éclaireurs de l’Alliance enquêter.",h="Au Glaive du Maître, dans le sud de Sombrivage, Onu craint que le Marteau du crépuscule ait atteint l’antique...",kw={"sombrivage","le glaive du maître","ancien seigneur","onu","flasque de divination","scrying bowl","marteau du crépuscule"},ang={["class:Druid"]="En tant que druide, vous répondez à l’appel d’Onu pour découvrir comment la souillure antique enfouie au plus profond de la terre perturbe la contrée et sa faune.",["faction:Alliance"]="En tant que membre de l’Alliance, vous contribuez à empêcher le Marteau du crépuscule de réveiller des horreurs antiques qui pourraient déferler sur les colonies en difficulté du nord de Kalimdor.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous voyez dans le Glaive du Maître un rappel des terreurs plus anciennes que votre peuple. La profanation du sol sacré de Sombrivage par des sectateurs fous est intolérable."},sec={{t="Une présence inquiétante",b="Onu voit la corruption persister le long de Sombrivage, chassant la faune de ses repaires. Les nagas de la côte l’inquiètent, mais les signes du Marteau du crépuscule l’alarment davantage. Ses fidèles vénèrent les seigneurs primordiaux qui régnaient sur le monde avant leur chute, il y a des âges."},{t="Le seigneur déchu",b="Au sud de l’endroit où se trouve Onu, une sinistre excavation entoure une créature colossale transpercée par une immense arme de pierre. Onu vous remet une Flasque de divination et vous demande d’entrer dans la fosse pour découvrir si des sectateurs s’y sont rassemblés. Le béhémoth est mort depuis des éternités, mais un pouvoir corrupteur imprègne encore ses os. Le Marteau du crépuscule pourrait chercher à s’en emparer."}},faq={{q="Qui m’envoie accomplir cette mission ?",a="Onu, un ancien du savoir, vous envoie depuis son emplacement au bord de la route, dans le sud de Sombrivage, près du Bosquet des Anciens.",al={"donneur de quête","qui donne la quête du glaive du maître","pnj de départ"}},{q="Qu’est-ce que le Glaive du Maître ?",a="Dans le sud de Sombrivage, un seigneur antique monstrueux est tombé il y a des éternités, le crâne transpercé par un glaive de pierre titanesque. Son immense squelette pétrifié demeure enfoui dans la terre.",al={"qu’est-ce que le glaive du maître","histoire du glaive du maître","crâne géant à sombrivage"}},{q="Pourquoi la secte du Marteau du crépuscule s’intéresse-t-elle à ce lieu ?",a="Le Marteau du crépuscule vénère les anciennes puissances obscures d’Azeroth. Des fragments de pouvoir primordial subsistent dans les restes de la créature morte depuis longtemps, et les sectateurs cherchent à les maîtriser.",al={"secte du crépuscule à sombrivage","pourquoi les sectateurs du crépuscule sont ici","marteau du crépuscule glaive du maître"}},{q="Comment faire mon rapport à Onu ?",a="Après avoir exploré la fosse, utilisez la Flasque de divination dans vos sacs pour faire apparaître un Scrying Bowl au sol. Grâce à lui, vous pouvez parler à Onu par magie sans retourner le voir.",al={"où rendre la quête","comment utiliser la flasque de divination","scrying bowl"}},{q="Que se passe-t-il après cette mission d’éclaireur ?",a="Une fois que le Scrying Bowl confirme la présence des sectateurs, Onu vous envoie dans leur campement, à Twilight Camp, pour en apprendre davantage sur leurs activités.",al={"quête suivante","suite du glaive du maître"}}},fx={fcbe4ca5={q="Pourquoi Onu vous envoie-t-il enquêter sur le Glaive du Maître ?",a="Onu est profondément troublé par la présence du Marteau du crépuscule à Sombrivage. En tant qu'ancien du savoir veillant sur les bois, il sait que ce culte nihiliste vénère les Dieux très anciens vaincus de la terre. Le Glaive du Maître marque l'ancien lieu de repos de l'une de ces monstruosités déchues, et Onu craint que, même dans la mort, des vestiges du pouvoir sombre persistant de l'entité ne puissent être déterrés et utilisés par les cultistes.",al={"pourquoi onu veut-il cela","motif d'onu le glaive du maître","pourquoi explorer le glaive du maître"}},["821e537b"]={q="Qui êtes-vous envoyé enquêter au Glaive du Maître ?",a="Vous êtes envoyé pour reconnaître les cultistes du Marteau du crépuscule qui rôdent autour du monument massif. Ces fanatiques vénèrent des pouvoirs primordiaux et anciens qui régnaient autrefois sur Azeroth. Ils se sont rassemblés dans la fosse caverneuse du Glaive du Maître pour puiser dans toute essence mystérieuse ou force résiduelle rayonnant encore du crâne pétrifié de l'être ancien qui y a été tué.",al={"cible au glaive du maître","qui est-ce que je cherche au glaive du maître","qui est au glaive du maître"}},dfa4afd6={q="Pourquoi Onu a-t-il besoin que vous exploriez le Glaive du Maître plutôt que d'y aller lui-même ?",a="Onu est un ancien du savoir massif et enraciné qui ne peut pas facilement se glisser inaperçu dans le ravin profond du Glaive du Maître. De plus, les forces elfes de la nuit de Sombrivage sont débordées par la lutte contre les nagas qui empiètent le long de la côte et la corruption qui s'étend dans la nature. Un voyageur agile et capable, armé d'une Flasque de divination, peut explorer discrètement le campement des cultistes et faire un rapport magique sans attirer une attention indésirable.",al={"pourquoi moi onu","pourquoi m'envoyer au glaive du maître","pourquoi onu n'explore-t-il pas le glaive du maître"}}},fp="19,162,21.256.0,15.334.0,29.119.0,28.172.0,57.180.0,28.187.0,32.147.0"}
P.entries["quest:94411"] = {n="Meddlesome Mages",s="Dans les Hautes-terres de Shen’dar, des apprentis de l’Ordre suprême se rassemblent près de pierres sacrées et s’ingèrent dans la magie. Leurs sorts menacent les forces fragiles qui maintiennent l’île unie.",h="Dans les Hautes-terres de Shen’dar, des apprentis de l’Ordre suprême se rassemblent près de pierres sacrées...",kw={"ingérence arcanique","ordre suprême","apprentis de l’ordre suprême","meddlesome mages","hautes-terres de shen’dar","shen'dorei","pierres dressées"},ang={["class:Mage"]="En tant que Mage, vous voyez le danger des sorts inconsidérés de l’Ordre suprême. Leurs apprentis ignorent l’équilibre délicat qui maintient l’île unie."},sec={{t="Intrusion près des pierres",b="Au nord du village, des apprentis de l’Ordre suprême se rassemblent autour d’anciennes pierres dressées. Les avertissements répétés ne les ont pas détournés de ces sites sacrés. Ils poursuivent leurs études arcaniques, tandis que les dirigeants locaux hésitent à verser le sang de leurs congénères shen'dorei. Ils font donc appel à une aide extérieure pour chasser les apprentis avant qu’ils ne causent des dégâts durables."},{t="Une île fragile",b="De délicates forces mystiques lient les terres de l’île et la protègent. Les défenseurs craignent que l’Ordre suprême ne se soucie guère des dangers de ses sortilèges. Un seul sort imprudent pourrait rompre ces liens. Alors, tous ceux qui vivent là-bas seraient voués à la ruine."}},faq={{q="De quoi parle la quête Meddlesome Mages ?",a="On vous demande de chasser les apprentis de l’Ordre suprême rassemblés près de pierres dressées sacrées, au nord du village, dans les Hautes-terres de Shen’dar.",al={"de quoi parle meddlesome mages","quête meddlesome mages","de quoi parle cette quête"}},{q="Qui sont les apprentis de l’Ordre suprême ?",a="L’Ordre suprême est une faction de mages dont les apprentis ont ignoré les avertissements et profané un lieu sacré pour expérimenter la magie. Les habitants les considèrent comme des frères et sœurs shen'dorei.",al={"qui sont les apprentis de l’ordre suprême","qu’est-ce que l’ordre suprême","mages de l’ordre suprême"}},{q="Pourquoi faut-il disperser les apprentis de l’Ordre suprême ?",a="Les apprentis ont ignoré les avertissements répétés leur demandant d’éviter les pierres dressées. Leurs sortilèges inconsidérés menacent les forces fragiles qui lient l’île et pourraient détruire leur patrie.",al={"pourquoi disperser l’ordre suprême","pourquoi combattre les apprentis","problème des pierres dressées"}},{q="Où les apprentis de l’Ordre suprême se rassemblent-ils ?",a="Les apprentis de l’Ordre suprême se rassemblent près de pierres dressées au nord du village, dans les Hautes-terres de Shen’dar.",al={"où se trouve cette quête","emplacement des hautes-terres de shen’dar","pierres dressées au nord du village"}},{q="Qui sont les shen'dorei mentionnés dans la quête ?",a="Les shen'dorei sont apparentés aux habitants qui demandent de l’aide. Les conflits entre les leurs pèsent sur les dirigeants locaux, mais ils se sentent obligés d’agir contre l’Ordre suprême pour protéger leur patrie.",al={"qui sont les shen'dorei","frères et sœurs shen'dorei","que sont les shen'dorei"}},{q="Quel danger les mages représentent-ils pour l’île ?",a="De délicates forces maintiennent l’île unie, et elles sont vulnérables. Une ingérence arcanique sans entrave pourrait les briser et détruire l’île.",al={"quel est le danger","forces fragiles de l’île","que pourrait-il arriver à l’île"}}},fp="16,168,26.347.0,18.259.0,41.133.0,35.191.0,49.195.0,47.100.0,46.196.0,44.133.0"}
P.entries["quest:94413"] = {n="A Magical Affront",s="Sur Zephras, A Magical Affront oppose l’ordre local aux Sculpte-vents. L’ordre cherche à exploiter et à étudier les lignes telluriques apparues à la surface, tandis que les Sculpte-vents les voient comme des cicatrices à soigner. Leur conflit a gagné la forêt du sud-ouest.",h="Sur Zephras, A Magical Affront oppose l’ordre local aux Sculpte-vents.",kw={"a magical affront","arcanes","ligne tellurique","lignes telluriques","cicatrices","sculpte-vents","zephras"},ang={["class:Druid"]="En tant que druide, vous pourriez ressentir la tension dans la façon dont les Sculpte-vents voient les lignes telluriques exposées comme des blessures à soigner sur les terres naturelles.",["class:Mage"]="En tant que mage, vous pourriez voir les lignes telluriques apparues à la surface de Zephras comme une occasion rare d’étudier directement l’énergie mystique brute. Leur préservation compte pour votre art des arcanes.",["class:Shaman"]="En tant que chaman, vous pourriez partager le souci des Sculpte-vents pour la protection des éléments et de la nature, tandis qu’ils cherchent à apaiser et à soigner les perturbations sur Zephras. Leurs objectifs les opposent ainsi aux ordres qui exploitent les flux de magie brute."},sec={{t="Courants dévoilés",b="D’anciens conduits de magie brute ont récemment percé la terre sur Zephras. Pour les érudits et les pratiquants de l’ordre local, c’est une aubaine rare. Le contact direct avec les lignes telluriques leur révèle de nouvelles perspectives sur les courants arcaniques de la région et approfondit leur maîtrise de la magie."},{t="Cicatrices et conflits",b="Les Sculpte-vents voient les énergies exposées comme des plaies ouvertes et des cicatrices sur Zephras. Ils se rassemblent sur les sites de rupture pour réprimer ou réparer les lignes telluriques et soigner la terre.\n\nL’ordre dépend de cette puissance brute et considère donc leurs efforts comme une menace. Il vous envoie au sud-ouest, dans la forêt, pour repousser les Sculpte-vents."}},faq={{q="Qui sont les Sculpte-vents ?",a="Les Sculpte-vents sont un groupe de Zephras qui voit les lignes telluriques apparues à la surface comme des blessures contre nature dans le paysage. Ils cherchent à les soigner, ce qui les oppose aux ordres qui étudient et canalisent les lignes telluriques.",al={"qui sont les sculpte-vents","que sont les sculpte-vents","sculpte-vents zephras"}},{q="Pourquoi l’ordre veut-il repousser les Sculpte-vents ?",a="L’ordre a besoin d’accéder aux lignes telluriques apparues à la surface pour approfondir sa compréhension de la magie. Les Sculpte-vents tentent de les réprimer ou de les réparer. L’ordre considère donc leurs efforts comme une menace et vous envoie les repousser.",al={"pourquoi tuer les sculpte-vents","pourquoi combattre les sculpte-vents","conflit des sculpte-vents"}},{q="Que sont les lignes telluriques de Zephras ?",a="Les lignes telluriques sont des conduits d’énergie mystique qui traversent le monde. Sur Zephras, elles ont récemment percé la terre, exposant la magie brute et permettant aux praticiens des arcanes de l’étudier directement.",al={"que sont les lignes telluriques de zephras","lignes telluriques zephras","lignes telluriques à la surface"}},{q="Où se trouve la ligne tellurique contestée ?",a="La ligne tellurique contestée se trouve dans la forêt, au sud-ouest de Zephras. Les Sculpte-vents s’y sont rassemblés pour refermer ou réparer le déferlement de magie exposé.",al={"où se trouve la forêt des lignes telluriques","emplacement de la ligne tellurique","forêt au sud-ouest"}},{q="Pourquoi les Sculpte-vents considèrent-ils les lignes telluriques comme des cicatrices ?",a="Les Sculpte-vents voient la rupture soudaine de l’énergie brute souterraine à travers la terre comme de violentes cicatrices sur Zephras. Ils pensent que réparer ces déchirures rétablira l’équilibre naturel, ce qui les oppose aux lanceurs de sorts qui veulent laisser les lignes telluriques ouvertes.",al={"pourquoi les sculpte-vents veulent-ils soigner les lignes telluriques","les lignes telluriques sont-elles nocives sur zephras","soigner les cicatrices"}},{q="Quelle est l’importance de Zephras dans ce conflit ?",a="C’est sur Zephras que les lignes telluriques ont récemment émergé à la surface. Leur magie brute a fait de la région un point de tension entre ceux qui cherchent à maîtriser sa puissance arcanique et ceux qui voient ces brèches comme des blessures à soigner.",al={"qu’est-ce que zephras","où se déroule a magical affront","lore de zephras"}}},fp="17,236,17.287.0,16.313.0,24.195.0,51.208.0,33.200.0,39.139.0,51.254.0,53.214.0"}
P.entries["quest:94414"] = {n="The Anchors of Zephras",s="Sur l’Île de Zéphras, Halaan Hawk-Eye vous demande de surveiller les anciens pylônes d’ancrage qui maintiennent l’île dans les airs. Leur magie vacille, et la bénédiction des esprits du vent pourrait faiblir.",h="Sur l’Île de Zéphras, Halaan Hawk-Eye vous demande de surveiller les anciens pylônes d’ancrage qui...",kw={"pylône d’ancrage","ancres de zéphras","halaan hawk-eye","lignes telluriques","vision céleste","esprits du vent","zéphras"},ang={["class:Mage"]="En tant que mage, vous reconnaissez la vue perçante de Halaan comme un don naturel.",["class:Shaman"]="En tant que chaman, vous savez que la bénédiction des esprits du vent soutient les pylônes d’ancrage. Leur magie instable mérite l’attention d’un élémentaire."},sec={{t="Les amarres de l’île",b="Les esprits du vent ont donné aux anciens pylônes d’ancrage de Zéphras le pouvoir de lier et de soutenir l’île flottante. Leur magie maintient la terre stable au milieu des cieux tourmentés. De loin, les imposants monolithes semblent intacts. Pourtant, l’île dépend toujours de la bénédiction des esprits du vent."},{t="Un changement inquiétant",b="Les pylônes d’ancrage semblent fiers et intacts, mais leur magie est devenue irrégulière. Halaan Hawk-Eye dit que l’harmonie qui les soutient est devenue instable et incertaine. Aucun signe manifeste de dommage physique n’est visible. Ceux qui veillent sur les bosquets ont raison de craindre ce qui menace l’île."},{t="Le don de Halaan",b="Halaan Hawk-Eye ne peut pas utiliser la vision céleste pour voir au-delà des mondes, ni puiser dans les profondes lignes telluriques de Zéphras. Son don est une vue naturelle assez perçante pour porter à d’immenses distances. Il prête cette vue aux nouveaux venus afin qu’ils puissent étudier les pylônes lointains et surveiller le destin changeant de leur terre natale."}},faq={{q="Que sont les pylônes d’ancrage de Zéphras ?",a="Les pylônes d’ancrage sont d’anciennes structures que les esprits du vent ont offertes à Zéphras. Ils lient et soutiennent l’île, la maintenant stable au-dessus du monde alentour.",al={"que sont les ancres","pylône d’ancrage de zéphras","qu’est-ce qu’un pylône d’ancrage"}},{q="Qu’est-ce qui ne va pas avec les pylônes d’ancrage ?",a="Les pylônes ne présentent aucun dommage physique évident, mais leur magie stabilisatrice est devenue instable et irrégulière. La cause reste inconnue.",al={"pourquoi les ancres faiblissent","problème des pylônes d’ancrage","qu’est-il arrivé aux ancres"}},{q="Qui est Halaan Hawk-Eye ?",a="Halaan Hawk-Eye veille sur les bosquets de l’Île de Zéphras. Sa vue naturelle porte très loin, et il veille au bien-être de la terre.",al={"histoire de halaan","qui est halaan"}},{q="Quel est le don de Halaan ?",a="Le don de Halaan est une vue exceptionnellement perçante qui porte très loin. C’est une vision naturelle, différente de la vision céleste ou du pouvoir de puiser dans les profondes lignes telluriques de Zéphras.",al={"don de halaan","comment halaan voit si loin"}},{q="Qu’est-ce que la vision céleste ?",a="La vision céleste est une perception mystique qui permet à certains adeptes de voir au-delà des mondes, bien plus loin que la vue ordinaire.",al={"qu’est-ce que la vision céleste","signification de vision céleste"}},{q="D’où vient la magie qui alimente les pylônes ?",a="Les esprits du vent ont offert les pylônes d’ancrage à Zéphras. Halaan dit qu’ils lient et soutiennent l’île, mais n’explique pas d’où vient leur pouvoir constant.",al={"qui a créé les pylônes","origine des pylônes d’ancrage"}}},fx={["61bc2f74"]={q="Pourquoi Halaan Hawk-Eye veut-il que vous regardiez le pylône d'ancrage ?",a="Halaan Hawk-Eye veille sur le bosquet et se soucie profondément de la santé de Zéphras. Les anciens pylônes d'ancrage, cadeaux des esprits des vents, lient et soutiennent l'île, mais leur magie est devenue récemment instable et irrégulière. Bien qu'ils semblent physiquement intacts, Halaan propose de partager sa vision lointaine afin que vous puissiez constater par vous-même l'état des pylônes et comprendre l'état délicat de votre patrie.",al={"motif de halaan","pourquoi regarder le pylône d'ancrage","pourquoi halaan veut-il cela"}}},fp="22,192,19.274.0,18.282.0,13.287.0,38.155.0,37.135.0,23.142.0,22.148.0,17.114.0,51.159.0"}
P.entries["quest:94427"] = {n="A Lesson in Divinity",s="Votre ordre vous envoie auprès de Tanis Alderwood, dans le Trade Quarter de Fossoyeuse. L’occasion de faire preuve de grâce se présente par de bonnes actions.",h="Votre ordre vous envoie auprès de Tanis Alderwood, dans le Trade Quarter de Fossoyeuse.",kw={"a lesson in divinity","divinité","grâce","quête d’aumône","tanis alderwood","trade quarter","fossoyeuse"},ang={["class:Priest"]="En tant que prêtre, votre ordre définit la divinité comme le fait de faire le bien pour lui-même. Il dit qu’une tragédie peut menacer la grâce qui vous définissait de votre vivant."},sec={{t="Un appel à la grâce",b="Votre ordre enseigne que la divinité consiste à faire le bien pour lui-même, et non à chercher à devenir un dieu. Il dit qu’une tragédie vous a conduit ici. À présent, il vous demande de retrouver Tanis Alderwood dans le Trade Quarter de Fossoyeuse. Tanis a besoin d’aide et pourrait bénéficier de votre grâce."},{t="La supplication de Tanis",b="Quand vous approchez de Tanis Alderwood, cette personne craint que vous lui fassiez du mal. Elle insiste sur le fait qu’elle n’a aucun différend avec vous ni avec votre ordre. Puis elle vous supplie de la laisser tranquille."}},faq={{q="Qui est Tanis Alderwood ?",a="Tanis Alderwood est une personne dans le besoin, dans le Trade Quarter de Fossoyeuse.",al={"tanis","qui est tanis","personne du trade quarter"}},{q="Pourquoi m’envoie-t-on auprès de Tanis ?",a="Votre ordre dit que Tanis Alderwood pourrait bénéficier de votre grâce.",al={"pourquoi tanis","aider tanis","quel est le but"}},{q="Que signifie la divinité pour mon ordre ?",a="Votre ordre définit la divinité comme le fait de faire le bien pour lui-même, plutôt que de chercher à devenir un dieu.",al={"sens de la divinité","faire le bien pour lui-même","qu’est-ce que la divinité"}},{q="Où puis-je trouver Tanis Alderwood ?",a="Vous trouverez Tanis Alderwood dans le Trade Quarter de Fossoyeuse.",al={"emplacement de tanis","où est tanis","trade quarter"}}},fp="20,127,16.244.0,14.156.1,23.66.0,23.60.0,36.88.0,33.60.0"}
P.entries["quest:94434"] = {n="A Lesson in Divinity",s="À Fossoyeuse, Tanis Alderwood vous demande du linge propre. Sa femme se désagrège, et il espère l'envelopper en attendant qu'un apothicaire se libère.",h="À Fossoyeuse, Tanis Alderwood vous demande du linge propre.",kw={"a lesson in divinity","apothicaires","mendiant","dame noire","linge de lin","tanis alderwood","fossoyeuse","femme"},sec={{t="La supplique d'un mendiant",b="Les apothicaires sont occupés par les affaires de la Dame noire. Tanis vous demande donc du linge pour sa femme. Il espère que le tissu la maintiendra en un seul morceau en attendant de l'aide."}},faq={{q="Qui demande de l'aide ?",a="Tanis Alderwood, un mendiant de Fossoyeuse, vous demande d'aider sa femme.",al={"qui est tanis","tanis alderwood","le mendiant"}},{q="Que se passe-t-il avec la femme de Tanis ?",a="Tanis dit qu'elle se désagrège littéralement et qu'il lui faut un bandage pour la maintenir en un seul morceau.",al={"sa femme se désagrège","qu'est-il arrivé à sa femme","la femme de tanis"}},{q="Pourquoi les apothicaires ne peuvent-ils pas aider ?",a="Tanis dit que les apothicaires sont occupés par les affaires de la Dame noire.",al={"apothicaires occupés","pourquoi pas d'apothicaire","affaires de la dame noire"}},{q="De quoi Tanis a-t-il besoin ?",a="Tanis vous demande d'apporter du linge propre pour envelopper sa femme en attendant les apothicaires.",al={"quel linge lui faut-il","lin pour tanis","aider le mendiant"}}},fp="20,140,15.175.0,23.70.0,31.84.0,32.71.0,21.97.0"}
P.entries["quest:94435"] = {n="A Lesson in Divinity",s="Tanis Alderwood vous remercie de votre aide et vous considère comme un ami. Danitha Morr voit dans ce petit geste un moyen de renforcer le lien des Réprouvés avec la Lumière.",h="Tanis Alderwood vous remercie de votre aide et vous considère comme un ami.",kw={"a lesson in divinity","danitha morr","dame noire","réprouvés","lumière","méfiance","symbole","tanis alderwood"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous entendez Danitha décrire les efforts des Réprouvés pour aider leur peuple à prospérer de nouveau.",["race:Undead"]="En tant que Réprouvé, vous entendez Danitha appeler au courage et à la droiture pour aider votre peuple à prospérer de nouveau."},sec={{t="Un petit service",b="Danitha Morr dit que votre aide pourrait renforcer le lien des Réprouvés avec la Lumière. La méfiance et les conspirations persistent parmi les fidèles de la Dame noire. Les Réprouvés doivent répondre à cette peur par le courage et la droiture. Danitha vous donne un symbole pour What Comes Next."}},faq={{q="Qui me remercie ?",a="Tanis Alderwood vous remercie de l’avoir aidé et dit que vous aurez toujours un ami en lui.",al={"tanis alderwood","qui est tanis","tanis remercie"}},{q="Que signifie mon aide, selon Danitha ?",a="Danitha dit que même un petit geste de service peut renforcer le lien des Réprouvés avec la Lumière.",al={"pourquoi aider danitha","sens d’un petit geste","lien avec la lumière"}},{q="Pourquoi Danitha parle-t-elle de méfiance ?",a="Danitha dit que la Dame noire et certains de ses serviteurs se méfient d’eux, et que certains conspirent même contre eux.",al={"méfiance des réprouvés","peur de la dame noire","pourquoi se méfient-ils d’eux"}},{q="Que me donne Danitha ?",a="Un symbole de Danitha, pour What Comes Next.",al={"quel symbole","objet de danitha","symbole pour la suite"}}},fp="20,173,15.265.0,19.89.0,36.97.0,34.107.0,26.43.0"}
P.entries["quest:94436"] = {n="A Lesson in Divinity",s="Dans A Lesson in Divinity, Danitha Morr vous demande de montrer ce qu’un prêtre peut faire avec le Symbole de vie. Le garde de la mort Billmuth, à la Forteresse de Bandarion, cherche de l’aide pour un ami.",h="Dans A Lesson in Divinity, Danitha Morr vous demande de montrer ce qu’un prêtre peut faire avec le Symbole de...",kw={"a lesson in divinity","forteresse de bandarion","danitha morr","garde de la mort billmuth","réprouvés","lumière","prêtre","symbole de vie"},ang={["class:Priest"]="En tant que prêtre, vous devez montrer à Danitha votre capacité à canaliser la Lumière avec le Symbole de vie."},sec={{t="Un appel à l’aide",b="Billmuth dit que les prêtres l’ont renvoyé et que son ami n’a peut-être personne d’autre vers qui se tourner. Il n’est pas fier de vous le demander, mais il a besoin d’aide pour les Réprouvés. Le Symbole de vie doit montrer votre capacité à canaliser la Lumière. Le manipuler peut causer un malaise. Son pouvoir peut tout de même être votre allié et votre guide, même auprès des Réprouvés, dont la création est liée à une force opposée à la Lumière."}},faq={{q="Qui demande de l’aide ?",a="Le garde de la mort Billmuth, à la Forteresse de Bandarion, cherche de l’aide pour un ami.",al={"aider billmuth","qui a besoin d’aide"}},{q="Pourquoi Billmuth demande-t-il l’aide d’un prêtre ?",a="Billmuth dit que les prêtres l’ont renvoyé et que vous êtes peut-être la seule chance de son ami.",al={"pourquoi un prêtre","les prêtres l’ont renvoyé"}},{q="Qu’est-ce que le Symbole de vie ?",a="Le Symbole de vie est un talisman de la Lumière que Danitha Morr vous confie pour montrer votre capacité à canaliser la Lumière.",al={"symbole de vie","talisman de la lumière"}},{q="Pourquoi le Symbole de vie pourrait-il être douloureux à manipuler ?",a="Danitha vous avertit que le talisman peut causer un malaise, car la Lumière s’oppose à la force qui a créé les Réprouvés.",al={"douleur du symbole","la lumière fait mal"}},{q="Où trouver le garde de la mort Billmuth ?",a="Le garde de la mort Billmuth se trouve à l’étage inférieur de la Forteresse de Bandarion.",al={"emplacement de billmuth","forteresse de bandarion"}}},fp="20,173,14.380.0,23.73.0,31.83.0,27.116.0,44.121.0,37.52.0"}
P.entries["quest:94438"] = {n="A Lesson in Divinity",s="Danitha Morr vous envoie dans la Vallée de Tissevenin retrouver Deathguard Falgan. Ils ont été séparés après avoir appris que la Croisade écarlate préparait une attaque contre Brill.",h="Danitha Morr vous envoie dans la Vallée de Tissevenin retrouver Deathguard Falgan.",kw={"a lesson in divinity","billmuth","brill","danitha morr","deathguard falgan","croisade écarlate","symbole de vie","vallée de tissevenin"},sec={{t="Le retour de Falgan",b="Deathguard Falgan est parti avec Billmuth repérer l’activité de la Croisade écarlate dans la Vallée de Tissevenin. Ils ont appris qu’elle préparait une attaque. Falgan vous demande maintenant si vous aiderez davantage les Réprouvés."}},faq={{q="Qui me demande de retrouver Falgan ?",a="Danitha Morr vous demande de retrouver Deathguard Falgan et de l’aider si vous le pouvez.",al={"qui m’a envoyé","danitha morr","donneur de quête"}},{q="Où se trouve Falgan ?",a="Falgan se trouve dans la Vallée de Tissevenin.",al={"emplacement de falgan","où est falgan","retrouver deathguard"}},{q="Qu’est-il arrivé à Falgan ?",a="Falgan est resté en arrière après qu’un bruit l’a trahi, lui et son compagnon, auprès des forces de la Croisade écarlate. Son compagnon a atteint Brill sans lui.",al={"falgan a disparu","que s’est-il passé","sauver falgan"}},{q="Qu’ont découvert Falgan et Billmuth ?",a="Falgan et Billmuth ont appris que la Croisade écarlate préparait une attaque.",al={"ordres des écarlates","qu’ont-ils découvert","plans d’attaque"}},{q="À quoi sert le Symbole de vie ?",a="Le Symbole de vie sert à ramener Deathguard Falgan à la vie.",al={"ressusciter falgan","symbole de vie","comment sauver falgan"}},{q="Que demande Falgan après son retour ?",a="Après son retour, Falgan vous demande si vous êtes prêt à aider davantage les Réprouvés.",al={"aider les réprouvés","quelle est la suite","falgan demande"}}},fp="20,163,15.200.0,32.72.0,16.27.0,24.124.0,38.79.0,31.67.0,37.82.0"}
P.entries["quest:94440"] = {n="A Lesson in Divinity",s="Le garde de la mort Billmuth vous demande de récupérer les plans d’attaque de la Croisade écarlate dans la Vallée de Tissevenin. La garde de la mort s’attend à un assaut et espère que les plans l’aideront à préparer une embuscade.",h="Le garde de la mort Billmuth vous demande de récupérer les plans d’attaque de la Croisade écarlate dans la...",kw={"a lesson in divinity","plans d’attaque","forteresse de bandarion","garde de la mort billmuth","réprouvés","croisade écarlate","vallée de tissevenin"},sec={{t="Ordres pour la forteresse",b="Les croisés écarlates transportent des ordres de déploiement dans leurs sacoches, et la garde de la mort s’attend à une attaque. Apportez une copie des plans au garde de la mort Billmuth, à la forteresse de Bandarion. La garde de la mort pourra alors préparer une embuscade."},{t="Un ami sauvé",b="Billmuth vous remercie d’avoir sauvé son ami et dit qu’il apportera les plans à son commandant. Vos actes lui ont montré que vous êtes un Réprouvé jusqu’au bout des ongles, malgré la méfiance que certains des siens éprouvent envers votre classe."}},faq={{q="De quoi Billmuth a-t-il besoin ?",a="Le garde de la mort Billmuth vous demande de récupérer les plans d’attaque de la Croisade écarlate dans la Vallée de Tissevenin.",al={"que veut billmuth","plans de billmuth","plans pour billmuth"}},{q="Où se trouvent les plans d’attaque ?",a="Les croisés écarlates de la Vallée de Tissevenin transportent les plans d’attaque.",al={"où sont les plans","emplacement des plans écarlates","trouver les plans d’attaque"}},{q="Pourquoi la garde de la mort veut-elle les plans ?",a="La garde de la mort s’attend à une attaque et veut les plans pour préparer une embuscade.",al={"pourquoi récupérer les plans","à quoi servent les plans","embuscade de la garde de la mort"}},{q="À qui faut-il remettre les plans ?",a="Apportez les plans au garde de la mort Billmuth, à la forteresse de Bandarion.",al={"qui reçoit les plans","rapporter les plans à","où est billmuth"}}},fp="20,172,19.209.0,14.221.1,24.94.0,27.62.0,39.81.0,29.57.0"}
P.entries["quest:94441"] = {n="A Lesson in Divinity",s="Un Réprouvé vous demande de remercier Danitha Morr pour le service rendu par les paladins à la Forteresse de Bandarion. Votre travail a gagné la gratitude de la Garde funeste et vous vaut un don de rédemption.",h="Un Réprouvé vous demande de remercier Danitha Morr pour le service rendu par les paladins à la Forteresse de...",kw={"a lesson in divinity","forteresse de bandarion","danitha morr","garde funeste","réprouvés","lumière","rédemption","symbole de vie"},sec={{t="Remerciements à la forteresse",b="Un Réprouvé vous demande de transmettre ses remerciements à Danitha Morr, à la Forteresse de Bandarion. Le reste de la Garde funeste entendra parler du service que vous et les autres paladins avez rendu. Ils sont fiers de vous compter parmi les Réprouvés et savent que la Dame noire veille sur vous."},{t="Un don de lumière",b="Danitha affirme qu’un paladin prêt à recevoir l’une des plus grandes bénédictions de la Lumière peut utiliser le Symbole de vie. Elle vous accorde le don de rédemption, qui vous permet de ressusciter vos compagnons tombés au combat. Votre service compte pour les Réprouvés comme pour les paladins de la Forteresse de Bandarion. La Garde funeste espère que de tels actes gagneront le cœur et l’esprit des autres Réprouvés."}},faq={{q="Qui dois-je remercier ?",a="Vous devez remercier Danitha Morr pour le service rendu par les paladins à la Forteresse de Bandarion.",al={"qui est danitha","remercier danitha","danitha morr"}},{q="Qui sera mis au courant du service ?",a="Le reste de la Garde funeste sera informé du service rendu par les paladins à la Forteresse de Bandarion.",al={"remerciements de la garde funeste","qui sera informé","service à la forteresse"}},{q="À quoi sert le Symbole de vie ?",a="Un paladin prêt à recevoir l’une des plus grandes bénédictions de la Lumière peut utiliser le Symbole de vie.",al={"symbole de vie","à quoi sert-il"}},{q="Pourquoi la Garde funeste est-elle fière de moi ?",a="La Garde funeste est fière de vous compter parmi les Réprouvés et apprécie le service que vous avez rendu avec les paladins de la Forteresse de Bandarion.",al={"fierté des réprouvés","pourquoi être fier","fierté de la garde funeste"}}},fp="20,178,18.262.0,15.335.1,15.82.0,32.82.0,32.101.0,34.129.0"}
P.entries["quest:94449"] = {n="Call of Fire",s="À Dun Morogh, un ancien envoie les initiés chamans auprès de Bruegs Kindleborn pour éprouver leur préparation au Sapta de feu.",h="À Dun Morogh, un ancien envoie les initiés chamans auprès de Bruegs Kindleborn pour éprouver leur préparation...",kw={"bruegs kindleborn","call of fire","dun morogh","earth sapta","totem de feu","sapta de feu","chaman","avant-poste de la porte sud"},ang={["class:Shaman"]="En tant que chaman, vous traversez une épreuve spirituelle qui vous mène de l’endurance de la pierre à la puissance farouche et destructrice du feu.",["faction:Alliance"]="En tant que chaman de l’Alliance, vous suivez les conseils de vos anciens dans les montagnes de Dun Morogh pour éveiller votre communion avec les éléments du feu.",["race:Dwarf"]="En tant que nain, vous traversez cette épreuve haut au-dessus de l’Avant-poste de la porte sud, à Dun Morogh, où votre discipline est mise à l’épreuve face à la faim brûlante de la flamme."},sec={{t="L’épreuve ardente",b="Après avoir prouvé leur patience et leur ancrage dans la terre, les chamans affrontent une force plus volatile : l’esprit élémentaire du feu. La pierre reste stable, mais le feu promet chaos, ruine et énergie farouche. Un ancien envoie donc l’initié à travers les pics enneigés de Dun Morogh chercher conseil avant de tenter de maîtriser sa chaleur sauvage."},{t="L’ermite des cimes",b="Bruegs Kindleborn veille dans une grotte isolée, haut dans les montagnes au-dessus de l’Avant-poste de la porte sud. Lorsqu’un initié arrive avec la recommandation d’un ancien, Bruegs le prépare au Sapta de feu. Il le met en garde : la flamme a faim de brûler et de consumer, et cette faim s’éveille facilement. Pour la maîtriser, un chaman doit savoir quand se retenir."}},faq={{q="Qui est Bruegs Kindleborn ?",a="Bruegs Kindleborn guide les chamans dans une grotte de montagne, haut au-dessus de l’Avant-poste de la porte sud, à Dun Morogh. Les anciens lui envoient des initiés, et il juge s’ils ont la maturité et la discipline nécessaires pour recevoir le Sapta de feu.",al={"qui est bruegs kindleborn","histoire de bruegs kindleborn","où se trouve bruegs"}},{q="Qu’est-ce que le Sapta de feu ?",a="Un sapta est une décoction ou une préparation élémentaire qui permet à un chaman de communier avec les esprits de cet élément. Le Sapta de feu ouvre la communion avec les flammes et leur puissance brute. Il exige une grande concentration et un ancrage préalable dans la pierre.",al={"qu’est-ce que le sapta de feu","sapta de feu","signification de sapta"}},{q="Où se trouve Bruegs Kindleborn ?",a="Bruegs Kindleborn vit loin à l’est, dans les montagnes enneigées de Dun Morogh, à l’abri dans une grotte qui surplombe l’Avant-poste de la porte sud.",al={"où trouver bruegs kindleborn","grotte de l’avant-poste de la porte sud","où rendre call of fire"}},{q="Quel est le but de Call of Fire ?",a="Call of Fire place les chamans qui ont fait preuve de patience et maîtrisé la terre face au pouvoir chaotique de la destruction. Bruegs Kindleborn veille sur leur épreuve.",al={"qu’est-ce que call of fire","quête du totem de feu à dun morogh"}},{q="Pourquoi un chaman doit-il apprendre les leçons de la pierre avant celles du feu ?",a="La terre enseigne la patience inébranlable, la stabilité et la maîtrise. Sans l’ancrage de la pierre, un chaman risque d’être submergé par la faim instable du feu et ses passions destructrices.",al={"pourquoi commencer par la pierre","se souvenir des leçons de la pierre"}},{q="Quelles conditions faut-il remplir avant d’entreprendre Call of Fire ?",a="Avant ce rite, un initié a fait preuve de patience et d’ancrage dans la terre au cours d’épreuves précédentes. L’ancien n’envoie un élève auprès de Bruegs Kindleborn que lorsque sa discipline est solidement établie.",al={"prérequis de call of fire","lien avec la quête de patience"}}},fp="12,175,17.311.0,24.321.0,25.214.0,26.225.0,35.122.0,40.155.0,57.173.0,68.186.0"}
P.entries["quest:94465"] = {n="Call of Fire",s="Vous portez la Torche de la flamme dormante à travers Loch Modan pour trouver Braldir Ashmantle. L’épreuve détermine si un initié est prêt à manier la flamme élémentaire.",h="Vous portez la Torche de la flamme dormante à travers Loch Modan pour trouver Braldir Ashmantle.",kw={"braldir ashmantle","call of fire","totem de feu","loch modan","chaman","autel de la flamme dormante","torche de la flamme dormante","vallée des rois"},ang={["class:Shaman"]="Futur chaman, vous prouvez votre dévouement aux esprits élémentaires du feu en portant une torche sacrée jusqu’à un sommet isolé de Loch Modan.",["faction:Alliance"]="Dans les terres de l’Alliance, les voyageurs ordinaires ne voient que la pierre nue des montagnes. Les gardiens de l’autel protègent des regards ordinaires d’anciens secrets élémentaires.",["race:Dwarf"]="En tant que nain, vous entendez parler nain tandis que le sentier vous mène au-delà de la Vallée des rois, dans les crags escarpés de Khaz Modan."},sec={{t="Après la Vallée des rois",b="Pour gagner le Totem de feu, vous portez la Torche de la flamme dormante éteinte dans les crags de Loch Modan. Au-delà des sculptures de pierre de la Vallée des rois, un sentier escarpé grimpe jusqu’à un sommet isolé. Là, les éléments règnent, loin des routes connues des voyageurs."},{t="L’Autel de la flamme dormante",b="Braldir Ashmantle veille sur l’Autel de la flamme dormante, au sommet d’un pic élevé balayé par les vents. Les vagabonds mal préparés et les chasseurs de fortune n’y trouvent que silence et pierre nue. Mais quand vous arrivez en véritable initié, porteur de la torche sacrée, Braldir révèle le pouvoir élémentaire endormi dans le brasero de l’autel, qui attend d’être ravivé."}},faq={{q="Qu’est-ce que la quête Call of Fire ?",a="Call of Fire est une épreuve pour l’initié qui cherche à gagner un Totem de feu. Vous vous rendez dans les crags de Loch Modan et apportez la Torche de la flamme dormante à Braldir Ashmantle, sur un sommet sacré.",al={"qu’est-ce que call of fire","quête de chaman feu loch modan","quête du totem de feu"}},{q="Qui est Braldir Ashmantle ?",a="Braldir Ashmantle garde l’Autel de la flamme dormante, dans les hauteurs des crags de Loch Modan. Il renvoie les voyageurs ordinaires et les chercheurs de trésors, et accueille ceux qui portent la Torche de la flamme dormante.",al={"qui est braldir ashmantle","gardien de l’autel loch modan"}},{q="Où se trouve l’Autel de la flamme dormante ?",a="L’Autel de la flamme dormante se trouve dans les hauteurs des crags de Loch Modan. Un Chemin secret y serpente au-delà de la Vallée des rois.",al={"où se trouve l’autel de la flamme dormante","emplacement de la flamme dormante"}},{q="À quoi sert la Torche de la flamme dormante ?",a="Les initiés portent la Torche de la flamme dormante pour prouver leur sincérité et leur aptitude à communier avec le feu élémentaire. Braldir Ashmantle exige que vous la présentiez avant de vous recevoir.",al={"qu’est-ce que la torche de la flamme dormante","rôle de la torche de la flamme dormante"}},{q="Pourquoi le postulant doit-il se rendre à Loch Modan ?",a="Vous vous rendez à Loch Modan, car le sommet élémentaire isolé où se trouve l’Autel de la flamme dormante s’élève au-delà de la Vallée des rois, loin des voyageurs de passage.",al={"pourquoi aller à loch modan","pourquoi l’autel du feu est-il à loch modan"}},{q="Comment gagner le Totem de feu au terme de cette épreuve ?",a="Après avoir rejoint Braldir Ashmantle et prouvé votre détermination avec la torche, vous allumez le brasero de l’autel. Vous repartez avec la flamme allumée et gagnez le Totem de feu.",al={"que se passe-t-il après avoir trouvé braldir","comment obtenir le totem de feu"}}},fp="12,157,35.270.0,31.328.0,31.202.0,25.204.0,49.124.0,54.195.0,45.165.0,48.166.0"}
P.entries["quest:94466"] = {n="Call of Fire",s="À Loch Modan, les initiés recherchent la Flamme éternelle et le totem de feu qu’elle leur accorde. Braldir Ashmantle les guide dans une épreuve qui exige des composants prélevés sur les kobolds et les troggs. Ils préparent un sapta de feu et apprennent que la flamme peut forger et donner la vie autant que détruire.",h="À Loch Modan, les initiés recherchent la Flamme éternelle et le totem de feu qu’elle leur accorde.",kw={"braldir ashmantle","call of fire","flamme éternelle","sapta de feu","goudron de feu","totem de feu","loch modan","stonesplinter seer","tunnel rat geomancer"},ang={["class:Shaman"]="Pour communier avec les esprits du feu et rechercher la Flamme éternelle, vous créez un lien élémentaire grâce à un sapta de feu. Cette voie mène au Totem de feu.",["faction:Alliance"]="Sur les terres de l’Alliance, vous affrontez les menaces locales des troggs et des kobolds en prenant part aux rites chamaniques de Loch Modan.",["race:Dwarf"]="En tant que nain, vous trouvez Braldir Ashmantle qui guide les initiés à Loch Modan. Pour lui, le feu est le souffle de la forge et de la création, et non une simple force de destruction."},sec={{t="Le chemin vers la flamme",b="À Loch Modan, Braldir Ashmantle guide les initiés en quête du pouvoir de la flamme. Avant de communier avec les esprits du feu, ils doivent harmoniser leur esprit mortel avec une préparation sacrée appelée sapta de feu. Sans elle, la Flamme éternelle les consumerait au lieu de les éclairer. Braldir demande à chaque postulant de récupérer deux composants auprès des habitants hostiles de la vallée et de prouver sa détermination."},{t="Composants de terre et d’étincelle",b="Un sapta de feu nécessite des substances riches en puissance élémentaire. Au nord, les Tunnel Rat Geomancers récoltent du goudron de feu visqueux dans leurs terriers pour alimenter leur magie souterraine. Au sud, les Stonesplinter Seers transportent dans les collines des Reagent Pouches remplis de charmes élémentaires primitifs. S’emparer de ces objets signifie affronter deux des fléaux les plus tenaces de Loch Modan et obtenir ce qu’il faut pour lier l’âme d’un initié à la flamme."},{t="La sagesse qui tempère",b="Une fois les composants rassemblés, Braldir Ashmantle enseigne la patience autant que le pouvoir de détruire. Pour lui, le feu ne se résume pas à la fureur et aux cendres. Il est la vie, l’art de la forge et le souffle de la création. La maîtrise exige l’équilibre : l’ombre donne son sens à la lumière, et la flamme empêche la pierre de n’être qu’un froid souvenir. Pour maîtriser le feu, un initié doit apprendre quand unir plutôt que brûler."}},faq={{q="Quel est le but de Call of Fire ?",a="Les aspirants chamans entreprennent Call of Fire pour chercher à communier avec la Flamme éternelle. Ils préparent d’abord un sapta de feu pour lier leur esprit mortel à l’élément.",al={"qu’est-ce que call of fire","quelle est cette quête","but de call of fire"}},{q="Qui est Braldir Ashmantle ?",a="Braldir Ashmantle guide les initiés à Loch Modan. Il leur enseigne l’équilibre du feu et prépare un sapta de feu après qu’ils ont rassemblé les composants nécessaires.",al={"qui donne call of fire","qui est braldir ashmantle","emplacement de braldir ashmantle"}},{q="Qu’est-ce qu’un sapta de feu ?",a="Un sapta de feu est une préparation composée de composants liés à la flamme. Il harmonise et lie l’esprit d’un chaman au feu, rendant possible la communion avec la Flamme éternelle.",al={"qu’est-ce qu’un sapta de feu","à quoi sert un sapta","pourquoi faut-il un sapta"}},{q="Où trouve-t-on le goudron de feu ?",a="Les Tunnel Rat Geomancers transportent du goudron de feu dans leurs grottes, au nord de Loch Modan. Ils l’utilisent dans leurs arts primitifs du feu.",al={"où trouver du goudron de feu","emplacement du goudron de feu","goudron de feu dans les grottes kobolds"}},{q="Où trouve-t-on le sac de composants des Stonesplinter ?",a="Les Stonesplinter Seers transportent des Reagent Pouches dans les collines du sud de Loch Modan. Ces mystiques troggs s’en servent pour garder des composants liés à la magie élémentaire.",al={"où trouver un reagent pouch","sac des stonesplinter seers","emplacement du sac des stonesplinter"}},{q="Comment Braldir Ashmantle voit-il l’élément du feu ?",a="Braldir enseigne que le feu est plus que destruction : il est la forge, la vie et le souffle de la création. En équilibre avec les autres forces, il tempère la pierre froide et donne chaleur et sens à l’existence.",al={"vision du feu de braldir","sens du feu à loch modan","philosophie du feu des nains"}}},fp="12,263,21.387.0,31.422.0,23.387.0,36.157.0,25.144.0,21.164.0,28.119.0,47.147.0,52.193.0"}
P.entries["quest:94467"] = {n="Call of Fire",s="Le Call of Fire est une épreuve où un initié boit du sapta de feu au sanctuaire. Le rite lui demande de soumettre un esprit et d’offrir ses braises au brasero sacré.",h="Le Call of Fire est une épreuve où un initié boit du sapta de feu au sanctuaire.",kw={"brasero","call of fire","sapta de feu","braise rougeoyante","minor manifestation of fire","épreuve du chaman","shrine of eternal flame"},ang={["class:Shaman"]="En tant que chaman, vous entreprenez une épreuve fondamentale de communion avec le feu. Le sapta sacré vous permet de percevoir et d’affronter les esprits de la flamme."},sec={{t="Le rite de la flamme",b="Un initié reçoit du sapta de feu préparé selon le savoir élémentaire. Le breuvage éveille ses sens au monde invisible. Après avoir bu au sanctuaire, il grimpe vers le sommet, où le regard des mortels cède la place aux forces primordiales. Là, une manifestation de feu dormante attend qu’il la défie."},{t="Face à la manifestation",b="La Minor Manifestation of Fire met à l’épreuve la détermination et l’endurance de l’initié. Elle n’attaque pas avant d’être provoquée, puis devient plus féroce à chaque instant. Une fois soumise, elle cède des braises rougeoyantes. Apportez-les au brasero au sommet du Shrine of Eternal Flame pour allumer la torche et gagner la faveur durable de l’esprit."}},faq={{q="Qu’est-ce que le Call of Fire ?",a="Le Call of Fire est un rite sacré au cours duquel un initié boit du sapta de feu préparé, affronte un esprit de flamme et offre sa braise à un brasero pour gagner la faveur du feu.",al={"qu’est-ce que le call of fire","quête call of fire","épreuve du totem de feu"}},{q="À quoi sert le sapta de feu ?",a="Le sapta de feu est un breuvage préparé qui ouvre la vision spirituelle de l’initié et lui révèle l’esprit élémentaire qui l’attend au sommet de la montagne.",al={"but du sapta de feu","pourquoi boire du sapta","effet du sapta"}},{q="Quel esprit apparaît pendant l’épreuve ?",a="Une Minor Manifestation of Fire attend l’initié au sommet. Elle ne combat que si on la frappe.",al={"quel esprit affronter","créature du call of fire","manifestation de feu"}},{q="Pourquoi faut-il vaincre rapidement l’esprit du feu ?",a="L’esprit élémentaire devient plus féroce et plus ardent à mesure que le combat se prolonge. Une attaque rapide et décisive peut le soumettre avant que ses flammes ne submergent l’initié.",al={"pourquoi frapper vite","combat du call of fire","délai de l’esprit du feu"}},{q="Que faire des braises rougeoyantes ?",a="Après avoir vaincu la Minor Manifestation of Fire, apportez ses braises rougeoyantes au brasero au sommet du Shrine of Eternal Flame pour allumer la torche rituelle.",al={"où apporter les braises","brasero du call of fire","brasero du shrine of eternal flame"}},{q="Que signifie gagner la faveur du feu ?",a="Allumer la torche vous vaut la faveur directe des élémentaires du feu et vous permet de communier avec eux. Le rite établit un lien avec les flammes.",al={"quelle est la récompense","que donne le rituel","faveur du feu"}}},fp="12,165,17.289.0,24.311.0,25.159.0,38.135.0,37.96.0,45.150.0,37.157.0,40.124.0"}
P.entries["quest:94468"] = {n="Call of Fire",s="Au-dessus de Loch Modan, un initié allume la flamme qui doit atteindre Dun Morogh. Bruegs Kindleborn attend son retour et juge sa maîtrise des éléments.",h="Au-dessus de Loch Modan, un initié allume la flamme qui doit atteindre Dun Morogh.",kw={"bruegs kindleborn","call of fire","dun morogh","totem de feu","enfant de la flamme","loch modan","chaman","torche de la flamme éternelle"},ang={["class:Shaman"]="En tant que chaman, vous accomplissez l'épreuve du feu à Khaz Modan et obtenez le Totem de feu. Il vous permet de canaliser les flammes et de communier avec les esprits du feu.",["faction:Alliance"]="Dans les terres de l'Alliance, à Khaz Modan, les vocations spirituelles prennent racine. Bruegs Kindleborn guide les nouveaux initiés dans leur apprentissage des arts élémentaires.",["race:Dwarf"]="En tant que nain, vous transportez la flamme des hauteurs au-dessus de Loch Modan jusqu'à Dun Morogh. Ce voyage unit votre quête spirituelle aux forces élémentaires de votre foyer montagnard."},sec={{t="La flamme au-dessus du Loch",b="Un initié allume la Torche de la flamme éternelle sur une crête montagneuse au-dessus de Loch Modan. Cette flamme marque le début d'un lien plus profond avec les éléments. De là, l'initié la transporte par les sentiers, jusqu'aux vallées enneigées de Dun Morogh."},{t="La récompense de l'enfant de la flamme",b="À Dun Morogh, Bruegs Kindleborn attend le voyageur. Mentor élémentaire, il juge si le feu intérieur du voyageur a pris racine. La torche flamboyante prouve la volonté de l'initié et sa vénération du feu. Bruegs lui remet alors le Totem de feu et accueille l'enfant de la flamme dans une lignée de guides élémentaires pour les siens."}},faq={{q="Qu'est-ce que Call of Fire ?",a="Call of Fire est une épreuve spirituelle destinée aux chamans de Khaz Modan. L'initié allume la Torche de la flamme éternelle à un brasero qui surplombe Loch Modan, puis la transporte à travers les montagnes jusqu'à Bruegs Kindleborn, à Dun Morogh.",al={"qu'est-ce que call of fire","quête call of fire","que faut-il faire dans call of fire"}},{q="Qui est Bruegs Kindleborn ?",a="Bruegs Kindleborn est un mentor élémentaire qui vit à Dun Morogh. Il veille sur les rites du feu et remet leur Totem de feu aux initiés qui accomplissent le voyage.",al={"qui est bruegs kindleborn","où se trouve bruegs kindleborn","emplacement de bruegs kindleborn"}},{q="Qu'est-ce que la Torche de la flamme éternelle ?",a="La Torche de la flamme éternelle est une torche cérémonielle allumée à un brasero qui surplombe Loch Modan. Elle symbolise le lien d'un initié avec le feu élémentaire et doit être transportée sans encombre jusqu'à Bruegs Kindleborn, à Dun Morogh.",al={"qu'est-ce que la torche de la flamme éternelle","torche de la flamme éternelle","où obtenir la torche"}},{q="Que reçoit-on en terminant cette épreuve ?",a="Lorsque vous apportez la Torche de la flamme éternelle sans encombre à Bruegs Kindleborn, il reconnaît votre esprit ardent et vous remet votre Totem de feu. Ce totem vous marque comme enfant de la flamme.",al={"quelle récompense pour call of fire","obtient-on le totem de feu","totem call of fire"}},{q="Où se déroule ce voyage ?",a="Le voyage commence sur un promontoire au-dessus de Loch Modan, où la torche est allumée. Le sentier de montagne mène à Dun Morogh, où Bruegs Kindleborn vous attend.",al={"où se déroule call of fire","itinéraire de call of fire","où apporter la torche"}},{q="Pourquoi Bruegs mentionne-t-il Madoran ?",a="Bruegs mentionne Madoran dans un serment, en référence à Madoran Bronzebeard. C'était le chef nain vénéré qui dirigeait le clan Bronzebeard pendant la War of the Three Hammers.",al={"pourquoi par la barbe de madoran","signification de madoran","qui est le madoran mentionné par bruegs"}}},fp="12,162,23.241.0,22.320.0,25.218.0,25.156.0,35.200.0,47.173.0,35.148.0,32.169.0"}
P.entries["quest:94480"] = {n="A Gift From Our Enemies",s="Vous apportez du fourrage volé à Gorg, à Rog’mar, pour nourrir ses alliés. Les gnolls des environs et le Twilight qui gagne du terrain menacent le campement.",h="Vous apportez du fourrage volé à Gorg, à Rog’mar, pour nourrir ses alliés.",kw={"alliés","ferme","gnolls","gorg","ragoût consistant","rog’mar","fourrage volé","twilight"},sec={{t="Du fourrage pour Rog’mar",b="Gorg vous attend à Rog’mar avec le fourrage volé que vous avez récupéré. Les humains ne sont pas la seule menace des environs : des gnolls grondent dans les collines, et le Twilight gagne du terrain. Nourrir les alliés de Rog’mar pourrait les aider à préserver leurs forces."},{t="Un ragoût consistant",b="Le fourrage dégage une odeur âcre et terreuse, avec une note désagréable. Gorg reconnaît que vous l’avez pris à la ferme et affirme qu’il fera un ragoût consistant pour les alliés."}},faq={{q="Pourquoi Gorg veut-il le fourrage volé ?",a="Gorg utilisera le fourrage volé pour préparer un ragoût consistant aux alliés de Rog’mar.",al={"pourquoi du fourrage","fourrage de gorg","à quoi sert le fourrage volé"}},{q="Quelles menaces rôdent près de Rog’mar ?",a="Les humains représentent une menace, tandis que des gnolls grondent dans les collines voisines et que le Twilight gagne du terrain.",al={"gnolls à proximité","menace du twilight","que trouve-t-on près de rog’mar"}},{q="Qui est Gorg ?",a="Gorg est celui qui reçoit le fourrage volé à Rog’mar et affirme qu’il peut en faire un ragoût consistant.",al={"qui est gorg"}},{q="Où dois-je apporter le fourrage volé ?",a="Apportez le fourrage volé à Gorg, à Rog’mar.",al={"emplacement du fourrage","où apporter le fourrage","emplacement de gorg"}}},fp="23,134,16.224.0,13.177.1,35.73.0,30.92.0,12.91.0,32.40.0"}
P.entries["quest:94481"] = {n="A Serving of Strength",s="Un instructeur vous demande de nourrir les recrues Rog’mar sur le terrain d’entraînement. Le ragoût les rassasie tandis qu’il devient difficile de défendre les lignes de ravitaillement.",h="Un instructeur vous demande de nourrir les recrues Rog’mar sur le terrain d’entraînement.",kw={"une ration de force","recrues rog’mar","ragoût","lignes de ravitaillement","recrues","terrain d’entraînement","guerriers"},sec={{t="De quoi nourrir les recrues",b="Les recrues sur le terrain d’entraînement ont besoin de nourriture, et leur instructeur vous envoie avec un copieux ragoût. Vous devez nourrir les recrues Rog’mar à l’ouest. Leurs plaintes peuvent attendre ; défendre les lignes de ravitaillement est devenu difficile, et les guerriers vous sont reconnaissants pour la nourriture que vous apportez."}},faq={{q="Qui a besoin de ragoût ?",a="Les recrues Rog’mar sur le terrain d’entraînement ont besoin de ragoût.",al={"qui a faim","qui est nourri","nourriture des recrues"}},{q="Où dois-je apporter le ragoût ?",a="Les recrues Rog’mar se trouvent sur le terrain d’entraînement à l’ouest.",al={"où nourrir les recrues","emplacement des recrues","où trouver le ragoût"}},{q="Pourquoi leur donne-t-on du ragoût ?",a="Le ragoût nourrit les recrues tandis qu’il est devenu difficile de défendre les lignes de ravitaillement.",al={"pourquoi du ragoût","à quoi sert la nourriture","pourquoi nourrir les recrues"}},{q="Que pense l’instructeur des plaintes des recrues ?",a="L’instructeur dit que les recrues peuvent lui adresser directement toute nouvelle plainte.",al={"plaintes des recrues","pourquoi se plaignent-elles","instructeur en colère"}},{q="L’instructeur est-il reconnaissant pour la nourriture ?",a="Oui. L’instructeur et les guerriers sont reconnaissants pour la nourriture, malgré ce que disent les guerriers.",al={"l’instructeur apprécie-t-il cela","remerciements pour le ragoût","guerriers reconnaissants"}}},fp="21,149,17.274.0,19.57.0,25.63.0,28.86.0,56.80.0,37.91.0"}
P.entries["quest:94483"] = {n="Show Them How It's Done",s="Un commandant vous envoie au sud de la rivière pour frapper les camps d’entraînement de Farholde. L’assaut doit retenir les humains près de leur donjon et donner du temps aux autres affaires.",h="Un commandant vous envoie au sud de la rivière pour frapper les camps d’entraînement de Farholde.",kw={"farholde","humains","donjon","prêtres","rivière","éclaireurs","camps d’entraînement"},sec={{t="Au bord de la rivière",b="Le commandant vous dirige vers les camps de Farholde au sud de la rivière, où des éclaireurs ont signalé des forces humaines. Il vous demande d’abattre les Farholde Priests et les Farholde Scouts. Retenir les humains près de leur donjon donnera au commandant le temps de s’occuper d’autres affaires."}},faq={{q="Qui me demande d’attaquer les camps ?",a="Un commandant qui a reçu des rapports d’éclaireurs sur des camps d’entraînement au sud de la rivière vous envoie contre les forces de Farholde.",al={"qui a donné cet ordre","demande du commandant"}},{q="Où se trouvent les camps de Farholde ?",a="Les camps d’entraînement se trouvent au sud de la rivière.",al={"où sont les camps","lieu de farholde"}},{q="Qui dois-je prendre pour cible ?",a="Le commandant désigne les Farholde Priests et les Farholde Scouts comme cibles.",al={"qui tuer","cibles"}},{q="Pourquoi attaquer les humains ?",a="Retenir les humains près de leur donjon doit donner du temps au commandant pour s’occuper d’autres affaires.",al={"pourquoi combattre les humains","quel est le but"}},{q="Que se passe-t-il après l’attaque ?",a="Le commandant dit que l’opération a été rapide et compte poursuivre ailleurs.",al={"quelle est la suite","après les camps"}}},fp="23,160,12.264.0,37.119.0,29.42.0,28.72.0,22.96.0,30.74.0"}
P.entries["quest:94484"] = {n="Unnerving Silence",s="Dans le nord-est de la Forêt de Trombenoire, une enclave de druides s'est tue. Depuis que Ban'aethall est tombé en ruine, les troubles gagnent la région.",h="Dans le nord-est de la Forêt de Trombenoire, une enclave de druides s'est tue.",kw={"ban'aethall","druide","conclave de druides","elegael thornpaw","forêt de trombenoire","unnerving silence"},ang={["class:Druid"]="En tant que druide, vous pouvez vous inquiéter pour vos frères et sœurs et pour l'équilibre de la nature lorsqu'une enclave isolée de la Forêt de Trombenoire se tait. Retrouver Elegael Thornpaw pourrait révéler ce qui a troublé leur communion."},sec={{t="Silence sous la canopée",b="Depuis que Ban'aethall est tombé en ruine, les troubles agitent la région. Les messages réguliers du conclave de druides, installé dans une grotte au nord-est de la Forêt de Trombenoire, ont cessé. Leurs alliés n'ont plus de nouvelles, et leur inquiétude grandit à mesure que la forêt se trouble."},{t="À la recherche de l'enclave",b="On vous envoie dans le nord-est de la Forêt de Trombenoire pour retrouver Elegael Thornpaw, une druidesse éminente de l'enclave. Le conclave s'est-il retiré pour communier plus profondément avec la nature, ou les dangers qui ont ravagé Ban'aethall ont-ils atteint la grotte ? Personne ne connaît le sort de l'enclave."}},faq={{q="De quoi parle la quête Unnerving Silence ?",a="On vous demande de découvrir pourquoi les messages d'un conclave de druides de la Forêt de Trombenoire ont cessé. Fouillez la grotte au nord-est de la forêt et découvrez ce qui est arrivé à cet ordre isolé.",al={"quête unnerving silence","qu'est-ce que unnerving silence"}},{q="Où trouver Elegael Thornpaw ?",a="Elegael Thornpaw se trouve dans une grotte au nord-est de la Forêt de Trombenoire. Elle est l'interlocutrice du conclave de druides isolé qui s'y trouve.",al={"où se trouve elegael thornpaw","emplacement d'elegael thornpaw","trouver thornpaw"}},{q="Qui est Elegael Thornpaw ?",a="Elegael Thornpaw appartient au conclave de druides installé dans une grotte au nord-est de la Forêt de Trombenoire. Son silence et l'absence des messages prévus suscitent des inquiétudes quant à la sécurité de l'enclave.",al={"qui est elegael thornpaw","histoire de thornpaw"}},{q="Qu'est-ce que la Forêt de Trombenoire ?",a="La Forêt de Trombenoire est une vaste étendue boisée qui abrite un conclave secret de druides dans une grotte au nord-est. Depuis la chute de Ban'aethall et les troubles qui ont gagné la région, les contacts avec les habitants de la forêt sont devenus incertains.",al={"qu'est-ce que la forêt de trombenoire","conclave de la forêt de trombenoire"}},{q="Qu'est-ce que Ban'aethall ?",a="Ban'aethall était un village situé au cœur de la Forêt de Trombenoire, aujourd'hui en ruine. Sa destruction et les troubles qui agitent la région font craindre pour les camps voisins, notamment celui du conclave de Trombenoire.",al={"qu'est-il arrivé à ban'aethall","histoire des ruines de ban'aethall","chute de ban'aethall"}},{q="Pourquoi le conclave de druides s'est-il tu ?",a="Les messages et rapports réguliers des druides de la Forêt de Trombenoire ont cessé sans explication. Ban'aethall étant en ruine et la tension montant, leurs alliés craignent qu'un désastre ou des forces hostiles aient pris le dessus sur l'enclave.",al={"pourquoi les druides ont-ils cessé d'envoyer des messages","pourquoi les druides se taisent"}}},fp="17,142,21.259.0,19.271.0,42.188.0,36.131.0,24.183.0,26.223.0,20.193.0,39.222.0"}
P.entries["quest:94485"] = {n="Tears of the Lady",s="À Trombenoire, la mousse Lady's Tear pourrait maintenir en vie les compagnons blessés d'Elegael. Ils sont piégés dans Nightclaw Den, et Elegael a besoin de remèdes tirés des arbres voisins.",h="À Trombenoire, la mousse Lady's Tear pourrait maintenir en vie les compagnons blessés d'Elegael.",kw={"elegael","lady's tear","mousse","nightclaw den","cataplasme","trombenoire","tears of the lady"},ang={["class:Priest"]="En tant que prêtre, vous canalisez la Lumière pour soigner les blessures des mortels. Les cataplasmes naturels comme Lady's Tear peuvent panser les plaies lorsque les soins magiques ne suffisent plus.",["profession:Herbalism"]="En tant qu'herboriste, vous connaissez Lady's Tear pour sa sécrétion antiseptique et collante. Elle peut lier les chairs à vif et aider à prévenir les infections en pleine nature."},sec={{t="Remèdes désespérés à Trombenoire",b="Elegael a besoin de votre aide à Trombenoire. Des compagnons blessés sont piégés dans Nightclaw Den, grièvement atteints et dans l'attente de secours. Les fournitures ordinaires se font rares, alors vous récoltez des remèdes dans les bois alentour. Leurs blessures ne peuvent attendre."},{t="La mousse médicinale",b="Elegael a besoin de Lady's Tear, une mousse grêle qui s'accroche à la base des arbres de Trombenoire. Sa sécrétion est visqueuse et collante, et possède des propriétés antiseptiques naturelles. Elle referme les plaies béantes et empêche les blessures traumatiques de s'aggraver dans cette nature humide. Avec assez de mousse, Elegael pourra préparer des pansements pour stabiliser les blessés."}},faq={{q="De quoi parle la quête Tears of the Lady ?",a="Elegael a besoin d'aide pour soigner des compagnons blessés piégés dans Nightclaw Den. Récoltez de la mousse Lady's Tear à Trombenoire afin qu'Elegael puisse préparer un cataplasme pour les maintenir en vie.",al={"qu'est-ce que tears of the lady","infos sur la quête tears of the lady"}},{q="Qu'est-ce que Lady's Tear ?",a="Lady's Tear est une mousse grêle qui pousse près de la base des arbres de Trombenoire. Sa sécrétion est visqueuse et collante, et possède des propriétés antiseptiques naturelles qui peuvent refermer les plaies béantes.",al={"qu'est-ce que lady's tear","mousse lady's tear","qu'est-ce que la mousse lady's tear"}},{q="Qui est Elegael ?",a="Elegael organise les secours médicaux à Trombenoire. Des compagnons blessés sont piégés dans Nightclaw Den, et Elegael a besoin de fournitures pour les soigner.",al={"qui est elegael","donneur de quête tears of the lady"}},{q="Qu'est-ce que Nightclaw Den ?",a="Nightclaw Den est l'endroit où plusieurs alliés blessés d'Elegael sont bloqués près de Trombenoire. Leur état est précaire tandis qu'Elegael cherche des ingrédients médicinaux.",al={"qu'est-ce que nightclaw den","où se trouve nightclaw den"}},{q="Pourquoi Elegael a-t-il besoin de mousse Lady's Tear ?",a="Elegael a besoin de la sécrétion antiseptique de Lady's Tear pour préparer un cataplasme. Cette substance visqueuse et collante referme les plaies béantes et empêche les blessures traumatiques de s'aggraver.",al={"pourquoi avoir besoin de lady's tear","que fait la mousse"}},{q="Où trouve-t-on la mousse Lady's Tear ?",a="Lady's Tear s'accroche à la base des arbres de Trombenoire. Elegael a récolté tout ce qui était à portée immédiate, et d'autres mousses se trouvent dans les bois alentour.",al={"où pousse lady's tear","trouver lady's tear"}}},fp="17,157,32.238.0,16.312.0,42.164.0,20.178.0,15.135.0,26.156.0,39.165.0,32.153.0"}
P.entries["quest:94486"] = {n="Feathers for Binding",s="Dans la Forêt de Trombenoire, les guérisseurs ont besoin des plumes de jeunes couineurs pour maintenir un cataplasme en place. Ces oiseaux habituellement dociles attaquent désormais les voyageurs, et leur plumage est dangereux à récolter.",h="Dans la Forêt de Trombenoire, les guérisseurs ont besoin des plumes de jeunes couineurs pour maintenir un...",kw={"sève antiseptique","feathers for binding","cataplasme","forêt de trombenoire","couineur de trombenoire","couineur","couineurs"},ang={["class:Druid"]="En tant que druide, vous partagez peut-être le chagrin des gardiens lorsqu’ils doivent abattre de jeunes bêtes des bois, même si l’agressivité croissante et les besoins médicaux urgents laissent peu d’autres choix.",["profession:Herbalism"]="Les herboristes et les guérisseurs naturels peuvent apprécier l’équilibre entre la mousse, la sève d’arbre antiseptique et les plumes isolantes dans un pansement de terrain ou un cataplasme médicinal."},sec={{t="Remèdes de la forêt",b="Dans la Forêt de Trombenoire, les guérisseurs de terrain soignent les blessures graves avec de la mousse et de la sève d’arbre antiseptique. Les intempéries peuvent assécher la sève ou lui faire perdre ses propriétés. Ils maintiennent donc le cataplasme en place avec les plumes des jeunes couineurs de Trombenoire, qui protègent la plaie et gardent le remède en place."},{t="Une hostilité inhabituelle",b="Récolter leur duvet est devenu dangereux. Les jeunes couineurs de Trombenoire sont généralement des habitants dociles des bois, mais ils sont récemment devenus inexplicablement agressifs. Leurs puissantes serres peuvent infliger des blessures mortelles. Désormais, les oisillons s’en prennent aux passants."},{t="Une nécessité regrettable",b="Les gardiens locaux déplorent la nécessité d’abattre de jeunes bêtes. Pourtant, des urgences menacent la région et les couineurs deviennent plus dangereux. Réduire leur nombre permet de récolter des matières curatives essentielles et de contenir une menace grandissante sur les sentiers forestiers. Chaque plume est traitée avec respect, afin que le sacrifice des bêtes ne soit pas vain."}},faq={{q="Pourquoi faut-il des plumes de couineur pour le cataplasme ?",a="Les plumes des jeunes couineurs de Trombenoire isolent le cataplasme. Posées sur la mousse et la sève antiseptique, elles empêchent la sève de sécher et protègent les plaies des intempéries.",al={"utilité des plumes","pourquoi les plumes de couineur","plumes pour cataplasme"}},{q="À quel point les jeunes couineurs sont-ils dangereux ?",a="Les couineurs de Trombenoire sont généralement dociles, mais ils sont récemment devenus inhabituellement hostiles. Même les jeunes ont de grandes serres féroces, capables d’éventrer un voyageur imprudent.",al={"danger des couineurs","les couineurs sont-ils dangereux","agressivité des couineurs"}},{q="Pourquoi faut-il chasser les jeunes couineurs plutôt que les adultes ?",a="Les gardiens regrettent d’abattre de jeunes couineurs, mais leur agressivité soudaine et les urgences qui frappent les terres sauvages rendent nécessaire la réduction de leurs effectifs. Récolter leurs plumes aide aussi à répondre aux besoins médicaux urgents.",al={"pourquoi tuer les jeunes couineurs","tuer les jeunes couineurs"}},{q="Où trouve-t-on les couineurs de Trombenoire ?",a="Les couineurs de Trombenoire parcourent les cimes et les sous-bois de la Forêt de Trombenoire. Les voyageurs doivent avancer prudemment dans les bois pour les trouver.",al={"où se trouve la forêt de trombenoire","lieu où trouver les couineurs","où trouver les couineurs"}},{q="Quels autres ingrédients sont utilisés avec ces plumes ?",a="Le cataplasme est composé de mousse locale et de sève antiseptique, maintenues et isolées par les plumes de jeunes couineurs.",al={"ingrédients du cataplasme","composition du cataplasme"}},{q="Pourquoi les couineurs sont-ils devenus si hostiles récemment ?",a="Personne ne connaît la cause exacte de l’hostilité soudaine des couineurs. Ces jeunes créatures habituellement paisibles sont devenues agressives, ce qui aggrave les crises auxquelles font face les gardiens locaux.",al={"pourquoi les couineurs sont-ils en colère","cause de l’agressivité des couineurs"}}},fp="20,179,22.275.0,26.255.0,23.313.0,63.166.0,43.170.0,58.225.0,43.142.0,63.106.0,50.175.0"}
P.entries["quest:94487"] = {n="Unwanted and Unworthy",s="Sur Zephras, le sang versé dans la Forêt de Trombenoire pousse Elegael à réclamer vengeance et à récupérer des objets ancestraux volés pour le High Elder.",h="Sur Zephras, le sang versé dans la Forêt de Trombenoire pousse Elegael à réclamer vengeance et à récupérer...",kw={"al’aketh","héritages ensanglantés","elegael","fantassins","héritages","forêt de trombenoire","shen'dorei","chasseurs de tempête","zephras"},ang={["class:Druid"]="Sur Zephras, les Al’Aketh Cultists ont versé le sang des druides de l'île lors d'une attaque sans provocation. En tant que druide, vous répondez par la vengeance et défendez l'équilibre de la nature."},sec={{t="Embuscade dans la Forêt de Trombenoire",b="Les Al’Aketh Cultists tendent une embuscade aux druides de la Forêt de Trombenoire. Elegael croyait ces fanatiques inoffensifs, de simples rêveurs avec des nuages entre les oreilles. Désormais, le sang des druides souille le sol de la forêt, et Elegael exige de promptes représailles contre les Footsoldiers et les Stormchasers responsables."},{t="Objets d'héritage souillés et jeunesse perdue",b="Elegael estime que la trahison des sectateurs leur a coûté leur héritage. Ils ne méritent plus le nom de shen'dorei, et leurs dépouilles ne méritent pas davantage les vents de leur terre natale. Beaucoup étaient jeunes, et le fanatisme a brisé leur avenir prometteur.\n\nLeurs objets ancestraux ensanglantés doivent être rendus au High Elder. Là, ces objets sacrés attendent une génération plus sage et plus digne."}},faq={{q="Qui sont les sectateurs d’Al’Aketh ?",a="Les Al’Aketh Cultists sont des sectateurs obsédés par les tempêtes sur Zephras. Elegael les croyait autrefois de simples rêveurs insensés, avec des nuages entre les oreilles, mais ils ont déchaîné leur violence contre les druides de l'île.",al={"qui sont les alaketh","secte d'alaketh","qui sont les sectateurs"}},{q="Qui est Elegael ?",a="Elegael est un protecteur ou un druide shen'dorei sur Zephras. Les Al’Aketh Cultists ont tendu une embuscade à Elegael, que cette trahison et le sang de jeunes vies versé ont plongé dans la détresse. Elegael réclame des représailles et cherche à récupérer les objets ancestraux volés.",al={"qui est elegael","donneur de quête elegael"}},{q="Que sont les objets d'héritage ensanglantés ?",a="Les objets ancestraux ensanglantés appartenaient à de jeunes shen'dorei entraînés dans l'Al’Aketh Cult. Elegael les rassemble pour les rendre à la collection du High Elder, où ils pourront être transmis à une génération future plus digne.",al={"héritages ensanglantés","pourquoi récupérer les héritages","que sont les héritages"}},{q="Que sont les shen'dorei ?",a="Les shen'dorei sont le peuple qui habite Zephras. Elegael estime que les Al’Aketh Cultists ont perdu le droit de porter ce nom en trahissant les leurs dans la violence et en profanant l'harmonie de l'île.",al={"signification de shen'dorei","qui sont les shen'dorei"}},{q="Où se trouve la Forêt de Trombenoire ?",a="La Forêt de Trombenoire est une région boisée de Zephras. Les Al’Aketh Footsoldiers et les Stormchasers y opèrent, et c'est là que les sectateurs ont tendu une embuscade aux druides.",al={"emplacement de la forêt de trombenoire","où se trouve trombenoire"}},{q="Pourquoi les sectateurs d’Al’Aketh ont-ils tendu une embuscade aux druides ?",a="Elegael ignore les motivations exactes des sectateurs. Autrefois considérés comme des fanatiques inoffensifs, ils ont soudain déchaîné une violence féroce et brisé l'équilibre fragile de l'île.",al={"pourquoi les sectateurs ont-ils attaqué","motifs de la secte","pourquoi tendre une embuscade aux druides"}}},fp="21,124,27.286.0,32.360.0,30.198.0,15.244.0,32.200.0,24.189.0,27.146.0,48.174.0"}
P.entries["quest:94488"] = {n="The Ties That Bind",s="Elegael Thornpaw affronte un traître parmi les druides de la Forêt de Trombenoire. Haalien a disparu des mois plus tôt, puis a rejoint les sectateurs assaillants et pris leur commandement. Elegael ordonne maintenant son exécution.",h="Elegael Thornpaw affronte un traître parmi les druides de la Forêt de Trombenoire.",kw={"cercle cénarien","commandant haal ien","sectateurs","druide","elegael thornpaw","haalien","forêt de trombenoire","the ties that bind"},ang={["class:Druid"]="En tant que druide, vous savez que le Cercle cénarien tient l’équilibre et la parenté pour sacrés. La trahison de Haalien et le sang versé entre druides sont de graves offenses à l’ordre."},sec={{t="Trahison dans la forêt",b="Les druides font face à une attaque féroce de sectateurs dans la Forêt de Trombenoire. Elegael Thornpaw retrouve la trace de Haalien au milieu du massacre. Haalien était un druide du cercle, disparu des mois plus tôt, mais il n’a pas péri dans les étendues sauvages. Il a rejoint les sectateurs envahisseurs et commande à présent leur violente campagne contre ses anciens semblables."},{t="Sang et parenté",b="Haalien a trahi bien plus que ses vœux envers le Cercle cénarien. Quand Elegael voit la tête tranchée du commandant déchu, elle révèle que Haalien était son cousin. La fureur que lui inspirent ses atrocités n’a pas allégé le poids de devoir abattre l’un des siens, et elle n’a pu le porter seule. Sa mort met fin à la vie d’un renégat dont la malveillance a coûté la vie à de nombreux innocents."}},faq={{q="Qui donne la quête The Ties That Bind ?",a="Elegael Thornpaw est une druidesse postée dans la Forêt de Trombenoire. Alors que les sectateurs attaquent, elle vous charge de retrouver le commandant Haalien après avoir découvert son rôle dans le massacre.",al={"qui donne the ties that bind","donneur de quête forêt de trombenoire","qui est elegael thornpaw"}},{q="Qui est le commandant Haalien ?",a="Le commandant Haalien était un druide du Cercle cénarien qui a disparu des mois avant les attaques des sectateurs. Il a rejoint de son plein gré les sectateurs ennemis et pris le commandement de leurs forces contre les siens.",al={"qui est haal ien","histoire du commandant haal ien","origines de haalien"}},{q="Pourquoi Elegael veut-elle la mort du commandant Haalien ?",a="Haalien a quitté son cercle druidique pour commander des sectateurs qui ont massacré des innocents et fait couler le sang de ses frères. Elegael ordonne son exécution à cause de ses crimes et du danger qu’il fait courir à la forêt.",al={"pourquoi tuer haalien","crimes de haalien","qu’a fait haalien"}},{q="Quel lien unit Elegael Thornpaw et Haalien ?",a="Le commandant Haalien est le cousin d’Elegael Thornpaw. Furieuse de ses crimes, elle avoue que tuer l’un des siens aurait été un fardeau amer, et vous demande de l’aider.",al={"elegael et haalien sont-ils liés","quel lien unit elegael et haalien"}},{q="Pourquoi des sectateurs se trouvent-ils dans la Forêt de Trombenoire ?",a="Même les druides locaux ignorent exactement pourquoi les sectateurs sont venus dans la Forêt de Trombenoire. D’anciens membres du cercle comme Haalien les dirigent et mènent la violence contre les défenseurs de la forêt.",al={"sectateurs de la forêt de trombenoire","pourquoi des sectateurs sont-ils dans la forêt de trombenoire"}},{q="Où cette quête se déroule-t-elle ?",a="Les événements se déroulent dans la Forêt de Trombenoire, où Elegael Thornpaw enquête sur l’attaque des sectateurs et affronte la trahison de son cousin.",al={"où se déroule the ties that bind","emplacement de la forêt de trombenoire"}}},fp="18,192,22.310.0,17.349.1,40.171.0,25.191.0,45.206.0,60.166.0,50.198.0,33.133.0"}
P.entries["quest:94489"] = {n="The Wounds of Betrayal",s="Dans la Forêt de Trombenoire, Elegael soigne les druides shen'dorei blessés lors d'un terrible assaut. Des cataplasmes attendent les blessés de Nightfang Den, au nord, de l'autre côté de la clairière, tandis que son compagnon Jorel Windsinger a disparu.",h="Dans la Forêt de Trombenoire, Elegael soigne les druides shen'dorei blessés lors d'un terrible assaut.",kw={"al’aketh","druide","elegael","jorel windsinger","nightfang den","forêt de trombenoire","shen'dorei","the wounds of betrayal"},ang={["class:Druid"]="En tant que druide, vous connaissez le poids que représente la trahison et les blessures graves infligées à ceux qui prennent soin de la nature. Les druides shen'dorei sont peu nombreux.",["race:NightElf"]="En tant qu'elfe de la nuit, vous vénérez les traditions druidiques. La souffrance de vos frères et sœurs druides dans la Forêt de Trombenoire et leur lutte contre la trahison peuvent vous peser."},sec={{t="Au secours des shen'dorei",b="Elegael soigne les druides shen'dorei blessés lors de l'assaut contre la Forêt de Trombenoire. Elle a préparé des cataplasmes pour ses frères et sœurs réfugiés à Nightfang Den, juste au nord, de l'autre côté de la clairière. Il reste peu de druides shen'dorei, et chaque survivant compte pour leur fragile enclave."},{t="À la recherche de Jorel Windsinger",b="Elegael vous demande de retrouver son compagnon, Jorel Windsinger, et de soigner les sept druides meurtris dans la grotte. Lorsqu'elle a fui les combats pour préparer des remèdes, Jorel s'accrochait déjà à la vie. Nightfang Den renferme toute l'étendue des ravages infligés au sanctuaire, et le sort de Jorel se joue dans ses recoins obscurs."},{t="Un serment de vengeance",b="Après avoir appris la fin de Jorel et vu le terrible tribut payé par ses frères et sœurs, le chagrin d'Elegael se change en fureur. Elle rejette le désespoir et choisit la vengeance. Tous ceux qui sont alliés aux Al’Aketh subiront son courroux implacable pour le massacre de son peuple."}},faq={{q="Qui donne la quête The Wounds of Betrayal ?",a="Elegael, une druide shen'dorei, vous demande de soigner ses frères et sœurs blessés après une violente attaque dans la Forêt de Trombenoire.",al={"qui donne the wounds of betrayal","donneur de quête the wounds of betrayal","qui est elegael"}},{q="Où se trouve Nightfang Den ?",a="Nightfang Den se trouve au nord, de l'autre côté de la clairière, dans la Forêt de Trombenoire. Des druides shen'dorei blessés se sont réfugiés dans la grotte.",al={"où se trouve nightfang den","emplacement de nightfang den","où se trouvent les druides blessés"}},{q="Qui est Jorel Windsinger ?",a="Jorel Windsinger est le compagnon d'Elegael. Gravement blessé lors de l'attaque, il est resté à Nightfang Den, où vous découvrirez son sort.",al={"qui est jorel windsinger","sort de jorel windsinger","où est jorel"}},{q="Qui sont les druides shen'dorei ?",a="Les shen'dorei sont un peuple rare qui compte peu de druides. Elegael dit que chaque survivant est précieux.",al={"qui sont les shen'dorei","qui sont les druides shen'dorei","histoire des druides shen'dorei"}},{q="Qui sont les Al’Aketh ?",a="Les Al’Aketh sont les ennemis responsables de l'attaque contre les druides, ou des alliés de ceux qui l'ont perpétrée. Après avoir appris le sort de Jorel et vu les ravages, Elegael leur promet vengeance, ainsi qu'à tous ceux qui sont leurs alliés.",al={"qui sont les al’aketh","al’aketh","pourquoi elegael déteste les al’aketh"}},{q="Qu'arrive-t-il à Jorel Windsinger dans cette quête ?",a="Lorsque vous trouvez Jorel Windsinger à Nightfang Den, son état a connu une évolution tragique. La nouvelle de son sort et la détresse des druides survivants accablent Elegael de chagrin et de fureur, et elle jure de se venger.",al={"qu'arrive-t-il à jorel windsinger","jorel survit-il","sort de jorel"}}},fp="22,202,22.265.0,31.307.1,20.247.2,43.111.0,31.123.0,24.120.0,31.101.0,21.214.0,46.206.0"}
P.entries["quest:94490"] = {n="Missive déchirée",s="Haalien porte une lettre ensanglantée après l’attaque d’un antre de druides dans la Forêt de Trombenoire. Elle révèle ce que cherchaient les sectateurs et signale un danger au sein de Valanaar.",h="Haalien porte une lettre ensanglantée après l’attaque d’un antre de druides dans la Forêt de Trombenoire.",kw={"sectateur","antre de druides","elegael thornpaw","haalien","lotheluum","pylône","ripped missive","forêt de trombenoire","valanaar"},ang={["class:Druid"]="La lettre apporte une nouvelle amère : les druides de l’antre ont été massacrés parce qu’ils barraient la route aux sectateurs en quête d’un pylône."},sec={{t="Ordres maculés de sang",b="La missive de Haalien donne un aperçu des violences dans la Forêt de Trombenoire. Retrouvé après une violente escarmouche, ce fragment déchiré annonce une sinistre nouvelle : des sectateurs ont attaqué un antre de druides des environs. Son contenu apporte des indices à ceux qui cherchent à rendre justice aux victimes."},{t="Un massacre insensé",b="Elegael Thornpaw découvre pourquoi les sectateurs ont attaqué l’antre. Ils cherchaient un mystérieux pylône, et n’avaient aucun différend avec les druides. Les habitants de l’antre sont morts parce qu’ils leur barraient la route. Enragée par le massacre, Elegael jure de se venger de tous les sectateurs encore présents dans la forêt."},{t="Trahison à Valanaar",b="L’attaque a été ordonnée depuis Valanaar. La missive désigne une directive venue de la colonie, où un traître pourrait être à l’œuvre. Pour découvrir le complot avant que d’autres vies ne soient perdues, la lettre doit parvenir sans délai à Lotheluum, à Valanaar."}},faq={{q="Qu’est-ce que la Ripped Missive ?",a="La missive est une lettre déchirée et maculée de sang, retrouvée derrière le brassard de Haalien après une bataille. Elle révèle pourquoi les sectateurs ont attaqué un antre de druides dans la Forêt de Trombenoire.",al={"qu’est-ce que la ripped missive","quête ripped missive","note ensanglantée de haalien"}},{q="Où la missive a-t-elle été retrouvée ?",a="La missive a été retrouvée derrière le brassard de Haalien après un violent affrontement. La bataille a déchiré et maculé de sang la lettre.",al={"qui a laissé tomber la ripped missive","d’où vient la ripped missive","qui est haalien"}},{q="À qui remettre la Ripped Missive ?",a="La missive doit d’abord être remise à Elegael Thornpaw, dans la Forêt de Trombenoire. Après l’avoir lue, Elegael demande qu’elle soit portée sans tarder à Lotheluum, à Valanaar.",al={"qui veut la ripped missive","à qui remettre la ripped missive","missive d’elegael thornpaw"}},{q="Pourquoi les sectateurs ont-ils attaqué l’antre de druides ?",a="Les sectateurs ont attaqué l’antre de druides pour s’emparer d’un pylône qui s’y trouvait. Ils ont tué les druides parce qu’ils leur barraient la route.",al={"pourquoi les sectateurs ont-ils attaqué l’antre de druides","motif des sectateurs contre l’antre de druides","pourquoi haalien a-t-il attaqué"}},{q="D’où venaient les ordres de l’attaque ?",a="La missive désigne des ordres venus de Valanaar, où un traître pourrait diriger les opérations des sectateurs.",al={"d’où venaient les ordres","qui a envoyé haalien","traître à valanaar"}},{q="Qui est Lotheluum et pourquoi faut-il le prévenir ?",a="Lotheluum est un contact à Valanaar. Elegael Thornpaw ordonne d’y porter la missive pour avertir que ces ordres meurtriers viennent d’une personne qui se cache dans la colonie.",al={"qui est lotheluum","pourquoi apporter la missive à lotheluum","lotheluum à valanaar"}}},fp="14,167,19.240.0,19.260.1,21.250.2,27.155.0,36.126.0,38.158.0,42.114.0,38.96.0,47.166.0"}
P.entries["quest:94491"] = {n="The Fate of the Den",s="À L’Antre des druides, les survivants pleurent leurs camarades tombés après l’assaut des cultistes. The Fate of the Den parvient à Lotheluum, à Valanaar, avec une missive retrouvée et la nouvelle de lourdes pertes. La dépêche révèle qu’une personne de Valanaar transmet des informations cruciales à l’ennemi.",h="À L’Antre des druides, les survivants pleurent leurs camarades tombés après l’assaut des cultistes.",kw={"cultistes","antre des druides","high elder","lotheluum","missive","the fate of the den","traître","valanaar"},ang={["class:Druid"]="En tant que druide, vous ressentez le poids de cette tragédie. Ceux qui sont tombés étaient vos compagnons, et des cultistes hostiles ont trahi leur refuge isolé."},sec={{t="Tragédie à L’Antre",b="Les cultistes ont frappé L’Antre des druides, laissant ses défenseurs meurtris et en deuil de leurs camarades tombés. Une aide extérieure a maîtrisé le danger immédiat, mais les ravages physiques et émotionnels restent immenses. Les morts ne peuvent revenir, et les survivants blessés sont trop faibles pour entreprendre le long voyage. Des cultistes rôdent toujours dans les environs."},{t="Trahison à Valanaar",b="La missive retrouvée montre que les cultistes ont choisi leur cible à dessein. Une personne cachée à Valanaar leur transmet des renseignements. Lorsque Lotheluum apprend le massacre et lit la dépêche, son chagrin pour ses compagnons tombés fait place à l’inquiétude. Un traître circule toujours librement dans la colonie. Il porte les preuves au High Elder pour que leur sacrifice ne soit pas oublié."}},faq={{q="Qui est Lotheluum ?",a="Lotheluum vit à Valanaar et reçoit des rapports sur L’Antre des druides. La nouvelle de l’assaut et la missive retrouvée le plongent dans le chagrin pour ses compagnons tombés. Il porte donc les preuves de la trahison au High Elder.",al={"lotheluum","qui est lotheluum","pnj lotheluum"}},{q="Que s’est-il passé à L’Antre des druides ?",a="Les cultistes ont dévasté L’Antre des druides et tué de nombreux défenseurs. Un aventurier a aidé à maîtriser le danger immédiat, et les survivants meurtris ont trouvé des preuves qu’un complice avait guidé l’attaque.",al={"que s’est-il passé à l’antre","attaque de l’antre des druides","histoire de the fate of the den"}},{q="Que révèle la missive retrouvée ?",a="La missive révèle qu’une personne cachée à Valanaar a secrètement transmis des renseignements au culte. Elle indique qu’un sabotage et de l’espionnage locaux ont permis le raid meurtrier contre L’Antre.",al={"que dit la missive","missive de l’antre","missive du traître"}},{q="Qui est le High Elder dont parle Lotheluum ?",a="Le High Elder est une autorité de Valanaar à laquelle Lotheluum répond. Face aux lourdes pertes et à la menace d’un traître, Lotheluum apporte la missive et la nouvelle de la tragédie au High Elder.",al={"qui est le high elder","high elder de valanaar","high elder"}},{q="Qui a attaqué L’Antre des druides ?",a="Des membres d’un culte actif dans la région ont attaqué L’Antre des druides. Un informateur caché à Valanaar les a guidés, et l’assaut a coûté cher aux habitants de L’Antre.",al={"qui a attaqué l’antre","qui a attaqué l’antre des druides","cultistes de l’antre"}},{q="Pourquoi le survivant de L’Antre n’a-t-il pas pu remettre la missive en personne ?",a="Le survivant avait été trop grièvement blessé pendant l’attaque pour faire le voyage jusqu’à Valanaar. Il est resté sur place pour éliminer les cultistes encore présents et a envoyé un aventurier donner l’alerte.",al={"pourquoi remettre la missive","donneur de quête blessé","pourquoi le survivant ne peut pas aller à valanaar"}}},fp="19,269,18.340.0,21.379.1,17.202.0,31.204.0,39.171.0,45.194.0,48.164.0,69.180.0"}
P.entries["quest:94493"] = {n="A Sacrifice in Vain",s="Elegael Thornpaw craint que les cultistes d’Al’Aketh ne submergent les blessés dans son repaire. Un message destiné à Valanaar ne leur est pas parvenu, et elle doit demander de l’aide.",h="Elegael Thornpaw craint que les cultistes d’Al’Aketh ne submergent les blessés dans son repaire.",kw={"a sacrifice in vain","cultistes d’al’aketh","repaire","elegael thornpaw","renforts","valanaar","blessés"},sec={{t="Un appel à l’aide",b="Les cultistes d’Al’Aketh ont fondu sur les compagnons d’Elegael Thornpaw sans presque aucun avertissement. Beaucoup de ses compagnons dans l’Antre sont blessés ou mourants, et elle ignore combien de temps ils pourront survivre à l’attaque. Elle a tenté d’envoyer un message à Valanaar, mais il n’est pas parvenu à destination. Aucun renfort en vue, Elegael vous demande de l’aide."}},faq={{q="Qui demande de l’aide ?",a="Elegael Thornpaw demande de l’aide tandis que les cultistes d’Al’Aketh attaquent ses compagnons.",al={"qui a besoin d’aide","elegael thornpaw","elegael"}},{q="Qu’est-il arrivé aux gens dans l’Antre ?",a="Les cultistes d’Al’Aketh leur ont tendu une embuscade sans presque les prévenir. Beaucoup sont blessés ou mourants.",al={"blessés du repaire","que s’est-il passé ici","attaque des cultistes"}},{q="Pourquoi Valanaar n’a-t-il pas envoyé de renforts ?",a="Le message d’Elegael n’est pas parvenu à Valanaar, et les renforts ne sont donc pas arrivés.",al={"où sont les renforts","message de valanaar","message pour valanaar"}},{q="De quoi Elegael a-t-elle besoin ?",a="Elegael vous demande d’aider ses compagnons blessés à survivre à l’attaque des cultistes d’Al’Aketh.",al={"comment aider","aider elegael","que demande-t-elle"}}},fp="19,163,14.316.0,23.75.0,39.83.0,41.77.0,23.83.0"}
P.entries["quest:94494"] = {n="Call of Water",s="Au Loch Modan, Norric Lochthane appelle un chaman à découvrir la pureté de l’eau. Après avoir trouvé l’harmonie avec le vent, la terre et la flamme, l’initié est prêt à communier avec l’eau.",h="Au Loch Modan, Norric Lochthane appelle un chaman à découvrir la pureté de l’eau.",kw={"call of water","éléments","montagne","pureté","chaman","épreuve du totem","totem d'eau"},ang={["class:Shaman"]="En tant que chaman, vous faites un pas fondamental vers la communion avec les esprits élémentaires. Vous passez de la terre et du feu à la fluidité et à la pureté de l’eau.",["race:Dwarf"]="En tant que nain, vous entendez la cadence bourrue d’un mentor tandis que vous suivez des sentiers de montagne accidentés vers la communion avec la nature."},sec={{t="La voie de la pureté",b="Le chaman qui a trouvé l’équilibre avec la terre, le vent et la flamme se tourne maintenant vers l’eau. Sa leçon va au-delà d’une force à maîtriser. L’eau offre une image spirituelle de pureté et de résilience."},{t="L’ascension vers les éléments",b="Norric Lochthane presse l’initié de poursuivre sans délai. Communier avec les éléments exige effort et endurance, et le chemin grimpe à travers un pays accidenté. La montagne n’attend personne. La compréhension commence par l’ascension."}},faq={{q="Qu’est-ce que Call of Water ?",a="Call of Water marque le début de la communion d’un chaman avec l’eau. Après avoir appris de la terre, du vent et du feu, l’initié cherche maintenant la vérité profonde de l’eau.",al={"qu’est-ce que call of water","quête call of water","qu’est-ce que cette quête"}},{q="Qui guide cette étape du voyage ?",a="Eldrun Stormbreaker, l’instructeur des chamans à Forgefer, envoie l’initié auprès de Norric Lochthane, au Loch Modan. Norric l’exhorte à faire un premier pas décisif, car ni les éléments ni les hauteurs n’attendent ceux qui hésitent.",al={"qui donne call of water","qui dit que la montagne n’attend personne","mentor de call of water"}},{q="Que signifie « la montagne n’attend personne » ?",a="Cette expression incite l’initié à entreprendre une ascension exigeante. Les voyages chamaniques mènent aux hauts sommets et aux contrées sauvages reculées où vivent les esprits, et demandent de la détermination.",al={"que signifie la montagne n’attend personne","la montagne n’attend personne","signification de la montagne"}},{q="Quelle est la vérité de la pureté de l’eau ?",a="L’eau enseigne la purification, la fluidité et la pureté. La pierre offre la stabilité et le feu nourrit la détermination, tandis que la sagesse de l’eau aide à équilibrer les esprits en soi.",al={"pourquoi la pureté de l’eau","vérité de la pureté de l’eau","signification de l’élément eau"}},{q="Quel rapport l’eau entretient-elle ici avec les autres éléments ?",a="La terre, le vent et le feu sont des fondements que l’initié a déjà ressentis dans ses bottes, son souffle et son ventre. L’harmonie exige l’équilibre entre les éléments, et non la recherche d’un seul pouvoir.",al={"quels éléments viennent en premier","prérequis pour l’eau","éléments de call of water"}},{q="Où l’initié se rend-il après avoir entendu ces paroles ?",a="Norric Lochthane envoie l’initié aux Paluns pour chercher le Water Sapta auprès de Hervdana Saegrund. Elle vit dans une grotte sous les chutes du sud.",al={"que faire ensuite dans call of water","où aller maintenant","étape suivante de call of water"}}},fp="13,164,18.179.0,24.227.0,26.141.0,36.205.0,53.171.0,36.156.0,49.173.0,53.148.0"}
P.entries["quest:94495"] = {n="Call of Water",s="Dans les Paluns, les chercheurs découvrent les pouvoirs de l’eau pure et cherchent le Water Sapta. Sous les chutes du sud, Hervdana Saegrund accueille ceux qui bravent les terres sauvages.",h="Dans les Paluns, les chercheurs découvrent les pouvoirs de l’eau pure et cherchent le Water Sapta.",kw={"call of water","nain","hervdana saegrund","chaman","chutes du sud","water sapta","les paluns"},ang={["class:Shaman"]="En tant que chaman, vous découvrez la nature de l’eau et cherchez un Water Sapta pour communier avec ses esprits.",["faction:Alliance"]="En tant que voyageur de l’Alliance, vous vous enfoncez dans les dangereux Paluns, loin des patrouilles des gardes nains ou de l’Alliance.",["race:Dwarf"]="En tant que nain, Hervdana vous reconnaît comme l’un des siens, bravant les marécages dangereux où rôdent des nains Sombrefer."},sec={{t="La nature de l’eau",b="L’eau pure redonne la vie, sculpte la pierre et lave les impuretés. L’eau souillée menace de tout détruire. Ceux qui cherchent la communion avec l’eau sont envoyés dans la nature sauvage pour obtenir un Water Sapta auprès de ceux qui vivent près de cet élément."},{t="À l’abri sous les chutes",b="Hervdana Saegrund et sa famille vivent dans une grotte isolée, juste sous les chutes du sud des Paluns. Les gardes de Forgefer sont loin, et des nains Sombrefer rôdent dans les marécages alentour. Pourtant, Hervdana et les siens gardent leur demeure isolée près des chutes."}},faq={{q="Qui est Hervdana Saegrund ?",a="Hervdana Saegrund est une naine qui vit avec sa famille dans une grotte sous les chutes du sud des Paluns. Elle aide les chamans qui cherchent la communion avec l’eau et les secrets du Water Sapta.",al={"qui est hervdana","hervdana saegrund","où est hervdana"}},{q="Qu’est-ce que le Water Sapta ?",a="Le Water Sapta est un élixir rituel dont les chamans se servent pour communier avec les esprits de l’eau. Dans les royaumes de l’est, les chercheurs sont envoyés auprès d’Hervdana Saegrund, près des chutes du sud, pour en obtenir un.",al={"qu’est-ce que le water sapta","signification de sapta","pourquoi obtenir le water sapta"}},{q="Où trouver Hervdana Saegrund ?",a="Hervdana Saegrund et sa famille vivent dans une grotte isolée, juste sous les chutes du sud des Paluns.",al={"où vit hervdana","où se trouve la grotte","emplacement des chutes du sud"}},{q="Pourquoi Hervdana vit-elle dans les dangereux Paluns ?",a="Hervdana et les siens ont choisi la solitude de la grotte sous la cascade pour leurs propres raisons, malgré la présence des nains Sombrefer dans les marais et l’absence de gardes de la ville.",al={"pourquoi vivre dans les paluns","dangers des paluns","sombrefer dans les paluns"}},{q="Quelle leçon l’eau enseigne-t-elle ici ?",a="L’eau pure apporte la renaissance, sculpte la pierre, lave les impuretés et apaise les esprits fatigués. L’eau corrompue ou souillée menace de tout détruire.",al={"que représente l’eau","philosophie de l’eau","leçon de l’eau"}},{q="Quel est le but de la quête Call of Water ?",a="Les chamans entreprennent la quête Call of Water pour découvrir la nature de l’eau et chercher le Water Sapta auprès de guides qui vivent à l’écart.",al={"quel est le type de cette quête","à qui s’adresse cette quête","quête de chaman nain"}}},fp="13,172,19.234.0,25.277.0,25.191.0,24.183.0,37.114.0,49.167.0,40.130.0,47.114.0"}
P.entries["quest:94497"] = {n="Call of Water",s="Dans les Paluns, un initié recueille de l’eau pour mériter le sapta lors de Call of Water. Le marais est dangereux, mais ses eaux montrent comment les énergies de l’eau façonnent et nourrissent la terre.",h="Dans les Paluns, un initié recueille de l’eau pour mériter le sapta lors de Call of Water.",kw={"call of water","sombrefer","estuaire","hervdana","sapta","outre","les paluns"},ang={["class:Shaman"]="En tant que chaman, vous cherchez le sapta en apprenant la nature de l’eau dans différentes contrées. Vous accordez votre esprit à ses multiples formes.",["race:Dwarf"]="En tant que nain, vous entendez Hervdana déplorer la division entre les clans. Les nains Sombrefer poussent vers le nord, jusque dans les Paluns."},sec={{t="La voie du sapta",b="Hervdana guide les initiés dans leur quête de l’eau sous ses multiples formes. Ils apprennent comment elle s’écoule, transforme les vies et nourrit la terre. Leur chemin vers le sapta et la communion avec les esprits commence à un estuaire, là où les marées océaniques rencontrent les eaux de ruissellement des hautes terres."},{t="Rencontre des eaux",b="Sous la caverne d’Hervdana, des cascades déversent l’eau de source des hautes terres dans le marais. Là, elle rencontre l’eau salée poussée vers l’intérieur des terres par les marées côtières. L’océan apporte des sédiments, des minéraux et des énergies différentes de celles de la fonte limpide des neiges de montagne. Un initié peut trouver la sagesse dans les voies naturelles de la terre, là où ces eaux se rencontrent."},{t="Ombres dans le marais",b="Les dangereuses créatures du marais rendent la collecte d’eau périlleuse. Des nains Sombrefer ont également poussé loin vers le nord, dans les Paluns. Hervdana regrette l’hostilité entre les clans nains. Elle voit tout ce que les nains pourraient accomplir s’ils mettaient leurs querelles de côté."}},faq={{q="Qu’est-ce que le sapta ?",a="Le sapta est une décoction sacrée qui permet à un initié de communier avec les esprits élémentaires. Pour le mériter, l’initié cherche l’eau sous ses multiples formes et apprend comment elle façonne la terre et nourrit la vie.",al={"qu’est-ce que le sapta","signification du sapta","pourquoi chercher le sapta"}},{q="Qui est Hervdana ?",a="Hervdana guide les initiés depuis sa caverne, au-dessus des cascades des Paluns. Elle leur demande de recueillir des échantillons d’eau et de s’accorder avec l’élément.",al={"qui confie call of water","où se trouve hervdana","caverne d’hervdana"}},{q="Pourquoi recueillir de l’eau là où l’eau douce rencontre l’eau saumâtre ?",a="À l’estuaire, la fonte des neiges et l’eau de source des hautes terres rencontrent les marées océaniques. Leurs eaux charrient des sédiments, des minéraux et une sagesse spirituelle.",al={"pourquoi l’eau de l’estuaire","eau saumâtre des paluns","rencontre de l’eau douce et salée"}},{q="Quels dangers rôdent près des cascades ?",a="Les dangereuses créatures du marais et les nains Sombrefer menacent les voyageurs près des cascades. Les nains ont poussé vers le nord, jusque dans les Paluns.",al={"sombrefer dans les paluns","pourquoi les nains sombrefer sont-ils ici","menace des sombrefer"}},{q="Que signifie devenir un réceptacle ?",a="Un réceptacle est un initié qui cherche la sagesse dans les eaux et porte des offrandes recueillies dans la nature pour approfondir l’harmonie élémentaire.",al={"qu’est-ce qu’un réceptacle","réceptacle d’eau"}},{q="À quoi sert l’Outre marron vide ?",a="Hervdana fournit l’Outre marron vide pour recueillir un échantillon d’eau saumâtre au pied des cascades, dans le marais.",al={"utilisation de l’outre marron vide","à quoi sert l’outre"}}},fp="13,176,20.273.0,26.308.0,20.248.0,18.191.0,16.149.0,52.128.0,38.136.0,37.126.0,43.116.0"}
P.entries["quest:94499"] = {n="Call of Water",s="Hervdana Saegrund vous envoie des Paluns aux Carmines pour tester l’eau des Chutes de Guet-de-pierre. Votre échantillon servira à vos épreuves spirituelles.",h="Hervdana Saegrund vous envoie des Paluns aux Carmines pour tester l’eau des Chutes de Guet-de-pierre.",kw={"call of water","hervdana saegrund","lac placide","murlocs nightcrawler","les carmines","sapta","shadowseers","chutes de guet-de-pierre","les paluns"},ang={["class:Shaman"]="En tant que chaman, vous recueillez de l’eau pour préparer un sapta et prouver votre dévouement ainsi que votre perception à travers des cours d’eau lointains, avant de communier avec les esprits de l’eau."},sec={{t="Une cascade suspecte",b="Hervdana Saegrund vous envoie au sud des Paluns pour examiner l’eau des Chutes de Guet-de-pierre, dans les Carmines. Le Lac placide fournit de l’eau pure à Comté-du-Lac, mais des murlocs rôdent sous la cascade. Ils sont devenus anormalement grands et difformes. Hervdana soupçonne du venin, une sombre sorcellerie ou des infiltrations provenant de la vieille forteresse en amont. Elle vous demande de prélever un échantillon dans une Outre rouge vide."},{t="La véritable source de la corruption",b="Hervdana Saegrund découvre que l’eau du Lac placide est propre et exempte de pollution. Une sombre sorcellerie pratiquée par des shadowseers près de Guet-de-pierre a déformé les murlocs Nightcrawler, et non l’eau. L’échantillon prouve que les chutes sont pures et que vous vous dévouez à vos épreuves. C’est aussi un réactif essentiel pour préparer un sapta spirituel."}},faq={{q="Qui donne cette quête et où se trouve cette personne ?",a="Hervdana Saegrund vous la confie depuis les Paluns. Elle étudie les sources d’eau et les réactifs nécessaires à la préparation d’un sapta pour les épreuves spirituelles d’un apprenti chaman.",al={"qui donne call of water","donneur de quête hervdana"}},{q="Pourquoi devez-vous recueillir de l’eau aux Chutes de Guet-de-pierre ?",a="Hervdana soupçonne que du venin, de la magie noire ou une corruption s’écoule de la vieille forteresse en amont des Chutes de Guet-de-pierre et déforme les murlocs en contrebas. Elle vous demande de rapporter un échantillon frais pour l’examiner.",al={"pourquoi remplir une outre dans les carmines","but des chutes de guet-de-pierre"}},{q="L’eau des Chutes de Guet-de-pierre est-elle réellement souillée ?",a="Non. L’eau est pure et intacte. Hervdana découvre que la magie noire des shadowseers locaux déforme les murlocs.",al={"les eaux de guet-de-pierre sont-elles souillées","le lac placide est-il corrompu"}},{q="Pourquoi les murlocs des environs des Chutes de Guet-de-pierre sont-ils si grands et difformes ?",a="Les murlocs Nightcrawler près des chutes sont plus grands et plus difformes que ceux du Loch ou des Paluns. Hervdana attribue ce changement à la magie impure des shadowseers locaux.",al={"pourquoi les murlocs des carmines sont-ils mutants","différence entre les murlocs de guet-de-pierre"}},{q="À quoi sert l’échantillon d’eau ?",a="Un sapta permet à un chaman de percer le voile et de percevoir les esprits élémentaires. Hervdana recueille de l’eau pure en divers lieux pour préparer le réactif de vos épreuves spirituelles.",al={"qu’est-ce qu’un sapta","but de la récompense de call of water"}},{q="Qui est Norric ?",a="Norric est un associé ou un mentor qui participe aux épreuves chamaniques. Hervdana dit que Norric sera heureux de vous voir revenir avec de l’eau pure.",al={"qui est norric","norric dans call of water"}}},fp="13,154,17.377.0,29.321.1,48.155.0,56.206.0,50.111.0,65.166.0,34.165.0,14.135.0"}
P.entries["quest:945"] = {n="L'évasion de Therylune",s="Au Glaive du Maître, dans le sud de Sombrivage, Therylune a besoin d’aide pour se mettre en sûreté. Elle s’est égarée sur les sites de fouilles, et sa sœur Therysil l’attend au sanctuaire d’Aessina, inquiète pour elle.",h="Au Glaive du Maître, dans le sud de Sombrivage, Therylune a besoin d’aide pour se mettre en sûreté.",kw={"orneval","cultistes","escorte","le glaive du maître","le sanctuaire d'aessina","therylune","therysil","marteau du crépuscule"},ang={["faction:Alliance"]="En aidant les voyageurs comme Therylune, vous renforcez la présence de l’Alliance et sa bonne entente avec les Elfes de la nuit qui défendent Orneval.",["race:NightElf"]="Le Glaive du Maître marque une ancienne cicatrice dans l’histoire de Kalimdor. Voir une autre kaldorei s’égarer dans les fouilles des cultistes rappelle cruellement les menaces qui pèsent sur Orneval."},sec={{t="Une promenade périlleuse",b="Au Glaive du Maître, des cultistes du Marteau du crépuscule tiennent Therylune en respect. Le crâne d’une monstruosité antique domine le ravin, transpercé par une immense lame de pierre. Malgré la peur qui règne autour d’elle, Therylune s’est aventurée au cœur de la vallée. Elle survit en réagissant vite et en se cachant dans le terrain accidenté."},{t="Des nouvelles au sanctuaire",b="Therysil attend loin au sud, au sanctuaire d’Aessina. Sa sœur Therylune, qui aime l’aventure, ne craint guère de salir ses vêtements, mais même Therysil a été stupéfaite d’apprendre qu’elle s’était aventurée dans les fouilles malsaines du Glaive du Maître. Dites-lui que Therylune est saine et sauve, et son inquiétude s’apaisera. Therysil connaît les forces obscures qui fouillent les terres ancestrales de Sombrivage."}},faq={{q="Qui est Therylune ?",a="Therylune est une jeune Elfe de la nuit aventureuse qui s’est égarée dans les dangereuses fouilles du Glaive du Maître, dans le sud de Sombrivage. C’est la sœur de Therysil.",al={"therylune","qui est la jeune elfe","elfe piégée"}},{q="Qui est Therysil ?",a="Therysil est la sœur de Therylune et vit au sanctuaire d’Aessina, en Orneval. Elle est consternée que sa sœur se soit aventurée si près d’un lieu sombre et corrompu.",al={"therysil","sœur de therylune"}},{q="Pourquoi le Glaive du Maître est-il si dangereux ?",a="Le Glaive du Maître est un ravin inquiétant où un ancien seigneur est tombé il y a bien longtemps. Des cultistes du Marteau du crépuscule pullulent sur le site, y creusent et attaquent les intrus.",al={"danger du glaive du maître","cultistes du glaive du maître"}},{q="Où faut-il escorter Therylune ?",a="Therylune a besoin d’une escorte pour quitter le Glaive du Maître et rejoindre un lieu sûr. Ensuite, rendez-vous au sanctuaire d’Aessina et dites à sa sœur qu’elle a survécu.",al={"destination de l’escorte","où va therylune"}},{q="Où se trouve le sanctuaire d’Aessina ?",a="Le sanctuaire d’Aessina se trouve dans le sud-ouest d’Orneval, à l’ouest d’Astranaar. C’est un sanctuaire dédié à l’esprit de la forêt Aessina.",al={"emplacement du sanctuaire d’aessina","où se trouve therysil"}},{q="Comment Therylune a-t-elle survécu, entourée de cultistes ?",a="Therylune a échappé à la capture en se cachant parmi les rochers et dans le terrain, avant que les cultistes du Marteau du crépuscule qui l’encerclaient ne la repèrent.",al={"comment therylune s’est cachée"}}},fx={["8c0c4bd7"]={q="Pourquoi Therylune a-t-elle besoin de votre aide pour s'échapper ?",a="Therylune s'est égarée dans les fouilles sinistres du Glaive du Maître et s'est rapidement retrouvée piégée et entourée par des cultistes du Marteau du crépuscule. Bien que son don pour se cacher l'ait maintenue en vie, elle ne peut pas se faufiler devant les fanatiques qui l'encerclent pour atteindre la sécurité et rassurer sa sœur, Therysil.",al={"pourquoi therylune veut-elle de l'aide","motif de therylune","pourquoi aider therylune"}},cc515991={q="Pourquoi Therylune ne peut-elle pas s'échapper seule ?",a="Bien qu'assez douée pour se cacher et éviter une capture immédiate, Therylune est totalement désarmée, sans défense et piégée au cœur d'un territoire hostile. Sans gardes ou alliés locaux à proximité pour l'aider, elle dépend entièrement d'un aventurier de passage pour se frayer un chemin à travers les cultistes.",al={"pourquoi therylune a-t-elle besoin de moi","pourquoi therylune ne peut-elle pas s'échapper","pourquoi moi therylune"}}},fp="18,189,17.304.0,18.371.0,17.159.0,16.156.0,40.167.0,41.143.0,39.130.0,49.129.0"}
P.entries["quest:94500"] = {n="Call of Water",s="À Orneval, vous recueillez de l’eau pure dans le lac près d’Astranaar. C’est le dernier échantillon qu’il vous faut avant de retourner auprès de Norric.",h="À Orneval, vous recueillez de l’eau pure dans le lac près d’Astranaar.",kw={"orneval","astranaar","auberdine","call of water","port de menethil","norric","austrivage","outre"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous traversez la mer des Royaumes de l’est jusqu’à Kalimdor, en naviguant du Port de Menethil à Auberdine. De là, vous rejoignez Astranaar, une colonie d’Elfes de la nuit.",["race:NightElf"]="En tant qu’Elfe de la nuit, on vous envoie recueillir de l’eau dans le lac pur près d’Astranaar, au cœur des terres des Kaldorei, à Orneval. D’anciennes ruines y reposent encore intactes."},sec={{t="À la recherche d’eau pure",b="On vous envoie remplir une outre avec l’eau non corrompue d’Orneval. Astranaar est un havre au bord du lac, dont les eaux anciennes clapotent contre des ruines englouties. C’est le dernier échantillon liquide dont le donneur a besoin avant de vous envoyer auprès de Norric."},{t="La route vers Astranaar",b="Pour rejoindre Orneval depuis les Royaumes de l’est, traversez la mer en bateau depuis le Port de Menethil en direction d’Auberdine. Le bateau fait escale à Austrivage en chemin. Depuis les quais d’Auberdine, suivez la route vers l’intérieur des terres, sous les frondaisons verdoyantes d’Orneval. Restez sur vos gardes parmi les ombres vigilantes des arbres."}},faq={{q="En quoi consiste la quête Call of Water ?",a="Vous portez une outre vide dans l’ancienne forêt d’Orneval pour recueillir de l’eau pure dans le lac près d’Astranaar. L’échantillon est peut-être enchanté, et vous le rapportez au donneur de quête.",al={"qu’est-ce que call of water","quête call of water","objectif de call of water"}},{q="Où recueillir l’eau pour cette quête ?",a="Recueillez de l’eau dans le lac près d’Astranaar, au cœur d’Orneval. Elle n’est pas corrompue, et d’anciennes ruines englouties gisent sous sa surface.",al={"où trouver de l’eau pure","où remplir une outre","lieu de call of water"}},{q="Comment me rendre à Orneval pour cette quête ?",a="Traversez la mer en bateau depuis le Port de Menethil jusqu’à Auberdine. Le bateau fait escale à Austrivage en chemin. Depuis Auberdine, sur la côte de Sombrivage, voyagez vers le sud à travers les forêts profondes d’Orneval jusqu’à Astranaar.",al={"comment rejoindre astranaar","voyager jusqu’à orneval","bateau pour astranaar"}},{q="Qu’est-ce qui rend l’eau d’Astranaar si particulière ?",a="Le lac près d’Astranaar abrite une eau que la corruption n’a pas touchée. Les ruines de pierre englouties évoquent une ancienne époque de civilisation elfique et confèrent à l’eau sa pureté et ses propriétés potentiellement enchantées.",al={"quel lac à astranaar","ruines aquatiques d’astranaar","ruines du lac d’astranaar"}},{q="Qui est Norric ?",a="Norric vous attend après que vous avez recueilli le dernier échantillon liquide. Le donneur de quête récupère l’eau pure d’Orneval avant de vous renvoyer auprès de Norric.",al={"qui est norric","retourner auprès de norric"}},{q="Quels dangers m’attendent à Orneval ?",a="Orneval est une forêt ancienne et dense, pleine de périls. Le donneur de quête vous avertit de rester sur vos gardes sous sa canopée verdoyante, où des regards vigilants ne clignent pas des yeux.",al={"dangers à orneval","menaces d’orneval"}}},fp="13,126,25.233.0,21.285.0,32.174.0,44.137.0,44.197.0,42.188.0,14.146.0,42.147.0"}
P.entries["quest:94501"] = {n="Call of Water",s="Au Loch Modan, des aspirants se préparent à communier avec les esprits de l’eau. Hervdana bénit l’eau pure pour Norric Lochthane, tandis que les futurs chamans se rapprochent des rites du totem d’eau.",h="Au Loch Modan, des aspirants se préparent à communier avec les esprits de l’eau.",kw={"call of water","hervdana","loch modan","ruisselune","norric lochthane","chaman","étang de stendel","fiole d'eau pure","water sapta","totem d'eau"},ang={["class:Shaman"]="En tant que chaman, vous devez affronter une épreuve de communion avec les éléments. Vous accomplissez les rites du totem d’eau et préparez le sapta nécessaire pour percevoir les esprits élémentaires.",["faction:Alliance"]="En tant que chaman de l’Alliance, vous cherchez à communier avec les esprits de l’eau dans les terres de l’est, entre le Loch Modan et la Marche de l’Ouest.",["race:Dwarf"]="En tant que nain, vous pouvez chercher conseil auprès de mentors élémentaires tels que Norric Lochthane à travers Khaz Modan."},sec={{t="La voie du totem d’eau",b="Vous cherchez l’harmonie avec l’eau par la patience et le respect. Hervdana bénit l’eau que vous recueillez, et vous la portez à Norric Lochthane au Loch Modan."},{t="La naissance du sapta",b="Norric Lochthane utilise l’eau bénite par Hervdana pour préparer un Water Sapta. Ce breuvage vous permet de percevoir les esprits de l’eau à l’Étang de Stendel, près de Ruisselune. Chaque goutte compte, et le bouchon humidifié a sa place dans les rites."}},faq={{q="Qui est Norric Lochthane ?",a="Norric Lochthane accompagne les candidats au Loch Modan dans leur quête de communion avec les éléments. Il supervise les préparatifs et les rites permettant d’obtenir le totem d’eau.",al={"qui est norric","norric loch modan","qui est norric lochthane"}},{q="Qui est Hervdana ?",a="Hervdana Saegrund vit avec sa famille dans une grotte près des chutes du sud des Paluns. Elle guide les futurs chamans et bénit l’eau sacrée qui sert à préparer le Water Sapta.",al={"qui est hervdana","béni par hervdana","eau hervdana"}},{q="À quoi sert un sapta ?",a="Un sapta est un breuvage préparé avec de l’eau sacrée. Le boire permet à un chaman de percevoir les insaisissables esprits de l’eau dans les bassins naturels.",al={"qu’est-ce que water sapta","utilité du sapta","que fait le sapta"}},{q="Où se trouve l’Étang de Stendel ?",a="L’Étang de Stendel se trouve dans la Marche de l’Ouest, près de Ruisselune. Des esprits de l’eau y vivent, et un chaman les recherche après avoir bu un sapta préparé.",al={"où se trouve l’étang de stendel","emplacement de l’étang de stendel","esprits de l’eau à stendel"}},{q="Pourquoi la Fiole d’eau pure est-elle importante ?",a="La Fiole d’eau pure contient l’eau bénite nécessaire à la préparation du Water Sapta et à l’accomplissement des rites pour obtenir un totem d’eau. Norric rappelle que chaque goutte compte.",al={"pourquoi faut-il de l’eau pure","utilité de la fiole d’eau pure"}},{q="Quels sont les rites du totem d’eau ?",a="Les rites du totem d’eau sont des épreuves spirituelles qui accordent les chamans à l’eau. Les chamans font preuve de respect et d’équilibre avant de recevoir un totem d’eau.",al={"que sont les rites du totem d’eau","comment obtenir le totem d’eau"}}},fp="13,168,27.150.0,18.228.1,24.159.0,16.165.0,25.123.0,32.133.0,42.162.0,31.137.0"}
P.entries["quest:94502"] = {n="Call of Water",s="Vous voyagez de Loch Modan à la Marche de l’Ouest, où une source corrompue a réduit les esprits de l’eau au silence. À l’Étang de Stendel, vous pouvez purifier la corruption et réveiller un ancien sanctuaire afin de gagner leur faveur et le Totem d'eau.",h="Vous voyagez de Loch Modan à la Marche de l’Ouest, où une source corrompue a réduit les esprits de l’eau au...",kw={"call of water","loch modan","ruisselune","norric","chaman","étang de stendel","totem d'eau","marche de l’ouest"},ang={["class:Shaman"]="En tant que chaman, vous accomplissez un rite de passage pour vous accorder aux esprits de l’eau et gagner le Totem d'eau. Il témoigne de votre harmonie avec les forces élémentaires et de votre maîtrise de celles-ci.",["faction:Alliance"]="En tant que chaman de l’Alliance, vous voyagez de Loch Modan jusqu’à la Marche de l’Ouest pour purifier ses eaux corrompues."},sec={{t="Une source souillée par l’ombre",b="Près de Ruisselune, l’Étang de Stendel subit une sombre corruption qui s’étend à travers la Marche de l’Ouest. Ses eaux étaient autrefois limpides, mais les esprits de l’eau locaux se taisent désormais. Un ancien sanctuaire délabré se dresse sur la rive, couvert de poussière et de toiles d’araignée. Vous pouvez tenter d’éveiller les pouvoirs qui sommeillent en lui."},{t="Le rite de purification",b="Norric, à Loch Modan, vous guide dans le rite destiné à rétablir l’équilibre. À l’Étang de Stendel, vous affrontez l’entité immonde qui pollue l’eau et apportez ses brassards au sanctuaire de pierre. Vous les offrez avec quelques gouttes d’un breuvage alchimique, puis prononcez l’incantation. Ses vapeurs invoquent un esprit purifié, qui vous transmet sa sagesse et vous juge digne du Totem d'eau."}},faq={{q="Qu’est-ce que la quête Call of Water ?",a="Pour les chamans en quête de communion avec les éléments de l’eau, Call of Water est une épreuve spirituelle. Vous purifiez la corruption de l’Étang de Stendel, dans la Marche de l’Ouest, puis utilisez son ancien sanctuaire pour invoquer un esprit de l’eau purifié et obtenir votre Totem d'eau.",al={"qu’est-ce que call of water","quête du totem d’eau","quête de l’eau marche de l’ouest"}},{q="Qui donne cette quête ?",a="Norric vous confie Call of Water à Loch Modan. Il vous enseigne les rites élémentaires, vous fournit des potions spéciales et vous guide dans la purification des eaux élémentaires corrompues.",al={"qui donne call of water","norric loch modan","donneur de quête"}},{q="Où se trouve l’Étang de Stendel ?",a="L’Étang de Stendel se trouve juste à l’extérieur de Ruisselune, dans le sud-ouest de la Marche de l’Ouest. Autrefois source pure, ses eaux sont devenues stagnantes et troubles sous l’effet d’influences sombres et corruptrices.",al={"où se trouve l’étang de stendel","emplacement de l’étang de stendel","étang près de ruisselune"}},{q="Comment purifier la corruption de l’Étang de Stendel ?",a="Pour purifier l’Étang de Stendel, vous devez vaincre la présence corruptrice et prendre ses brassards. Déposez-les sur l’ancien sanctuaire avec les dernières gouttes de potion, puis prononcez l’incantation que Norric vous a enseignée.",al={"comment purifier l’étang","purifier l’étang de stendel","rituel du sanctuaire"}},{q="Que gagnez-vous en terminant cette quête ?",a="Après avoir accompli l’épreuve et rapporté à Norric, à Loch Modan, la preuve de la purification, vous recevez le Totem d'eau. Il vous donne le pouvoir de commander aux forces élémentaires de l’eau.",al={"récompense de call of water","récompense totem d’eau"}},{q="Pourquoi l’Étang de Stendel est-il corrompu ?",a="Personne ne sait ce qui a provoqué les ténèbres à l’Étang de Stendel. Le bassin demeure anormalement immobile au milieu des ossements de bêtes. Le mal qui s’étend dans la Marche de l’Ouest l’a-t-il empoisonné, ou l’étang est-il lui-même une source de corruption ?",al={"pourquoi l’étang de stendel est-il corrompu","qu’est-ce qui a corrompu l’étang"}}},fp="13,212,26.284.0,21.359.1,32.235.0,21.168.0,24.152.0,52.195.0,43.169.0,32.211.0"}
P.entries["quest:94503"] = {n="Call of Water",s="Dans la Marche de l’Ouest, vous chassez les esprits agités des eaux avant qu’une Manifestation d'eau mineure ne vous parle.",h="Dans la Marche de l’Ouest, vous chassez les esprits agités des eaux avant qu’une Manifestation d'eau mineure...",kw={"call of water","purification","corruption","élémentaire","manifestation d'eau mineure","esprit de l’eau","marche de l’ouest"},ang={["class:Shaman"]="En tant que chaman, vous communiez avec les éléments primordiaux et purifiez les esprits de l’eau souillés. Ce rite vous rappelle votre devoir durable de préserver l’équilibre de la nature.",["faction:Alliance"]="En tant que membre de l’Alliance, vous trouvez la manifestation dans la Marche de l’Ouest, où les esprits locaux subissent le fléau qui gagne la terre."},sec={{t="Purifier les eaux souillées",b="Des esprits corrompus troublent les eaux de la Marche de l’Ouest et leur équilibre naturel. Vous prononcez des paroles sacrées, et une lumière éclatante disperse les essences agitées en cendres et en brume paisible."},{t="L’avertissement de l’esprit",b="Une fois les esprits corrompus repoussés, une Manifestation d'eau mineure peut apparaître. Elle vous avertit que les énergies vitales de la terre déclinent toujours et que préserver la vie exige une attention constante."}},faq={{q="Qu’est-ce que Call of Water ?",a="Dans la Marche de l’Ouest, vous affrontez des esprits corrompus lors d’une épreuve spirituelle. Une invocation sacrée les repousse dans une lumière éclatante et libère les eaux troublées, vous permettant de parler à une Manifestation d'eau mineure.",al={"qu’est-ce que call of water","call of water marche de l’ouest","quête de l’eau marche de l’ouest"}},{q="Où trouver la Manifestation d'eau mineure ?",a="La Manifestation d'eau mineure apparaît dans la Marche de l’Ouest après que les esprits corrompus des environs ont été maîtrisés et dissipés. Elle attend de parler à ceux qui ont aidé les eaux.",al={"où trouver la manifestation d'eau mineure","emplacement de la manifestation","esprit de l’eau marche de l’ouest"}},{q="Que se passe-t-il quand les esprits corrompus sont purifiés ?",a="À la fin de l’invocation, une lumière éclatante disperse les esprits corrompus. Leur essence souillée se défait en cendres, tandis que l’eau siffle et se change en une douce brume.",al={"que se passe-t-il pendant le rituel","esprits corrompus call of water"}},{q="La terre est-elle entièrement restaurée après cette tâche ?",a="La corruption immédiate reflue, mais l’élémentaire avertit que la vitalité de la terre continue de décliner. Les mortels ont toujours le devoir de protéger la vie.",al={"la corruption a-t-elle disparu","l’eau a-t-elle été sauvée"}},{q="Qui est appelé à aider la manifestation ?",a="Vous êtes appelé à purifier les esprits et à prendre en charge la protection d’une vie qui décline. La manifestation remercie votre classe d’avoir répondu à l’appel.",al={"qui peut faire call of water","classe requise quête de l’eau"}},{q="Pourquoi les esprits de l’eau ont-ils été corrompus dans la Marche de l’Ouest ?",a="Des esprits corrompus ont troublé les eaux naturelles de la Marche de l’Ouest. Leur origine exacte reste inconnue, mais leur présence malveillante épuise la vitalité de la région.",al={"pourquoi l’eau est-elle corrompue dans la marche de l’ouest","problème de l’eau dans la marche de l’ouest"}}},fp="13,113,28.166.0,20.184.0,22.203.0,52.163.0,53.149.0,53.155.0,47.147.0,49.153.0"}
P.entries["quest:94505"] = {n="Call of Water",s="Dans la Marche de l’Ouest, vous découvrez ce que l’eau peut offrir et ce que la corruption peut détruire. Rapportez un Éclat d'eau à Norric Lochthane, à Loch Modan, et il vous remettra un totem d'eau.",h="Dans la Marche de l’Ouest, vous découvrez ce que l’eau peut offrir et ce que la corruption peut détruire.",kw={"call of water","loch modan","norric lochthane","chaman","eclat d'eau","totem d'eau","marche de l’ouest"},ang={["class:Shaman"]="En tant que chaman, vous accomplissez un rite de passage qui vous permet de communier avec les esprits de l’eau et vous octroie un totem d'eau pour guérir et soutenir la vie.",["faction:Alliance"]="En tant que novice de l’Alliance, vous rendez compte à des mentors comme Norric Lochthane, à Loch Modan, et affrontez des épreuves dans des lieux comme la Marche de l’Ouest, contrairement aux chamans de la Horde sur Kalimdor."},sec={{t="La voie de l’eau",b="Vous vous rendez dans la Marche de l’Ouest, puis retournez auprès de Norric Lochthane à Loch Modan avec un Éclat d'eau. Ce voyage met à l’épreuve votre dévouement à l’eau et votre compréhension de son pouvoir de donner la vie et de chasser la corruption. Ceux qui font leurs preuves reçoivent un totem d'eau et franchissent une étape essentielle sur leur voie élémentaire."},{t="Source de vie",b="L’eau donne la vie, et la corruption y met fin. Norric Lochthane vous apprend à employer la force régénératrice de l’eau pour protéger les plus vulnérables et préserver les êtres vivants. Ses dons vont au-delà de la guérison du corps. Ils apportent endurance, renouveau et équilibre spirituel."}},faq={{q="Qui est Norric Lochthane ?",a="Norric Lochthane est un mentor chaman à Loch Modan. Il guide les novices dans des épreuves pour leur faire comprendre les esprits de l’eau, et met leur détermination à l’épreuve en les envoyant dans la Marche de l’Ouest. Lorsqu’ils rapportent la preuve de leur communion, il leur remet un totem d'eau.",al={"qui est norric lochthane","qui remet le totem d’eau","norric à loch modan"}},{q="Qu’est-ce que l’Éclat d'eau ?",a="L’Éclat d'eau est la preuve que vous rapportez de la Marche de l’Ouest à Norric Lochthane, à Loch Modan. Il montre que vous avez communié avec l’eau, compris sa nature vivifiante et appris à combattre la corruption.",al={"qu’est-ce que l’éclat d’eau","utilité de l’éclat d’eau","objet de quête éclat d’eau"}},{q="Pourquoi l’épreuve mène-t-elle dans la Marche de l’Ouest ?",a="Vous vous rendez dans la Marche de l’Ouest pour apprendre le pouvoir vivifiant de l’eau et voir comment la corruption le menace. Même de modestes victoires dans cette région troublée démontrent votre capacité à protéger la vie.",al={"pourquoi aller dans la marche de l’ouest","quête de l’eau dans la marche de l’ouest","voyage dans la marche de l’ouest call of water"}},{q="Quelle est l’importance du totem d'eau ?",a="Un totem d'eau incarne votre lien avec l’eau. Son eau pure peut apaiser et guérir les blessures, tandis que ses dons spirituels préservent et soutiennent aussi la vie.",al={"que fait le totem d’eau","pourquoi les chamans ont-ils besoin d’un totem d’eau","histoire du totem d’eau"}},{q="Quelle leçon l’épreuve enseigne-t-elle sur l’eau ?",a="L’épreuve vous enseigne que l’eau donne la vie, tandis que la corruption y met fin. Vous devez employer le pouvoir de l’eau pour nourrir et protéger les êtres vivants, et rétablir l’équilibre là où la corruption les menace.",al={"que signifie l’eau est la vie","philosophie de call of water","enseignements chamaniques sur l’eau"}},{q="Que se passe-t-il après avoir accompli Call of Water ?",a="Norric Lochthane vous dit que votre prochaine épreuve élémentaire n’aura pas lieu tout de suite. Il vous encourage à vous exercer et à explorer les mystères plus profonds de l’eau avant d’affronter d’autres épreuves.",al={"quelle est la prochaine épreuve","prochaine épreuve chamanique","que se passe-t-il après call of water"}}},fp="13,163,17.305.0,13.267.0,24.236.0,27.193.0,36.173.0,44.145.0,45.201.0,46.170.0"}
P.entries["quest:94532"] = {n="Gnoll Infestation",s="Neza Bloodsnout, à Rog’mar, vous demande de repousser les gnolls dans les collines au sud-ouest. Leur présence perturbe le commerce et les déplacements, même si l’avancée de Twilight a réduit leurs effectifs.",h="Neza Bloodsnout, à Rog’mar, vous demande de repousser les gnolls dans les collines au sud-ouest.",kw={"brutes","infestation de gnolls","gnolls","mystiques","neza bloodsnout","les carmines","rog’mar","trappeurs","twilight"},sec={{t="Des gnolls dans les collines",b="Bien que l’avancée de Twilight ait réduit leurs effectifs, les gnolls des Carmines rôdent toujours dans les collines au sud-ouest de Rog’mar. Neza Bloodsnout vous demande de dégager le passage pour les alliés en éliminant la menace. Le commerce et les voyageurs restent entravés tant que les gnolls tiennent leur position."}},faq={{q="Pourquoi les gnolls posent-ils problème ?",a="Les gnolls des collines au sud-ouest de Rog’mar perturbent le commerce et gênent les voyageurs.",al={"gnolls qui perturbent le commerce","pourquoi éliminer les gnolls","menace des gnolls"}},{q="Où se trouvent les gnolls ?",a="Ils infestent les collines au sud-ouest.",al={"collines infestées de gnolls","où se trouvent les gnolls des carmines"}},{q="Qui me demande de m’occuper d’eux ?",a="Neza Bloodsnout, à Rog’mar, vous demande d’éliminer la menace des gnolls.",al={"qui a confié l’infestation de gnolls","quête de neza"}},{q="Les gnolls sont-ils moins nombreux à présent ?",a="Oui. Leurs effectifs ont diminué avec l’avancée de Twilight, mais la menace persiste.",al={"effectifs des gnolls","twilight et les gnolls"}},{q="Quels types de gnolls trouve-t-on ?",a="Les gnolls mentionnés sont les mystiques des Carmines, les trappeurs des Carmines et les brutes des Carmines.",al={"types de gnolls","mystiques trappeurs brutes"}}},fp="17,187,19.268.0,29.81.0,21.39.0,30.63.0,27.86.0,31.78.0"}
P.entries["quest:94533"] = {n="Snargl's Snout",s="Neza Bloodsnout cherche le museau de Snargl comme trophée. Les sons désagréables de ce vieux gnoll gênent les alliés et les éclaireurs dans les Collines Hirsutes.",h="Neza Bloodsnout cherche le museau de Snargl comme trophée.",kw={"collines hirsutes","gnoll","neza bloodsnout","snargl","museau de snargl","museau","trophée"},sec={{t="Un trophée pour Neza",b="Neza Bloodsnout veut un souvenir pour sa collection, et Snargl est le gnoll qu'elle désigne. Vous êtes envoyé dans les Collines Hirsutes pour récupérer son museau. Neza s'attend à ce que vous fassiez vite ; les alliés et les éclaireurs qui pénètrent dans cette zone sont gênés par les sons de Snargl."}},faq={{q="Qui est Snargl ?",a="Snargl est un vieux gnoll des Collines Hirsutes, au sud-ouest de Neza Bloodsnout.",al={"snargl","gnoll snargl","vieux gnoll"}},{q="Pourquoi Neza veut-elle le museau de Snargl ?",a="Neza veut le museau de Snargl comme souvenir pour sa collection de trophées.",al={"pourquoi le museau","trophée snargl","collection neza"}},{q="Où se trouve Snargl ?",a="Snargl se trouve dans les Collines Hirsutes, au sud-ouest de Neza Bloodsnout.",al={"emplacement snargl","où se trouve snargl","gnoll des collines hirsutes"}},{q="Quels problèmes Snargl cause-t-il ?",a="Snargl produit des sons désagréables qui gênent les alliés et les éclaireurs entrant dans les Collines Hirsutes.",al={"sons de snargl","pourquoi les éclaireurs sont gênés","bruit de gnoll"}},{q="Que dit Neza à votre retour ?",a="Neza dit que le trophée est plus lourd que prévu et se réjouit de l'ajouter à sa collection.",al={"fin de la quête snargl","réaction de neza","museau récupéré"}}},fp="14,133,17.247.0,14.75.0,34.63.0,16.61.0,31.90.0,35.95.0"}
P.entries["quest:94535"] = {n="Bristle Hills Bandits",s="Kreza Darkthorn vous envoie dans les Collines Hirsutes après l’attaque de mineurs alliés par des gnolls. Vous devez récupérer le minerai volé dans leurs camps.",h="Kreza Darkthorn vous envoie dans les Collines Hirsutes après l’attaque de mineurs alliés par des gnolls.",kw={"mineurs alliés","bandits","collines hirsutes","gnolls","kreza darkthorn","minerai volé"},sec={{t="Le minerai des collines",b="Des mineurs alliés signalent des attaques de gnolls dans les collines au sud de Kreza Darkthorn. Vous devez trouver les camps des Collines Hirsutes et récupérer le minerai volé. Les pertes des mineurs sont en jeu."},{t="Après la récupération",b="Kreza Darkthorn affirme que le minerai a été récupéré et que le feu effacera toute trace ou odeur laissée derrière."}},faq={{q="Qui m’envoie récupérer le minerai volé ?",a="Kreza Darkthorn vous demande de récupérer le minerai volé aux mineurs alliés.",al={"qui est kreza","donneur de quête du minerai"}},{q="Où se trouvent les bandits ?",a="Les gnolls se trouvent dans des camps des Collines Hirsutes, au sud de Kreza Darkthorn.",al={"camps de gnolls","où sont les bandits"}},{q="Qui a volé le minerai ?",a="Des gnolls des Collines Hirsutes ont attaqué des mineurs alliés et leur ont pris leur minerai.",al={"voleurs de minerai","qui l’a pris"}},{q="Qu’est-il arrivé aux mineurs ?",a="Des mineurs alliés qui travaillaient dans les collines au sud ont signalé plusieurs attaques de gnolls.",al={"mineurs attaqués","pourquoi le minerai a été volé"}}},fp="21,139,18.187.0,18.98.1,34.70.0,22.71.0,18.70.0,28.83.0"}
P.entries["quest:94556"] = {n="Jom-jom's Escape",s="Jom-jom veut rentrer chez lui et vous demande de l’escorter jusqu’à Clugfist, à Bolder'ok.",h="Jom-jom veut rentrer chez lui et vous demande de l’escorter jusqu’à Clugfist, à Bolder'ok.",kw={"bolder'ok","clugfist","escorter","ami","chez soi","jom-jom"},sec={{t="Le chemin du retour",b="Jom-jom s’est mis en route pour trouver un ami. À présent, il a besoin que vous le guidiez jusqu’à Clugfist, à Bolder’ok, pour pouvoir rentrer chez lui."}},faq={{q="Qui est Jom-jom ?",a="Jom-jom est venu chercher un ami et veut maintenant rentrer chez lui.",al={"qui est jom-jom","jom-jom"}},{q="Où Jom-jom veut-il aller ?",a="Jom-jom veut rentrer chez lui, et l’on vous demande de l’escorter jusqu’à Clugfist, à Bolder'ok.",al={"où va jom-jom","jom-jom chez lui"}},{q="Qui est Clugfist ?",a="Clugfist est celui que vous devez escorter jusqu’à Bolder'ok pour Jom-jom.",al={"clugfist","qui est clugfist"}},{q="Pourquoi Jom-jom est-il venu ici ?",a="Jom-jom est venu chercher un ami.",al={"pourquoi jom-jom est ici","venue de jom-jom"}},{q="Jom-jom vous considère-t-il comme un ami ?",a="Après que vous l’avez sauvé, Jom-jom vous appelle son ami.",al={"ami de jom-jom","petit"}}},fp="16,81,12.107.0,15.59.0,30.87.0,16.62.0,26.34.0,35.47.0"}
P.entries["quest:94568"] = {n="The Cult's True Plans",s="L'informateur de la secte est mort avant de révéler ce qu'il savait. Talaanis Shadowsong doit aider les enquêteurs à trouver un autre moyen de s'opposer à la secte.",h="L'informateur de la secte est mort avant de révéler ce qu'il savait.",kw={"secte","déserteur","pacificateurs","talaanis shadowsong","the cult's true plans","traître"},sec={{t="Un déserteur réduit au silence",b="Un initié terrifié a quitté la secte dans l'espoir de trouver de l'aide à l'extérieur. Il a été tué avant de pouvoir révéler ce qu'il savait. Ses avertissements subsistent, mais les plans de la secte restent inconnus."},{t="Revoir la stratégie",b="La mort de l'informateur prive les dirigeants de leur principale source de renseignements. Ils consultent Talaanis Shadowsong et reconsidèrent la façon d'affronter la secte. Une attaque ouverte avec les pacificateurs est jugée vouée à l'échec. Les enquêteurs doivent donc trouver une autre voie."}},faq={{q="Qui était le déserteur mentionné dans cette quête ?",a="Le déserteur était un initié de la secte qui a cherché de l'aide après avoir été terrifié par ses manigances. Il a été tué avant de pouvoir révéler ce qu'il savait.",al={"qui est mort dans the cult's true plans","qui est le déserteur mort","secrets de la secte connus du déserteur"}},{q="Qui est Talaanis Shadowsong ?",a="Talaanis Shadowsong est le contact consulté après la mort de l'informateur. Vous assistez à une discussion stratégique avec Talaanis sur la marche à suivre contre la secte.",al={"rôle de talaanis shadowsong","qui est talaanis shadowsong","parler à talaanis"}},{q="Pourquoi les pacificateurs ne peuvent-ils pas simplement attaquer la secte de front ?",a="Les pacificateurs ne devraient pas faire le poids dans un affrontement ouvert contre la secte. Les enquêteurs estiment qu'une attaque directe serait vouée à l'échec.",al={"pourquoi ne pas combattre la secte","pacificateurs contre secte","assaut direct contre la secte"}},{q="Quels sont les véritables plans de la secte ?",a="Les plans de la secte restent inconnus, car l'informateur est mort avant de révéler ce qu'il savait. Ses intentions étaient assez terrifiantes pour pousser un membre à chercher de l'aide.",al={"que prépare la secte","manigances de la secte","sens de the cult's true plans"}},{q="Quelle est la prochaine étape après avoir parlé à Talaanis ?",a="Après la mort de l'informateur et le rejet d'un affrontement ouvert, les dirigeants doivent trouver un autre moyen de découvrir et de déjouer les plans de la secte.",al={"que se passe-t-il après the cult's true plans","prochaines étapes de la quête de la secte"}},{q="Que se passe-t-il dans The Cult's True Plans ?",a="Vous parlez avec Talaanis Shadowsong et assistez à un conseil au sujet de la mort de l'informateur. La discussion porte sur les raisons pour lesquelles les pacificateurs ne peuvent pas compter sur la force pour arrêter la secte.",al={"résumé de la quête the cult's true plans","que fait-on dans the cult's true plans"}}},fp="21,139,19.170.0,23.268.1,45.146.0,27.161.0,55.145.0,33.163.0,51.142.0,42.178.0"}
P.entries["quest:94613"] = {n="My Kingdom for a Horse",s="Une ferme voisine a perdu ses chevaux, laissant Farholde sans cavalerie pour sa campagne contre la Horde. On vous envoie à Wheeler’s Grange pour parler à Benjy.",h="Une ferme voisine a perdu ses chevaux, laissant Farholde sans cavalerie pour sa campagne contre la Horde.",kw={"benjy","horde","chevaux disparus","mon royaume pour un cheval","cavalerie de farholde","chevaux de guerre","wheeler’s grange"},sec={{t="Le cheptel disparu",b="Farholde se procure ses chevaux de guerre dans deux fermes voisines, mais Wheeler’s Grange a perdu tout son cheptel. On ignore la cause de cette perte et, sans chevaux, Farholde n’a pas de cavalerie pour sa campagne contre la Horde. On vous envoie parler à Benjy à la ferme pour savoir ce qu’il a à dire."}},faq={{q="Pourquoi Farholde a-t-elle besoin de ces chevaux ?",a="Farholde compte sur ses chevaux de guerre pour sa cavalerie, qu’elle juge nécessaire à sa campagne contre la Horde.",al={"pourquoi des chevaux","besoin de chevaux de guerre","cavalerie de farholde"}},{q="Qu’est-il arrivé aux chevaux de Wheeler’s Grange ?",a="Tout le cheptel de la famille Wheeler a disparu, et la cause est inconnue.",al={"chevaux disparus","où sont passés les chevaux","chevaux de wheeler"}},{q="Qui est Benjy ?",a="Benjy se trouve à Wheeler’s Grange, où vous êtes envoyé pour l’interroger sur les chevaux disparus.",al={"benjy","homme de wheeler’s grange","à qui parler"}},{q="Où garde-t-on les chevaux de guerre de Farholde ?",a="Farholde se procure ses chevaux de guerre dans deux fermes voisines. La famille Wheeler possède l’une d’elles, Wheeler’s Grange.",al={"fermes équestres","origine des chevaux","fermes de chevaux de guerre"}}},fp="22,159,17.278.0,34.110.0,50.73.0,13.83.0,38.107.0"}
P.entries["quest:94615"] = {n="Foal Play",s="À Wheeler's Grange, les chevaux ont disparu des écuries. Vous cherchez des indices pour découvrir ce qui s'est passé.",h="À Wheeler's Grange, les chevaux ont disparu des écuries.",kw={"coyotes","farholde","jeu de poulain","chevaux","chevaux disparus","murlocs","écuries","wheeler's grange"},sec={{t="À la recherche d'indices à la ferme",b="Les écuries de Wheeler's Grange pourraient contenir des indices sur la disparition des chevaux. Leur gardien dit qu'ils avaient disparu lorsqu'il s'est levé pour les nourrir. Aux abords de Farholde, des animaux, des murlocs, des orcs ou d'autres dangers pourraient être en cause. Vous cherchez près des écuries pour comprendre ce qui s'est passé."}},faq={{q="Où sont passés les chevaux ?",a="Les chevaux ont disparu de Wheeler's Grange, et vous cherchez près des écuries des indices sur l'endroit où ils sont allés.",al={"chevaux disparus","chevaux absents","où sont les chevaux"}},{q="Qu'est-ce qui a pu emporter les chevaux ?",a="Le gardien pense que des animaux, des murlocs, des orcs ou d'autres dangers aux abords de Farholde pourraient être responsables.",al={"qui a pris les chevaux","coupable de la disparition des chevaux","qu'est-ce qui les a emportés"}},{q="Pourquoi les chevaux sont-ils importants ?",a="Le gardien gagne sa vie grâce aux chevaux.",al={"pourquoi les chevaux comptent","chevaux et moyens de subsistance","commerce des chevaux"}},{q="Où chercher des indices ?",a="Cherchez près des écuries de Wheeler's Grange des indices sur la disparition des chevaux.",al={"indices dans les écuries","où chercher","jeu de poulain"}}},fp="9,116,22.266.0,24.110.0,33.100.0,29.47.0,30.82.0"}
P.entries["quest:94616"] = {n="Sapta d'eau",s="Dans la Marche de l’Ouest, vous prenez le Water Sapta pour trouver une mare perturbée. Ce breuvage cérémoniel aiguise votre vue des esprits de l’eau et des corruptions cachées, afin que vous puissiez enquêter sur le déséquilibre.",h="Dans la Marche de l’Ouest, vous prenez le Water Sapta pour trouver une mare perturbée.",kw={"accord élémentaire","sapta","épreuve chamanique","mare souillée","water sapta","esprits de l’eau","marche de l’ouest"},ang={["class:Shaman"]="En tant que chaman, vous pouvez utiliser un sapta pour accorder vos sens spirituels aux esprits élémentaires cachés à la vue ordinaire.",["faction:Alliance"]="En tant que membre de l’Alliance, vous enquêtez sur les eaux corrompues de la Marche de l’Ouest et apportez les rites de purification élémentaire aux terres de l’Alliance."},sec={{t="Le regard des eaux",b="Les chamans préparent un sapta pour voir au-delà du monde physique. Le Water Sapta accorde vos sens à l’eau et révèle les perturbations et les esprits cachés aux voyageurs ordinaires. Sans cette vue altérée, une présence élémentaire pourrait ne sembler être que de simples ondulations."},{t="Troubles dans la Marche de l’Ouest",b="Le Water Sapta vous mène dans la Marche de l’Ouest, un royaume aride de l’Alliance troublé par l’agitation et l’abandon. Une mare y renferme une eau polluée spirituellement. Grâce à la vision du sapta, vous recherchez l’eau corrompue, découvrez la perturbation et rétablissez l’harmonie avec les esprits de l’eau locaux."}},faq={{q="Qu’est-ce qu’un Water Sapta ?",a="Un Water Sapta est un breuvage cérémoniel qui accorde votre vue spirituelle aux esprits de l’eau et aux perturbations cachées aux yeux des mortels.",al={"qu’est-ce qu’un water sapta","but du water sapta","que fait le water sapta"}},{q="Où se trouve la mare souillée de la Marche de l’Ouest ?",a="La mare souillée se trouve dans la Marche de l’Ouest. Le Water Sapta vous y guide pour trouver l’eau corrompue et remédier à la perturbation spirituelle.",al={"où se trouve la mare souillée","mare souillée marche de l’ouest","emplacement de la mare souillée"}},{q="Pourquoi le Water Sapta mène-t-il dans la Marche de l’Ouest ?",a="Le Water Sapta vous mène dans la Marche de l’Ouest, car une mare y renferme une eau souillée. Vous enquêtez sur la corruption et cherchez à rétablir l’équilibre parmi les esprits troublés.",al={"pourquoi aller dans la marche de l’ouest","corruption de l’eau dans la marche de l’ouest","pourquoi l’eau de la marche de l’ouest est-elle souillée"}},{q="Qui utilise le Water Sapta ?",a="Les chamans utilisent des saptas de l’eau lors d’épreuves de communion élémentaire. Le breuvage accorde leurs sens aux esprits de l’eau et les aide à percevoir les élémentaires cachés et à examiner les mares souillées.",al={"qui boit le water sapta","qui utilise le water sapta","breuvage sapta des chamans"}},{q="Que se passe-t-il quand vous apportez le sapta à la mare souillée ?",a="Près de la mare souillée de la Marche de l’Ouest, le Water Sapta vous accorde la vision élémentaire. Il révèle l’état spirituel de l’eau ou invoque des esprits cachés liés à l’épreuve locale de l’eau.",al={"que se passe-t-il après l’utilisation du sapta","vision élémentaire du sapta"}},{q="Comment les saptas fonctionnent-ils dans la tradition chamanique ?",a="Les saptas sont des breuvages cérémoniels qui accordent les chamans à un élément et font le lien entre le monde physique et le royaume des esprits. Les chamans les utilisent lors d’épreuves liées à la terre, au feu, à l’eau ou à l’air.",al={"comment fonctionnent les saptas","histoire du sapta"}}},fp="11,183,23.267.0,23.267.0,22.127.0,38.138.0,42.163.0,25.180.0,58.170.0,51.171.0"}
P.entries["quest:94618"] = {n="Wheeler's Fleeing Steeds",s="Benjy vous demande de retrouver un cheval qui a fui Wheeler's Grange après une attaque de coyotes. Nourrissez-le pour gagner sa confiance et le ramener.",h="Benjy vous demande de retrouver un cheval qui a fui Wheeler's Grange après une attaque de coyotes.",kw={"benjy","coyotes","fourrage","chevaux échappés","chevaux","wheeler's fleeing steeds","wheeler's grange"},sec={{t="Échappé de la Grange",b="Benjy, à Wheeler's Grange, a besoin de votre aide pour retrouver l'un des chevaux qui ont fui l'attaque des coyotes. Ceux-ci ont emporté certains chevaux, tandis que d'autres se sont enfuis, effrayés. Donnez du fourrage à un cheval pour gagner sa confiance et le ramener."}},faq={{q="Qu'est-il arrivé aux chevaux ?",a="Les coyotes ont emporté la plupart des chevaux, tandis que certains se sont enfuis de Wheeler's Grange, effrayés.",al={"chevaux à wheeler's grange","chevaux attaqués par des coyotes"}},{q="Qui demande de l'aide ?",a="Benjy vous demande de retrouver un cheval qui a fui Wheeler's Grange.",al={"qui m'a donné ça","chevaux de benjy"}},{q="Que dois-je faire du fourrage ?",a="Donnez du fourrage à un cheval pour gagner sa confiance et le ramener.",al={"comment utiliser le sac","nourrir un cheval"}},{q="Pourquoi cherche-t-on les chevaux ?",a="Benjy dit qu'il faut retrouver les chevaux échappés avant le retour des coyotes.",al={"pourquoi retrouver les chevaux","où sont-ils allés"}}},fp="24,127,20.231.0,28.78.0,23.58.0,31.70.0,32.72.0"}
P.entries["quest:94638"] = {n="Strength and Mercy",s="Le compagnon d'Ur'endra vous demande d'abréger ses souffrances après qu'elle a sombré dans la folie. Votre détermination vous vaut une bénédiction permettant de prendre la forme de ses semblables.",h="Le compagnon d'Ur'endra vous demande d'abréger ses souffrances après qu'elle a sombré dans la folie.",kw={"bénédiction du druide","plaines aérelles","forme de la griffe","hautes-terres de shen’dar","force et miséricorde","ur'endra","magie des vents"},ang={["class:Druid"]="En tant que druide, vous devez prouver votre détermination avant de recevoir une bénédiction permettant de prendre la forme des semblables du druide."},sec={{t="Une douloureuse requête",b="Un druide vous demande d'abréger les souffrances d'Ur'endra dans les Hautes-terres de Shen’dar. Elle est sa compagne, mais la folie l'a retournée contre les siens. La perte de la magie des vents a fait perdre la raison à de nombreuses créatures, dont Ur'endra. Son antre se trouve dans une grotte à l'ouest d'ici, le long des falaises entre les Hautes-terres de Shen’dar et les Plaines Aérelles."},{t="La bénédiction",b="Dans les Hautes-terres de Shen’dar, le compagnon d'Ur'endra pleure sa perte et la juge nécessaire à l'équilibre. Il reconnaît votre détermination à accepter un prix aussi terrible. Il vous accorde une bénédiction permettant de prendre la forme de ses semblables et vous charge d'aider les faibles et de défendre les démunis."}},faq={{q="Qui est Ur'endra ?",a="Ur'endra est la compagne du druide qui vous demande d'abréger ses souffrances.",al={"ur'endra","qui est urendra","compagne du druide"}},{q="Pourquoi Ur'endra attaque-t-elle les siens ?",a="Ur'endra a sombré dans la folie. La perte de la magie des vents a fait perdre la raison à de nombreuses créatures.",al={"pourquoi urendra est folle","urendra attaque","qu'est-il arrivé à urendra"}},{q="Où se trouve l'antre d'Ur'endra ?",a="Ur'endra a établi son antre dans une grotte à l'ouest du druide, dans les falaises entre les Hautes-terres de Shen’dar et les Plaines Aérelles.",al={"grotte d'urendra","où est urendra","grotte de shen'dar"}},{q="Que me demande le druide ?",a="Le druide vous demande d'abréger les souffrances d'Ur'endra.",al={"tâche urendra","que faire","tuer urendra"}},{q="Quelle bénédiction le druide accorde-t-il ?",a="Le druide vous accorde une bénédiction permettant de prendre la forme de ses semblables.",al={"bénédiction de forme","voie de la griffe","bénédiction du druide"}},{q="Pourquoi le druide demande-t-il cela ?",a="Le druide estime qu'abréger les souffrances d'Ur'endra est nécessaire à l'équilibre.",al={"pourquoi tuer urendra","pourquoi est-ce nécessaire","équilibre"}}},fp="18,141,12.353.0,12.293.1,16.68.0,34.112.0,25.125.0,33.47.0,35.72.0,32.74.0"}
P.entries["quest:94668"] = {n="Bloodmaster's Ring",s="Au Bloodmaster's Ring, vous faites votre rapport à Jezap après avoir fait vos preuves contre les Twilight ogres. Le Bloodmaster est prêt à décider si vous avez votre place ici.",h="Au Bloodmaster's Ring, vous faites votre rapport à Jezap après avoir fait vos preuves contre les Twilight...",kw={"bloodmaster","bloodmaster's ring","gobelin","jezap","précipice du pouvoir","twilight ogres"},sec={{t="Au Bloodmaster's Ring",b="Le défi du Bloodmaster's Ring vous a conduit auprès de Jezap, le gobelin de l’anneau. Après avoir vaincu les Twilight ogres, vous lui faites votre rapport, sous le regard du Bloodmaster et de Jezap. Ils déterminent si vous avez votre place parmi ceux qui s’approchent du précipice du pouvoir."}},faq={{q="À qui dois-je faire mon rapport au Bloodmaster's Ring ?",a="Vous faites votre rapport à Jezap au Bloodmaster's Ring.",al={"qui est jezap","faire son rapport à jezap","gobelin du bloodmaster's ring"}},{q="Qu'ai-je fait avant de venir ici ?",a="Vous avez écrasé des Twilight ogres jugés faibles.",al={"que s'est-il passé avant","twilight ogres","étape précédente du bloodmaster's ring"}},{q="Que cherche le Bloodmaster ?",a="Le Bloodmaster décide si vous avez votre place au précipice du pouvoir.",al={"faire ses preuves","que veut le bloodmaster","ai-je ma place"}}},fp="18,147,11.267.0,45.46.0,33.49.0,36.72.0"}
P.entries["quest:94669"] = {n="Pay to Play",s="Un collectionneur exige un dépôt de garantie avant de vous laisser entrer dans le Bloodmaster's Ring. Payez, et vous pourrez y prouver votre force.",h="Un collectionneur exige un dépôt de garantie avant de vous laisser entrer dans le Bloodmaster's Ring.",kw={"bloodmaster's ring","clugfist","payer pour jouer","prouver votre force","arène","dépôt de garantie"},sec={{t="Le prix d’entrée",b="Pour entrer dans le Bloodmaster's Ring, on vous demande de verser un dépôt de garantie. Le collectionneur affirme que ce paiement est nécessaire à votre sécurité. Sans cela, il menace de dire à Clugfist que vous avez refusé de prouver votre force à la compagnie qui vous accueille. Votre choix détermine si vous pourrez entrer dans l’arène."}},faq={{q="Pourquoi dois-je payer ?",a="Le collectionneur affirme qu’un dépôt de garantie est nécessaire à votre sécurité et pour pouvoir entrer dans le Bloodmaster's Ring.",al={"pourquoi payer","dépôt de garantie","quête payer pour jouer"}},{q="Qui est Clugfist ?",a="Clugfist est la personne à qui le collectionneur menace de parler si vous refusez de payer.",al={"qui est clugfist","clugfist","le vieux clugfist"}},{q="Que se passe-t-il si je refuse ?",a="Le collectionneur affirme qu’il dira à Clugfist que vous n’avez pas voulu prouver votre force.",al={"ne pas payer","refuser le dépôt","pas de dépôt"}},{q="À quoi me donne droit le paiement ?",a="Le dépôt de garantie vous donne le droit d’entrer dans le Bloodmaster's Ring.",al={"pour quoi se qualifier","entrée dans l’arène","bloodmaster ring"}}},fp="11,132,18.294.0,21.106.0,16.76.0,25.90.0,32.67.0"}
P.entries["quest:94670"] = {n="Bloodmaster's Ring",s="Le défi de Bloodmaster's Ring vous oppose à Buzzbeak, avec la gloire à la clé. Le gobelin de l'arène pense que le combat sera facile.",h="Le défi de Bloodmaster's Ring vous oppose à Buzzbeak, avec la gloire à la clé.",kw={"bloodmaster","bloodmaster's ring","buzzbeak","renommée","créature démoniaque","combat","arène"},sec={{t="Dans l'arène",b="Le gobelin de l'arène place Buzzbeak devant vous dans l'arène. On vous dit que ce premier combat devrait être facile, même si la créature est réputée pour terrasser son adversaire et lui prendre ses effets personnels. La gloire est promise à ceux qui entrent dans l'arène."}},faq={{q="Qui dois-je affronter dans le Bloodmaster's Ring ?",a="Vous affrontez Buzzbeak dans le Bloodmaster's Ring.",al={"combat du bloodmaster","qui est buzzbeak","adversaire de l'arène"}},{q="Que doit faire Buzzbeak ?",a="Buzzbeak est décrit comme une créature démoniaque imprévisible, capable de vous terrasser et de vous dérober vos affaires.",al={"attaque de buzzbeak","que fait buzzbeak","créature démoniaque dans l'arène"}},{q="Pourquoi entrer dans l'arène ?",a="Le gobelin de l'arène promet la gloire à ceux qui y entrent.",al={"renommée dans l'arène","renommée du bloodmaster","pourquoi affronter buzzbeak"}},{q="Ce combat est-il censé être facile ?",a="Le gobelin de l'arène présente ce combat comme un premier affrontement facile.",al={"combat facile dans l'arène","bloodmaster facile","buzzbeak difficile"}}},fp="18,129,13.212.0,41.44.0,32.90.0,19.54.0,31.55.0"}
P.entries["quest:94672"] = {n="Encroaching Twilight",s="Tran'gul avertit que le Marteau du crépuscule a frappé un établissement humain à l’ouest de Rog’mar. Vous êtes envoyé à Clairsoleil pour réduire les effectifs du culte avant qu’il ne s’implante dans les environs.",h="Tran'gul avertit que le Marteau du crépuscule a frappé un établissement humain à l’ouest de Rog’mar.",kw={"crépuscule menaçant","établissement humain","rog’mar","clairsoleil","tran'gul","néophytes du crépuscule","pillards du crépuscule","marteau du crépuscule"},sec={{t="Une menace proche",b="L’établissement humain à l’ouest a déjà été ravagé, et Rog’mar pourrait être la prochaine cible. Tran'gul vous envoie à Clairsoleil, où le Marteau du crépuscule a lancé sa campagne contre ceux qu’il qualifie d’hérétiques. Ses pillards et ses néophytes menacent de s’implanter près de Rog’mar."},{t="Après le combat",b="Les effectifs du culte ayant diminué, Tran'gul peut chercher la source de son expansion sans précédent."}},faq={{q="Qui inquiète Tran'gul ?",a="Tran'gul craint le Marteau du crépuscule, un culte qui s’en prend à ceux qu’il juge hérétiques.",al={"qui est la menace","menace du marteau du crépuscule"}},{q="Qu’est-il arrivé à l’établissement humain ?",a="Le Marteau du crépuscule a ravagé un établissement humain à l’ouest de Rog’mar.",al={"établissement à l’ouest","que s’est-il passé à l’ouest"}},{q="Pourquoi vais-je à Clairsoleil ?",a="Tran'gul vous envoie à Clairsoleil pour réduire les effectifs du Marteau du crépuscule.",al={"pourquoi clairsoleil","que trouve-t-on à clairsoleil"}},{q="Qui le culte pourrait-il cibler ensuite ?",a="Tran'gul craint que Rog’mar ne soit la prochaine cible après l’établissement humain à l’ouest.",al={"qui est le prochain","rog’mar ensuite"}}},fp="20,173,15.274.0,15.96.1,30.75.0,38.65.0,29.74.0,31.74.0"}
P.entries["quest:94679"] = {n="Snargl's Snout",s="À Southern Watch, Cedric Dalton veut le museau de Snargl, dans les Collines Hirsutes. Il pense que tuer un gnoll puissant affaiblira les rangs des Carmines et les effraiera.",h="À Southern Watch, Cedric Dalton veut le museau de Snargl, dans les Collines Hirsutes.",kw={"collines hirsutes","cedric dalton","gnoll","les carmines","snargl","museau de snargl","southern watch"},sec={{t="Un gnoll dans les collines",b="À Southern Watch, Cedric Dalton vous demande de vous occuper de Snargl, un gnoll tristement célèbre qui vit dans un repaire des Collines Hirsutes. Il pense que les gnolls ne jurent que par la force. La mort de Snargl pourrait donc affaiblir les rangs des Carmines et semer la peur parmi eux. Cedric veut que vous lui rapportiez le museau de Snargl."},{t="Un trophée rapporté",b="Cedric reçoit le museau de Snargl comme trophée et dit qu’il sera bientôt mis à profit. La mort du gnoll doit semer la peur dans les rangs des Carmines."}},faq={{q="Qui est Snargl ?",a="Snargl est un gnoll tristement célèbre qui vit dans un repaire des Collines Hirsutes.",al={"qui est snargl","snargl gnoll","gnoll des collines hirsutes"}},{q="Qui veut le museau de Snargl ?",a="Cedric Dalton, à Southern Watch, vous demande de lui rapporter le museau de Snargl.",al={"pour qui le museau de snargl","demande de cedric dalton","museau de southern watch"}},{q="Pourquoi Cedric veut-il la mort de Snargl ?",a="Cedric pense que les gnolls accordent plus d’importance à la force qu’à tout le reste, et que tuer le plus fort d’entre eux les affaiblira et les effraiera.",al={"pourquoi tuer snargl","force des gnolls","effrayer les carmines"}},{q="Où se trouve Snargl ?",a="Snargl se trouve dans un repaire des Collines Hirsutes.",al={"emplacement de snargl","où se trouve snargl","repaire des collines hirsutes"}}},fp="14,159,20.287.0,17.144.1,14.61.0,25.69.0,33.122.0,16.43.0"}
P.entries["quest:94680"] = {n="Twilight Missives",s="Tran'gul cherche pourquoi les cultistes du Marteau du crépuscule sont plus nombreux près de Clairsoleil. Il vous demande de rapporter leurs missives pour découvrir ce qu'ils cherchent.",h="Tran'gul cherche pourquoi les cultistes du Marteau du crépuscule sont plus nombreux près de Clairsoleil.",kw={"cultistes","missives","rog’mar","clairsoleil","tran'gul","missives du crépuscule","twilight shadowmancers","marteau du crépuscule"},sec={{t="Une présence grandissante",b="Tran'gul a vu plus de cultistes du Marteau du crépuscule dans la région qu'avant. Les Twilight Shadowmancers sont des membres de confiance de l'ordre et pourraient connaître sa campagne. Vous devez rapporter leurs missives pour que Tran'gul découvre ce que cherche le culte."}},faq={{q="Qui demande les missives du Crépuscule ?",a="Tran'gul, à Rog’mar, vous demande de récupérer les missives des Twilight Shadowmancers à Clairsoleil.",al={"qui veut les missives","requête de tran'gul","qui est tran'gul"}},{q="Où trouver les Twilight Shadowmancers ?",a="Les Twilight Shadowmancers se trouvent à Clairsoleil.",al={"lieu des twilight shadowmancers","où sont les cultistes du crépuscule","missives de clairsoleil"}},{q="Pourquoi Tran'gul veut-il les missives ?",a="Tran'gul veut en apprendre davantage sur les cultistes et ce qu'ils cherchent.",al={"pourquoi récupérer les missives","que veut savoir tran'gul","documents des cultistes"}},{q="Pourquoi les cultistes inquiètent-ils Tran'gul ?",a="Tran'gul a vu plus de cultistes du Marteau du crépuscule qu'avant, et ils semblent enhardis à étendre leur influence.",al={"pourquoi le marteau du crépuscule est ici","cultistes de plus en plus nombreux","nombre de cultistes du crépuscule"}}},fp="17,171,18.258.0,35.91.0,44.45.0,36.67.0,45.128.0"}
P.entries["quest:947"] = {n="La caverne aux champignons",s="À Sombrivage, la caverne aux champignons fournit les ingrédients d’une potion que prépare Barithras Lunombrage à Auberdine. Il vous demande de récolter des champignons rares derrière les Chutes de la Bondissante et d’enquêter sur les avertissements du Bosquet des Anciens.",h="À Sombrivage, la caverne aux champignons fournit les ingrédients d’une potion que prépare Barithras...",kw={"auberdine","barithras lunombrage","la caverne aux champignons","chutes de la bondissante","sombrivage","amanite phalloïde","bosquet des anciens","onu","tiges de scaber"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous savez qu’Auberdine est le principal bastion de l’Alliance sur la côte de Kalimdor. Un mal qui se répand dans les montagnes de l’est menace tout le littoral.",["profession:Herbalism"]="En tant qu’herboriste, la recherche d’Amanites phalloïdes et de tiges de scaber pourrait vous intéresser. Ces champignons poussent dans des cavernes sombres plutôt que dans les sols luxuriants des bois.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous savez que le Bosquet des Anciens est profondément lié à l’équilibre naturel de Sombrivage. Toute perturbation sous les chutes préoccupe les Kaldorei."},sec={{t="Une recette derrière les chutes",b="Barithras Lunombrage a besoin de tiges de scaber et d’une Amanite phalloïde pour préparer un mélange puissant. Ces deux champignons poussent dans une caverne humide derrière les Chutes de la Bondissante, au nord-est de Sombrivage. Les récolter est plus dangereux que cueillir des herbes ordinaires des bois."},{t="L’avertissement des Anciens",b="Les gardiens des arbres du Bosquet des Anciens ont mis Barithras en garde contre la caverne. Ils sentent une présence malfaisante dans les grottes de la montagne. Lunombrage vous envoie découvrir si les craintes des anciens concernant un mal qui gagne le nord de Sombrivage sont fondées."}},faq={{q="Où cette mission commence-t-elle ?",a="Barithras Lunombrage vous confie cette mission à Auberdine, le village des Elfes de la nuit sur la côte centrale de Sombrivage.",al={"où trouver la caverne aux champignons","emplacement de barithras lunombrage","début de la quête de la caverne aux champignons"}},{q="Où se trouvent les champignons ?",a="Les champignons poussent dans une caverne derrière les Chutes de la Bondissante, le long de la montagne au nord-est d’Auberdine.",al={"où trouver les tiges de scaber","emplacement de l’amanite phalloïde","caverne derrière la cascade de sombrivage"}},{q="Pourquoi Barithras Lunombrage ne va-t-il pas chercher les champignons lui-même ?",a="Le Bosquet des Anciens a averti Barithras de se tenir à l’écart des chutes. Les grands Anciens sentent qu’un mal surnaturel grandissant s’est réfugié dans la grotte.",al={"pourquoi barithras n’y va pas","pourquoi barithras reste à auberdine"}},{q="Quels champignons faut-il trouver précisément ?",a="Lunombrage a besoin de cinq tiges de scaber et d’une Amanite phalloïde dangereuse pour sa potion.",al={"champignons nécessaires","champignons pour lunombrage"}},{q="Où cette mission vous mène-t-elle ensuite ?",a="Après avoir vérifié la présence dans la grotte et livré les champignons, vous partez vers le sud retrouver Onu, l’ancien protecteur du Bosquet des Anciens.",al={"quête suivante après la caverne aux champignons","suite de quête d’onu"}},{q="Pourquoi les Anciens s’inquiètent-ils des Chutes de la Bondissante ?",a="Le Bosquet des Anciens a averti Barithras qu’un mal grandissant pourrait rôder dans la caverne derrière les chutes. Il vous demande de récolter des champignons et d’enquêter sur cet avertissement.",al={"avertissement des anciens aux chutes de la bondissante","pourquoi explorer la caverne"}}},fx={a048db56={q="Pourquoi Barithras Lunombrage veut-il que cela soit fait ?",a="Barithras Lunombrage est un herboriste qui prépare une nouvelle potion puissante nécessitant des champignons rares que l'on ne trouve que dans la grotte située derrière les Chutes de la Bondissante. Au-delà de son travail alchimique, il porte cependant une inquiétude plus profonde : le Bosquet des Anciens l'a averti qu'un mal grandissant rôdait au sein même de cette grotte. En vous envoyant récolter les ingrédients, il espère également découvrir si les sinistres présages des Anciens sont fondés.",al={"pourquoi barithras veut-il des cave mushrooms","motivation de barithras lunombrage","pourquoi collecter des champignons pour barithras"}},["991c4c10"]={q="À quoi sert l'amanite phalloïde ?",a="L'amanite phalloïde est un champignon toxique exceptionnellement rare et puissant, originaire de la grotte située derrière les Chutes de la Bondissante. Barithras Lunombrage a besoin d'un spécimen intact comme réactif clé pour une potion spécialisée qu'il élabore à Auberdine.",al={"à quoi sert l'amanite phalloïde","but de l'amanite phalloïde","pourquoi barithras a-t-il besoin d'amanite phalloïde"}},be6516db={q="À quoi sert le pédoncule d'amanite ?",a="Les pédoncules d'amanite sont des champignons rares qui prospèrent dans la grotte humide et ombragée située derrière les Chutes de la Bondissante. Barithras Lunombrage en a besoin de cinq pour les incorporer dans ses concoctions alchimiques en cours, aux côtés de la puissante amanite phalloïde.",al={"à quoi servent les pédoncules d'amanite","but du pédoncule d'amanite","pourquoi barithras a-t-il besoin de pédoncules d'amanite"}}},fp="14,210,25.227.0,21.252.1,27.115.0,32.104.0,61.156.0,35.87.0,35.141.0,55.161.1"}
P.entries["quest:94727"] = {n="Digging for Answers",s="Le Marteau du crépuscule fouille les Rives Claires à la recherche d’une source de pouvoir inconnue. Vous êtes envoyé à Clairsoleil pour interroger l’un de ses mineurs.",h="Le Marteau du crépuscule fouille les Rives Claires à la recherche d’une source de pouvoir inconnue.",kw={"creuser pour trouver des réponses","mineur","rives claires","source of power","clairsoleil","marteau du crépuscule"},sec={{t="Les mineurs de Clairsoleil",b="Le Marteau du crépuscule fait creuser des ouvriers à Clairsoleil, et vous êtes envoyé pour interroger l’un des mineurs. Leur recherche semble viser une source de pouvoir, mais sa nature reste inconnue. Les zélotes gardent leurs secrets, alors les mineurs savent peut-être ce qu’ils cherchent."}},faq={{q="Que cherche le Marteau du crépuscule en creusant ?",a="Le Marteau du crépuscule semble chercher une source de pouvoir dans les Rives Claires, mais on ignore encore de quoi il s’agit.",al={"que cherchent-ils en creusant","creuser du marteau du crépuscule","source of power"}},{q="Pourquoi est-ce que j’interroge un mineur ?",a="Les zélotes du Marteau du crépuscule gardent leurs secrets, alors vous êtes envoyé à Clairsoleil pour interroger l’un de leurs mineurs.",al={"pourquoi un mineur","parler au mineur","quête creuser pour trouver des réponses"}},{q="Où se trouvent les mineurs ?",a="Les mineurs creusent à Clairsoleil, dans les Rives Claires.",al={"où se trouve clairsoleil","emplacement du mineur","creuser dans les rives claires"}}},fp="19,148,20.255.0,42.119.0,29.112.0,21.61.0"}
P.entries["quest:94733"] = {n="Our Ogre Friend",s="Un gobelin vous demande de retrouver Gobam à Bolder'ok et d'apporter de la nourriture à Snufflesnout, le sanglier de compagnie de Chub'chob. Gobam accepte d'aider, car Chub'chob est son ami.",h="Un gobelin vous demande de retrouver Gobam à Bolder'ok et d'apporter de la nourriture à Snufflesnout, le...",kw={"bolder'ok","chub'chob","repaire","gobam","gobelin","notre ami ogre","sanglier de compagnie","snufflesnout"},sec={{t="La requête d'un ami",b="Après quelques victoires, le gobelin vous demande de retrouver Gobam à Bolder'ok. Il lui faut de la nourriture pour Snufflesnout, le sanglier de compagnie de Chub'chob, mais il dit que son travail l'occupe beaucoup. Gobam se trouve à l'est du repaire de Clugfist, et le gobelin espère que vous pourrez le trouver."}},faq={{q="Qui est Gobam ?",a="Gobam est le timide que le gobelin vous envoie chercher à Bolder'ok.",al={"qui est gobam"}},{q="Où trouver Gobam ?",a="Gobam se trouve à l'est du repaire de Clugfist, à Bolder'ok.",al={"emplacement de gobam","où trouver gobam"}},{q="Qui est Snufflesnout ?",a="Snufflesnout est le sanglier de compagnie de Chub'chob, et le gobelin vous demande de lui apporter de la nourriture.",al={"snufflesnout","nourriture pour sanglier"}},{q="Pourquoi le gobelin a-t-il besoin d'aide ?",a="Le gobelin dit que son travail l'occupe beaucoup, alors il vous demande de trouver de la nourriture pour Snufflesnout.",al={"pourquoi aider le gobelin","gobelin occupé"}},{q="Pourquoi Gobam va-t-il aider ?",a="Gobam dit qu'il n'aime pas le gobelin, mais qu'il aidera Chub'chob parce qu'ils sont de bons amis.",al={"aide de gobam","pourquoi gobam aide"}}},fp="15,157,20.242.0,13.66.0,23.51.0,20.83.0,30.86.0,20.92.0"}
P.entries["quest:94734"] = {n="A Boar's Delight",s="Gobam vous demande de ramasser des baies sucrées et des plantes de rivière pour Snufflesnout, l’animal de compagnie de Chub'chob. Ces ingrédients composeront une friandise spéciale.",h="Gobam vous demande de ramasser des baies sucrées et des plantes de rivière pour Snufflesnout, l’animal de...",kw={"baie","gobam","animal de compagnie","herbe de rivière","snufflesnout","baie sucrée","friandise"},sec={{t="Une friandise pour animal",b="Gobam veut préparer quelque chose de spécial pour Snufflesnout, qui aime la bonne nourriture. Il vous demande de rapporter des baies sucrées et des plantes de rivière pour la friandise."}},faq={{q="Qui est Gobam",a="Gobam vous demande d’apporter les ingrédients d’une friandise spéciale pour Snufflesnout, l’animal de compagnie de Chub'chob.",al={"qui est gobam","qui demande des baies"}},{q="Qui est Snufflesnout",a="Snufflesnout est l’animal de compagnie de Chub'chob et adore la bonne nourriture.",al={"snufflesnout animal de compagnie","animal de compagnie de gobam"}},{q="Quels ingrédients Gobam demande-t-il",a="Gobam demande des baies sucrées et de l'herbe de rivière pour préparer une friandise à Snufflesnout.",al={"baies et plante","quelle nourriture"}},{q="Pourquoi Gobam veut-il des baies",a="Gobam veut des baies sucrées et de l'herbe de rivière pour préparer une friandise spéciale à Snufflesnout.",al={"pourquoi des baies","des baies pour quoi"}}},fp="16,133,13.150.0,13.95.0,20.52.0,33.76.0,28.81.0"}
P.entries["quest:94739"] = {n="Bloodmaster's Ring",s="Le gobelin du Bloodmaster's Ring vous envoie dans la fosse du Bloodmaster's Ring pour affronter Kronk. La foule attend déjà avec impatience le prochain combat.",h="Le gobelin du Bloodmaster's Ring vous envoie dans la fosse du Bloodmaster's Ring pour affronter Kronk.",kw={"présentateur","bloodmaster","bloodmaster's ring","combat","combattant","kronk","fosse"},sec={{t="Le prochain combat",b="Le présentateur prépare la foule tandis que Kronk attend son tour comme prochain combattant. Vous êtes envoyé dans la fosse pour l'affronter, et le bruit monte à l'approche du combat."}},faq={{q="Qui est Kronk ?",a="Kronk est le prochain combattant du Bloodmaster's Ring. Le présentateur dit qu'ils se connaissent depuis longtemps et le décrit comme un bagarreur puissant.",al={"kronk","qui est kronk","kronk bloodmaster"}},{q="Que veut le Bloodmaster ?",a="On vous envoie dans la fosse du Bloodmaster's Ring pour affronter Kronk.",al={"que faire","mission de l'arène","bloodmaster ring"}},{q="Pourquoi dois-je affronter Kronk ?",a="Le présentateur annonce Kronk comme prochain combattant, et le combat est prévu dans le Bloodmaster's Ring.",al={"pourquoi kronk","affronter kronk","combat contre kronk"}},{q="Où a lieu le combat ?",a="Le combat a lieu dans la fosse du Bloodmaster's Ring.",al={"où a lieu le combat","la fosse","emplacement de l'arène"}},{q="Que se passe-t-il après mon entrée dans la fosse ?",a="Le présentateur s'apprête à annoncer Kronk tandis que vous vous préparez dans la fosse.",al={"après être entré","prochain dans l'arène","que se passe-t-il ensuite"}},{q="Que dit le présentateur au sujet de Kronk ?",a="Le présentateur dit que Kronk n'est pas très malin, mais qu'il sait cogner tout ce qui se trouve sur son chemin.",al={"histoire de kronk","à quoi ressemble kronk","présentateur kronk"}}},fp="18,136,13.160.0,13.130.0,40.66.0,24.101.0,31.58.0,35.78.0,40.91.0"}
P.entries["quest:94744"] = {n="The Wayward Warrior",s="Krom'rosh vous demande de rejoindre son frère Dag'rosh au bastion du Marteau du crépuscule, à l'ouest de Rog’mar. Le culte a perdu du terrain à Clairsoleil, et le combat se déplace vers son bastion.",h="Krom'rosh vous demande de rejoindre son frère Dag'rosh au bastion du Marteau du crépuscule, à l'ouest de...",kw={"dag'rosh","krom'rosh","guerriers ogres","rog’mar","clairsoleil","le guerrier égaré","marteau du crépuscule"},sec={{t="Un frère en éclaireur",b="Krom'rosh vous envoie rejoindre Dag'rosh, parti en avant avec une patrouille d'éclaireurs. Vous devez le chercher dans les collines à l'ouest de Rog’mar. Krom'rosh dit que le Marteau du crépuscule a perdu du terrain à Clairsoleil et que ses guerriers ogres se sont retournés contre lui. Il veut maintenant que vous rejoigniez son frère tandis que la bataille se déplace vers le bastion du culte."}},faq={{q="Qui me demande de retrouver Dag'rosh ?",a="Krom'rosh vous demande de rejoindre son frère Dag'rosh au bastion du Marteau du crépuscule.",al={"qui m'a envoyé","krom'rosh","qui veut retrouver dag'rosh"}},{q="Où puis-je trouver Dag'rosh ?",a="Krom'rosh vous dit de chercher Dag'rosh dans les collines à l'ouest de Rog’mar.",al={"où est dag'rosh","emplacement de dag'rosh","trouver dag'rosh"}},{q="Qui est Dag'rosh ?",a="Dag'rosh est le frère de Krom'rosh. Il est parti en avant avec une patrouille d'éclaireurs.",al={"histoire de dag'rosh","frère de krom'rosh","qui est dag'rosh"}},{q="Qu'est-il arrivé au Marteau du crépuscule à Clairsoleil ?",a="Le Marteau du crépuscule a perdu du terrain à Clairsoleil, et ses guerriers ogres se sont retournés contre lui.",al={"culte de clairsoleil","bastion du marteau du crépuscule","qu'est-il arrivé aux ogres"}}},fp="19,191,15.334.0,34.84.0,26.65.0,16.73.0,53.104.0"}
P.entries["quest:94773"] = {n="Divine Grace",s="Une leçon appelée Divine Grace vous remercie de servir la Lumière. Votre exemple compte pour les voyageurs en terres dangereuses.",h="Une leçon appelée Divine Grace vous remercie de servir la Lumière.",kw={"terres dangereuses","divine grace","leçon","lumière","voyageurs"},sec={{t="Une leçon en remerciement",b="Après vos services, la Lumière est louée pour l’exemple que vous donnez aux voyageurs en terres dangereuses. Une leçon vous est offerte en remerciement de ce que vous avez accompli."}},faq={{q="De quoi parle Divine Grace ?",a="Divine Grace vous remercie de servir la Lumière et de donner l’exemple aux voyageurs en terres dangereuses.",al={"divine grace","qu’est-ce que divine grace","quête divine grace"}},{q="À qui cette leçon est-elle destinée ?",a="Cette leçon vous est offerte en remerciement de vos services à la Lumière.",al={"qui reçoit la leçon","leçon pour moi","récompense divine grace"}},{q="Quel exemple ai-je donné ?",a="Vous êtes devenu un exemple pour les voyageurs en terres dangereuses et au-delà.",al={"mon exemple","exemple éclatant","qu’ai-je fait"}}},fp="12,116,18.159.0,27.102.0,23.69.0,23.65.0"}
P.entries["quest:94774"] = {n="Divine Grace",s="La Grande prêtresse Laurena vous appelle à la Cathédrale de la Lumière de Hurlevent, car vos supérieurs ont approuvé la poursuite de votre formation. Vos leçons dans les voies de la Lumière sont prêtes à commencer.",h="La Grande prêtresse Laurena vous appelle à la Cathédrale de la Lumière de Hurlevent, car vos supérieurs ont...",kw={"cathédrale de la lumière","grâce divine","grande prêtresse laurena","lumière","serviteur de la lumière","hurlevent","formation"},ang={["class:Priest"]="En tant que prêtre, vos supérieurs ont approuvé la poursuite de votre formation dans les voies de la Lumière."},sec={{t="Un appel à Hurlevent",b="Vos supérieurs vous envoient à la Cathédrale de la Lumière de Hurlevent après avoir jugé que vous avez fait vos preuves. Là, la Grande prêtresse Laurena est prête à vous guider dans la suite de votre formation. Elle dit que chaque serviteur de la Lumière doit apprendre certaines leçons, et elle est prête à en discuter avec vous."}},faq={{q="Pourquoi m’envoie-t-on à Hurlevent ?",a="Vos supérieurs estiment que vous avez fait vos preuves et ont approuvé la poursuite de votre formation dans les voies de la Lumière.",al={"pourquoi hurlevent","envoi à la cathédrale","pourquoi y aller"}},{q="Qui est la Grande prêtresse Laurena ?",a="La Grande prêtresse Laurena se trouve dans la Cathédrale de la Lumière de Hurlevent et est prête à vous guider dans votre formation.",al={"laurena qui","qui est laurena","grande prêtresse"}},{q="Où trouver la Grande prêtresse Laurena ?",a="La Grande prêtresse Laurena se trouve à la Cathédrale de la Lumière de Hurlevent.",al={"emplacement de laurena","où est laurena","emplacement de la cathédrale"}},{q="Quelle formation Laurena propose-t-elle ?",a="Laurena est prête à discuter des leçons que tous les serviteurs de la Lumière doivent apprendre.",al={"formation dans la lumière","quelles leçons","apprendre les voies de la lumière"}}},fp="12,181,19.290.0,33.108.0,30.101.0,39.65.0,34.81.0"}
P.entries["quest:94789"] = {n="Call of Air",s="Un chaman est envoyé auprès de Veyric Thundervein dans les collines du nord des Hautes-terres Arathies. Il vous en apprendra davantage sur la maîtrise de l’air.",h="Un chaman est envoyé auprès de Veyric Thundervein dans les collines du nord des Hautes-terres Arathies.",kw={"air","hautes-terres arathies","call of air","chaman","esprits de l’air","veyric thundervein","sorts de vent"},sec={{t="Les collines du nord",b="Un chaman vous envoie au nord, dans les Hautes-terres Arathies, pour trouver Veyric Thundervein. L’élément de l’air est difficile à maîtriser, et il peut vous en apprendre davantage. Vos compétences grandissantes vous ont mené jusqu’ici ; votre formation se tourne désormais vers le vent et les esprits de l’air."}},faq={{q="Qui est Veyric Thundervein ?",a="Veyric Thundervein se trouve dans les collines du nord des Hautes-terres Arathies, où il peut vous en apprendre davantage sur l’air.",al={"veyric","qui est veyric","maître de l’air"}},{q="Où trouver Veyric ?",a="Trouvez Veyric Thundervein dans les collines du nord des Hautes-terres Arathies.",al={"emplacement de veyric","où est veyric","maître de l’air d’arathi"}},{q="De quoi parle Call of Air ?",a="Un chaman vous envoie auprès de Veyric Thundervein pour qu’il vous en apprenne davantage sur l’élément de l’air.",al={"quête call of air","formation à l’air","sorts de vent"}},{q="Pourquoi dois-je me rendre dans les Hautes-terres Arathies ?",a="Veyric Thundervein se trouve dans les collines du nord des Hautes-terres Arathies, et il vous en apprendra davantage sur l’air.",al={"pourquoi arathi","quête aller au nord","trouver veyric"}},{q="Qu’enseigne Veyric ?",a="Veyric vous apprend à canaliser les sorts de vent et à faire appel aux esprits de l’air.",al={"formation de veyric","esprits de l’air","canaliser les sorts de vent"}}},fp="11,125,18.245.0,26.103.0,23.66.0,26.91.0,35.102.0,23.73.0"}
P.entries["quest:94792"] = {n="Taming the Beast",s="Josephine Carson forme les chasseurs en herbe dans Taming the Beast aux soins à apporter à un compagnon sauvage. L'épreuve met en scène un Rockhide Boar et un Bâtonnet de domptage, dans le respect de l'équilibre naturel.",h="Josephine Carson forme les chasseurs en herbe dans Taming the Beast aux soins à apporter à un compagnon...",kw={"compagnon animal","équilibre de la nature","domptage des bêtes","familier du chasseur","josephine carson","rockhide boar","bâtonnet de domptage","taming the beast"},ang={["class:Druid"]="En tant que druide, vous savez que le soin et la retenue contribuent à préserver l'équilibre de la nature. Respecter la faune des forêts honore l'ordre naturel que vous avez juré de protéger.",["class:Hunter"]="En tant que chasseur, dompter des bêtes sauvages est un rite de passage essentiel. Un compagnon loyal protège et veille au combat, forgeant un lien durable entre le pisteur et la bête."},sec={{t="Se lier aux bêtes",b="Voyager seul dans la nature peut être dangereux. Un compagnon animal protège au combat et tient compagnie lors des longs périples. Pour les chasseurs et pisteurs en herbe, nouer ce lien est une étape essentielle. Josephine Carson guide les novices dans une épreuve avec un Rockhide Boar et un Bâtonnet de domptage. Pour calmer et diriger la bête, ils doivent garder leur sang-froid et rester concentrés, sans céder à la peur ni provoquer de bain de sang inutile."},{t="L'équilibre de la nature",b="Josephine Carson met ses élèves en garde contre l'exploitation inconsidérée des bêtes. Le domptage exige patience et discipline, jamais cruauté ni domination, et il faut préserver l'équilibre de la nature. Le bâtonnet enchanté permet aux novices de s'exercer à maîtriser un redoutable Rockhide Boar sans épuiser durablement la faune locale. Une fois qu'ils savent diriger et apaiser la bête, ils rendent le bâtonnet. Le respect de la nature passe avant l'orgueil."}},faq={{q="Quel est le but de la quête Taming the Beast ?",a="Taming the Beast apprend aux chasseurs en herbe à se lier aux créatures sauvages. Josephine Carson leur montre comment approcher et apaiser un Rockhide Boar à l'aide d'un Bâtonnet de domptage. L'épreuve enseigne des techniques de survie et le respect de l'équilibre naturel.",al={"quête taming the beast","qu'est-ce que taming the beast","quête de familier du chasseur"}},{q="Qui est Josephine Carson ?",a="Josephine Carson apprend aux aventuriers à prendre soin de leurs compagnons animaux. Elle prête un Bâtonnet de domptage à ses élèves afin qu'ils s'exercent à faire preuve de patience et d'habileté avec les bêtes. Elle leur enseigne que cela demande de la pratique et le respect de l'équilibre naturel.",al={"josephine carson","qui donne taming the beast","donneur de quête bâtonnet de domptage"}},{q="À quoi sert le Bâtonnet de domptage ?",a="Le Bâtonnet de domptage est un outil enchanté qui permet de maîtriser une bête redoutable en toute sécurité. Il permet aux novices de s'exercer à diriger et apaiser un Rockhide Boar sans épuiser durablement la faune locale. Ils rendent le bâtonnet une fois les rudiments appris.",al={"bâtonnet de domptage","à quoi sert le bâtonnet de domptage","comment utiliser le bâtonnet de domptage"}},{q="Pourquoi les chasseurs ont-ils besoin de compagnons animaux ?",a="Un compagnon animal protège, veille et aide au combat. Une bête loyale peut garder la ligne de front et tenir compagnie au voyageur lors de longs périples dangereux à travers les contrées sauvages.",al={"pourquoi avoir un familier","avantages d'un compagnon animal","pourquoi dompter des bêtes"}},{q="Quelle créature faut-il dompter durant cette épreuve ?",a="L'épreuve met à l'honneur un Rockhide Boar, une bête robuste qui permet de tester les rudiments du dressage animal. L'exercice enseigne le sang-froid et la discipline face à une faune agressive. Ensuite, les aventuriers rendent compte de leurs progrès à Josephine Carson.",al={"quel sanglier dompter","cible rockhide boar","créature de taming the beast"}},{q="Pourquoi Josephine Carson insiste-t-elle sur l'équilibre de la nature ?",a="Josephine Carson met en garde contre la cupidité et le recours à la force pour maîtriser les bêtes sauvages. Un usage inconsidéré perturbe l'équilibre de la nature, et les bêtes ne sont pas des outils jetables. La véritable maîtrise consiste à respecter leur place dans la nature.",al={"sens de l'équilibre de la nature","équilibre naturel et domptage","pourquoi respecter la nature"}}},fp="16,181,19.403.0,21.405.0,50.234.0,24.231.0,32.240.0,38.186.0,46.237.0,58.205.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="À Comté-de-l’Or, Training the Beast apprend aux jeunes chasseurs à prendre soin d’un compagnon apprivoisé. Isaac Chan leur enseigne à nourrir et à ressusciter leurs bêtes, puis à les entraîner pour qu’elles vivent à leurs côtés.",h="À Comté-de-l’Or, Training the Beast apprend aux jeunes chasseurs à prendre soin d’un compagnon apprivoisé.",kw={"forêt d’elwynn","nourrir son familier","comté-de-l’or","familier du chasseur","isaac chan","dressage de familier","ressusciter son familier","training the beast","homme des bois"},ang={["class:Hunter"]="En tant que chasseur, vous allez au-delà de la capture des bêtes pour nouer avec votre compagnon un lien durable et discipliné. Nourrissez-le, ressuscitez-le et entraînez-le.",["faction:Alliance"]="En tant que chasseur de l’Alliance dans la Forêt d’Elwynn, vous pouvez apprendre les bases du dressage des bêtes auprès d’hommes des bois chevronnés comme Isaac Chan, à Comté-de-l’Or."},sec={{t="Les responsabilités de la chasse",b="Vous cherchez Isaac Chan, un homme des bois expérimenté de Comté-de-l’Or, pour apprendre à dresser votre bête. Une créature apprivoisée a besoin de soins et de discipline avant de devenir une alliée fiable. Sans les conseils de Chan, votre compagnon risque de rester indiscipliné dans la nature sauvage."},{t="Les conseils d’un homme des bois",b="Isaac Chan vous apprend à prendre soin de votre compagnon animal. Vous apprenez à le nourrir et à le ressusciter s’il tombe au combat. Il vous enseigne aussi des ordres qui l’aident à combattre et vous rappelle que le pouvoir sur la faune exige du respect. Respectez l’équilibre de la nature et vivez dans l’émerveillement devant le monde qui vous entoure."}},faq={{q="Qui est Isaac Chan ?",a="Isaac Chan est un homme des bois de longue date qui vit à Comté-de-l’Or, dans la Forêt d’Elwynn. Il connaît la faune et la survie en milieu sauvage. Il apprend aux chasseurs novices à guider, nourrir et ressusciter leurs compagnons animaux, ainsi qu’à leur enseigner des techniques.",al={"qui est isaac chan","dresseur de bêtes de comté-de-l’or","histoire d’isaac chan"}},{q="Quel est le but de Training the Beast ?",a="Les chasseurs apprennent à prendre soin d’une bête apprivoisée et à préserver le lien qui les unit. Isaac Chan leur apprend à nourrir leur compagnon, à le ressusciter s’il tombe au combat et à lui enseigner de nouvelles techniques de combat.",al={"que fait cette quête","pourquoi dresser une bête","but de training the beast"}},{q="Où trouver Isaac Chan ?",a="Isaac Chan vit à Comté-de-l’Or, le bourg central de la Forêt d’Elwynn, au sud de la Vallée de Comté-du-Nord et au sud-ouest de Hurlevent.",al={"où est isaac chan","où rendre cette quête","emplacement d’isaac chan"}},{q="Quelles techniques Isaac Chan enseigne-t-il ?",a="Isaac Chan enseigne les bases des soins et du dressage d’un compagnon animal. Vous apprenez à nourrir votre bête, à la ressusciter si elle tombe au combat et à lui enseigner de nouvelles techniques à mesure qu’elle grandit à vos côtés.",al={"quelles techniques obtient-on","techniques apprises par le familier","qu’enseigne isaac chan"}},{q="Pourquoi Isaac Chan rappelle-t-il aux chasseurs de respecter la nature ?",a="Isaac Chan enseigne aux chasseurs l’humilité face à la nature sauvage. Il leur demande de respecter l’équilibre de la nature et de vivre dans l’émerveillement devant le monde qui les entoure, afin que leur lien avec une bête repose sur la protection plutôt que sur l’exploitation.",al={"pourquoi respecter la nature","chasseur et respect de l’équilibre"}},{q="Qui entreprend cette quête ?",a="Les chasseurs qui savent déjà apprivoiser des bêtes recherchent la discipline sylvestre d’Isaac Chan pour prendre soin d’un compagnon animal et l’entraîner.",al={"qui peut faire cette quête","training the beast est-elle réservée aux chasseurs"}}},fp="18,184,32.248.0,21.284.0,18.217.0,42.181.0,30.129.0,34.194.0,53.207.0,26.115.0"}
P.entries["quest:948"] = {n="Onu",s="Barithras Lunombrage vous envoie au sud d’Auberdine consulter Onu. Vos découvertes aux Chutes de la Bondissante ont attiré l’attention de l’un des plus anciens gardiens de Sombrivage.",h="Barithras Lunombrage vous envoie au sud d’Auberdine consulter Onu.",kw={"ancien du savoir","auberdine","barithras lunombrage","cliffwater falls","sombrivage","bosquet des anciens","onu"},ang={["class:Druid"]="En tant que druide, vous révérez les Anciens, gardiens de la sagesse de la nature. Enquêter sur les étranges excroissances des grottes à la demande d’Onu s’inscrit dans le travail du Cercle cénarien.",["faction:Alliance"]="En tant que voyageur de l’Alliance qui aide à défendre Sombrivage, vous pouvez chercher auprès des Anciens de la région des éclaircissements sur les étendues sauvages du nord de Kalimdor.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous connaissez les Anciens du savoir comme des alliés sacrés qui guident votre peuple depuis avant la Fracture. Répondre à l’appel d’Onu contribue à préserver Sombrivage."},sec={{t="Un appel des Anciens",b="Barithras Lunombrage voit plus que d’étranges champignons dans les échantillons que vous avez rapportés à Auberdine. Les grottes sous les Chutes de la Bondissante sont souillées, et la nouvelle est parvenue à Onu, un Ancien du savoir du Bosquet des Anciens, au sud de la ville. Les cours d’eau de Sombrivage sont peut-être corrompus au-delà de ce qu’un naturaliste peut expliquer. Onu demande conseil, et même la patience d’un Ancien ne peut masquer le poids de sa convocation."},{t="En route vers le Bosquet",b="La route au sud d’Auberdine quitte la côte et ses ruines pour s’enfoncer dans les terres, en direction des pentes montagneuses. Le Bosquet des Anciens abrite un ancien refuge de la nature, à l’écart du déclin qui touche le rivage. Onu vous attend parmi les tertres de pierre et les esprits frères. Il est prêt à guider ses alliés vers les fléaux qui s’éveillent aux confins des terres sauvages."}},faq={{q="Qui est Onu ?",a="Ancien du savoir, Onu recueille et préserve les connaissances. Il veille sur le Bosquet des Anciens, dans le sud de Sombrivage, et offre sa sagesse à ceux qui défendent la terre.",al={"qui est onu","identité d’onu","qu’est-ce qu’ onu"}},{q="Pourquoi Onu veut-il me parler ?",a="Vous avez recueilli des échantillons fongiques pour Barithras Lunombrage dans les grottes sous les Chutes de la Bondissante. Vos découvertes ont alarmé les naturalistes, et Onu veut vous parler de la corruption qui se répand.",al={"pourquoi onu convoque","raison de la rencontre","pourquoi aller voir onu"}},{q="Où se trouve le Bosquet des Anciens ?",a="Le Bosquet des Anciens se trouve au sud d’Auberdine, au pied des montagnes à l’est. Suivez la route principale vers le sud à travers Sombrivage, puis dirigez-vous vers l’est, en direction des pentes montagneuses, pour rejoindre Onu.",al={"emplacement d’ onu","où se trouve le bosquet des anciens","comment trouver onu"}},{q="Quelle sorte de créature est un Ancien du savoir ?",a="Les Anciens du savoir sont de vieux tréants alliés aux Elfes de la nuit et au Cercle cénarien. Leur sagesse et leur mémoire sont vénérées, et ils préservent la magie et l’histoire de la nature.",al={"ancien du savoir","quelle créature est onu","tréant ou ancien"}},{q="Pourquoi la convocation d’Onu est-elle urgente ?",a="Les Anciens agissent avec circonspection et se pressent rarement. Selon Barithras Lunombrage, si Onu demande conseil, c’est que la menace qui pèse sur Sombrivage est grave.",al={"pourquoi est-ce urgent","onu est-il inquiet","avertissement de barithras"}},{q="Que se passe-t-il après avoir rencontré Onu ?",a="Après vous avoir rencontré au Bosquet des Anciens, Onu vous demande d’enquêter sur une menace plus sombre, plus au sud le long de la côte : les fouilles autour de la Glaive du Maître.",al={"quête après onu","que se passe-t-il ensuite","où onu vous envoie"}}},fx={be40e913={q="Pourquoi Barithras Lunombrage m'envoie-t-il voir Onu ?",a="Barithras sait que les Anciens du Savoir possèdent une profonde sagesse concernant la corruption de ces terres, et Onu a remarqué ce que vous avez trouvé dans la grotte des Chutes de la Bondissante. Comme un Ancien ne se manifeste que rarement à moins que Sombrivage ne soit confronté à une menace grave et urgente, Barithras vous presse de répondre immédiatement à son appel.",al={"motivation de barithras","pourquoi envoyer voir onu","pourquoi barithras veut-il que cela soit fait"}}},fp="3,166,27.409.0,20.339.0,11.167.0,35.197.0,35.190.0,44.180.0,39.132.0,34.167.1"}
P.entries["quest:94819"] = {n="Contingency Plan",s="Quelqu’un vous envoie à Forgefer pour rencontrer High Priestess Mims. Votre prochaine épreuve approche, et elle vous attend dans le Mystic Ward.",h="Quelqu’un vous envoie à Forgefer pour rencontrer High Priestess Mims.",kw={"plan de secours","high priestess mims","forgefer","lumière","mystic ward","prochaine épreuve","rites"},sec={{t="Une audience en attente",b="À Forgefer, High Priestess Mims attend de vous parler dans le Mystic Ward. Votre prochaine épreuve approche, et la personne qui vous a envoyé ne peut quitter son poste pour assister aux rites de votre peuple. Que la Lumière vous accompagne dans votre voyage tandis que vous allez rencontrer Mims."}},faq={{q="Qui dois-je rencontrer ?",a="High Priestess Mims attend de vous parler dans le Mystic Ward de Forgefer.",al={"qui attend","rencontrer mims","mims"}},{q="Où puis-je trouver Mims ?",a="Mims devrait se trouver dans le Mystic Ward, à Forgefer.",al={"où est mims","emplacement de mims","mystic ward"}},{q="Pourquoi dois-je aller à Forgefer ?",a="High Priestess Mims aimerait vous parler là-bas, et votre prochaine épreuve approche.",al={"pourquoi forgefer","que trouve-t-on à forgefer","audience"}},{q="Que dit la personne qui m’a envoyé au sujet des rites de mon peuple ?",a="La personne qui vous a envoyé aurait aimé assister aux rites de votre peuple, mais dit qu’elle ne peut quitter son poste.",al={"rites de mon peuple","rites spéciaux","pourquoi ne peut-elle pas venir"}},{q="Quel souhait est formulé pour mon voyage ?",a="La personne qui vous a envoyé souhaite que la Lumière vous accompagne dans votre voyage.",al={"bénédiction de la lumière","que la lumière m’accompagne","bénédiction du voyage"}}},fp="16,129,18.253.0,23.76.0,22.47.0,28.82.0,49.97.0,30.61.0"}
P.entries["quest:94822"] = {n="Confounding Flash",s="Vos supérieurs vous envoient à Forgefer poursuivre votre formation auprès de High Priestess Mims. Votre dévouement à la Light a retenu leur attention.",h="Vos supérieurs vous envoient à Forgefer poursuivre votre formation auprès de High Priestess Mims.",kw={"confounding flash","hall of mysteries","high priestess mims","forgefer","light","supérieurs","formation"},sec={{t="Une nouvelle leçon",b="Vos supérieurs vous envoient auprès de High Priestess Mims au Hall of Mysteries de Forgefer. Ils estiment que vos services vous ont préparé à poursuivre votre formation. Mims doit vous guider, et la leçon vous attend à votre arrivée."},{t="Devant Mims",b="High Priestess Mims vous reçoit à Forgefer et remarque votre arrivée tardive. Elle excuse ce retard au vu de vos services rendus à la Light, puis vous demande d'écouter attentivement sa leçon."}},faq={{q="Qui m'a envoyé à Forgefer ?",a="Vos supérieurs vous ont demandé de vous rendre au Hall of Mysteries de Forgefer pour poursuivre votre formation.",al={"qui m'a envoyé","qui sont mes supérieurs"}},{q="Qui est High Priestess Mims ?",a="High Priestess Mims est la personne que vos supérieurs vous demandent de trouver à Forgefer. Elle peut vous guider dans la suite de votre formation.",al={"qui est mims","mims"}},{q="Pourquoi m'envoie-t-on poursuivre ma formation ?",a="Vos supérieurs estiment que vous avez fait vos preuves en servant la Light.",al={"pourquoi cette formation","pourquoi moi"}},{q="Où trouver High Priestess Mims ?",a="Trouvez High Priestess Mims au Hall of Mysteries de Forgefer.",al={"où est mims","hall of mysteries"}}},fp="17,139,16.203.0,11.169.0,25.94.0,27.115.0,33.82.0,36.63.0"}
P.entries["quest:94824"] = {n="Confounding Flash",s="Un message vous envoie à Forgefer pour parler à la grande prêtresse Mims. Elle vous attend au Hall of Mysteries, mais la raison de cette convocation reste inconnue.",h="Un message vous envoie à Forgefer pour parler à la grande prêtresse Mims.",kw={"confounding flash","hall of mysteries","grande prêtresse mims","forgefer","parler avec mims","convocation"},sec={{t="Un appel à Forgefer",b="La route vous mène à Forgefer, où la grande prêtresse Mims vous attend au Hall of Mysteries. On vous envoie lui parler en personne, sans préciser la raison de cette convocation. Le message suppose que vos exploits se sont bien déroulés, mais laisse à Mims le soin de vous en expliquer la raison."}},faq={{q="Qui souhaite me parler ?",a="La grande prêtresse Mims souhaite que vous veniez lui parler à Forgefer.",al={"qui m'a fait demander","convocation de mims","grande prêtresse mims"}},{q="Où dois-je me rendre ?",a="On vous demande de parler à la grande prêtresse Mims au Hall of Mysteries, à Forgefer.",al={"où se trouve mims","emplacement du hall of mysteries","aller à forgefer"}},{q="Pourquoi Mims veut-elle me voir ?",a="Le message n'explique pas pourquoi la grande prêtresse Mims souhaite vous parler.",al={"pourquoi mims m'a appelé","que veut-elle","raison de la convocation"}},{q="Que me demande-t-on de faire ?",a="On vous demande de parler à la grande prêtresse Mims à Forgefer.",al={"quelle est la tâche","parler à mims","demande de mims"}}},fp="17,148,19.277.0,27.66.0,14.86.0,29.77.0,28.67.0"}
P.entries["quest:94841"] = {n="Lost Shipping Crate",s="Une caisse d’expédition destinée à Friz Frazzlespark a disparu dans les Rives Claires. Son étiquette demande qu’elle soit rapportée au Port de Poudremèche.",h="Une caisse d’expédition destinée à Friz Frazzlespark a disparu dans les Rives Claires.",kw={"caisse","friz frazzlespark","étiquette","caisse d’expédition perdue","carte","port de poudremèche","rives claires"},sec={{t="Une caisse marquée",b="La caisse de Friz Frazzlespark porte une étiquette manuscrite qui indique le Port de Poudremèche, dans les Rives Claires. Une carte marque une rive au sud-est, au nord d’un temple entouré d’eau, avec des créatures ailées à proximité. L’étiquette déconseille d’ouvrir la caisse sans supervision et indique que Friz doit la recevoir."}},faq={{q="À qui appartient la caisse d’expédition ?",a="L’étiquette désigne Friz Frazzlespark comme propriétaire de la caisse.",al={"propriétaire de la caisse","à qui appartient-elle"}},{q="Où dois-je apporter la caisse ?",a="L’étiquette demande de rapporter la caisse à Friz Frazzlespark, au Port de Poudremèche, dans les Rives Claires.",al={"où livrer la caisse","livraison de la caisse"}},{q="Que dit l’étiquette de la caisse ?",a="Elle indique Friz Frazzlespark et le Port de Poudremèche, déconseille d’ouvrir la caisse sans supervision et précise un lieu de retour dans les Rives Claires.",al={"étiquette de la caisse","ce qui est écrit dessus"}},{q="Peut-on ouvrir la caisse sans danger ?",a="L’étiquette indique de ne pas l’ouvrir sans supervision.",al={"ouvrir la caisse","avertissement sur la caisse"}}},fp="19,137,14.300.0,28.55.0,30.94.0,32.153.0,26.50.0"}
P.entries["quest:94863"] = {n="Taming the Beast",s="Josephine Carson vous guide dans Taming the Beast, où vous apprenez à maîtriser un sanglier avant d'affronter un Gray Forest Wolf. Avec un Bâtonnet de domptage, vous cherchez à gagner la confiance de ce prédateur plus féroce.",h="Josephine Carson vous guide dans Taming the Beast, où vous apprenez à maîtriser un sanglier avant d'affronter...",kw={"domptage des bêtes","gray forest wolf","chasseur","entraînement des chasseurs","josephine carson","bâtonnet de domptage","taming the beast"},ang={["class:Hunter"]="En tant que Chasseur, vous apprenez la patience et le respect nécessaires pour nouer un lien avec de féroces prédateurs sauvages."},sec={{t="La voie du Chasseur",b="Josephine Carson vous observe tandis que vous progressez dans l'apprentissage du maniement des bêtes. Vous vous êtes exercé avec de simples sangliers ; à présent, vous pénétrez dans la forêt pour dompter un Gray Forest Wolf. Le bâtonnet enchanté qu'elle vous confie aide à apaiser le prédateur. La patience et le respect comptent autant que le pistage et le tir lorsque vous cherchez à gagner la confiance d'une créature sauvage."},{t="L'épreuve de l'instinct et de la confiance",b="Josephine Carson vous confie un Bâtonnet de domptage spécialement conçu pour apaiser les animaux dangereux. Approchez-vous du loup avec patience et précision, et surmontez son agressivité sans recourir à la force létale. Après vous être exercé à tisser un lien avec la bête, rapportez le bâtonnet à Josephine pour prouver vos progrès."}},faq={{q="Qu'est-ce que la quête Taming the Beast ?",a="Taming the Beast est une épreuve d'entraînement pour les Chasseurs, où vous utilisez un Bâtonnet de domptage enchanté pour dompter un Gray Forest Wolf.",al={"quête taming the beast","quête gray forest wolf","leçon pour dompter un loup"}},{q="Qui vous confie cette quête et la termine ?",a="Josephine Carson vous donne ses instructions et vous confie le Bâtonnet de domptage. Après l'épreuve, vous le lui rapportez.",al={"qui donne taming the beast","qui est josephine carson","où rendre taming the beast"}},{q="Quelle créature devez-vous dompter ?",a="Vous devez dompter un Gray Forest Wolf, prédateur forestier plus féroce que les sangliers que vous avez apprivoisés auparavant.",al={"que dois-je dompter","quelle bête","cible de taming the beast"}},{q="À quoi sert le Bâtonnet de domptage ?",a="Josephine Carson vous confie le Bâtonnet de domptage pour apaiser un Gray Forest Wolf sauvage et nouer un lien temporaire sans lui causer de dommages permanents.",al={"effet du bâtonnet de domptage","pourquoi utiliser le bâtonnet de domptage","histoire du bâtonnet de domptage"}},{q="Quelle bête le Chasseur a-t-il domptée avant cette épreuve ?",a="Avant d'affronter le Gray Forest Wolf, vous vous êtes exercé à maîtriser un sanglier de la forêt.",al={"leçon précédente de domptage","quelle bête dompter avant le loup"}},{q="Gardez-vous le Gray Forest Wolf comme compagnon permanent ?",a="Non. Après vous être exercé à tisser des liens avec les bêtes, vous rapportez le Bâtonnet de domptage à Josephine Carson.",al={"garde-t-on le loup","le loup est-il un familier permanent"}}},fp="16,174,22.331.0,28.279.0,35.112.0,35.99.0,34.107.0,32.133.0,43.73.0,58.94.0"}
P.entries["quest:94864"] = {n="Taming the Beast",s="Dans la Forêt d’Elwynn, les chasseurs affrontent Taming the Beast, l’épreuve finale supervisée par Josephine Carson. Après avoir dompté un sanglier et un loup, chaque chasseur se sert d’un Bâtonnet de domptage pour gagner la confiance d’un Young Forest Bear. Cette épreuve approfondit le lien du chasseur avec les bêtes et lui enseigne le respect de l’équilibre des bois.",h="Dans la Forêt d’Elwynn, les chasseurs affrontent Taming the Beast, l’épreuve finale supervisée par Josephine...",kw={"lien avec les bêtes","entraînement des bêtes","forêt d’elwynn","quête de chasseur","josephine carson","bâtonnet de domptage","taming the beast","young forest bear"},ang={["class:Hunter"]="En tant que chasseur, vous dépassez le simple pistage pour nouer un lien plus profond et plus compréhensif avec les bêtes sauvages.",["faction:Alliance"]="En tant que maître des bêtes de l’Alliance, vous pouvez confier des compagnons disciplinés aux éclaireurs des étendues sauvages, afin qu’ils défendent les fermes et patrouillent sur les routes commerciales des territoires de Hurlevent.",["race:Human"]="En tant que chasseur humain qui s’entraîne dans la Forêt d’Elwynn, vous apprenez à vivre aux côtés des prédateurs naturels du royaume au lieu de chercher à les détruire."},sec={{t="L’épreuve finale de la chasse",b="Dans la Forêt d’Elwynn, les chasseurs apprennent à vivre parmi les créatures sauvages qui les entourent. Après avoir dompté un loup et un sanglier, ils affrontent une dernière épreuve de courage et de patience. Josephine Carson envoie chaque chasseur auprès d’un Young Forest Bear, le plus puissant des prédateurs communs de la forêt. Le chasseur doit résister à la force de l’ours et gagner sa confiance, plutôt que de le soumettre par la force."},{t="Respect et équilibre à Elwynn",b="Dominer la faune d’Elwynn exige du respect, pas de la domination. Les ours des forêts incarnent la force et la vitalité des bois et contribuent à préserver leur ordre naturel. Avec un Bâtonnet de domptage, les chasseurs apprennent à apaiser l’agressivité d’un ours et à nouer un lien fondé sur la compréhension. Gagner la confiance d’un animal aussi puissant approfondit le lien du chasseur avec la nature sauvage et achève les premières leçons supervisées par Josephine Carson."}},faq={{q="Qui confie cette épreuve aux chasseurs ?",a="Josephine Carson confie cette épreuve aux chasseurs qui s’entraînent dans la Forêt d’Elwynn. Après qu’ils ont dompté des bêtes moins redoutables, elle les guide et leur remet le Bâtonnet de domptage pour l’ours des forêts. Une fois l’épreuve terminée, ils lui rendent le bâtonnet.",al={"qui confie taming the beast","donneur de quête taming the beast","quête josephine carson"}},{q="Quelles bêtes faut-il dompter avant cette épreuve ?",a="Les chasseurs domptent d’abord un sanglier et un loup avant d’affronter un Young Forest Bear. Ces épreuves montrent qu’ils savent maîtriser des bêtes endurantes et habituées à vivre en meute avant de tenter de gagner la confiance d’un ours.",al={"bêtes requises avant le domptage","quelles bêtes dompter avant l’ours","bêtes domptées avant cette épreuve"}},{q="Pourquoi envoyer les chasseurs auprès d’un Young Forest Bear ?",a="Un Young Forest Bear met à l’épreuve la force et la puissance d’un chasseur face à la faune de la Forêt d’Elwynn. Après s’être mesuré au loup agile et au sanglier robuste, le chasseur doit faire preuve d’endurance, de respect et de courage pour gagner la confiance de l’ours.",al={"pourquoi dompter un young forest bear","rôle du young forest bear","pourquoi des ours à elwynn"}},{q="À quoi sert le Bâtonnet de domptage ?",a="Josephine Carson remet un Bâtonnet de domptage aux chasseurs pour les aider à apaiser les animaux sauvages. Il permet de calmer un Young Forest Bear agressif sans le tuer et aide le chasseur à nouer un lien paisible avec lui. Les chasseurs rendent le bâtonnet à Carson une fois l’épreuve terminée.",al={"rôle du bâtonnet de domptage","effet du bâtonnet de domptage","pourquoi utiliser un bâtonnet de domptage"}},{q="Comment le domptage des bêtes aide-t-il la Forêt d’Elwynn ?",a="Les chasseurs apprennent à préserver l’équilibre naturel de la Forêt d’Elwynn en traitant la faune avec respect et retenue. Ils guident pacifiquement les bêtes dangereuses au lieu de les traquer, préservant l’harmonie entre la faune locale et les communautés humanoïdes.",al={"pourquoi l’équilibre d’elwynn compte","équilibre de la forêt d’elwynn","domptage et équilibre de la forêt"}},{q="Que signifie l’achèvement de cette leçon pour un chasseur ?",a="Achever l’épreuve finale approfondit le lien d’un chasseur avec les bêtes sauvages. Gagner la confiance de la créature la plus puissante d’Elwynn lui enseigne la compréhension nécessaire pour nouer des liens durables avec des compagnons animaux partout en Azeroth.",al={"que se passe-t-il après avoir dompté l’ours","achèvement de l’entraînement du chasseur","sens du lien avec les bêtes"}},{q="Où trouve-t-on les Young Forest Bears ?",a="Les Young Forest Bears parcourent les zones boisées de la Forêt d’Elwynn, entre les arbres touffus et aux côtés des loups et des araignées. Les chasseurs quittent les établissements voisins et suivent leurs traces dans les sous-bois, guidés par les dernières instructions de Carson et munis du Bâtonnet de domptage.",al={"emplacement des young forest bears","où trouver des ours à elwynn","ours des forêts d’elwynn"}}},fp="16,291,27.363.0,29.396.0,34.219.0,49.184.0,47.224.0,38.240.0,42.245.0,54.219.0,35.246.0"}
P.entries["quest:94873"] = {n="Buying Friendship: Gelkis",s="Un étranger offre au clan Gelkis un sac de totems au Village des Gelkis. Leur intendant voit dans ce cadeau une aide contre le clan Magram.",h="Un étranger offre au clan Gelkis un sac de totems au Village des Gelkis.",kw={"acheter l’amitié","centaure","gelkis","clan gelkis","village des gelkis","magram","molkar","sac de totems"},sec={{t="Un cadeau pour les Gelkis",b="Quelqu’un a préparé un sac de totems à remettre à l’intendant des Gelkis, au Village des Gelkis. Les Gelkis perdent du terrain face aux Magram, et leur isolement pourrait les rendre réceptifs à l’aide d’étrangers. Ce cadeau doit améliorer votre réputation auprès du clan."}},faq={{q="Pourquoi apporter un sac de totems aux Gelkis ?",a="Ce cadeau doit améliorer votre réputation auprès du clan Gelkis, qui perd du terrain face aux Magram.",al={"sac de totems","pourquoi des totems","cadeau gelkis"}},{q="Qui reçoit le sac ?",a="L’intendant des Gelkis, au Village des Gelkis, reçoit le sac.",al={"intendant gelkis","qui reçoit le sac","destinataire des totems"}},{q="À quel problème les Gelkis font-ils face ?",a="Les Gelkis sont en mauvaise posture face aux Magram, dont le clan s’est montré particulièrement féroce.",al={"problème des gelkis","magram gelkis","pourquoi perdre"}},{q="Qui est Molkar ?",a="Molkar est l’intendant des Gelkis qui reçoit le sac.",al={"molkar gelkis","intendant molkar","qui est molkar"}}},fp="25,137,21.259.0,38.102.0,22.61.0,32.92.0,14.57.0"}
P.entries["quest:94890"] = {n="Bring Me His Head",s="Le sergent Riftan vous renvoie au Suaire du Crépuscule, où Overlord Kilgar reste caché dans son donjon. Les soldats secourus sont prêts à combattre, et Riftan veut la défaite de Kilgar.",h="Le sergent Riftan vous renvoie au Suaire du Crépuscule, où Overlord Kilgar reste caché dans son donjon.",kw={"rapportez-moi sa tête","orc","overlord kilgar","soldats secourus","sergent riftan","suaire du crépuscule"},sec={{t="De retour au donjon",b="Les soldats secourus sont impatients de combattre, et le sergent Riftan affirme que votre force a permis de mener l’assaut jusqu’ici. Overlord Kilgar, un orc, est caché au plus profond de son donjon, dans le Suaire du Crépuscule. Riftan vous demande de le vaincre et de rapporter sa tête."}},faq={{q="Qui est Overlord Kilgar ?",a="Overlord Kilgar est un chef orc qui se cache au plus profond de son donjon, dans le Suaire du Crépuscule.",al={"kilgar","qui est kilgar","chef orc"}},{q="Pourquoi suis-je renvoyé au Suaire du Crépuscule ?",a="Les soldats secourus sont prêts à combattre, et le sergent Riftan affirme que l’assaut doit se poursuivre. Il vous demande de retourner au Suaire du Crépuscule et de rapporter la tête d’Overlord Kilgar.",al={"pourquoi y retourner","mission au suaire du crépuscule","quelle est la suite"}},{q="Qui veut la tête de Kilgar ?",a="Le sergent Riftan vous demande de lui rapporter la tête d’Overlord Kilgar.",al={"que veut riftan","qui a demandé kilgar","rapportez-moi sa tête"}},{q="Où Kilgar se cache-t-il ?",a="Overlord Kilgar est caché au plus profond de son donjon, dans le Suaire du Crépuscule.",al={"emplacement de kilgar","où est overlord","donjon de kilgar"}}},fp="17,185,16.255.0,23.86.0,50.180.0,24.61.0,23.72.0"}
P.entries["quest:94891"] = {n="News to Farholde",s="Ashe Amberhall attend votre rapport au Donjon de Fort-Lointain, après votre travail avec le sergent Riftan. Votre retour montrera si l'expédition a réussi.",h="Ashe Amberhall attend votre rapport au Donjon de Fort-Lointain, après votre travail avec le sergent Riftan.",kw={"ashe amberhall","donjon de fort-lointain","kilgar","nouvelles pour fort-lointain","rapport","sergent riftan"},sec={{t="Un rapport pour Ashe",b="Le sergent Riftan vous renvoie auprès d'Ashe Amberhall, au Donjon de Fort-Lointain, avec un rapport. Il vous confie la tête de Kilgar à emporter. Ashe dit qu'elle avait commencé à douter de son jugement pendant votre absence, mais loue maintenant vos talents."}},faq={{q="Qui attend le rapport ?",a="Ashe Amberhall attend votre rapport au Donjon de Fort-Lointain.",al={"à qui faire mon rapport","rapport pour ashe","rapport à fort-lointain"}},{q="Que me donne Riftan ?",a="Le sergent Riftan vous donne la tête de Kilgar pour l'apporter à Ashe Amberhall.",al={"qu'est-ce que riftan m'a lancé","tête de kilgar","qu'est-ce que je transporte"}},{q="Que dit Ashe à mon retour ?",a="Ashe dit qu'elle commençait à craindre d'avoir mal jugé vos talents, puis affirme que vous étiez la personne qu'il fallait pour cette mission.",al={"réaction d'amberhall","dialogue d'ashe","ashe était-elle inquiète"}},{q="Que dit Ashe au sujet de Riftan ?",a="Ashe demande si Riftan est toujours dans les parages et dit qu'elle pensait que vous vous entendriez bien tous les deux.",al={"riftan est-il encore en vie","qu'en est-il du sergent riftan","ashe et riftan"}}},fp="16,141,17.222.0,21.59.0,25.66.0,33.98.0,32.84.0"}
P.entries["quest:94892"] = {n="Dying Wish",s="Le maréchal Ryan se meurt et vous demande de porter son blason au commandant chevalier Demar Brant. Ses derniers mots vont à son foyer et à Abigail.",h="Le maréchal Ryan se meurt et vous demande de porter son blason au commandant chevalier Demar Brant.",kw={"abigail","blason","dernière volonté","donjon de fort-lointain","commandant chevalier demar brant","maréchal ryan","ryan"},sec={{t="Les derniers mots de Ryan",b="Alors que le regard de Ryan s’éteint, il parle de son foyer et d’Abigail. Le maréchal vous confie son blason et vous demande de prévenir le commandant chevalier Demar Brant. Vous portez l’insigne de son rang au Donjon de Fort-Lointain, où le commandant vous attend."}},faq={{q="Qui se meurt ?",a="Le maréchal Ryan se meurt lorsqu’il vous demande de porter son blason au commandant chevalier Demar Brant.",al={"dernière volonté qui","maréchal ryan"}},{q="Que veut Ryan que je fasse ?",a="Ryan vous demande de porter son blason au commandant chevalier Demar Brant et de le prévenir.",al={"demande de ryan","que faire du blason"}},{q="Qui est Abigail ?",a="Dans ses derniers mots, Ryan mentionne Abigail et dit qu’il aurait dû rentrer chez lui.",al={"abigail et ryan","qui est abigail"}},{q="Où dois-je porter le blason ?",a="Portez le blason du maréchal Ryan au commandant chevalier Demar Brant, au Donjon de Fort-Lointain.",al={"où porter le blason","lieu où se trouve demar brant"}}},fp="10,132,19.218.0,13.89.0,29.78.0,15.68.0,26.75.0"}
P.entries["quest:94893"] = {n="Delivering Closure",s="Demar vous demande de remettre le blason du maréchal Ryan à Abigail Lawson, à Hurlevent. La mort de Ryan transmet un message à celle qu’il comptait épouser.",h="Demar vous demande de remettre le blason du maréchal Ryan à Abigail Lawson, à Hurlevent.",kw={"abigail lawson","place de la cathédrale","tourner la page","demar","donjon de fort-lointain","maréchal ryan","blason de ryan","hurlevent"},sec={{t="Un message à Hurlevent",b="Abigail Lawson vous attend sur la Place de la Cathédrale, où vous lui remettez le blason du maréchal Ryan pour Demar. Elle n’a pas rejoint Demar et Ryan lorsqu’ils ont fondé le Donjon de Fort-Lointain. Ryan et Abigail étaient en désaccord, mais Demar en ignore la raison. Il pense que sa présence serait malvenue, alors le blason doit parler à sa place."},{t="Des mots tus",b="La famille de Ryan a péri pendant l’invasion des orcs, et son devoir envers la Horde s’est mué en haine. Demar lui a un jour proposé de vivre avec ses parents à Hurlevent, mais Ryan a refusé. Il a juré de rester jusqu’à ce qu’il ait chassé les orcs de chez lui. Ryan et Abigail ne s’étaient plus parlé depuis."},{t="Le blason remis",b="Quand vous lui remettez le blason, Abigail parle du refus de Ryan de quitter son foyer et de leur long silence. Elle qualifie Demar de héros, mais avertit que les héros mettent souvent en danger ceux qui les entourent. Puis elle serre le blason de Ryan contre elle et le traite d’idiot."}},faq={{q="Qui est Abigail Lawson ?",a="Abigail Lawson était la fiancée du maréchal Ryan. Elle vit à Hurlevent et n’avait pas rejoint Ryan et Demar au Donjon de Fort-Lointain.",al={"abigail qui","qui est abigail","fiancée de ryan"}},{q="Qui me demande d’apporter le blason de Ryan ?",a="Demar vous demande d’apporter le blason du maréchal Ryan à Abigail Lawson, à Hurlevent. Il pense qu’elle ne serait pas heureuse de le voir.",al={"qui m’a envoyé","blason de demar","qui veut la remise du blason"}},{q="Pourquoi Ryan est-il resté ?",a="Après la mort de sa famille pendant l’invasion des orcs, le devoir de Ryan envers la Horde s’est mué en haine. Il a juré de rester jusqu’à ce qu’il ait chassé les orcs de chez lui.",al={"pourquoi ryan est resté","ryan et les orcs","sa famille"}},{q="Pourquoi Abigail et Ryan ont-ils cessé de se parler ?",a="Abigail et Ryan étaient en désaccord, mais Demar en ignore les détails. Ils ne s’étaient plus parlé depuis.",al={"pourquoi ils ont cessé de se parler","abigail et ryan","leur désaccord"}},{q="À quoi sert le blason de Ryan ?",a="Demar vous demande d’apporter le blason du maréchal Ryan à Abigail Lawson, sur la Place de la Cathédrale, à Hurlevent.",al={"blason du maréchal","blason de ryan","que dois-je apporter"}}},fp="18,150,22.324.0,17.284.0,18.252.1,22.126.0,36.131.0,25.162.0,39.102.0,27.101.0"}
P.entries["quest:94894"] = {n="The Twilight Threat",s="Farholde demande l’aide de Hurlevent face à la soudaine recrudescence des activités du Marteau du crépuscule. Vous apportez des preuves à Bolvar Fordragon, alors que l’Alliance doit déjà faire face à d’autres guerres.",h="Farholde demande l’aide de Hurlevent face à la soudaine recrudescence des activités du Marteau du crépuscule.",kw={"bolvar fordragon","brant","farholde","horde","kilgar","rives claires","donjon de hurlevent","marteau du crépuscule"},ang={["faction:Alliance"]="En tant qu’aventurier de l’Alliance, vous apportez à Bolvar Fordragon les preuves de Farholde, dont les habitants cherchent de l’aide contre le Marteau du crépuscule et la Horde."},sec={{t="L’appel de Farholde",b="Les habitants de Farholde se tournent vers vous après que dame Amberhall a appris vos démêlés avec le Marteau du crépuscule. Leur campagne visait à chasser la Horde de leur terre natale, mais l’activité des cultistes a fortement augmenté. Ils craignent que Hurlevent ne réponde pas à leurs appels avant que Farholde ne se retrouve face à des ennemis sur deux fronts. Vous apportez des preuves à Bolvar Fordragon, au Donjon de Hurlevent."},{t="La réponse de Hurlevent",b="Au Donjon de Hurlevent, Bolvar Fordragon entend l’avertissement de Farholde. Il affirme que l’Alliance est déjà engagée dans une guerre bien plus vaste et ne peut consacrer ses forces à une querelle locale. La Horde a rasé davantage de foyers que ceux des Rives Claires. Bolvar voit peu d’espoir que Brant ravale sa fierté et mène sa cavalerie au secours de l’Alliance."}},faq={{q="Qui demande l’aide de Hurlevent ?",a="Farholde demande l’aide de Hurlevent face à la recrudescence des activités du Marteau du crépuscule.",al={"qui demande de l’aide","appel de farholde","qui m’a envoyé"}},{q="Pourquoi Farholde est-elle inquiète ?",a="Farholde craint d’être submergée par des ennemis sur deux fronts si Hurlevent ne répond pas à ses appels.",al={"que se passe-t-il à farholde","problème des cultistes","pourquoi s’inquiéter"}},{q="Quelles preuves est-ce que j’apporte ?",a="Vous apportez la tête de Kilgar à Bolvar Fordragon, au Donjon de Hurlevent.",al={"quelles preuves","tête de kilgar","livraison de la tête"}},{q="De qui Bolvar reçoit-il des nouvelles ?",a="Bolvar Fordragon reçoit des nouvelles de Farholde, dont la campagne visait à chasser la Horde de sa terre natale.",al={"qui a envoyé les nouvelles","rapport de farholde","question sur bolvar"}},{q="Pourquoi Hurlevent ne peut-elle pas aider Farholde ?",a="Bolvar explique que l’Alliance mène une guerre de bien plus grande ampleur et n’a pas les ressources nécessaires pour soutenir la querelle personnelle de Farholde.",al={"pourquoi pas d’aide","soutien de hurlevent","bolvar refuse"}}},fp="19,175,15.357.0,18.365.1,30.69.0,24.100.0,25.62.0,27.105.0,37.120.0"}
P.entries["quest:94895"] = {n="Lost Shipping Crate",s="La caisse d'expédition de Friz Frazzlespark a disparu du Port de Poudremèche, dans les Rives Claires. Son étiquette déconseille de l'ouvrir sans surveillance et vous demande de la rapporter à Friz.",h="La caisse d'expédition de Friz Frazzlespark a disparu du Port de Poudremèche, dans les Rives Claires.",kw={"étiquette de la caisse","carte de la caisse","friz frazzlespark","caisse d'expédition perdue","port de poudremèche","rives claires","avertissement"},sec={{t="Une caisse marquée",b="Une carte et un avertissement indiquent la caisse que vous transportez dans les Rives Claires. Son étiquette mentionne Friz Frazzlespark et le Port de Poudremèche, et demande qu'on l'y rapporte si elle est perdue. Vous la ramenez à son propriétaire."}},faq={{q="À qui appartient la caisse d'expédition ?",a="L'étiquette désigne Friz Frazzlespark comme propriétaire de la caisse d'expédition.",al={"propriétaire de la caisse","à qui appartient-elle","caisse de friz"}},{q="Où dois-je apporter la caisse ?",a="La caisse doit être rapportée à Friz Frazzlespark, au Port de Poudremèche, dans les Rives Claires.",al={"où rapporter la caisse","destination de la caisse","port de poudremèche"}},{q="De quoi l'étiquette met-elle en garde ?",a="L'étiquette met en garde contre toute manipulation et indique de ne pas ouvrir la caisse sans surveillance.",al={"avertissement sur la caisse","puis-je l'ouvrir","ouvrir la caisse"}},{q="Que montre la carte de la caisse ?",a="La carte montre un cercle rouge sur une côte sud-est, au nord d'un temple mal dessiné, entouré d'eau et de créatures ailées.",al={"carte de la caisse","que montre la carte","cercle rouge sur la carte"}}},fp="19,188,14.214.0,28.69.0,30.87.0,31.85.0,34.131.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="Après la chute de Ban'aethal, ses survivants ont peu de choses qu'ils puissent encore appeler leurs. La colonie, au cœur de la Forêt de Trombenoire, a commencé à tomber dans le ciel en pleine nuit, et le danger empêche les réfugiés de récupérer ce qu'ils ont laissé derrière eux.",h="Après la chute de Ban'aethal, ses survivants ont peu de choses qu'ils puissent encore appeler leurs.",kw={"aid for the refugees","ban'aethal","banaethal","biens","ealaane","réfugiés","forêt de trombenoire"},sec={{t="Un appel désespéré",b="Ealaane et les autres réfugiés ont fui leurs foyers, au cœur de la Forêt de Trombenoire. Avec presque rien autour d'eux, ils demandent aux voyageurs d'affronter les dangers qu'ils ont laissés derrière eux."},{t="La catastrophe de Ban'aethal",b="Ban'aethal a commencé à tomber dans le ciel en pleine nuit. Ses habitants n'ont eu que quelques instants pour fuir, abandonnant leurs effets personnels. Les bois alentour sont devenus hostiles et dangereux."}},faq={{q="Qui est Ealaane ?",a="Ealaane a fui Ban'aethal avec d'autres habitants lorsque leur colonie a commencé à s'effondrer. Elle demande aux voyageurs qui se rendent dans la Forêt de Trombenoire de récupérer les biens laissés dans les ruines.",al={"qui a lancé un appel à l'aide pour les réfugiés","donneur de quête aid for the refugees","ealaane"}},{q="Qu'est-il arrivé à Ban'aethal ?",a="Ban'aethal était une colonie située au cœur de la Forêt de Trombenoire. Ses habitants ont fui en pleine nuit lorsqu'une catastrophe soudaine s'est abattue sur eux.",al={"qu'est-ce que banaethal","où se trouve banaethal","village ban aethal"}},{q="Pourquoi les villageois ont-ils dû évacuer Ban'aethal ?",a="Ban'aethal a commencé à tomber dans le ciel en pleine nuit, forçant ses habitants à fuir. Le village et la forêt alentour sont devenus trop dangereux pour qu'ils y restent ou y retournent.",al={"pourquoi évacuer banaethal","chute dans le ciel","catastrophe de ban aethal"}},{q="Pourquoi les villageois demandent-ils que leurs biens soient récupérés ?",a="La catastrophe a frappé soudainement, en pleine nuit, laissant peu de temps aux villageois pour fuir avec leurs biens. La forêt et les ruines sont désormais trop dangereuses, alors ils comptent sur les voyageurs pour récupérer ce qui a été laissé derrière eux.",al={"pourquoi récupérer les biens","biens abandonnés"}},{q="Qu'est-ce que la Forêt de Trombenoire ?",a="La Forêt de Trombenoire est la région boisée où se trouvait Ban'aethal. Depuis que la catastrophe a dévasté le village, la forêt est devenue extrêmement dangereuse pour les gens ordinaires.",al={"où se trouve la forêt de trombenoire","histoire de la forêt de trombenoire"}},{q="Les réfugiés peuvent-ils retourner chez eux ?",a="Non. Ealaane affirme que la Forêt de Trombenoire et les ruines de Ban'aethal sont trop dangereuses pour que les réfugiés y retournent seuls.",al={"les réfugiés peuvent-ils rentrer","banaethal est-il sûr"}}},fp="20,237,16.174.0,26.196.0,15.173.0,28.138.0,50.180.0,66.227.0,26.166.0,39.121.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="Resaan a quitté les Ruines de Ban’aethal depuis plus d’une semaine, et son partenaire attend de ses nouvelles. Les voyageurs qui s’y rendent sont invités à le ramener ou à rapporter son précieux héritage familial.",h="Resaan a quitté les Ruines de Ban’aethal depuis plus d’une semaine, et son partenaire attend de ses nouvelles.",kw={"ban'aethal","héritage familial","resaan","ruines de ban’aethal","provisions","the fate of a loved one"},sec={{t="Un appel désespéré",b="Le partenaire de Resaan le supplie de rester alors qu’il se prépare à retourner dans les Ruines de Ban’aethal. Pourtant, il se sent obligé d’affronter les ruines pour trouver des provisions. Son partenaire attend désormais de ses nouvelles."},{t="Disparu dans les ruines",b="Plus d’une semaine s’est écoulée depuis le départ de Resaan, bien plus longtemps qu’un retour rapide ne devrait prendre. Son partenaire demande aux voyageurs qui se rendent à Ban’aethal de fouiller les ruines. Si Resaan est vivant, ramenez-le chez lui. Si le sort s’est acharné sur lui, retrouvez son héritage familial."}},faq={{q="Qui est Resaan ?",a="Resaan est retourné dans les Ruines de Ban’aethal pour trouver des provisions malgré les supplications de son partenaire, qui lui demandait de rester. Plus d’une semaine s’est écoulée sans nouvelles, et son partenaire craint le pire.",al={"qui est resaan","où est resaan","trouver resaan"}},{q="Que sont les Ruines de Ban'aethal ?",a="Les Ruines de Ban'aethal sont l’endroit où Resaan est parti chercher des provisions. Son partenaire craint qu’il n’ait pas survécu une semaine là-bas, seul.",al={"qu’est-ce que banaethal","histoire des ruines de banaethal","où se trouve banaethal"}},{q="Pourquoi Resaan est-il retourné à Ban'aethal ?",a="Resaan est retourné à Ban'aethal pour récupérer des provisions malgré les supplications de son partenaire, qui lui demandait de rester.",al={"pourquoi resaan est-il reparti","pourquoi resaan est-il à banaethal"}},{q="Que vous demande de rapporter la personne qui confie la quête ?",a="Le partenaire de Resaan demande aux voyageurs de le ramener sain et sauf s’il est vivant. S’il a péri dans les ruines, il leur demande de rapporter son héritage personnel en souvenir.",al={"que veut la personne qui confie la quête","que se passe-t-il si resaan est mort"}},{q="Depuis combien de temps Resaan a-t-il disparu ?",a="Resaan a disparu depuis plus d’une semaine, après être parti pour les Ruines de Ban’aethal. Les dangers qui s’y trouvent font craindre le pire à son partenaire.",al={"depuis combien de temps resaan a-t-il disparu","depuis combien de temps resaan est-il parti"}},{q="Qui propose cette quête ?",a="Le partenaire éploré de Resaan demande de l’aide aux voyageurs de passage qui se dirigent vers Ban'aethal, désespéré de découvrir ce qui lui est arrivé.",al={"qui donne la quête le sort d’un être cher","personne qui confie la quête le sort d’un être cher"}}},fp="23,187,16.187.0,21.250.0,14.178.0,33.131.0,36.92.0,47.155.0,33.146.0,22.123.0"}
P.entries["quest:949"] = {n="Le camp du Marteau du crépuscule",s="Au Glaive du Maître, dans le sud de Sombrivage, des sectateurs se rassemblent tandis que des éclaireurs de l'Alliance cherchent à découvrir leurs intentions. Un bol divinatoire a révélé leur site rituel. Vous pénétrez maintenant dans les fouilles pour découvrir ce que le Marteau du crépuscule cherche sous terre.",h="Au Glaive du Maître, dans le sud de Sombrivage, des sectateurs se rassemblent tandis que des éclaireurs de...",kw={"sombrivage","le glaive du maître","onu","bol divinatoire","camp du crépuscule","twilight tome","marteau du crépuscule"},ang={["class:Druid"]="En tant que Druide, vous aidez les gardiens cénariens à découvrir les recherches de la secte et à empêcher qu'elles ne corrompent les entités anciennes enfouies sous terre.",["faction:Alliance"]="En tant que membre de l'Alliance, vous contribuez à empêcher les fouilles étranges de la secte de déstabiliser le nord de Kalimdor.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous voyez le Marteau du crépuscule profaner le Kalimdor sacré sous les bosquets anciens de Sombrivage."},sec={{t="Dans les fouilles",b="Le Marteau du crépuscule a fait du Glaive du Maître une menace. Un bol divinatoire a révélé les fortifications des sectateurs. Vous entrez dans leur camp pour découvrir leurs desseins avant que l'Alliance puisse préparer ses défenses."},{t="Le tome illustré",b="Dans le camp nord des sectateurs, un tome ancien regorge d'illustrations inquiétantes. Imprimées à la main, ses pages révèlent que le Marteau du crépuscule étudie l'entité colossale enfouie sous terre."}},faq={{q="Quel est l'objectif de la quête Le camp du Marteau du crépuscule ?",a="Vous pénétrez dans le camp du Marteau du crépuscule, près du Glaive du Maître, dans le sud de Sombrivage, pour trouver un indice sur les motifs de la secte : un livre rituel imprimé à la main.",al={"objectif de la quête du camp du crépuscule","que faire dans le camp du crépuscule"}},{q="Qui vous envoie enquêter dans le camp ?",a="Le bol divinatoire du Surplomb, au-dessus du Glaive du Maître, vous envoie enquêter. Vous poursuivez l'enquête commencée pour Onu, l'ancien protecteur.",al={"qui donne le camp du crépuscule","donneur de quête du camp du crépuscule"}},{q="Où trouve-t-on l'indice dans le camp ?",a="Le Twilight Tome se trouve dans la partie nord du campement. D'autres tomes peuvent libérer une magie protectrice contre les intrus.",al={"où se trouve le livre","emplacement du twilight tome","trouver l'indice dans le camp du crépuscule"}},{q="Pourquoi le Marteau du crépuscule se trouve-t-il au Glaive du Maître ?",a="Les sectateurs convoitent les pouvoirs obscurs des Dieux très anciens et de leurs serviteurs. Autour de l'immense carcasse pétrifiée, transpercée par la lame de pierre géante, ils creusent pour étudier ou réveiller le mal ancien qui s'y trouve encore.",al={"pourquoi les sectateurs sont au glaive du maître","but du marteau du crépuscule à sombrivage"}},{q="Que se passe-t-il après avoir trouvé le tome ?",a="La découverte du tome mène à Return to Onu. Vous portez les écrits vers le nord, à l'ancien tréant du Bosquet des Anciens.",al={"quête suivante après le camp du crépuscule","où aller après le twilight tome"}}},fx={["8554815a"]={q="Pourquoi le Scrying Bowl vous demande-t-il d'enquêter sur le camp ?",a="Le bol de divination d'Onu révèle que des sectateurs du Marteau du crépuscule se sont rassemblés autour du Glaive du Maître, où un antique « vieux seigneur » est tombé jadis. Leur objectif reste inconnu, mais Onu est certain qu'il est sinistre. Avant de pouvoir élaborer un plan avec les défenseurs du bosquet, il leur faut quelque chose provenant du camp qui révèle les intentions du culte.",al={"pourquoi enquêter sur the twilight camp","utilité scrying bowl","pourquoi fouiller the twilight camp"}}},fp="17,240,15.204.0,20.195.1,44.149.0,38.146.0,36.119.0,52.204.0,36.121.0"}
P.entries["quest:94911"] = {n="Child of Nature",s="Un membre des Ailes célestes voit du potentiel dans vos talents de druide et vous oriente vers Turak Totem-runique, aux Pitons-du-Tonnerre. Il peut vous apprendre à rejoindre le bastion du Cercle cénarien à Reflet-de-Lune.",h="Un membre des Ailes célestes voit du potentiel dans vos talents de druide et vous oriente vers Turak...",kw={"cercle cénarien","child of nature","druide","reflet-de-lune","ailes célestes","pitons-du-tonnerre","turak totem-runique"},ang={["class:Druid"]="En tant que druide, vous êtes envoyé auprès de Turak Totem-runique, aux Pitons-du-Tonnerre. Il peut vous apprendre à rejoindre le Cercle cénarien, à Reflet-de-Lune.",["race:Skyborne"]="En tant que membre des Ailes célestes, on vous annonce que les druides du Cercle cénarien vous accueilleront et partageront leur savoir."},sec={{t="Bienvenue chez les druides",b="Votre maître pense que les druides du Cercle cénarien vous accueilleront et partageront leur savoir. Turak Totem-runique, aux Pitons-du-Tonnerre, peut vous montrer comment rejoindre leur bastion à Reflet-de-Lune."}},faq={{q="À qui dois-je parler ?",a="Parlez à Turak Totem-runique, aux Pitons-du-Tonnerre. Il peut vous apprendre à rejoindre Reflet-de-Lune.",al={"à qui parler","turak totem-runique","qui est turak"}},{q="Où se trouve le bastion du Cercle cénarien ?",a="Le bastion du Cercle cénarien se trouve à Reflet-de-Lune, en Kalimdor.",al={"où se trouve le cercle","emplacement du cercle cénarien","reflet-de-lune"}},{q="Pourquoi m’envoie-t-on à Reflet-de-Lune ?",a="Les druides du Cercle cénarien peuvent partager leur savoir avec vous.",al={"pourquoi reflet-de-lune","apprendre la druidisme","formation de druide"}}},fp="15,186,19.189.0,24.85.0,44.63.0,33.69.0"}
P.entries["quest:94912"] = {n="Child of Nature",s="À Hurlevent, Sheldras Moontree peut vous indiquer le chemin vers Reflet-de-Lune. Là-bas, les druides du Cercle cénarien ont leur sagesse à partager avec un enfant de la nature.",h="À Hurlevent, Sheldras Moontree peut vous indiquer le chemin vers Reflet-de-Lune.",kw={"cercle cénarien","child of nature","druide","kalimdor","reflet-de-lune","sheldras moontree","skyborne","hurlevent"},ang={["class:Druid"]="En tant que druide, vous êtes dirigé vers le Cercle cénarien, un ordre ancien dont les membres pratiquent les arts druidiques.",["race:Skyborne"]="En tant que Skyborne, vous êtes parmi les premiers de votre peuple à arriver en Azeroth, et vous êtes accueilli."},sec={{t="Un bastion lointain",b="Sheldras Moontree, un Elfe de la nuit à Hurlevent, peut vous montrer comment rejoindre Reflet-de-Lune, sur Kalimdor. Le Cercle cénarien y a établi son bastion. C’est un ordre ancien de naturalistes et de druides, qui a beaucoup à vous enseigner."}},faq={{q="Qui est Sheldras Moontree ?",a="Sheldras Moontree est un Elfe de la nuit à Hurlevent qui peut vous montrer comment rejoindre Reflet-de-Lune.",al={"sheldras","elfe de la nuit à hurlevent","qui m’enseigne à rejoindre reflet-de-lune"}},{q="Qu’est-ce que le Cercle cénarien ?",a="Le Cercle cénarien est un ordre ancien de naturalistes et de praticiens des arts druidiques.",al={"cercle cénarien","ordre druidique","cercle de la nature"}},{q="Où se trouve le bastion du Cercle cénarien ?",a="Le Cercle cénarien a établi son bastion à Reflet-de-Lune, sur Kalimdor.",al={"bastion cénarien","où se trouve reflet-de-lune","reflet-de-lune"}},{q="Que puis-je apprendre auprès du Cercle cénarien ?",a="Les druides du Cercle cénarien ont beaucoup de sagesse à partager avec vous.",al={"enseignements cénariens","que peuvent-ils enseigner","sagesse druidique"}}},fp="15,149,16.215.0,25.86.0,28.93.0,42.66.0,42.66.0"}
P.entries["quest:94914"] = {n="Reflet-de-Lune",s="Votre enseignant ouvre un passage vers Reflet-de-Lune, où Dendrite Brasétoile vous attend. Vous pourrez lui parler de la voie que vous avez commencée à suivre.",h="Votre enseignant ouvre un passage vers Reflet-de-Lune, où Dendrite Brasétoile vous attend.",kw={"forme d’ours","dendrite brasétoile","druide","gardien remulos","reflet-de-lune","havrenuit","téléportation"},ang={["class:Druid"]="En tant que druide, votre enseignant vous accueille à Reflet-de-Lune et vous apprend un sort pour vous y rendre."},sec={{t="Une première leçon",b="Votre enseignant accueille les druides à Reflet-de-Lune. Le gardien Remulos veille sur ceux qui s’y reposent. Vous recevez le sort Téléportation : Reflet-de-Lune, qui vous y transporte quand vous recherchez le savoir ou le réconfort. Votre première leçon consiste à parler à Dendrite Brasétoile, à Havrenuit, de la voie que vous suivez désormais."},{t="La forme d’ours",b="Dendrite Brasétoile constate que vous maîtrisez déjà la forme d’ours. Il estime que vous êtes sur la bonne voie."}},faq={{q="À qui parler à Reflet-de-Lune ?",a="Parlez à Dendrite Brasétoile, à Havrenuit, de la voie que vous suivez.",al={"à qui parler","dendrite brasétoile","druide de havrenuit"}},{q="Comment rejoindre Reflet-de-Lune ?",a="Votre enseignant vous donne le sort Téléportation : Reflet-de-Lune, qui vous y transporte.",al={"téléportation vers reflet-de-lune","comment rejoindre reflet-de-lune","sort de téléportation"}},{q="Qui veille sur les druides à Reflet-de-Lune ?",a="Le gardien Remulos veille sur les druides qui se reposent à Reflet-de-Lune.",al={"gardien remulos","gardien de reflet-de-lune","qui veille sur reflet-de-lune"}},{q="Que dit Dendrite de mes progrès ?",a="Dendrite constate que vous maîtrisez déjà la forme d’ours.",al={"forme d’ours","ai-je maîtrisé la forme d’ours","réponse de dendrite"}}},fp="9,132,14.290.0,13.112.1,35.70.0,26.75.0,37.57.0,41.72.0"}
P.entries["quest:94923"] = {n="Hats Off",s="Robbie vous demande de retrouver le chapeau d’anniversaire qu’il a perdu près de la rivière, non loin des murlocs. Il craint que sa famille apprenne qu’il s’y est rendu.",h="Robbie vous demande de retrouver le chapeau d’anniversaire qu’il a perdu près de la rivière, non loin des...",kw={"chapeau d’anniversaire","ellie","chapeau","chapeau perdu","murlocs","rivière","robbie"},sec={{t="Un chapeau perdu",b="Robbie a perdu près de la rivière le chapeau que sa sœur lui avait offert pour son anniversaire, alors qu’il jouait. Il n’a pas le droit de s’approcher des murlocs. Il ne peut donc demander de l’aide ni à son père ni à Ellie. Il pense qu’un murloc a trouvé le chapeau. Vous devez le chercher quelque part le long de la rivière."}},faq={{q="Qui est Robbie ?",a="Robbie est un garçon qui a perdu près de la rivière le chapeau que sa sœur lui avait offert pour son anniversaire, alors qu’il jouait.",al={"robbie","qui est robbie"}},{q="Qu’a perdu Robbie ?",a="Robbie a perdu un chapeau que sa sœur lui avait offert pour son anniversaire.",al={"chapeau de robbie","chapeau perdu"}},{q="Où Robbie a-t-il perdu son chapeau ?",a="Robbie a perdu son chapeau alors qu’il jouait dans la rivière. Il vous demande de le chercher quelque part le long de la rivière, près des murlocs.",al={"emplacement du chapeau","où est le chapeau"}},{q="Pourquoi Robbie ne peut-il pas demander de l’aide à sa famille ?",a="Robbie n’a pas le droit de s’approcher des murlocs. Demander de l’aide à son père ou à Ellie révélerait où il était allé.",al={"pourquoi ne pas demander à papa","pourquoi le cacher"}},{q="Robbie sait-il si un murloc a pris le chapeau ?",a="Robbie suppose qu’un des murlocs a trouvé et gardé son chapeau.",al={"chapeau de murloc","les murlocs l’ont-ils pris"}}},fp="8,125,10.268.0,14.89.0,21.55.0,30.111.0,41.111.0,42.62.0"}
P.entries["quest:94946"] = {n="The Magical City of Dalaran",s="Un mage de Valanaar vous envoie de l’île de Zéphras à Dalaran, où des mages attendent l’arrivée de votre peuple. La cité offre un point de départ pour explorer Azeroth, mais les terres au-delà peuvent être dangereuses sans préparation ni expérience.",h="Un mage de Valanaar vous envoie de l’île de Zéphras à Dalaran, où des mages attendent l’arrivée de votre...",kw={"culte","dalaran","danaaris stargale","mages","coupe-ciel","valanaar","île de zéphras"},ang={["race:Skyborne"]="En tant que Skyborne, vous voyagez de l’île de Zéphras pour rejoindre les mages qui attendent l’arrivée de votre peuple à Dalaran."},sec={{t="Arrivée à Dalaran",b="Les récents événements liés au culte obligent la personne qui s’exprime à rester à Valanaar pour le moment. Plusieurs mages attendent votre peuple à Dalaran, alors vous êtes envoyé au quai, à l’extérieur du pavillon. Là, vous embarquez à bord d’un coupe-ciel en direction de Dalaran.\n\nÀ votre arrivée, parlez à Danaaris Stargale. Votre peuple s’installe encore dans la cité, et les terres au-delà de sa protection peuvent se révéler dangereuses."}},faq={{q="Qui vous attend à Dalaran ?",a="Plusieurs mages attendent l’arrivée de votre peuple à Dalaran. Une fois dans la cité, on vous demande de parler à Danaaris Stargale.",al={"mages à dalaran","qui est à dalaran","mages de dalaran"}},{q="D’où dois-je partir ?",a="Vous voyagez de l’île de Zéphras à Dalaran à bord du coupe-ciel qui se trouve au quai, à l’extérieur du pavillon.",al={"comment aller à dalaran","depuis zéphras","coupe-ciel"}},{q="Pourquoi la personne qui s’exprime reste-t-elle à Valanaar ?",a="Les récents événements liés au culte ont changé les plans de la personne qui s’exprime, qui compte donc rester quelque temps à Valanaar.",al={"pourquoi rester à valanaar","culte et plans modifiés","mage de valanaar"}},{q="Est-il prudent de sortir de Dalaran ?",a="Les terres au-delà de Dalaran peuvent être dangereuses sans préparation adéquate ni expérience.",al={"sortir de dalaran sans danger","dangers près de dalaran","alentours de dalaran"}}},fp="27,238,18.368.0,26.125.0,23.96.0,39.105.0,27.83.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="Vous arrivez à Hurlevent par le Skyborne Portal, où son régent vous accueille. Le généralissime Bolvar Fordragon vous autorise à voyager sur les terres de l’Alliance.",h="Vous arrivez à Hurlevent par le Skyborne Portal, où son régent vous accueille.",kw={"bolvar fordragon","haut-elfe","ordre suprême","kirin tor","portail","skyborne","donjon de hurlevent","welcome to azeroth"},ang={["faction:Alliance"]="Le généralissime Bolvar Fordragon accueille officiellement l’Ordre suprême au nom du roi Anduin Wrynn et l’autorise à parcourir librement les terres de l’Alliance.",["race:Skyborne"]="En tant que Skyborne, vous êtes accueilli à Hurlevent et autorisé à parcourir les territoires de l’Alliance à votre arrivée par le portail."},sec={{t="Arrivée dans la capitale",b="Vous franchissez le Skyborne Portal et pénétrez dans Hurlevent, la capitale humaine. De là, vous empruntez les grandes artères de la ville jusqu’au Donjon de Hurlevent, où la régence attend votre arrivée."},{t="Audience avec le régent",b="Le généralissime Bolvar Fordragon reçoit les membres de l’Ordre suprême qui arrivent dans la salle du trône. Un messager du Kirin Tor l’avait prévenu de leur venue. Cela fait longtemps que des hauts-elfes n’ont pas parcouru les couloirs du Donjon de Hurlevent, mais Bolvar les accueille comme des invités et leur accorde le libre passage sur les territoires de l’Alliance au nom du roi."}},faq={{q="De quoi parle cette quête ?",a="Vous arrivez à Hurlevent par le Skyborne Portal et vous présentez au généralissime Bolvar Fordragon au Donjon de Hurlevent.",al={"qu’est-ce que welcome to azeroth","quête welcome to azeroth"}},{q="Qui est Bolvar Fordragon ?",a="Le généralissime Bolvar Fordragon gouverne Hurlevent depuis le Donjon de Hurlevent en tant que régent. Il règne au nom du jeune roi Anduin Wrynn, tandis que le roi Varian reste introuvable.",al={"qui est bolvar fordragon","régent de hurlevent"}},{q="Pourquoi Bolvar reçoit-il les Skyborne ?",a="Un messager du Kirin Tor a annoncé à Bolvar Fordragon l’arrivée de membres de l’Ordre suprême. Il les accueille comme des invités de la couronne et les autorise à voyager librement sur les terres de l’Alliance.",al={"pourquoi les skyborne sont-ils à hurlevent","hauts-elfes à hurlevent"}},{q="Qu’est-ce que l’Ordre suprême ?",a="L’Ordre suprême est le groupe associé aux hauts-elfes Skyborne. Le Kirin Tor a annoncé leur arrivée aux dirigeants de Hurlevent.",al={"qui est l’ordre suprême","histoire de l’ordre suprême"}},{q="Où mène le Skyborne Portal ?",a="Le Skyborne Portal conduit les voyageurs directement à Hurlevent, la capitale humaine. De là, les nouveaux arrivants peuvent se rendre au Donjon de Hurlevent pour demander audience auprès de la couronne.",al={"destination du skyborne portal","où mène le portail"}},{q="Les Skyborne sont-ils autorisés à parcourir les territoires de l’Alliance ?",a="Bolvar Fordragon accueille les Skyborne comme les invités du roi et les autorise à voyager sans entrave sur les terres de l’Alliance.",al={"les skyborne sont-ils de l’alliance","accueil des skyborne par l’alliance"}}},fp="18,159,22.196.0,27.336.0,25.120.0,24.159.0,37.190.0,23.130.0,36.163.0,55.129.0"}
P.entries["quest:94962"] = {n="Bloodmaster's Ring",s="Un combat contre Bonegnaw est la prochaine épreuve pour devenir champion du Bloodmaster's Ring. Les ogres attendent de voir si vous leur offrirez un combat digne d'être regardé.",h="Un combat contre Bonegnaw est la prochaine épreuve pour devenir champion du Bloodmaster's Ring.",kw={"bloodmaster","bloodmaster's ring","bonegnaw","combat","champion","ogres"},sec={{t="La prochaine épreuve",b="Vos victoires ne font pas encore de vous un champion, et le gobelin de l’arène a un autre combat en tête. Bonegnaw sera votre adversaire, et le gobelin vous promet une surprise. Les ogres observent, et le prochain affrontement est censé les divertir."},{t="Après le combat",b="Le gobelin est mécontent de la façon dont le combat le fait paraître. Les ogres, cependant, semblent divertis, et il vous met en garde contre toute fierté quant au résultat."}},faq={{q="Qui est mon adversaire ?",a="Bonegnaw est votre adversaire dans le Bloodmaster's Ring.",al={"combat contre bonegnaw","qui dois-je affronter"}},{q="Suis-je déjà champion ?",a="Le gobelin de l’arène affirme que vos victoires ne font pas encore de vous un champion.",al={"champion bloodmaster","devenir champion"}},{q="Qui regarde le combat ?",a="Des ogres regardent le combat dans le Bloodmaster's Ring.",al={"ogres spectateurs","qui est diverti"}}},fp="18,170,13.226.0,15.151.1,19.52.0,20.66.0,26.54.0"}
P.entries["quest:94964"] = {n="Bloodmaster's Ring",s="Un présentateur vous appelle à affronter Mog’thar dans le Bloodmaster’s Ring. La foule attend son prochain adversaire.",h="Un présentateur vous appelle à affronter Mog’thar dans le Bloodmaster’s Ring.",kw={"présentateur","bloodmaster’s ring","adversaire","foule","mog’thar","arène"},sec={{t="Le prochain adversaire",b="Le présentateur a tenu la foule en haleine et présente maintenant Mog’thar comme le prochain adversaire. On vous appelle dans le Bloodmaster’s Ring, où la foule attend de voir ce qui va se passer."}},faq={{q="Qui dois-je affronter dans le Bloodmaster’s Ring ?",a="On vous appelle à affronter Mog’thar dans le Bloodmaster’s Ring.",al={"combat contre mog’thar","qui est le prochain adversaire","adversaire du bloodmaster’s ring"}},{q="Que dit le présentateur au sujet de Mog’thar ?",a="Le présentateur dit que Mog’thar n’est pas à prendre à la légère.",al={"qui est mog’thar","prochain adversaire","mog’thar est-il une plaisanterie"}},{q="Pourquoi m’envoie-t-on dans l’arène ?",a="Le présentateur veut maintenir l’enthousiasme de la foule en lui présentant un autre adversaire.",al={"pourquoi affronter mog’thar","raison du combat dans l’arène","que veut le présentateur"}}},fp="18,123,18.181.0,42.62.0,45.41.0,34.91.0"}
P.entries["quest:94968"] = {n="Eye of Mugg",s="Krom'rosh vous envoie au Bastion Krol’dok, où l'implantation du Twilight cult s'avère plus importante que prévu. Il vous demande une preuve de la mort de son chef.",h="Krom'rosh vous envoie au Bastion Krol’dok, où l'implantation du Twilight cult s'avère plus importante que...",kw={"grotte","chef du culte","œil de mugg","bastion krol’dok","krom'rosh","sacrifices","twilight cult"},sec={{t="Bastion Krol’dok",b="Krom'rosh craint que d'autres alliés soient sacrifiés si le Twilight cult continue de ravager ces terres. Peu de ceux qui sont entrés dans la grotte ont survécu, et l'implantation du Twilight cult est plus importante qu'il ne le croyait. Vous devez maintenant pénétrer dans le Bastion Krol’dok et revenir avec la preuve de la mort du chef."}},faq={{q="Qui me demande d'entrer dans le Bastion Krol’dok ?",a="Krom'rosh vous envoie au Bastion Krol’dok pour rapporter la preuve que le chef du Twilight cult est mort.",al={"qui m'a envoyé","requête de krom'rosh"}},{q="Que se passe-t-il au bastion ?",a="Le Twilight cult est mieux implanté que Krom'rosh ne le pensait et ravage les terres en sacrifiant des alliés.",al={"que se passe-t-il là-bas","problème du twilight cult"}},{q="Pourquoi Krom'rosh veut-il que j'entre ?",a="Krom'rosh veut arrêter le Twilight cult avant qu'il ne continue de ravager les terres et de sacrifier des alliés.",al={"pourquoi entrer","pourquoi entrer dans le bastion"}},{q="Quelle preuve Krom'rosh demande-t-il ?",a="Il demande la preuve que le chef du Twilight cult est mort.",al={"preuve nécessaire","que dois-je rapporter"}},{q="Beaucoup de ceux qui sont entrés dans la grotte ont-ils survécu ?",a="Peu de ceux qui ont réussi à entrer dans la grotte ont survécu.",al={"survivants de la grotte","qui s'en est sorti"}}},fp="11,150,19.268.0,46.105.0,32.119.0,36.98.0,34.58.0,38.43.0"}
P.entries["quest:94973"] = {n="Krol'dok Moulding",s="Un moulage trouvé près de Rog’mar semble faire partie d’une clé. Quelqu’un dans le campement saura peut-être ce qu’il ouvre.",h="Un moulage trouvé près de Rog’mar semble faire partie d’une clé.",kw={"clé","moulage de krol'dok","moule","moulage","rog’mar","bastion"},sec={{t="Un moulage intrigant",b="Vous avez un moulage qui semble destiné à une clé. À Rog’mar, quelqu’un saura peut-être à quoi sert cette pièce. S’il vient du bastion, il est peut-être important."}},faq={{q="À quoi sert le moulage ?",a="Le moulage semble destiné à une clé.",al={"pièce moulée","qu’est-ce que ce moule","moule de clé"}},{q="Qui peut identifier le moulage ?",a="Quelqu’un à Rog’mar en saura peut-être plus sur le moule.",al={"qui connaît le moule","se renseigner sur le moule","où apporter le moule"}},{q="Pourquoi pourrait-il être important ?",a="Si le moulage vient du bastion, il doit être important.",al={"le moule est-il important","moule du bastion","pourquoi s’intéresser au moule"}}},fp="17,108,15.151.0,25.37.0,30.44.0,20.61.0"}
P.entries["quest:94974"] = {n="Key Ingredients",s="Kreza Darkthorn a besoin de cuir et de fer pour fabriquer un moule à clé. Vous rassemblez les matériaux pendant qu’elle entretient les braises.",h="Kreza Darkthorn a besoin de cuir et de fer pour fabriquer un moule à clé.",kw={"braises","barre de fer","clé","ingrédients pour une clé","kreza darkthorn","moule","cuir épais"},sec={{t="Matériaux pour le moulage",b="Kreza Darkthorn possède un moule usé qui pourrait servir à façonner une clé. Vous lui apportez quatre Thick Leather et douze Iron Bar pendant qu’elle entretient les braises. Le moule devrait tenir, et Kreza est prête à voir ce qu’elle peut en faire."}},faq={{q="De quoi Kreza a-t-elle besoin ?",a="Kreza vous demande de lui apporter quatre Thick Leather et douze Iron Bar.",al={"quels matériaux","ingrédients pour une clé","de quoi kreza a-t-elle besoin"}},{q="À quoi servent ces matériaux ?",a="Ces matériaux servent à façonner une clé à partir d’un moule grossier et usé.",al={"pourquoi du cuir et du fer","clé pour quoi","matériaux pour le moulage"}},{q="Qui entretient les braises ?",a="Kreza Darkthorn dit qu’elle entretiendra les braises pendant que vous rassemblez les matériaux.",al={"qui entretient les braises","braises de kreza","braises ardentes"}},{q="Que dit Kreza au sujet du moule ?",a="Kreza dit que le moule est grossier et usé, mais qu’il pourrait tout de même servir à façonner une clé.",al={"état du moule","le moule est-il utilisable","moule à clé"}}},fp="15,115,26.225.0,21.63.0,27.67.0,30.81.0,39.82.0"}
P.entries["quest:94975"] = {n="A Token of Vengeance",s="Un allié vous charge de trouver Twilight’s Hammer dans les cavernes près du Bastion Krol’dok. Leurs attaques ont blessé vos alliés et menacent la région.",h="Un allié vous charge de trouver Twilight’s Hammer dans les cavernes près du Bastion Krol’dok.",kw={"un gage de vengeance","oreilles de cultiste","cultistes","caverne cachée","bastion krol’dok","marteau du crépuscule"},sec={{t="Les cavernes cachées",b="Les éclaireurs ont signalé que des cultistes de Twilight’s Hammer se déplacent sous le terrain accidenté près du Bastion Krol’dok. Votre allié affirme que leurs attaques ont fait souffrir vos alliés et que les cultistes s’emparent des terres. Vous devez trouver leur cachette et rapporter quinze oreilles de cultiste en signe de vengeance."}},faq={{q="Qui dois-je chercher ?",a="Vous devez chercher des cultistes de Twilight’s Hammer cachés dans un réseau de cavernes près du Bastion Krol’dok.",al={"qui sont les cultistes","twilight’s hammer ici","oreilles de cultiste"}},{q="Pourquoi traquer les cultistes ?",a="Selon le donneur de quête, les cultistes ont fait souffrir ses alliés et s’emparent des terres.",al={"pourquoi se venger","pourquoi les combattre","qu’ont-ils fait"}},{q="Que savent les éclaireurs ?",a="Les éclaireurs ont signalé des déplacements de cultistes sous le terrain accidenté, dans un réseau de cavernes caché au nord.",al={"rapport des éclaireurs","où sont les cultistes","déplacements des cultistes"}},{q="Que dois-je rapporter ?",a="Vous devez récupérer quinze Cultist Ears sur les membres de Twilight’s Hammer au Bastion Krol’dok.",al={"que dois-je récupérer","quête des oreilles","combien d’oreilles"}}},fp="20,158,16.328.0,21.99.0,34.90.0,24.99.0,30.98.0"}
P.entries["quest:94978"] = {n="Taming the Beast",s="Quel'ana Quickgale vous enseigne le lien entre la bête et son maître. Vous commencez par dompter un Windsong Crawler près des eaux de Zephras.",h="Quel'ana Quickgale vous enseigne le lien entre la bête et son maître.",kw={"domptage des bêtes","quel'ana quickgale","bâtonnet de domptage","taming the beast","valanaar","windsong crawler","zephras"},sec={{t="Premier lien",b="Vous avez le Bâtonnet de domptage et un Windsong Crawler à dompter. Trouvez-en un près d'un point d'eau et exercez-vous. Puis rapportez le bâtonnet à Quel'ana Quickgale, à Valanaar. Cette créature est votre premier pas vers la maîtrise."}},faq={{q="Quelle bête Quel'ana me demande-t-elle de dompter ?",a="Quel'ana vous demande de dompter un Windsong Crawler près d'un point d'eau sur Zephras.",al={"quelle bête","cible de domptage","quête du crawler"}},{q="À quoi sert le Bâtonnet de domptage ?",a="Vous utilisez le Bâtonnet de domptage pour dompter un Windsong Crawler.",al={"fonctionnement du bâtonnet","outil de domptage","quête du bâtonnet"}},{q="Où trouver un Windsong Crawler ?",a="Les Windsong Crawlers vivent près des points d'eau sur Zephras.",al={"emplacement du crawler","où trouver le crawler","bête de zephras"}},{q="Qui m'a donné le Bâtonnet de domptage ?",a="Quel'ana Quickgale vous donne le Bâtonnet de domptage à Valanaar.",al={"donneur de quête","qui est quel'ana","quel'ana quickgale"}},{q="Pourquoi est-ce que j'apprends à dompter une bête ?",a="Apprendre le lien entre la bête et son maître est le premier pas vers la maîtrise de votre classe.",al={"pourquoi dompter le crawler","maîtrise des bêtes","premier domptage"}}},fp="16,132,10.215.0,34.77.0,27.50.0,35.55.0,27.56.0,34.90.0"}
P.entries["quest:94979"] = {n="Taming the Beast",s="Dans les Plaines Aérelles, Quel'ana Quickgale vous demande de dompter un galestrider. Votre maîtrise des grands espaces vous préparera aux épreuves à venir.",h="Dans les Plaines Aérelles, Quel'ana Quickgale vous demande de dompter un galestrider.",kw={"galestrider","plaines aérelles","ornery galestrider","quel'ana quickgale","bâtonnet de domptage","taming the beast","valanaar","zephras"},sec={{t="À travers les plaines",b="Vous avez déjà montré que vous pouviez dompter le rampant des rivières. À présent, Quel'ana Quickgale vous remet un Bâtonnet de domptage et vous envoie dans les basses terres de Zephras. Là, un fier galestrider ailé court à vive allure dans les plaines. Gagnez sa confiance et exercez votre talent. Puis rapportez le bâtonnet à Quel'ana, à Valanaar."}},faq={{q="Que veut que je dompte Quel'ana ?",a="Quel'ana vous demande de dompter un Ornery Galestrider dans les Plaines Aérelles.",al={"dompter quoi","dompter un galestrider","quelle bête"}},{q="Où trouver le galestrider ?",a="Vous trouverez l'Ornery Galestrider dans les Plaines Aérelles, dans les plaines de Zephras.",al={"où trouver le galestrider","emplacement du galestrider","où sont les basses terres"}},{q="À quoi sert le Bâtonnet de domptage ?",a="Quel'ana vous remet le Bâtonnet de domptage pour que vous puissiez dompter un Ornery Galestrider.",al={"utilité du bâtonnet de domptage","à quoi sert le bâtonnet","comment dompter une bête"}},{q="Qui m'a confié cette mission ?",a="Quel'ana Quickgale, à Valanaar, vous demande de dompter un Ornery Galestrider et de rapporter le Bâtonnet de domptage.",al={"qui m'a envoyé","qui est quel'ana","quickgale"}}},fp="16,138,17.298.0,35.74.0,32.88.0,27.72.0,28.100.0"}
P.entries["quest:94980"] = {n="Krol'dok Moulding",s="Le moulage de Krol'dok semble être celui d'une clé. Quelqu'un au Donjon de Fort-Lointain en saura peut-être davantage.",h="Le moulage de Krol'dok semble être celui d'une clé.",kw={"donjon de fort-lointain","clé","moulage de krol'dok","moulage"},sec={{t="Le moulage d'une clé",b="Vous avez un moulage qui semble être celui d'une clé. Quelqu'un au Donjon de Fort-Lointain saura peut-être à quoi il sert, et vous le lui apportez pour en apprendre davantage."}},faq={{q="Qu'est-ce que le moulage de Krol'dok ?",a="Le moulage de Krol'dok semble être celui d'une clé.",al={"moulage de kroldok","moulage de krol'dok","qu'est-ce que ce moulage"}},{q="Qui pourrait en savoir plus sur le moulage ?",a="Quelqu'un au Donjon de Fort-Lointain en saura peut-être davantage.",al={"qui connaît le moulage","spécialiste du moulage","se renseigner sur le moulage"}},{q="Que se passe-t-il quand j'apporte le moulage ?",a="La personne à qui vous l'apportez dit qu'elle va voir ce qu'elle peut en faire.",al={"résultat du moulage","que dit-on","moulage de clé"}}},fp="17,107,13.146.0,30.46.0,31.50.0,39.71.0"}
P.entries["quest:94981"] = {n="Key Ingredients",s="Alphonse Dumas a besoin de matériaux pour façonner une clé à partir d’un moule grossier. Vous devez lui apporter du Thick Leather et des Iron Bars.",h="Alphonse Dumas a besoin de matériaux pour façonner une clé à partir d’un moule grossier.",kw={"alphonse dumas","braises","iron bars","clé","ingrédients de la clé","moule","thick leather"},sec={{t="Matériaux pour la clé",b="Alphonse Dumas garde les braises ardentes pendant que vous rassemblez ce dont il a besoin. Le moule est grossier, mais les bons matériaux pourraient lui permettre de façonner une clé."}},faq={{q="De quoi Alphonse a-t-il besoin ?",a="Alphonse Dumas vous demande de lui apporter quatre Thick Leather et douze Iron Bars.",al={"matériaux nécessaires","quoi apporter","ingrédients de la clé"}},{q="Que fabrique Alphonse ?",a="Alphonse espère façonner une clé à partir d’un moule grossier en utilisant les bons matériaux.",al={"que fabrique-t-il","à quoi sert la clé","moule de la clé"}},{q="À qui dois-je apporter les matériaux ?",a="Apportez le Thick Leather et les Iron Bars à Alphonse Dumas.",al={"qui reçoit les ingrédients","à qui apporter les matériaux"}}},fp="15,126,21.141.0,24.73.0,24.80.0,30.56.0"}
P.entries["quest:94983"] = {n="Twilight Mementos",s="Le sergent Riftan vous envoie au nord, au Bastion Krol’dok, après que des éclaireurs ont confirmé une cachette du Marteau du crépuscule. Il vous demande de rapporter une preuve de la défaite des cultistes.",h="Le sergent Riftan vous envoie au nord, au Bastion Krol’dok, après que des éclaireurs ont confirmé une...",kw={"grotte","bracelets des cultistes","cachette des cultistes","bastion krol’dok","éclaireurs","sergent riftan","twilight mementos","marteau du crépuscule"},sec={{t="Rapports des éclaireurs",b="Les éclaireurs ont rapporté au sergent Riftan de sombres nouvelles au sujet d’une cachette de cultistes. Leurs récits confirment les témoignages d’autres personnes. Une grotte se trouve au nord, dissimulée par le paysage, et Riftan pense qu’elle offre au culte un point d’appui au cœur des montagnes. Il vous envoie au Bastion Krol’dok rapporter la preuve que les cultistes du Marteau du crépuscule ont été vaincus."}},faq={{q="Qui me demande d’aller au nord ?",a="Le sergent Riftan vous demande de retrouver les cultistes du Marteau du crépuscule au Bastion Krol’dok et de revenir avec une preuve de leur défaite.",al={"qui m’a envoyé","sergent riftan"}},{q="Qu’ont découvert les éclaireurs ?",a="Les récits des éclaireurs ont confirmé les rapports sur une cachette de cultistes, dans une grotte dissimulée au nord.",al={"rapport des éclaireurs","qu’ont-ils découvert"}},{q="Où se trouve la cachette ?",a="La cachette se trouve dans une grotte au nord, dissimulée par le paysage. Riftan pense qu’elle constitue un point d’appui au cœur des montagnes.",al={"grotte des cultistes","où sont les cultistes"}},{q="Quelle preuve Riftan veut-il ?",a="Riftan vous demande de rapporter la preuve que les cultistes du Bastion Krol’dok ont été vaincus.",al={"quelle preuve","preuve contre les cultistes"}},{q="Qui sont les cultistes ?",a="Ce sont des membres du Marteau du crépuscule, dont les rapports des éclaireurs ont confirmé l’existence de la cachette.",al={"culte du crépuscule","marteau du crépuscule"}}},fp="17,161,15.350.0,29.129.0,25.96.0,21.125.0,28.96.0,21.99.0"}
P.entries["quest:94992"] = {n="Rescue Roundup",s="Wheeler vous demande de ramener son cheval perdu, Biscuit, à Wheeler's Grange. Son retour permet à la ferme de reprendre ses activités.",h="Wheeler vous demande de ramener son cheval perdu, Biscuit, à Wheeler's Grange.",kw={"biscuit","demar","cheval","cheval perdu","rassemblement des sauvetages","compagnes d'écurie","wheeler's grange"},sec={{t="Le retour de Biscuit",b="Le cheval perdu de Wheeler s'appelle Biscuit. Elle baisse la tête avant de vous donner un petit coup de museau sur le bras. Vous la ramenez à Wheeler's Grange. Wheeler est reconnaissant de retrouver Biscuit, même si elle s'attend à ce que la jument soit seule quelque temps. La ferme reprend ses activités."}},faq={{q="Qui est Biscuit ?",a="Biscuit est le cheval de Wheeler. Elle s'est égarée et doit être ramenée à Wheeler's Grange.",al={"cheval biscuit","cheval perdu","qui est biscuit"}},{q="Où faut-il emmener Biscuit ?",a="Il faut ramener Biscuit à Wheeler's Grange.",al={"où emmener le cheval","emplacement de biscuit","destination du cheval"}},{q="Pourquoi Wheeler est-il reconnaissant ?",a="Wheeler est reconnaissant parce que vous ramenez Biscuit à la ferme.",al={"pourquoi remercier","biscuit sauvée","remerciements de wheeler"}},{q="Biscuit est-elle seule ?",a="Wheeler dit que Biscuit sera seule quelque temps et espère retrouver certaines de ses compagnes d'écurie.",al={"biscuit seule","où sont les compagnes d'écurie","autres chevaux"}},{q="Wheeler's Grange est-elle ouverte ?",a="Avec le retour de Biscuit, Wheeler's Grange reprend ses activités.",al={"ferme ouverte","activités de wheeler","ferme reprend"}}},fp="14,125,15.260.0,15.95.0,30.53.0,24.65.0,17.90.0,25.56.0"}
P.entries["quest:94997"] = {n="Lingering Essence",s="Riftan vous demande d’apporter une sacoche remplie de souvenirs maudits à Ashe Amberhall, au donjon de Fort-Lointain. Il espère que ses études révéleront les énergies que renferment ces objets.",h="Riftan vous demande d’apporter une sacoche remplie de souvenirs maudits à Ashe Amberhall, au donjon de...",kw={"ashe amberhall","cultistes","souvenirs maudits","énergies","donjon de fort-lointain","essence persistante","riftan","satchel of cursed mementos"},sec={{t="Au donjon",b="Au donjon de Fort-Lointain, Ashe Amberhall prend la sacoche et apprend que Riftan l’a envoyée. Elle dit que son long combat contre les cultistes lui fait craindre que la fatigue n’obscurcisse son jugement. Pourtant, elle reconnaît que ses inquiétudes sont peut-être fondées et se penche sur les objets."}},faq={{q="Qui me demande d’apporter la sacoche ?",a="Riftan vous demande d’apporter le Satchel of Cursed Mementos à Ashe Amberhall.",al={"qui m’a envoyé","sacoche de riftan","qui est riftan"}},{q="Qui est Ashe Amberhall ?",a="Ashe Amberhall est une érudite respectée. Ses travaux pourraient l’aider à examiner les énergies contenues dans les objets.",al={"ashe, qui est-ce","qui est ashe","amberhall"}},{q="Où dois-je apporter les souvenirs ?",a="Apportez le Satchel of Cursed Mementos à Ashe Amberhall, au donjon de Fort-Lointain.",al={"où apporter la sacoche","donjon de fort-lointain","destination de la sacoche"}},{q="Que contient la sacoche ?",a="La sacoche contient des souvenirs maudits que Riftan souhaite faire examiner par Ashe afin de découvrir quelles énergies ils renferment.",al={"que contient le sac","souvenirs maudits","contenu de la sacoche"}},{q="Pourquoi Riftan veut-il qu’Ashe les examine ?",a="Riftan espère que les études d’Ashe révéleront les énergies contenues dans les objets.",al={"pourquoi ashe","à quoi sert la sacoche","essence persistante"}},{q="Que pense Ashe des inquiétudes de Riftan ?",a="Ashe craint que la fatigue, après le long combat de Riftan contre les cultistes, ne lui brouille l’esprit, mais elle reconnaît que ses inquiétudes sont peut-être fondées.",al={"ashe fait-elle confiance à riftan","riftan est fatigué","avis d’ashe"}}},fp="17,153,11.279.0,38.73.0,22.108.0,29.72.0,23.95.0,42.86.0,41.132.0"}
P.entries["quest:94998"] = {n="Curios of Curiosity",s="Vous apportez à Melanie Sable une sacoche de souvenirs insolites. Leur facture soignée pourrait les rendre utiles.",h="Vous apportez à Melanie Sable une sacoche de souvenirs insolites.",kw={"facture","curiosités insolites","melanie sable","souvenirs","vestiges","sacoche de souvenirs"},sec={{t="Une sacoche pour Melanie",b="Une personne qui a examiné les souvenirs vous envoie remettre la sacoche à Melanie Sable. Elle pense que les objets sont sans danger, bien que leur origine reste inconnue. Leur facture est inhabituelle, et Melanie pourrait leur trouver une utilité."}},faq={{q="À qui dois-je apporter les souvenirs ?",a="Remettez la sacoche de souvenirs à Melanie Sable, comme le demande la personne qui les a examinés.",al={"où apporter la sacoche","qui est melanie sable"}},{q="Que sont ces souvenirs ?",a="Ce sont les vestiges de quelque chose, mais la personne qui les a examinés ignore exactement de quoi.",al={"que contient la sacoche","que sont ces curiosités"}},{q="Pourquoi ces souvenirs sont-ils inhabituels ?",a="Leur facture est décrite comme tout à fait unique et complexe.",al={"qu'ont-elles de particulier","facture des curiosités"}},{q="Ces souvenirs sont-ils sans danger ?",a="La personne qui les a examinés vous demande de dire à Melanie que les souvenirs sont sans danger.",al={"la sacoche est-elle sans danger","sont-elles dangereuses"}}},fp="19,104,21.217.0,34.68.0,22.76.0,29.63.0,22.65.0"}
P.entries["quest:95"] = {n="La vengeance de Sven",s="Dans La vengeance de Sven, le chagrin pousse Sven Yorgen à quitter sa ferme en ruine, dans le sud du Bois de la Pénombre, pour traquer ses meurtriers. Désormais campé dans les collines de l’ouest, il demande aux voyageurs de retourner à la ferme, où un inconnu a enterré quelque chose près de la grange.",h="Dans La vengeance de Sven, le chagrin pousse Sven Yorgen à quitter sa ferme en ruine, dans le sud du Bois de...",kw={"dark riders","défilé de deuillevent","bois de la pénombre","tas de terre meuble","souche","sven yorgen","la vengeance de sven","la ferme des yorgen"},ang={["class:Paladin"]="En tant que paladin, vous voyez dans le massacre d’innocents par des forces venues du Défilé de Deuillevent un appel à rendre justice aux morts.",["faction:Alliance"]="Le massacre de la famille Yorgen montre jusqu’où s’étendent les forces obscures dans les régions isolées du Bois de la Pénombre, où les patrouilles de l’armée de Hurlevent sont rares."},sec={{t="La tragédie de la ferme",b="Des Dark Riders encapuchonnés sont venus du Défilé de Deuillevent et ont attaqué la ferme de Sven Yorgen, dans le sud-est du Bois de la Pénombre. Sven était absent et ils ont tué sa famille. À son retour, découvrant le massacre, il a vu une silhouette inconnue rôder près de la grange et enterrer quelque chose à la hâte. Sven a laissé l’objet caché et s’est lancé à la poursuite des meurtriers."},{t="Secrets enfouis",b="Sven Yorgen campe dans les collines de l’ouest, consumé par la colère et en quête d’aide à sa ferme. Entre la maison et la grange en ruine, un tas de terre meuble derrière une vieille souche indique l’endroit où quelque chose a été enterré à la hâte. Le retrouver pourrait expliquer pourquoi ces cavaliers ténébreux ont pris pour cible un paisible fermier du Bois de la Pénombre."}},faq={{q="Qui est Sven Yorgen ?",a="Sven Yorgen était fermier dans le sud-est du Bois de la Pénombre, près de la frontière du Défilé de Deuillevent. Après le meurtre de sa famille par des cavaliers encapuchonnés, il a quitté sa ferme et s’est isolé, consumé par son désir de vengeance.",al={"qui est sven","histoire de sven","passé de sven"}},{q="Qu’est-il arrivé à la ferme de Sven ?",a="Des Dark Riders venus du Défilé de Deuillevent ont attaqué la ferme de Sven Yorgen et tué sa famille. La propriété a été laissée en ruines pendant l’absence de Sven.",al={"tragédie de la ferme des yorgen","qu’est-il arrivé à la ferme de sven","pourquoi la ferme de sven est-elle détruite"}},{q="Qui a enterré quelque chose derrière la grange ?",a="Après le massacre, Sven a vu une silhouette obscure enterrer quelque chose près de sa grange. Il s’est lancé à la poursuite des Dark Riders avant d’avoir pu rattraper l’inconnu ou découvrir ce qui avait été enterré.",al={"qui a enterré l’objet","silhouette obscure à la ferme de sven","qui a creusé le tas"}},{q="Où se trouve le tas de terre meuble ?",a="À la ferme des Yorgen, dans le sud-est du Bois de la Pénombre, un tas de terre meuble se trouve derrière une vieille souche, entre la grange et la maison en ruine.",al={"où se trouve le tas de terre","emplacement du tas de terre","où se trouve la souche"}},{q="Qui sont les Dark Riders ?",a="Les Dark Riders sont des cavaliers encapuchonnés qui chevauchent depuis le Défilé de Deuillevent. Leurs origines sont inconnues, mais leurs attaques dans le Bois de la Pénombre sèment la mort et la ruine.",al={"que sont les dark riders","histoire des dark riders","cavaliers du défilé de deuillevent"}},{q="Pourquoi Sven n’a-t-il pas déterré l’objet lui-même ?",a="Sven était accablé par le chagrin en rentrant chez lui, lorsqu’il a vu une silhouette enterrer quelque chose. Il s’est aussitôt lancé à la poursuite des Dark Riders en fuite, laissant l’objet derrière lui.",al={"pourquoi sven n’a-t-il pas vérifié la terre","pourquoi sven est-il parti"}}},fx={e064b97c={q="Pourquoi Sven Yorgen veut-il que l'objet enterré soit récupéré ?",a="Sven cherche à se venger du massacre brutal de sa famille par les mystérieux Dark Riders du Défilé de Deuillevent. Lorsqu'il a découvert le massacre, il a été témoin d'une silhouette sombre enterrant précipitamment quelque chose près de sa grange avant de s'enfuir. Poussé par la rage et le besoin de réponses, Sven pense que ce qui repose sous le sol détient la clé pour découvrir pourquoi sa ferme a été prise pour cible et qui a aidé à la destruction de sa famille.",al={"pourquoi sven veut-il cela","motivation de sven yorgen","raison de la quête de vengeance de sven"}}},fp="14,234,24.320.0,18.307.0,19.181.0,29.133.0,37.168.0,41.140.0,24.145.0,47.164.0"}
P.entries["quest:950"] = {n="Retourner voir Onu",s="Vous apportez à Onu, à Sombrivage, une page déchirée du Twilight Tome. Vous n’avez pu supporter que les écrits des cultistes tirés de leur livre.",h="Vous apportez à Onu, à Sombrivage, une page déchirée du Twilight Tome.",kw={"sombrivage","bosquet des anciens","gribouillages déments","old gods","onu","twilight tome","marteau du crépuscule"},ang={["class:Druid"]="En tant que druide, vous reconnaissez dans la résonance chaotique et contre nature des gribouillages une offense à l’ordre naturel que vous protégez aux côtés des tréants comme Onu.",["faction:Alliance"]="En tant que membre de l’Alliance, vous aidez à enquêter sur les activités du culte le long de la côte de Sombrivage et à protéger les communautés des Elfes de la nuit, comme Auberdine, des menaces cachées.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous voyez dans la profanation des côtes de Sombrivage par les cultistes une menace pour l’équilibre protégé par les Ancients of Lore. Les avertissements d’Onu touchent de près les kaldorei."},sec={{t="Un aperçu de la folie",b="Le Twilight Tome submerge quiconque tente de le lire. Ses mots ondulent sur la page et ses volutes ornementées se tordent en figures grotesques. Vous arrachez une page couverte de gribouillages avant que la tension ne vous donne le vertige."},{t="Soupçons anciens",b="Onu, l’Ancient of Lore, reconnaît une aura étrange dans la page que vous lui apportez. Sa magie chaotique et primordiale révèle des forces anciennes et ténébreuses enfouies sous la terre. Bien que l’écriture soit difficile à déchiffrer, elle montre que le Marteau du crépuscule à Sombrivage ne se livre pas qu’au banditisme."}},faq={{q="De quel livre provient la page arrachée ?",a="Gribouillages déments est une page déchirée du Twilight Tome, le livre sacré du culte. Son écriture changeante provoque une grave détresse mentale.",al={"gribouillages déments","que sont les gribouillages","page du twilight tome"}},{q="Qui est Onu ?",a="Onu est un Ancient of Lore du Bosquet des Anciens, dans le sud de Sombrivage. Gardien et érudit, il guide les Elfes de la nuit et leurs alliés de l’Alliance contre la corruption qui gagne la forêt.",al={"qui est onu","onu à sombrivage","onu le tréant"}},{q="Qu’apprend Onu grâce aux gribouillages ?",a="Onu ressent dans la page une énergie chaotique et primordiale, ainsi que l’influence d’entités anciennes et malveillantes. Les écrits laissent entendre que les cultistes du Marteau du crépuscule recherchent des sites de reliques et des pouvoirs enfouis à travers Sombrivage.",al={"qu’a découvert onu","signification des gribouillages"}},{q="Pourquoi le Marteau du crépuscule est-il à Sombrivage ?",a="Le Marteau du crépuscule est venu à Sombrivage pour fouiller des ruines elfiques et découvrir des traces de pouvoir ancien liées aux ténèbres primordiales et aux Old Gods. Le chaos qui règne dans la région aide à dissimuler leurs rites.",al={"cultistes à sombrivage","pourquoi le marteau du crépuscule est ici"}},{q="Où cette enquête mène-t-elle ensuite ?",a="Onu porte son attention sur les anciennes ruines elfiques de Mathystra, au nord. Il charge les aventuriers de mettre les reliques en sécurité avant que les cultistes ne s’en emparent.",al={"quelle est la quête suivante","après retourner voir onu"}},{q="Pourquoi la lecture du tome donne-t-elle le vertige ?",a="Une magie sombre et démente emplit le Twilight Tome. Ses glyphes désorientent les esprits mortels, provoquant des hallucinations et des évanouissements qui empêchent les étrangers de percer ses secrets.",al={"pourquoi le tome donne le vertige","effets du twilight tome"}}},fp="13,134,22.216.0,18.276.1,46.130.0,11.190.0,39.209.0,42.194.0,40.157.1,42.166.0"}
P.entries["quest:95033"] = {n="On the Other Side",s="Tan'jani vous envoie au Camp Mojache, en Féralas, pour demander l'aide du Féticheur Uzer'i. Réputé pour sa magie, Uzer'i est aussi chasseur.",h="Tan'jani vous envoie au Camp Mojache, en Féralas, pour demander l'aide du Féticheur Uzer'i.",kw={"camp mojache","féralas","chasseur","magie","de l'autre côté","tan'jani","féticheur uzer'i"},sec={{t="L'ami de Tan'jani",b="Au cœur de Féralas, vous trouverez le Féticheur Uzer'i au Camp Mojache. C'est un vieil ami de Tan'jani. Tan'jani dit qu'Uzer'i pratique la magie, mais qu'il est aussi chasseur. Vous partez lui parler, laissant derrière vous les vastes plaines ouvertes."}},faq={{q="Qui m'envoie voir Uzer'i ?",a="Tan'jani vous envoie voir le Féticheur Uzer'i, un vieil ami.",al={"tan'jani m'a envoyé","qui est le vieux tan'jani"}},{q="Où trouver Uzer'i ?",a="Le Féticheur Uzer'i se trouve au Camp Mojache, en Féralas.",al={"emplacement d'uzer'i","où est le féticheur"}},{q="Pourquoi m'envoie-t-on voir Uzer'i ?",a="Tan'jani dit qu'Uzer'i cherche de l'aide et vous demande de lui parler.",al={"pourquoi parler à uzer'i","que veut tan'jani"}},{q="Que fait Uzer'i ?",a="Le Féticheur Uzer'i pratique la magie et est aussi chasseur.",al={"métier d'uzer'i","féticheur chasseur"}}},fp="17,137,17.228.0,22.57.0,24.50.0,30.72.0,20.58.0"}
P.entries["quest:95034"] = {n="The Debt",s="Lumina Windsinger, au Sépulcre, raconte l’attaque qui a laissé Banon grièvement blessé. Selon son récit, c’est un worgen qui les a attaqués sur la route.",h="Lumina Windsinger, au Sépulcre, raconte l’attaque qui a laissé Banon grièvement blessé.",kw={"banon","gnolls","lumina windsinger","attaque sur la route","le sépulcre","the debt","worgen"},sec={{t="Une blessure sur la route",b="Lumina Windsinger, au Sépulcre, vous raconte ce qui s’est passé sur la route. Un worgen gigantesque, semblable à un loup, a attaqué son groupe et tué ses gardes. Banon s’est interposé entre la créature et Lumina, qui l’a repoussée avec un sort. Banon avait alors été gravement mordu. Il l’a suppliée de l’abandonner, mais elle est restée, et tous deux ont poursuivi leur chemin en boitant avant que des gnolls les trouvent."},{t="Les derniers instants de Banon",b="Banon, au Sépulcre, a été transpercé par de nombreuses lames gnolles avant de se retourner contre Lumina. Elle a vu qu’il la reconnaissait encore, même s’il ne pouvait plus se maîtriser. Lumina pense que le worgen l’a condamné et jure de le tuer pour qu’il ne puisse faire subir la même horreur à aucun autre être vivant."}},faq={{q="Qui a attaqué Lumina et Banon sur la route ?",a="Un worgen gigantesque, semblable à un loup, a attaqué Lumina et Banon sur la route.",al={"ce qui les a attaqués","attaque de worgen","agresseur sur la route"}},{q="Qu’est-il arrivé aux gardes ?",a="Le worgen a tué les gardes qui accompagnaient Lumina et Banon.",al={"sort des gardes","qu’est-il arrivé aux gardes","gardes sur la route"}},{q="Comment Lumina a-t-elle repoussé le worgen ?",a="Lumina a réussi à lancer un sort qui a effrayé le worgen et l’a fait fuir.",al={"comment le worgen a fui","sort de lumina","ce qui l’a effrayé"}},{q="Pourquoi Banon a-t-il été mordu ?",a="Banon s’est jeté sur le chemin du worgen pour protéger Lumina, et la créature l’a gravement mordu.",al={"morsure de banon","comment banon a été blessé","ce qui est arrivé à banon"}},{q="Où Lumina vous raconte-t-elle ce qui s’est passé ?",a="Lumina Windsinger vous livre son récit au Sépulcre.",al={"où trouver lumina","emplacement de lumina","le sépulcre"}}},fp="8,160,19.344.0,20.277.1,42.64.0,28.66.0,36.78.0,21.91.0,41.57.0"}
P.entries["quest:95036"] = {n="A Moon-Kissed Blade",s="Trevan vous avertit que les worgens menacent la Forêt des Pins-Argentés. Old Fire-Eye échappe à la mort grâce à une magie inconnue, et Trevan vous demande de découvrir ce qu’exige une lame spéciale.",h="Trevan vous avertit que les worgens menacent la Forêt des Pins-Argentés.",kw={"a moon-kissed blade","matériaux pour la lame","old fire-eye","forêt des pins-argentés","arme spéciale","trevan","worgen"},sec={{t="La liste du forgeron",b="Old Fire-Eye est le worgen qui a attaqué Trevan et ses compagnons. Trevan vous remettra la liste des matériaux nécessaires pour fabriquer une arme contre lui. Les matériaux sont réunis, et Trevan pense connaître un forgeron capable de fabriquer la lame."}},faq={{q="Qui est Old Fire-Eye ?",a="Old Fire-Eye est le plus grand et le plus cruel des worgens. Il a attaqué Trevan et ses compagnons.",al={"old fire-eye","worgen au feu dans l’œil","grand worgen"}},{q="Pourquoi Old Fire-Eye revient-il sans cesse ?",a="Une magie inconnue empêche Old Fire-Eye de rester mort.",al={"pourquoi fire-eye ne meurt pas","magie d’old fire-eye","worgen qui ne reste pas mort"}},{q="Qu’attend Trevan de moi ?",a="Trevan vous remettra la liste des matériaux nécessaires pour forger une arme spéciale.",al={"ce que veut trevan","liste de trevan","matériaux pour la lame"}},{q="Pourquoi faut-il une lame spéciale ?",a="Old Fire-Eye échappe à la mort grâce à une magie inconnue. Selon Trevan, une arme spéciale est nécessaire pour en venir à bout.",al={"pourquoi une lame baisée par la lune","arme contre old fire-eye","tuer fire-eye"}},{q="Qui peut fabriquer la lame ?",a="Trevan pense connaître un forgeron capable de fabriquer la lame.",al={"forgeron pour la lame","qui fabrique la lame lunaire","forgeron de la lame"}}},fp="19,170,14.223.0,20.93.0,39.51.0,30.74.0,30.105.0,24.55.0"}
P.entries["quest:95041"] = {n="Data Hoarders",s="À l’extérieur de Gnomeregan, Jemma Quikswitch cherche dans la neige des cartes perforées perdues. Cette gnome exilée vit à Forgefer. Les cartes contiennent les archives de sa famille, des plans de sous-marins aux recettes familiales. Sans elles, les documents qu’elle possède encore restent illisibles.",h="À l’extérieur de Gnomeregan, Jemma Quikswitch cherche dans la neige des cartes perforées perdues.",kw={"data hoarders","dun morogh","gnomeregan","forgefer","jemma quikswitch","cartes perforées","deuxième guerre","coque de sous-marin"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez aider les gnomes déplacés à préserver les archives d’ingénierie de guerre et le savoir de l’Alliance qu’elles contiennent.",["profession:Cooking"]="En tant que cuisinier, vous pouvez apprécier la recette de chili de grand-mère Quikswitch parmi les archives d’ingénierie.",["profession:Engineering"]="En tant qu’ingénieur, vous pouvez mesurer la valeur des plans de sous-marins et des équations arcanotechniques de la Deuxième guerre contenus dans ces cartes.",["race:Gnome"]="En tant que gnome, vous pouvez préserver les inventions et les souvenirs familiaux de votre terre natale en récupérant les cartes perforées."},sec={{t="Une recherche dans la neige",b="Quand les troggs envahirent Gnomeregan et que les radiations frappèrent, des milliers de gnomes s’enfuirent avec ce qu’ils purent emporter. Une sacoche abîmée laissa tomber plusieurs cartes de Jemma dans la neige autour de la cité déchue. Sans elles, les documents qu’elle a conservés ressemblent à du charabia, et le savoir de sa famille risque de se perdre."},{t="Équations et chili",b="Les archives Quikswitch contiennent des équations de champ arcanotechniques et des plans de coques de sous-marins datant de la Deuxième guerre. Elles préservent aussi la recette secrète de chili de grand-mère Quikswitch. Pour les réfugiés de Forgefer, les plaisirs du foyer comptent autant que les merveilles de l’ingénierie."}},faq={{q="Qui est Jemma Quikswitch ?",a="Jemma Quikswitch est une réfugiée gnome qui a échappé à la chute de Gnomeregan et vit désormais à Forgefer.",al={"jemma quikswitch","qui donne data hoarders","donneur de quête data hoarders"}},{q="Quelles données sont stockées sur les cartes perdues ?",a="Les cartes perforées contiennent les archives de la famille Quikswitch, notamment des équations arcanotechniques, des schémas de coques de sous-marins datant de la Deuxième guerre et la recette de chili de grand-mère Quikswitch.",al={"que sont les cartes perforées","contenu des cartes","archives quikswitch"}},{q="Où les cartes de données ont-elles été perdues ?",a="Les cartes sont tombées du sac de Jemma pendant sa fuite de Gnomeregan. Elles se trouvent dans la neige, juste à l’extérieur des portes de la cité, à Dun Morogh.",al={"où sont les cartes","emplacement des cartes de données","où les a-t-elle laissées tomber"}},{q="Pourquoi Jemma ne peut-elle pas lire les cartes qu’elle a conservées sans celles qui manquent ?",a="Jemma explique que les données sont trop brouillées pour être récupérées sans les cartes perforées manquantes. Les documents n’expliquent pas comment les cartes encodent ou organisent ces informations.",al={"pourquoi faut-il toutes les cartes","données brouillées","données des cartes perforées"}},{q="Quel rôle les gnomes ont-ils joué avec les sous-marins pendant la Deuxième guerre ?",a="Pendant la Deuxième guerre, les gnomes ont aidé l’Alliance grâce à leur ingénierie avancée. Ils ont conçu et piloté des submersibles pour contrer les forces navales de la Horde.",al={"sous-marins gnomes deuxième guerre","plans de coques de sous-marins"}},{q="Pourquoi des réfugiés gnomes vivent-ils à Forgefer ?",a="Après que des envahisseurs troggs eurent provoqué la chute de Gnomeregan et que les radiations eurent frappé, les gnomes survivants ont fui leur foyer souterrain. Le Roi Magni Barbe-de-Bronze leur a offert un refuge à Forgefer.",al={"pourquoi les gnomes sont à forgefer","gnomes vivant avec les nains"}}},fp="13,256,22.294.0,19.259.0,24.95.0,38.177.0,34.125.0,66.158.0,65.158.0,45.172.0"}
P.entries["quest:95042"] = {n="Seeking the Kor Gem",s="À Orneval, Ulric Frostveil voit dans votre quête d’une Kor Gem une tâche familière aux lanceurs de sorts de l’Alliance. Il vous indique les Profondeurs de Brassenoire, au nord, où les nagas utilisent encore ces gemmes.",h="À Orneval, Ulric Frostveil voit dans votre quête d’une Kor Gem une tâche familière aux lanceurs de sorts de...",kw={"orneval","profondeurs de brassenoire","réprouvés","kor gem","nagas","ulric frostveil"},sec={{t="Une gemme à Orneval",b="Ulric vous demande de lui rapporter une Kor Gem des ruines des Profondeurs de Brassenoire, au nord d’Orneval. Les nagas qui s’y trouvent utilisent encore ces gemmes. Elles peuvent imprégner de pouvoir les armes et les objets magiques, mais Ulric vous déconseille d’y aller seul."},{t="L’intérêt d’Ulric",b="Ulric Frostveil reconnaît la corruption de la gemme. Il affirme pouvoir dissiper le mal que les sorcières nagas y ont insufflé. Puis il vous demande si vous accepteriez de la lui vendre pour ses recherches universitaires."}},faq={{q="Qui est Ulric Frostveil ?",a="Ulric Frostveil est un Réprouvé d’Orneval qui vous demande de lui rapporter une Kor Gem.",al={"ulric frostveil","qui est ulric","réprouvé d’orneval"}},{q="Où trouver une Kor Gem ?",a="Ulric vous indique les Profondeurs de Brassenoire, au nord, où les nagas utilisent encore des Kor Gems.",al={"emplacement de la kor gem","où trouver la gemme","gemme de brassenoire"}},{q="À quoi servent les Kor Gems ?",a="Les Kor Gems peuvent imprégner de pouvoir les armes et les objets magiques.",al={"utilité de la kor gem","magie de la gemme","à quoi sert la kor gem"}},{q="Pourquoi Ulric veut-il une Kor Gem ?",a="Ulric vous demande de lui rapporter une Kor Gem. Il dit qu’elle pourrait lui être utile pour ses recherches universitaires.",al={"ulric veut la gemme","pourquoi la gemme","gemme frostveil"}},{q="Qui utilise encore les Kor Gems ?",a="Les nagas des Profondeurs de Brassenoire utilisent encore les Kor Gems.",al={"gemmes des nagas","qui utilise les kor gems","nagas de brassenoire"}}},fp="19,177,18.215.0,16.190.1,23.79.0,27.76.0,27.52.0,30.89.0,24.49.0"}
P.entries["quest:95059"] = {n="Frazzlespark's Crate",s="Un gobelin a une livraison pour le chevalier-commandant Demar Brant au Donjon de Fort-Lointain. On vous demande de lui apporter Frazzlespark's Crate.",h="Un gobelin a une livraison pour le chevalier-commandant Demar Brant au Donjon de Fort-Lointain.",kw={"caisse","demar brant","donjon de fort-lointain","frazzlespark","frazzlespark's crate","livraison gobeline","commandant-chevalier"},sec={{t="Une livraison au donjon",b="Frazzlespark vous envoie vers le sud-ouest, au Donjon de Fort-Lointain, où le chevalier-commandant Demar Brant attend. La caisse lui est destinée, et le gobelin tient à employer son nom complet. Au donjon, Demar considère le gobelin comme un simple moyen d'arriver à ses fins, dans le cadre des affaires qui, selon lui, assurent la sécurité et la réussite de son peuple."}},faq={{q="Qui attend la caisse ?",a="Le commandant-chevalier Demar Brant attend Frazzlespark's Crate au Donjon de Fort-Lointain.",al={"qui veut la caisse","livraison demar brant"}},{q="Où dois-je apporter Frazzlespark's Crate ?",a="Apportez Frazzlespark's Crate au commandant-chevalier Demar Brant, au Donjon de Fort-Lointain, au sud-ouest de Frazzlespark.",al={"emplacement de la caisse","où se trouve farholde keep"}},{q="Pourquoi Demar veut-il qu'on utilise son nom complet ?",a="Frazzlespark remarque que Demar lui demande toujours d'utiliser son nom complet, mais n'en donne pas la raison.",al={"nom complet de demar","pourquoi commandant-chevalier"}},{q="Pourquoi Frazzlespark parle-t-il d'une livraison spéciale ?",a="Frazzlespark parle d'une livraison spéciale et dit que Demar Brant l'attend au Donjon de Fort-Lointain.",al={"livraison de la caisse","qu'a de spécial la caisse"}},{q="Pourquoi cette livraison est-elle importante ?",a="Demar Brant affirme que certaines affaires doivent être menées pour assurer la sécurité et la réussite de son peuple, et considère le gobelin comme un simple moyen d'arriver à ses fins.",al={"pourquoi livrer la caisse","sécurité des gobelins"}}},fp="20,126,19.303.0,29.82.0,37.102.0,39.95.0,49.98.0,30.152.0"}
P.entries["quest:95065"] = {n="Fishin' Time",s="Au port de Hurlevent, Gilbert Gray reste près de sa ligne quand les poissons mordent. Ses provisions s’épuisent, alors il demande aux passants de lui rapporter des nightcrawlers et un shiny bauble dans une boutique le long des Canals de la ville.",h="Au port de Hurlevent, Gilbert Gray reste près de sa ligne quand les poissons mordent.",kw={"canals","catherine leland","fishin time","gilbert gray","nightcrawlers","shiny bauble","port de hurlevent","quartier commerçant"},ang={["faction:Alliance"]="En tant que citoyen de l’Alliance, aider Gilbert Gray à répondre à un besoin quotidien soutient la vie et le moral de toute Hurlevent.",["race:Human"]="En tant qu’humain qui a élu domicile à Hurlevent, aider un aîné à profiter d’un après-midi paisible de pêche lui offre une pause dans les affaires politiques du royaume."},sec={{t="Une journée au bord de l’eau",b="Gilbert Gray regarde son bouchon danser sur l’eau. Ce pêcheur âgé ne quittera pas son perchoir favori tant que les poissons mordent. Ses provisions sont épuisées et il a besoin d’aide pour rester près de sa ligne au lieu de retourner en ville."},{t="Des provisions le long des Canals",b="Catherine Leland tient une boutique d’articles de pêche près des Canals de pierre de Hurlevent, juste à l’ouest du Quartier commerçant. Les pêcheurs de toute la ville viennent y chercher des leurres et des appâts. Sa boutique peut fournir à Gilbert Gray ce dont il a besoin pour continuer à pêcher."}},faq={{q="Qui est Gilbert Gray ?",a="Gilbert Gray est un pêcheur âgé au port de Hurlevent. Il passe ses journées à lancer sa ligne en mer et demande aux passants de lui rapporter des appâts et des leurres quand ses provisions s’épuisent.",al={"gilbert gray","le vieux gray","qui donne cette quête"}},{q="Qui est Catherine Leland ?",a="Catherine Leland tient une boutique d’articles de pêche le long des Canals de la ville, juste à l’ouest du Quartier commerçant. Elle vend du matériel de pêche et des appâts aux pêcheurs de Hurlevent.",al={"catherine leland","vendeur de pêche à hurlevent","leland hurlevent"}},{q="Où Gilbert Gray pêche-t-il ?",a="Gilbert Gray pêche au port de Hurlevent, où il apprécie la vue dégagée sur la mer.",al={"emplacement de gilbert gray","où se trouve gilbert gray","pêcheur du port"}},{q="De quelles provisions Gilbert Gray a-t-il besoin ?",a="Gilbert Gray a besoin de nightcrawlers comme appât et d’un shiny bauble comme leurre. Catherine Leland vend les deux le long des Canals.",al={"objets de quête fishin time","quel appât gray veut-il"}},{q="Pourquoi Gilbert Gray ne va-t-il pas chercher les provisions lui-même ?",a="Les poissons mordent, et Gilbert Gray ne veut pas quitter son poste ni manquer une belle prise en retournant en ville chercher des provisions.",al={"pourquoi gray ne peut-il pas acheter d’appâts","pourquoi gray a-t-il besoin d’aide"}},{q="Où se trouve la boutique de Catherine Leland le long des Canals ?",a="La boutique de Catherine Leland se trouve le long des Canals, juste à l’ouest du Quartier commerçant, près des allées de pierre qui surplombent les voies d’eau de la ville.",al={"emplacement de catherine leland","où se trouve la boutique de leland","canals du quartier commerçant"}}},fp="12,206,18.235.0,25.223.0,20.167.0,24.160.0,29.82.0,37.118.0,52.132.0,58.129.0"}
P.entries["quest:951"] = {n="Les Reliques de Mathystra",s="Sur la côte nord-est de Sombrivage, les Reliques de Mathystra pourraient révéler comment le Marteau du crépuscule détourne l’ancienne magie elfique. Onu, un Ancien du Savoir du Bosquet des Anciens, les cherche pour découvrir les intentions de la secte.",h="Sur la côte nord-est de Sombrivage, les Reliques de Mathystra pourraient révéler comment le Marteau du...",kw={"sombrivage","bosquet des anciens","le glaive du maître","mathystra","onu","reliques","ruines de mathystra","marteau du crépuscule"},ang={["class:Druid"]="En tant que druide, vous aidez Onu, l’un des plus grands anciens gardiens de la nature. Vous contribuez à préserver l’histoire ancienne de Sombrivage des sectateurs malveillants.",["faction:Alliance"]="En tant que membre de l’Alliance, vous contribuez à protéger le nord de Kalimdor des forces maléfiques enfouies sous terre, en empêchant le Marteau du crépuscule d’armer une ancienne magie.",["race:NightElf"]="En tant qu’elfe de la nuit, vous voyez les reliques de la gloire de votre peuple avant la Fracture exhumées de la terre. Leur chute est un rappel funèbre, et l’usage que fait le Marteau du crépuscule des arts puissants de vos ancêtres est un avertissement alarmant."},sec={{t="Une découverte troublante",b="Après que vous avez récupéré un parchemin souillé auprès de sectateurs du Marteau du crépuscule près du Glaive du Maître, Onu en a déchiffré le sens. Le texte ne venait pas de la secte. C’était un fragment maudit d’une ancienne écriture des elfes de la nuit, souillé par le Marteau du crépuscule. Les zélotes utilisent une magie elfique oubliée pour éveiller ou invoquer leurs anciens maîtres dans le monde des mortels."},{t="Le bastion déchu",b="Onu vous envoie aux Ruines de Mathystra, sur la côte nord-est de Sombrivage. Avant la Fracture, Mathystra était un bastion resplendissant de la civilisation des Bien-nés. La cité est tombée en ruines, envahie par les mauvaises herbes et les nagas, mais ses anciens enchantements perdurent dans des urnes brisées et des reliques dispersées parmi les fondations de pierre."},{t="Déchiffrer les desseins",b="Vous rassemblez les reliques préservées parmi les décombres herbeux afin que les défenseurs de Sombrivage découvrent quels arts la secte compte employer. Onu étudie la magie qui subsiste dans chaque fragment. Il doit percer les plans de la secte avant que le Marteau du crépuscule ne détourne l’ancienne sorcellerie kaldorei pour libérer ses maîtres souterrains."}},faq={{q="Que sont les Reliques de Mathystra ?",a="Les Reliques de Mathystra sont des fragments de poteries enchantées, d’urnes et d’artefacts provenant des ruines. Ils ont été façonnés à l’apogée de l’ancienne civilisation des elfes de la nuit, avant la Grande Fracture, et conservent encore une magie résiduelle.",al={"que sont les reliques","histoire des reliques de mathystra","reliques elfiques de mathystra"}},{q="Pourquoi Onu veut-il ces reliques ?",a="Onu veut ces reliques car le Marteau du crépuscule utilise une ancienne magie elfique pour ramener ses maîtres maléfiques dans le monde. En étudiant des fragments intacts de Mathystra, il espère découvrir comment la secte compte manier ce pouvoir.",al={"pourquoi onu veut des reliques","but des reliques de mathystra"}},{q="Où se trouvaient les Ruines de Mathystra ?",a="Les Ruines de Mathystra se trouvent sur la côte nord-est de Sombrivage, au nord d’Ameth'Aran et de Bashal'Aran, juste après la Tour d'Althalaxx.",al={"où se trouve mathystra","emplacement de mathystra"}},{q="Qui le Marteau du crépuscule cherche-t-il à ramener ?",a="Le Marteau du crépuscule cherche à ramener ses anciens maîtres maléfiques. Onu vous avertit que la secte utilise une ancienne magie elfique pour les faire revenir en Azeroth.",al={"qui sont les maîtres du marteau du crépuscule","maîtres de la secte à sombrivage"}},{q="Qu’était Mathystra avant de devenir une ruine ?",a="Mathystra était autrefois une grande cité et un bastion des elfes de la nuit, il y a des milliers d’années. La Grande Fracture l’a laissée en ruines, puis la nature sauvage, les fantômes et de viles créatures du littoral comme les nagas l’ont envahie.",al={"histoire de mathystra","qu’était mathystra"}},{q="Qui donne la quête « Les Reliques de Mathystra » ?",a="Onu vous confie la quête des Reliques de Mathystra. C’est un ancien tréant enraciné dans le Bosquet des Anciens, dans le centre-sud de Sombrivage, après votre enquête au Glaive du Maître.",al={"qui donne les reliques de mathystra","donneur de quête des reliques de mathystra"}}},fp="16,215,22.360.1,18.296.0,21.293.1,30.220.0,31.222.0,42.138.0,50.154.0,43.204.0,39.177.0"}
P.entries["quest:95111"] = {n="An Underrated Talent",s="Dans la Forêt des Pins-Argentés, Trevan Rol donne à Ott l’occasion de forger une lame selon vos exigences. Les armes simples d’Ott ont été louées par les forgerons de Fossoyeuse.",h="Dans la Forêt des Pins-Argentés, Trevan Rol donne à Ott l’occasion de forger une lame selon vos exigences.",kw={"commande","lame sur mesure","ott","forgeron","moulin-de-tarren","fossoyeuse","forgeron d’armes"},sec={{t="Une chance de forger",b="Trevan Rol vous demande d’apporter des matériaux à Ott, au Moulin-de-Tarren, et de lui proposer une commande. Ott vend des lames simples aux voyageurs. Trevan en a acheté une, puis l’a apportée à Fossoyeuse pour l’entretien. Là-bas, les forgerons locaux ont loué sa qualité et l’ont prise pour l’œuvre d’un maître renommé. Ott a maintenant l’occasion de forger une lame selon vos exigences."},{t="La réponse d’Ott",b="Ott dit que personne ne lui a jamais demandé de fabriquer une arme sur mesure. Il forge habituellement des armes modestes et fonctionnelles dans son propre style, sans rechercher la gloire. Il accepte tout de même d’essayer. Il se demande pourquoi vous l’avez choisi, alors que les forgerons de Fossoyeuse acceptent aussi les commandes sur mesure."}},faq={{q="Qui est Ott ?",a="Ott est un forgeron d’armes au Moulin-de-Tarren qui vend des lames simples aux voyageurs.",al={"forgeron ott","qui est ott","forgeron moulin-de-tarren"}},{q="Pourquoi le forgeron de Fossoyeuse veut-il que je trouve Ott ?",a="Le forgeron a acheté l’une des lames d’Ott et a été surpris lorsque les forgerons de Fossoyeuse en ont loué la qualité. Il veut donner à Ott l’occasion de réaliser quelque chose de spécial.",al={"pourquoi ott","commande au forgeron de fossoyeuse","commande pour ott"}},{q="Qu’est-ce que j’apporte à Ott ?",a="Vous apportez des matériaux à Ott, au Moulin-de-Tarren, et lui proposez une commande pour forger votre lame.",al={"matériaux pour ott","qu’est-ce que j’apporte","matériaux d’ott"}},{q="Ott fabrique-t-il des armes sur mesure ?",a="Ott dit que personne ne lui a jamais demandé de fabriquer une arme sur mesure, mais il accepte d’essayer.",al={"lame sur mesure d’ott","ott peut-il forger pour moi","commandes d’ott"}},{q="Pourquoi Ott demande-t-il pourquoi je l’ai choisi ?",a="Ott dit que les forgerons de Fossoyeuse acceptent les commandes sur mesure et se demande pourquoi vous vous êtes adressé à lui.",al={"pourquoi choisir ott","ott se demande pourquoi","pourquoi pas un forgeron de fossoyeuse"}}},fp="20,155,16.348.0,12.255.1,11.73.0,49.163.0,26.97.0,29.87.0,33.90.0"}
P.entries["quest:95118"] = {n="Saltwater Savages",s="Un gardien du port vous demande de réduire le nombre de Murlocs sur la côte d’Eastwind. Les marins, les pêcheurs et ses enfants se plaignent sans cesse de cette nuisance.",h="Un gardien du port vous demande de réduire le nombre de Murlocs sur la côte d’Eastwind.",kw={"côte d’eastwind","pêcheurs","murloc","oracle murloc","guerrier murloc","gardien du port","marins","sauvages des mers salées"},sec={{t="Plaintes au port",b="Le gardien du port a entendu assez de plaintes de la part des marins, des pêcheurs et même de ses enfants. Les Murlocs le dérangent, mais il doit tout de même gérer le port. Il vous demande d’en tuer quelques-uns sur la côte d’Eastwind, espérant retrouver un peu de calme au milieu de tout ce vacarme."}},faq={{q="Pourquoi le gardien du port veut-il faire tuer les Murlocs ?",a="Les marins, les pêcheurs et les enfants du gardien du port n’arrêtent pas de se plaindre à leur sujet. Il les considère comme une nuisance et veut retrouver un peu de calme pendant qu’il gère le port.",al={"pourquoi tuer les murlocs","murlocs qui dérangent le port"}},{q="De quels Murlocs parle-t-il ?",a="Il vous demande de tuer des oracles murlocs et des guerriers murlocs sur la côte d’Eastwind.",al={"types de murlocs","oracles et guerriers"}},{q="Où se trouvent les Murlocs ?",a="Le gardien du port vous indique la côte d’Eastwind.",al={"murlocs de la côte d’eastwind","où sont les murlocs"}},{q="Tuer ces Murlocs résoudra-t-il le problème ?",a="Le gardien du port s’attend à ce que d’autres Murlocs reviennent bientôt, mais il espère que leur mort lui apportera un peu de calme d’ici là.",al={"retour des murlocs","est-ce terminé"}}},fp="17,152,22.244.0,49.149.0,33.76.0,22.45.0,45.118.0"}
P.entries["quest:95120"] = {n="WANTED: Old Rot-Chum",s="Le maître de quai Whizzbuzz offre une récompense contre la preuve de la mort d’Old Rot-Chum. Ce murloc agressif s’en prend aux petites embarcations dans les eaux du sud.",h="Le maître de quai Whizzbuzz offre une récompense contre la preuve de la mort d’Old Rot-Chum.",kw={"murloc","îles des murlocs","old rot-chum","chaloupes","petites embarcations","eaux du sud","maître de quai whizzbuzz"},sec={{t="Une menace en mer",b="Les marins et les nageurs des eaux du sud sont attaqués à bord de chaloupes et d’autres petites embarcations. Les pêcheurs locaux appellent Old Rot-Chum le murloc agressif qui en est responsable. Le maître de quai Whizzbuzz offre une récompense contre la preuve que la créature est morte, et vous demande de la lui apporter."}},faq={{q="Qui est Old Rot-Chum ?",a="Old Rot-Chum est le surnom que les pêcheurs locaux donnent à un murloc particulièrement agressif.",al={"old rot-chum","rot-chum","qui est rot-chum"}},{q="Où a-t-on aperçu Old Rot-Chum ?",a="Old Rot-Chum a été aperçu dans les eaux du sud, près d’îles infestées de murlocs.",al={"où est old rot-chum","emplacement de rot-chum","où est le murloc"}},{q="Qu’est-ce qu’Old Rot-Chum attaque ?",a="Old Rot-Chum s’en prend aux chaloupes et aux autres petites embarcations.",al={"qu’attaque rot-chum","attaques de bateaux","murloc et chaloupes"}},{q="Qui offre la récompense ?",a="Le maître de quai Whizzbuzz offre une récompense contre la preuve de la mort d’Old Rot-Chum.",al={"qui veut une preuve de rot-chum","récompense du maître de quai","qui paie pour old rot-chum"}},{q="Quelle preuve Whizzbuzz demande-t-il ?",a="Le maître de quai Whizzbuzz vous demande de lui apporter la preuve de la mort d’Old Rot-Chum.",al={"quelle preuve pour rot-chum","apporter une preuve","proof of demise"}}},fp="20,154,15.274.0,20.82.0,33.90.0,37.65.0,22.87.0,34.73.0"}
P.entries["quest:95121"] = {n="A Taste of the Sea",s="Fimbo Greasemitz veut des fruits de mer frais pour préparer un nouveau ragoût dans son café au bord de l’eau. Vous rassemblez des ingrédients locaux pour renouveler le menu.",h="Fimbo Greasemitz veut des fruits de mer frais pour préparer un nouveau ragoût dans son café au bord de l’eau.",kw={"plage","café","fimbo greasemitz","poisson","yeux de murloc","sanglier rôti","viande de sand crawler","ragoût de fruits de mer"},ang={["profession:Cooking"]="En tant que cuisinier, vous voyez que Fimbo cherche des ingrédients frais et locaux pour préparer un ragoût de fruits de mer."},sec={{t="Un nouveau plat",b="Fimbo Greasemitz tient un café au bord de l’eau, où le menu propose chaque jour du sanglier rôti et du poisson. Il veut essayer un ragoût de fruits de mer et vous demande de lui apporter des yeux de murloc et de la viande de Sand Crawler des plages voisines."}},faq={{q="Qui est Fimbo Greasemitz ?",a="Fimbo Greasemitz tient un café au bord de l’eau et veut ajouter un ragoût de fruits de mer à son menu.",al={"qui est fimbo","café de fimbo","fimbo greasemitz"}},{q="De quels ingrédients Fimbo a-t-il besoin ?",a="Fimbo demande des yeux de murloc et de la viande de Sand Crawler pour son ragoût de fruits de mer.",al={"ingrédients du ragoût","quelle viande","yeux de murloc"}},{q="Pourquoi Fimbo veut-il des fruits de mer ?",a="Il veut une nouvelle recette de ragoût de fruits de mer pour varier le menu quotidien du café, composé de sanglier rôti et de poisson.",al={"pourquoi un ragoût","nouveau menu","plats du café"}},{q="Où trouver les ingrédients ?",a="Fimbo dit que les yeux de murloc et la viande de Sand Crawler se trouvent le long des plages voisines.",al={"où trouver la viande","où trouver les ingrédients","trouvailles de la plage"}}},fp="18,129,10.206.0,24.84.0,33.70.0,28.94.0,35.87.0"}
P.entries["quest:95125"] = {n="Chef-d’œuvre d’Ott",s="Ott est prêt à forger une lame pour vous à partir de matériaux de qualité. Vous pouvez le regarder travailler.",h="Ott est prêt à forger une lame pour vous à partir de matériaux de qualité.",kw={"forgeron","lame","forge","chef-d’œuvre","matériaux","ott"},sec={{t="À la forge",b="Ott accorde de la valeur aux matériaux de qualité et espère que son travail sera à la hauteur de vos attentes. Il forge une lame pour vous, puis vous la propose pour vos voyages."}},faq={{q="Qui forge ma lame ?",a="Ott forge votre lame à partir des matériaux de qualité que vous lui avez fournis.",al={"qui la forge","lame d’ott","ott forgeron"}},{q="Puis-je regarder Ott la forger ?",a="Ott vous demande de reculer tandis qu’il commence à forger. Il vous invite à le regarder travailler.",al={"regarder ott forger","voir la lame fabriquée","processus de forge"}},{q="Que dit Ott quand la lame est terminée ?",a="Ott qualifie la lame de son plus beau chef-d’œuvre et espère qu’elle vous sera utile au cours de vos voyages.",al={"fin du travail d’ott","que dit ott","lame terminée"}}},fp="16,85,12.137.0,23.63.0,25.81.0,45.81.0"}
P.entries["quest:95126"] = {n="The Moonsilver Blade",s="Dans la Forêt des Pins-Argentés, Trevan Rol attend la lame qui achèvera son œuvre avant qu’il affronte une bête.",h="Dans la Forêt des Pins-Argentés, Trevan Rol attend la lame qui achèvera son œuvre avant qu’il affronte une...",kw={"bête","lumina","lame de sélénargent","ott","chef-d’œuvre d’ott","forêt des pins-argentés","trevan rol"},sec={{t="La lame",b="Ott vous remercie de lui avoir donné l’occasion d’aider et vous demande de transmettre sa gratitude à Trevan. Vous rapportez le chef-d’œuvre d’Ott à Trevan Rol, dans la Forêt des Pins-Argentés."},{t="L’approbation de Trevan",b="Trevan Rol examine la lame et approuve le travail d’Ott. Seule la bête reste à affronter. Quand vous serez prêt, il vous conseille de parler à Lumina."}},faq={{q="Qui a fabriqué le chef-d’œuvre d’Ott ?",a="Ott a fabriqué le chef-d’œuvre d’Ott et vous l’a confié pour le remettre à Trevan Rol.",al={"qui a fabriqué la lame","lame d’ott","fabricant du chef-d’œuvre"}},{q="Qui est Trevan Rol ?",a="Trevan Rol reçoit et examine le chef-d’œuvre d’Ott dans la Forêt des Pins-Argentés.",al={"qui est trevan","lame de trevan","trevan rol"}},{q="Où dois-je apporter la lame ?",a="Apportez le chef-d’œuvre d’Ott à Trevan Rol, dans la Forêt des Pins-Argentés.",al={"où apporter la lame","où apporter le chef-d’œuvre d’ott","destination de la lame"}},{q="Que pense Trevan de la lame ?",a="Trevan Rol examine la lame et dit qu’elle fera parfaitement l’affaire.",al={"trevan aime la lame","la lame d’ott est-elle bonne","approbation de trevan"}},{q="À qui dois-je parler après Trevan ?",a="Quand vous serez prêt, Trevan Rol vous conseille de parler à Lumina.",al={"quelle est la suite","qui est lumina","parler à lumina"}}},fp="20,102,9.152.0,17.138.1,26.61.0,18.71.0,27.58.0,36.57.0,37.64.0"}
P.entries["quest:95140"] = {n="Old Fire-Eye",s="Lumina Windsinger vous envoie traquer Old Fire-Eye dans la Forêt des Pins-Argentés avec la Lame de sélénargent. Les Sculpte-vents attendent sa mort, et Lumina espère que la lame vous guidera bien.",h="Lumina Windsinger vous envoie traquer Old Fire-Eye dans la Forêt des Pins-Argentés avec la Lame de...",kw={"banon","gilnéas","lumina windsinger","lame de sélénargent","old fire-eye","forêt des pins-argentés","sculpte-vents"},sec={{t="Le dessein d’une lame",b="Les Sculpte-vents vous ont remis la Lame de sélénargent. Les habitants disent qu’Old Fire-Eye chasse dans une vaste zone au sud d’ici, généralement près des portes de Gilnéas. Lumina vous demande de le trouver et d’utiliser la lame pour l’achever. La gratitude des Sculpte-vents dépend de sa mort."},{t="Après la chasse",b="À votre retour, Lumina vous remercie et dit que Banon peut reposer en paix. Elle dépose ensuite une petite part de la magie de son peuple sur la lame maculée de sang, dans l’espoir que les vents la guideront bien."}},faq={{q="Qui me demande de traquer Old Fire-Eye ?",a="Lumina Windsinger vous demande de traquer Old Fire-Eye avec la Lame de sélénargent.",al={"qui m’a envoyé","mission de lumina","windsinger"}},{q="Où trouver Old Fire-Eye ?",a="Les habitants disent qu’Old Fire-Eye chasse dans une vaste zone au sud de Lumina, généralement près des portes de Gilnéas.",al={"lieu où se trouve fire-eye","où est old fire-eye","portes de gilnéas"}},{q="Que dois-je utiliser contre Old Fire-Eye ?",a="Lumina vous demande d’utiliser la Lame de sélénargent pour achever Old Fire-Eye.",al={"lame contre fire-eye","arme de sélénargent","quelle arme"}},{q="Pourquoi Lumina veut-elle la mort d’Old Fire-Eye ?",a="Lumina dit que les Sculpte-vents lui seront reconnaissants quand Old Fire-Eye sera mort.",al={"pourquoi tuer fire-eye","pourquoi le traquer","raison pour fire-eye"}},{q="Qui est Banon ?",a="Lumina dit que Banon pourra reposer en paix une fois Old Fire-Eye tué.",al={"qui est banon","banon repose en paix"}},{q="Que fait Lumina avec la lame ?",a="Lumina dépose une petite part de la magie de son peuple sur la Lame de sélénargent maculée de sang.",al={"magie de la lame","lumina enchante la lame","magie des vents"}}},fp="12,175,17.261.0,14.186.1,38.74.0,30.100.0,39.64.0,40.71.0,13.64.0,35.89.0"}
P.entries["quest:95141"] = {n="Report to Rog'mar",s="Un Orc vous envoie à Rog’mar, un avant-poste des Rives Claires en proie aux combats. Présentez-vous à Krom'rosh, dont l’expérience a aidé l’avant-poste à résister à des attaques répétées.",h="Un Orc vous envoie à Rog’mar, un avant-poste des Rives Claires en proie aux combats.",kw={"attaques","côte orientale","krom'rosh","avant-poste","rives claires","rog’mar","pierrêche"},sec={{t="Un avant-poste résiste",b="Les Rives Claires s’étendent au nord-est de Pierrêche, le long de la côte orientale. Beaucoup ont tenté de s’emparer de ces terres, mais peu y sont parvenus. Rog’mar est un petit avant-poste qui a survécu à d’innombrables attaques. On vous y envoie vous présenter à Krom'rosh, un allié de longue date dont l’expérience du combat a aidé l’avant-poste à tenir bon."}},faq={{q="Où se trouve Rog’mar ?",a="Rog’mar se trouve dans les Rives Claires, au nord-est de Pierrêche, le long de la côte orientale.",al={"emplacement de rog’mar","où se trouve rogmar","avant-poste de rog’mar"}},{q="À qui dois-je me présenter ?",a="Vous devez vous présenter à Krom'rosh à l’avant-poste de Rog’mar.",al={"à qui se présenter","qui est krom'rosh","kromrosh"}},{q="Qu’est-ce que Rog’mar ?",a="Rog’mar est un petit avant-poste des Rives Claires qui a résisté à d’innombrables attaques.",al={"qu’est-ce que rogmar","avant-poste des rives claires","petit avant-poste"}},{q="Pourquoi Krom'rosh est-il à Rog’mar ?",a="L’expérience de Krom'rosh dans la lutte contre les ennemis a aidé l’avant-poste à tenir bon.",al={"pourquoi kromrosh est là","rôle de krom'rosh","qui dirige rogmar"}},{q="À quoi ressemblent les Rives Claires ?",a="Les Rives Claires sont des terres en proie aux combats, le long de la côte orientale, au nord-est de Pierrêche.",al={"rives claires","à quoi ressemblent les rives claires","terres en proie aux combats"}}},fp="17,157,18.302.0,17.78.0,22.54.0,16.81.0,28.70.0,38.84.0"}
P.entries["quest:95143"] = {n="Finding Tan'jani",s="Un voyageur vous demande de retrouver son frère Tan'jani. Les messages le situent au sud de Loch Modan, le plus récent indiquant Rog’mar, dans les Rives Claires.",h="Un voyageur vous demande de retrouver son frère Tan'jani.",kw={"lettre tachée de sang","loch modan","frère disparu","rives claires","rog’mar","tan jani","tan'jani"},sec={{t="Un frère disparu",b="Le frère d’un voyageur, Tan'jani, est parti à la recherche de quelque chose d’inconnu. Un message le situe quelque part au sud de Loch Modan. Une lettre tachée de sang mentionne les Rives Claires et Rog’mar, plus au sud, et le voyageur vous demande de l’y retrouver."}},faq={{q="Qui est Tan'jani ?",a="Tan'jani est le frère du voyageur qui vous demande de le retrouver.",al={"tan'jani","tan jani","frère disparu"}},{q="Où Tan'jani a-t-il été mentionné pour la dernière fois ?",a="Une lettre tachée de sang mentionne les Rives Claires et Rog’mar, plus au sud que Loch Modan.",al={"où est tan'jani","lieu où se trouve tan'jani","rog’mar"}},{q="Que cherchait Tan'jani ?",a="Tan'jani était toujours à la recherche de quelque chose, mais son frère ignore quoi.",al={"ce qu'il cherchait","recherches de tan'jani","pourquoi est-il parti"}},{q="Que disent les messages ?",a="Un voyageur a indiqué avoir rencontré Tan'jani quelque part au sud de Loch Modan. Une lettre tachée de sang mentionne les Rives Claires et Rog’mar, mais la majeure partie est illisible.",al={"messages de tan'jani","lettre tachée de sang","qu'est-il arrivé à la lettre"}}},fp="16,147,17.242.0,16.63.0,34.86.0,32.80.0,25.156.0"}
